CREATE OR REPLACE FUNCTION ISOWeekDate(WEEK INTEGER, YEAR INTEGER) RETURN DATE DETERMINISTIC IS
    res DATE;
BEGIN
    IF WEEK > 53 OR WEEK < 1 THEN
        RAISE VALUE_ERROR;      
    END IF;
    res := NEXT_DAY(TO_DATE( YEAR || '0104', 'YYYYMMDD' ) - 7, 'MONDAY') + ( WEEK - 1 ) * 7;
    IF TO_CHAR(res, 'fmIYYY') = YEAR THEN
        RETURN res;
    ELSE
        RAISE VALUE_ERROR;
    END IF;
END ISOWeekDate;
/

-- ============================================================================
-- 8. VUES (ordre de dependance)
-- 1309 vues. Une vue qui en utilise une autre vient apres elle (creation en mode FORCE).
-- ============================================================================
-- [1/1309] ACTE_LIB
CREATE OR REPLACE FORCE VIEW "ACTE_LIB" ("ID","DATY","IDPRODUIT","LIBELLEPRODUIT","QTE","PU","MONTANT","LIBELLE","IDCLIENT","IDCLIENTLIB","IDRESERVATION","ETAT","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT","IDCHAMBRE","CHAMBRE") AS
SELECT
    a.ID,
    a.DATY,
    a.IDPRODUIT,
    ai.LIBELLE AS libelleproduit,
    a.QTE,
    a.PU,
    a.PU * a.QTE AS montant,
    a.LIBELLE,
    a.IDCLIENT,
    c.NOM AS idclientlib,
    a.IDRESERVATION,
    a.ETAT,
    CASE
        WHEN a.ETAT = 0
            THEN 'ANNULEE'
        WHEN a.ETAT = 1
            THEN 'CREE'
        WHEN a.ETAT = 11
            THEN 'VISEE'
        END AS ETATLIB,
    ai.COMPTE_VENTE,
    ai.COMPTE_ACHAT,
    a.IDPRODUIT as IDCHAMBRE,
    ai.LIBELLE as chambre
FROM ACTE a
         LEFT JOIN AS_INGREDIENTS ai  ON ai.id = a.IDPRODUIT
         LEFT JOIN CLIENT c ON c.id = a.IDCLIENT
;
-- [2/1309] ACTE_LIB_A
CREATE OR REPLACE FORCE VIEW "ACTE_LIB_A" ("ID","DATY","IDPRODUIT","LIBELLEPRODUIT","QTE","PU","MONTANT","LIBELLE","IDCLIENT","IDCLIENTLIB","IDRESERVATION","ETAT","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT") AS
SELECT 
al."ID",al."DATY",al."IDPRODUIT",al."LIBELLEPRODUIT",al."QTE",al."PU",al."MONTANT",al."LIBELLE",al."IDCLIENT",al."IDCLIENTLIB",al."IDRESERVATION",al."ETAT",al."ETATLIB",al."COMPTE_VENTE",al."COMPTE_ACHAT"
FROM ACTE_LIB al 
WHERE al.etat = 0
;
-- [3/1309] ACTE_LIB_C
CREATE OR REPLACE FORCE VIEW "ACTE_LIB_C" ("ID","DATY","IDPRODUIT","LIBELLEPRODUIT","QTE","PU","MONTANT","LIBELLE","IDCLIENT","IDCLIENTLIB","IDRESERVATION","ETAT","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT") AS
SELECT 
al."ID",al."DATY",al."IDPRODUIT",al."LIBELLEPRODUIT",al."QTE",al."PU",al."MONTANT",al."LIBELLE",al."IDCLIENT",al."IDCLIENTLIB",al."IDRESERVATION",al."ETAT",al."ETATLIB",al."COMPTE_VENTE",al."COMPTE_ACHAT"
FROM ACTE_LIB al 
WHERE al.etat = 1
;
-- [4/1309] ACTE_LIB_FACT
CREATE OR REPLACE FORCE VIEW "ACTE_LIB_FACT" ("ID","DATY","IDPRODUIT","LIBELLEPRODUIT","QTE","PU","MONTANT","LIBELLE","IDCLIENT","IDCLIENTLIB","IDRESERVATION","ETAT","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT") AS
SELECT
al."ID",al."DATY",al."IDPRODUIT",al."LIBELLEPRODUIT",al."QTE",al."PU",al."MONTANT",al."LIBELLE",al."IDCLIENT",al."IDCLIENTLIB",al."IDRESERVATION",al."ETAT",al."ETATLIB",al."COMPTE_VENTE",al."COMPTE_ACHAT"
FROM ACTE_LIB al 
WHERE EXISTS ( SELECT f.idacte FROM FACTURECLIENTDETAILS f WHERE f.idacte = al.id )
;
-- [5/1309] ACTE_LIB_NONFACT
CREATE OR REPLACE FORCE VIEW "ACTE_LIB_NONFACT" ("ID","DATY","IDPRODUIT","LIBELLEPRODUIT","QTE","PU","MONTANT","LIBELLE","IDCLIENT","IDCLIENTLIB","IDRESERVATION","ETAT","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT") AS
SELECT
al."ID",al."DATY",al."IDPRODUIT",al."LIBELLEPRODUIT",al."QTE",al."PU",al."MONTANT",al."LIBELLE",al."IDCLIENT",al."IDCLIENTLIB",al."IDRESERVATION",al."ETAT",al."ETATLIB",al."COMPTE_VENTE",al."COMPTE_ACHAT"
FROM ACTE_LIB al 
WHERE NOT EXISTS ( SELECT f.idacte FROM FACTURECLIENTDETAILS f WHERE f.idacte = al.id )
;
-- [6/1309] ACTE_LIB_V
CREATE OR REPLACE FORCE VIEW "ACTE_LIB_V" ("ID","DATY","IDPRODUIT","LIBELLEPRODUIT","QTE","PU","MONTANT","LIBELLE","IDCLIENT","IDCLIENTLIB","IDRESERVATION","ETAT","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT") AS
SELECT 
al."ID",al."DATY",al."IDPRODUIT",al."LIBELLEPRODUIT",al."QTE",al."PU",al."MONTANT",al."LIBELLE",al."IDCLIENT",al."IDCLIENTLIB",al."IDRESERVATION",al."ETAT",al."ETATLIB",al."COMPTE_VENTE",al."COMPTE_ACHAT"
FROM ACTE_LIB al 
WHERE al.etat = 11
;
-- [7/1309] ACTION_FORMATION_DETAIL_LIB
CREATE OR REPLACE FORCE VIEW "ACTION_FORMATION_DETAIL_LIB" ("ID","IDACTIONFORMATION","IDTYPECOUT","COUT","IDDEVISE","IDTYPECOUTLIB","IDDEVISELIB") AS
SELECT
    afd.ID,afd.IDACTIONFORMATION,afd.IDTYPECOUT,afd.COUT,afd.IDDEVISE,
    tcf.VAL AS idTypeCoutLib,
    dev.VAL AS idDeviseLib
FROM ACTION_FORMATION_DETAIL afd
         LEFT JOIN TYPE_COUT_FORMATION tcf
                   ON afd.IDTYPECOUT = tcf.ID
         LEFT JOIN DEVISE dev
                   ON afd.IDDEVISE = dev.ID
;
-- [8/1309] ACTION_FORMATION_LIB
CREATE OR REPLACE FORCE VIEW "ACTION_FORMATION_LIB" ("ID","IDPLANFORMATION","IDPLANFORMATIONLIB","IDTYPEFORMATION","IDTYPEFORMATIONLIB","IDCATEGORIEFORMATION","IDCATEGORIEFORMATIONLIB","FORMATEUR","REFERENCE","INTITULE","TYPEPRESTATAIRE","IDSEMESTRE","IDSEMESTRELIB","NBSESSIONPREVUS","DUREESTAGIAIREHEURE","NBOUVRIERSPREVUE","NBCADREPREVUE","OBJECTIF","ETAT","ETATLIB","ESTREALISEELIB") AS
SELECT
    af.ID,
    af.IDPLANFORMATION,
    pf.LIBELLE AS IDPLANFORMATIONLIB,
    af.IDTYPEFORMATION,
    tf.VAL AS IDTYPEFORMATIONLIB,
    af.IDCATEGORIEFORMATION,
    cf.VAL AS IDCATEGORIEFORMATIONLIB,
    af.FORMATEUR,
    af.REFERENCE,
    af.INTITULE,
    CASE
        WHEN af.TYPEPRESTATAIRE = '1' THEN 'INTERNE'
        WHEN af.TYPEPRESTATAIRE = '0' THEN 'EXTERNE'
        ELSE 'Inconnu'
        END AS TYPEPRESTATAIRE,
    af.IDSEMESTRE,
    s.VAL AS IDSEMESTRELIB,
    af.NBSESSIONPREVUS,
    af.DUREESTAGIAIREHEURE,
    af.NBOUVRIERSPREVUE,
    af.NBCADREPREVUE,
    af.OBJECTIF,
    af.ETAT,
    CASE
        WHEN af.ETAT = 1 THEN 'Cree'
        WHEN af.ETAT = 11 THEN 'Valide'
        WHEN af.ETAT = 0 THEN 'Annule'
        ELSE 'Inconnu'
        END AS ETATLIB,
     CASE
        WHEN af.estRealisee = '1' THEN 'OUI'
        WHEN af.estRealisee = '0' THEN 'NON'
        ELSE 'Inconnu'
        END AS estRealiseelib
FROM ACTION_FORMATION af

         LEFT JOIN PLAN_FORMATION_ANNUEL pf
                   ON af.IDPLANFORMATION = pf.ID

         LEFT JOIN TYPE_FORMATION tf
                   ON af.IDTYPEFORMATION = tf.ID

         LEFT JOIN CATEGORIE_FORMATION cf
                   ON af.IDCATEGORIEFORMATION = cf.ID

         LEFT JOIN SEMESTRE s
                   ON af.IDSEMESTRE = s.ID
;
-- [9/1309] ALIMENTPOUSSIN_LIBCOMPLET
CREATE OR REPLACE FORCE VIEW "ALIMENTPOUSSIN_LIBCOMPLET" ("ID","IDPRODUITS","IDINGREDIENTS","UNITE","QUANTITE","LIBINGREDIENTS","IDUNITE") AS
select rec."ID",rec."IDPRODUITS",rec."IDINGREDIENTS",rec."UNITE",rec."QUANTITE", ing.LIBELLE as libIngredients, u.VAL as idUnite
from AlimentPoussin rec
         left join as_ingredients ing on
    ing.id=rec.idingredients
left join as_UNITE u on u.id = rec.UNITE
;
-- [10/1309] AS_BC_FILLE_AVEC_PRIX
CREATE OR REPLACE FORCE VIEW "AS_BC_FILLE_AVEC_PRIX" ("ID","PRODUIT","NUMBL","QUANTITE","IDVENTEDETAIL","UNITE","IDBC_FILLE","PU","TVA","COMPTE_VENTE","COMPTE_ACHAT") AS
SELECT
    bl.ID,bl.PRODUIT,bl.NUMBL,CAST(bl.QUANTITE AS NUMBER(10,5)) AS  QUANTITE,bl.IDVENTEDETAIL,bl.UNITE,bl.IDBC_FILLE,
    CAST(ai.PV AS NUMBER(20, 5)) AS pu,
    CAST(ai.TVA AS NUMBER(20, 5)) AS tva,
    ai.COMPTE_VENTE,ai.COMPTE_ACHAT
FROM
    AS_BONDELIVRAISON_CLIENT_FILLE bl
LEFT JOIN AS_INGREDIENTS ai
    ON ai.ID = bl.PRODUIT
;
-- [11/1309] AS_BLCLIENTFILLEGRPBCFILLE
CREATE OR REPLACE FORCE VIEW "AS_BLCLIENTFILLEGRPBCFILLE" ("PRODUIT","IDBC_FILLE","QUANTITE") AS
select produit,IDBC_FILLE,sum(QUANTITE) as quantite from AS_BONDELIVRAISON_CLIENT_FILLE f
                                                             join AS_BONDELIVRAISON_CLIENT m on m.ID=f.NUMBL where m.ETAT>=11
group by produit, IDBC_FILLE
;
-- [12/1309] AS_BL_CLIENT_FILLE_VISE
CREATE OR REPLACE FORCE VIEW "AS_BL_CLIENT_FILLE_VISE" ("ID","PRODUIT","NUMBL","QUANTITE","IDVENTEDETAIL","UNITE","IDBC_FILLE") AS
select acf."ID",acf."PRODUIT",acf."NUMBL",acf."QUANTITE",acf."IDVENTEDETAIL",acf."UNITE",acf."IDBC_FILLE" from AS_BONDELIVRAISON_CLIENT_FILLE acf
left join AS_BONDELIVRAISON_CLIENT abc on abc.ID = NUMBL
where ETAT = 11
;
-- [13/1309] AS_BONCOMMANDE_FILLE_AVEC_PRIX
CREATE OR REPLACE FORCE VIEW "AS_BONCOMMANDE_FILLE_AVEC_PRIX" ("ID","PRODUIT","IDMERE","QUANTITE","UNITE","PU","TVA","COMPTE_VENTE","COMPTE_ACHAT") AS
SELECT
    bc.ID,
    bc.PRODUIT,
    bc.IDMERE,
    bc.QUANTITE,
    bc.UNITE,
    CAST(ai.PV AS NUMBER(20, 2)) AS pu,
    CAST(ai.TVA AS NUMBER(20, 2)) AS tva,
    ai.COMPTE_VENTE,ai.COMPTE_ACHAT
FROM
    BONDECOMMANDE_CLIENT_FILLE bC
LEFT JOIN AS_INGREDIENTS ai
    ON ai.ID = bl.PRODUIT
;
-- [14/1309] AS_BONDECOMMANDE_CPL
CREATE OR REPLACE FORCE VIEW "AS_BONDECOMMANDE_CPL" ("ID","PRODUIT","IDBC","QUANTITE","MONTANT","PU","TVA","UNITE","REMISE","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","FOURNISSEUR","REFERENCE","PRODUITLIB","UNITELIB","MODEPAIEMENTLIB","FOURNISSEURLIB","MONTANTTVA","MONTANTTTC","MONTANTHT","REMISEMONTANT","IDDEVISE","TAUXDECHANGE","MONTANTTTCAR") AS
select bcf.ID,bcf.PRODUIT,bcf.IDBC,bcf.QUANTITE,bcf.QUANTITE*bcf.PU AS montant,bcf.PU,bcf.TVA,bcf.UNITE,bcf.REMISE,
       ab.DATY,
       ab.ETAT,
       ab.REMARQUE,
       ab.DESIGNATION,
       ab.MODEPAIEMENT,
       ab.FOURNISSEUR,
       ab.REFERENCE,
       p.LIBELLE  as produitlib,
       u.VAL  as unitelib,
       mp.VAL as MODEPAIEMENTLIB,
       F.nom  AS FOURNISSEURLIB,
       CAST (((bcf.quantite * bcf.pu)-((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) * (bcf.tva / 100) AS NUMBER(30, 2)) AS montanttva,
       CAST( (((((bcf.quantite * bcf.pu + (bcf.quantite * bcf.pu * (bcf.tva / 100)) - bcf.quantite * bcf.pu * (bcf.tva / 100))-(((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)))))+(((bcf.quantite * bcf.pu)-((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) * (bcf.tva / 100)))) AS NUMBER(30, 2)) AS montantttc,
       CAST (((bcf.quantite * bcf.pu + (bcf.quantite * bcf.pu * (bcf.tva / 100)) - bcf.quantite * bcf.pu * (bcf.tva / 100))) AS NUMBER(30, 2)) AS montantht,
       CAST(((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) AS NUMBER(30, 2)) AS remiseMontant,
       bcf.iddevise,
       CAST(bcf.TAUXDECHANGE AS NUMBER(30,2)) AS TAUXDECHANGE,
       CAST( (((((bcf.quantite * bcf.pu + (bcf.quantite * bcf.pu * (bcf.tva / 100)) - bcf.quantite * bcf.pu * (bcf.tva / 100))-(((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)))))+(((bcf.quantite * bcf.pu)-((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) * (bcf.tva / 100))))* bcf.TAUXDECHANGE AS NUMBER(30, 2)) AS MONTANTTTCAR
from AS_BONDECOMMANDE_FILLE bcf
         left outer join AS_BONDECOMMANDE AB on AB.ID = bcf.IDBC
         left join AS_INGREDIENTS P on bcf.PRODUIT = P.ID
         left join AS_UNITE u on bcf.UNITE = u.id
         left join MODEPAIEMENT mp on AB.MODEPAIEMENT = mp.id
         left join fournisseur F on AB.fournisseur = F.id
;
-- [15/1309] AS_BONDECOMMANDEFILLE_CPL
CREATE OR REPLACE FORCE VIEW "AS_BONDECOMMANDEFILLE_CPL" ("IDBC","MONTANTHT","MONTANTTVA","REMISEMONTANT","TAUXDECHANGE") AS
SELECT
abf.IDBC ,
CAST(nvl(sum(montantht),0) AS NUMBER(30,2))  AS montantHT,
CAST(nvl(sum(montanttva),0) AS NUMBER(30,2)) AS montanttva,
CAST(nvl(sum(remiseMontant),0) AS NUMBER(30,2)) AS remiseMontant,
abf.TAUXDECHANGE
FROM AS_BONDECOMMANDE_CPL abf
GROUP BY abf.IDBC,abf.TAUXDECHANGE
;
-- [16/1309] AS_BONDECOMMANDE_FILLE_CPL
CREATE OR REPLACE FORCE VIEW "AS_BONDECOMMANDE_FILLE_CPL" ("ID","PRODUIT","IDBC","QUANTITE","PU","MONTANT","TVA","UNITE","IDUNITE","REMISE","IDDEVISE","TAUXDECHANGE","PRODUITLIB") AS
(
SELECT asbc."ID",
       asbc."PRODUIT",
       asbc."IDBC",
       asbc."QUANTITE",
       asbc."PU",
       asbc."MONTANT",
       asbc."TVA",
       asbc."UNITE",
       au.VAL        as IDUNITE,
       asbc."REMISE",
       asbc."IDDEVISE",
       asbc."TAUXDECHANGE",
       asing.libelle AS PRODUITLIB
FROM AS_BONDECOMMANDE_FILLE asbc
         LEFT JOIN AS_INGREDIENTS asing ON asbc.PRODUIT = asing.ID
         left join as_unite au on au.ID = asbc.UNITE
    )
;
-- [17/1309] AS_BONDECOMMANDE_MF
CREATE OR REPLACE FORCE VIEW "AS_BONDECOMMANDE_MF" ("ID","PRODUIT","IDBC","QUANTITE","PU","MONTANT","TVA","UNITE","REMISE","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","FOURNISSEUR","REFERENCE","TAUXDECHANGE") AS
select bcf."ID",bcf."PRODUIT",bcf."IDBC",bcf."QUANTITE",bcf."PU",bcf."MONTANT",bcf."TVA",bcf."UNITE",bcf."REMISE",
       ab.DATY,
       ab.ETAT,
       ab.REMARQUE,
       ab.DESIGNATION,
       ab.MODEPAIEMENT,
       ab.FOURNISSEUR,
       ab.REFERENCE,
       bcf.TAUXDECHANGE
from AS_BONDECOMMANDE_FILLE bcf
         left outer join AS_BONDECOMMANDE AB on AB.ID = bcf.IDBC
;
-- [18/1309] AS_BONDELIVRAISON_FILLE_LIB
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISON_FILLE_LIB" ("ID","PRODUIT","NUMBL","QUANTITE","IDDETAILSFACTUREFOURNISSEUR","UNITE","IDBC_FILLE") AS
select bl.ID,
       p.VAL as PRODUIT,
       bl.NUMBL,
       bl.QUANTITE,
       bl.IDDETAILSFACTUREFOURNISSEUR,
       u.VAL as UNITE,
       bl.IDBC_FILLE
from As_BonDeLivraison_Fille bl
         left join PRODUIT p on bl.PRODUIT = p.ID
         left join UNITE u on bl.UNITE = u.ID
;
-- [19/1309] AS_BONDELIVRAISON_MF
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISON_MF" ("ID","PRODUIT","NUMBL","QUANTITE","IDDETAILSFACTUREFOURNISSEUR","UNITE","IDBC_FILLE","REMARQUE","IDBC","DATY","ETAT") AS
select blf."ID",blf."PRODUIT",blf."NUMBL",blf."QUANTITE",blf."IDDETAILSFACTUREFOURNISSEUR",blf."UNITE",blf."IDBC_FILLE",
       AB.REMARQUE,
       AB.IDBC,
       AB.DATY,
       AB.ETAT

from AS_BONDELIVRAISON_FILLE blf
         left join AS_BONDELIVRAISON AB on AB.ID = blf.NUMBL
;
-- [20/1309] AS_BONDELIVRAISON_LIVRE
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISON_LIVRE" ("IDBC_FILLE","QTE_LIVRE") AS
select IDBC_FILLE, sum(QUANTITE) as qte_livre
from AS_BONDELIVRAISON_MF
group by IDBC_FILLE
;
-- [21/1309] AS_BONDECOMMANDE_LIVRE
CREATE OR REPLACE FORCE VIEW "AS_BONDECOMMANDE_LIVRE" ("ID","PRODUIT","IDBC","QUANTITE","PU","MONTANT","TVA","UNITE","REMISE","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","FOURNISSEUR","REFERENCE","QTE_COMMANDE","QTE_LIVRE","QTE_RESTE","PRODUITLIB","TAUXDECHANGE") AS
select bc."ID",bc."PRODUIT",bc."IDBC",bc."QUANTITE",bc."PU",bc."MONTANT",bc."TVA",bc."UNITE",bc."REMISE",bc."DATY",bc."ETAT",bc."REMARQUE",bc."DESIGNATION",bc."MODEPAIEMENT",bc."FOURNISSEUR",bc."REFERENCE",
       BC.QUANTITE as qte_commande,
       nvl(AB.qte_livre, 0)               as qte_livre,
       BC.QUANTITE - nvl(AB.qte_livre, 0) AS QTE_reste,
       p.LIBELLE as produitlib,
       bc.TAUXDECHANGE
from AS_BONDECOMMANDE_MF bc
         left join AS_BONDELIVRAISON_LIVRE AB on AB.IDBC_FILLE = bc.id
         left join AS_INGREDIENTS p on p.id=bc.PRODUIT
;
-- [22/1309] AS_INGREDIENTS_CONSOMMABLE
CREATE OR REPLACE FORCE VIEW "AS_INGREDIENTS_CONSOMMABLE" ("ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT","LIBELLEEXTACTE","TVA","FILEPATH","RESTE","TYPESTOCK","REFPOST","REFQUALIFICATION","IDCHAMBRE","ISPERISHABLE","PV2","IDFAMILLE","IDMAGASIN","PARFUMS","ISPETRI","TYPECONSO","COMPTE_TVA","TYPEPRODUIT") AS
SELECT "ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT","LIBELLEEXTACTE","TVA","FILEPATH","RESTE","TYPESTOCK","REFPOST","REFQUALIFICATION","IDCHAMBRE","ISPERISHABLE","PV2","IDFAMILLE","IDMAGASIN","PARFUMS","ISPETRI","TYPECONSO","COMPTE_TVA","TYPEPRODUIT" FROM AS_INGREDIENTS ai WHERE ai.CATEGORIEINGREDIENT = 'CAT0011'
;
-- [23/1309] AS_INGREDIENTS_ELECTRICITE
CREATE OR REPLACE FORCE VIEW "AS_INGREDIENTS_ELECTRICITE" ("ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT","LIBELLEEXTACTE","TVA","FILEPATH","RESTE","TYPESTOCK","REFPOST","REFQUALIFICATION","IDCHAMBRE","ISPERISHABLE","PV2","IDFAMILLE","IDMAGASIN","PARFUMS","ISPETRI","TYPECONSO","COMPTE_TVA","TYPEPRODUIT") AS
SELECT aic."ID",aic."LIBELLE",aic."SEUIL",aic."UNITE",aic."QUANTITEPARPACK",aic."PU",aic."ACTIF",aic."PHOTO",aic."CALORIE",aic."DURRE",aic."COMPOSE",aic."CATEGORIEINGREDIENT",aic."IDFOURNISSEUR",aic."DATY",aic."QTELIMITE",aic."PV",aic."LIBELLEVENTE",aic."SEUILMIN",aic."SEUILMAX",aic."PUACHATUSD",aic."PUACHATEURO",aic."PUACHATAUTREDEVISE",aic."PUVENTEUSD",aic."PUVENTEEURO",aic."PUVENTEAUTREDEVISE",aic."ISVENTE",aic."ISACHAT",aic."COMPTE_VENTE",aic."COMPTE_ACHAT",aic."LIBELLEEXTACTE",aic."TVA",aic."FILEPATH",aic."RESTE",aic."TYPESTOCK",aic."REFPOST",aic."REFQUALIFICATION",aic."IDCHAMBRE",aic."ISPERISHABLE",aic."PV2",aic."IDFAMILLE",aic."IDMAGASIN",aic."PARFUMS",aic."ISPETRI",aic."TYPECONSO",aic."COMPTE_TVA",aic."TYPEPRODUIT"
