-- [24/1309] AS_INGREDIENTS_NON_VENTE
CREATE OR REPLACE FORCE VIEW "AS_INGREDIENTS_NON_VENTE" ("ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV") AS
