-- [26/1309] AS_INGREDIENT_MAINTENANCE_LIB
CREATE OR REPLACE FORCE VIEW "AS_INGREDIENT_MAINTENANCE_LIB" ("ID","IDINGREDIENT","IDENTITE","REFERENCEOBJET","MARQUEOBJET","MODELEOBJET","NUMEROSERIEOBJET","DESCRIPTIONOBJET","QUALITEOBJET","ETATOBJET","LOCALISATIONOBJET","PUISSANCEOBJET","OBSERVATIONOBJET","TYPERATTACHEMENT","ESTENGIN","LIBELLE","DATEAQUISITION","INGREDIENTLIB","IDENTITELIB","QUALITEOBJETLIB","ETATOBJETLIB","LOCALISATIONOBJETLIB","ESTENGINLIB","IDLIGNE","IDLIGNELIB","PU","MOTSCLESSS","IDDEPARTEMENT","IDDEPARTEMENTLIB") AS
SELECT
    am.ID,
    am.IDINGREDIENT,
    am.IDENTITE,
    am.REFERENCEOBJET,
    am.MARQUEOBJET,
    am.MODELEOBJET,
    am.NUMEROSERIEOBJET,
    am.DESCRIPTIONOBJET,
    am.QUALITEOBJET,
    am.ETATOBJET,
    am.LOCALISATIONOBJET,
    am.PUISSANCEOBJET,
    am.OBSERVATIONOBJET,
    am.TYPERATTACHEMENT,
    am.ESTENGIN,
    am.LIBELLE,
    am.DATEAQUISITION,

    ai.libelle AS INGREDIENTLIB,
    am.IDENTITE AS IDENTITELIB,
    qo.VAL AS QUALITEOBJETLIB,
    eo.VAL AS ETATOBJETLIB,
    ld.val AS localisationObjetLib,

    CASE
        WHEN am.ESTENGIN = 1 THEN 'Oui'
        ELSE 'Non'
        END AS ESTENGINLIB,

    l.id AS idligne,
    l.val AS idlignelib,
    am.pu AS PU,

    (
        NVL(am.ID, '') || ' | ' ||
        NVL(ai.libelle, '') || ' | ' ||
        NVL(am.IDENTITE, '') || ' | ' ||
        NVL(qo.val, '') || ' | ' ||
        NVL(eo.val, '') || ' | ' ||
        NVL(ld.val, '') || ' | ' ||
        NVL(l.val, '') || ' | ' ||
        NVL(am.LIBELLE, '')
        ) AS MOTSCLESSS,
    ai.parfums AS iddepartement,
    de.val AS iddepartementlib

FROM AS_INGREDIENTS ai
         JOIN AS_INGREDIENT_MAINTENANCE am ON ai.ID = am.IDINGREDIENT
         LEFT JOIN QUALITESOBJETMAINTENANCE qo ON am.QUALITEOBJET = qo.ID
         LEFT JOIN ETATOBJETMAINTENANCE eo ON am.ETATOBJET = eo.ID
         LEFT JOIN LOG_DEPARTEMENT ld ON am.LOCALISATIONOBJET = ld.ID
         LEFT JOIN LIGNE l ON l.ID = am.IDLIGNE
         LEFT JOIN departement de ON de.id=ai.parfums
;
-- [27/1309] AS_INGREDIENT_MACHINE
CREATE OR REPLACE FORCE VIEW "AS_INGREDIENT_MACHINE" ("ID","IDINGREDIENT","IDENTITE","REFERENCEOBJET","MARQUEOBJET","MODELEOBJET","NUMEROSERIEOBJET","DESCRIPTIONOBJET","QUALITEOBJET","ETATOBJET","LOCALISATIONOBJET","PUISSANCEOBJET","OBSERVATIONOBJET","TYPERATTACHEMENT","ESTENGIN","LIBELLE","DATEAQUISITION","INGREDIENTLIB","IDENTITELIB","QUALITEOBJETLIB","ETATOBJETLIB","LOCALISATIONOBJETLIB","ESTENGINLIB","IDLIGNE","IDLIGNELIB","PU","IDINSPECTION") AS
(
  SELECT
	  asm.ID,
	  asm.IDINGREDIENT,
	  asm.IDENTITE,
	  asm.REFERENCEOBJET,
	  asm.MARQUEOBJET,
	  asm.MODELEOBJET,
	  asm.NUMEROSERIEOBJET,
	  asm.DESCRIPTIONOBJET,
	  asm.QUALITEOBJET,
	  asm.ETATOBJET,
	  asm.LOCALISATIONOBJET,
	  asm.PUISSANCEOBJET,
	  asm.OBSERVATIONOBJET,
	  asm.TYPERATTACHEMENT,
	  asm.ESTENGIN,
	  asm.LIBELLE,
	  asm.DATEAQUISITION,
	  asm.INGREDIENTLIB,
	  asm.IDENTITELIB,
	  asm.QUALITEOBJETLIB,
	  asm.ETATOBJETLIB,
	  asm.LOCALISATIONOBJETLIB,
	  asm.ESTENGINLIB,
	  asm.IDLIGNE,
	  asm.IDLIGNELIB,
	  asm.PU,
	  im.id AS idinspection
  FROM
  	As_ingredient_maintenance_lib asm
  	LEFT JOIN inspectionmere im ON im.idElement=asm.id
  WHERE
  	IDENTITE = 'ENT000001')
;
-- [28/1309] AS_INGREDIENT_PIECE
CREATE OR REPLACE FORCE VIEW "AS_INGREDIENT_PIECE" ("ID","IDINGREDIENT","IDENTITE","REFERENCEOBJET","MARQUEOBJET","MODELEOBJET","NUMEROSERIEOBJET","DESCRIPTIONOBJET","QUALITEOBJET","ETATOBJET","LOCALISATIONOBJET","PUISSANCEOBJET","OBSERVATIONOBJET","TYPERATTACHEMENT","ESTENGIN","LIBELLE","DATEAQUISITION","INGREDIENTLIB","IDENTITELIB","QUALITEOBJETLIB","ETATOBJETLIB","LOCALISATIONOBJETLIB","ESTENGINLIB","IDLIGNE","IDLIGNELIB","PU") AS
SELECT "ID","IDINGREDIENT","IDENTITE","REFERENCEOBJET","MARQUEOBJET","MODELEOBJET","NUMEROSERIEOBJET","DESCRIPTIONOBJET","QUALITEOBJET","ETATOBJET","LOCALISATIONOBJET","PUISSANCEOBJET","OBSERVATIONOBJET","TYPERATTACHEMENT","ESTENGIN","LIBELLE","DATEAQUISITION","INGREDIENTLIB","IDENTITELIB","QUALITEOBJETLIB","ETATOBJETLIB","LOCALISATIONOBJETLIB","ESTENGINLIB","IDLIGNE","IDLIGNELIB","PU" FROM As_ingredient_maintenance_lib WHERE IDENTITE = 'ENT000004'
;
-- [29/1309] AS_PRODUITS
CREATE OR REPLACE FORCE VIEW "AS_PRODUITS" ("ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT") AS
select "ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT" from AS_INGREDIENTS where pv>0
;
-- [30/1309] AS_RECETTECOMPOSE
CREATE OR REPLACE FORCE VIEW "AS_RECETTECOMPOSE" ("ID","IDPRODUITS","IDINGREDIENTS","QUANTITE","UNITE","COMPOSE","TYPESTOCK","CATEGORIEINGREDIENT") AS
select r.ID,
       r.IDPRODUITS,
       r.IDINGREDIENTS,
       CAST(r.QUANTITE AS NUMBER(30,
                                 10)) AS quantite,
       nvl(r.UNITE, u.VAL) as unite,
       ing.compose,
       ing.TYPESTOCK,
       ing.CATEGORIEINGREDIENT
FROM
    as_recette r,
    as_ingredients ing,
    as_unite u
WHERE
    r.IDINGREDIENTS = ing.id(+)
  and ing.UNITE=u.id
;
-- [31/1309] AS_RECETTEBC
CREATE OR REPLACE FORCE VIEW "AS_RECETTEBC" ("ID","IDPRODUITS","IDINGREDIENTS","QUANTITE","UNITE","COMPOSE") AS
select offi.id,offi.idbc as IDPRODUITS,offi.PRODUIT as idingredients,
cast(cast(offi.quantite as number(20,2))*cast(nvl(e.qte,1) as number(20,2)) as number(20,2)) as quantite,ing.unite,ing.compose from BONDECOMMANDE_CLIENT_FILLE offi left join equivalence e
on e.idproduit=offi.PRODUIT and e.idunite=offi.unite
left join as_ingredients ing on ing.id=offi.PRODUIT
union all
select "ID","IDPRODUITS","IDINGREDIENTS",cast (QUANTITE as number(20,2))as quantite,"UNITE","COMPOSE" from AS_RECETTECOMPOSE
;
-- [32/1309] AS_RECETTEFAB
CREATE OR REPLACE FORCE VIEW "AS_RECETTEFAB" ("ID","IDPRODUITS","IDINGREDIENTS","QUANTITE","VAL","COMPOSE") AS
select offi.id,offi.idMere as IDPRODUITS,offi.idingredients,
cast(offi.qte*nvl(e.qte,1) as number(30,10))as quantite,u.val,ing.compose from FabricationFille offi left join equivalence e
on e.idproduit=offi.idingredients and e.idunite=offi.idunite
left join as_ingredients ing on ing.id=offi.idingredients
left join as_unite u on ing.UNITE=u.id
union all
select "ID","IDPRODUITS","IDINGREDIENTS",cast (QUANTITE as number(30,10))as quantite,"UNITE","COMPOSE" from AS_RECETTECOMPOSE
;
-- [33/1309] AS_RECETTEOF
CREATE OR REPLACE FORCE VIEW "AS_RECETTEOF" ("ID","IDPRODUITS","IDINGREDIENTS","QUANTITE","UNITE","COMPOSE") AS
SELECT
    id,
    IDPRODUITS,
    IDINGREDIENTS,
    CAST(quantite AS NUMBER(30,10)) AS quantite,
    unite,
    compose
FROM (
    SELECT
        offi.id,
        offi.idMere AS IDPRODUITS,
        offi.idingredients AS IDINGREDIENTS,
        CAST(offi.qte AS NUMBER(30,10)) * CAST(NVL(e.qte, 1) AS NUMBER(30,10)) AS quantite,
        ing.unite,
        ing.compose
    FROM
        OFFille offi
    LEFT JOIN equivalence e ON
        e.idproduit = offi.idingredients
        AND e.idunite = offi.idunite
    LEFT JOIN as_ingredients ing ON
        ing.id = offi.idingredients
    
    UNION ALL
    
    SELECT
        ID,
        IDPRODUITS,
        IDINGREDIENTS,
        QUANTITE,
        UNITE,
        COMPOSE
    FROM
        AS_RECETTECOMPOSE
)
;
-- [34/1309] AS_RECETTEOFABRICATION
CREATE OR REPLACE FORCE VIEW "AS_RECETTEOFABRICATION" ("ID","IDPRODUITS","IDINGREDIENTS","QUANTITE","UNITE","COMPOSE") AS
select offi.id,fab.ID as IDPRODUITS,offi.IDINGREDIENTS as idingredients,
cast(cast(offi.QTE as number(20,2))*cast(nvl(e.qte,1) as number(20,2)) as number(20,2)) as quantite,ing.unite,ing.compose from OFFILLE offi left join equivalence e
on e.idproduit=offi.IDINGREDIENTS and e.idunite=offi.IDUNITE
left join as_ingredients ing on ing.id=offi.IDINGREDIENTS
left join OFAB fab on offi.IDMERE=fab.ID
union all
select ID,IDPRODUITS,IDINGREDIENTS,cast (QUANTITE as number(20,2))as quantite,UNITE,COMPOSE from AS_RECETTECOMPOSE
;
-- [35/1309] AS_RECETTEOFF
CREATE OR REPLACE FORCE VIEW "AS_RECETTEOFF" ("ID","IDPRODUITS","IDINGREDIENTS","QUANTITE","UNITE","COMPOSE") AS
select offi.id,offi.ID as IDPRODUITS,offi.IDINGREDIENTS as idingredients,
cast(cast(offi.QTE as number(30,10))*cast(nvl(e.qte,1) as number(30,10)) as number(30,10)) as quantite,ing.unite,ing.compose from OFFILLE offi left join equivalence e
on e.idproduit=offi.IDINGREDIENTS and e.idunite=offi.IDUNITE
left join as_ingredients ing on ing.id=offi.IDINGREDIENTS
union all
select ID,IDPRODUITS,IDINGREDIENTS,cast (QUANTITE as number(30,10))as quantite,UNITE,COMPOSE from AS_RECETTECOMPOSE
;
-- [36/1309] AS_RECETTEREC
CREATE OR REPLACE FORCE VIEW "AS_RECETTEREC" ("ID","IDPRODUITS","IDINGREDIENTS","QUANTITE","VAL","COMPOSE") AS
select offi.id,offi.id as IDPRODUITS,offi.idingredients,
cast(offi.quantite*nvl(e.qte,1) as number(30,10))as quantite,u.val,ing.compose from as_recette offi left join equivalence e
on e.idproduit=offi.idingredients and e.idunite=offi.unite
left join as_ingredients ing on ing.id=offi.idingredients
left join as_unite u on ing.UNITE=u.id
union all
select "ID","IDPRODUITS","IDINGREDIENTS",cast (QUANTITE as number(30,10))as quantite,"UNITE","COMPOSE" from AS_RECETTECOMPOSE
;
-- [37/1309] AS_RECETTE_LIBCOMPLET
CREATE OR REPLACE FORCE VIEW "AS_RECETTE_LIBCOMPLET" ("ID","IDPRODUITS","IDINGREDIENTS","QUANTITE","UNITE","LIBELLEINGREDIENT","LIBELLEPRODUIT","IDUNITE","VALUNITE","PU") AS
select rec."ID",rec."IDPRODUITS",rec."IDINGREDIENTS",rec."QUANTITE",ing."UNITE",
ing.LIBELLE as libelleingredient,
       ing2.libelle as libelleproduit,
un.id as idunite,
un.val as valunite,
ing.pu
from as_recette rec
left join as_ingredients ing on
ing.id=rec.idingredients
left join as_ingredients ing2 on
ing2.id=rec.IDPRODUITS
left join as_unite un on
un.id=ing.unite
order by rec.id asc
;
-- [38/1309] AS_RECETTE_MAINTENANCE_LIB
CREATE OR REPLACE FORCE VIEW "AS_RECETTE_MAINTENANCE_LIB" ("ID","IDPRODUITS","IDINGREDIENTS","UNITE","QUANTITE","IDPRODUITSLIB","IDINGREDIENTSLIB","IDINGREDIENTSMAINTENANCE","UNITELIB") AS
select
             ar."ID",ar."IDPRODUITS",ar."IDINGREDIENTS",ar."UNITE",ar."QUANTITE" ,
             ai2.LIBELLE AS idProduitslib,
             ai.LIBELLE  AS idIngredientsLib,
             aim.id AS idIngredientsMaintenance,
             au.val AS uniteLib
         FROM AS_recette ar
                  LEFT JOIN As_ingredients ai ON ai.id = ar.IDINGREDIENTS
                  LEFT JOIN As_ingredients ai2 ON ai2.id = ar.IDPRODUITS
                  LEFT JOIN AS_UNITE au ON ai.unite = au.id
                  JOIN AS_INGREDIENT_MAINTENANCE aim ON aim.IDINGREDIENT  = ai2.id
;
-- [39/1309] AS_RECOFFVUE
CREATE OR REPLACE FORCE VIEW "AS_RECOFFVUE" ("ID","IDINGREDIENTS","UNITE","QTEAV","QUANTITE","IDPRODUITS","IDUNITE","COMPOSE","NIVEAU","LIBINGREDIENTS","RESTESTOCK","TYPESTOCK") AS
SELECT
    ar.ID,ar.IDINGREDIENTS,ar.UNITE,ar.QTEAV,ar.QUANTITE,ar.IDPRODUITS,ar.IDUNITE,ar.COMPOSE,ar.NIVEAU,
    ai.LIBELLE AS libIngredients,cast(0 as number(30,10)) as resteStock,ai.TYPESTOCK
FROM AS_RECETTEOFFFABTABLE ar
         LEFT JOIN AS_INGREDIENTS ai ON ai.id = ar.IDINGREDIENTS
;
-- [40/1309] AS_RECOFFVUERESTEST
CREATE OR REPLACE FORCE VIEW "AS_RECOFFVUERESTEST" ("ID","IDINGREDIENTS","UNITE","QTEAV","QUANTITE","IDPRODUITS","IDUNITE","COMPOSE","NIVEAU","LIBINGREDIENTS","RESTESTOCK","RAF","TYPESTOCK") AS
SELECT 
a.ID,a.IDINGREDIENTS,a.UNITE,a.QTEAV,a.QUANTITE,a.IDPRODUITS,a.IDUNITE,a.COMPOSE,a.NIVEAU,a.LIBINGREDIENTS,
a.resteStock,
CAST( nvl(a.QUANTITE,0) - nvl(a.RESTESTOCK,0) AS NUMBER(30,10))  AS raf,a.TYPESTOCK
FROM as_recOffVue a
;
-- [41/1309] AS_UNITE_ACTIF
CREATE OR REPLACE FORCE VIEW "AS_UNITE_ACTIF" ("ID","VAL","DESCE","ACTIF") AS
select "ID","VAL","DESCE","ACTIF" from AS_UNITE where ACTIF=1
;
-- [42/1309] ATTRIBUTIONELEMENTLIB
CREATE OR REPLACE FORCE VIEW "ATTRIBUTIONELEMENTLIB" ("ID","IDINGREDIENTMAINTENANCE","IDPERSONNEL","DATY","ETATELEMENT","TYPEATTRIBUTION","IDINGREDIENTMAINTENANCELIB","IDPERSONNELLIB","QUALITEOBJETMAINTENANCELIB","TYPEATTRIBUTIONLIB","QTE","ETAT","ETATLIB","MOTSCLESSS") AS
select
	    attr.ID,attr.IDINGREDIENTMAINTENANCE,attr.IDPERSONNEL,attr.DATY,attr.ETATELEMENT,attr.TYPEATTRIBUTION,
	    asing.LIBELLE as IDINGREDIENTMAINTENANCELIB,
	    pers.NOM as idPersonnelLib,
	    qom.VAL as qualiteObjetMaintenanceLib,
	    case
	        when attr.TYPEATTRIBUTION = 0 then 'Sortie'
	        when attr.TYPEATTRIBUTION = 1 then 'Retour'
	        else 'Inconnu'
	        end as typeAttributionLib,
	    attr.qte AS qte,
	    attr.etat,
	    case
	        when attr.etat = 1 then 'Creee'
	        when attr.etat = 11 then 'Visee'
	        when attr.etat = 0 then 'Annulee'
	        end as etatLib,
	    attr.id || asing.libelle || pers.nom || qom.val AS motsclesss
	from
	    ATTRIBUTIONELEMENT attr
	        left join AS_INGREDIENT_MAINTENANCE ingm on attr.IDINGREDIENTMAINTENANCE = ingm.ID
	        left join AS_INGREDIENTS asing on ingm.IDINGREDIENT = asing.ID
	        left join PERSONNEL pers on attr.IDPERSONNEL = pers.ID
	        left join QUALITESOBJETMAINTENANCE qom on attr.ETATELEMENT = qom.ID
;
-- [43/1309] AUTOLIB
CREATE OR REPLACE FORCE VIEW "AUTOLIB" ("ID","IDINGREDIENT","DESCRIPTION","NUMERODEPARC","DATEPREMIEREMISEENCIRCULATION","IMMATRICULATION","NOTE","FOURNISSEUR","NUMERO","VOLUME","MONTANT","TYPE","VIN","MARQUE","MODELE","ANNEE","NOMBREDEPLACES","NOMBREDEPORTES","PUISSANCEFISCALE","BAILLEUR","VALEURINITIALE","DATEDEBUT","DURREEENMOIS","MENSUALITE","VENDEUR","PRIX","DATEDACHAT","NUMERODIMMOBILISATION","DUREEDAMORTISSEMENTENMOIS","PNEUS","BATTERIE","HUILEMOTEUR","HUILEBOITEDEVITESSE","TYPEDECARBURANT","CONSOMMATION","UNITEDECONSOMMATION","TYPECARBURANTLIB","UNITEDECONSOMMATIONLIB") AS
select ia."ID",ia."IDINGREDIENT",ia."DESCRIPTION",ia."NUMERODEPARC",ia."DATEPREMIEREMISEENCIRCULATION",ia."IMMATRICULATION",ia."NOTE",ia."FOURNISSEUR",ia."NUMERO",ia."VOLUME",ia."MONTANT",ia."TYPE",ia."VIN",ia."MARQUE",ia."MODELE",ia."ANNEE",ia."NOMBREDEPLACES",ia."NOMBREDEPORTES",ia."PUISSANCEFISCALE",ia."BAILLEUR",ia."VALEURINITIALE",ia."DATEDEBUT",ia."DURREEENMOIS",ia."MENSUALITE",ia."VENDEUR",ia."PRIX",ia."DATEDACHAT",ia."NUMERODIMMOBILISATION",ia."DUREEDAMORTISSEMENTENMOIS",ia."PNEUS",ia."BATTERIE",ia."HUILEMOTEUR",ia."HUILEBOITEDEVITESSE",ia."TYPEDECARBURANT",ia."CONSOMMATION",ia."UNITEDECONSOMMATION", tc.val as typecarburantlib, uc.val as UNITEDECONSOMMATIONLIB from INFOSAUTO ia
                                                                                   left join Typecarburant tc on ia.TYPEDECARBURANT = tc.id
                                                                                   left join uniteconso uc on ia.UNITEDECONSOMMATION = uc.id
;
-- [44/1309] AUTOMAINTENANCE
CREATE OR REPLACE FORCE VIEW "AUTOMAINTENANCE" ("ID","VAL","DESCE") AS
select
    im.ID,
    ai.LIBELLE as val,
    ' ' as desce
from AS_INGREDIENT_MAINTENANCE im
         left join AS_INGREDIENTS ai on im.IDINGREDIENT = ai.ID
where im.IDENTITE = 'ENT000003'
;
-- [45/1309] AUTOMATIQUEFORM
CREATE OR REPLACE FORCE VIEW "AUTOMATIQUEFORM" ("ID","IDCAISSEBANQUE","DATEMIN","DATEMAX") AS
select
    '' as id,
    '' as idCaisseBanque,
    null as dateMin,
    null as dateMax
from dual
;
-- [46/1309] AVANCE_LIB
CREATE OR REPLACE FORCE VIEW "AVANCE_LIB" ("ID","IDPERSONNEL","MONTANT","NBREMBOURSEMENT","REMARQUE","DATY","DATEAVANCE","INTERET","ETAT","IDTYPEAVANCE","MATRICULE","DATEDEBUTREMBOURSEMENT") AS
SELECT av.id,
       (log.nom || ' ') || log.prenom AS idpersonnel,
       av.montant,
       av.nbremboursement,
       av.remarque,
       av.daty,
       av.dateavance,
       av.interet,
       av.etat,
       ty.val AS idtypeavance,
       p.matricule,
       av.DATEDEBUTREMBOURSEMENT
FROM avance av
         LEFT JOIN log_personnel log ON av.idpersonnel = log.id
         LEFT JOIN paie_info_personnel p ON p.id = log.id
         LEFT JOIN typeavance ty ON ty.id = av.idtypeavance
;
-- [47/1309] AVANCE_LIB2
CREATE OR REPLACE FORCE VIEW "AVANCE_LIB2" ("ID","IDPERSONNEL","MONTANT","NBREMBOURSEMENT","REMARQUE","DATY","DATEAVANCE","INTERET","ETAT","DATEDEBLOCAGE","DATEDEBUTREMBOURSEMENT","ETATLIB","IDTYPEAVANCE","IDTYPEAVANCELIB","MATRICULE","MOISLIB","MOIS","DATESAISIE") AS
SELECT av.id,
       (log.nom || ' ') || log.prenom AS idpersonnel,
       av.montant,
       av.nbremboursement,
       av.remarque,
       av.daty,
       av.dateavance,
       av.interet,
       av.etat,
       av.DATEDEBLOCAGE,
       av.DATEDEBUTREMBOURSEMENT,
       CASE
           WHEN av.etat = 1  THEN '<span style= color:blue; >creee</span>'
           WHEN av.etat = 11 THEN '<span style= color:blue; >validee et impayee</span>'
           WHEN av.etat = 21 THEN '<span style= color:blue; >validee et payee </span>'
           ELSE NULL
           END AS etatlib,
       av.idtypeavance,
       ty.val AS idtypeavancelib,
       p.matricule,
       TO_CHAR(
               TO_DATE(TO_CHAR(av.mois, 'FM00'), 'MM'),
               'FMMonth',
               'NLS_DATE_LANGUAGE=FRENCH'
       ) AS moisLib,
       av.MOIS,
       av.dateSaisie
FROM avance av
         LEFT JOIN log_personnel log ON av.idpersonnel = log.id
         LEFT JOIN paie_info_personnel p ON p.id = log.id
         LEFT JOIN typeavance ty ON ty.id = av.idtypeavance
 ORDER BY TO_NUMBER(REGEXP_REPLACE(matricule, '[^0-9]', ''))
;
-- [48/1309] AVANCE_LIB_CREE
CREATE OR REPLACE FORCE VIEW "AVANCE_LIB_CREE" ("ID","IDPERSONNEL","MONTANT","NBREMBOURSEMENT","REMARQUE","DATY","DATEAVANCE","INTERET","ETAT","ETATLIB","IDTYPEAVANCE","IDTYPEAVANCELIB","MATRICULE") AS
select "ID","IDPERSONNEL","MONTANT","NBREMBOURSEMENT","REMARQUE","DATY","DATEAVANCE","INTERET","ETAT","ETATLIB","IDTYPEAVANCE","IDTYPEAVANCELIB","MATRICULE" from AVANCE_LIB2 where etat = 1
;
-- [49/1309] AVANCE_LIB_PAYE
CREATE OR REPLACE FORCE VIEW "AVANCE_LIB_PAYE" ("ID","IDPERSONNEL","MONTANT","NBREMBOURSEMENT","REMARQUE","DATY","DATEAVANCE","INTERET","ETAT","ETATLIB","IDTYPEAVANCE","IDTYPEAVANCELIB","MATRICULE") AS
select "ID","IDPERSONNEL","MONTANT","NBREMBOURSEMENT","REMARQUE","DATY","DATEAVANCE","INTERET","ETAT","ETATLIB","IDTYPEAVANCE","IDTYPEAVANCELIB","MATRICULE" from AVANCE_LIB2 where etat = 21
;
-- [50/1309] AVANCE_LIB_VISEE
CREATE OR REPLACE FORCE VIEW "AVANCE_LIB_VISEE" ("ID","IDPERSONNEL","MONTANT","NBREMBOURSEMENT","REMARQUE","DATY","DATEAVANCE","INTERET","ETAT","ETATLIB","IDTYPEAVANCE","IDTYPEAVANCELIB","MATRICULE") AS
select "ID","IDPERSONNEL","MONTANT","NBREMBOURSEMENT","REMARQUE","DATY","DATEAVANCE","INTERET","ETAT","ETATLIB","IDTYPEAVANCE","IDTYPEAVANCELIB","MATRICULE" from AVANCE_LIB2 where etat = 11
;
-- [51/1309] AVOIRACHATFILLECALC
CREATE OR REPLACE FORCE VIEW "AVOIRACHATFILLECALC" ("ID","IDMERE","IDPRODUIT","QTE","PU","REMISE","TVA","IDDEVISE","TAUX","DESIGNATION","IDFACTUREDETAILS","RISTOURNE","TAUXDECHANGE","MONTANTNONREMISE","MONTANTREMISESANSTVA","MONTANTHT","PUREMISE","MONTANTHTAR","MONTANTTVA","MONTANTTVAAR","MONTANTTTC","MONTANTTTCAR") AS
select vd."ID",vd."IDMERE",vd."IDPRODUIT",vd."QTE",vd."PU",vd."REMISE",vd."TVA",vd."IDDEVISE",vd."TAUX",vd."DESIGNATION",vd."IDFACTUREDETAILS",vd."RISTOURNE",vd."TAUXDECHANGE",cast(vd.QTE*vd.pu as number(30,2)) as montantNonRemise,
       cast(vd.QTE*vd.pu*((nvl(vd.REMISE,0)+nvl(vd.RISTOURNE,0))/100) as number(30,2)) as montantRemiseSansTva,
       cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100)) as number(30,2)) as montantHT,
       cast(vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100)) as number(30,2)) as puRemise,
       cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*nvl(vd.TAUXDECHANGE,1) as number(30,2)) as montantHTAr,
       cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*nvl(vd.tva,0)/100 as number(30,2)) as montantTva,
       cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*nvl(vd.TAUXDECHANGE,1)*nvl(vd.tva,0)/100 as number(30,2)) as montantTvaAr,
       cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*(1+(nvl(vd.tva,0)/100)) as number(30,2)) as montantTTC,
       cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*(1+(nvl(vd.tva,0)/100))*nvl(vd.TAUXDECHANGE,1) as number(30,2)) as montantTTCAr from AVOIRAchatFILLE vd
;
-- [52/1309] AVOIRACHATCALCGROUPEORIGINE
CREATE OR REPLACE FORCE VIEW "AVOIRACHATCALCGROUPEORIGINE" ("IDFACTURE","MONTANTNONREMISE","MONTANTREMISESANSTVA","MONTANTHT","MONTANTTTC","MONTANTTVA","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR") AS
select aa.IDFACTURE ,cast(sum(montantNonRemise) as number(30,2)) as montantNonRemise,cast(sum(montantRemiseSansTva) as number(30,2)) as montantRemiseSansTva,
       cast(sum(montantHT) as number(30,2)) as montantHT,cast(sum(montantTTC) as number(30,2)) as montantTTC,cast(sum(montantTva) as number(30,2)) as montantTva,
       cast(sum(montantHTAr) as number(30,2)) as montantHTAr,cast(sum(montantTvaAr) as number(30,2)) as montantTvaAr,cast(sum(montantTTCAr) as number(30,2)) as montantTTCAr
from AvoirAChatFilleCalc vdc left join avoirAchat aa on aa.id=vdc.IDMERE where aa.ETAT>=11   group by aa.IDFACTURE
;
-- [53/1309] AVOIRACHATFILLECALCGROUPE
CREATE OR REPLACE FORCE VIEW "AVOIRACHATFILLECALCGROUPE" ("IDAVOIRACHAT","MONTANTNONREMISE","MONTANTREMISESANSTVA","MONTANTHT","MONTANTTTC","MONTANTTVA","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR") AS
select vdc.IDMERE as idAvoirAchat ,cast(sum(montantNonRemise) as number(30,2)) as montantNonRemise,cast(sum(montantRemiseSansTva) as number(30,2)) as montantRemiseSansTva,
       cast(sum(montantHT) as number(30,2)) as montantHT,cast(sum(montantTTC) as number(30,2)) as montantTTC,cast(sum(montantTva) as number(30,2)) as montantTva,
       cast(sum(montantHTAr) as number(30,2)) as montantHTAr,cast(sum(montantTvaAr) as number(30,2)) as montantTvaAr,cast(sum(montantTTCAr) as number(30,2)) as montantTTCAr
from AvoirAChatFilleCalc vdc group by vdc.IDMERE
;
-- [54/1309] AVOIRACHATCALC
CREATE OR REPLACE FORCE VIEW "AVOIRACHATCALC" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDFOURNISSEUR","IDFACTURE","REMISE","MONTANTREMISE","MONTANTNONREMISE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTTTCAR") AS
select v."ID",v."DESIGNATION",v."IDMAGASIN",v."DATY",v."REMARQUE",v."ETAT",v."IDFOURNISSEUR",v."IDFACTURE",v."REMISE", cast(montantRemiseSansTva+ (montantHT* (nvl(v.REMISE,0)/100)) as number(30,2)) as montantRemise, montantNonRemise,
       cast(montantHT*(1-(nvl(v.REMISE,0)/100)) as number(30,2)) as montantHT,cast(montantTva*(1-(nvl(v.REMISE,0)/100)) as number(30,2)) as montantTva,
       cast(montantTTC*(1-(nvl(v.REMISE,0)/100)) as number(30,2)) as montantTTC, montantTTCAr*(1-(nvl(v.REMISE,0)/100)) as montantTTCAr
from AVOIRACHAT v left join AvoirAChatFilleCalcGroupe vdcv on v.id=vdcv.idAvoirAchat
;
-- [55/1309] AVOIRACHATCALC_AVEC_LIB
CREATE OR REPLACE FORCE VIEW "AVOIRACHATCALC_AVEC_LIB" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDFOURNISSEUR","IDFACTURE","REMISE","MONTANTREMISE","MONTANTNONREMISE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","ETATLIB","IDMAGASINLIB","IDFOURNISSEURLIB") AS
select a."ID",
       a."DESIGNATION",
       a."IDMAGASIN",
       a."DATY",
       a."REMARQUE",
       a."ETAT",
       a."IDFOURNISSEUR",
       a."IDFACTURE",
       a."REMISE",
       a."MONTANTREMISE",
       a."MONTANTNONREMISE",
       a."MONTANTHT",
       a."MONTANTTVA",
       a."MONTANTTTC",
       a."MONTANTTTCAR",
       case
           when a.etat = 1 then 'CR&Eacute;&Eacute;(E)'
           when a.etat = 11 then 'VIS&Eacute;(E)'
           when a.etat = 11 then 'ANNUL&Eacute;(E)'
           end as etatlib,
       m.VAL AS idmagasinLib,
       f.nom AS idfournisseurLib
from AVOIRACHATCALC a
         left join AvoirAChatFilleCalcGroupe vdcv on a.id = vdcv.idAvoirAchat
         LEFT JOIN MAGASIN2 m ON a.IDMAGASIN = m.ID
         LEFT JOIN FOURNISSEUR f ON a.IDFOURNISSEUR = f.ID
;
-- [56/1309] AVOIRACHATFILLELIB
CREATE OR REPLACE FORCE VIEW "AVOIRACHATFILLELIB" ("ID","IDMERE","IDPRODUIT","QTE","PU","REMISE","TVA","IDDEVISE","TAUX","DESIGNATION","IDFACTUREDETAILS","IDPRODUITLIB","IDDEVISELIB","MONTANT","MONTANTREMISE","MONTANTHT","MONTANTTVA","MONTANTTTC") AS
SELECT
    af.ID,
    af.IDMERE,
    af.IDPRODUIT,
    af.QTE,
    af.PU,
    af.REMISE,
    af.TVA,
    af.IDDEVISE,
    af.TAUX,
    af.DESIGNATION,
    af.IDFACTUREDETAILS,
    p.LIBELLE AS idproduitLib,
    d.val AS iddeviseLib,
    ----------------------------------------------------------
    -- 1 Montant HT brut
    ----------------------------------------------------------
    CAST(af.QTE * af.PU AS NUMBER(30, 2)) AS montant,
    ----------------------------------------------------------
    -- 2 Montant remise (appliquee sur HT)
    ----------------------------------------------------------
    CAST((NVL(af.REMISE, 0) / 100) * (af.QTE * af.PU) AS NUMBER(30, 2)) AS montantRemise,
    ----------------------------------------------------------
    -- 3 Montant HT net apres remise
    ----------------------------------------------------------
    CAST((af.QTE * af.PU) - ((NVL(af.REMISE, 0) / 100) * (af.QTE * af.PU)) AS NUMBER(30, 2)) AS montantht,
    ----------------------------------------------------------
    -- 4 TVA sur montant HT net
    ----------------------------------------------------------
    CAST(((af.QTE * af.PU) - ((NVL(af.REMISE, 0) / 100) * (af.QTE * af.PU))) * af.TVA / 100 AS NUMBER(30, 2))AS montanttva,
    ----------------------------------------------------------
    -- 5 Montant TTC net (HT net + TVA)
    ----------------------------------------------------------
    CAST( ((af.QTE * af.PU) - ((NVL(af.REMISE, 0) / 100) * (af.QTE * af.PU))) + ( ((af.QTE * af.PU) - ((NVL(af.REMISE, 0) / 100) * (af.QTE * af.PU)))  * af.TVA / 100  ) AS NUMBER(30, 2)) AS montantttc
FROM AVOIRACHATFILLE af
    LEFT JOIN AS_INGREDIENTS p ON af.IDPRODUIT = p.ID
    LEFT JOIN DEVISE d ON af.IDDEVISE = d.ID
;
-- [57/1309] AVOIRACHATLIB
CREATE OR REPLACE FORCE VIEW "AVOIRACHATLIB" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDFOURNISSEUR","IDFACTURE","IDMAGASINLIB","IDFOURNISSEURLIB") AS
SELECT a.ID,a.DESIGNATION,a.IDMAGASIN,a.DATY,a.REMARQUE,a.ETAT,a.IDFOURNISSEUR,a.IDFACTURE, m.VAL AS idmagasinLib, f.nom AS idfournisseurLib
FROM AVOIRACHAT a
    LEFT JOIN MAGASIN2 m ON a.IDMAGASIN = m.ID
    LEFT JOIN FOURNISSEUR f ON a.IDFOURNISSEUR = f.ID
;
-- [58/1309] AVOIRFCFILLELIB
CREATE OR REPLACE FORCE VIEW "AVOIRFCFILLELIB" ("ID","IDAVOIRFC","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","IDVENTEDETAILS","IDPRODUITLIB","CALORIE","POIDS","PTHT","MONTANTTVA") AS
SELECT
    AF.ID,
    AF.IDAVOIRFC,
    AF.IDPRODUIT,
    AF.IDORIGINE,
    AF.QTE,
    AF.PU,
    AF.REMISE,
    AF.TVA,
    AF.PUACHAT,
    AF.PUVENTE,
    AF.IDDEVISE,
    AF.TAUXDECHANGE,
    AF.DESIGNATION,
    AF.IDVENTEDETAILS,
    nvl(P.libellevente,P.LIBELLE) AS IDPRODUITLIB,
    P.CALORIE,
    P.CALORIE * AF.QTE AS POIDS,
    AF.PU * AF.QTE AS PTHT,
    (NVL(AF.pu,0) * NVL(AF.QTE,0)) * NVL(AF.TVA,0) / 100 AS montantTVA
FROM
    AVOIRFCFILLE AF
        LEFT JOIN as_ingredients P ON
        P.id = AF.IDPRODUIT
;
-- [59/1309] AVOIRFCFILLELIB_PDF
CREATE OR REPLACE FORCE VIEW "AVOIRFCFILLELIB_PDF" ("ID","IDAVOIRFC","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","IDVENTEDETAILS","IDPRODUITLIB","CALORIE","POIDS","PTHT","MONTANTTVA","TAUX") AS
SELECT
    AF.ID,
    AF.IDAVOIRFC,
    AF.IDPRODUIT,
    AF.IDORIGINE,
    AF.QTE,
    AF.PU,
    AF.REMISE,
    AF.TVA,
    AF.PUACHAT,
    AF.PUVENTE,
    AF.IDDEVISE,
    AF.TAUXDECHANGE,
    AF.DESIGNATION,
    AF.IDVENTEDETAILS,
    P.LIBELLEVENTE AS IDPRODUITLIB,
    P.CALORIE,
    P.CALORIE * AF.QTE AS POIDS,
    AF.PU * AF.QTE AS PTHT,
    (NVL(AF.pu,0) * NVL(AF.QTE,0)) * NVL(AF.TVA,0) / 100 AS montantTVA,
    AF.TAUX
FROM
    AVOIRFCFILLE AF
        LEFT JOIN as_ingredients P ON
        P.id = AF.IDPRODUIT
order by P.LIBELLEVENTE asc
;
-- [60/1309] AVOIRFCFILLE_GRP
CREATE OR REPLACE FORCE VIEW "AVOIRFCFILLE_GRP" ("IDAVOIRFC","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","TAUXDECHANGE","IDDEVISE") AS
SELECT a.idavoirfc,
       CAST(nvl(sum(a.QTE * a.PU), 0) AS NUMBER(30, 2))                                          AS montantht,
       CAST(nvl(sum(a.QTE * a.PU * a.TVA / 100), 0) AS NUMBER(30, 2))                            AS montanttva,
       CAST(nvl(sum((a.QTE * a.PU) + (a.QTE * a.PU * a.TVA / 100)), 0) AS NUMBER(30, 2))         AS montantttc,
       CAST(nvl(sum(a.QTE * a.PU * nvl(a.TAUXDECHANGE, 1)), 0) AS NUMBER(30, 2))                 AS montanthtAR,
       CAST(nvl(sum((a.QTE * a.PU * a.TVA / 100) * nvl(a.TAUXDECHANGE, 1)), 0) AS NUMBER(30, 2)) AS montanttvaAR,
       CAST(nvl(sum((a.QTE * a.PU * nvl(a.TAUXDECHANGE, 1)) + (a.QTE * a.PU * a.TVA / 100) * nvl(a.TAUXDECHANGE, 1)),
                0) AS NUMBER(30, 2))                                                             AS montantttcar,
       MAX(TAUXDECHANGE)                                                                         as tauxdechange,
       a.IDDEVISE
FROM AVOIRFCFILLE a
GROUP BY a.idavoirfc, a.IDDEVISE
;
-- [61/1309] AVOIRFCFILLE_GRP_VISEEE
CREATE OR REPLACE FORCE VIEW "AVOIRFCFILLE_GRP_VISEEE" ("IDVENTEDETAILS","QTE") AS
SELECT
IDVENTEDETAILS,
SUM(qte) AS qte
FROM
AvoirFCFille abcf
left join AvoirFC b on b.id=abcf.idAvoirFC
where b.ETAT>=11
GROUP BY IDVENTEDETAILS
;
-- [62/1309] AVOIRFC_MF
CREATE OR REPLACE FORCE VIEW "AVOIRFC_MF" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","IDVENTE","IDMOTIF","IDCATEGORIE") AS
SELECT 
a1."ID",a1."DESIGNATION",a1."IDMAGASIN",a1."DATY",a1."REMARQUE",a1."ETAT",a1."IDORIGINE",a1."IDCLIENT",a1."IDVENTE",a1."IDMOTIF",a1."IDCATEGORIE"
FROM AVOIRFCFILLE a 
JOIN AVOIRFC a1 ON a1.ID = a.IDAVOIRFC
;
-- [63/1309] BALANCE_CLIENT
CREATE OR REPLACE FORCE VIEW "BALANCE_CLIENT" ("IDPRODUIT","LIBELLE","IDFAMILLE","FAMILLE","QTE","PU","MONTANT","IDCLIENT","IDPROVINCE","VAL","DATY","REMISE") AS
select
    vd.IDPRODUIT,
    ing.LIBELLE,
    nvl(ing.IDFAMILLE,'AUTRE') as IDFAMILLE,
    nvl(fam.VAL,'AUTRE') as famille,
    sum(vd.QTE) as qte,
    sum(vd.PU*vd.QTE)/sum(vd.QTE) as pu,
    sum(vd.QTE * vd.PU) as montant,
    v.IDCLIENT,
    cl.IDPROVINCE,
    p.VAL,
    v.DATY,
    SUM(vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) AS remise
from VENTE_DETAILS vd
    join Vente v on vd.IDVENTE=v.id
    join AS_INGREDIENTS ing on ing.id=vd.IDPRODUIT
    left join FAMILLEPRODUIT fam on fam.id=ing.IDFAMILLE
    join Client cl on cl.id=v.IDCLIENT
    left join Province p on p.id=cl.IDPROVINCE
group by vd.IDPRODUIT, ing.LIBELLE, nvl(ing.IDFAMILLE,'AUTRE'),nvl(fam.VAL,'AUTRE'), v.IDCLIENT, cl.IDPROVINCE, p.VAL, v.DATY
;
-- [64/1309] BALANCE_VIDE
CREATE OR REPLACE FORCE VIEW "BALANCE_VIDE" ("COMPTE","CHIFFRE3","CHIFFRE2","LIBELLECOMPTE","ANTERIEURDEBIT","ANTERIEURCREDIT","MOUVEMENTDEBIT","MOUVEMENTCREDIT") AS
SELECT
    '-' AS compte,
    '-' AS chiffre3,
    '-' AS chiffre2,
    '-' AS libelleCompte,
    CAST(0 AS NUMBER(30,
        2)) AS anterieurDebit,
    CAST(0 AS NUMBER(30,
        2)) AS anterieurCredit,
    CAST(0 AS NUMBER(30,
        2)) AS mouvementDebit,
    CAST(0 AS NUMBER(30,
        2)) AS mouvementCredit
FROM
    dual
;
-- [65/1309] BANQUEAGENCELIB
CREATE OR REPLACE FORCE VIEW "BANQUEAGENCELIB" ("ID","NOM","CODEAGENCE","IDBANQUE","IDBANQUELIB") AS
SELECT
       bqa.id,
       bqa.nom,
       bqa.codeAgence,
       bqa.idBanque,
       b.val as idBanqueLib
FROM BANQUE_AGENCE bqa
   LEFT JOIN Banque b ON bqa.idBanque = b.id
;
-- [66/1309] BANQUE_COMPTA
CREATE OR REPLACE FORCE VIEW "BANQUE_COMPTA" ("ID","VAL","DESCE") AS
SELECT id,
       val,
       COMPTE AS desce
FROM CAISSE c
WHERE IDTYPECAISSE = 'TCA001'
  AND actif = 1
;
-- [67/1309] BATIMENTDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "BATIMENTDETAIL_LIB" ("ID","IDMERE","IDPARQUET","SURFACE","CAPACITE","IDLOT","IDSEXE","DENSITE","IDPARQUETLIB","IDLOTLIB","IDSEXELIB","EFFECTIF") AS
SELECT
    bd."ID",bd."IDMERE",bd."IDPARQUET",bd."SURFACE",bd."CAPACITE",bd."IDLOT",bd."IDSEXE",bd."DENSITE",
    p.val    AS idParquetLib,
    l.nomLot AS idLotLib,
    s.val    AS idSexeLib,
    NVL(bd."SURFACE" * bd."DENSITE", 0) AS EFFECTIF
FROM batimentDetail bd
         LEFT JOIN parquet p ON bd.idParquet = p.id
         LEFT JOIN lot  l ON bd.idLot     = l.id
         LEFT JOIN sexe s ON bd.idSexe    = s.id
;
-- [68/1309] BATIMENTVIDESANITAIREDETAILLIB
CREATE OR REPLACE FORCE VIEW "BATIMENTVIDESANITAIREDETAILLIB" ("ID","IDMERE","IDPRODUIT","QTE","REMARQUE","IDPRODUITLIB","IDUNITE","IDUNITELIB","PU") AS
SELECT 
	bvsd.id AS ID,
	bvsd.idmere AS IDMERE,
	bvsd.idproduit AS IDPRODUIT,
	bvsd.qte AS QTE,
	bvsd.remarque AS REMARQUE,
	ai.LIBELLE AS IDPRODUITLIB,
	ai.UNITE AS IDUNITE,
	asu.VAL AS IDUNITELIB,
	ai.PU AS PU
FROM batimentVideSanitaireDetail bvsd
LEFT JOIN AS_INGREDIENTS ai ON bvsd.idproduit = ai.ID
LEFT JOIN AS_UNITE asu ON ai.UNITE = asu.ID
;
-- [69/1309] BATIMENTVIDESANITAIRE_LIB
CREATE OR REPLACE FORCE VIEW "BATIMENTVIDESANITAIRE_LIB" ("ID","IDBATIMENT","IDRESPONSABLE","DATY","HEUREDEBUT","HEUREFIN","IDBATIMENTLIB","IDFERME","IDFERMELIB","IDRESPONSABLELIB","ETAT","ETATLIB") AS
SELECT
	bvs.id AS ID,
	bvs.idbatiment AS IDBATIMENT,
	bvs.idresponsable AS IDRESPONSABLE,
	bvs.daty AS DATY,
	bvs.heuredebut AS HEUREDEBUT,
	bvs.heurefin AS HEUREFIN,
	b.NOMBATIMENT AS IDBATIMENTLIB,
	b.IDFERME AS IDFERME,
	m.VAL AS IDFERMELIB,
	lp.NOM || ' ' || lp.PRENOM AS IDRESPONSABLELIB,
	bvs.etat,
	CASE
        WHEN bvs.etat = 1 THEN 'CREE'
            WHEN bvs.etat = 0 THEN 'ANNULEE'
            WHEN bvs.etat = 11 THEN 'VISEE'
        END AS etatLib
FROM batimentVideSanitaire bvs
LEFT JOIN BATIMENT b ON bvs.idbatiment = b.ID
LEFT JOIN MAGASIN2 m ON b.IDFERME = m.ID
LEFT JOIN LOG_PERSONNEL lp ON bvs.idresponsable = lp.ID
;
-- [70/1309] BATIMENT_LIB
CREATE OR REPLACE FORCE VIEW "BATIMENT_LIB" ("ID","IDFERME","NOMBATIMENT","SURFACE","CAPACITE","DENSITE","LONGUEUR","LARGEUR","IDFERMELIB") AS
SELECT
    b.ID,b.IDFERME,b.NOMBATIMENT,b.SURFACE,b.CAPACITE,b.DENSITE,b.LONGUEUR,b.LARGEUR,
    m.val AS idFermeLib
FROM batiment b
         LEFT JOIN MAGASIN2 m ON b.idFerme = m.id
;
-- [71/1309] BCCLIENT_FILLE_GRP
CREATE OR REPLACE FORCE VIEW "BCCLIENT_FILLE_GRP" ("ID","QUANTITE") AS
SELECT 
bc.ID,
nvl( sum(bcf.QUANTITE) ,0) AS QUANTITE
FROM BONDECOMMANDE_CLIENT_FILLE bcf 
LEFT JOIN BONDECOMMANDE_CLIENT bc ON bcf.IDBC = bc.ID
GROUP BY bc.ID
;
-- [72/1309] BCFILLERESTEALIVRERLIB
CREATE OR REPLACE FORCE VIEW "BCFILLERESTEALIVRERLIB" ("ID","IDBC","IDPRODUIT","IDPRODUITLIB","QUANTITE","PU","REMISE","TVA","IDUNITE","IDDEVISE","TAUXDECHANGE") AS
SELECT 
f.ID ,
f.IDBC ,
f.PRODUIT AS idproduit,
p.VAL AS IDPRODUITLIB,
f.QUANTITE ,
f.PU ,
f.REMISE , 
f.TVA , 
p.idunite AS idunite, 
f.iddevise,
f.tauxdechange
FROM AS_BONDECOMMANDE_FILLE f 
LEFT JOIN PRODUIT p ON p.ID = f.PRODUIT
;
-- [73/1309] BLCF_GRPVENTEDET
CREATE OR REPLACE FORCE VIEW "BLCF_GRPVENTEDET" ("IDVENTEDETAIL","QUANTITE") AS
SELECT 
IDVENTEDETAIL,
sum(quantite) AS quantite
FROM 
AS_BONDELIVRAISON_CLIENT_FILLE group by IDVENTEDETAIL
;
-- [74/1309] AS_BLCF_VENTE_RESTE
CREATE OR REPLACE FORCE VIEW "AS_BLCF_VENTE_RESTE" ("ID","IDPRODUIT","QUANTITE","IDVENTEDETAIL","UNITE","IDBC_FILLE") AS
SELECT 
v.id,
v.idproduit,
v.qte -nvl(b.quantite,0) AS quantite,
v.id AS idventedetail,
NULL AS unite,
NULL AS idbc_fille 
FROM VENTE_DETAILS v
LEFT JOIN blcf_grpventedet b ON  b.idventedetail=v.ID
;
-- [75/1309] BLCLIENT_FILLE_GRP
CREATE OR REPLACE FORCE VIEW "BLCLIENT_FILLE_GRP" ("IDBC_FILLE","IDBC","QUANTITE","PRODUIT","NUMBL","IDVENTEDETAIL","UNITE") AS
SELECT 
abcf.IDBC_FILLE ,
bcf.IDBC,
nvl(sum(abcf.QUANTITE),0) AS QUANTITE,
abcf.PRODUIT,
abcf.NUMBL,
abcf.IDVENTEDETAIL,
abcf.UNITE
FROM AS_BONDELIVRAISON_CLIENT_FILLE abcf 
LEFT JOIN BONDECOMMANDE_CLIENT_FILLE bcf ON bcf.id = abcf.IDBC_FILLE
GROUP BY abcf.IDBC_FILLE,bcf.IDBC,abcf.PRODUIT,abcf.NUMBL,abcf.IDVENTEDETAIL,abcf.UNITE
;
-- [76/1309] AS_BL_CLIENTFILLE_BC_RESTE
CREATE OR REPLACE FORCE VIEW "AS_BL_CLIENTFILLE_BC_RESTE" ("ID","PRODUIT","NUMBL","QUANTITE","IDVENTEDETAIL","UNITE") AS
SELECT 
bc.ID,
b.PRODUIT,
b.NUMBL,
nvl((bc.QUANTITE - b.QUANTITE),0) AS QUANTITE,
b.IDVENTEDETAIL,
b.UNITE
FROM BCClient_Fille_GRP bc 
JOIN BLClient_Fille_GRP b ON b.IDBC = bc.ID
;
-- [77/1309] BLGROUPBYIDBC
CREATE OR REPLACE FORCE VIEW "BLGROUPBYIDBC" ("IDBC_FILLE","QUANTITE") AS
SELECT 
    f.IDBC_FILLE,
    SUM(f.QUANTITE) AS quantite
FROM AS_BONDELIVRAISON_CLIENT_FILLE f
LEFT JOIN AS_BONDELIVRAISON_CLIENT m ON m.ID = f.NUMBL
WHERE m.ETAT >= 11
GROUP BY f.IDBC_FILLE
;
-- [78/1309] BL_CLIENT_FILLE_BC
CREATE OR REPLACE FORCE VIEW "BL_CLIENT_FILLE_BC" ("ID","IDBC","PRODUIT","IDPRODUIT","QUANTITE","DATY") AS
SELECT
	ABCF.id,
	ABC.IDBC ,
	pl.LIBELLE AS PRODUIT,
	ABCF.PRODUIT AS IDPRODUIT,
	ABCF.QUANTITE ,
	ABC.DATY 
 FROM AS_BONDELIVRAISON_CLIENT_FILLE abcf 
	JOIN BONDECOMMANDE_CLIENT_FILLE bcfc ON BCFC.ID = ABCF.IDBC_FILLE 
	JOIN AS_BONDELIVRAISON_CLIENT abc ON abc.ID = ABCF.NUMBL 
	JOIN AS_INGREDIENTS pl ON pl.ID = ABCF.PRODUIT
;
-- [79/1309] BL_CLIENT_FILLE_GRP_BC
CREATE OR REPLACE FORCE VIEW "BL_CLIENT_FILLE_GRP_BC" ("IDBC_FILLE","QUANTITE") AS
SELECT
    IDBC_FILLE,
    SUM(QUANTITE) AS QUANTITE
FROM
    AS_BONDELIVRAISON_CLIENT_FILLE abcf
        left join BONDECOMMANDE_CLIENT b on b.id=abcf.NUMBL
        left join AS_BONDELIVRAISON_CLIENT abc on abc.ID = NUMBL
where abc.ETAT =11
GROUP BY IDBC_FILLE
;
-- [80/1309] BC_DETAILS_RESTE
CREATE OR REPLACE FORCE VIEW "BC_DETAILS_RESTE" ("ID","PRODUIT","UNITE","QUANTITE","RESTE","IDBC") AS
SELECT 
bcf.id AS id,
bcf.produit,
bcf.UNITE AS unite,
bcf.QUANTITE  AS QUANTITE,
nvl(bcf.QUANTITE,0) - nvl(bl.QUANTITE,0) AS reste,
bcf.IDBC AS IDBC
FROM 
BONDECOMMANDE_CLIENT_FILLE bcf LEFT JOIN 
BL_CLIENT_FILLE_grp_bc bl ON bcf.ID = bl.idbc_fille
;
-- [81/1309] BL_CLIENT_FILLE_GRP_VENTE
CREATE OR REPLACE FORCE VIEW "BL_CLIENT_FILLE_GRP_VENTE" ("IDVENTEDETAIL","QUANTITE") AS
SELECT IDVENTEDETAIL,
       SUM(QUANTITE) AS QUANTITE
FROM AS_BONDELIVRAISON_CLIENT_FILLE abcf
GROUP BY IDVENTEDETAIL
;
-- [82/1309] BL_QTELIVREE_BY_IDBCFILLE
CREATE OR REPLACE FORCE VIEW "BL_QTELIVREE_BY_IDBCFILLE" ("IDBC_FILLE","QUANTITE_LIVREE") AS
SELECT
  IDBC_FILLE,
  SUM(QUANTITE) AS QUANTITE_LIVREE
FROM AS_BONDELIVRAISON_CLIENT_FILLE
GROUP BY IDBC_FILLE
;
-- [83/1309] BONCOMMANDEDETAILSCARTON_CPL
CREATE OR REPLACE FORCE VIEW "BONCOMMANDEDETAILSCARTON_CPL" ("ID","IDBC","PRODUITLIB","PRODUIT","QUANTITEBF","QUANTITECF","RESTECF") AS
SELECT 
bc.ID ,
bc.idbc AS idbc ,
ai.LIBELLE AS produitlib,
ai.id AS produit,
nvl(bc.QUANTITE,0) AS quantitebf ,
nvl(c.QUANTITE,0) AS quantitecf,
nvl(bc.QUANTITE,0) - nvl(c.QUANTITE,0) AS restecf
FROM BONDECOMMANDE_CLIENT_FILLE bc 
LEFT JOIN CARTONFILLE c  ON c.IDBCFILLE = bc.ID 
LEFT JOIN AS_INGREDIENTS ai ON ai.ID = bc.PRODUIT
GROUP BY bc.ID, bc.idbc, ai.LIBELLE, ai.id, bc.QUANTITE, c.QUANTITE
;
-- [84/1309] BONCOMMANDEFABDETAILS
CREATE OR REPLACE FORCE VIEW "BONCOMMANDEFABDETAILS" ("IDINGREDIENTS","LIBELLEEXTACTE","IDBC","QTE","IDFABRICATION") AS
SELECT
	fl.IDINGREDIENTS ,
	i.LIBELLE,
	bc.ID,
	sum(fl.QTE) qte,
	fl.IDMERE AS IDFABRICATION
FROM FABRICATIONFILLE fl
LEFT JOIN BONDECOMMANDE_CLIENT_FILLE bcf ON bcf.ID = fl.IDBCFILLE
LEFT JOIN BONDECOMMANDE_CLIENT bc ON bc.ID = bcf.IDBC
LEFT JOIN FABRICATION f
ON f.ID = fl.IDMERE
JOIN AS_INGREDIENTS i
ON fl.IDINGREDIENTS = i.ID
WHERE f.ETAT >= 11
GROUP BY fl.IDINGREDIENTS ,i.LIBELLE,bc.ID, fl.IDMERE
;
-- [85/1309] BONDECOMMANDEFACTURER
CREATE OR REPLACE FORCE VIEW "BONDECOMMANDEFACTURER" ("PRODUIT","QUANTITE","IDPROFORMA") AS
select PRODUIT,sum(bcf.QUANTITE) - sum(vdf.QTE) as quantite, bc.IDPROFORMA from bondecommande_client_fille bcf join VENTE_DETAILS vdf ON bcf.id = vdf.idbcfille join vente v on v.id=vdf.IDVENTE join BONDECOMMANDE_CLIENT bc on bc.ID=bcf.IDBC where v.ETAT>=11 group by PRODUIT, bc.IDPROFORMA
;
-- [86/1309] BONDECOMMANDE_CLIENT_FILLE_V
CREATE OR REPLACE FORCE VIEW "BONDECOMMANDE_CLIENT_FILLE_V" ("ID","PRODUIT","IDBC","QUANTITE","PU","MONTANT","TVA","REMISE","IDDEVISE","UNITE","DESIGNATION","UNITELIB","PUNET","MONTANTHT","MONTANTTTC","RISTOURNE","CALORIE","RISTOURNEARBIOCHEM","REMISEARBIOCHEM") AS
select p.ID,
       p.PRODUIT,
       p.IDBC,
       p.QUANTITE,
       p.PU,
       p.MONTANT,
       p.TVA,
       p.REMISE,
       p.IDDEVISE,
       p.UNITE,
       p.DESIGNATION,
       uni.val as unitelib,
       0  as punet,
       0  as montantht,
       0  as montantttc,
       p.RISTOURNE,
       ing.calorie,
       p.ristourneArbiochem,
       p.remiseArbiochem
from BONDECOMMANDE_CLIENT_FILLE p
         LEFT JOIN as_unite uni ON p.unite = uni.id
         LEFT JOIN  AS_INGREDIENTS ing ON p.PRODUIT = ing.ID
;
-- [87/1309] BONDECOMMANDE_OFDETAILS
CREATE OR REPLACE FORCE VIEW "BONDECOMMANDE_OFDETAILS" ("IDINGREDIENTS","LIBELLEEXACTE","IDBC","QTE","DATY") AS
SELECT off.IDINGREDIENTS,i.LIBELLEEXTACTE,bc.IDBC, sum(off.QTE) qte, o.DATY  FROM 
OFFILLE off 
LEFT JOIN BONDECOMMANDE_CLIENT_FILLE bc 
ON bc.ID = off.IDBCFILLE 
LEFT JOIN OFAB o 
ON o.ID = off.IDMERE 
JOIN AS_INGREDIENTS i
ON off.IDINGREDIENTS = i.ID 
WHERE o.ETAT >= 11
GROUP BY off.IDINGREDIENTS,i.LIBELLEEXTACTE,bc.IDBC,o.DATY
;
-- [88/1309] CAISSEBANQUE
CREATE OR REPLACE FORCE VIEW "CAISSEBANQUE" ("ID","VAL","DESCE") AS
SELECT id,
       val,
       desce
FROM CAISSE
WHERE IDTYPECAISSE = 'TCA001'
    AND actif = 1
   OR id = 'CAIS001'
;
-- [89/1309] CAISSECPL
CREATE OR REPLACE FORCE VIEW "CAISSECPL" ("ID","VAL","DESCE","IDTYPECAISSE","IDTYPECAISSELIB","IDPOINT","IDPOINTLIB","IDPOMPISTE","ETAT","COMPTE","ETATLIB","IDCATEGORIECAISSE","IDCATEGORIECAISSELIB","IDMAGASIN","IDMAGASINLIB","MOTSCLESSS") AS
SELECT SQ.ID,SQ.VAL,SQ.DESCE,SQ.IDTYPECAISSE,SQ.IDTYPECAISSELIB,SQ.IDPOINT,SQ.IDPOINTLIB,SQ.IDPOMPISTE,SQ.ETAT,SQ.COMPTE,SQ.ETATLIB,SQ.IDCATEGORIECAISSE,SQ.IDCATEGORIECAISSELIB,SQ.IDMAGASIN,SQ.IDMAGASINLIB,
	       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(VAL),'') || ' | ' || NVL(TO_CHAR(DESCE),'') || ' | ' || NVL(TO_CHAR(IDTYPECAISSE),'') || ' | ' || NVL(TO_CHAR(IDTYPECAISSELIB),'') || ' | ' || NVL(TO_CHAR(IDPOINT),'') || ' | ' || NVL(TO_CHAR(IDPOINTLIB),'') || ' | ' || NVL(TO_CHAR(IDPOMPISTE),'') || ' | ' || NVL(TO_CHAR(ETAT),'') || ' | ' || NVL(TO_CHAR(COMPTE),'') || ' | ' || NVL(TO_CHAR(ETATLIB),'') || ' | ' || NVL(TO_CHAR(IDCATEGORIECAISSE),'') || ' | ' || NVL(TO_CHAR(IDCATEGORIECAISSELIB),'') || ' | ' || NVL(TO_CHAR(IDMAGASIN),'') || ' | ' || NVL(TO_CHAR(IDMAGASINLIB),'')) AS MOTSCLESSS
	FROM (
	         SELECT c.ID,
	                c.VAL,
	                c.DESCE,
	                c.IDTYPECAISSE,
	                t.VAL   AS IDTYPECAISSELIB,
	                c.IDPOINT,
	                p.VAL   AS IDPOINTLIB,
	                c.IDPOMPISTE,
	                c.ETAT,
	                cop.LIBELLE||'('||cop.COMPTE||')' as compte ,
	                CASE
	                    WHEN c.ETAT = 0
	                        THEN 'ANNUL&Eacute;'
	                    WHEN c.ETAT = 1
	                        THEN 'CR&Eacute;&Eacute;'
	                    WHEN c.ETAT = 11
	                        THEN 'VIS&Eacute;'
	                    END AS ETATLIB,
	                c.idCategorieCaisse,
	                c2.VAL  AS idCategorieCaisseLib,
	                c.IDMAGASIN ,
	                m.val AS idMagasinLib
	         FROM CAISSE c
	                  LEFT JOIN TYPECAISSE t ON t.ID = c.IDTYPECAISSE
	                  LEFT JOIN POINT p ON p.ID = c.IDPOINT
	                  LEFT JOIN CATEGORIECAISSE c2 ON c2.ID = c.idCategorieCaisse
	                  LEFT JOIN COMPTA_COMPTE cop ON cop.COMPTE = c.COMPTE
	                  LEFT JOIN MAGASIN2 m ON m.ID =c.IDMAGASIN
	
	
	     ) SQ
;
-- [90/1309] CAISSETRAITE
CREATE OR REPLACE FORCE VIEW "CAISSETRAITE" ("ID","VAL","DESCE") AS
select ID,VAL,DESCE from caisse where id = 'CAIS00000T00016'
;
-- [91/1309] CAISSE_POMPISTE
CREATE OR REPLACE FORCE VIEW "CAISSE_POMPISTE" ("ID","VAL","DESCE","IDTYPECAISSE","IDTYPECAISSELIB","IDPOINT","IDPOINTLIB","IDPOMPISTE","ETAT","ETATLIB","IDCATEGORIECAISSE","IDCATEGORIECAISSELIB") AS
SELECT 
c.ID ,
c.VAL ,
c.DESCE ,
c.IDTYPECAISSE ,
t.VAL AS IDTYPECAISSELIB,
c.IDPOINT ,
p.VAL AS IDPOINTLIB,
c.IDPOMPISTE ,
c.ETAT ,
CASE 
	WHEN c.ETAT  = 0 
	THEN 'ANNULEE'
	WHEN c.ETAT  = 1 
	THEN 'CREE'
	WHEN c.ETAT  = 11
	THEN 'VISEE'
END AS ETATLIB,
c.idCategorieCaisse,
c2.VAL AS idCategorieCaisseLib
FROM CAISSE c 
LEFT JOIN TYPECAISSE t ON t.ID = c.IDTYPECAISSE 
LEFT JOIN POINT p ON p.ID = c.IDPOINT 
LEFT JOIN CATEGORIECAISSE c2 ON c2.ID = c.idCategorieCaisse
WHERE c.IDPOMPISTE IS NOT NULL
;
-- [92/1309] CANDIDATURESLIB
CREATE OR REPLACE FORCE VIEW "CANDIDATURESLIB" ("ID","IDCANDIDAT","IDCANDIDATLIB","IDOFFREEMPLOIE","IDOFFREEMPLOIELIB","ETAT","ETATLIB","DATEAPPLICATION","REMARQUE","RAISONREFUS") AS
SELECT
    c.id,
    c.idCandidat,
    (ca.nom || ' ' || ca.prenom) AS idCandidatlib,
    c.idOffreEmploie,
    o.titre AS idOffreEmploielib,
    c.etat,
    CASE
        WHEN c.etat = 1 THEN 'Creee'
        WHEN c.etat = 11 THEN 'Validee'
        WHEN c.etat = 13 THEN 'Embauchee'
        WHEN c.etat = -1 THEN 'Refuser'
        ELSE 'Inconnu'
        END AS etatlib,
    c.dateApplication,
    c.remarque,
    c.raisonRefus
FROM candidatures c
         LEFT JOIN candidat ca
                   ON c.idCandidat = ca.id
         LEFT JOIN offre_emploi o
                   ON c.idOffreEmploie = o.id
;
-- [93/1309] CARTONFILLE_CPL
CREATE OR REPLACE FORCE VIEW "CARTONFILLE_CPL" ("ID","IDMERE","IDINGREDIENT","QUANTITE","REMARQUE","IDBCFILLE","PRODUITLIB","IDBC") AS
select cf.ID,
 		cf.IDMERE,
 		cf.IDINGREDIENT,
 		cf.QUANTITE,
 		cf.REMARQUE,
 		cf.IDBCFILLE,
 		ai.libelle AS PRODUITLIB,
		c.IDBC AS IDBC
       from CARTONFILLE cf 
   LEFT JOIN AS_INGREDIENTS ai ON cf.IDINGREDIENT = ai.ID
   LEFT JOIN CARTON c ON cf.IDMERE = c.ID
;
-- [94/1309] CATEGORIEINGREDIENTLIB
CREATE OR REPLACE FORCE VIEW "CATEGORIEINGREDIENTLIB" ("ID","VAL","DESCE") AS
select cat.id,cat.val,ti.val as DESCE from CATEGORIEINGREDIENT cat
left join typeCATEGORIEINGREDIENT ti on cat.DESCE=ti.id
;
-- [95/1309] AS_INGREDIENTS_LIB
CREATE OR REPLACE FORCE VIEW "AS_INGREDIENTS_LIB" ("ID","LIBELLE","PARFUMS","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","COMPOSELIB","IDCATEGORIEINGREDIENT","CATEGORIEINGREDIENT","IDCATEGORIE","IDFOURNISSEUR","DATY","BIENOUSERV","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT","PV","TVA","TYPESTOCK","IDUNITE","REFPOST","REFQUALIFICATION","REFPOSTLIB","REFQUALIFICATIONLIB","IDFAMILLELIB","TYPEPRODUIT","IDLIGNE","COMPTE_STOCK","COMPTE_SORTIE_STOCK","IDFOURNISSEURLIB","IDDEPARTEMENTLIB","LIBELLEVENTE","NBPIECE","TYPEPRODUITLIB","COMPTE_RISTOURNE","ISACHAT") AS
SELECT ing.id,
       ing.LIBELLE,
       ing.PARFUMS,
       CAST(ing.SEUIL AS NUMBER(10,5)) AS SEUIL ,
       au.VAL AS unite,
       CAST(ing.QUANTITEPARPACK AS NUMBER(10,5)) AS QUANTITEPARPACK,
       CAST(ing.pu AS NUMBER(30,5)) AS pu,
       ing.ACTIF,
       ing.PHOTO,
       ing.CALORIE,
       ing.DURRE,
       ing.COMPOSE,
       CAST(
               CASE
                   WHEN ing.COMPOSE = 1 THEN 'OUI'
                   WHEN ing.COMPOSE = 0 THEN 'NON'
                   END AS VARCHAR2(100)
       ) AS COMPOSELIB,
       cating.id AS IDCATEGORIEINGREDIENT ,
       catIng.VAL AS CATEGORIEINGREDIENT,
       ing.CATEGORIEINGREDIENT AS idcategorie,
       ing.idfournisseur,
       ing.daty,
       catIng.desce as bienOuServ,
       CASE WHEN ing.id IN (SELECT idproduit FROM INDISPONIBILITE i )
                THEN 'INDISPONIBLE'
            WHEN ing.id NOT IN (SELECT idproduit FROM INDISPONIBILITE i )
                THEN 'DISPONIBLE'
           END AS etatlib,
       ing.COMPTE_VENTE,
       ing.COMPTE_ACHAT,
       CAST(ing.pv AS NUMBER(30,5)) AS pv,
       CAST(ing.tva AS NUMBER(10,5)) AS tva,
       ing.TYPESTOCK,
       ing.UNITE as idunite,
       ing.REFPOST,
       ing.REFQUALIFICATION ,
       p.VAL AS REFPOSTLIB,
       qp.VAL AS REFQUALIFICATIONLIB,
       fp.val AS idfamilleLib,
       ing.typeProduit,
       tp.idligne,
       ing.compte_stock,
       ing.compte_sortie_stock,
       f.nom as idFournisseurLib,
       dep.val AS idDepartementLib,
       nvl(ing.LIBELLEVENTE,ing.libelle) as LIBELLEVENTE,
       eq.QUANTITE as nbpiece,
       tp.val AS typeproduitLib,
       ing.COMPTE_RISTOURNE,
       ing.isAchat
FROM as_ingredients ing
         LEFT JOIN AS_UNITE AU ON ing.UNITE = AU.ID
         LEFT JOIN CATEGORIEINGREDIENTLIB catIng
                   ON catIng.id = ing.CATEGORIEINGREDIENT
         LEFT JOIN POSTE p ON p.id = ing.REFPOST
         LEFT JOIN FAMILLEPRODUIT fp ON fp.id=ing.idfamille
         LEFT JOIN QUALIFICATION_PAIE qp ON qp.id = ing.REFQUALIFICATION
         LEFT JOIN TYPE_PRODUIT tp ON tp.ID=ing.typeProduit
         LEFT JOIN FOURNISSEUR f ON ing.idFournisseur = f.id
         LEFT JOIN departement dep ON dep.id=ing.parfums
         Left join EQUIVALENCEVENTE eq on eq.IDPRODUIT1 = ing.ID
;
-- [96/1309] AS_INGREDIENTS_LIB2
CREATE OR REPLACE FORCE VIEW "AS_INGREDIENTS_LIB2" ("ID","LIBELLE","PARFUMS","SEUIL","UNITELIB","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","COMPOSELIB","IDCATEGORIEINGREDIENT","CATEGORIEINGREDIENT","IDCATEGORIE","IDFOURNISSEUR","DATY","BIENOUSERV","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT","PV","TVA","TYPESTOCK","UNITE","REFPOST","REFQUALIFICATION","REFPOSTLIB","REFQUALIFICATIONLIB") AS
SELECT ing.id,
       concat(concat(ing.LIBELLE,' '),ing.PARFUMS) as LIBELLE,
       ing.PARFUMS,
       ing.SEUIL,
       au.VAL AS unitelib,
       ing.QUANTITEPARPACK,
       ing.pu,
       ing.ACTIF,
       ing.PHOTO,
       ing.CALORIE,
       ing.DURRE,
       ing.COMPOSE,
       CAST(
               CASE
                   WHEN ing.COMPOSE = 1 THEN 'OUI'
                   WHEN ing.COMPOSE = 0 THEN 'NON'
                   END AS VARCHAR2(100)
       ) AS COMPOSELIB,
       cating.id AS IDCATEGORIEINGREDIENT ,
       catIng.VAL AS CATEGORIEINGREDIENT,
       ing.CATEGORIEINGREDIENT AS idcategorie,
       ing.idfournisseur,
       ing.daty,
       catIng.desce as bienOuServ,
       CASE WHEN ing.id IN (SELECT idproduit FROM INDISPONIBILITE i )
                THEN 'INDISPONIBLE'
            WHEN ing.id NOT IN (SELECT idproduit FROM INDISPONIBILITE i )
                THEN 'DISPONIBLE'
           END AS etatlib,
       ing.COMPTE_VENTE,
       ing.COMPTE_ACHAT,
       ing.pv,
       ing.tva,
       ing.TYPESTOCK,
       ing.UNITE as unite,
       ing.REFPOST,
       ing.REFQUALIFICATION ,
       p.VAL AS REFPOSTLIB,
       qp.VAL AS REFQUALIFICATIONLIB
FROM as_ingredients ing
         LEFT JOIN AS_UNITE AU ON ing.UNITE = AU.ID
         LEFT JOIN CATEGORIEINGREDIENTLIB catIng
                   ON catIng.id = ing.CATEGORIEINGREDIENT
         LEFT JOIN POSTE p ON p.id = ing.REFPOST
         LEFT JOIN QUALIFICATION_PAIE qp ON qp.id = ing.REFQUALIFICATION
;
-- [97/1309] AS_INGREDIENTS_LIB_ACHAT
CREATE OR REPLACE FORCE VIEW "AS_INGREDIENTS_LIB_ACHAT" ("ID","LIBELLE","PARFUMS","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","COMPOSELIB","IDCATEGORIEINGREDIENT","CATEGORIEINGREDIENT","IDCATEGORIE","IDFOURNISSEUR","DATY","BIENOUSERV","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT","PV","TVA","TYPESTOCK","IDUNITE","REFPOST","REFQUALIFICATION","REFPOSTLIB","REFQUALIFICATIONLIB","IDFAMILLELIB","TYPEPRODUIT","IDLIGNE","COMPTE_STOCK","COMPTE_SORTIE_STOCK","IDFOURNISSEURLIB","IDDEPARTEMENTLIB","LIBELLEVENTE","NBPIECE","TYPEPRODUITLIB","COMPTE_RISTOURNE","ISACHAT") AS
SELECT "ID","LIBELLE","PARFUMS","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","COMPOSELIB","IDCATEGORIEINGREDIENT","CATEGORIEINGREDIENT","IDCATEGORIE","IDFOURNISSEUR","DATY","BIENOUSERV","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT","PV","TVA","TYPESTOCK","IDUNITE","REFPOST","REFQUALIFICATION","REFPOSTLIB","REFQUALIFICATIONLIB","IDFAMILLELIB","TYPEPRODUIT","IDLIGNE","COMPTE_STOCK","COMPTE_SORTIE_STOCK","IDFOURNISSEURLIB","IDDEPARTEMENTLIB","LIBELLEVENTE","NBPIECE","TYPEPRODUITLIB","COMPTE_RISTOURNE","ISACHAT" FROM AS_INGREDIENTS_LIB ail WHERE ail.isAchat = 1 AND ail.actif = 1
;
-- [98/1309] AS_INGREDIENTS_LIB_PIECE
CREATE OR REPLACE FORCE VIEW "AS_INGREDIENTS_LIB_PIECE" ("ID","LIBELLE","PARFUMS","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","COMPOSELIB","IDCATEGORIEINGREDIENT","CATEGORIEINGREDIENT","IDCATEGORIE","IDFOURNISSEUR","DATY","BIENOUSERV","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT","PV","TVA","TYPESTOCK","IDUNITE","REFPOST","REFQUALIFICATION","REFPOSTLIB","REFQUALIFICATIONLIB","IDFAMILLELIB","TYPEPRODUIT","IDLIGNE","COMPTE_STOCK","COMPTE_SORTIE_STOCK","IDFOURNISSEURLIB","MOTSCLESSS") AS
SELECT SQ.ID,SQ.LIBELLE,SQ.PARFUMS,SQ.SEUIL,SQ.UNITE,SQ.QUANTITEPARPACK,SQ.PU,SQ.ACTIF,SQ.PHOTO,SQ.CALORIE,SQ.DURRE,SQ.COMPOSE,SQ.COMPOSELIB,SQ.IDCATEGORIEINGREDIENT,SQ.CATEGORIEINGREDIENT,SQ.IDCATEGORIE,SQ.IDFOURNISSEUR,SQ.DATY,SQ.BIENOUSERV,SQ.ETATLIB,SQ.COMPTE_VENTE,SQ.COMPTE_ACHAT,SQ.PV,SQ.TVA,SQ.TYPESTOCK,SQ.IDUNITE,SQ.REFPOST,SQ.REFQUALIFICATION,SQ.REFPOSTLIB,SQ.REFQUALIFICATIONLIB,SQ.IDFAMILLELIB,SQ.TYPEPRODUIT,SQ.IDLIGNE,SQ.COMPTE_STOCK,SQ.COMPTE_SORTIE_STOCK,SQ.IDFOURNISSEURLIB,
	       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(LIBELLE),'') || ' | ' || NVL(TO_CHAR(PARFUMS),'') || ' | ' || NVL(TO_CHAR(SEUIL),'') || ' | ' || NVL(TO_CHAR(UNITE),'') || ' | ' || NVL(TO_CHAR(QUANTITEPARPACK),'') || ' | ' || NVL(TO_CHAR(PU),'') || ' | ' || NVL(TO_CHAR(ACTIF),'') || ' | ' || NVL(TO_CHAR(PHOTO),'') || ' | ' || NVL(TO_CHAR(CALORIE),'') || ' | ' || NVL(TO_CHAR(DURRE),'') || ' | ' || NVL(TO_CHAR(COMPOSE),'') || ' | ' || NVL(TO_CHAR(COMPOSELIB),'') || ' | ' || NVL(TO_CHAR(IDCATEGORIEINGREDIENT),'') || ' | ' || NVL(TO_CHAR(CATEGORIEINGREDIENT),'') || ' | ' || NVL(TO_CHAR(IDCATEGORIE),'') || ' | ' || NVL(TO_CHAR(IDFOURNISSEUR),'') || ' | ' || NVL(TO_CHAR(DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(BIENOUSERV),'') || ' | ' || NVL(TO_CHAR(ETATLIB),'') || ' | ' || NVL(TO_CHAR(COMPTE_VENTE),'') || ' | ' || NVL(TO_CHAR(COMPTE_ACHAT),'') || ' | ' || NVL(TO_CHAR(PV),'') || ' | ' || NVL(TO_CHAR(TVA),'') || ' | ' || NVL(TO_CHAR(TYPESTOCK),'') || ' | ' || NVL(TO_CHAR(IDUNITE),'') || ' | ' || NVL(TO_CHAR(REFPOST),'') || ' | ' || NVL(TO_CHAR(REFQUALIFICATION),'') || ' | ' || NVL(TO_CHAR(REFPOSTLIB),'') || ' | ' || NVL(TO_CHAR(REFQUALIFICATIONLIB),'') || ' | ' || NVL(TO_CHAR(IDFAMILLELIB),'') || ' | ' || NVL(TO_CHAR(TYPEPRODUIT),'') || ' | ' || NVL(TO_CHAR(IDLIGNE),'') || ' | ' || NVL(TO_CHAR(COMPTE_STOCK),'') || ' | ' || NVL(TO_CHAR(COMPTE_SORTIE_STOCK),'') || ' | ' || NVL(TO_CHAR(IDFOURNISSEURLIB),'')) AS MOTSCLESSS
	FROM (
	         SELECT ing.id,
	                ing.LIBELLE,
	                ing.PARFUMS,
	                ing.SEUIL,
	                au.VAL AS unite,
	                ing.QUANTITEPARPACK,
	                ing.pu,
	                ing.ACTIF,
	                ing.PHOTO,
	                ing.CALORIE,
	                ing.DURRE,
	                ing.COMPOSE,
	                CAST(
	                        CASE
	                            WHEN ing.COMPOSE = 1 THEN 'OUI'
	                            WHEN ing.COMPOSE = 0 THEN 'NON'
	                            END AS VARCHAR2(100)
	                ) AS COMPOSELIB,
	                cating.id AS IDCATEGORIEINGREDIENT ,
	                catIng.VAL AS CATEGORIEINGREDIENT,
	                ing.CATEGORIEINGREDIENT AS idcategorie,
	                ing.idfournisseur,
	                ing.daty,
	                catIng.desce as bienOuServ,
	                CASE WHEN ing.id IN (SELECT idproduit FROM INDISPONIBILITE i )
	                         THEN 'INDISPONIBLE'
	                     WHEN ing.id NOT IN (SELECT idproduit FROM INDISPONIBILITE i )
	                         THEN 'DISPONIBLE'
	                    END AS etatlib,
	                ing.COMPTE_VENTE,
	                ing.COMPTE_ACHAT,
	                ing.pv,
	                ing.tva,
	                ing.TYPESTOCK,
	                ing.UNITE as idunite,
	                ing.REFPOST,
	                ing.REFQUALIFICATION ,
	                p.VAL AS REFPOSTLIB,
	                qp.VAL AS REFQUALIFICATIONLIB,
	                fp.val AS idfamilleLib,
	                ing.typeProduit,
	                tp.idligne,
	                ing.compte_stock,
	                ing.compte_sortie_stock,
	                f.nom as idFournisseurLib
	         FROM as_ingredients ing
	                  LEFT JOIN AS_UNITE AU ON ing.UNITE = AU.ID
	                  LEFT JOIN CATEGORIEINGREDIENTLIB catIng
	                            ON catIng.id = ing.CATEGORIEINGREDIENT
	                  LEFT JOIN POSTE p ON p.id = ing.REFPOST
	                  LEFT JOIN FAMILLEPRODUIT fp ON fp.id=ing.idfamille
	                  LEFT JOIN QUALIFICATION_PAIE qp ON qp.id = ing.REFQUALIFICATION
	                  LEFT JOIN TYPE_PRODUIT tp ON tp.ID=ing.typeProduit
	                  LEFT JOIN FOURNISSEUR f ON ing.idFournisseur = f.id
	                  LEFT JOIN AS_INGREDIENT_MAINTENANCE aim ON aim.IDINGREDIENT=ing.id
	         WHERE aim.IDINGREDIENT IS NOT NULL AND aim.identite='ENT000004'
	     ) SQ
;
-- [99/1309] AS_INGREDIENTS_PRODUIT_FINIE
CREATE OR REPLACE FORCE VIEW "AS_INGREDIENTS_PRODUIT_FINIE" ("ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","IDCATEGORIEINGREDIENT","CATEGORIEINGREDIENT","IDCATEGORIE","IDFOURNISSEUR","DATY","BIENOUSERV","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT","PV","TVA","TYPESTOCK","IDUNITE","REFPOST","REFQUALIFICATION") AS
SELECT 
  	   ing.id,
       ing.LIBELLE,
       ing.SEUIL,
       au.VAL AS unite,
       ing.QUANTITEPARPACK,
       ing.pu,
       ing.ACTIF,
       ing.PHOTO,
       ing.CALORIE,
       ing.DURRE,
       ing.COMPOSE,
       cating.id AS IDCATEGORIEINGREDIENT ,
       catIng.VAL AS CATEGORIEINGREDIENT,
       ing.CATEGORIEINGREDIENT AS idcategorie,
       ing.idfournisseur,
       ing.daty,
       catIng.desce as bienOuServ,
       CASE WHEN ing.id IN (SELECT idproduit FROM INDISPONIBILITE i )
                THEN 'INDISPONIBLE'
            WHEN ing.id NOT IN (SELECT idproduit FROM INDISPONIBILITE i )
                THEN 'DISPONIBLE'
           END AS etatlib,
       ing.COMPTE_VENTE,
       ing.COMPTE_ACHAT,
       ing.pv,
       ing.tva,
       ing.TYPESTOCK,
       ing.UNITE as idunite,
       ing.REFPOST,
       ing.REFQUALIFICATION 
FROM as_ingredients ing
     JOIN AS_UNITE AU 
     ON ing.UNITE = AU.ID
     JOIN CATEGORIEINGREDIENTLIB catIng
     ON catIng.id = ing.CATEGORIEINGREDIENT
WHERE ing.CATEGORIEINGREDIENT in ('CAT008','CAT001')
;
-- [100/1309] AS_MACHINE
CREATE OR REPLACE FORCE VIEW "AS_MACHINE" ("ID","LIBELLE","PARFUMS","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","COMPOSELIB","IDCATEGORIEINGREDIENT","CATEGORIEINGREDIENT","IDCATEGORIE","IDFOURNISSEUR","DATY","BIENOUSERV","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT","PV","TVA","TYPESTOCK","IDUNITE","REFPOST","REFQUALIFICATION","REFPOSTLIB","REFQUALIFICATIONLIB","IDFAMILLELIB") AS
SELECT "ID","LIBELLE","PARFUMS","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","COMPOSELIB","IDCATEGORIEINGREDIENT","CATEGORIEINGREDIENT","IDCATEGORIE","IDFOURNISSEUR","DATY","BIENOUSERV","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT","PV","TVA","TYPESTOCK","IDUNITE","REFPOST","REFQUALIFICATION","REFPOSTLIB","REFQUALIFICATIONLIB","IDFAMILLELIB" FROM AS_INGREDIENTS_LIB ai WHERE ai.IDCATEGORIEINGREDIENT = 'CAT005'
;
-- [101/1309] AS_RECETTEFABLIB
CREATE OR REPLACE FORCE VIEW "AS_RECETTEFABLIB" ("ID","IDINGREDIENTS","UNITE","QTEAV","QUANTITE","IDPRODUITS","LIBINGREDIENTS","TYPESTOCK","CATEGORIEINGREDIENT","PU","CATEGORIEINGREDIENTLIB") AS
select 
	arf.ID,
	arf.IDINGREDIENTS,
	arf.UNITE,
	arf.QTEAV,
	arf.QUANTITE,
	arf.IDPRODUITS,
	i.LIBELLE ||' ('||u.VAL||')' as libIngredients,
	i.TYPESTOCK,
	i.CATEGORIEINGREDIENT,
	i.pu,
	cat.val AS CATEGORIEINGREDIENTLIB
from as_recettefabrication arf
left join AS_INGREDIENTS i 
on arf.idingredients=i.id
LEFT JOIN CATEGORIEINGREDIENT cat 
ON cat.id=i.CATEGORIEINGREDIENT  
left join AS_UNITE u on i.UNITE=u.ID
;
-- [102/1309] AS_RECETTEFABLIBSERVICE
CREATE OR REPLACE FORCE VIEW "AS_RECETTEFABLIBSERVICE" ("ID","IDINGREDIENTS","UNITE","QTEAV","QUANTITE","IDPRODUITS","LIBINGREDIENTS","TYPESTOCK","CATEGORIEINGREDIENT") AS
SELECT ID,IDINGREDIENTS,UNITE,QTEAV,QUANTITE,IDPRODUITS,LIBINGREDIENTS,TYPESTOCK,categorieingredient FROM As_recetteFabLib WHERE TYPESTOCK IS NULL AND UNITE = 'UNT003' AND CATEGORIEINGREDIENT!='CAT002'
;
-- [103/1309] AS_RECFABLIBGROUPE
CREATE OR REPLACE FORCE VIEW "AS_RECFABLIBGROUPE" ("IDPRODUITS","IDINGREDIENTS","UNITE","QUANTITE","QTEAV","PU","LIBINGREDIENTS","CATEGORIEINGREDIENT") AS
select a.IDPRODUITS,a.idingredients,max(a.unite) as unite,sum(quantite) as quantite, avg(a.qteav) as qteav,avg(a.pu) AS pu, a.libIngredients,a.categorieingredient
from as_recetteFabLib a group by a.IDPRODUITS, a.idingredients, a.libIngredients,a.categorieingredient
;
-- [104/1309] AS_RECFOFABLIBGROUPE
CREATE OR REPLACE FORCE VIEW "AS_RECFOFABLIBGROUPE" ("IDPRODUITS","IDINGREDIENTS","UNITE","QUANTITE","QTEAV","PU","LIBINGREDIENTS","CATEGORIEINGREDIENT","CATEGORIEINGREDIENTLIB") AS
select 
	fille.IDMERE as IDPRODUITS,
	a.idingredients,
	max(a.unite) as unite,
	sum(quantite) as quantite,
	avg(a.qteav) as qteav,
	CAST(avg(a.pu) AS NUMBER(30,2)) AS pu,
	a.libIngredients,
	a.CATEGORIEINGREDIENT,
	a.CATEGORIEINGREDIENTLIB
from as_recetteFabLib a 
left join fabrication fab on a.IDPRODUITS=fab.ID
left join OFFILLE fille on fab.IDOFFILLE=fille.id
group by fille.idMere, a.idingredients, a.libIngredients, a.CATEGORIEINGREDIENT, a.CATEGORIEINGREDIENTLIB
;
-- [105/1309] CATEGORIEINGREDIENTLIB_ACHT
CREATE OR REPLACE FORCE VIEW "CATEGORIEINGREDIENTLIB_ACHT" ("ID","VAL","DESCE") AS
SELECT
	cat.id,
	cat.val,
	cat.desce
FROM
	CATEGORIEINGREDIENT cat
	WHERE estachat=1
;
-- [106/1309] CATEGORIEINGREDIENT_ACTIF
CREATE OR REPLACE FORCE VIEW "CATEGORIEINGREDIENT_ACTIF" ("ID","VAL","DESCE","ESTACHAT","ACTIF") AS
select "ID","VAL","DESCE","ESTACHAT","ACTIF" from CATEGORIEINGREDIENT where ACTIF=1
;
-- [107/1309] CATEGORIELIB
CREATE OR REPLACE FORCE VIEW "CATEGORIELIB" ("ID","VAL","DESCE","IDTYPEPRODUIT","IDTYPEPRODUITLIB") AS
(
SELECT
	c.ID AS id,
	c.VAL AS VAL,
	c.DESCE AS DESCE,
	c.IDTYPEPRODUIT AS IDTYPEPRODUIT,
	tp.VAL AS IDTYPEPRODUITLIB 
FROM CATEGORIEINGREDIENT c
LEFT JOIN TYPE_PRODUIT tp ON tp.id=c.IDTYPEPRODUIT 
)
;
-- [108/1309] AS_RECETTE_LIB_CAT
CREATE OR REPLACE FORCE VIEW "AS_RECETTE_LIB_CAT" ("ID","IDPRODUITS","IDINGREDIENTS","QUANTITE","UNITE","LIBELLEINGREDIENT","LIBELLEPRODUIT","IDUNITE","VALUNITE","PU","CATEGORIEINGREDIENT","CATEGORIELIB","COMPTE_VENTE","COMPTE_ACHAT") AS
SELECT arl."ID",arl."IDPRODUITS",arl."IDINGREDIENTS",arl."QUANTITE",arl."UNITE",arl."LIBELLEINGREDIENT",arl."LIBELLEPRODUIT",arl."IDUNITE",arl."VALUNITE",arl."PU",c.ID AS CATEGORIEINGREDIENT , c.VAL AS categorielib, ai.COMPTE_VENTE ,ai.COMPTE_ACHAT  FROM 
	AS_RECETTE_LIBCOMPLET arl 
	JOIN AS_INGREDIENTS ai ON ai.id = arl.IDINGREDIENTS 
	JOIN CATEGORIEINGREDIENT c ON c.ID = ai.CATEGORIEINGREDIENT
;
-- [109/1309] CATEGORIE_PAIE_LIB
CREATE OR REPLACE FORCE VIEW "CATEGORIE_PAIE_LIB" ("ID","VAL","DESCE","MONTANT","REMARQUE","DROIT_HEURE_SUP","ESSAIE") AS
SELECT cp.id,
       cp.val,
       cp.desce,
       cp.montant,
       cp.remarque,
       CASE
           WHEN cp.droit_heure_sup = 'o' THEN 'OUI'
           WHEN cp.droit_heure_sup = 'n' THEN 'NON'
           ELSE NULL
           END AS droit_heure_sup,
       cp.essaie
FROM categorie_paie cp
;
-- [110/1309] CATEGORIE_PAIE_SALAIRE
CREATE OR REPLACE FORCE VIEW "CATEGORIE_PAIE_SALAIRE" ("ID","VAL","DESCE","MONTANT","REMARQUE","DROIT_HEURE_SUP","ESSAIE") AS
SELECT ID,VAL,DESCE,MONTANT,REMARQUE,DROIT_HEURE_SUP,ESSAIE FROM CATEGORIE_PAIE cp WHERE id in('CP0000010','CP0000011')
;
-- [111/1309] CATEGORIE_QUALIFICATION_LIBC
CREATE OR REPLACE FORCE VIEW "CATEGORIE_QUALIFICATION_LIBC" ("ID","IDCATEGORIE","IDQUALIFICATION","REMARQUE","ETAT","MONTANT","IDCATEGORIELIB","CATEGORIE_QUALIFICATIONLIB") AS
SELECT
    cq.id,
    cq.idcategorie,
    cq.idqualification,
    cq.remarque,
    cq.etat,
    cq.montant,
    cp.val AS idcategorielib,
    qp.val AS categorie_qualificationlib
FROM categorie_qualification cq
         JOIN qualification_paie qp ON TO_CHAR(qp.id) = TO_CHAR(cq.idqualification)
         JOIN categorie_paie cp ON TO_CHAR(cp.id) = TO_CHAR(cq.idcategorie)
;
-- [112/1309] CATEGORIE_QUALIFICATION_VW
CREATE OR REPLACE FORCE VIEW "CATEGORIE_QUALIFICATION_VW" ("ID","IDCATEGORIE","IDQUALIFICATION","REMARQUE","ETAT","MONTANT","DATE_DEBUT","DATE_FIN","AVENANT","IDPOSTE","INDICE","CATEGORIELIB","QUALIFICATIONLIB","ETATLIB") AS
SELECT
    cq."ID",cq."IDCATEGORIE",cq."IDQUALIFICATION",cq."REMARQUE",cq."ETAT",cq."MONTANT",cq."DATE_DEBUT",cq."DATE_FIN",cq."AVENANT",cq."IDPOSTE",cq."INDICE",
    cp.val AS categorieLib,
    qual.val AS qualificationLib,
    CASE
        WHEN cq.etat = 1 THEN 'ACTIF'
        WHEN cq.etat = -1 THEN 'INACTIF'
        ELSE 'INCONNU'
    END AS etatLib
FROM CATEGORIE_QUALIFICATION cq
LEFT JOIN CATEGORIE_PAIE cp
    ON cp.id = cq.idcategorie
LEFT JOIN QUALIFICATION_PAIE qual
    ON cq.idqualification = qual.id
;
-- [113/1309] CATEG_QUALI_CONTRAT
CREATE OR REPLACE FORCE VIEW "CATEG_QUALI_CONTRAT" ("ID","IDCATEGORIE","IDQUALIFICATION","REMARQUE","ETAT","MONTANT","DATE_DEBUT","DATE_FIN","AVENANT") AS
SELECT cq.id,
       cq.idcategorie,
       cq.idqualification,
       cq.remarque,
       cq.etat,
       cq.montant,
       cq.date_debut,
       cq.date_fin,
       cq.avenant
FROM categorie_qualification cq
WHERE cq.avenant >=0 AND cq.remarque IS NOT NULL
;
-- [114/1309] CATEG_QUALI_CONTRAT_2
CREATE OR REPLACE FORCE VIEW "CATEG_QUALI_CONTRAT_2" ("ID","IDCATEGORIE","IDQUALIFICATION","REMARQUE","ETAT","MONTANT","DATE_DEBUT","DATE_FIN","DATEFIN","AVENANT","NUMERO") AS
SELECT
    cq.id,
    cq.idcategorie,
    cq.idqualification,
    cq.remarque,
    cq.etat,
    cq.montant,
    cq.date_debut,
    cq.date_fin,

    -- Utilisation de LEAD pour datefin
    NVL(
            LEAD(cq.date_debut) OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) - 1,
            cq.date_fin
    ) AS datefin,

    -- Generation de l''avenant
    CASE
        WHEN ROW_NUMBER() OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) = 1 THEN 'initial'
        ELSE 'Avenant N?' || (ROW_NUMBER() OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) - 1)
        END AS avenant,

    -- Numero de l''avenant
    CASE
        WHEN ROW_NUMBER() OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) = 1 THEN '0'
        ELSE TO_CHAR(ROW_NUMBER() OVER (PARTITION BY cq.remarque ORDER BY cq.date_debut) - 1)
        END AS numero

FROM categ_quali_contrat cq
;
-- [115/1309] CATEG_QUALI_LIBCOMPLET
CREATE OR REPLACE FORCE VIEW "CATEG_QUALI_LIBCOMPLET" ("ID","IDCATEGORIE","IDQUALIFICATION","REMARQUE","ETAT","MONTANT","IDCATEGORIELIB","CATEGORIE_QUALIFICATIONLIB") AS
SELECT cq.id,
       cq.idcategorie,
       cq.idqualification,
       cq.remarque,
       cq.etat,
       cq.montant,
       cp.val AS idcategorielib,
       qp.val AS categorie_qualificationlib
FROM categorie_qualification cq
         JOIN qualification_paie qp ON qp.id = cq.idqualification
         JOIN categorie_paie cp ON cq.idcategorie = cp.id
;
-- [116/1309] CHARGEGROUPBYOFF
CREATE OR REPLACE FORCE VIEW "CHARGEGROUPBYOFF" ("IDOFF","MONTANTENTREE","MONTANTSORTIE") AS
select ofile.id as idoff, cast(0 as number(30,3)) as montantentree,cast(nvl(sum(c.pu*c.qte),0) as number(30,3)) as montantsortie
from charge c
         left join fabrication fabb on c.IDFABRICATION=fabb.id
         left join OFFILLE ofile on fabb.IDOFFILLE=ofile.ID
where c.etat>=11 group by ofile.id
;
-- [117/1309] CHARGEGROUPEBYOFF
CREATE OR REPLACE FORCE VIEW "CHARGEGROUPEBYOFF" ("IDOFF","MONTANTENTREE","MONTANTSORTIE") AS
SELECT ofile.id AS idoff , CAST(0 AS NUMBER(30,3)) AS montantentree  ,
cast(nvl(sum(c.pu*c.qte),0) AS NUMBER(30,3)) AS montantsortie FROM charge c
LEFT JOIN fabrication fabb ON c.IDFABRICATION=fabb.ID 
LEFT JOIN OFFILLE ofile ON fabb.IDoffilLe=ofile.id
WHERE c.etat>=11 GROUP BY OFILE.ID
;
-- [118/1309] CHARGEMONTANT
CREATE OR REPLACE FORCE VIEW "CHARGEMONTANT" ("ID","DATY","LIBELLE","PU","TYPE","IDFABRICATION","ETAT","IDINGREDIENTS","QTE","MONTANT") AS
SELECT c."ID",c."DATY",c."LIBELLE",c."PU",c."TYPE",c."IDFABRICATION",c."ETAT",c."IDINGREDIENTS",c."QTE", cast(c.pu * c.qte AS NUMBER(30,10)) AS montant FROM charge c
;
-- [119/1309] CHARGE_CPL
CREATE OR REPLACE FORCE VIEW "CHARGE_CPL" ("ID","DATY","LIBELLE","PU","QTE","TYPE","IDFABRICATION","ETAT","TYPELIB","ETATLIB") AS
SELECT
	    c.ID,
	    c.DATY,
	    c.LIBELLE,
	    c.PU,
	    c.QTE,
	    c.TYPE,
	    c.IDFABRICATION,
	    c.ETAT,
	    t.val AS typelib,
	    CASE
	        WHEN c.ETAT = 0
	            THEN 'ANNULEE'
	        WHEN c.ETAT = 1
	            THEN 'CREEE'
	        WHEN c.ETAT = 11
	            THEN 'VISEE'
	        ELSE 'INCONNU'
	        END AS etatlib
	FROM
	    CHARGE c
	        LEFT JOIN TYPECHARGE t ON t.id = c.TYPE
;
-- [120/1309] CHARGE_CPL_A
CREATE OR REPLACE FORCE VIEW "CHARGE_CPL_A" ("ID","DATY","LIBELLE","PU","QTE","TYPE","IDFABRICATION","ETAT","TYPELIB","ETATLIB") AS
SELECT 
"ID","DATY","LIBELLE","PU","QTE","TYPE","IDFABRICATION","ETAT","TYPELIB","ETATLIB" 
FROM CHARGE_CPL 
WHERE etat = 0
;
-- [121/1309] CHARGE_CPL_C
CREATE OR REPLACE FORCE VIEW "CHARGE_CPL_C" ("ID","DATY","LIBELLE","PU","QTE","TYPE","IDFABRICATION","ETAT","TYPELIB","ETATLIB") AS
SELECT 
"ID","DATY","LIBELLE","PU","QTE","TYPE","IDFABRICATION","ETAT","TYPELIB","ETATLIB" 
FROM CHARGE_CPL 
WHERE etat = 1
;
-- [122/1309] CHARGE_CPL_V
CREATE OR REPLACE FORCE VIEW "CHARGE_CPL_V" ("ID","DATY","LIBELLE","PU","QTE","TYPE","IDFABRICATION","ETAT","TYPELIB","ETATLIB") AS
SELECT 
"ID","DATY","LIBELLE","PU","QTE","TYPE","IDFABRICATION","ETAT","TYPELIB","ETATLIB" 
FROM CHARGE_CPL 
WHERE etat = 11
;
-- [123/1309] CHARGE_LIB
CREATE OR REPLACE FORCE VIEW "CHARGE_LIB" ("ID","DATY","LIBELLE","PU","TYPE","IDFABRICATION","ETAT","IDINGREDIENTS","QTE","IDOFFILLE","IDOF","MOTSCLESSS","TYPECHARGELIB","IDINGREDIENTSLIB","MONTANT") AS
SELECT SQ.ID,SQ.DATY,SQ.LIBELLE,SQ.PU,SQ.TYPE,SQ.IDFABRICATION,SQ.ETAT,SQ.IDINGREDIENTS,SQ.QTE,SQ.IDOFFILLE,SQ.IDOF,
	  (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(LIBELLE),'') || ' | ' || NVL(TO_CHAR(PU),'') || ' | ' || NVL(TO_CHAR(TYPE),'') || ' | ' || NVL(TO_CHAR(IDFABRICATION),'') || ' | ' || NVL(TO_CHAR(ETAT),'') || ' | ' || NVL(TO_CHAR(IDINGREDIENTS),'') || ' | ' || NVL(TO_CHAR(QTE),'') || ' | ' || NVL(TO_CHAR(IDOFFILLE),'') || ' | ' || NVL(TO_CHAR(IDOF),'')) AS MOTSCLESSS,typechargelib,idingredientslib,montant
	FROM (
	  SELECT 
	c.id ,
	c.daty ,
	c.libelle,
	c.pu ,
	c.type ,
	c.idfabrication,
	c.etat , 
	c.idingredients,
	c.qte ,
	f.IDOFFILLE,
	f.IDOF,
	tc.val AS typechargelib,
	ing.libelle AS idingredientslib,
	CAST(NVL(c.pu * c.qte, 0) AS NUMBER(30,2)) AS montant
	FROM CHARGE c 
	LEFT JOIN FABRICATION f ON f.id = c.idfabrication  
	LEFT JOIN typecharge tc ON c.TYPE=tc.id
	LEFT JOIN as_ingredients ing ON c.idingredients=ing.id 
	) SQ
;
-- [124/1309] CHECKINAVECCHEKOUT
CREATE OR REPLACE FORCE VIEW "CHECKINAVECCHEKOUT" ("ID","RESERVATION","DATY","HEURE","REMARQUE","CLIENT","IDPRODUIT","ETAT","IDCLIENT","QTE","CHECKOUT") AS
select c."ID",c."RESERVATION",c."DATY",c."HEURE",c."REMARQUE",c."CLIENT",c."IDPRODUIT",c."ETAT",c."IDCLIENT", c.qte,o.id as checkOut from CHECKIN c left join CHECKOUT o on c.id=o.RESERVATION
;
-- [125/1309] CHECKINAVECCHEKOUTCOMPLET
CREATE OR REPLACE FORCE VIEW "CHECKINAVECCHEKOUTCOMPLET" ("RESERVATION","ID","DATY","ETAT","HEURE","REMARQUE","CHECKOUT") AS
select c.RESERVATION ,o.id,o.DATY,o.ETAT,  o.HEURE,o.REMARQUE, o.RESERVATION as checkOut from CHECKIN c left join CHECKOUT o on c.id=o.RESERVATION
;
-- [126/1309] CHECKINLIBELLE
CREATE OR REPLACE FORCE VIEW "CHECKINLIBELLE" ("ID","RESERVATION","DATY","HEURE","REMARQUE","CLIENT","IDPRODUIT","ETAT","IDCLIENT","CHECKOUT","PRODUITLIBELLE","PU","TVA","ETATLIB") AS
SELECT
	c.ID,
	c.RESERVATION,
	c.DATY,
	c.HEURE,
	c.REMARQUE,
	cl.nom AS CLIENT,
	c.IDPRODUIT,
	c.ETAT,
	c.IDCLIENT,
	c.CHECKOUT,
	i.LIBELLE AS produitLibelle,
	i.pu,
	i.tva,
	CASE
	WHEN c.ETAT = 0
	THEN 'ANNULEE'
	WHEN c.ETAT = 1
	THEN 'CREE'
	WHEN c.ETAT = 11
	THEN 'VISEE'
END AS ETATLIB
FROM
	checkInAvecChekOut c
LEFT JOIN AS_INGREDIENTS i ON c.IDPRODUIT = i.id
LEFT JOIN CLIENT cl ON c.IDCLIENT=cl.id
;
-- [127/1309] CHECKINSANSCHEKOUT
CREATE OR REPLACE FORCE VIEW "CHECKINSANSCHEKOUT" ("ID","RESERVATION","DATY","HEURE","REMARQUE","CLIENT","IDPRODUIT","ETAT","IDCLIENT") AS
select c."ID",c."RESERVATION",c."DATY",c."HEURE",c."REMARQUE",c."CLIENT",c."IDPRODUIT",c."ETAT",c."IDCLIENT" from CHECKIN c where c.id not in (select o.reservation from CHECKOUT o where o.ETAT>=11)
;
-- [128/1309] CHECKINSANSCHEKOUTCPL
CREATE OR REPLACE FORCE VIEW "CHECKINSANSCHEKOUTCPL" ("ID","RESERVATION","DATY","HEURE","REMARQUE","CLIENT","IDPRODUIT","ETAT","IDCLIENT","CHAMBRE") AS
select
    ch."ID",ch."RESERVATION",ch."DATY",ch."HEURE",ch."REMARQUE",ch."CLIENT",ch."IDPRODUIT",ch."ETAT",ch."IDCLIENT",
    ing.LIBELLE as chambre
from CHECKINSANSCHEKOUT ch
         join AS_INGREDIENTS ing on ch.idproduit = ing.id
where ing.CATEGORIEINGREDIENT = 'CAT001'
;
-- [129/1309] CHECKLIST_MERE_LIB
CREATE OR REPLACE FORCE VIEW "CHECKLIST_MERE_LIB" ("ID","DATY","IDPERSONNEL","TYPECHECKLISTE","TYPECHECKLISTELIB","IDPERSONNELLIB","MATRICULE","IDFONCTION","IDFONCTIONLIB","IDSERVICE","IDSERVICELIB","IDDIRECTION","IDDIRECTIONLIB") AS
SELECT cm.ID,
       cm.DATY,
       cm.IDPERSONNEL,
       cm.TYPECHECKLISTE,
       -- typeCheckListeLib (0 => entree, 1 => sortie)
       CASE cm.TYPECHECKLISTE
           WHEN 0 THEN 'entree'
           WHEN 1 THEN 'sortie'
           ELSE 'Inconnu'
           END AS typeCheckListeLib,
       -- idPersonnelLib : Nom + prenom depuis table log_personnel
       lp.NOM || ' ' || lp.PRENOM AS idPersonnelLib,
       -- Matricule et idFonction depuis paie_info_personnel
       pip.MATRICULE,
       pip.IDFONCTION,
       -- idFonctionLib : Recuperer val depuis table paie_fonction
       pf.VAL AS idFonctionLib,
       -- idService depuis log_personnel et idServiceLib depuis log_service
       lp.SERVICE AS idService,
       ls.LIBELLE AS idServiceLib,
       -- idDirection depuis log_personnel et idDirectionLib depuis log_direction
       lp.DIRECTION AS idDirection,
       ld.VAL AS idDirectionLib
FROM CHECKLIST_MERE cm
         LEFT JOIN LOG_PERSONNEL lp ON lp.ID = cm.IDPERSONNEL
         LEFT JOIN PAIE_INFO_PERSONNEL pip ON pip.ID = lp.ID
         LEFT JOIN PAIE_FONCTION pf ON pf.ID = pip.IDFONCTION
         LEFT JOIN LOG_SERVICE ls ON ls.ID = lp.SERVICE
         LEFT JOIN LOG_DIRECTION ld ON ld.ID = lp.DIRECTION
;
-- [130/1309] CHECKOUTLIB
CREATE OR REPLACE FORCE VIEW "CHECKOUTLIB" ("ID","RESERVATION","DATY","HEURE","REMARQUE","ETAT","PRODUITLIBELLE","ETATLIB") AS
select
    ch."ID",ch."RESERVATION",ch."DATY",ch."HEURE",ch."REMARQUE",ch."ETAT",
    ci.PRODUITLIBELLE,
    case when ch.ETAT = 1 then 'CREE'
    when ch.ETAT = 11 then 'VALIDEE'
    END as etatlib
from CHECKOUT ch
join CHECKINLIBELLE ci on ci.ID = ch.RESERVATION
;
-- [131/1309] CHEQUECPL
CREATE OR REPLACE FORCE VIEW "CHEQUECPL" ("ID","REFERENCE","IDCAISSE","IDCAISSELIB","MONTANT","DATY","ETAT","ETATLIB","REMARQUE") AS
SELECT 
c.ID ,
c.REFERENCE ,
c.IDCAISSE ,
c2.VAL AS IDCAISSELIB,
c.MONTANT ,
c.DATY ,
c.ETAT ,
CASE 
	WHEN c.ETAT = 1 
	THEN 'CREE'
	WHEN c.ETAT = 11 
	THEN 'VALIDEE'
	WHEN c.ETAT = 20 
	THEN 'TOUCHEE'
END AS ETATLIB,
c.REMARQUE 
FROM CHEQUE c 
LEFT JOIN CAISSE c2 ON c2.ID = c.IDCAISSE
;
-- [132/1309] CHEQUECPL_CREE
CREATE OR REPLACE FORCE VIEW "CHEQUECPL_CREE" ("ID","REFERENCE","IDCAISSE","IDCAISSELIB","MONTANT","DATY","ETAT","ETATLIB","REMARQUE") AS
SELECT 
c."ID",c."REFERENCE",c."IDCAISSE",c."IDCAISSELIB",c."MONTANT",c."DATY",c."ETAT",c."ETATLIB",c."REMARQUE"
FROM CHEQUECPL c 
WHERE c.ETAT = 1
;
-- [133/1309] CHEQUECPL_TOUCHEE
CREATE OR REPLACE FORCE VIEW "CHEQUECPL_TOUCHEE" ("ID","REFERENCE","IDCAISSE","IDCAISSELIB","MONTANT","DATY","ETAT","ETATLIB","REMARQUE") AS
SELECT 
c."ID",c."REFERENCE",c."IDCAISSE",c."IDCAISSELIB",c."MONTANT",c."DATY",c."ETAT",c."ETATLIB",c."REMARQUE"
FROM CHEQUECPL c 
WHERE c.ETAT = 20
;
-- [134/1309] CHEQUECPL_VISEE
CREATE OR REPLACE FORCE VIEW "CHEQUECPL_VISEE" ("ID","REFERENCE","IDCAISSE","IDCAISSELIB","MONTANT","DATY","ETAT","ETATLIB","REMARQUE") AS
SELECT 
c."ID",c."REFERENCE",c."IDCAISSE",c."IDCAISSELIB",c."MONTANT",c."DATY",c."ETAT",c."ETATLIB",c."REMARQUE"
FROM CHEQUECPL c 
WHERE c.ETAT = 11
;
-- [135/1309] CLIENTLIB
CREATE OR REPLACE FORCE VIEW "CLIENTLIB" ("ID","NOM","TELEPHONE","MAIL","ADRESSE","REMARQUE","COMPTE","IDNATIONALITE","COMPTEAUXILIAIRE","IDTYPECLIENT","IDTYPECLIENTLIB","CODECLIENT","DATECARTE","TAXE","IDPROVINCE","ECHEANCE","TELFIXE","NIF","STAT","CARTE","PROVINCELIB","SEUIL") AS
SELECT
    c.ID,c.NOM,c.TELEPHONE,c.MAIL,c.ADRESSE,c.REMARQUE,c.COMPTE,c.IDNATIONALITE,c.COMPTEAUXILIAIRE,c.IDTYPECLIENT,
    t.val AS idTypeClientLib,
    c.codeclient,c.datecarte,c.taxe,c.idprovince,c.echeance,c.telfixe,c.nif,c.stat,c.carte,p.val AS provincelib,
    c.SEUIL
FROM CLIENT c
LEFT JOIN typeclient t
ON c.idTypeClient = t.id
LEFT JOIN province p ON c.idprovince=p.id where ESTACTIF=1
;
-- [136/1309] CLIENT_ACTIF
CREATE OR REPLACE FORCE VIEW "CLIENT_ACTIF" ("ID","NOM","TELEPHONE","MAIL","ADRESSE","REMARQUE","COMPTE","IDNATIONALITE","COMPTEAUXILIAIRE","IDTYPECLIENT","IDPROVINCE","ECHEANCE","TELFIXE","NIF","STAT","CARTE","DATECARTE","TAXE","CODECLIENT") AS
select ID, NOM, TELEPHONE, MAIL, ADRESSE, REMARQUE, COMPTE, IDNATIONALITE, COMPTEAUXILIAIRE, IDTYPECLIENT, IDPROVINCE, ECHEANCE, TELFIXE, NIF, STAT, CARTE, DATECARTE, TAXE, CODECLIENT from Client where estactif = 1
;
-- [137/1309] CLOTURECAISSE_CPL
CREATE OR REPLACE FORCE VIEW "CLOTURECAISSE_CPL" ("ID","DATY","REMARQUE","ETAT","IDPOINT","IDPOINTLIB","ETATLIB") AS
SELECT
    cc.ID,cc.DATY,cc.REMARQUE,cc.ETAT,cc.IDPOINT,
    p.val AS idpointlib,
    CASE
        WHEN cc.etat = 1 THEN 'CR&Eacute;&Eacute;E'
        WHEN cc.etat >= 11 THEN 'VIS&Eacute;E'
        ELSE 'AUTRE' end as etatLib
FROM CLOTURECAISSE cc
         LEFT JOIN POINT p ON cc.idPoint = p.id
;
-- [138/1309] CODE_ROME_LIB
CREATE OR REPLACE FORCE VIEW "CODE_ROME_LIB" ("ID","IDSOUSFAMILLE","CODE","IDSOUSFAMILLELIB") AS
(
    select
       cr.ID,cr.IDSOUSFAMILLE,cr.CODE,
       sfp.val as idSousFamilleLib
    from code_rome cr
       left join sous_famille_pro sfp on sfp.id=cr.idsousfamille

)
;
-- [139/1309] COMMANDEFILLECPL
CREATE OR REPLACE FORCE VIEW "COMMANDEFILLECPL" ("ID","PRODUIT","IDC","QUANTITE","PU","MONTANT","TVA","REMISE","IDDEVISE","UNITE","DESIGNATION","RISTOURNE","PRODUITLIB") AS
SELECT cmd."ID",cmd."PRODUIT",cmd."IDC",cmd."QUANTITE",cmd."PU",cmd."MONTANT",cmd."TVA",cmd."REMISE",cmd."IDDEVISE",cmd."UNITE",cmd."DESIGNATION",cmd."RISTOURNE",
       p.LIBELLE as produitLib
FROM COMMANDEFILLE cmd
         LEFT JOIN AS_INGREDIENTS p
                   ON p.id = cmd.PRODUIT
;
-- [140/1309] COMMANDEFILLEVIDE
CREATE OR REPLACE FORCE VIEW "COMMANDEFILLEVIDE" ("ID","PRODUIT","IDC","QUANTITE","PU","MONTANT","TVA","REMISE","IDDEVISE","UNITE","DESIGNATION","RISTOURNE","CALORIE","UNITELIB") AS
select cm."ID",cm."PRODUIT",cm."IDC",cm."QUANTITE",cm."PU",cm."MONTANT",cm."TVA",cm."REMISE",cm."IDDEVISE",cm."UNITE",cm."DESIGNATION",cm."RISTOURNE",cm."CALORIE",'' as uniteLib from COMMANDEFILLE cm
;
-- [141/1309] COMMANDEFILLE_ARBIOCHEM
CREATE OR REPLACE FORCE VIEW "COMMANDEFILLE_ARBIOCHEM" ("ID","PRODUIT","IDC","QUANTITE","PU","MONTANT","TVA","REMISE","IDDEVISE","UNITE","DESIGNATION","RISTOURNE","CALORIE","MONTANTRISTOURNE","MONTANTREMISE") AS
select "ID","PRODUIT","IDC","QUANTITE","PU","MONTANT","TVA","REMISE","IDDEVISE","UNITE","DESIGNATION","RISTOURNE","CALORIE",    0 AS montantRistourne,
       0 AS montantRemise from COMMANDEFILLE
;
-- [142/1309] COMMANDEFILLE_V
CREATE OR REPLACE FORCE VIEW "COMMANDEFILLE_V" ("ID","PRODUIT","IDC","QUANTITE","PU","MONTANT","TVA","REMISE","IDDEVISE","UNITE","DESIGNATION","UNITELIB","PUNET","MONTANTHT","MONTANTTTC","RISTOURNE","CALORIE") AS
select p.ID,
       p.PRODUIT,
       p.IDC,
       p.QUANTITE,
       p.PU,
       p.MONTANT,
       p.TVA,
       p.REMISE,
       p.IDDEVISE,
       p.UNITE,
       p.DESIGNATION,
       uni.val as unitelib,
       0  as punet,
       0  as montantht,
       0  as montantttc,
       p.RISTOURNE,
       ing.calorie
from COMMANDEFILLE p
         LEFT JOIN as_unite uni ON p.unite = uni.id
         LEFT JOIN  AS_INGREDIENTS ing ON p.PRODUIT = ing.ID
;
-- [143/1309] COMPTA_COMPTE_LIB
CREATE OR REPLACE FORCE VIEW "COMPTA_COMPTE_LIB" ("ID","COMPTE","LIBELLE","TYPECOMPTE","CLASSY","ANALYTIQUE_OBLI","IDJOURNAL") AS
select ID,
	       Compte,
	       LIBELLE||' : '||COMPTE as libelle,
	       TYPECOMPTE,
	       CLASSY,
	       ANALYTIQUE_OBLI,
	       IDJOURNAL
	from COMPTA_COMPTE
;
-- [144/1309] COMPTA_COMPTE_LIBELLE
CREATE OR REPLACE FORCE VIEW "COMPTA_COMPTE_LIBELLE" ("ID","COMPTE","LIBELLE","TYPECOMPTE","CLASSE","IDJOURNAL","IDTYPECOMPTE") AS
(SELECT   compta_compte.ID,
            compta_compte.compte,
            compta_compte.libelle,
            compta_type_compte.val AS typecompte,
            compta_classe_compte.val  AS classe ,
            (compta_journal.VAL ||'|'|| compta_journal.DESCE) as idjournal,
            compta_type_compte.id AS idtypecompte
  FROM compta_compte
  join compta_type_compte on compta_type_compte.ID = compta_compte.typecompte
  left join compta_classe_compte on compta_classe_compte.ID = compta_compte.classy
  left join compta_journal on compta_compte.idjournal = compta_journal.id)
;
-- [145/1309] COMPTA_ECRITURE_FILLE
CREATE OR REPLACE FORCE VIEW "COMPTA_ECRITURE_FILLE" ("ID","MOIS","JOUR","COMPTE","FOLIO","SOURCE","LIBELLE","DEBIT","CREDIT","DATY","ANALYTIQUE","JOURNAL","EXERCICE") AS
SELECT id,
		EXTRACT(MONTH FROM daty ) as mois,
		EXTRACT(DAY FROM daty ) as jour,
		compte,
		folio,
		SOURCE,
		libellepiece AS libelle,
		debit,
		credit,
		daty,
		analytique,
		journal,
		exercice
	FROM COMPTA_SOUS_ECRITURE
;
-- [146/1309] COMPTA_ECRITURE_MERE
CREATE OR REPLACE FORCE VIEW "COMPTA_ECRITURE_MERE" ("ID","MOIS","EXERCICE","JOURNAL") AS
SELECT
	id,
	EXTRACT(MONTH FROM daty ) AS mois,
	exercice,
	journal
FROM
	COMPTA_SOUS_ECRITURE
;
-- [147/1309] COMPTA_ECRITURE_MF
CREATE OR REPLACE FORCE VIEW "COMPTA_ECRITURE_MF" ("ID","DATY","DATECOMPTABLE","EXERCICE","DESIGNATION","REMARQUE","ETAT","HORSEXERCICE","JOURNAL","OD","ORIGINE","IDUSER","PERIODE","TRIMESTRE","ANNEE","IDOBJET","LETTRAGE","COMPTE","DEBIT","CREDIT") AS
SELECT
    ce.ID,
    ce.DATY,
    ce.DATECOMPTABLE,
    ce.EXERCICE,
    ce.DESIGNATION,
    ce.REMARQUE,
    ce.ETAT,
    ce.HORSEXERCICE,
    ce.JOURNAL,
    ce.OD,
    ce.ORIGINE,
    ce.IDUSER,
    ce.PERIODE,
    ce.TRIMESTRE,
    ce.ANNEE,
    ce.IDOBJET,
    ce.LETTRAGE,
    cse.COMPTE ,
    CAST( SUM(cse.DEBIT) AS NUMBER(30,2))  AS DEBIT,
    CAST( SUM(cse.CREDIT) AS NUMBER(30,2)) AS CREDIT
FROM COMPTA_ECRITURE ce
         LEFT JOIN COMPTA_SOUS_ECRITURE cse ON ce.ID = cse.IDMERE
GROUP BY
    ce.ID,
    ce.DATY,
    ce.DATECOMPTABLE,
    ce.EXERCICE,
    ce.DESIGNATION,
    ce.REMARQUE,
    ce.ETAT,
    ce.HORSEXERCICE,
    ce.JOURNAL,
    ce.OD,
    ce.ORIGINE,
    ce.IDUSER,
    ce.PERIODE,
    ce.TRIMESTRE,
    ce.ANNEE,
    ce.IDOBJET,
    ce.LETTRAGE,
    cse.COMPTE
;
-- [148/1309] COMPTA_JOURNAL_COMPTE
CREATE OR REPLACE FORCE VIEW "COMPTA_JOURNAL_COMPTE" ("ID","VAL","DESCE") AS
SELECT ID,
       CASE
           WHEN COMPTE IS NOT NULL THEN VAL || ' - ' || COMPTE
           ELSE VAL
           END                               AS VAL,
       VAL || '|' || DESCE || '**' || COMPTE AS DESCE
FROM COMPTA_JOURNAL
WHERE VAL != 'COMP000015'
;
-- [149/1309] COMPTA_JOURNAL_ECRITURE_VIEW
CREATE OR REPLACE FORCE VIEW "COMPTA_JOURNAL_ECRITURE_VIEW" ("ID","VAL","DESCE") AS
SELECT
	ID,
	CASE
		WHEN COMPTE IS NOT NULL THEN VAL || ' - ' || COMPTE
		ELSE VAL
	END AS VAL,
	VAL || '|' || DESCE || '**' || COMPTE AS DESCE
FROM
	COMPTA_JOURNAL
WHERE
	VAL != 'COMP000015'
;
-- [150/1309] COMPTA_JOURNAL_MOTSCLESSS
CREATE OR REPLACE FORCE VIEW "COMPTA_JOURNAL_MOTSCLESSS" ("ID","VAL","DESCE","COMPTE","MOTSCLESSS") AS
SELECT 
cj.ID,
cj.VAL,
cj.DESCE,
cj.COMPTE,
cj.id || '' || cj.val || '' || cj.desce || '' || cj.compte AS motsclesss
FROM COMPTA_JOURNAL cj
;
-- [151/1309] COMPTA_JOURNAL_VIEW
CREATE OR REPLACE FORCE VIEW "COMPTA_JOURNAL_VIEW" ("ID","VAL","DESCE") AS
SELECT ID, VAL, VAL||'|'||DESCE AS DESCE FROM COMPTA_JOURNAL
;
-- [152/1309] COMPTA_LETTRAGE_LIB
CREATE OR REPLACE FORCE VIEW "COMPTA_LETTRAGE_LIB" ("ID","LETTRE","DATE_LETTRAGE","COMPTE","MONTANT","REMARQUE","JOURNAL") AS
SELECT cl.id, cl.LETTRE, cl.DATE_LETTRAGE, cc.COMPTE, cl.montant, cl.remarque,
  jrn.desce as journal
FROM compta_lettrage cl
         LEFT JOIN COMPTA_SOUS_ECRITURE cse ON cse.LETTRAGE = cl.ID
         LEFT JOIN COMPTA_COMPTE cc ON cc.COMPTE = cse.compte
         LEFT JOIN COMPTA_JOURNAL jrn ON cse.JOURNAL = jrn.ID
;
-- [153/1309] COMPTA_MONTANT
CREATE OR REPLACE FORCE VIEW "COMPTA_MONTANT" ("MONTANT","IDMERE") AS
SELECT
sum(nvl(cse.DEBIT,0)) AS montant ,
cse.IDMERE
FROM COMPTA_SOUS_ECRITURE cse
GROUP BY IDMERE
;
-- [154/1309] COMPTA_REPORT
CREATE OR REPLACE FORCE VIEW "COMPTA_REPORT" ("ID","COMPTE","LIBELLE_COMPTE","DEBIT","CREDIT","DATY","TYPECOMPTE","MOIS","ANNEE") AS
SELECT
    cse.ID,
    cse.compte,
    '-',
    CAST(sum(cse.debit) AS number(20,2)) AS debit,
    CAST(sum(cse.credit) AS number(20,2)) AS credit,
    NULL,
    1,
    12,
    cse.exercice
FROM
    compta_sous_ecriture cse,
    compta_compte cc,
    compta_journal cj
WHERE cse.compte = cc.compte
  AND cse.journal = cj.ID
  AND cse.etat = 11
  AND cc.typecompte = '1'
  AND cc.CLASSY  NOT IN ('6', '7')
GROUP BY
    cse.ID,
    cse.compte,
    cse.exercice
;
-- [155/1309] COMPTA_VIEW_FOLIO
CREATE OR REPLACE FORCE VIEW "COMPTA_VIEW_FOLIO" ("ID","JOURNAL","MOIS","EXERCICE","COMPTE","FOLIO","TYPECOMPTE") AS
SELECT
    ' ' AS id ,
    ' ' AS journal ,
    ' ' AS mois ,
    ' ' AS exercice,
    ' ' AS compte ,
    ' ' AS folio ,
    ' ' AS typeCompte
FROM
    dual
;
-- [156/1309] COMPTE6
CREATE OR REPLACE FORCE VIEW "COMPTE6" ("ID","COMPTE","LIBELLE","TYPECOMPTE","CLASSY","ANALYTIQUE_OBLI","IDJOURNAL") AS
SELECT "ID","COMPTE","LIBELLE","TYPECOMPTE","CLASSY","ANALYTIQUE_OBLI","IDJOURNAL"
FROM COMPTA_COMPTE c
WHERE compte LIKE '6%'
;
-- [157/1309] COMPTEURCPL
CREATE OR REPLACE FORCE VIEW "COMPTEURCPL" ("ID","DATY","IDLIGNE","ANCIEN","VALEUR","ECART","IDCATEGORIE","IDLIGNELIB","IDCATEGORIELIB","ETAT","ETATLIB","IDMAGASIN","IDMAGASINLIB") AS
SELECT
    c.id,
    c.daty,
    c.idligne,
    c.ancien,
    c.valeur,
    c.ecart,
    c.idcategorie,
    l.val        AS idlignelib,
    cc.libelle       AS idcategorielib,
    c.etat,
       CASE
	        WHEN c.ETAT = 0
	            THEN 'ANNUL&Eacute;E'
	        WHEN c.ETAT = 1
	            THEN 'CR&Eacute;&Eacute;E'
	        WHEN c.ETAT = 11
	            THEN 'VIS&Eacute;(E) par Chef de Fabrication'
	        WHEN c.ETAT = 3
	            THEN 'VIS&Eacute;(E) par Releveur'
	        END AS etatlib,
    c.IDMAGASIN,
    m.VAL AS idMagasinLib
FROM compteurmaintenance c
         LEFT JOIN ligne l
                   ON l.id = c.idligne
         LEFT JOIN AS_INGREDIENTS_CONSOMMABLE cc
                   ON cc.id = c.idcategorie
         LEFT JOIN MAGASIN2 m ON m.ID = c.IDMAGASIN
;
-- [158/1309] COMPTEURCPLRECENT
CREATE OR REPLACE FORCE VIEW "COMPTEURCPLRECENT" ("ID","DATY","IDLIGNE","VALEUR","ECART","IDCATEGORIE","IDMAGASIN","ETAT","ANCIEN","IDLIGNELIB","IDCATEGORIELIB","IDMAGASINLIB","RN") AS
SELECT "ID","DATY","IDLIGNE","VALEUR","ECART","IDCATEGORIE","IDMAGASIN","ETAT","ANCIEN","IDLIGNELIB","IDCATEGORIELIB","IDMAGASINLIB","RN"
FROM (
    SELECT 
        cm.ID,
        cm.DATY,
        cm.IDLIGNE,
        cm.VALEUR,
        cm.ECART,
        cm.IDCATEGORIE,
        cm.IDMAGASIN,
        cm.ETAT,
        cm.ANCIEN,
        cm.IDLIGNELIB ,
        cm.IDCATEGORIELIB ,
        cm.IDMAGASINLIB ,
        ROW_NUMBER() OVER (
            PARTITION BY cm.IDLIGNE, cm.IDCATEGORIE, cm.IDMAGASIN
            ORDER BY cm.DATY DESC
        ) AS rn
        
    FROM CompteurCPL cm
)
WHERE rn = 1
;
-- [159/1309] COMPTEURELECTRICITELIB
CREATE OR REPLACE FORCE VIEW "COMPTEURELECTRICITELIB" ("ID","DATY","IDLIGNE","VALEUR","ECART","IDCATEGORIE","IDMAGASIN","ETAT","ANCIEN","REMARQUE","HEURE","IDMACHINE","IDMERE","IDLIGNELIB","IDMACHINELIB","IDCATEGORIELIB","PU","MONTANT") AS
SELECT
    ce.ID,ce.DATY,ce.IDLIGNE,ce.VALEUR,ce.ECART,ce.IDCATEGORIE,ce.IDMAGASIN,ce.ETAT,ce.ANCIEN,ce.REMARQUE,ce.HEURE,ce.IDMACHINE,ce.IDMERE,
    l.VAL AS IdLigneLib,
    m.LIBELLE AS IdMachineLib,
    cat.LIBELLE AS IdCategorieLib,
    cat.pu AS pu,
    cat.pu * ce.ECART AS montant
FROM CompteurElectricite ce
         LEFT JOIN Ligne l ON ce.IdLigne = l.id
         LEFT JOIN AS_INGREDIENT_MACHINE m ON ce.IdMachine = m.ID
         LEFT JOIN AS_INGREDIENTS_CONSOMMABLE cat ON ce.IdCategorie = cat.id
;
-- [160/1309] COMPTEURELECTRICITEMERELIB
CREATE OR REPLACE FORCE VIEW "COMPTEURELECTRICITEMERELIB" ("ID","DATY","LIGNE","REMARQUE","ETAT","LIGNELIB","CONSOMMATION","MONTANT","ETATLIB") AS
SELECT
    c.ID,
    c.DATY,
    c.LIGNE,
    c.REMARQUE,
    c.ETAT,
    l.VAL AS LIGNELIB,
    NVL(f.CONSOMMATION, 0) AS CONSOMMATION,
    NVL(f.MONTANT, 0) AS MONTANT,
    CASE
        WHEN c.ETAT = 0
            THEN 'ANNUL&Eacute;E'
        WHEN c.ETAT = 1
            THEN 'CR&Eacute;&Eacute;E'
        WHEN c.ETAT = 11
            THEN 'VIS&Eacute;(E) par Chef de Fabrication'
        WHEN c.ETAT = 3
            THEN 'VIS&Eacute;(E) par Releveur'
        END AS etatlib
FROM
    COMPTEURELECTRICITEMERE c
        LEFT JOIN LIGNE l
                  ON l.ID = c.LIGNE
        LEFT JOIN (
            SELECT
                fe.IDMERE AS ID_MERE,
                SUM(fe.ECART)    AS CONSOMMATION,
                SUM(fe.MONTANT)    AS MONTANT
            FROM
                COMPTEURELECTRICITELIB fe
            GROUP BY
                fe.IDMERE
        ) f ON f.ID_MERE = c.ID
;
-- [161/1309] COMPTEURLIB
CREATE OR REPLACE FORCE VIEW "COMPTEURLIB" ("ID","NOMBRE","IDFABRICATION","IDMACHINE","DATY","HEURE","DEBUT","ETAT","IDORIGINE","IDFABRICATIONLIB","IDMACHINELIB","ETATLIB") AS
SELECT
	    c.ID,
	    c.NOMBRE,
	    c.IDFABRICATION,
	    c.IDMACHINE,
	    c.DATY,
	    c.HEURE,
	    c.DEBUT,
	    c.ETAT,
	    c.IDORIGINE,
	    f.LIBELLE AS idfabricationlib,
	    aim.INGREDIENTLIB AS idmachinelib,
	     CASE
	        WHEN c.ETAT = 0
	            THEN 'ANNUL&Eacute;E'
	        WHEN c.ETAT = 1
	            THEN 'CR&Eacute;&Eacute;E'
	        WHEN c.ETAT = 11
	            THEN 'VIS&Eacute;(E) par Chef de Fabrication'
	        WHEN c.ETAT = 3
	            THEN 'VIS&Eacute;(E) par Releveur'
	        END AS etatlib
	FROM COMPTEUR c
	         LEFT JOIN FABRICATION f ON f.id = c.idfabrication
	         LEFT JOIN AS_INGREDIENT_MACHINE aim    ON aim.id = c.idmachine
;
-- [162/1309] COMPTEURLIBANNULER
CREATE OR REPLACE FORCE VIEW "COMPTEURLIBANNULER" ("ID","NOMBRE","IDFABRICATION","IDMACHINE","DATY","HEURE","DEBUT","ETAT","IDORIGINE","IDFABRICATIONLIB","IDMACHINELIB","ETATLIB") AS
SELECT 
"ID","NOMBRE","IDFABRICATION","IDMACHINE","DATY","HEURE","DEBUT","ETAT","IDORIGINE","IDFABRICATIONLIB","IDMACHINELIB","ETATLIB"
FROM COMPTEURLIB 
WHERE etat = 0
;
-- [163/1309] COMPTEURLIBCREER
CREATE OR REPLACE FORCE VIEW "COMPTEURLIBCREER" ("ID","NOMBRE","IDFABRICATION","IDMACHINE","DATY","HEURE","DEBUT","ETAT","IDORIGINE","IDFABRICATIONLIB","IDMACHINELIB","ETATLIB") AS
SELECT 
"ID","NOMBRE","IDFABRICATION","IDMACHINE","DATY","HEURE","DEBUT","ETAT","IDORIGINE","IDFABRICATIONLIB","IDMACHINELIB","ETATLIB"
FROM COMPTEURLIB 
WHERE etat = 1
;
-- [164/1309] COMPTEURLIBVISER
CREATE OR REPLACE FORCE VIEW "COMPTEURLIBVISER" ("ID","NOMBRE","IDFABRICATION","IDMACHINE","DATY","HEURE","DEBUT","ETAT","IDORIGINE","IDFABRICATIONLIB","IDMACHINELIB","ETATLIB") AS
SELECT 
"ID","NOMBRE","IDFABRICATION","IDMACHINE","DATY","HEURE","DEBUT","ETAT","IDORIGINE","IDFABRICATIONLIB","IDMACHINELIB","ETATLIB"
FROM COMPTEURLIB 
WHERE etat = 11
;
-- [165/1309] COMPTE_ANALYTIQUE
CREATE OR REPLACE FORCE VIEW "COMPTE_ANALYTIQUE" ("ID","COMPTE","LIBELLE","TYPECOMPTE","CLASSY","ANALYTIQUE_OBLI","IDJOURNAL","CODEIMPOT") AS
select "ID","COMPTE","LIBELLE","TYPECOMPTE","CLASSY","ANALYTIQUE_OBLI","IDJOURNAL","CODEIMPOT" from COMPTA_COMPTE where TYPECOMPTE='3'
;
-- [166/1309] COMPTE_AUX
CREATE OR REPLACE FORCE VIEW "COMPTE_AUX" ("LIBELLE","COMPTE") AS
select nom as libelle,COMPTEAUXILIAIRE as compte from CLIENT union select nom as libelle,COMPTEAUXILIAIRE as compte from FOURNISSEUR
;
-- [167/1309] COMPTASOUSECRITURESTVA
CREATE OR REPLACE FORCE VIEW "COMPTASOUSECRITURESTVA" ("ID","COMPTE","DEBIT","CREDIT","REMARQUE","LIBELLEPIECE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO","ANALYTIQUE","SOURCE") AS
select cse1."ID",cse1."COMPTE",cse1."DEBIT",cse1."CREDIT",cse1."REMARQUE",cse1."LIBELLEPIECE",cse1."IDMERE",cse1."REFERENCE_ENGAGEMENT",cse1."COMPTE_AUX",cse1."LETTRAGE",cse1."JOURNAL",cse1."EXERCICE",cse1."ETAT",cse1."DATY",cse1."FOLIO",cse1."ANALYTIQUE",cse1."SOURCE" from COMPTA_SOUS_ECRITURE cse1 left join COMPTA_SOUS_ECRITURE cse2 on cse1.IDMERE=cse2.IDMERE AND cse2.COMPTE like '445%' where cse2.COMPTE is null
;
-- [168/1309] COMPTA_MOUVEMENT_DETAILGEN
CREATE OR REPLACE FORCE VIEW "COMPTA_MOUVEMENT_DETAILGEN" ("ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","MERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO","COURSDEVISE","MONTANTDEVISE") AS
SELECT
	cse.id,
	(
	SELECT
		MIN(csec.compte) KEEP (DENSE_RANK FIRST
	ORDER BY
		GREATEST(csec.debit, csec.credit) DESC)
	FROM
		compta_sous_ecriture csec,
		COMPTA_JOURNAL_VIEW cjv
	WHERE
		csec.idmere = cse.idmere
		AND csec.id <> cse.id
		AND cjv.id = csec.journal
		AND (

            (cse.debit > 0
			AND csec.credit > 0)
		OR

            (cse.credit > 0
			AND csec.debit > 0)

            )
		AND cjv.id <> 'COMP000015'

    ) AS contrep,
	cse.compte,
	cse.debit,
	cse.credit,
	cse.libellepiece,
	cse.remarque,
	cse.idmere,
	cse.analytique AS REFERENCE_ENGAGEMENT,
	cse.compte_aux,
	lettre.lettre AS lettrage,
	cj.val AS journal,
	EXTRACT(YEAR FROM cse.daty) AS exercice,
	cse.etat,
	cse.daty,
	cse.folio,
	CAST(0 AS NUMBER(20, 2)) AS coursdevise,
	CAST(0 AS NUMBER(20, 2)) AS montantdevise
FROM
	COMPTA_SOUS_ECRITURE cse
LEFT JOIN COMPTA_JOURNAL_VIEW cj ON
	cj.id = cse.journal
LEFT JOIN compta_compte cc ON
	cse.compte = cc.compte
LEFT JOIN compta_type_compte ctc ON
	cc.typecompte = ctc.id
LEFT JOIN COMPTA_LETTRAGE lettre ON
	lettre.id = cse.lettrage
WHERE
	1<2
	AND cj.id <> 'COMP000015'
	AND ((cse.DEBIT>0
		AND cse.credit = 0)
	OR (cse.DEBIT = 0
		AND cse.credit>0))
;
-- [169/1309] COMPTA_MOUVEMENT_DETAILS_ANAL2
CREATE OR REPLACE FORCE VIEW "COMPTA_MOUVEMENT_DETAILS_ANAL2" ("ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO") AS
SELECT
	cse.id,
	(
	SELECT
		csec.analytique
	FROM
		compta_sous_ecriture csec,
		COMPTA_JOURNAL_VIEW cjv,
		compta_compte cco,
		compta_type_compte ctcp
	WHERE
		csec.idmere = cse.idmere
		AND csec.credit>0
		AND cjv.id = csec.journal
		AND csec.analytique = cco.compte
		AND cco.typecompte = ctcp.id
		AND cjv.val <> 'COMP000015'
		AND rownum = 1) AS contrep,
	cse.analytique,
	cse.debit,
	cse.credit,
	cse.libellepiece,
	cse.remarque,
	cse.idmere,
	cse.reference_engagement,
	cse.compte_aux,
	lettre.lettre AS lettrage,
	cj.val AS journal,
	EXTRACT(YEAR FROM cse.daty),
	cse.etat,
	cse.daty,
	cse.folio
FROM
	COMPTA_SOUS_ECRITURE cse
JOIN compta_ecriture ce ON
	ce.id = cse.idmere
JOIN COMPTA_JOURNAL_VIEW cj ON
	cj.id = cse.journal
JOIN compta_compte cc ON
	cse.analytique = cc.compte
JOIN compta_type_compte ctc ON
	cc.typecompte = ctc.id
LEFT JOIN COMPTA_LETTRAGE lettre ON
	lettre.id = cse.lettrage
WHERE
	1<2
	AND cj.id <> 'COMP000015'
	AND cse.DEBIT>0
UNION

SELECT
	cse.id,
	(
	SELECT
		csec.analytique
	FROM
		compta_sous_ecriture csec,
		COMPTA_JOURNAL_VIEW cjv,
		compta_compte cco,
		compta_type_compte ctcp
	WHERE
		csec.idmere = cse.idmere
		AND csec.debit>0
		AND cjv.id = csec.journal
		AND csec.analytique = cco.compte
		AND cco.typecompte = ctcp.id
		AND cjv.id <> 'COMP000015'
		AND rownum = 1) AS contrep,
	cse.analytique,
	cse.debit,
	cse.credit,
	cse.libellepiece,
	cse.remarque,
	cse.idmere,
	cse.reference_engagement,
	cse.compte_aux,
	lettre.lettre AS lettrage,
	cj.val AS journal,
	EXTRACT(YEAR FROM cse.daty),
	cse.etat,
	cse.daty,
	cse.folio
FROM
	COMPTA_SOUS_ECRITURE cse
JOIN compta_ecriture ce ON
	ce.id = cse.idmere
JOIN COMPTA_JOURNAL_VIEW cj ON
	cj.id = cse.journal
JOIN compta_compte cc ON
	cse.analytique = cc.compte
JOIN compta_type_compte ctc ON
	cc.typecompte = ctc.id
LEFT JOIN COMPTA_LETTRAGE lettre ON
	lettre.id = cse.lettrage
WHERE
	1<2
	AND cj.id <> 'COMP000015'
	AND cse.CREDIT>0
;
-- [170/1309] COMPTA_MOUVEMENT_ANAL_C
CREATE OR REPLACE FORCE VIEW "COMPTA_MOUVEMENT_ANAL_C" ("ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO") AS
SELECT
    "ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO"
FROM
    COMPTA_MOUVEMENT_DETAILS_ANAL2 cmda
WHERE cmda.etat = 1
;
-- [171/1309] COMPTA_MOUVEMENT_ANAL_V
CREATE OR REPLACE FORCE VIEW "COMPTA_MOUVEMENT_ANAL_V" ("ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO") AS
SELECT
    "ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO"
FROM
    COMPTA_MOUVEMENT_DETAILS_ANAL2 cmda
WHERE cmda.etat = 11
;
-- [172/1309] COMPTA_MOUVEMENT_DETAILS_GEN_2
CREATE OR REPLACE FORCE VIEW "COMPTA_MOUVEMENT_DETAILS_GEN_2" ("ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO","COURSDEVISE","MONTANTDEVISE","COMPTEINT") AS
SELECT
    ID,
    CONTREP,
    COMPTE,
    DEBIT,
    CREDIT,
    LIBELLEPIECE,
    REMARQUE,
    MERE AS IDMERE,
    REFERENCE_ENGAGEMENT,
    COMPTE_AUX,
    LETTRAGE,
    JOURNAL,
    EXERCICE,
    ETAT,
    DATY,
    FOLIO,
    CAST(COURSDEVISE AS NUMBER(20,
                               2)) AS COURSDEVISE,
    CAST(MONTANTDEVISE AS NUMBER(20,
                                 2)) AS MONTANTDEVISE,
    TO_NUMBER(REGEXP_SUBSTR(TRIM(compte), '^[0-9]+')) AS compteInt
FROM
    COMPTA_MOUVEMENT_DETAILGEN
where REGEXP_LIKE(TRIM(compte), '^[0-9]+')
;
-- [173/1309] COMPTAMOUVEMENTDETAILS_GEN_2_C
CREATE OR REPLACE FORCE VIEW "COMPTAMOUVEMENTDETAILS_GEN_2_C" ("ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO","COURSDEVISE","MONTANTDEVISE","COMPTEINT") AS
SELECT
    "ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO","COURSDEVISE","MONTANTDEVISE","COMPTEINT"
FROM
    COMPTA_MOUVEMENT_DETAILS_GEN_2 cmdg
WHERE cmdg.etat = 1
;
-- [174/1309] COMPTAMOUVEMENTDETAILS_GEN_2_V
CREATE OR REPLACE FORCE VIEW "COMPTAMOUVEMENTDETAILS_GEN_2_V" ("ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO","COURSDEVISE","MONTANTDEVISE","COMPTEINT") AS
SELECT
    "ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO","COURSDEVISE","MONTANTDEVISE","COMPTEINT"
FROM
    COMPTA_MOUVEMENT_DETAILS_GEN_2 cmdg
WHERE cmdg.etat = 11
;
-- [175/1309] COMPTA_SOUS_ECRITURE_ANAL
CREATE OR REPLACE FORCE VIEW "COMPTA_SOUS_ECRITURE_ANAL" ("ID","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO") AS
SELECT cse.id, cse.analytique as compte, cse.debit, cse.credit,cse.libellepiece, cse.remarque,cse.idMere, cse.reference_engagement, cse.compte_aux, lettre.lettre as lettrage,cj.val as journal,cse.exercice, cse.etat,cse.daty, cse.folio FROM COMPTA_SOUS_ECRITURE cse
join COMPTA_JOURNAL_VIEW cj on cj.id = cse.journal
join compta_compte cc on cse.analytique=cc.compte
join compta_type_compte ctc on cc.typecompte=ctc.id
left join COMPTA_LETTRAGE lettre on lettre.id = cse.lettrage
;
-- [176/1309] COMPTA_SOUS_ECRITURE_CSEMF
CREATE OR REPLACE FORCE VIEW "COMPTA_SOUS_ECRITURE_CSEMF" ("ID","COMPTE","DEBIT","CREDIT","REMARQUE","LIBELLEPIECE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO","ANALYTIQUE","SOURCE","ORIGINE","MONTANT") AS
SELECT 
    CSE.ID,
    CSE.COMPTE,
    CSE.DEBIT,
    CSE.CREDIT,
    CSE.REMARQUE,
    CSE.LIBELLEPIECE,
    CSE.IDMERE,
    CSE.REFERENCE_ENGAGEMENT,
    CSE.COMPTE_AUX,
    CSE.LETTRAGE,
    CSE.JOURNAL,
    CSE.EXERCICE,
    CSE.ETAT,
    CSE.DATY,
    CSE.FOLIO,
    CSE.ANALYTIQUE,
    CSE.SOURCE,
    CE.ORIGINE,
     CASE
        WHEN NVL(CSE.DEBIT, 0) = 0 THEN CSE.CREDIT
        WHEN NVL(CSE.CREDIT, 0) = 0 THEN CSE.DEBIT
        ELSE CSE.DEBIT - CSE.CREDIT
    END AS MONTANT
FROM COMPTA_SOUS_ECRITURE CSE
LEFT JOIN COMPTA_ECRITURE CE
    ON CE.ID = CSE.IDMERE
;
-- [177/1309] COMPTA_SOUS_ECRITURE_GEN
CREATE OR REPLACE FORCE VIEW "COMPTA_SOUS_ECRITURE_GEN" ("ID","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO") AS
SELECT cse.id, cse.compte, cse.debit, cse.credit,cse.libellepiece, cse.remarque,cse.idMere, cse.reference_engagement, cse.compte_aux, lettre.lettre as lettrage,cj.val as journal,cse.exercice, cse.etat,cse.daty, cse.folio FROM COMPTA_SOUS_ECRITURE cse
join COMPTA_JOURNAL_VIEW cj on cj.id = cse.journal
join compta_compte cc on cse.compte=cc.compte
join compta_type_compte ctc on cc.typecompte=ctc.id
left join COMPTA_LETTRAGE lettre on lettre.id = cse.lettrage
;
-- [178/1309] CONFIGPOIDS_LIB
CREATE OR REPLACE FORCE VIEW "CONFIGPOIDS_LIB" ("ID","POIDSMIN","POIDSMAX","PAS") AS
SELECT '1' AS "ID",
       1.0   AS "POIDSMIN",
       1.0   AS "POIDSMAX",
       1.0   AS "PAS"
FROM DUAL
;
-- [179/1309] CONF_CNAPS
CREATE OR REPLACE FORCE VIEW "CONF_CNAPS" ("PLAFOND","DATY") AS
SELECT
    ROUND(configuration.valmin * 1000, 2) AS plafond,
    NVL(configuration.daty, SYSDATE) AS daty
FROM configcnaps_plafond configuration
WHERE configuration.remarque = 'cnaps_plafond'
ORDER BY NVL(configuration.daty, SYSDATE)
;
-- [180/1309] CONGEPRIS
CREATE OR REPLACE FORCE VIEW "CONGEPRIS" ("ID","IDPERSONNEL","IDTYPEDEMANDE","TITRE","HORAIRENORMAL","HEUREDEPART","HEUREARRIVE","IDTYPEABSENCE","MOTIF","NUMERO","DESCE","ETAT","DATY","DUREE","DATEDEPART","DATERETOUR","OBSERVATION","REMARQUE","IDREMPLACENTS","RESTE_CONGE","DATEFIN") AS
SELECT demande.id,
       demande.idpersonnel,
       demande.idtypedemande,
       demande.titre,
       demande.horairenormal,
       demande.heuredepart,
       demande.heurearrive,
       demande.idtypeabsence,
       demande.motif,
       demande.numero,
       demande.desce,
       demande.etat,
       demande.daty,
       demande.duree,
       demande.datedepart,
       demande.dateretour,
       demande.observation,
       demande.remarque,
       demande.idremplacents,
       demande.reste_conge,
       demande.datefin
FROM demande
WHERE demande.etat = 11 AND demande.idtypeabsence = 'TYP000004'
;
-- [181/1309] CONGEPRISGROUPBYPERS
CREATE OR REPLACE FORCE VIEW "CONGEPRISGROUPBYPERS" ("IDPERSONNEL","CONGE") AS
SELECT congepris.idpersonnel,
       sum(congepris.duree) AS conge
FROM congepris
GROUP BY congepris.idpersonnel
;
-- [182/1309] CONSOMMABLEMACHINELIB
CREATE OR REPLACE FORCE VIEW "CONSOMMABLEMACHINELIB" ("ID","IDMACHINE","IDCONSOMMABLE","IDTYPEMAINTENANCE","QTE","IDUNITE","FREQUENCE","IDTYPEMAINTENANCELIB","IDMACHINELIB","IDCONSOMMABLELIB","IDUNITELIB","FREQUENCELIB") AS
SELECT
    c."ID",c."IDMACHINE",c."IDCONSOMMABLE",c."IDTYPEMAINTENANCE",c."QTE",c."IDUNITE",c."FREQUENCE",
    tm.VAL AS idTypeMaintenanceLib,
    aim.LIBELLE AS idMachineLib,
    ai.LIBELLE AS idConsommableLib,
    u.VAL AS idUniteLib,
    fr.VAL AS frequenceLib
FROM CONSOMMABLEMACHINE c
         LEFT JOIN TYPEMAINTENANCE tm ON tm.ID = c.IDTYPEMAINTENANCE
         LEFT JOIN UNITEMAINTENANCE fr ON fr.ID = c.frequence
         LEFT JOIN AS_INGREDIENTS ai ON ai.ID = c.idConsommable
         LEFT JOIN AS_UNITE u ON u.ID = c.idUnite
         LEFT JOIN AS_INGREDIENT_MAINTENANCE aim ON aim.ID = c.IDMACHINE
;
-- [183/1309] CONSOMMATIONDETAILSLIB
CREATE OR REPLACE FORCE VIEW "CONSOMMATIONDETAILSLIB" ("ID","IDMERE","IDINGREDIENTS","QTE","IDUNITE","IDUNITELIB","IDINGREDIENTSLIB") AS
SELECT
    c."ID",c."IDMERE",c."IDINGREDIENTS",c."QTE",c."IDUNITE",
    au.VAL AS idUniteLib,
    ai.LIBELLE AS idIngredientsLib
FROM CONSOMMATIONDETAILS c
         LEFT JOIN AS_UNITE au ON au.ID = c.IDUNITE
         LEFT JOIN AS_INGREDIENTS ai ON ai.ID = c.IDINGREDIENTS
;
-- [184/1309] CONSOMMATIONLIB
CREATE OR REPLACE FORCE VIEW "CONSOMMATIONLIB" ("ID","DATY","IDTYPEMAINTENANCE","IDMACHINE","DESCE","ETAT","IDTYPEMAINTENANCELIB","IDMACHINELIB","ETATLIB") AS
SELECT
    c."ID",c."DATY",c."IDTYPEMAINTENANCE",c."IDMACHINE",c."DESCE",c."ETAT",
    tm.VAL AS idTypeMaintenanceLib,
    aim.LIBELLE AS idMachineLib,
    CASE
        WHEN c.ETAT = 1 THEN 'CR&Eacute;&Eacute;E'
        WHEN c.ETAT = 11 THEN 'VIS&Eacute;E'
        WHEN c.ETAT = 0 THEN 'ANNUL&Eacute;E'
        END AS ETATLIB
FROM CONSOMMATION c
         LEFT JOIN TYPEMAINTENANCE tm ON tm.ID = c.IDTYPEMAINTENANCE
         LEFT JOIN AS_INGREDIENT_MAINTENANCE aim ON aim.ID = c.IDMACHINE
;
-- [185/1309] CV_LIB
CREATE OR REPLACE FORCE VIEW "CV_LIB" ("ID","NOMCANDIDAT","PRENOMCANDIDAT","TITRECV","RESUMEPROFIL","DATY","IDFICHEPOSTE","IDFICHEPOSTELIB","ETATLIB") AS
SELECT
    c.ID,c.NOMCANDIDAT,c.PRENOMCANDIDAT,c.TITRECV,c.RESUMEPROFIL,c.DATY,c.IDFICHEPOSTE,
    f.TITRE AS idFichePosteLib,
    CASE
        WHEN f.ETAT = '1'  THEN 'Cree'
        WHEN f.ETAT = '11' THEN 'Valide'
        WHEN f.ETAT = '0'  THEN 'Annule'
        ELSE 'Inconnu'
    END AS ETATLIB
FROM CV c
LEFT JOIN FICHE_POSTE f ON f.ID = c.IDFICHEPOSTE
;
-- [186/1309] DECALAGEPREVISION
CREATE OR REPLACE FORCE VIEW "DECALAGEPREVISION" ("ID","IDPREVISION","DEBIT","CREDIT","DATYNOUVEAU") AS
SELECT 
    ' ' AS id,
    ' ' AS idPrevision,
    CAST(0 AS NUMBER(30,2)) AS debit,
    CAST(0 AS NUMBER(30,2)) AS credit,
    CAST(null AS DATE) AS datyNouveau 
FROM dual
;
-- [187/1309] DECLARATIONTVA_VIDE
CREATE OR REPLACE FORCE VIEW "DECLARATIONTVA_VIDE" ("ID","DESIGNATION","DATYDEBUT","DATYFIN","ETAT","MOIS","ANNEE") AS
SELECT
	dtva.id,
	dtva.designation,
	dtva.datydebut,
	dtva.datyfin,
	dtva.etat,
	0 AS mois,
	0 AS annee
FROM
	DECLARATIONTVA dtva
;
-- [188/1309] DEMANDETRANSFERTFILLECPL
CREATE OR REPLACE FORCE VIEW "DEMANDETRANSFERTFILLECPL" ("ID","IDDEMANDETRANSFERT","IDDEMANDETRANSFERTLIB","IDPRODUIT","IDPRODUITLIB","QUANTITE","TYPESTOCK","UNITE","PU") AS
SELECT
    t.ID ,
    t.IDdemandetransfert ,
    t2.DESIGNATION AS IDdemandetransfertLIB,
    t.IDPRODUIT ,
    p.libelle AS IDPRODUITLIB,
    t.QUANTITE,
    p.TYPESTOCK,
    p.UNITE,
    CAST(p.PU AS NUMBER(30, 5)) AS PU
FROM demandetransfertfille t
         LEFT JOIN demandetransfert t2 ON t2.ID = t.IDdemandetransfert
         LEFT JOIN AS_INGREDIENTS  p ON p.ID = t.IDPRODUIT
;
-- [189/1309] DEMANDETRAVAUX_CPL
CREATE OR REPLACE FORCE VIEW "DEMANDETRAVAUX_CPL" ("ID","IDENTITE","IDSITUATION","IDMACHINE","DATY","DATEBESOIN","PRIORITE","ESTEXISTANT","DESCRIPTION","ETAT","IDDEPARTEMENT","IDENTITELIB","IDSITUATIONLIB","IDMACHINELIB","ESTEXISTANTLIB","ETATLIB","IDDEPARTEMENTMAINTENANCE","IDDEPARTEMENTMAINTENANCELIB","PRIORITELIB","IDDEPARTEMENTLIB","IDOTFILLE","IDTYPEMAINTENANCE","IDTYPEMAINTENANCELIB","PERSONNELLIB","MOTSCLESSS") AS
SELECT SQ.ID,SQ.IDENTITE,SQ.IDSITUATION,SQ.IDMACHINE,SQ.DATY,SQ.DATEBESOIN,SQ.PRIORITE,SQ.ESTEXISTANT,SQ.DESCRIPTION,SQ.ETAT,SQ.IDDEPARTEMENT,SQ.IDENTITELIB,SQ.IDSITUATIONLIB,SQ.IDMACHINELIB,SQ.ESTEXISTANTLIB,SQ.ETATLIB,SQ.IDDEPARTEMENTMAINTENANCE,SQ.IDDEPARTEMENTMAINTENANCELIB,SQ.PRIORITELIB,SQ.IDDEPARTEMENTLIB,SQ.IDOTFILLE,SQ.IDTYPEMAINTENANCE,SQ.IDTYPEMAINTENANCELIB,SQ.PERSONNELLIB,
       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(IDENTITE),'') || ' | ' || NVL(TO_CHAR(IDSITUATION),'') || ' | ' || NVL(TO_CHAR(IDMACHINE),'') || ' | ' || NVL(TO_CHAR(DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(DATEBESOIN,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(PRIORITE),'') || ' | ' || NVL(TO_CHAR(ESTEXISTANT),'') || ' | ' || NVL(TO_CHAR(DESCRIPTION),'') || ' | ' || NVL(TO_CHAR(ETAT),'') || ' | ' || NVL(TO_CHAR(IDDEPARTEMENT),'') || ' | ' || NVL(TO_CHAR(IDENTITELIB),'') || ' | ' || NVL(TO_CHAR(IDSITUATIONLIB),'') || ' | ' || NVL(TO_CHAR(IDMACHINELIB),'') || ' | ' || NVL(TO_CHAR(ESTEXISTANTLIB),'') || ' | ' || NVL(TO_CHAR(ETATLIB),'') || ' | ' || NVL(TO_CHAR(IDDEPARTEMENTMAINTENANCE),'') || ' | ' || NVL(TO_CHAR(IDDEPARTEMENTMAINTENANCELIB),'') || ' | ' || NVL(TO_CHAR(PRIORITELIB),'') || ' | ' || NVL(TO_CHAR(IDDEPARTEMENTLIB),'') || ' | ' || NVL(TO_CHAR(IDOTFILLE),'') || ' | ' || NVL(TO_CHAR(IDTYPEMAINTENANCE),'') || ' | ' || NVL(TO_CHAR(IDTYPEMAINTENANCELIB),'') || ' | ' || NVL(TO_CHAR(PERSONNELLIB),'')) AS MOTSCLESSS
FROM (
         SELECT
             dmd.ID, dmd.IDENTITE, dmd.IDSITUATION, dmd.IDMACHINE, dmd.DATY, dmd.DATEBESOIN, dmd.PRIORITE, dmd.ESTEXISTANT, dmd.DESCRIPTION, dmd.ETAT, dmd.IDDEPARTEMENT,
             e.VAL AS idEntiteLib,
             s.VAL AS idSituationLib,
             m.LIBELLE AS idMachineLib,
             CASE dmd.ESTEXISTANT
                 WHEN 0 THEN 'NON'
                 WHEN 1 THEN 'OUI'
                 ELSE 'Non specifie'
                 END AS estExistantLib,
             CASE dmd.ETAT
                 WHEN 1 THEN 'CR&Eacute;&Eacute;E'
                 WHEN 11 THEN 'VALID&Eacute;E' 
                 ELSE 'CR&Eacute;&Eacute;E'
                 END AS etatLib,
             d.id AS IDDEPARTEMENTMAINTENANCE,
             d.VAL AS IDDEPARTEMENTMAINTENANCELIB,
             pri.val AS prioritelib,
             departement.val AS IDDEPARTEMENTLIB,
             otf.ID AS idOtFille,
             pl.idtypemaintenance AS idtypemaintenance,
             tm.val AS idtypemaintenancelib,
             pers.NOMUSER as personnelLib
         FROM DEMANDETRAVAUX dmd
                  LEFT JOIN ENTITE e ON e.ID = dmd.IDENTITE
                  LEFT JOIN SITUATION s ON s.ID = dmd.IDSITUATION
                  LEFT JOIN AS_INGREDIENT_MAINTENANCE m ON m.ID = dmd.IDMACHINE
                  LEFT JOIN DEPARTEMENTMAINTENANCE d ON d.ID = dmd.IDDEPARTEMENTMAINTENANCE
                  LEFT JOIN PRIORITE pri ON dmd.priorite = pri.ID
                  LEFT JOIN DEPARTEMENT departement ON departement.id = dmd.iddepartement
                  LEFT JOIN ORDRETRAVAUX o ON o.IDBC = dmd.ID
                  LEFT JOIN ORDRETRAVAUXFILLE otf ON otf.IDMERE = o.ID
                  LEFT JOIN PLANNING pl ON pl.id = dmd.idplanning
                  LEFT JOIN TYPEMAINTENANCE tm ON tm.id = pl.idtypemaintenance
                  LEFT JOIN UTILISATEUR pers ON pers.REFUSER = dmd.DEMANDEUR
     ) SQ
;
-- [190/1309] DEMANDETRAVAUX_CPL_NOMBRE
CREATE OR REPLACE FORCE VIEW "DEMANDETRAVAUX_CPL_NOMBRE" ("ID","IDENTITE","IDSITUATION","IDMACHINE","DATY","DATEBESOIN","PRIORITE","ESTEXISTANT","DESCRIPTION","ETAT","IDDEPARTEMENT","IDENTITELIB","IDSITUATIONLIB","IDMACHINELIB","ESTEXISTANTLIB","ETATLIB","IDDEPARTEMENTMAINTENANCE","IDDEPARTEMENTMAINTENANCELIB","PRIORITELIB","IDDEPARTEMENTLIB","IDOTFILLE","QTE") AS
SELECT
    ID,
    IDENTITE,
    IDSITUATION,
    IDMACHINE,
    DATY,
    DATEBESOIN,
    PRIORITE,
    ESTEXISTANT,
    DESCRIPTION,
    ETAT,
    IDDEPARTEMENT,
    IDENTITELIB,
    IDSITUATIONLIB,
    IDMACHINELIB,
    ESTEXISTANTLIB,
    ETATLIB,
    IDDEPARTEMENTMAINTENANCE,
    IDDEPARTEMENTMAINTENANCELIB,
    PRIORITELIB,
    IDDEPARTEMENTLIB,
    IDOTFILLE,
    COUNT(*) AS qte
FROM DEMANDETRAVAUX_CPL
GROUP BY
    ID,
    IDENTITE,
    IDSITUATION,
    IDMACHINE,
    DATY,
    DATEBESOIN,
    PRIORITE,
    ESTEXISTANT,
    DESCRIPTION,
    ETAT,
    IDDEPARTEMENT,
    IDENTITELIB,
    IDSITUATIONLIB,
    IDMACHINELIB,
    ESTEXISTANTLIB,
    ETATLIB,
    IDDEPARTEMENTMAINTENANCE,
    IDDEPARTEMENTMAINTENANCELIB,
    PRIORITELIB,
    IDDEPARTEMENTLIB,
    IDOTFILLE
ORDER BY qte DESC
;
-- [191/1309] DEMANDE_VIDE
CREATE OR REPLACE FORCE VIEW "DEMANDE_VIDE" ("IDPERSONNEL","MATRICULE","IDFONCTION","FONCTIONLIB","IDTYPEDEMANDE","TYPEDEMANDELIB","TITRE","HORAIRENORMAL","IDTYPEABSENCE","TYPEABSENCELIB","NOM","PRENOM","REFUSER","RANGUSER","IDSUP","ANNULER","DUREEFINAL","TETAT","ASIDDIRECTION","DIRECTIONLIB","ETATLIB","DATY") AS
SELECT
    CAST(NULL AS VARCHAR2(100)) AS idpersonnel,
    CAST(NULL AS VARCHAR2(100)) AS matricule,
    CAST(NULL AS VARCHAR2(100)) AS idfonction,
    CAST(NULL AS VARCHAR2(100)) AS fonctionlib,
    CAST(NULL AS VARCHAR2(100)) AS idtypedemande,
    CAST(NULL AS VARCHAR2(100)) AS typedemandelib,
    CAST(NULL AS VARCHAR2(100)) AS titre,
    CAST(NULL AS VARCHAR2(100)) AS horairenormal,
    CAST(NULL AS VARCHAR2(100)) AS idtypeabsence,
    CAST(NULL AS VARCHAR2(100)) AS typeabsencelib,
    CAST(NULL AS VARCHAR2(100)) AS nom,
    CAST(NULL AS VARCHAR2(100)) AS prenom,
    0 AS refuser,
    0 AS ranguser,
    CAST(NULL AS VARCHAR2(100)) AS idsup,
    CAST(NULL AS VARCHAR2(100)) AS annuler,
    CAST(0 AS NUMBER(32, 0)) AS dureefinal,
    0 AS tetat,
    CAST(NULL AS VARCHAR2(100)) AS asiddirection,
    CAST(NULL AS VARCHAR2(100)) AS directionlib,
    CAST(NULL AS VARCHAR2(100)) AS etatlib,
    SYSDATE AS daty
FROM dual
;
-- [192/1309] DEMTRANSFILLEGROUPEMERE
CREATE OR REPLACE FORCE VIEW "DEMTRANSFILLEGROUPEMERE" ("IDDEMANDETRANSFERT","MONTANTQUANTITE") AS
select f.IDDEMANDETRANSFERT,cast(sum(nvl(f.pu*f.QUANTITE,0)) as number(30,2)) as montantQuantite
from DEMANDETRANSFERTFILLE f group by f.IDDEMANDETRANSFERT
;
-- [193/1309] DEPARTEMENT_ACTIF
CREATE OR REPLACE FORCE VIEW "DEPARTEMENT_ACTIF" ("ID","VAL","DESCE","ACTIF") AS
select "ID","VAL","DESCE","ACTIF" from DEPARTEMENT where ACTIF=1
;
-- [194/1309] DEPENSEDIVERSFILLELIB
CREATE OR REPLACE FORCE VIEW "DEPENSEDIVERSFILLELIB" ("ID","IDMERE","IDPRODUIT","DESIGNATION","QUANTITE","PU","IDPRODUITLIB","MONTANT","TVA") AS
SELECT
    d.ID,
    d.IDMERE,
    d.IDPRODUIT,
    d.DESIGNATION,
    d.QUANTITE,
    d.PU,
    ail.LIBELLE AS idProduitLib,
    NVL(d.QUANTITE, 0) * NVL(d.PU, 0) AS montant,
    d.tva
FROM DEPENSEDIVERSFILLE d
LEFT JOIN AS_INGREDIENTS_LIB ail ON d.IDPRODUIT = ail.ID
;
-- [195/1309] DEPENSEDIVERSLIB
CREATE OR REPLACE FORCE VIEW "DEPENSEDIVERSLIB" ("ID","DATY","FOURNISSEUR","REMARQUE","IDMODEPAIEMENT","COMPTECHEQUE","ACHETEUR","IDMAGASIN","IDCATEGORIE","ETAT","FOURNISSEURLIB","IDMODEPAIEMENTLIB","IDMAGASINLIB","IDCATEGORIELIB","ETATLIB","SERVICELIB","IDSECTIONLIB","SERVICE","IDSECTION","MONTANTTOTAL","SURPLUSTOTAL","RENDUTOTAL") AS
SELECT
    d.ID, d.DATY, d.FOURNISSEUR, d.REMARQUE, d.IDMODEPAIEMENT, d.COMPTECHEQUE, d.ACHETEUR, d.IDMAGASIN, d.IDCATEGORIE, d.ETAT,
    f.NOM AS fournisseurLib,
    m.VAL AS IDMODEPAIEMENTLIB,
    m2.val AS idMagasinLib,
    c.VAL AS idCategorieLib,
    CASE
        WHEN d.ETAT = 0 THEN 'ANNUL&Eacute;E'
        WHEN d.ETAT = 1 THEN 'CR&Eacute;&Eacute;E'
        WHEN d.ETAT = 3 THEN 'VIS&Eacute;E par Chef de D&eacutepartement'
        WHEN d.ETAT = 4 THEN 'VIS&Eacute;E par Directeur de D&eacutepartement'
        WHEN d.ETAT = 5 THEN 'VIS&Eacute;E par Le Directeur'
        WHEN d.ETAT = 11 THEN 'VIS&Eacute;E par Contr&ocirc;le'
        END AS etatlib,
    s.LIBELLE AS serviceLib,
    sec.VAL AS idSectionLib,
    d.service,
    d.idSection,
    (SELECT NVL(SUM(NVL(df.QUANTITE, 0) * NVL(df.PU, 0)), 0)
     FROM DEPENSEDIVERSFILLE df
     WHERE df.IDMERE = d.ID
    ) AS montantTotal,
    CASE
        WHEN EXISTS (
            SELECT 1 FROM MOUVEMENTCAISSE mc
            WHERE mc.IDORIGINE = d.ID
               OR mc.IDORIGINE IN (SELECT b.IDFACTUREFOURNISSEUR FROM AS_BONDELIVRAISON b WHERE b.IDDEPENSEDIVERS = d.ID)
        )
            THEN (SELECT NVL(SUM(NVL(mc.DEBIT, 0)), 0)
                  FROM MOUVEMENTCAISSE mc
                  WHERE mc.IDORIGINE = d.ID
                     OR mc.IDORIGINE IN (SELECT b.IDFACTUREFOURNISSEUR FROM AS_BONDELIVRAISON b WHERE b.IDDEPENSEDIVERS = d.ID)
                 ) - (SELECT NVL(SUM(NVL(df.QUANTITE, 0) * NVL(df.PU, 0)), 0)
                      FROM DEPENSEDIVERSFILLE df
                      WHERE df.IDMERE = d.ID)
        ELSE 0
        END AS surplusTotal,
    CASE
        WHEN EXISTS (
            SELECT 1 FROM MOUVEMENTCAISSE mc
            WHERE mc.IDORIGINE = d.ID
               OR mc.IDORIGINE IN (SELECT b.IDFACTUREFOURNISSEUR FROM AS_BONDELIVRAISON b WHERE b.IDDEPENSEDIVERS = d.ID)
        )
            THEN (SELECT NVL(SUM(NVL(mc.CREDIT, 0)), 0)
                  FROM MOUVEMENTCAISSE mc
                  WHERE mc.IDORIGINE = d.ID
                     OR mc.IDORIGINE IN (SELECT b.IDFACTUREFOURNISSEUR FROM AS_BONDELIVRAISON b WHERE b.IDDEPENSEDIVERS = d.ID)
        )
        ELSE 0
        END AS renduTotal
FROM DEPENSEDIVERS d
         LEFT JOIN FOURNISSEUR f ON d.FOURNISSEUR = f.ID
         LEFT JOIN MODEPAIEMENT m ON d.IDMODEPAIEMENT = m.ID
         LEFT JOIN MAGASIN2 m2 ON d.IDMAGASIN = m2.ID
         LEFT JOIN CATEGORIEINGREDIENT c ON d.IDCATEGORIE = c.ID
         LEFT JOIN departementDivers s ON s.id = d.SERVICE
         LEFT JOIN SECTION sec ON sec.ID = d.IDSECTION
;
-- [196/1309] DEPENSEENCAISSEMENT
CREATE OR REPLACE FORCE VIEW "DEPENSEENCAISSEMENT" ("ID","DESIGNATION","IDENCAISSEMENT","DATY","ETAT","MONTANT") AS
SELECT 
cast(' ' AS varchar(255)) AS id,
cast(' ' AS varchar(255)) AS designation,
cast(' ' AS varchar(255)) AS idEncaissement,
cast(NULL AS date) AS daty,
cast(-1 AS int) AS etat,
cast(0 AS NUMBER(30,2)) AS montant
FROM dual
;
-- [197/1309] DEPENSEFAB
CREATE OR REPLACE FORCE VIEW "DEPENSEFAB" ("IDOBJET","IDPRODUIT","ENTREE","SORTIE","PU","MONTANTENTREE","MONTANTSORTIE","IDMERE","ID") AS
select c.IDFABRICATION as idobjet,c.IDINGREDIENTS as IDPRODUIT,cast(0 as number(15,2)) as entree,cast(sum(c.qte) as number (15,2)) as sortie,cast(avg(c.PU) as number(30,2)) as pu,cast(0 as number(30,3)) as montantentree,cast(nvl(avg(c.pu)*sum(c.qte),0) as number(30,3)) as montantsortie,ofile.IDMERE,ofile.id
from charge c
left join fabrication fabb on c.IDFABRICATION=fabb.id
left join OFFILLE ofile on fabb.IDOFFILLE=ofile.ID
where c.etat>=11 group by c.IDFABRICATION, c.IDINGREDIENTS,ofile.IDMERE,ofile.id
;
-- [198/1309] DEPENSEFILLESAISIE
CREATE OR REPLACE FORCE VIEW "DEPENSEFILLESAISIE" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","IDBCDETAIL","DEVISE","IDDEVISE","DESIGNATION","COMPTE","COMPTEANALYTIQUE","LIBELLE","INTITULE","PU","PUHT","TAUXDECHANGE","REMISES","MOIS","ANNEE","QTE","MONTANTPERTEGAIN","DEBIT","CREDIT","TVA","MONTANTTVA") AS
SELECT
    '' AS ID,
    '' AS IDFACTUREFOURNISSEUR,
    '' AS IDPRODUIT,
    '' AS IDBCDETAIL,
    '' AS DEVISE,
    '' AS IDDEVISE,
    '' AS DESIGNATION,
    '' AS COMPTE,
    '' AS COMPTEANALYTIQUE,
    '' AS LIBELLE,
    '' AS INTITULE,
    CAST(NULL AS NUMBER(30, 2)) AS PU,
    CAST(NULL AS NUMBER(30, 2)) AS PUHT,
    CAST(NULL AS NUMBER(30, 2)) AS TAUXDECHANGE,
    CAST(NULL AS NUMBER(30, 2)) AS REMISES,
    CAST(NULL AS NUMBER) AS MOIS,
    CAST(NULL AS NUMBER) AS ANNEE,
    CAST(NULL AS NUMBER(30, 2)) AS QTE,
    CAST(NULL AS NUMBER(30, 2)) AS MONTANTPERTEGAIN,
    CAST(NULL AS NUMBER(30, 2)) AS DEBIT,
    CAST(NULL AS NUMBER(30, 2)) AS CREDIT,
    CAST(NULL AS NUMBER(30, 2)) AS TVA,
    CAST(NULL AS NUMBER(30, 2)) AS MONTANTTVA
FROM DUAL
;
-- [199/1309] DEPENSELIB
CREATE OR REPLACE FORCE VIEW "DEPENSELIB" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDOP","IDORIGINE","DATY","MONTANT","ETAT","ETATLIB") AS
SELECT
    d.ID ,
    d.DESIGNATION ,
    d.IDCAISSE ,
    c.VAL AS IDCAISSELIB,
    d.IDOP ,
    d.IDORIGINE ,
    d.DATY ,
    d.MONTANT ,
    d.ETAT ,
    CASE
        WHEN d.ETAT = 1
            THEN 'CREEE'
        WHEN d.ETAT = 11
            THEN 'VISEE'
        WHEN d.ETAT = 0
            THEN 'ANNULEE'
        END AS ETATLIB
FROM DEPENSE d
         LEFT JOIN CAISSE c ON c.ID = d.IDCAISSE
;
-- [200/1309] DEPENSELIB_ANNULEE
CREATE OR REPLACE FORCE VIEW "DEPENSELIB_ANNULEE" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDOP","IDORIGINE","DATY","MONTANT","ETAT","ETATLIB") AS
SELECT 
d."ID",d."DESIGNATION",d."IDCAISSE",d."IDCAISSELIB",d."IDOP",d."IDORIGINE",d."DATY",d."MONTANT",d."ETAT",d."ETATLIB"
FROM depenseLib d 
WHERE d.ETAT = 0
;
-- [201/1309] DEPENSELIB_CREE
CREATE OR REPLACE FORCE VIEW "DEPENSELIB_CREE" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDOP","IDORIGINE","DATY","MONTANT","ETAT","ETATLIB") AS
SELECT 
d."ID",d."DESIGNATION",d."IDCAISSE",d."IDCAISSELIB",d."IDOP",d."IDORIGINE",d."DATY",d."MONTANT",d."ETAT",d."ETATLIB"
FROM depenseLib d 
WHERE d.ETAT = 1
;
-- [202/1309] DEPENSELIB_VISEE
CREATE OR REPLACE FORCE VIEW "DEPENSELIB_VISEE" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDOP","IDORIGINE","DATY","MONTANT","ETAT","ETATLIB") AS
SELECT 
d."ID",d."DESIGNATION",d."IDCAISSE",d."IDCAISSELIB",d."IDOP",d."IDORIGINE",d."DATY",d."MONTANT",d."ETAT",d."ETATLIB"
FROM depenseLib d 
WHERE d.ETAT = 11
;
-- [203/1309] DEPENSESAISIE
CREATE OR REPLACE FORCE VIEW "DEPENSESAISIE" ("ID","IDFOURNISSEUR","IDMODEPAIEMENT","IDTYPEFACTURE","IDDEVISE","DATY","DATYPREVU","DATEECHEANCEPAIEMENT","ESTPREVU","ETAT","TAUX","DEVISE","DESIGNATION","REFERENCE","IDBC","IDMAGASIN","NUMERO","TYPEACHAT","TYPE_FACTURE","IDOBJET","IDREF","IDDMDACHAT","EXERCICE","PERIODE","LIBELLE","TOTALFACTURE","TYPETVA","TYPEFACTUREFOURNISSEUR","JOUR") AS
SELECT
    '' AS ID,
    '' AS IDFOURNISSEUR,
    '' AS IDMODEPAIEMENT,
    '' AS IDTYPEFACTURE,
    '' AS IDDEVISE,
    CAST(NULL AS DATE) AS DATY,
    CAST(NULL AS DATE) AS DATYPREVU,
    CAST(NULL AS DATE) AS DATEECHEANCEPAIEMENT,
    CAST(NULL AS NUMBER(1)) AS ESTPREVU,
    CAST(NULL AS NUMBER) AS ETAT,
    CAST(NULL AS NUMBER(30, 2)) AS TAUX,
    '' AS DEVISE,
    '' AS DESIGNATION,
    '' AS REFERENCE,
    '' AS IDBC,
    '' AS IDMAGASIN,
    '' AS NUMERO,
    '' AS TYPEACHAT,
    '' AS TYPE_FACTURE,
    '' AS IDOBJET,
    '' AS IDREF,
    '' AS IDDMDACHAT,
    CAST(NULL AS NUMBER) AS EXERCICE,
    '' AS PERIODE,
    '' AS LIBELLE,
    CAST(NULL AS NUMBER(30, 2)) AS TOTALFACTURE,
    '' AS TYPETVA,
    '' AS TYPEFACTUREFOURNISSEUR,
    '' AS JOUR
FROM DUAL
;
-- [204/1309] DEPENSE_MAT_PREM
CREATE OR REPLACE FORCE VIEW "DEPENSE_MAT_PREM" ("DATY","ID","DESIGNATION","QUANTITE","PU","DEPENSE") AS
SELECT 
	f.DATY ,
	ff.idproduit AS id,
	ai.LIBELLE AS designation,
	nvl(sum(ff.qte),0) AS quantite,
	nvl(avg(ff.pu),0) AS pu,
	nvl(sum(ff.qte)*avg(ff.pu),0) AS depense
FROM 
FACTUREFOURNISSEURFILLE ff
LEFT JOIN FACTUREFOURNISSEUR f 
ON f.ID = ff.IDFACTUREFOURNISSEUR 
LEFT JOIN AS_INGREDIENTS ai 
ON ai.ID = ff.idproduit
WHERE f.etat >=11
GROUP BY 
	ff.idproduit, 
	ai.LIBELLE,
	f.DATY
;
-- [205/1309] DEPENSE_VALIDEE
CREATE OR REPLACE FORCE VIEW "DEPENSE_VALIDEE" ("IDORIGINE","DEPENSE") AS
SELECT 
d.IDORIGINE ,
sum(nvl(d.MONTANT,0) ) AS depense
FROM DEPENSE d 
WHERE d.ETAT > 1 
GROUP BY d.IDORIGINE
;
-- [206/1309] DERNIERATTRIBUTIONELEMENT
CREATE OR REPLACE FORCE VIEW "DERNIERATTRIBUTIONELEMENT" ("ID","IDINGREDIENTMAINTENANCE","IDPERSONNEL","DATY","ETATELEMENT","TYPEATTRIBUTION","QTE","ETAT") AS
SELECT ae."ID",ae."IDINGREDIENTMAINTENANCE",ae."IDPERSONNEL",ae."DATY",ae."ETATELEMENT",ae."TYPEATTRIBUTION",ae."QTE",ae."ETAT"
FROM ATTRIBUTIONELEMENT ae
         INNER JOIN (
    SELECT
        IDINGREDIENTMAINTENANCE,
        MAX(DATY) AS max_daty
    FROM ATTRIBUTIONELEMENT
    GROUP BY IDINGREDIENTMAINTENANCE
) derniere ON ae.IDINGREDIENTMAINTENANCE = derniere.IDINGREDIENTMAINTENANCE
    AND ae.DATY = derniere.max_daty
;
-- [207/1309] DERNIER_DEBAUCHE_BY_EMPLOYE
CREATE OR REPLACE FORCE VIEW "DERNIER_DEBAUCHE_BY_EMPLOYE" ("IDLOGPERS","DATEAPPLICATION","IDTYPEDEBAUCHE","DATE_DECISION","DATE_REINTEGRATION","RK","DATEFIN") AS
WITH summary AS (
    SELECT
        p.idlogpers,
        p.dateapplication,
        p.idtypedebauche,
        p.date_decision,
        p.date_reintegration,
        ROW_NUMBER() OVER (PARTITION BY p.idlogpers ORDER BY p.date_decision DESC) AS rk,
        p.datefin
    FROM log_personnel_non_valide p
    WHERE p.idtypedebauche IN (
                               'TYD000013', 'TYD000002', 'TYD000003', 'TYD000004',
                               'TYD000012', 'TYD000014', 'TYD000001'
        )
      AND p.etat >= 11
)
SELECT
    s.idlogpers,
    s.dateapplication,
    s.idtypedebauche,
    s.date_decision,
    s.date_reintegration,
    s.rk,
    s.datefin
FROM summary s
WHERE s.rk = 1
;
-- [208/1309] DERNIER_DEBAUCHE_LPNV
CREATE OR REPLACE FORCE VIEW "DERNIER_DEBAUCHE_LPNV" ("ID","IDLOGPERS","DATEAPPLICATION","IDTYPEDEBAUCHE","ETAT","IDUSER","MOTIF","DATE_REINTEGRATION","DATE_DECISION","REFDECISION","IDAVANCEMENT") AS
SELECT lpnv.id,
       lpnv.idlogpers,
       lpnv.dateapplication,
       lpnv.idtypedebauche,
       lpnv.etat,
       lpnv.iduser,
       lpnv.motif,
       lpnv.date_reintegration,
       lpnv.date_decision,
       lpnv.refdecision,
       lpnv.idavancement
FROM dernier_debauche_by_employe debauche,
     log_personnel_non_valide lpnv
WHERE debauche.idlogpers = lpnv.idlogpers AND debauche.dateapplication = lpnv.dateapplication AND debauche.date_decision = lpnv.date_decision
;
-- [209/1309] DETAILSBONCAISSECPL
CREATE OR REPLACE FORCE VIEW "DETAILSBONCAISSECPL" ("ID","IDCAISSE","IDCAISSELIB","IDPOINT","IDPOINTLIB","DEBIT","CREDIT","IDCLIENT","IDCLIENTLIB","IDPRECISIONDETAILENCAISSEMENT","DATY","REMARQUE","ETAT","ETATLIB") AS
SELECT 
d.ID ,
d.IDCAISSE ,
c.VAL AS IDCAISSELIB,
c.IDPOINT ,
p.VAL AS IDPOINTLIB,
d.DEBIT ,
d.CREDIT ,
d.IDCLIENT ,
c2.NOM AS IDCLIENTLIB,
d.IDPRECISIONDETAILENCAISSEMENT ,
d.DATY ,
d.REMARQUE ,
d.ETAT ,
CASE 
	WHEN d.ETAT = 1 
	THEN 'CREE'
	WHEN d.ETAT = 11
	THEN 'VISEE'
	WHEN d.ETAT = 0 
	THEN 'ANNULEE'
END AS ETATLIB
FROM DETAILSBONCAISSE d 
LEFT JOIN CAISSE c ON c.ID = d.IDCAISSE 
LEFT JOIN POINT p ON p.ID = c.IDPOINT 
LEFT JOIN CLIENT c2 ON c2.ID = d.IDCLIENT
;
-- [210/1309] DETAILS_PAIE_EDITION_PDF
CREATE OR REPLACE FORCE VIEW "DETAILS_PAIE_EDITION_PDF" ("IDPERSONNEL","IDELEMENTPAIE","GAIN","RETENUE","SALAIRE_DE_BASE","TAUX","JUILLET","INDEMNITE_DE_TRANSPORT","INDEMNITEDEPRESENTATIONBRUT","AVANTAGES_EN_NATURE","MONTANT_BRUT","CNAPS_TRAVAILLEUR","BRUTCNAPS","REDUCTIONPOURPERSONNESACHARGE","IRSA","NETAPRESCALCUL","IRSANET","NET_A_PAYER","MOIS","ANNEE","IDEDITION") AS
SELECT paie_edition.idpersonnel,
       paie_edition.idelementpaie,
       paie_edition.gain,
       paie_edition.retenue,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000041' AND cq2.montant IS NOT NULL THEN cq2.montant
           WHEN paie_edition.idelementpaie = 'PR000041' AND cq2.montant IS NULL THEN cq.montant
           ELSE 0
           END AS salaire_de_base,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000041' AND cq2.montant IS NOT NULL THEN cq2.montant
           WHEN paie_edition.idelementpaie = 'PR000041' AND cq2.montant IS NULL THEN cq.montant
           ELSE 0
           END / 30 AS taux,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000041' THEN paie_edition.gain
           ELSE 0
           END AS juillet,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000001' THEN paie_edition.gain
           ELSE 0
           END AS indemnite_de_transport,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000021' THEN paie_edition.gain
           ELSE 0
           END AS indemnitedepresentationbrut,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000201' THEN paie_edition.gain
           ELSE 0
           END AS avantages_en_nature,
       0 AS montant_brut,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000101' THEN paie_edition.retenue
           ELSE 0
           END AS cnaps_travailleur,
       0 AS brutcnaps,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000181' THEN paie_edition.gain
           ELSE 0
           END AS reductionpourpersonnesacharge,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000141' THEN GREATEST(paie_edition.retenue, 3000)
           ELSE 0
           END AS irsa,
       0 AS netaprescalcul,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000141NET' THEN paie_edition.retenue
           ELSE 0
           END AS irsanet,
       CASE
           WHEN paie_edition.idelementpaie = 'PR000210A' THEN paie_edition.gain
           ELSE 0
           END AS net_a_payer,
       paie_edition.mois,
       paie_edition.annee,
       paie_edition.idedition
FROM paie_edition
         JOIN paie_info_personnel pip ON pip.id = paie_edition.idpersonnel
         LEFT JOIN categorie_qualification cq ON cq.idcategorie = pip.idcategorie_paie AND cq.idqualification = pip.idqualification AND cq.remarque = '''' AND cq.etat = 1
         LEFT JOIN categorie_qualification cq2 ON cq2.idcategorie = pip.idcategorie_paie AND cq2.idqualification = pip.idqualification AND cq2.remarque = paie_edition.idpersonnel AND cq2.remarque = pip.id AND cq2.etat = 1
;
-- [211/1309] DIRECTION_LISTE
CREATE OR REPLACE FORCE VIEW "DIRECTION_LISTE" ("IDDIR","LIBELLEDIR","DESCDIR","IDDIRECTEUR","ABBREVDIR") AS
SELECT ''     AS IDDIR,
       'Tous' AS LIBELLEDIR,
       'Tous' AS DESCDIR,
       0      AS IDDIRECTEUR,
       'Tous' AS ABBREVDIR
FROM DUAL

UNION ALL

SELECT "IDDIR","LIBELLEDIR","DESCDIR","IDDIRECTEUR","ABBREVDIR"
FROM DIRECTION
;
-- [212/1309] DISPONIBLITESTOCKOF_VIDE
CREATE OR REPLACE FORCE VIEW "DISPONIBLITESTOCKOF_VIDE" ("IDINGREDIENTS","LIBINGREDIENTS","UNITE","TYPESTOCK","CATEGORIEINGREDIENT","IDMAGASINLIB","QTEAV","QTETOTAL","QUANTITE","RESTE","DATY") AS
SELECT '-'                          AS idIngredients,
       '-'                          AS libIngredients,
       '-'                          AS unite,
       '-'                          AS typestock,
       '-'                          AS categorieingredient,
       '-'                          AS idMagasinLib,
       CAST(0 AS NUMBER(30, 2))     AS qteAv,
       CAST(0 AS NUMBER(30, 2))     AS qteTotal,
       CAST(0 AS NUMBER(30, 2))     AS quantite,
       CAST(0 AS NUMBER(30, 2))     AS reste,
       CAST(NULL AS DATE)            AS daty
FROM DUAL
;
-- [213/1309] DISTRIBUTIONALIMENTDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "DISTRIBUTIONALIMENTDETAIL_LIB" ("ID","IDMERE","IDBATIMENT","IDPARQUET","IDALIMENT","IDLOTSTOCK","QTE","RATIONPARTETE","IDBATIMENTLIB","IDPARQUETLIB","IDALIMENTLIB") AS
SELECT
    dd."ID",dd."IDMERE",dd."IDBATIMENT",dd."IDPARQUET",dd."IDALIMENT",dd."IDLOTSTOCK",dd."QTE",dd."RATIONPARTETE",
    b.nombatiment AS idBatimentLib,
    p.val         AS idParquetLib,
    ai.libelle    AS idAlimentLib
FROM distributionAlimentDetail dd
         LEFT JOIN batiment b ON dd.idBatiment = b.id
         LEFT JOIN parquet p ON dd.idParquet = p.id
         LEFT JOIN as_ingredients ai ON dd.idAliment = ai.id
;
-- [214/1309] DISTRIBUTIONALIMENT_LIB
CREATE OR REPLACE FORCE VIEW "DISTRIBUTIONALIMENT_LIB" ("ID","DATY","IDFERME","IDLOT","IDFERMELIB","IDLOTLIB","IDSOUCHELIB","ETAT","ETATLIB") AS
SELECT
    d.ID,d.DATY,d.IDFERME,d.IDLOT,
    b2.val   AS idFermeLib,
    l.nomLot AS idLotLib,
    s.val AS idSoucheLib,
    d.ETAT AS ETAT,
    CASE d.ETAT
        WHEN 1  THEN 'CREE'
        WHEN 11 THEN 'VALIDE'
        WHEN 0  THEN 'ANULLE'
        END AS ETATLIB
FROM distributionAliment d
         LEFT JOIN magasin2 b2 ON d.idFerme = b2.id
         LEFT JOIN lot l ON d.idLot = l.id
         LEFT JOIN SOUCHE s ON l.idSouche = s.id
;
-- [215/1309] DMDACHATFILLE_LIB
CREATE OR REPLACE FORCE VIEW "DMDACHATFILLE_LIB" ("ID","IDMERE","IDPRODUIT","DESIGNATION","QUANTITE","PU","TVA","QTESTOCK","UNITE","REFERENCE") AS
SELECT
    d."ID",d."IDMERE",d."IDPRODUIT",d."DESIGNATION",d."QUANTITE",d."PU",d."TVA",d."QTESTOCK",
    au.val AS unite, d.REFERENCE
FROM DMDACHATFILLE d
         LEFT JOIN AS_INGREDIENTS ai
                   ON ai.id = d.idproduit
         LEFT JOIN AS_UNITE au
                   ON au.id = ai.UNITE
;
-- [216/1309] DMDACHATFILLE_LIB_PRD
CREATE OR REPLACE FORCE VIEW "DMDACHATFILLE_LIB_PRD" ("ID","IDMERE","IDPRODUIT","DESIGNATION","QUANTITE","PU","TVA","QTESTOCK","UNITE","IDPRODUITLIB") AS
(
select d."ID",d."IDMERE",d."IDPRODUIT",d."DESIGNATION",d."QUANTITE",d."PU",d."TVA",d."QTESTOCK",d."UNITE", i.LIBELLE as idproduitLib
from DMDACHATFILLE_LIB d
         join AS_INGREDIENTS i on i.ID = d.IDPRODUIT)
;
-- [217/1309] DMDACHATLIB
CREATE OR REPLACE FORCE VIEW "DMDACHATLIB" ("ID","DATY","FOURNISSEUR","FOURNISSEURLIB","REMARQUE","DATELIMITE","IDMAGASINLIB","IDCATEGORIELIB","ETAT","ETATLIB","IDOBJET","IDSERVICELIB","IDPROVENANCE","IDPROVENANCELIB","SERVICE") AS
SELECT
    da.id,
    da.daty,
    da.fournisseur,
    f.nom AS fournisseurlib,
    da.remarque,
    da.dateLimite,
    m.val AS idMagasinLib,
    ci.val AS idCategorieLib,
    da.etat,
    CASE
        WHEN da.ETAT = 0
            THEN 'ANNULEE'
        WHEN da.ETAT = 1
            THEN 'CREEE'
        WHEN da.ETAT = 3
            THEN 'VISEE par Chef de departement'
        WHEN da.ETAT = 11
            THEN 'VISEE'
        END AS etatlib,
    da.idObjet,
    d.VAL AS idServiceLib,
    da.idProvenance,
    pr.val AS idProvenanceLib,
    da.SERVICE
FROM DMDACHAT da
         LEFT JOIN FOURNISSEUR f ON f.ID = da.fournisseur
         LEFT JOIN MAGASIN2 m ON da.idMagasin = m.ID
         LEFT JOIN categorieIngredient ci ON da.idCategorie = ci.id
         LEFT JOIN DEPARTEMENT d ON da.SERVICE = d.id
         LEFT JOIN provenance pr ON da.idProvenance=pr.id
;
-- [218/1309] DMDACHATSUIVICOMMANDE
CREATE OR REPLACE FORCE VIEW "DMDACHATSUIVICOMMANDE" ("PRODUIT","PRODUITDESIGNATION","IDDMDACHAT","QUANTITEDEMANDE","QUANTITEDEJACOMMANDE","RESTEACOMMANDER") AS
SELECT
    df.IDPRODUIT AS produit,
    df.DESIGNATION AS produitDesignation,
    df.IDMERE AS idDmdAchat,
    df.QUANTITE AS quantiteDemande,
    NVL(bcf_sum.quantiteCommande, 0) AS quantiteDejaCommande,
    df.QUANTITE - NVL(bcf_sum.quantiteCommande, 0) AS resteACommander
FROM DMDACHATFILLE df
LEFT JOIN DMDACHAT d
    ON d.ID = df.IDMERE
LEFT JOIN (
    SELECT
        bc.IDDMDACHAT,
        bcf.PRODUIT,
        SUM(bcf.QUANTITE) AS quantiteCommande
    FROM AS_BONDECOMMANDE bc
    INNER JOIN AS_BONDECOMMANDE_FILLE bcf
        ON bcf.IDBC = bc.ID
    WHERE bc.IDDMDACHAT IS NOT NULL
      AND bcf.PRODUIT IS NOT NULL
      AND bc.ETAT <> 0
    GROUP BY bc.IDDMDACHAT, bcf.PRODUIT
) bcf_sum
    ON bcf_sum.IDDMDACHAT = df.IDMERE
   AND bcf_sum.PRODUIT = df.IDPRODUIT
;
-- [219/1309] DMDACHATSUIVICOMMANDEGROUPEE
CREATE OR REPLACE FORCE VIEW "DMDACHATSUIVICOMMANDEGROUPEE" ("IDDMDACHAT","TOTALCOMMANDE","TOTALRESTE") AS
SELECT d.IDDMDACHAT, sum (d.QUANTITEDEJACOMMANDE ) AS totalCommande , sum (d.RESTEACOMMANDER ) AS totalReste FROM DMDACHATSUIVICOMMANDE d GROUP BY d.IDDMDACHAT
;
-- [220/1309] DMDACHATLIB_TRAITE
CREATE OR REPLACE FORCE VIEW "DMDACHATLIB_TRAITE" ("ID","DATY","FOURNISSEUR","FOURNISSEURLIB","REMARQUE","DATELIMITE","IDMAGASINLIB","IDCATEGORIELIB","ETAT","ETATLIB","IDOBJET","IDSERVICELIB","SERVICE","IDTRAITE","TRAITE","IDPROVENANCE","IDPROVENANCELIB") AS
SELECT
    d.ID,
    d.DATY,
    d.FOURNISSEUR,
    d.FOURNISSEURLIB,
    d.REMARQUE,
    d.DATELIMITE,
    d.IDMAGASINLIB,
    d.IDCATEGORIELIB,
    d.ETAT,
    d.ETATLIB,
    d.IDOBJET,
    d.IDSERVICELIB,
    d.service,
    CASE
        WHEN suivi.totalCommande = 0 THEN '0'
        WHEN suivi.totalReste = 0 THEN '2'
        WHEN suivi.totalReste > 0 AND suivi.totalCommande > 0 THEN '1'
        ELSE '3'
        END AS IDTRAITE,
    CASE
        WHEN suivi.totalCommande = 0 THEN 'Non Trait&eacute;'
        WHEN suivi.totalReste = 0 THEN 'Trait&eacute;'
        WHEN suivi.totalReste > 0 AND suivi.totalCommande > 0 THEN 'Trait&eacute; Partiellement'
        ELSE 'Trait&eacute; avec surplus'
        END AS TRAITE,
    d.idProvenance,
    d.IDPROVENANCELIB
FROM DMDACHATLIB d
LEFT JOIN DMDACHATSUIVICOMMANDEGROUPEE suivi ON d.id = suivi.iddmdachat
;
-- [221/1309] DUREE_CYCLE_FAB
CREATE OR REPLACE FORCE VIEW "DUREE_CYCLE_FAB" ("IDMERE","TEMPS") AS
SELECT 
    off.IDMERE,
    ROUND(SUM(p.ecart) / 60, 2) AS temps 
FROM 
    PROCESS p
    JOIN FABRICATION fab ON fab.id = p.refobjet AND fab.etat >= 11
    JOIN OFFILLE off ON off.id = fab.IDOFFILLE
    JOIN OFAB o ON o.id = off.IDMERE
GROUP BY 
    off.IDMERE
;
-- [222/1309] ECLOSIONDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "ECLOSIONDETAIL_LIB" ("ID","IDMERE","IDQUALITEECLOSION","QTE","REMARQUE","IDQUALITEECLOSIONLIB") AS
SELECT d."ID",
       d."IDMERE",
       d."IDQUALITEECLOSION",
       d."QTE",
       d."REMARQUE",
       qe."VAL" AS "IDQUALITEECLOSIONLIB"
FROM "ECLOSIONDETAIL" d
LEFT JOIN "QUALITEECLOSION" qe ON qe."ID" = d."IDQUALITEECLOSION"
;
-- [223/1309] ECLOSION_LIB
CREATE OR REPLACE FORCE VIEW "ECLOSION_LIB" ("ID","IDLOT","DATEECLOSION","NOMBREOEUFINITIAL","IDECLOSOIR","IDINCUBATEUR","IDBATIMENT","IDPARQUET","ETAT","IDINCUBATEURLIB","IDBATIMENTLIB","IDPARQUETLIB","IDECLOSOIRLIB","ETATLIB") AS
SELECT e."ID",
       e."IDLOT",
       e."DATEECLOSION",
       e."NOMBREOEUFINITIAL",
       e."IDECLOSOIR",
       e."IDINCUBATEUR",
       e."IDBATIMENT",
       e."IDPARQUET",
       e."ETAT",
       inc."VAL"       AS "IDINCUBATEURLIB",
       b."NOMBATIMENT" AS "IDBATIMENTLIB",
       p."VAL"         AS "IDPARQUETLIB",
       ec."VAL"        AS "IDECLOSOIRLIB",
       CASE e."ETAT"
           WHEN 1  THEN 'CREE'
           WHEN 11 THEN 'VALIDE'
           WHEN 0  THEN 'ANULLE'
           END              AS "ETATLIB"
FROM "ECLOSION" e
         LEFT JOIN "INCUBATEUR" inc ON inc."ID" = e."IDINCUBATEUR"
         LEFT JOIN "BATIMENT" b ON b."ID" = e."IDBATIMENT"
         LEFT JOIN "PARQUET" p ON p."ID" = e."IDPARQUET"
         LEFT JOIN ECLOSOIR ec ON ec.ID = e.IDECLOSOIR
;
-- [224/1309] ECRITURE_IMPOT
CREATE OR REPLACE FORCE VIEW "ECRITURE_IMPOT" ("ID","COMPTE","DEBIT","CREDIT","REMARQUE","LIBELLEPIECE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO","ANALYTIQUE","SOURCE","DATYMERE","CODEIMPOT","MOISDECLARATION") AS
select
    se.ID,
    se.COMPTE,
    se.DEBIT,
    se.CREDIT,
    se.REMARQUE,
    se.LIBELLEPIECE,
    se.IDMERE,
    se.REFERENCE_ENGAGEMENT,
    se.COMPTE_AUX,
    se.LETTRAGE,
    se.JOURNAL,
    se.EXERCICE,
    se.ETAT,
    se.DATY,
    se.FOLIO,
    se.ANALYTIQUE,
    se.SOURCE,
    ce.daty as datymere,
    cc.COMPTE as codeimpot,
    sed.MOISDECLARATION
from COMPTA_SOUS_ECRITURE se
         join COMPTA_ECRITURE ce on ce.id=se.IDMERE
         join COMPTA_COMPTE cc on cc.COMPTE=se.COMPTE
         JOIN SOUSECRITUREDECLARER sed ON sed.IDSOUSECRITURE = se.ID
;
-- [225/1309] ELEMENTINSPECTIONMACHINELIB
CREATE OR REPLACE FORCE VIEW "ELEMENTINSPECTIONMACHINELIB" ("ID","IDELEMENTINSPECTION","IDMACHINE","IDELEMENTINSPECTIONLIB","IDMACHINELIB","MOTSCLESSS") AS
SELECT SQ.ID,SQ.IDELEMENTINSPECTION,SQ.IDMACHINE,SQ.IDELEMENTINSPECTIONLIB,SQ.IDMACHINELIB,
	       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(IDELEMENTINSPECTION),'') || ' | ' || NVL(TO_CHAR(IDMACHINE),'') || ' | ' || NVL(TO_CHAR(IDELEMENTINSPECTIONLIB),'') || ' | ' || NVL(TO_CHAR(IDMACHINELIB),'')) AS MOTSCLESSS
	FROM (
	         SELECT
	             eim.id,
	             eim.idElementInspection as idElementInspection,
	             eim.idMachine as idMachine,
	             ei.val      AS idElementInspectionLib,
	             m.DESCRIPTIONOBJET       AS idMachineLib
	         FROM ElementInspectionMachine eim
	                  LEFT JOIN ElementInspection ei
	                            ON eim.idElementInspection = ei.id
	                  LEFT JOIN AS_INGREDIENT_MAINTENANCE m
	                            ON eim.idMachine = m.id
	
	     ) SQ
;
-- [226/1309] EMPLOYEEONBOARDINGCHECKLISTCPL
CREATE OR REPLACE FORCE VIEW "EMPLOYEEONBOARDINGCHECKLISTCPL" ("ID","IDSESSIONONBOARDING","IDONBOARDINGITEM","ESTTERMINER","DATEFIN","REMARQUE","ESTTERMINERLIB","IDSESSION","PROGRESSION","ETAT","ETATLIB","IDONBOARDINGITEMLIB") AS
SELECT
    c.ID,c.IDSESSIONONBOARDING,c.IDONBOARDINGITEM,c.ESTTERMINER,c.DATEFIN,c.REMARQUE,
    CASE
        WHEN c.estTerminer = 0 THEN 'Non'
        WHEN c.estTerminer = 1 THEN 'Oui'
        END AS estTerminerLib,

    s.id AS idSession,
    s.progression,
    s.etat,
    CASE
        WHEN s.etat = 1  THEN 'En cours'
        WHEN s.etat = 11 THEN 'Termine'
        END AS etatlib,

    ofi.titre AS idOnboardingItemlib

FROM employee_onboarding_checklist c
         JOIN employee_onboarding_sessions s
              ON c.idSessionOnboarding = s.id
         JOIN onboarding_fille ofi
              ON c.idOnboardingItem = ofi.id
;
-- [227/1309] EMPLOYE_COMPLET
CREATE OR REPLACE FORCE VIEW "EMPLOYE_COMPLET" ("ID","NOM","PRENOM","ID_PERS","INITIALE","MATRICULE","DATE_NAISSANCE","LIEU_NAISSANCE_COMMUNE","SEXE","NUMERO_CIN","DATE_CIN","DATE_DUPL_CIN","LIEU_DELIVRANCE_CIN","ADRESSE","DIRECTION","FOKOTANY","NATIONALITE","ACTE_NAISSANCE","SITUATION_MATRIMONIAL","IDCONJOINT","SERVICE","IDFONCTION","CTG","IDCATEGORIE","CLASSEE","INDICEGRADE","INDICE_FONCTIONNEL","MATRICULE_PATRON","STATUT","MODE_PAIEMENT","CODE_AGENCE_BANQUE","BANQUE_NUMERO_COMPTE","BANQUE_COMPTE_CLE","PERMIS_CONDUIRE","REMARQUE","CHEMIN_PERMIS","CTURGENCE_NOM_PRENOM","CTURGENCE_TELEPHONE1","CTURGENCE_TELEPHONE2","CTURGENCE_TELEPHONE3","DATEEMBAUCHE","DATESAISIE","CODE_DR","BANQUE_CODE","ECHELON","ETAT","VEHICULEE","DATE_DERNIERPROMO","DROIT_HS","HEUREJOURNALIER","HEUREHEBDOMADAIRE","HEUREMENSUEL","NUMERO_CNAPS","NUMERO_OSTIE","TEMPORAIRE","NBENFANT","INDESIRABLE","DUREE","TELEPHONE","MAIL","IDCATEGORIE_PAIE","IDQUALIFICATION","DISCIPLINE","FORMATION","ANNEEEXPERIENCE","PERSONNEL_ETAT","DEBUTCONTRAT","FINCONTRAT","REFUSER","IDETATHIERARCHIE","ETATVISA","ETATANNULE","TYPECONTRAT","CHEMINIMAGE","CODE_POSTAL","IDDEPARTEMENT","MERE","PERE","IDCIVILITELIB","IDCIVILITE","IDBANQUE","IDBANQUELIB","IDAGENCE","CODEAGENCE","IDAGENCELIB","IDSTATUT","IDSTATUTLIB","UNITE","RETRAITECOMPL") AS
SELECT logp.id,
       logp.nom,
       logp.prenom,
       logp.id_pers,
       paie.initiale,
       paie.matricule,
       logp.date_naissance,
       paie.lieu_naissance_commune,
       logp.sexe,
       logp.numero_cin,
       logp.date_cin,
       logp.date_dupl_cin,
       paie.lieu_delivrance_cin,
       logp.adresse,
       logp.direction,
       logp.fokotany,
       logp.nationalite,
       logp.acte_naissance,
       paie.situation_matrimonial,
       paie.idconjoint,
       logp.service,
       paie.idfonction,
       paie.ctg,
       paie.idcategorie,
       paie.classee,
       paie.indicegrade,
       paie.indice_fonctionnel,
       paie.matricule_patron,
       paie.statut,
       paie.mode_paiement,
       paie.code_agence_banque,
       paie.banque_numero_compte,
       paie.banque_compte_cle,
       logp.permis_conduire,
       logp.remarque,
       logp.chemin_permis,
       paie.cturgence_nom_prenom,
       paie.cturgence_telephone1,
       paie.cturgence_telephone2,
       paie.cturgence_telephone3,
       paie.dateembauche,
       paie.datesaisie,
       serv.code_dr,
       trs.val AS banque_code,
       paie.echelon,
       paie.etat,
       paie.vehiculee,
       tab.date_dernierpromo,
       paie.droit_hs,
       paie.heurejournalier,
       paie.heurehebdomadaire,
       paie.heuremensuel,
       paie.numero_cnaps,
       paie.numero_ostie,
       paie.temporaire,
       paie.nbenfant,
       paie.indesirable,
       paie.duree,
       paie.telephone,
       paie.mail,
       paie.idcategorie_paie,
       paie.idqualification,
       paie.discipline,
       paie.formation,
       paie.anneeexperience,
       paie.personnel_etat,
       paie.debutcontrat,
       paie.fincontrat,
       logp.refuser,
       logp.idhierarchie AS idetathierarchie,
       et.etatvisa,
       et.etatannule,
       paie.typecontrat,
       logp.cheminImage,
       paie.code_postal,
       paie.IDDEPARTEMENT,
       logp.mere,
       logp.pere,
       civ.val as idcivilitelib,
       logp.IDCIVILITE,
       paie.idbanque,
       bnq.val as idbanquelib,
       paie.idagence,
       bnqa.codeagence,
       bnqa.nom as idagencelib,
       paie.idstatut,
       stat.val as idStatutLib,
       paie.unite,
       paie.retraiteCompl
FROM log_personnel logp
         LEFT JOIN ( SELECT paie_avancement.id_logpers,
                            max(paie_avancement.datedecision) AS date_dernierpromo
                     FROM paie_avancement
                     GROUP BY paie_avancement.id_logpers) tab ON logp.id = tab.id_logpers
         LEFT JOIN paie_info_personnel paie ON logp.id = paie.id
         LEFT JOIN log_service serv ON serv.id = logp.service
         LEFT JOIN trs_banques_agences trs ON paie.code_agence_banque = trs.id
         LEFT JOIN categorie_paie cp ON cp.id = paie.idcategorie_paie
         LEFT JOIN qualification_paie qp ON qp.id = paie.idqualification
         LEFT JOIN categorie_qualification cq ON cq.idcategorie = paie.idcategorie_paie AND cq.idqualification = paie.idqualification AND cq.REMARQUE = logp.id
         LEFT JOIN etathierarchie et ON et.id = logp.idhierarchie
         LEFT JOIN civilite civ ON logp.idcivilite = civ.id
         LEFT JOIN banque bnq ON bnq.id = paie.idbanque
         LEFT JOIN BANQUE_AGENCE bnqa ON bnqa.id = paie.idagence
         LEFT JOIN PAIE_STATUT stat ON stat.id = paie.idStatut
;
