-- [229/1309] EMPLOYE_COMPLET_LIBELLE2
CREATE OR REPLACE FORCE VIEW "EMPLOYE_COMPLET_LIBELLE2" ("ID","NOM","PRENOM","ID_PERS","INITIALE","MATRICULE","DATE_NAISSANCE","LIEU_NAISSANCE_COMMUNE","SEXE","NUMERO_CIN","DATE_CIN","DATE_DUPL_CIN","LIEU_DELIVRANCE_CIN","ADRESSE","DIRECTION","FOKOTANY","NATIONALITE","ACTE_NAISSANCE","SITUATION_MATRIMONIAL","IDCONJOINT","SERVICE","IDFONCTION","CTG","IDCATEGORIE","CLASSEE","INDICEGRADE","INDICE_FONCTIONNEL","MATRICULE_PATRON","STATUT","MODE_PAIEMENT","CODE_AGENCE_BANQUE","BANQUE_COMPTE_CLE","BANQUE_NUMERO_COMPTE","PERMIS_CONDUIRE","REMARQUE","CHEMIN_PERMIS","CTURGENCE_NOM_PRENOM","CTURGENCE_TELEPHONE1","CTURGENCE_TELEPHONE2","CTURGENCE_TELEPHONE3","DATEEMBAUCHE","DATESAISIE","CODE_DR","BANQUE_CODE","ECHELON","VEHICULEE","VEHICULEE_STR","DATE_DERNIERPROMO","HEUREJOURNALIER","HEUREHEBDOMADAIRE","HEUREMENSUEL","NUMERO_CNAPS","NUMERO_OSTIE","TEMPORAIRE","TEMPORAIRE_LIB","IDSTATUT","IDSTATUTLIB","NBENFANT","MOTIF_DEBAUCHE","TYPE_DEBAUCHE","ADRESSE_LIGNE1","ADRESSE_LIGNE2","MAIL","TELEPHONE","CODE_POSTAL","REGION","ANNEEEXPERIENCE","FORMATION","DISCIPLINE","ETAT","CATEGORIEPAIELIB","IDDEPARTEMENT","IDDEPARTEMENTLIB","IDCATEGORIE_PAIE","IDQUALIFICATION","SALAIREBASE","TAUXHORAIRE") AS
SELECT logp.id,
       logp.nom,
       logp.prenom,
       logp.id_pers,
       paie.initiale,
       paie.matricule AS matricule,
       logp.date_naissance,
       paie.lieu_naissance_commune,
       s.desce AS sexe,
       logp.numero_cin,
       logp.date_cin,
       logp.date_dupl_cin,
       paie.lieu_delivrance_cin,
       logp.adresse,
       ld.val AS direction,
       sf.val AS fokotany,
       p.val AS nationalite,
       logp.acte_naissance,
       sitmat.desce AS situation_matrimonial,
       paie.idconjoint,
       serv.libelle AS service,
       pf.desce AS idfonction,
       paie.ctg,
       pc.val AS idcategorie,
       paie.classee,
       paie.indicegrade,
       paie.indice_fonctionnel,
       paie.matricule_patron,
       paie.statut,
       pm.val AS mode_paiement,
       paie.code_agence_banque,
       paie.banque_compte_cle,
       paie.banque_numero_compte,
       logp.permis_conduire,
       logp.remarque,
       logp.chemin_permis,
       paie.cturgence_nom_prenom,
       paie.cturgence_telephone1,
       paie.cturgence_telephone2,
       paie.cturgence_telephone3,
       paie.dateembauche,
       paie.datesaisie,
       serv.code_dr,
       trs.val AS banque_code,
       paie.echelon,
       paie.vehiculee,
       CASE paie.vehiculee
           WHEN 0 THEN 'non'
           WHEN 1 THEN 'oui'
           ELSE NULL
           END AS vehiculee_str,
       tab.date_dernierpromo,
       paie.heurejournalier,
       paie.heurehebdomadaire,
       paie.heuremensuel,
       paie.numero_cnaps,
       paie.numero_ostie,
       paie.temporaire,
       CASE
           WHEN paie.temporaire = '-1' THEN 'Temporaire'
           WHEN paie.temporaire = 0 THEN 'Permanent'
           WHEN paie.temporaire = 1 THEN 'Cadre'
           ELSE NULL
           END AS temporaire_lib,
       paie.idStatut,
       stat.val as idStatutLib,
       paie.nbenfant,
       lpnv.motif AS motif_debauche,
       ddt.val AS type_debauche,
       paie.adresse_ligne1,
       paie.adresse_ligne2,
       paie.mail,
       paie.telephone,
       paie.code_postal,
       reg.val AS region,
       paie.anneeexperience,
       fd.val AS formation,
       paie.discipline,
       paie.etat,
       cp.DESCE AS categoriePaieLib,
       paie.iddepartement AS iddepartement,
       dep.val AS iddepartementlib,
       paie.IDCATEGORIE_PAIE,
       paie.IDQUALIFICATION,
       paie.SALAIREBASE,
       paie.SALAIREBASE / 173.33 as tauxHoraire
FROM log_personnel logp
         LEFT JOIN ( SELECT paie_avancement.id_logpers,
                            max(paie_avancement.datedecision) AS date_dernierpromo
                     FROM paie_avancement
                     GROUP BY paie_avancement.id_logpers) tab ON logp.id = tab.id_logpers
         LEFT JOIN paie_info_personnel paie ON logp.id = paie.id
         LEFT JOIN log_service serv ON serv.id = logp.service
         LEFT JOIN trs_banques_agences trs ON paie.code_agence_banque = trs.id
         LEFT JOIN sexe s ON logp.sexe = s.id
         LEFT JOIN sig_fokontany sf ON logp.fokotany = sf.id
         LEFT JOIN pays p ON logp.nationalite = p.id
         LEFT JOIN log_direction ld ON logp.direction = ld.id
         LEFT JOIN paie_fonction pf ON paie.idfonction = pf.id
         LEFT JOIN paie_categorie pc ON paie.idcategorie = pc.id
         LEFT JOIN modepaiement pm ON paie.mode_paiement = pm.id
         LEFT JOIN situation_matrimoniale sitmat ON paie.situation_matrimonial = sitmat.id
         LEFT JOIN log_personnel_non_valide lpnv ON logp.id = lpnv.idlogpers
         LEFT JOIN dec_decision_type ddt ON lpnv.idtypedebauche = ddt.id
         LEFT JOIN region reg ON reg.id = paie.region
         LEFT JOIN formation_diplome fd ON fd.id = paie.formation
         LEFT JOIN categorie_paie cp ON paie.IDCATEGORIE_PAIE = cp.id
         LEFT JOIN DEPARTEMENT dep ON dep.id=paie.iddepartement
         LEFT JOIN PAIE_STATUT stat ON stat.id = paie.IDSTATUT
WHERE logp.id <> '1002067'
;
-- [230/1309] DEMANDE_REMPLACENTS
CREATE OR REPLACE FORCE VIEW "DEMANDE_REMPLACENTS" ("ID","REMPLACENTS") AS
SELECT d.id,
       LISTAGG(t.nom || ' ' || t.prenom, '   ,    ') WITHIN GROUP (ORDER BY t.nom) AS remplacents
FROM demande d
    LEFT JOIN employe_complet_libelle2 t ON INSTR(d.idremplacents, t.id) > 0
GROUP BY d.id
;
-- [231/1309] DEMANDE_LIBCOMPLET
CREATE OR REPLACE FORCE VIEW "DEMANDE_LIBCOMPLET" ("ID","IDPERSONNEL","MATRICULE","IDFONCTION","FONCTIONLIB","IDTYPEDEMANDE","TYPEDEMANDELIB","TITRE","HORAIRENORMAL","HEUREDEPART","HEUREARRIVE","IDTYPEABSENCE","TYPEABSENCELIB","MOTIF","NUMERO","DESCE","ETAT","DATY","DUREE","DATEDEPART","DATERETOUR","OBSERVATION","REMARQUE","NOM","PRENOM","IDDIRECTION","DIRECTIONLIB","ETATLIB","REFUSER","RANGUSER","IDREMPLACENTS","REMPLACENTS","MATRICULES","DATEFIN","PERSONNEL","IDSUP","AVENANT","ANNULER","SUPERIEUR","MOTIFREFU","WEEKENDDECOMPTELIB","IDDEPARTEMENT","DEPARTEMENTLIB") AS
SELECT d.id,
	       d.idpersonnel,
	       pip.matricule,
	       pip.idfonction,
	       pf.val AS fonctionlib,
	       d.idtypedemande,
	       t.val AS typedemandelib,
	       d.titre,
	       d.horairenormal,
	       d.heuredepart,
	       d.heurearrive,
	       d.idtypeabsence,
	       t2.desce AS typeabsencelib,
	       d.motif,
	       d.numero,
	       d.desce,
	       d.etat,
	       d.daty,
	       d.duree,
	       d.datedepart,
	       d.dateretour,
	       d.observation,
	       d.remarque,
	       lp.nom,
	       lp.prenom,
	       lp.direction AS iddirection,
	       ld.val AS directionlib,
	       CASE
	           WHEN d.etat = 1 THEN 'Cree'
	           WHEN d.etat = 11 THEN 'Valide'
	           WHEN d.etat = -1 THEN 'Refusee'
	           ELSE 'AUTRE'
	           END AS etatlib,
	       u.refuser,
	       r.rang AS ranguser,
	       d.idremplacents,
	       rmp.remplacents,
	       pip.matricule AS matricules,
	       d.datefin,
	       (lp.nom || ' ') || lp.prenom AS personnel,
	       lp.idsup,
	       d.avenant,
	       CASE
	           WHEN d.avenant IS NOT NULL THEN 'OUI'
	           ELSE NULL
	           END AS annuler,
	       (pl.nom || ' ') || pl.prenom AS superieur,
	       d.MOTIFREFU,
	       CASE WHEN
	                WEEKENDDECOMPTE = 1 THEN 'OUI'
	            WHEN WEEKENDDECOMPTE = 0 THEN 'NON'
	           END AS weekendDecompteLib,
	       d.IDDEPARTEMENT,
	       dp.DESCE as departementLib
	FROM demande d
	         LEFT JOIN paie_info_personnel pip ON d.idpersonnel = pip.id
	         LEFT JOIN paie_fonction pf ON pf.id = pip.idfonction
	         LEFT JOIN typedemande t ON t.id = d.idtypedemande
	         LEFT JOIN typeabsence t2 ON t2.id = d.idtypeabsence
	         LEFT JOIN log_personnel lp ON lp.id = pip.id
	         LEFT JOIN log_direction ld ON ld.id = lp.direction
	         LEFT JOIN utilisateur u ON u.refuser = lp.refuser
	         LEFT JOIN roles r ON r.idrole = u.idrole
	         LEFT JOIN demande_remplacents rmp ON rmp.id = d.id
	         LEFT JOIN log_personnel pl ON pl.id = lp.idsup
	         LEFT JOIN DEPARTEMENT dp ON dp.id = d.IDDEPARTEMENT
;
-- [232/1309] CONGECOLLECTIF_LIB
CREATE OR REPLACE FORCE VIEW "CONGECOLLECTIF_LIB" ("ID","IDPERSONNEL","MATRICULE","IDFONCTION","FONCTIONLIB","IDTYPEDEMANDE","TYPEDEMANDELIB","TITRE","HORAIRENORMAL","HEUREDEPART","HEUREARRIVE","IDTYPEABSENCE","TYPEABSENCELIB","MOTIF","NUMERO","DESCE","ETAT","DATY","DUREE","DATEDEPART","DATERETOUR","OBSERVATION","REMARQUE","NOM","PRENOM","IDDIRECTION","DIRECTIONLIB","ETATLIB","REFUSER","RANGUSER","IDREMPLACENTS","REMPLACENTS","MATRICULES","DATEFIN","PERSONNEL","IDSUP","AVENANT","ANNULER","SUPERIEUR","MOTIFREFU","WEEKENDDECOMPTELIB","IDDEPARTEMENT","DEPARTEMENTLIB") AS
SELECT
	ID,
	IDPERSONNEL,
	MATRICULE,
	IDFONCTION,
	FONCTIONLIB,
	IDTYPEDEMANDE,
	TYPEDEMANDELIB,
	TITRE,
	HORAIRENORMAL,
	HEUREDEPART,
	HEUREARRIVE,
	IDTYPEABSENCE,
	TYPEABSENCELIB,
	MOTIF,
	NUMERO,
	DESCE,
	ETAT,
	DATY,
	DUREE,
	DATEDEPART,
	DATERETOUR,
	OBSERVATION,
	REMARQUE,
	NOM,
	PRENOM,
	IDDIRECTION,
	DIRECTIONLIB,
	ETATLIB,
	REFUSER,
	RANGUSER,
	IDREMPLACENTS,
	REMPLACENTS,
	MATRICULES,
	DATEFIN,
	PERSONNEL,
	IDSUP,
	AVENANT,
	ANNULER,
	SUPERIEUR,
	MOTIFREFU,
	WEEKENDDECOMPTELIB,
	IDDEPARTEMENT,
	DEPARTEMENTLIB
FROM
	DEMANDE_LIBCOMPLET
WHERE
	idtypeabsence = 'TYPCOL0004'
;
-- [233/1309] DEMANDE_LIBCOMPLET2
CREATE OR REPLACE FORCE VIEW "DEMANDE_LIBCOMPLET2" ("ID","IDPERSONNEL","MATRICULES","IDFONCTION","FONCTIONLIB","IDTYPEDEMANDE","TYPEDEMANDELIB","TITRE","HORAIRENORMAL","HEUREDEPART","HEUREARRIVE","IDTYPEABSENCE","TYPEABSENCELIB","MOTIF","NUMERO","DESCE","ETAT","DATY","DUREE","DATEDEPART","DATEFIN","DATERETOUR","OBSERVATION","REMARQUE","NOM","PRENOM","PERSONNEL","IDDIRECTION","DIRECTIONLIB","ETATLIB","REFUSER","RANGUSER","IDREMPLACENTS","REMPLACENTS","AVENANT") AS
SELECT d.id,
       d.idpersonnel,
       pip.matricule AS matricules,
       pip.idfonction,
       pf.val AS fonctionlib,
       d.idtypedemande,
       t.val AS typedemandelib,
       d.titre,
       d.horairenormal,
       d.heuredepart,
       d.heurearrive,
       d.idtypeabsence,
       t2.desce AS typeabsencelib,
       d.motif,
       d.numero,
       d.desce,
       d.etat,
       d.daty,
       d.duree,
       d.datedepart,
       d.datefin,
       d.dateretour,
       d.observation,
       d.remarque,
       lp.nom,
       lp.prenom,
       (lp.nom || ' ') || lp.prenom AS personnel,
       lp.direction AS iddirection,
       ld.val AS directionlib,
       CASE
           WHEN d.etat = 1 THEN '<span style="color:green;">CR&Eacute;&Eacute;E</span>'
           WHEN d.etat = 11 THEN '<span style="color:blue;">VIS&Eacute;E</span>'
           WHEN d.etat = -1 THEN '<span style="color:red;">REFUS&Eacute;E</span>'
           ELSE '<span style="color: yellow;">AUTRE</span>'
           END AS etatlib,
       u.refuser,
       r.rang AS ranguser,
       d.idremplacents,
       rmp.remplacents,
       d.avenant
FROM demande d
         LEFT JOIN paie_info_personnel pip ON d.idpersonnel = pip.id
         LEFT JOIN paie_fonction pf ON pf.id = pip.idfonction
         LEFT JOIN typedemande t ON t.id = d.idtypedemande
         LEFT JOIN typeabsence t2 ON t2.id = d.idtypeabsence
         LEFT JOIN log_personnel lp ON lp.id = pip.id
         LEFT JOIN log_direction ld ON ld.id = lp.direction
         LEFT JOIN utilisateur u ON u.refuser = lp.refuser
         LEFT JOIN roles r ON r.idrole = u.idrole
         LEFT JOIN demande_remplacents rmp ON rmp.id = d.id
;
-- [234/1309] DEMANDE_LIBCOMPLET3
