       ecn.rang,
       ecn2.refuser AS refusersup,
       ecn2.idrole AS idrolesup,
       ecn2.rang AS rangsup
FROM employe_complet_nou2 ecn
         LEFT JOIN employe_complet_nou2 ecn2 ON ecn.idsup = ecn2.id
;
-- [238/1309] ENCAISSEMENTCPL
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENTCPL" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDPOINT","ETAT","ETATLIB","DATY","IDORIGINE","IDTYPEENCAISSEMENT","IDTYPEENCAISSEMENTLIB","MONTANT","IDDEVISE","TAUX") AS
SELECT 
e.ID ,
e.DESIGNATION ,
e.IDCAISSE ,
c.VAL AS IDCAISSELIB,
c.IDPOINT ,
e.ETAT ,
CASE 
	WHEN e.ETAT = 1 
	THEN 'CREE'
	WHEN e.ETAT = 0 
	THEN 'ANNULEE'
	WHEN e.ETAT = 11 
	THEN 'VISEE'
END AS ETATLIB,
e.DATY ,
e.IDORIGINE,
e.IDTYPEENCAISSEMENT,
te.val AS IDTYPEENCAISSEMENTLIB,
e.montant,
nvl(e.iddevise,'AR') AS iddevise,
e.taux
FROM ENCAISSEMENT e 
LEFT JOIN CAISSE c ON c.ID  = e.IDCAISSE 
LEFT JOIN TYPE_ENCAISSEMENT te ON te.id = e.IDTYPEENCAISSEMENT
;
-- [239/1309] ENCAISSEMENT_BON
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_BON" ("IDENCAISSEMENT","MONTANTCATEGORIE") AS
SELECT 
ed.IDENCAISSEMENT ,
sum( nvl(ed.MONTANT,0) ) AS montantcategorie
FROM ENCAISSEMENT_DETAILS ed
WHERE ed.IDCATEGORIECAISSE = 'CTC001' 
GROUP BY ed.IDENCAISSEMENT
;
-- [240/1309] ENCAISSEMENT_CHEQUE
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_CHEQUE" ("IDENCAISSEMENT","MONTANTCATEGORIE") AS
SELECT 
ed.IDENCAISSEMENT ,
sum( nvl(ed.MONTANT,0) ) AS montantcategorie
FROM ENCAISSEMENT_DETAILS ed
WHERE ed.IDCATEGORIECAISSE = 'CTC002' 
GROUP BY ed.IDENCAISSEMENT
;
-- [241/1309] ENCAISSEMENT_DETAILS_LIB
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_DETAILS_LIB" ("ID","IDENCAISSEMENT","IDCATEGORIECAISSE","IDCATEGORIECAISSELIB","MONTANT","REMARQUE") AS
SELECT 
ed.ID ,
ed.IDENCAISSEMENT ,
ed.IDCATEGORIECAISSE ,
c.VAL AS IDCATEGORIECAISSELIB,
ed.MONTANT ,
ed.REMARQUE 
FROM ENCAISSEMENT_DETAILS ed 
LEFT JOIN CATEGORIECAISSE c ON c.ID = ed.IDCATEGORIECAISSE
;
-- [242/1309] ENCAISSEMENT_ESPECES
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_ESPECES" ("IDENCAISSEMENT","MONTANTCATEGORIE") AS
SELECT 
ed.IDENCAISSEMENT ,
sum( nvl(ed.MONTANT,0) ) AS montantcategorie
FROM ENCAISSEMENT_DETAILS ed
WHERE ed.IDCATEGORIECAISSE = 'CTC003' 
GROUP BY ed.IDENCAISSEMENT
;
-- [243/1309] ENCAISSEMENT_FANILO
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_FANILO" ("IDENCAISSEMENT","MONTANTCATEGORIE") AS
SELECT 
ed.IDENCAISSEMENT ,
sum( nvl(ed.MONTANT,0) ) AS montantcategorie
FROM ENCAISSEMENT_DETAILS ed
WHERE ed.IDCATEGORIECAISSE = 'CTC006' 
GROUP BY ed.IDENCAISSEMENT
;
-- [244/1309] ENCAISSEMENT_MVOLA
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_MVOLA" ("IDENCAISSEMENT","MONTANTCATEGORIE") AS
SELECT 
ed.IDENCAISSEMENT ,
sum( nvl(ed.MONTANT,0) ) AS montantcategorie
FROM ENCAISSEMENT_DETAILS ed
WHERE ed.IDCATEGORIECAISSE = 'CTC003' 
GROUP BY ed.IDENCAISSEMENT
;
-- [245/1309] ENCAISSEMENT_ORANGEMONEY
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_ORANGEMONEY" ("IDENCAISSEMENT","MONTANTCATEGORIE") AS
SELECT 
ed.IDENCAISSEMENT ,
sum( nvl(ed.MONTANT,0) ) AS montantcategorie
FROM ENCAISSEMENT_DETAILS ed
WHERE ed.IDCATEGORIECAISSE = 'CTC005' 
