;
-- [246/1309] ENCAISSEMENT_TEMP
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_TEMP" ("ID","DESIGNATION","IDCAISSE","ETAT","DATY","IDENCAISSEMENT") AS
SELECT 
CAST(' ' AS VARCHAR(255)) AS ID , 
CAST(' ' AS VARCHAR(400)) AS DESIGNATION , 
CAST(' ' AS VARCHAR(255)) AS IDCAISSE , 
CAST(-1 AS int ) AS ETAT , 
CAST(NULL  AS DATE ) AS DATY  ,
CAST(' ' AS VARCHAR(255)) AS idEncaissement 
FROM dual
;
-- [247/1309] ENCAISSEMENT_TPE
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_TPE" ("IDENCAISSEMENT","MONTANTCATEGORIE") AS
SELECT 
ed.IDENCAISSEMENT ,
sum( nvl(ed.MONTANT,0) ) AS montantcategorie
FROM ENCAISSEMENT_DETAILS ed
WHERE ed.IDCATEGORIECAISSE = 'CTC007' 
GROUP BY ed.IDENCAISSEMENT
;
-- [248/1309] ENCAISSEMENT_VALIDEE
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_VALIDEE" ("IDENCAISSEMENT","TOTALENCAISSEMENT") AS
SELECT 
ed.IDENCAISSEMENT ,
sum( nvl(ed.MONTANT,0) ) AS totalencaissement  
FROM ENCAISSEMENT_DETAILS ed 
GROUP BY ed.IDENCAISSEMENT
;
-- [249/1309] ENCAISSEMENT_VISA
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_VISA" ("IDENCAISSEMENT","MONTANTCATEGORIE") AS
SELECT 
ed.IDENCAISSEMENT ,
sum( nvl(ed.MONTANT,0) ) AS montantcategorie
FROM ENCAISSEMENT_DETAILS ed
WHERE ed.IDCATEGORIECAISSE = 'CTC008' 
GROUP BY ed.IDENCAISSEMENT
;
-- [250/1309] ENCAISSEMENT_VISEE
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_VISEE" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDPOINT","ETAT","ETATLIB","DATY","IDORIGINE","IDTYPEENCAISSEMENT","IDTYPEENCAISSEMENTLIB") AS
SELECT 
e.ID,e.DESIGNATION,e.IDCAISSE,e.IDCAISSELIB,e.IDPOINT,e.ETAT,e.ETATLIB,e.DATY , e.IDORIGINE ,e.IDTYPEENCAISSEMENT,e.IDTYPEENCAISSEMENTLIB
FROM ENCAISSEMENTCPL e
WHERE e.etat = 11
;
-- [251/1309] ENTREEPRODUIT
CREATE OR REPLACE FORCE VIEW "ENTREEPRODUIT" ("IDPRODUIT","QTEENTREE") AS
SELECT
idproduit,
CAST(sum(nvl(m.ENTREE,0)) AS NUMBER(15,2))  AS qteEntree
FROM MVTSTOCKFILLE m
LEFT JOIN MVTSTOCK mp ON mp.id = m.IDMVTSTOCK
WHERE mp.etat >= 11
GROUP BY idproduit
;
-- [252/1309] ENTRETIENRH_DETAIL_LIB
CREATE OR REPLACE FORCE VIEW "ENTRETIENRH_DETAIL_LIB" ("ID","IDENTRETIENTRH","IDCATEGORIEEVALUATION","CRITERE","NOTE","OBSERVATION","IDCATEGORIEEVALUATIONLIB") AS
SELECT
    d.ID,d.IDENTRETIENTRH,d.IDCATEGORIEEVALUATION,d.CRITERE,d.NOTE,d.OBSERVATION,
    c.val AS idCategorieEvaluationLib
FROM EntretienRH_Detail d
         LEFT JOIN categorieEvalEntretient c ON d.idCategorieEvaluation = c.id
;
-- [253/1309] ENTRETIENRH_LIB
CREATE OR REPLACE FORCE VIEW "ENTRETIENRH_LIB" ("ID","TYPEENTRETIENT","NOMPRENOMCANDIDAT","IDPERSONNEL","IDFONCTION","IDDIRECTION","IDEVALUATEUR","MOTIVATIONCANDIDAT","AMBITIONPROFESSIONEL","PRETENTIONSALARIALE","REMUNERATIONACTUEL","APPRECIATIONCANDIDAT","COMMENTAIRES","EXPERIENCECANDIDAT","ATOUT","FAIBLESSES","POINTVIGILANCE","CONCLUSTION","TYPEENTRETIENTLIB","IDFONCTIONLIB","IDDIRECTIONLIB","IDEVALUATEURLIB") AS
SELECT
    e.ID,e.TYPEENTRETIENT,e.NOMPRENOMCANDIDAT,e.IDPERSONNEL,e.IDFONCTION,e.IDDIRECTION,e.IDEVALUATEUR,e.MOTIVATIONCANDIDAT,e.AMBITIONPROFESSIONEL,e.PRETENTIONSALARIALE,e.REMUNERATIONACTUEL,e.APPRECIATIONCANDIDAT,e.COMMENTAIRES,e.EXPERIENCECANDIDAT,e.ATOUT,e.FAIBLESSES,e.POINTVIGILANCE,e.CONCLUSTION,
    CASE
        WHEN e.typeEntretient = '0'  THEN 'Interne'
        WHEN e.typeEntretient = '1' THEN 'Externe'
        ELSE 'Inconnu'
        END AS typeEntretientLib,
    f.val AS idFonctionLib,
    d.val AS idDirectionLib,
    (lp.nom || ' ' || lp.prenom) AS idEvaluateurLib
FROM EntretienRH e
         LEFT JOIN PAIE_FONCTION f ON e.idFonction = f.id
         LEFT JOIN LOG_DIRECTION d ON e.idDirection = d.id
         LEFT JOIN LOG_PERSONNEL lp ON e.idEvaluateur = lp.id
;
-- [254/1309] EQUIVALENCECARTONLIB
CREATE OR REPLACE FORCE VIEW "EQUIVALENCECARTONLIB" ("ID","IDPETRIS","IDCARTON","NBCARTON","IDPETRISLIB","IDCARTONLIB") AS
SELECT 
e."ID",e."IDPETRIS",e."IDCARTON",e."NBCARTON",
a.LIBELLE AS idpetrislib,
p.LIBELLE AS idcartonlib
FROM equivalencecarton e
LEFT JOIN AS_INGREDIENTS a ON a.id = e.idpetris
LEFT JOIN AS_INGREDIENTS p ON p.id = e.idcarton
;
-- [255/1309] EQUIVALENCE_LIB
CREATE OR REPLACE FORCE VIEW "EQUIVALENCE_LIB" ("ID","IDPRODUIT","IDUNITE","QTE") AS
select eq.id,
       ar.VAL as idproduit,
       un.VAL         as idunite,
       qte
from equivalence eq
         left join PRODUIT ar on ar.ID = eq.IDPRODUIT
         left join UNITE un on un.id = eq.IDUNITE
;
-- [256/1309] EQUIVALENCE_LIBCOMPLET
CREATE OR REPLACE FORCE VIEW "EQUIVALENCE_LIBCOMPLET" ("ID","IDPRODUIT","IDUNITE","QTE","IDPRODUITLIB","IDUNITELIB") AS
SELECT eq."ID",
          eq."IDPRODUIT",
          eq."IDUNITE",
          eq."QTE",
          ar.DESIGNATION AS idproduitlib,
          un.VAL||' ('||EQ.QTE||' unite)' AS idunitelib
     FROM equivalence eq
          LEFT JOIN ST_ARTICLE ar ON ar.ID = eq.IDPRODUIT
          LEFT JOIN ST_UNITE un ON un.id = eq.IDUNITE
;
-- [257/1309] EQUIVALENCE_QTE
CREATE OR REPLACE FORCE VIEW "EQUIVALENCE_QTE" ("ID","IDPRODUIT","IDUNITE","QTE","IDPRODUITLIB","IDUNITELIB") AS
select "ID",
       "IDPRODUIT",
       "IDUNITE",
       "QTE",
       "IDPRODUITLIB",
       "IDUNITELIB"
from EQUIVALENCE_LIBCOMPLET
where QTE = 1
;
-- [258/1309] ESCOMPTE_LIBV
CREATE OR REPLACE FORCE VIEW "ESCOMPTE_LIBV" ("ID","IDTRAITE","FRAIS","ETAT","DATY") AS
SELECT ID,IDTRAITE,FRAIS,ETAT,DATY FROM ESCOMPTE el WHERE etat=11
;
-- [259/1309] ETATDEMANDE_ETAT
CREATE OR REPLACE FORCE VIEW "ETATDEMANDE_ETAT" ("ID","VAL","DESCE","RANG","IDTYPEDEMANDE","IDETATHIERARCHIE","VALETATHIERARCHIE","ETATVISA","ETATANNULE") AS
SELECT e.id,
       e.val,
       e.desce,
       e.rang,
       e.idtypedemande,
       e.idetathierarchie,
       e2.val AS valetathierarchie,
       e2.etatvisa,
       e2.etatannule
FROM etatdemande e
         JOIN etathierarchie e2 ON e2.id = e.idetathierarchie
;
-- [260/1309] ETATDEMANDE_LIBCPL
CREATE OR REPLACE FORCE VIEW "ETATDEMANDE_LIBCPL" ("ID","VAL","DESCE","RANG","IDTYPEDEMANDE","IDETATHIERARCHIE","IDTYPEDEMANDELIB","IDETATHIERARCHIELIB") AS
SELECT e.id,
       e.val,
       e.desce,
       e.rang,
       e.idtypedemande,
       e.idetathierarchie,
       td.val AS idtypedemandelib,
       eh.val AS idetathierarchielib
FROM etatdemande e
         LEFT JOIN typedemande td ON td.id = e.idtypedemande
         LEFT JOIN etathierarchie eh ON eh.id = e.idetathierarchie
;
-- [261/1309] ETATINSPECTIONMOTCLES
CREATE OR REPLACE FORCE VIEW "ETATINSPECTIONMOTCLES" ("ID","VAL","DESCE","MOTSCLESSS") AS
SELECT
	et."ID",et."VAL",et."DESCE",
	et.ID || et.val || et.DESCE AS motsClesss
FROM
	ETATINSPECTION et
;
-- [262/1309] EVALUATION_A_CHAUD_FILLE_LIB
CREATE OR REPLACE FORCE VIEW "EVALUATION_A_CHAUD_FILLE_LIB" ("ID","IDEVALUATIONCHAUD","IDEVALUATIONCRITERE","NOTE","IDEVALUATIONCRITERELIB") AS
(
	SELECT
		eacf.ID,eacf.IDEVALUATIONCHAUD,eacf.IDEVALUATIONCRITERE,eacf.NOTE,
		ceac.val AS idevaluationcriterelib
	FROM EVALUATION_A_CHAUD_FILLE eacf
	LEFT JOIN critere_eval_a_chaud ceac ON ceac.id= eacf.idevaluationcritere
)
;
-- [263/1309] EVALUATION_A_CHAUD_LIB
CREATE OR REPLACE FORCE VIEW "EVALUATION_A_CHAUD_LIB" ("ID","IDFORMATIONSUIVIE","IDPERSONNEL","IDINTERVENANT","DATEFORMATION","DATY","REMARQUE","IDFORMATIONSUIVIELIB","IDPERSONNELLIB","MATRICULEPERSONNEL","IDFONCTION","IDFONCTIONLIB","IDINTERVENANTLIB","IDFONCTIONINTERVENANT","IDFONCTIONINTERENANTLIB") AS
(
	SELECT
		eac.ID,eac.IDFORMATIONSUIVIE,eac.IDPERSONNEL,eac.IDINTERVENANT,eac.DATEFORMATION,eac.DATY,eac.REMARQUE,
		af.intitule AS idformationsuivielib,
		lp.nom||lp.prenom AS idpersonnellib,
		pip.matricule AS matriculepersonnel,
		pip.idfonction AS idfonction,
		pf.val AS idfonctionlib,
		lpintervenant.nom || lpintervenant.prenom AS idintervenantlib,
		pipintervenant.idfonction AS idfonctionintervenant,
		pfintervenant.val AS idfonctioninterenantlib
	FROM evaluation_a_chaud eac
	LEFT JOIN action_formation af ON af.id=eac.idformationsuivie
	LEFT JOIN log_personnel lp ON lp.id=eac.idpersonnel
	LEFT JOIN paie_info_personnel pip ON pip.id=eac.idpersonnel
	LEFT JOIN paie_fonction pf ON pf.id=pip.idfonction
	LEFT JOIN log_personnel lpintervenant ON lpintervenant.id=eac.idintervenant
	LEFT JOIN paie_info_personnel pipintervenant ON pipintervenant.id=eac.idintervenant
	LEFT JOIN paie_fonction pfintervenant ON pfintervenant.id=pipintervenant.idfonction
)
;
-- [264/1309] EVALUATION_DETAIL_LIB
CREATE OR REPLACE FORCE VIEW "EVALUATION_DETAIL_LIB" ("ID","IDEVALUATION","IDCRITERE","IDTYPECOMPETENCEFP","IDTYPECOMPETENCEFPLIB","COMPETENCE","AUTOEVALUATION","EVALUATIONSUPERIEUR","SYNTHESE","APPRECIATION","NOTE","COMMENTAIRE","REMARQUE") AS
SELECT
    ed.ID,
    ed.IDEVALUATION,
    ed.IDCRITERE,
    ed.IDTYPECOMPETENCEFP,
    tpf.VAL AS idTypeCompetenceFPLib,
    ed.COMPETENCE,
    ed.AUTOEVALUATION,
    ed.EVALUATIONSUPERIEUR,
    ed.SYNTHESE,
    ed.APPRECIATION,
    ed.NOTE,
    ed.COMMENTAIRE,
    ed.REMARQUE
FROM EVALUATION_DETAIL ed
         JOIN TYPE_COMPETENCES_FP tpf
              ON ed.IDTYPECOMPETENCEFP = tpf.ID
;
-- [265/1309] EVALUATION_FROID_LIB
CREATE OR REPLACE FORCE VIEW "EVALUATION_FROID_LIB" ("ID","IDFORMATIONSUIVI","IDPERSONNEL","NOTE","COMMENTAIRE","DATEEVALUATION","PERSONNEL","MATRICULE") AS
(
	SELECT
		ef.ID,ef.IDFORMATIONSUIVI,ef.IDPERSONNEL,ef.NOTE,ef.COMMENTAIRE,ef.DATEEVALUATION,
		lp.nom||lp.prenom AS personnel,
		pip.matricule AS matricule
	FROM evaluation_froid ef
	LEFT JOIN log_personnel lp ON lp.id=ef.idpersonnel
	LEFT JOIN paie_info_personnel pip ON pip.id=ef.idpersonnel
)
;
-- [266/1309] FABRGROUPBYIDBC
CREATE OR REPLACE FORCE VIEW "FABRGROUPBYIDBC" ("IDBCFILLE","QTE") AS
SELECT 
    f.IDBCFILLE,
    SUM(f.QTE) AS qte
FROM FABRICATIONFILLE f
LEFT JOIN FABRICATION m ON m.ID = f.IDMERE
WHERE m.ETAT >= 11
GROUP BY f.IDBCFILLE
;
-- [267/1309] FABRICATIONAUTOCOMPLETE
CREATE OR REPLACE FORCE VIEW "FABRICATIONAUTOCOMPLETE" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","ETAT","IDBC","IDOFFILLE","IDOF","FABRICATIONPREC","FABRICATIONSUIV","EQUIPE","LANCEUR") AS
SELECT 
f.ID,
f.LANCEPAR,
f.CIBLE,
f.REMARQUE,
f.LIBELLE,
f.BESOIN,
f.DATY,
f.ETAT,
f.IDBC,
f.IDOFFILLE,
f.IDOF,
f.FABRICATIONPREC,
f.FABRICATIONSUIV,
f.EQUIPE,
CASE 
	WHEN f.LANCEUR IS NOT NULL 
	THEN f.LANCEUR||'---'||lp.nom||' '||lp.prenom 
END AS LANCEUR
FROM FABRICATION f 
LEFT JOIN OFFILLE o ON o.id = f.idOffille
LEFT JOIN LOG_PERSONNEL lp ON lp.id = f.LANCEUR
;
-- [268/1309] FABRICATIONFILLEAUTOCOMPLETE
CREATE OR REPLACE FORCE VIEW "FABRICATIONFILLEAUTOCOMPLETE" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","IDUNITE","IDBCFILLE","OPERATEUR","NIVEAU","IDMACHINE","PU","QTE") AS
SELECT 
f.ID,
CASE 
	WHEN f.IDINGREDIENTS IS NOT NULL 
	THEN f.IDINGREDIENTS||'---'||ai.libelle 
	ELSE f.IDINGREDIENTS
END AS IDINGREDIENTS ,
f.LIBELLE,
f.REMARQUE,
f.IDMERE,
f.DATYBESOIN,
f.IDUNITE,
f.IDBCFILLE,
f.OPERATEUR,
f.NIVEAU,
f.IDMACHINE,
f.PU,
f.QTE
FROM FABRICATIONFILLE f 
LEFT JOIN AS_INGREDIENTS ai ON ai.id =  f.IDINGREDIENTS
;
-- [269/1309] FABRICATIONFILLECPL
CREATE OR REPLACE FORCE VIEW "FABRICATIONFILLECPL" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","PU","IDINGREDIENTSLIB","OPERATEUR","IDUNITELIB","IDBCFILLE","IDMACHINE","IDMACHINELIB","ISPETRI","IDOFFILLE","MONTANT") AS
SELECT
	f.ID,
	f.IDINGREDIENTS,
	f.LIBELLE,
	f.REMARQUE,
	f.IDMERE,
	f.DATYBESOIN,
	f.QTE,
	f.IDUNITE,
	f.PU,
	ai.LIBELLE AS idingredientsLib,
	p.NOM || ' - ' || p.TELEPHONE AS operateur,
	au.val AS IDUNITELIB,
	f.IDBCFILLE ,
	f.IDMACHINE,
	m.descriptionobjet AS IDMACHINELIB,
	ai.ISPETRI ,
	f2.IDOFFILLE ,
	CAST( (f.QTE * f.PU ) AS NUMBER(30,5) ) AS MONTANT 
FROM
	FABRICATIONFILLE f
JOIN FABRICATION f2 ON f2.ID = f.IDMERE 
LEFT JOIN AS_INGREDIENTS ai ON
	ai.id = f.IDINGREDIENTS
LEFT JOIN PERSONNEL p ON
	p.ID = f.OPERATEUR
LEFT JOIN AS_UNITE au ON
	au.id = f.IDUNITE
LEFT JOIN AS_INGREDIENT_MACHINE m ON m.ID = f.IDMACHINE
;
-- [270/1309] FABRICATIONFILLECPL2
CREATE OR REPLACE FORCE VIEW "FABRICATIONFILLECPL2" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","PU","REVIENT","IDINGREDIENTSLIB","DATY") AS
SELECT
    f.ID,
    f.IDINGREDIENTS,
    f.LIBELLE,
    f.REMARQUE,
    f.IDMERE,
    f.DATYBESOIN,
    f.QTE,
    f.IDUNITE,
    f.PU,
    CAST(f.QTE * f.PU AS NUMBER(10,2)) AS revient,
    ai.LIBELLE AS idingredientsLib,
    ff.DATY
FROM FABRICATIONFILLE f
LEFT JOIN AS_INGREDIENTS ai ON ai.ID = f.IDINGREDIENTS
JOIN FABRICATION ff ON f.IDMERE = ff.ID
WHERE ETAT >= 11
;
-- [271/1309] FABRICATIONFILLEFABRIQUEVISE
CREATE OR REPLACE FORCE VIEW "FABRICATIONFILLEFABRIQUEVISE" ("IDMERE","IDINGREDIENTS","QTE") AS
SELECT 
f.idMere,
f.IDINGREDIENTS,
sum(f.qte) AS qte
FROM FABRICATIONFILLE f 
LEFT JOIN FABRICATION fab ON fab.id = f.idMere
WHERE fab.etat >=11
GROUP BY f.idMere,
f.IDINGREDIENTS
;
-- [272/1309] FABRICATIONFILLEPETRI
CREATE OR REPLACE FORCE VIEW "FABRICATIONFILLEPETRI" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","PU","IDBCFILLE","OPERATEUR","NIVEAU","IDMACHINE","IDLIGNE","LIGNE","DATY") AS
SELECT
f.ID,f.IDINGREDIENTS,f.LIBELLE,f.REMARQUE,f.IDMERE,f.DATYBESOIN,f.QTE,f.IDUNITE,f.PU,f.IDBCFILLE,f.OPERATEUR,f.NIVEAU,f.IDMACHINE, l.id AS idligne,
        l.VAL AS ligne, fab.daty
FROM FABRICATIONFILLE f
JOIN fabrication fab ON f.idmere = fab.id
LEFT JOIN AS_INGREDIENTS ai ON ai.id = f.IDINGREDIENTS  
LEFT JOIN TYPE_PRODUIT tp ON tp.id = ai.typeproduit
LEFT JOIN LIGNE l ON l.id=tp.IDLIGNE
WHERE ai.ispetri = 1
;
-- [273/1309] FABRICATIONFILLEPU
CREATE OR REPLACE FORCE VIEW "FABRICATIONFILLEPU" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","PU","IDBCFILLE","OPERATEUR") AS
select f.id, f.idingredients, f.libelle, f.remarque, f.idmere, f.datybesoin, f.qte, f.idunite, a.pu, f.IDBCFILLE,f.OPERATEUR
from FABRICATIONFILLE f left join AS_INGREDIENTS a on f.IDINGREDIENTS=a.id
;
-- [274/1309] FABRICATIONMEREFILLE
CREATE OR REPLACE FORCE VIEW "FABRICATIONMEREFILLE" ("IDINGREDIENTS","IDINGREDIENTSLIB","QTE","IDUNITE","IDOFFILLE","IDOF","LIBELLE","DATY","IDBCFILLE") AS
SELECT
	ff.IDINGREDIENTS,
	ff.IDINGREDIENTSLIB ,
	sum(ff.QTE) qte,
	ff.IDUNITE ,
	f.idOffille,
	f.IDOF,
	f.LIBELLE,
	f.DATY,
	ff.IDBCFILLE 
FROM
	FabricationFilleCpl ff
JOIN FABRICATION f ON
	f.id = ff.IDMERE
WHERE
	f.etat = 11
GROUP BY
	ff.IDINGREDIENTS,
	ff.IDINGREDIENTSLIB ,
	ff.IDUNITE ,
	f.idOffille,
	f.LIBELLE,
	f.DATY,
	ff.IDBCFILLE,
	f.IDOF
;
-- [275/1309] FABRICATIONOFFILLE
CREATE OR REPLACE FORCE VIEW "FABRICATIONOFFILLE" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","IDBCFILLE","IDFAB") AS
select off."ID",off."IDINGREDIENTS",off."LIBELLE",off."REMARQUE",off."IDMERE",off."DATYBESOIN",off."QTE",off."IDUNITE",off."IDBCFILLE",f.id as idFab from OFFILLE off left join fabrication f on f.IDOFFILLE=off.ID
;
-- [276/1309] FABRICATIONRATTACHE
CREATE OR REPLACE FORCE VIEW "FABRICATIONRATTACHE" ("IDFAB","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","PU","IDBCFILLE","OPERATEUR","NIVEAU","IDMACHINE","IDLIGNE","LIGNE","DATY","ID","IDRELEVE","POURCENTAGE") AS
SELECT f.ID AS idFab ,f.IDINGREDIENTS,f.LIBELLE,f.REMARQUE,f.IDMERE,f.DATYBESOIN,f.QTE,f.IDUNITE,f.PU,f.IDBCFILLE,f.OPERATEUR,f.NIVEAU,f.IDMACHINE,f.IDLIGNE,f.LIGNE,f.DATY, r.id  ,r.idreleve AS idreleve, CAST((f.QTE  / SUM(f.QTE ) OVER (PARTITION BY r.IDRELEVE)) * 100 AS NUMBER(30,2) ) AS POURCENTAGE FROM FABRICATIONFILLEPETRI f
	JOIN RELEVEFAB r ON r.IDFAB = f.id
;
-- [277/1309] FABRICATION_OF
CREATE OR REPLACE FORCE VIEW "FABRICATION_OF" ("ID","IDMERE","IDINGREDIENTS","LIBELLE","REMARQUE","DATYBESOIN","QTE","IDUNITE","IDOFFILLE","IDOF") AS
(
SELECT
	f.id,
	f.idMere,
	f.idingredients,
	f.libelle,
	f.remarque,
	f.datybesoin,
	f.qte,
	f.idunite,
	f2.idOffille,
	f2.IDOF
FROM
	FABRICATIONFILLE f
JOIN FABRICATION f2 ON
	f.IDMERE = f2.ID
)
;
-- [278/1309] FACTFRNSFILLEAUTOCOMPLETE
CREATE OR REPLACE FORCE VIEW "FACTFRNSFILLEAUTOCOMPLETE" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","PU","REMISES","IDBCDETAIL","TVA","DEVISE","TAUXDECHANGE","IDDEVISE","DESIGNATION","COMPTE","MOIS","ANNEE","QTE","MONTANTPERTEGAIN","IDPREVISION") AS
SELECT 
ff.ID,
ff.IDFACTUREFOURNISSEUR,
CASE 
	WHEN ff.IDPRODUIT IS NOT NULL
	THEN ff.IDPRODUIT||'---'||ai.LIBELLE
	ELSE ff.IDPRODUIT
END AS IDPRODUIT,
ff.PU,
ff.REMISES,
ff.IDBCDETAIL,
ff.TVA,
ff.DEVISE,
ff.TAUXDECHANGE,
ff.IDDEVISE,
ff.DESIGNATION,
ff.COMPTE,
ff.MOIS,
ff.ANNEE,
ff.QTE,
ff.MONTANTPERTEGAIN,
CASE 
	WHEN ff.IDPREVISION IS NOT NULL 
	THEN ff.IDPREVISION||'---'||p.DESIGNATION  
	ELSE ff.IDPREVISION
END AS IDPREVISION
FROM FactureFournisseurFille ff 
LEFT JOIN AS_INGREDIENTS ai ON ai.id = ff.IDPRODUIT 
LEFT JOIN PREVISION p ON p.id = ff.IDPREVISION
;
-- [279/1309] FACTURECLIENTDETAILSLIB
CREATE OR REPLACE FORCE VIEW "FACTURECLIENTDETAILSLIB" ("ID","IDFACTURECLIENT","IDACTE","LIBELLE","QTE","PU","REMISES","TVA","COMPTE","IDPRODUIT","IDPRODUITLIB","MONTANT") AS
SELECT
	f.ID,
	f.IDFACTURECLIENT,
	f.idacte,
	a.libelle,
	f.QTE,
	f.PU,
	f.REMISES,
	f.TVA,
	f.COMPTE,
	f.IDPRODUIT,
	p.val AS idproduitlib,
	CAST(  f.qte * f.pu * (1  - CAST( (f.remises /100) AS number(30,2)) )  AS number(30,2)) + CAST(  f.qte * f.pu * (1  - CAST( (f.remises /100) AS number(30,2)) ) * (nvl(f.tva,0) /100)  AS number(30,2)) AS montant
FROM
	FACTURECLIENTDETAILS f
LEFT JOIN PRODUIT p ON
	p.id = f.idproduit
LEFT JOIN acte a ON a.id = f.idacte
;
-- [280/1309] FACTURECLIENTMONTANT
CREATE OR REPLACE FORCE VIEW "FACTURECLIENTMONTANT" ("ID","MONTANTTOTAL","MONTANTTVA","MONTANTTTC") AS
SELECT 
f.id ,
CAST( sum( fc.qte * fc.pu * (1  - CAST( (fc.remises /100) AS number(30,2)) ) ) AS number(30,2))  AS montanttotal,
CAST( sum( fc.qte * fc.pu * (1  - CAST( (fc.remises /100) AS number(30,2)) ) * (nvl(fc.tva,0) /100) ) AS number(30,2))  AS montanttva,
CAST( sum( fc.qte * fc.pu * (1  - CAST( (fc.remises /100) AS number(30,2)) ) ) AS number(30,2)) + CAST( sum( fc.qte * fc.pu * (1  - CAST( (fc.remises /100) AS number(30,2)) ) * (nvl(fc.tva,0) /100) ) AS number(30,2))  AS montantttc
FROM FACTURECLIENTDETAILS fc 
LEFT JOIN FACTURECLIENT f ON f.id = fc.idfactureclient
GROUP BY f.ID
;
-- [281/1309] FACTURECLIENTPAYE
CREATE OR REPLACE FORCE VIEW "FACTURECLIENTPAYE" ("IDORIGINE","CREDIT") AS
SELECT
m.IDORIGINE, 
sum(m.credit) AS credit
FROM MOUVEMENTCAISSE m 
WHERE m.ETAT = 11 
GROUP BY m.IDORIGINE
;
-- [282/1309] FACTURECLIENTCPL
CREATE OR REPLACE FORCE VIEW "FACTURECLIENTCPL" ("ID","IDCLIENT","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","MONTANTTOTAL","MONTANTHT","MONTANTTVA","MONTANTTTC","IDCLIENTLIB","NUMEROCLIENT","MONTANTPAYE","IDRESERVATION","RESTEAPAYERTTC") AS
SELECT
    f.ID,f.IDCLIENT,f.DATY,f.DESIGNATION,f.DATEECHEANCEPAIEMENT,f.ETAT,
    CASE
        WHEN f.etat=0 THEN 'ANNULE'
        WHEN f.etat=1 THEN 'CREE'
        WHEN f.etat=11 THEN 'VISEE'
        ELSE 'AUTRE'
        END AS etatlib,
    fm.montanttotal,
    fm.montanttotal - fm.montantTva AS montantHT,
    fm.montantTva,
    fm.montantTTC,
    c.NOM AS idClientLib,
    c.TELEPHONE AS numeroClient,
    nvl(fp.credit,0) as montantPaye,
    f.idreservation,
    (fm.montantTTC - nvl(fp.credit,0)) as resteapayerTTC
FROM FactureClient f
         LEFT JOIN FACTURECLIENTMONTANT fm ON fm.id = f.id
         LEFT JOIN CLIENT c ON c.id = f.IDCLIENT
         LEFT JOIN factureclientpaye fp ON fp.IDORIGINE = f.ID
;
-- [283/1309] FACTUREDECLARATIONFILLECPL
CREATE OR REPLACE FORCE VIEW "FACTUREDECLARATIONFILLECPL" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","IDPRODUITLIB","QTE","PU","REMISES","IDBCDETAIL","TVA","IDDEVISE","DATY","MONTANT","MONTANTREMISE","MONTANTHT","MONTANTTVA","MONTANTTTC","FRAISACCESOIRE","MONTANTAVECFRAISACCESSOIRE","PUAVECFRAISACCESSOIRE","LIBELLEEXACTE") AS
SELECT f.ID,
       f.IDFACTUREFOURNISSEUR,
       f.IDPRODUIT,
       p.LIBELLE                                                         AS IDPRODUITLIB,
       f.QTE,
       f.PU,
       f.REMISES,
       f.IDBCDETAIL,
       f.TVA,
       f.IDDEVISE,
       f2.DATY,

       CAST(f.QTE * f.PU AS NUMBER(30, 2))                               AS montant,
       CAST((NVL(f.remises, 0) / 100) * (f.QTE * f.PU) AS NUMBER(30, 2)) AS montantRemise,
       CAST((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU))
           AS NUMBER(30, 2))                                             AS montantht,
       CAST(
               ((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU)))
                   * f.TVA / 100
           AS NUMBER(30, 2)
       )                                                                 AS montanttva,
       CAST(
               ((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU)))
                   + (
                   ((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU)))
                       * f.TVA / 100
                   )
           AS NUMBER(30, 2)
       )                                                                 AS montantttc,

       NVL(MONTANTPERTEGAIN, 0)                                          AS fraisaccesoire,

       CAST(
               (
                   ((f.QTE * f.PU * f.TAUXDECHANGE) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU * f.TAUXDECHANGE)))
                   )
                   + NVL(MONTANTPERTEGAIN, 0)
           AS NUMBER(30, 2)
       )                                                                 AS montantavecfraisaccessoire,
       CAST(
               (
                   (
                       ((f.QTE * f.PU * f.TAUXDECHANGE) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU * f.TAUXDECHANGE)))
                       )
                       + NVL(MONTANTPERTEGAIN, 0)
                   ) / f.QTE
           AS NUMBER(30, 2)
       )                                                                 AS puavecfraisaccessoire,

       NVL(p.LIBELLEEXTACTE, p.LIBELLE)                                  AS libelleexacte
FROM FACTUREDECLARATIONFILLE f
         LEFT JOIN FACTUREFOURNISSEUR f2
                   ON f2.ID = f.IDFACTUREFOURNISSEUR
         LEFT JOIN AS_INGREDIENTS p
                   ON p.ID = f.IDPRODUIT
;
-- [284/1309] FACTUREDECLARATIONMONTANT
CREATE OR REPLACE FORCE VIEW "FACTUREDECLARATIONMONTANT" ("ID","MONTANTTOTAL","MONTANTTVA","MONTANTTTC","IDDEVISE","TAUXDECHANGE") AS
SELECT v.ID,
                cast(SUM ((1-nvl(vd.remises/100,0))* (NVL (vd.QTE, 0) * NVL (vd.PU, 0))) as number(30,2)) AS montanttotal,
                cast(SUM ((1-nvl(vd.REMISES /100,0))* (NVL (vd.QTE, 0) * NVL (vd.PU, 0))* (NVL (VD.TVA , 0))/100) as number(30,2)) AS montantTva,
                cast(SUM ((1-nvl(vd.remises/100,0))* (NVL (vd.QTE, 0) * NVL (vd.PU, 0))* (NVL (VD.TVA , 0))/100)+SUM ((1-nvl(vd.remises/100,0))* (NVL (vd.QTE, 0) * NVL (vd.PU, 0)))as number(30,2))  as montantTTC,
                NVL (vd.IDDEVISE,'AR') AS IDDEVISE,
                nvl (vd.tauxdechange,1) AS tauxdechange
         FROM FACTUREDECLARATIONFILLE vd LEFT JOIN FACTUREDECLARATION v ON v.ID = vd.idfacturefournisseur
         GROUP BY v.ID, vd.IDDEVISE,vd.tauxdechange
;
-- [285/1309] FACTUREFOURNISSEURAUTOCOMPLETE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURAUTOCOMPLETE" ("ID","IDFOURNISSEUR","IDMODEPAIEMENT","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","REFERENCE","IDBC","DEVISE","TAUX","IDMAGASIN","IDDEVISE","ESTPREVU","DATYPREVU","NUMERO","TYPEACHAT","IDTYPEFACTURE","IDOBJET","IDREF","IDDMDACHAT","IDFACTUREPRINCIPALE","SERVICE","TYPEFACTUREFOURNISSEUR","ECHEANCEFACTURE") AS
SELECT
    f.ID,
    CASE
        WHEN f.IDFOURNISSEUR IS NOT NULL
            THEN f.IDFOURNISSEUR||'---'||fr.NOM
        ELSE f.IDFOURNISSEUR
        END AS IDFOURNISSEUR ,
    f.IDMODEPAIEMENT,
    f.DATY,
    f.DESIGNATION,
    f.DATEECHEANCEPAIEMENT,
    f.ETAT,
    f.REFERENCE,
    f.IDBC,
    f.DEVISE,
    f.TAUX,
    f.IDMAGASIN,
    f.IDDEVISE,
    f.ESTPREVU,
    f.DATYPREVU,
    f.NUMERO,
    f.TYPEACHAT,
    f.IDTYPEFACTURE,
    f.IDOBJET,
    f.IDREF,
    f.IDDMDACHAT,
    f.IDFACTUREPRINCIPALE,
    f.SERVICE,
    f.TYPEFACTUREFOURNISSEUR,
    f.echeancefacture
FROM FACTUREFOURNISSEUR f
         LEFT JOIN FOURNISSEUR fr ON fr.id = f.IDFOURNISSEUR
;
-- [286/1309] FACTUREFOURNISSEURFILLEVALIDE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURFILLEVALIDE" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","PU","REMISES","IDBCDETAIL","TVA","DEVISE","TAUXDECHANGE","IDDEVISE","DESIGNATION","COMPTE","MOIS","ANNEE","QTE","MONTANTPERTEGAIN","IDPREVISION") AS
SELECT ff."ID",ff."IDFACTUREFOURNISSEUR",ff."IDPRODUIT",ff."PU",ff."REMISES",ff."IDBCDETAIL",ff."TVA",ff."DEVISE",ff."TAUXDECHANGE",ff."IDDEVISE",ff."DESIGNATION",ff."COMPTE",ff."MOIS",ff."ANNEE",ff."QTE",ff."MONTANTPERTEGAIN",ff."IDPREVISION" FROM FACTUREFOURNISSEURFILLE ff JOIN facturefournisseur f ON f.id=ff.idfacturefournisseur WHERE f.etat>=11
;
-- [287/1309] FACTUREFOURNISSEURFILLE_U
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURFILLE_U" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","PU","REMISES","IDBCDETAIL","TVA","DEVISE","TAUXDECHANGE","IDDEVISE","DESIGNATION","COMPTE","MOIS","ANNEE","QTE","MONTANTPERTEGAIN","IDPREVISION","REMISE","RISTOURNE","COMPTEANALYTIQUE","UNITE","IDUNITE") AS
(
select f."ID",f."IDFACTUREFOURNISSEUR",f."IDPRODUIT",f."PU",f."REMISES",f."IDBCDETAIL",f."TVA",f."DEVISE",f."TAUXDECHANGE",f."IDDEVISE",f."DESIGNATION",f."COMPTE",f."MOIS",f."ANNEE",f."QTE",f."MONTANTPERTEGAIN",f."IDPREVISION",f."REMISE",f."RISTOURNE",f."COMPTEANALYTIQUE", au.id as UNITE, au.val as IDUNITE
from FACTUREFOURNISSEURFILLE f
         left join AS_ingredients ai on ai.ID = f.IDPRODUIT
         left join as_unite au on au.ID = ai.UNITE
    )
;
-- [288/1309] FACTUREFOURNISSEURMONTANT
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURMONTANT" ("ID","MONTANTTOTAL","MONTANTTVA","MONTANTTTC","IDDEVISE","TAUXDECHANGE") AS
SELECT v.ID,
            cast(SUM ((1-nvl(vd.remises/100,0))* (NVL (vd.QTE, 0) * NVL (vd.PU, 0))) as number(30,2)) AS montanttotal, 
            cast(SUM ((1-nvl(vd.REMISES /100,0))* (NVL (vd.QTE, 0) * NVL (vd.PU, 0))* (NVL (VD.TVA , 0))/100) as number(30,2)) AS montantTva,
            cast(SUM ((1-nvl(vd.remises/100,0))* (NVL (vd.QTE, 0) * NVL (vd.PU, 0))* (NVL (VD.TVA , 0))/100)+SUM ((1-nvl(vd.remises/100,0))* (NVL (vd.QTE, 0) * NVL (vd.PU, 0)))as number(30,2))  as montantTTC,
            NVL (vd.IDDEVISE,'AR') AS IDDEVISE,
            nvl (vd.tauxdechange,1) AS tauxdechange
            FROM FactureFournisseurFille vd LEFT JOIN facturefournisseur v ON v.ID = vd.idfacturefournisseur
   GROUP BY v.ID, vd.IDDEVISE,vd.tauxdechange
;
-- [289/1309] FACTUREFOURNISSEUR_CPL
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_CPL" ("ID","IDFOURNISSEUR","IDMODEPAIEMENT","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","REFERENCE","IDBC","DEVISE","TAUX","IDMAGASIN","FOURNISSEURLIB","MODEDEPAIMENTLIB","COMPTE","COMPTEAUXILIAIRE") AS
select ff."ID",ff."IDFOURNISSEUR",ff."IDMODEPAIEMENT",ff."DATY",ff."DESIGNATION",ff."DATEECHEANCEPAIEMENT",ff."ETAT",ff."REFERENCE",ff."IDBC",ff."DEVISE",ff."TAUX",ff."IDMAGASIN",
       f.NOM as fournisseurlib,
       mp.VAL as modedepaimentlib,
       f.COMPTE,
       f.compteauxiliaire
from FACTUREFOURNISSEUR ff
         left join FOURNISSEUR f on ff.IDFOURNISSEUR = f.ID
         left join MODEPAIEMENT mp on ff.IDMODEPAIEMENT = mp.ID
;
-- [290/1309] FACTUREFOURNISSEUR_MONTANT
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_MONTANT" ("IDFACTUREFOURNISSEUR","MONTANT") AS
select iDFACTUREFOURNISSEUR,
       cast(sum(pu * QTE) as number(30, 2)) as montant

from FACTUREFOURNISSEURFILLE
group by IDFACTUREFOURNISSEUR
;
-- [291/1309] FFFILLECALC
CREATE OR REPLACE FORCE VIEW "FFFILLECALC" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","PU","REMISES","IDBCDETAIL","TVA","DEVISE","TAUXDECHANGE","IDDEVISE","DESIGNATION","COMPTE","MOIS","ANNEE","QTE","MONTANTPERTEGAIN","IDPREVISION","REMISE","RISTOURNE","MONTANTNONREMISE","MONTANTREMISESANSTVA","MONTANTHT","PUREMISE","MONTANTHTAR","MONTANTTVA","MONTANTTVAAR","MONTANTTTC","MONTANTTTCAR") AS
select vd."ID",vd."IDFACTUREFOURNISSEUR",vd."IDPRODUIT",vd."PU",vd."REMISES",vd."IDBCDETAIL",vd."TVA",vd."DEVISE",vd."TAUXDECHANGE",vd."IDDEVISE",vd."DESIGNATION",vd."COMPTE",vd."MOIS",vd."ANNEE",vd."QTE",vd."MONTANTPERTEGAIN",vd."IDPREVISION",vd."REMISE",vd."RISTOURNE",cast(vd.QTE*vd.pu as number(30,2)) as montantNonRemise,
cast(vd.QTE*vd.pu*((nvl(vd.REMISE,0)+nvl(vd.RISTOURNE,0))/100) as number(30,2)) as montantRemiseSansTva,
cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100)) as number(30,2)) as montantHT,
cast(vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100)) as number(30,2)) as puRemise,
cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*nvl(vd.TAUXDECHANGE,1) as number(30,2)) as montantHTAr,
cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*nvl(vd.tva,0)/100 as number(30,2)) as montantTva,
cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*nvl(vd.TAUXDECHANGE,1)*nvl(vd.tva,0)/100 as number(30,2)) as montantTvaAr,
cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*(1+(nvl(vd.tva,0)/100)) as number(30,2)) as montantTTC,
cast(vd.QTE*vd.pu*(1-(nvl(vd.REMISE,0)/100))*(1-(nvl(vd.RISTOURNE,0)/100))*(1+(nvl(vd.tva,0)/100))*nvl(vd.TAUXDECHANGE,1) as number(30,2)) as montantTTCAr from FACTUREFOURNISSEURFILLE vd
;
-- [292/1309] FACTUREFOURNISSEUR_FILLECOMPTE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_FILLECOMPTE" ("COMPTE","IDFACTUREFOURNISSEUR","ETAT","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","IDDEVISE","TAUXDECHANGE") AS
select ff.COMPTE,
       ff.IDFACTUREFOURNISSEUR,
       f.etat,
       cast(sum(MONTANTHT) as number(30, 2))                            as montantht,
       cast(sum(MONTANTTVA) as number(30, 2))              as montanttva,
       cast(sum(MONTANTTTC) as number(30, 2)) as montantttc,
       cast(sum(MONTANTTTCAr) as number(30, 2)) as montantttcAr,
       ff.iddevise,
       ff.tauxdechange
from FFFILLECALC ff join FACTUREFOURNISSEUR f on f.id=ff.IDFACTUREFOURNISSEUR
group by COMPTE, IDFACTUREFOURNISSEUR, f.etat,ff.iddevise,ff.tauxdechange
;
-- [293/1309] FACTUREFOURNISSEUR_FILLE_CREE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_FILLE_CREE" ("COMPTE","IDFACTUREFOURNISSEUR","ETAT","MONTANTHT","MONTANTTVA","MONTANTTTC") AS
select "COMPTE","IDFACTUREFOURNISSEUR","ETAT","MONTANTHT","MONTANTTVA","MONTANTTTC"
from FACTUREFOURNISSEUR_FILLECOMPTE
where etat = 1
;
-- [294/1309] FACTUREFOURNISSEUR_FILLE_VISE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_FILLE_VISE" ("COMPTE","IDFACTUREFOURNISSEUR","ETAT","MONTANTHT","MONTANTTVA","MONTANTTTC","IDDEVISE","TAUXDECHANGE") AS
select COMPTE,IDFACTUREFOURNISSEUR,ETAT,MONTANTHT,MONTANTTVA,MONTANTTTC,iddevise,tauxdechange
from FACTUREFOURNISSEUR_FILLECOMPTE
where etat = 11
;
-- [295/1309] FACTUREFOURNISSEUR_MERECMPT
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_MERECMPT" ("ID","IDFOURNISSEUR","IDMODEPAIEMENT","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","REFERENCE","IDBC","DEVISE","TAUX","IDMAGASIN","FOURNISSEURLIB","MODEDEPAIMENTLIB","COMPTE","COMPTEAUXILIAIRE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTTTCAR") AS
select ff."ID",
       ff."IDFOURNISSEUR",
       ff."IDMODEPAIEMENT",
       ff."DATY",
       ff."DESIGNATION",
       ff."DATEECHEANCEPAIEMENT",
       ff."ETAT",
       ff."REFERENCE",
       ff."IDBC",
       ff."DEVISE",
       ff."TAUX",
       ff."IDMAGASIN",
       ff."FOURNISSEURLIB",
       ff."MODEDEPAIMENTLIB",
       ff."COMPTE",
       ff.compteauxiliaire,
       fm.MONTANTHT,
       fm.MONTANTTVA,
       fm.MONTANTTTC,fm.montantttcAr
from FACTUREFOURNISSEUR_CPL ff
         left join FACTUREFOURNISSEUR_FILLECOMPTE fm on fm.IDFACTUREFOURNISSEUR = ff.id
;
-- [296/1309] FACTUREFOURNISSEUR_MF
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_MF" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","QTE","PU","REMISES","IDBCDETAIL","TVA","DEVISE","TAUXDECHANGE","IDDEVISE","DESIGNATION","COMPTE","MONTANTPERTEGAIN","IDFOURNISSEUR","ETAT","DATY","PUREMISE") AS
SELECT ff.ID,
       ff.IDFACTUREFOURNISSEUR,
       ff.IDPRODUIT,
       ff.QTE,
       ff.PU,
       ff.REMISES,
       ff.IDBCDETAIL,
       ff.TVA,
       ff.DEVISE,
       ff.TAUXDECHANGE,
       ff.IDDEVISE,
       ff.DESIGNATION,
       ff.COMPTE,
       ff.MONTANTPERTEGAIN,
       f.IDFOURNISSEUR,
       f.ETAT,
       f.DATY,
       ff.PUREMISE
FROM FFFilleCalc ff
         JOIN FACTUREFOURNISSEUR f ON ff.IDFACTUREFOURNISSEUR = f.ID
;
-- [297/1309] FFAVECPERTE_FF
CREATE OR REPLACE FORCE VIEW "FFAVECPERTE_FF" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","QTE","PU","REMISES","IDBCDETAIL","TVA","DEVISE","TAUXDECHANGE","IDDEVISE","DESIGNATION","COMPTE","MONTANTPERTEGAIN","IDFOURNISSEUR","ETAT","DATY","PUPERTEGAIN","MONTANTAVECPERTEGAIN","LIBELLEPRODUIT") AS
SELECT
    ff.ID,
    ff.IDFACTUREFOURNISSEUR,
    ff.IDPRODUIT,
    ff.QTE,
    ff.PU,
    ff.REMISES,
    ff.IDBCDETAIL,
    ff.TVA,
    ff.DEVISE,
    ff.TAUXDECHANGE,
    ff.IDDEVISE,
    ff.DESIGNATION,
    ff.COMPTE,
    CAST(nvl(rep.montant,0) AS NUMBER(30,2) ) AS MONTANTPERTEGAIN ,
    ff.IDFOURNISSEUR,
    ff.ETAT,ff.DATY,
    CAST(((ff.PUREMISE*TAUXDECHANGE)+(nvl(rep.MONTANT,0)/qte)) AS NUMBER(30,2) ) AS pupertegain ,
    CAST(((qte*ff.PUREMISE*TAUXDECHANGE)+nvl(rep.montant,0)) AS NUMBER(30,2) ) AS montantavecpertegain,
    asi.LIBELLE AS LIBELLEPRODUIT
FROM
    FACTUREFOURNISSEUR_mf ff
        LEFT JOIN AS_INGREDIENTS asi ON ASI.ID = ff.IDPRODUIT
        left join RepartirionPG rep on rep.IDFACTUREFILLE=ff.id
;
-- [298/1309] FFFILLECALCGROUPEFF
CREATE OR REPLACE FORCE VIEW "FFFILLECALCGROUPEFF" ("IDFACTUREFOURNISSEUR","MONTANTNONREMISE","MONTANTREMISESANSTVA","MONTANTHT","MONTANTTTC","MONTANTTVA","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR") AS
select vdc.IDFACTUREFOURNISSEUR ,cast(sum(montantNonRemise) as number(30,2)) as montantNonRemise,cast(sum(montantRemiseSansTva) as number(30,2)) as montantRemiseSansTva,
       cast(sum(montantHT) as number(30,2)) as montantHT,cast(sum(montantTTC) as number(30,2)) as montantTTC,cast(sum(montantTva) as number(30,2)) as montantTva,
       cast(sum(montantHTAr) as number(30,2)) as montantHTAr,cast(sum(montantTvaAr) as number(30,2)) as montantTvaAr,cast(sum(montantTTCAr) as number(30,2)) as montantTTCAr
from FFFilleCalc vdc group by vdc.IDFACTUREFOURNISSEUR
;
-- [299/1309] FACTFOURNISSEURCALC
CREATE OR REPLACE FORCE VIEW "FACTFOURNISSEURCALC" ("ID","IDFOURNISSEUR","IDMODEPAIEMENT","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","REFERENCE","IDBC","DEVISE","TAUX","IDMAGASIN","IDDEVISE","ESTPREVU","DATYPREVU","NUMERO","TYPEACHAT","IDTYPEFACTURE","IDOBJET","IDREF","IDDMDACHAT","IDFACTUREPRINCIPALE","SERVICE","TYPEFACTUREFOURNISSEUR","ECHEANCEFACTURE","REMISE","MONTANTREMISE","MONTANTNONREMISE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTHTAR") AS
select v."ID",v."IDFOURNISSEUR",v."IDMODEPAIEMENT",v."DATY",v."DESIGNATION",v."DATEECHEANCEPAIEMENT",v."ETAT",v."REFERENCE",v."IDBC",v."DEVISE",v."TAUX",v."IDMAGASIN",v."IDDEVISE",v."ESTPREVU",v."DATYPREVU",v."NUMERO",v."TYPEACHAT",v."IDTYPEFACTURE",v."IDOBJET",v."IDREF",v."IDDMDACHAT",v."IDFACTUREPRINCIPALE",v."SERVICE",v."TYPEFACTUREFOURNISSEUR",v."ECHEANCEFACTURE",v."REMISE", cast(montantRemiseSansTva+ (montantHT* (nvl(v.REMISE,0)/100)) as number(30,2)) as montantRemise, montantNonRemise,
       cast(montantHT*(1-(nvl(v.REMISE,0)/100)) as number(30,2)) as montantHT,cast(montantTva*(1-(nvl(v.REMISE,0)/100)) as number(30,2)) as montantTva,
       cast(montantTTC*(1-(nvl(v.REMISE,0)/100)) as number(30,2)) as montantTTC, montantTTCAr*(1-(nvl(v.REMISE,0)/100)) as montantTTCAr, MONTANTHTAR*(1-(nvl(v.REMISE,0)/100)) as montantHtAr
from FACTUREFOURNISSEUR v left join FFFilleCalcGroupeFF vdcv on v.id=vdcv.IDFACTUREFOURNISSEUR
;
-- [300/1309] FFFILLECPL_VISEE
CREATE OR REPLACE FORCE VIEW "FFFILLECPL_VISEE" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","IDPRODUITLIB","QTE","PU","REMISES","IDBCDETAIL","TVA","IDDEVISE","DATY","MONTANTHT","MONTANTTTC","MONTANTTVA","MONTANTREMISE","MONTANT","IDPREVISION") AS
SELECT
    f.ID ,
    f.IDFACTUREFOURNISSEUR ,
    f.IDPRODUIT ,
    nvl(i.LIBELLE,p.LIBELLE) AS IDPRODUITLIB,
    f.QTE ,
    f.PU ,
    f.REMISES ,
    f.IDBCDETAIL ,
    f.TVA ,
    f.IDDEVISE,
    f2.DATY,
    CAST(f.QTE * f.PU AS NUMBER(30,2)) AS montantht,
    CAST(f.QTE * f.PU + (f.QTE * f.PU * f.TVA/100) AS NUMBER(30,2)) AS montantttc,
    CAST(f.QTE * f.PU * f.TVA/100 AS NUMBER(30,2)) AS montanttva,
    CAST((nvl(f.remises/100,0))*(f.QTE * f.PU) AS NUMBER(30,2)) AS montantRemise,
    CAST((1-nvl(f.remises/100,0))*(f.QTE * f.PU) AS NUMBER(30,2)) AS montant,
    f.idprevision
FROM FACTUREFOURNISSEURFILLE f
         LEFT JOIN FACTUREFOURNISSEUR f2 ON f2.ID = f.IDFACTUREFOURNISSEUR
         LEFT JOIN AS_INGREDIENTS p ON p.ID = f.IDPRODUIT
         LEFT JOIN AS_INGREDIENTS i ON i.ID = f.IDPRODUIT
where f2.ETAT >= 11
;
-- [301/1309] FFFILLERESTEALIVRER
CREATE OR REPLACE FORCE VIEW "FFFILLERESTEALIVRER" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","QTE","PU","REMISES","IDBCDETAIL","TVA","IDUNITE","IDPRODUITLIB","UNITELIB","PUPERTEGAIN") AS
SELECT f.id,
       f.IDFACTUREFOURNISSEUR,
       f.IDPRODUIT,
       cast(f.QTE - nvl(sum(abf.QUANTITE), 0) as number(38, 2)) AS qte,
       f.PU,
       f.REMISES,
       f.IDBCDETAIL,
       f.TVA,
       au.id as idunite,
       ai.LIBELLE as idproduitlib,
       au.val as unitelib,
       cast(fac.PUPERTEGAIN as number(38, 2)) as PUPERTEGAIN
FROM FACTUREFOURNISSEURFILLE f
         LEFT JOIN AS_BONDELIVRAISON_FILLE abf ON f.ID = abf.IDBC_FILLE
    LEFT JOIN AS_INGREDIENTS ai on ai.id = f.idproduit
    LEFT JOIN AS_UNITE au on au.id = ai.UNITE
    LEFT JOIN FFAVECPERTE_ff fac on fac.id = f.id
GROUP BY f.id, f.IDFACTUREFOURNISSEUR, f.IDPRODUIT, f.QTE, f.PU, f.REMISES, f.IDBCDETAIL, f.TVA, ai.LIBELLE, au.val, au.id, ai.id, fac.PUPERTEGAIN
;
-- [302/1309] FFFILLERESTEALIVRERLIB
CREATE OR REPLACE FORCE VIEW "FFFILLERESTEALIVRERLIB" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","IDPRODUITLIB","QTE","PU","REMISES","IDBCDETAIL","TVA","IDUNITE") AS
SELECT 
f.ID ,
f.IDFACTUREFOURNISSEUR ,
f.IDPRODUIT ,
p.VAL AS IDPRODUITLIB,
f.QTE ,
f.PU ,
f.REMISES ,
f.IDBCDETAIL ,
f.TVA , 
p.idunite
FROM FFFILLERESTEALIVRER f 
LEFT JOIN FACTUREFOURNISSEUR f2 ON f2.ID = f.IDFACTUREFOURNISSEUR 
LEFT JOIN PRODUIT p ON p.ID = f.IDPRODUIT
;
-- [303/1309] FF_FILLEBC_GRP
CREATE OR REPLACE FORCE VIEW "FF_FILLEBC_GRP" ("IDPRODUIT","IDBCDETAIL","QTE") AS
SELECT
	ff.idproduit,
	ff.IDBCDETAIL,
	sum(ff.qte) AS qte
	FROM (SELECT ff.* FROM FACTUREFOURNISSEURFILLE ff JOIN facturefournisseur f ON f.id=ff.idfacturefournisseur WHERE f.etat>=11  ) ff
GROUP BY idproduit,IDBCDETAIL
;
-- [304/1309] FF_FILLEBC_GRP_MERE
CREATE OR REPLACE FORCE VIEW "FF_FILLEBC_GRP_MERE" ("IDPRODUIT","IDBC","QTE") AS
SELECT
	ff.idproduit,
	ff.idbc,
	sum(ff.qte) AS qte
	FROM (SELECT ff.*, f.IDBC FROM FACTUREFOURNISSEURFILLE ff JOIN facturefournisseur f ON f.id=ff.idfacturefournisseur WHERE f.etat>=11) ff
GROUP BY idproduit, ff.idbc
;
-- [305/1309] FF_FILLEBL_GRP
CREATE OR REPLACE FORCE VIEW "FF_FILLEBL_GRP" ("PRODUIT","IDBC_FILLE","QTE") AS
SELECT
	produit,
	IDBC_FILLE,
	sum(quantite) AS qte
	FROM (SELECT blf.* FROM AS_BONDELIVRAISON_FILLE blf JOIN AS_BONDELIVRAISON bl ON bl.id=blf.NUMBL WHERE bl.etat>=11  )
GROUP BY produit,IDBC_FILLE
;
-- [306/1309] AS_BC_RESTE_A_FACTURER
CREATE OR REPLACE FORCE VIEW "AS_BC_RESTE_A_FACTURER" ("ID","IDBC","PRODUITLIB","UNITELIB","PRODUIT","QUANTITE","QTELIVRER","QTEFACTURER","FOURNISSEUR","FOURNISSEURLIB","DATY") AS
SELECT
    bc.id,
    bc.idbc,
    bc.produitlib,
    bc.unitelib,
    bc.produit,
    nvl(bc.quantite,0) AS quantite,
    nvl(bl.qte,0) AS qtelivrer,
    --nvl(ff.qte + ffm.qte,0) AS qtefacturer
    nvl(ffm.qte,0) AS qtefacturer,
    FOURNISSEUR,
    FOURNISSEURLIB,
    DATY
FROM AS_BONDECOMMANDE_CPL bc
         LEFT JOIN ff_fillebl_grp bl ON bc.id = bl.IDBC_FILLE
         --LEFT JOIN ff_fillebc_grp ff ON bc.id = ff.IDBCDETAIL
        left join FF_FILLEBC_GRP_MERE ffm on ffm.IDBC = bc.IDBC and ffm.IDPRODUIT = bc.PRODUIT
;
-- [307/1309] AS_BONDECOMMANDE_CPL_RECEPT
CREATE OR REPLACE FORCE VIEW "AS_BONDECOMMANDE_CPL_RECEPT" ("ID","IDBC","PRODUITLIB","UNITELIB","PRODUIT","QUANTITE","QTELIVRER","QTEFACTURER") AS
SELECT
    bc.id,
    bc.idbc,
    bc.produitlib,
    bc.unitelib,
    bc.produit,
    nvl(bc.quantite,0) AS quantite,
    nvl(bl.qte,0) AS qtelivrer,
    --nvl(ff.qte + ffm.qte,0) AS qtefacturer
    nvl(ffm.qte,0) AS qtefacturer
FROM AS_BONDECOMMANDE_CPL bc
         LEFT JOIN ff_fillebl_grp bl ON bc.id = bl.IDBC_FILLE
         --LEFT JOIN ff_fillebc_grp ff ON bc.id = ff.IDBCDETAIL
        left join FF_FILLEBC_GRP_MERE ffm on ffm.IDBC = bc.IDBC and ffm.IDPRODUIT = bc.PRODUIT
;
-- [308/1309] AS_BONDECOMMANDE_CPL_RECEPTGRP
CREATE OR REPLACE FORCE VIEW "AS_BONDECOMMANDE_CPL_RECEPTGRP" ("IDBC","TOTALCOMMANDE","TOTALRECEPT") AS
SELECT bc.idbc, sum (bc.quantite ) AS totalCommande , sum (bc.qtelivrer ) AS totalRecept FROM AS_BONDECOMMANDE_CPL_RECEPT bc GROUP BY bc.idbc
;
-- [309/1309] FF_GRPMERE
CREATE OR REPLACE FORCE VIEW "FF_GRPMERE" ("IDFACTUREFOURNISSEUR","MONTANTTOTAL","MONTANTPERTEGAIN") AS
SELECT
idfacturefournisseur,
sum(qte*pu) AS montanttotal,
sum(MONTANTPERTEGAIN) AS MONTANTPERTEGAIN
FROM facturefournisseurfille
GROUP BY idfacturefournisseur
;
-- [310/1309] FICHE_POSTE_COMPETENCES_LIB
CREATE OR REPLACE FORCE VIEW "FICHE_POSTE_COMPETENCES_LIB" ("ID","IDFICHEPOSTE","IDTYPECOMPETENCESFP","IDTYPECOMPETENCESFPLIB","DESCRIPTION","NIVEAU","NIVEAULIB") AS
SELECT
    fpc.ID,
    fpc.IDFICHEPOSTE,
    fpc.IDTYPECOMPETENCESFP,
    t.VAL AS IDTYPECOMPETENCESFPLIB,
    fpc.DESCRIPTION,
    fpc.NIVEAU,

    CASE
        WHEN fpc.NIVEAU = 0 THEN 'Non acquis'
        WHEN fpc.NIVEAU = 1 THEN 'En cours d''acquisition'
        WHEN fpc.NIVEAU = 2 THEN 'Acquis'
        WHEN fpc.NIVEAU = 3 THEN 'Maitrise'
        ELSE 'Inconnu'
        END AS NIVEAULIB

FROM FICHE_POSTE_COMPETENCES fpc
         LEFT JOIN TYPE_COMPETENCES_FP t
                   ON t.ID = fpc.IDTYPECOMPETENCESFP
;
-- [311/1309] FICHE_POSTE_COMPETENCES_VIDE
CREATE OR REPLACE FORCE VIEW "FICHE_POSTE_COMPETENCES_VIDE" ("ID","IDFICHEPOSTE","IDTYPECOMPETENCESFP","DESCRIPTION","NIVEAU") AS
SELECT
    ID,
    IDFICHEPOSTE,
    IDTYPECOMPETENCESFP,
    DESCRIPTION,
    NIVEAU
FROM FICHE_POSTE_COMPETENCES
;
-- [312/1309] FICHE_POSTE_LIB
CREATE OR REPLACE FORCE VIEW "FICHE_POSTE_LIB" ("ID","IDDEPARTEMENT","IDTYPECONTRAT","TITRE","REFERENCE","DESCRIPTION","MISSIONS","EXIGENCEPOSTE","SALAIREMIN","SALAIREMAX","ETAT","DATY","LIEUTRAVAIL","MATERIELDOCUMENT","OUTILS","CONDITIONTRAVAIL","MODECONTROLE","IDNIVEAUFORMATION","IDPERMIS","IDFONCTION","IDBU","AUTRE","IDCATEGORIEPAIE","IDQUALIFICATIONPAIE","IDDEPARTEMENTLIB","IDTYPECONTRATLIB","IDFONCTIONLIB","IDNIVEAUFORMATIONLIB","IDPERMISLIB","IDBULIB","IDCATEGORIEPAIELIB","IDQUALIFICATIONPAIELIB","ETATLIB","IDFAMILLEPROFESSIONELLIB","IDMETIERLIB","IDEMPLOILIB","IDCODEROMELIB") AS
SELECT
    f.ID,f.IDDEPARTEMENT,f.IDTYPECONTRAT,f.TITRE,f.REFERENCE,f.DESCRIPTION,f.MISSIONS,f.EXIGENCEPOSTE,f.SALAIREMIN,f.SALAIREMAX,f.ETAT,f.DATY,f.LIEUTRAVAIL,f.MATERIELDOCUMENT,f.OUTILS,f.CONDITIONTRAVAIL,f.MODECONTROLE,f.IDNIVEAUFORMATION,f.IDPERMIS,f.IDFONCTION,f.IDBU,f.AUTRE,f.IDCATEGORIEPAIE,f.IDQUALIFICATIONPAIE,
    d.VAL AS IDDEPARTEMENTLIB,
    t.VAL AS IDTYPECONTRATLIB,
    pf.VAL AS IDFONCTIONLIB,
    nf.DESCE AS idNiveauFormationLib,
    p.DESCE AS idPermisLib,
    bu.VAL AS idBuLib,
    cp.VAL AS idCategoriePaieLib,
    qp.VAL AS idQualificationPaieLib,

    CASE
        WHEN f.ETAT = '1'  THEN 'Cree'
        WHEN f.ETAT = '11' THEN 'Valide'
        WHEN f.ETAT = '0'  THEN 'Annule'
        ELSE 'Inconnu'
        END AS ETATLIB,
    fp.val AS idFamilleProfessionelLib,
    m.val AS idMetierLib,
    em.val AS idEmploiLib,
    cr.code AS idCodeRomeLib
FROM FICHE_POSTE f
         LEFT JOIN DEPARTEMENT d ON d.ID = f.IDDEPARTEMENT
         LEFT JOIN TYPE_CONTRAT t ON t.ID = f.IDTYPECONTRAT
         LEFT JOIN PAIE_FONCTION pf ON pf.ID = f.IDFONCTION
         LEFT JOIN FORMATION_DIPLOME nf ON nf.ID = f.idNiveauFormation
         LEFT JOIN PERMIS p ON p.ID = f.idPermis
         LEFT JOIN BUSINESS_UNITE bu ON bu.ID = f.idBu
         LEFT JOIN CATEGORIE_PAIE cp ON cp.ID = f.idCategoriePaie
         LEFT JOIN QUALIFICATION_PAIE qp ON qp.ID = f.idQualificationPaie
         LEFT JOIN FAMILLE_PROFESSIONNELLE fp ON fp.id = f.idFamilleProfessionel
         LEFT JOIN METIER m ON m.id = f.idMetier
         LEFT JOIN emploi em ON em.id = f.idEmploi
         LEFT JOIN code_rome cr ON cr.id = f.idCodeRome
;
-- [313/1309] FOURNISSEURCPL
CREATE OR REPLACE FORCE VIEW "FOURNISSEURCPL" ("ID","NOM","NIF","STAT","ADRESSE","CONTACT","CODEPOSTAL","COMPTE","IDTYPEFOURNISSEUR","COMPTEAUXILIAIRE","ESTACTIF","NB") AS
SELECT f."ID",f."NOM",f."NIF",f."STAT",f."ADRESSE",f."CONTACT",f."CODEPOSTAL",f."COMPTE",f."IDTYPEFOURNISSEUR",f."COMPTEAUXILIAIRE",f."ESTACTIF",
       1 as nb
FROM FOURNISSEUR f
;
-- [314/1309] FRAIS_MEDICAUXMOIS
CREATE OR REPLACE FORCE VIEW "FRAIS_MEDICAUXMOIS" ("IDPERSONNEL","MOIS","ANNEE","TOTAL_BRUT","FRAIS_MEDICAUX") AS
SELECT pe.idpersonnel,
       pe.mois,
       pe.annee,
       sum(pe.gain) AS total_brut,
       COALESCE(prfrm.gain, 0) AS frais_medicaux
FROM paie_edition pe
         LEFT JOIN paie_edition prfrm ON pe.idpersonnel = prfrm.idpersonnel AND pe.mois = prfrm.mois AND pe.annee = prfrm.annee AND prfrm.idelementpaie = 'PR000FRM'
WHERE (pe.idelementpaie IN ( SELECT pr.id
                             FROM paie_rubrique pr
                             WHERE pr.typerubrique = 'G' AND (pr.id NOT IN ('PR000210A', 'PR000FRM', 'PR000181'))))
GROUP BY pe.idpersonnel, pe.mois, pe.annee, prfrm.gain
;
-- [315/1309] FRAIS_MEDICAUX_ALL
CREATE OR REPLACE FORCE VIEW "FRAIS_MEDICAUX_ALL" ("ID","MATRICULE","NOM","POSTE","DATEEMBAUCHE","NUMERO_CNAPS","TOTAL_BRUT","FRAIS_MEDICAUX","MOIS","ANNEE","TEST","MOISLIB") AS
SELECT pip.id,
       pip.matricule,
       lp.nom || lp.prenom AS nom,
       pf.desce AS poste,
       pip.dateembauche,
       pip.numero_cnaps,
       frm.total_brut,
       frm.frais_medicaux,
       frm.mois,
       frm.annee AS annee,
       (frm.total_brut * 0.06) AS test,
       mo.val AS moislib
FROM paie_info_personnel pip
         LEFT JOIN paie_fonction pf ON pip.idfonction = pf.id
         LEFT JOIN log_personnel lp ON lp.id = pip.id
         LEFT JOIN frais_medicauxmois frm ON frm.idpersonnel = pip.id
         LEFT JOIN moiscp mo ON mo.id = frm.mois
;
-- [316/1309] FREQUENCE_PANNE_MACHINE
CREATE OR REPLACE FORCE VIEW "FREQUENCE_PANNE_MACHINE" ("ID","IDENTITE","IDSITUATION","IDMACHINE","DATY","DATEBESOIN","PRIORITE","ESTEXISTANT","DESCRIPTION","ETAT","IDDEPARTEMENT","CAUSE","DEMANDEUR","IDDEPARTEMENTMAINTENANCE","IDMACHINELIB","QTE") AS
SELECT
    d."ID",d."IDENTITE",d."IDSITUATION",d."IDMACHINE",d."DATY",d."DATEBESOIN",d."PRIORITE",d."ESTEXISTANT",d."DESCRIPTION",d."ETAT",d."IDDEPARTEMENT",d."CAUSE",d."DEMANDEUR",d."IDDEPARTEMENTMAINTENANCE" ,
    ai.LIBELLE AS idMachineLib,
    1 AS qte
FROM DEMANDETRAVAUX d
         LEFT JOIN AS_INGREDIENT_MAINTENANCE m
                   ON d.IDMACHINE = m.ID
         LEFT JOIN AS_INGREDIENTS ai
                   ON m.IDINGREDIENT = ai.ID
;
-- [317/1309] FRM_MOIS_ANNEE
CREATE OR REPLACE FORCE VIEW "FRM_MOIS_ANNEE" ("MOIS","ANNEE","TOTAL_FRM") AS
SELECT fma.mois,
       fma.annee AS annee,
       CAST(sum(fma.frais_medicaux) AS NUMBER(15,2)) AS total_frm
FROM frais_medicaux_all fma
GROUP BY fma.mois, fma.annee
;
-- [318/1309] FUMIGATION_LIB
CREATE OR REPLACE FORCE VIEW "FUMIGATION_LIB" ("ID","DATY","IDNUMEROVAGUE","IDOPERATEUR","IDLOT","IDBATIMENT","IDPARQUET","NOMBREOAC","HEUREDEBUTFUMIGATION","HEUREFINFUMIGATION","HEUREDEBUTEXTRACTION","HEUREFINEXTRACTION","IDPRODUIT","QTE","TEMPERATUREMIN","TEMPERATUREMAX","ETAT","IDNUMEROVAGUELIB","IDOPERATEURLIB","IDLOTLIB","IDBATIMENTLIB","IDPARQUETLIB","IDPRODUITLIB","ETATLIB") AS
SELECT f.ID,
       f.DATY,
       f.IDNUMEROVAGUE,
       f.IDOPERATEUR,
       f.IDLOT,
       f.IDBATIMENT,
       f.IDPARQUET,
       f.NOMBREOAC,
       f.HEUREDEBUTFUMIGATION,
       f.HEUREFINFUMIGATION,
       f.HEUREDEBUTEXTRACTION,
       f.HEUREFINEXTRACTION,
       f.IDPRODUIT,
       f.QTE,
       f.TEMPERATUREMIN,
       f.TEMPERATUREMAX,
       f.ETAT,
       nc.VAL                          AS IDNUMEROVAGUELIB,
       op.NOM || ' ' || op.PRENOM    AS IDOPERATEURLIB,
       l.NOMLOT                        AS IDLOTLIB,
       b.NOMBATIMENT                   AS IDBATIMENTLIB,
       p.VAL                           AS IDPARQUETLIB,
       ai.LIBELLE                      AS IDPRODUITLIB,
       CASE f.ETAT
           WHEN 1  THEN 'CREE'
           WHEN 11 THEN 'VALIDE'
           WHEN 0  THEN 'ANULLE'
           END                                AS ETATLIB
FROM FUMIGATION f
         LEFT JOIN NUMEROCOLLECTE nc ON nc.ID = f.IDNUMEROVAGUE
         LEFT JOIN LOG_PERSONNEL op ON op.ID = f.IDOPERATEUR
         LEFT JOIN LOT l ON l.ID = f.IDLOT
         LEFT JOIN BATIMENT b ON b.ID = f.IDBATIMENT
         LEFT JOIN PARQUET p ON p.ID = f.IDPARQUET
         LEFT JOIN AS_INGREDIENTS ai ON ai.ID = f.IDPRODUIT
;
-- [319/1309] GETNUMERO_CARTON_NEXT
CREATE OR REPLACE FORCE VIEW "GETNUMERO_CARTON_NEXT" ("ID","IDBC","ETAT","IDBL","NUMERO","DATECREATION","REMARQUE","NUMEROCARTON") AS
SELECT 
    c.ID,
    c.IDBC,
    c.ETAT,
    c.IDBL,
    c.NUMERO,
    c.DATECREATION,
    c.REMARQUE,
    COUNT(*) AS NUMEROCARTON
FROM CARTON c 
WHERE c.ETAT >= 11
GROUP BY 
    c.ID,
    c.IDBC,
    c.ETAT,
    c.IDBL,
    c.NUMERO,
    c.DATECREATION,
    c.REMARQUE
;
-- [320/1309] HISTOINSERTVUE
CREATE OR REPLACE FORCE VIEW "HISTOINSERTVUE" ("IDHISTORIQUE","DATEHISTORIQUE","HEURE","OBJET","ACTION","IDUTILISATEUR","REFOBJET","REMARQUE") AS
SELECT 
h.IDHISTORIQUE,
h.DATEHISTORIQUE,
h.HEURE,
h.OBJET,
h.ACTION,
h.IDUTILISATEUR,
h.REFOBJET,
h.REMARQUE||' '||h.REFOBJET AS REMARQUE
FROM HISTOINSERT h
;
-- [321/1309] HISTORIQUEAVECUSER
CREATE OR REPLACE FORCE VIEW "HISTORIQUEAVECUSER" ("IDHISTORIQUE","DATEHISTORIQUE","HEURE","OBJET","ACTION","IDUTILISATEUR","REFOBJET") AS
select
    idhistorique,
    datehistorique,
    heure,
    SUBSTR(objet, INSTR(objet, '.', -1) + 1) as objet,
    action,
    u.LOGINUSER as idutilisateur,
    refobjet
from HISTORIQUE h
         join UTILISATEUR u on u.REFUSER = h.IDUTILISATEUR
order by h.DATEHISTORIQUE desc, h.heure desc
;
-- [322/1309] HISTORIQUEDEMANDEMAX
CREATE OR REPLACE FORCE VIEW "HISTORIQUEDEMANDEMAX" ("IDDEMANDE","DATY","HEURE") AS
SELECT h.iddemande,
       max(h.daty) AS daty,
       max(h.heure) AS heure
FROM historiquedemande h
GROUP BY h.iddemande
;
-- [323/1309] HISTORIQUEINSPECTIONFILLELIB
CREATE OR REPLACE FORCE VIEW "HISTORIQUEINSPECTIONFILLELIB" ("ID","IDMERE","IDELEMENT","ETATINSPECTION","REMARQUE","IDELEMENTLIB") AS
SELECT
    hif.id,
    hif.idmere,
    hif.idelement,
    hif.etatinspection,
    hif.remarque,
    eim.IDELEMENTINSPECTIONLIB AS idElementLib
FROM historiqueinspectionfille hif
         LEFT JOIN ELEMENTINSPECTIONMACHINELIB eim
                   ON hif.idelement = eim.IDELEMENTINSPECTION
;
-- [324/1309] HISTORIQUEINSPECTIONLIB
CREATE OR REPLACE FORCE VIEW "HISTORIQUEINSPECTIONLIB" ("ID","DATY","HEURE","IDINSPECTEUR","IDELEMENT","REMARQUE","ETAT","IDINSPECTEURLIB","IDELEMENTLIB") AS
SELECT
    hi.id,
    hi.daty,
    hi.heure,
    hi.idinspecteur,
    hi.idelement,
    hi.remarque,
    hi.etat,
    p.nom AS idInspecteurLib,
    aim.libelle AS idElementLib
FROM HISTORIQUEINSPECTIONMERE hi
         JOIN personnel p
              ON hi.idinspecteur = p.id
         JOIN as_ingredient_maintenance aim
              ON hi.idelement = aim.id
;
-- [325/1309] HISTORIQUEPRIXLIB
CREATE OR REPLACE FORCE VIEW "HISTORIQUEPRIXLIB" ("ID","PRODUIT","DATY","PV","IDPRODUIT","IDFACTUREFOURNISSEURFILLE","REMARQUE","ETAT","ETATLIB") AS
SELECT 
  	h.ID,
  	ing.LIBELLE AS produit,
	h.DATY,
	h.PV,
	h.idProduit,
	h.idFacturefournisseurfille,
	h.REMARQUE,
	h.ETAT,
	CASE
		WHEN h.ETAT=1
		THEN 'CR&Eacute;&Eacute;'
		WHEN h.ETAT=11
		THEN 'VALID&Eacute;'
		WHEN h.ETAT=0
		THEN 'ANNUL&Eacute;'
	    WHEN h.ETAT=21
		THEN 'ENTAM&Eacute;'
	    WHEN h.ETAT=31
		THEN 'BLOQU&Eacute;'
	    WHEN h.ETAT=41
		THEN 'TERMIN&Eacute;'
	END AS ETATLIB
FROM HISTORIQUEPRIX h 
	LEFT JOIN AS_INGREDIENTS ing ON ing.ID = h.idProduit
;
-- [326/1309] HISTORIQUEPUINGTRIE
CREATE OR REPLACE FORCE VIEW "HISTORIQUEPUINGTRIE" ("ID","DATY","PU","REMARQUE","IDINGREDIENTS") AS
select "ID","DATY","PU","REMARQUE","IDINGREDIENTS" from HISTORIQUEPUING order by DATY desc
;
-- [327/1309] HISTORIQUEPVINGTRIE
CREATE OR REPLACE FORCE VIEW "HISTORIQUEPVINGTRIE" ("ID","DATY","PU","REMARQUE","IDINGREDIENTS") AS
select "ID","DATY","PU","REMARQUE","IDINGREDIENTS" from HISTORIQUEPVING order by DATY desc
;
-- [328/1309] HISTORIQUE_PRODUIT_LIB
CREATE OR REPLACE FORCE VIEW "HISTORIQUE_PRODUIT_LIB" ("ID","DATY","IDPRODUIT","IDPRODUITLIB","PUACHAT","PUVENTE") AS
SELECT 
hp.ID ,
hp.DATY ,
hp.IDPRODUIT ,
p.VAL AS IDPRODUITLIB,
hp.PUACHAT ,
hp.PUVENTE 
FROM HISTORIQUE_PRODUIT hp 
LEFT JOIN PRODUIT p ON p.ID = hp.IDPRODUIT
;
-- [329/1309] HSMOIS_CPL
CREATE OR REPLACE FORCE VIEW "HSMOIS_CPL" ("ID","IDCATEGORIE","MOIS","ANNEE","MOISLIB","DATY","IDDEPARTEMENT","ETAT","IDCATEGORIELIB","IDDEPARTEMENTLIB","ETATLIB") AS
SELECT
    hs."ID",hs."IDCATEGORIE",hs."MOIS",hs."ANNEE",
    TO_CHAR(

            TO_DATE(TO_CHAR(hs.mois, 'FM00'), 'MM'),

            'FMMonth',

            'NLS_DATE_LANGUAGE=FRENCH'

    ) AS moisLib,
    hs."DATY",hs."IDDEPARTEMENT",hs."ETAT",
    c.val AS idCategorieLib,
    d.val AS idDepartementLib,
    CASE
        WHEN hs.etat = 1 THEN 'CREE'
        WHEN hs.etat = 11 THEN 'VISEE'
        ELSE 'INCONNU'
        END AS etatLib
FROM
    HSMOIS hs
        LEFT JOIN CATEGORIE_PAIE c ON hs.idCategorie = c.id
        LEFT JOIN departement d ON hs.idDepartement = d.id
;
-- [330/1309] HS_FAB_SEMAINE_PARTRANCHE
CREATE OR REPLACE FORCE VIEW "HS_FAB_SEMAINE_PARTRANCHE" ("IDPERSONNE","IDRESSPARFAB","SEMAINE","ANNEE","MOIS","HS_TOTAL","HS30","HS50","MONTANT_TOTAL","IDDEPARTEMENT","IDCATEGORIE") AS
SELECT
    pip.id as idpersonne,
    hp.IDRESSPARFAB,
    TO_CHAR(f.daty, 'IYYY-IW') AS semaine,
    p.annee,
    p.mois,

    SUM(hp.HS) AS hs_total,

    CASE
        WHEN SUM(hp.HS) <= 8 THEN SUM(hp.HS)
        ELSE 8
        END AS hs30,

    CASE
        WHEN SUM(hp.HS) <= 8 THEN 0
        ELSE SUM(hp.HS) - 8
        END AS hs50,

    SUM(hp.MONTANT) AS montant_total,

    pip.IDDEPARTEMENT,
    pip.IDCATEGORIE_PAIE AS idCategorie

FROM HEURESUPFABRICATION hp
         JOIN FABRICATION f ON f.id = hp.IDFABRICATION
         LEFT JOIN PERIODEPAIE p
                   ON f.daty BETWEEN p.datedebut AND p.datefin
         LEFT JOIN RESSOURCEPARFABRICATION ress ON ress.id = hp.IDRESSPARFAB
         LEFT JOIN PAIE_INFO_PERSONNEL pip
                   ON pip.id = ress.IDRESSOURCE

GROUP BY
    pip.id,
    hp.IDRESSPARFAB,
    TO_CHAR(f.daty, 'IYYY-IW'),
    p.annee,
    p.mois,
    pip.IDDEPARTEMENT,
    pip.IDCATEGORIE_PAIE
;
-- [331/1309] HS_PAR_FAB
CREATE OR REPLACE FORCE VIEW "HS_PAR_FAB" ("IDMERE","CATEGORIE","MONTANTPERSONNEL") AS
SELECT
    fab.id AS idMere,
    'CATING000001' AS CATEGORIE,
    CAST(SUM(hs.MONTANT) AS NUMBER(30,2)) AS montantPersonnel
FROM HEURESUPFABRICATION hs
         JOIN FABRICATION fab ON fab.id = hs.IDFABRICATION
GROUP BY fab.id
;
-- [332/1309] HS_PAR_OF
CREATE OR REPLACE FORCE VIEW "HS_PAR_OF" ("IDMERE","CATEGORIE","MONTANTPERSONNEL") AS
SELECT
    fille.IDMERE AS idMere,
    'CATING000001' AS CATEGORIE,
    CAST(SUM(hs.MONTANT) AS NUMBER(30,2)) AS montantPersonnel
FROM HEURESUPFABRICATION hs
         JOIN FABRICATION fab ON fab.id = hs.IDFABRICATION
         JOIN OFFILLE fille ON fille.id = fab.IDOFFILLE
GROUP BY fille.IDMERE
;
-- [333/1309] HS_PAR_OFFILLE
CREATE OR REPLACE FORCE VIEW "HS_PAR_OFFILLE" ("IDMERE","CATEGORIE","MONTANTPERSONNEL") AS
SELECT
    fille.id AS idMere,
    'CATING000001' AS CATEGORIE,
    CAST(SUM(hs.MONTANT) AS NUMBER(30,2)) AS montantPersonnel
FROM HEURESUPFABRICATION hs
         JOIN FABRICATION fab ON fab.id = hs.IDFABRICATION
         JOIN OFFILLE fille ON fille.id = fab.IDOFFILLE
GROUP BY fille.id
;
-- [334/1309] IMPORTOAC_LIB
CREATE OR REPLACE FORCE VIEW "IMPORTOAC_LIB" ("ID","DATERECEPTION","DATEPONTE","DATECOLLECTE","IDNUMEROCOLLECTE","HEUREDEPARTFERME","HEUREARRIVEECOUVOIR","IDRESPONSABLE","IDCHAMBREFROIDE","IDCHAUFFEUR","IDVEHICULE","TEMPERATUREMINVEHICULE","TEMPERATUREMAXVEHICULE","IDPROVENANCE","IDNUMEROCOLLECTELIB","IDRESPONSABLELIB","IDCHAMBREFROIDELIB","IDCHAUFFEURLIB","IDVEHICULELIB") AS
SELECT r."ID",
       r."DATERECEPTION",
       r."DATEPONTE",
       r."DATECOLLECTE",
       r."IDNUMEROCOLLECTE",
       r."HEUREDEPARTFERME",
       r."HEUREARRIVEECOUVOIR",
       r."IDRESPONSABLE",
       r."IDCHAMBREFROIDE",
       r."IDCHAUFFEUR",
       r."IDVEHICULE",
       r."TEMPERATUREMINVEHICULE",
       r."TEMPERATUREMAXVEHICULE",
       r."IDPROVENANCE",
       nc."VAL"                          AS "IDNUMEROCOLLECTELIB",
       resp."NOM" || ' ' || resp."PRENOM" AS "IDRESPONSABLELIB",
       cf."VAL"                          AS "IDCHAMBREFROIDELIB",
       chf."NOM" || ' ' || chf."PRENOM"  AS "IDCHAUFFEURLIB",
       v."VAL"                           AS "IDVEHICULELIB"
FROM "RECEPTIONOAC" r
         LEFT JOIN "NUMEROCOLLECTE" nc ON nc."ID" = r."IDNUMEROCOLLECTE"
         LEFT JOIN "LOG_PERSONNEL" resp ON resp."ID" = r."IDRESPONSABLE"
         LEFT JOIN "MAGASIN2" cf ON cf."ID" = r."IDCHAMBREFROIDE"
         LEFT JOIN "LOG_PERSONNEL" chf ON chf."ID" = r."IDCHAUFFEUR"
         LEFT JOIN "VEHICULE" v ON v."ID" = r."IDVEHICULE" WHERE r.IDPROVENANCE IS NOT NULL
;
-- [335/1309] IMPORTRECEPTIONOAC
CREATE OR REPLACE FORCE VIEW "IMPORTRECEPTIONOAC" ("ID","DATERECEPTION","DATEPONTE","DATECOLLECTE","IDNUMEROCOLLECTE","HEUREDEPARTFERME","HEUREARRIVEECOUVOIR","IDRESPONSABLE","IDCHAMBREFROIDE","IDCHAUFFEUR","IDVEHICULE","TEMPERATUREMINVEHICULE","TEMPERATUREMAXVEHICULE","IDPROVENANCE","ETAT","IDNUMEROCOLLECTELIB","IDRESPONSABLELIB","IDCHAMBREFROIDELIB","IDCHAUFFEURLIB","IDVEHICULELIB","ETATLIB") AS
SELECT r."ID",
       r."DATERECEPTION",
       r."DATEPONTE",
       r."DATECOLLECTE",
       r."IDNUMEROCOLLECTE",
       r."HEUREDEPARTFERME",
       r."HEUREARRIVEECOUVOIR",
       r."IDRESPONSABLE",
       r."IDCHAMBREFROIDE",
       r."IDCHAUFFEUR",
       r."IDVEHICULE",
       r."TEMPERATUREMINVEHICULE",
       r."TEMPERATUREMAXVEHICULE",
       r."IDPROVENANCE",
       r."ETAT",
       nc."VAL"                          AS "IDNUMEROCOLLECTELIB",
       resp."NOM" || ' ' || resp."PRENOM" AS "IDRESPONSABLELIB",
       cf."VAL"                          AS "IDCHAMBREFROIDELIB",
       chf."NOM" || ' ' || chf."PRENOM"  AS "IDCHAUFFEURLIB",
       v."VAL"                           AS "IDVEHICULELIB",
       CASE r."ETAT"
            WHEN 1  THEN 'CREE'
            WHEN 11 THEN 'VALIDE'
            WHEN 0  THEN 'ANULLE'
       END                                AS "ETATLIB"
FROM "RECEPTIONOAC" r
         LEFT JOIN "NUMEROCOLLECTE" nc ON nc."ID" = r."IDNUMEROCOLLECTE"
         LEFT JOIN "LOG_PERSONNEL" resp ON resp."ID" = r."IDRESPONSABLE"
         LEFT JOIN "MAGASIN2" cf ON cf."ID" = r."IDCHAMBREFROIDE"
         LEFT JOIN "LOG_PERSONNEL" chf ON chf."ID" = r."IDCHAUFFEUR"
         LEFT JOIN "VEHICULE" v ON v."ID" = r."IDVEHICULE"
;
-- [336/1309] IMPORTOAC
CREATE OR REPLACE FORCE VIEW "IMPORTOAC" ("ID","DATERECEPTION","DATEPONTE","DATECOLLECTE","IDNUMEROCOLLECTE","HEUREDEPARTFERME","HEUREARRIVEECOUVOIR","IDRESPONSABLE","IDCHAMBREFROIDE","IDCHAUFFEUR","IDVEHICULE","TEMPERATUREMINVEHICULE","TEMPERATUREMAXVEHICULE","IDPROVENANCE","ETAT","IDNUMEROCOLLECTELIB","IDRESPONSABLELIB","IDCHAMBREFROIDELIB","IDCHAUFFEURLIB","IDVEHICULELIB","ETATLIB","IDPROVENANCELIB") AS
SELECT rl."ID",
       rl."DATERECEPTION",
       rl."DATEPONTE",
       rl."DATECOLLECTE",
       rl."IDNUMEROCOLLECTE",
       rl."HEUREDEPARTFERME",
       rl."HEUREARRIVEECOUVOIR",
       rl."IDRESPONSABLE",
       rl."IDCHAMBREFROIDE",
       rl."IDCHAUFFEUR",
       rl."IDVEHICULE",
       rl."TEMPERATUREMINVEHICULE",
       rl."TEMPERATUREMAXVEHICULE",
       rl."IDPROVENANCE",
       rl."ETAT",
       rl."IDNUMEROCOLLECTELIB",
       rl."IDRESPONSABLELIB",
       rl."IDCHAMBREFROIDELIB",
       rl."IDCHAUFFEURLIB",
       rl."IDVEHICULELIB",
       rl."ETATLIB",
       o."VAL" AS "IDPROVENANCELIB"
FROM "IMPORTRECEPTIONOAC" rl
         LEFT JOIN "ORIGINELOT" o ON o."ID" = rl."IDPROVENANCE"
WHERE rl."IDPROVENANCE" IS NOT NULL
;
-- [337/1309] IMPRIMEDECLARATIONLIB
CREATE OR REPLACE FORCE VIEW "IMPRIMEDECLARATIONLIB" ("ID","NUMERO","RUBRIQUE","MONTANT","MONTANTADECLARER") AS
SELECT
    i."ID",i."NUMERO",i."RUBRIQUE",
    0 AS montant,
    0 AS montantadeclarer
FROM IMPRIMEDECLARATION i
;
-- [338/1309] INFOSAUTOLIB
CREATE OR REPLACE FORCE VIEW "INFOSAUTOLIB" ("ID","IDINGREDIENT","DESCRIPTION","NUMERODEPARC","DATEPREMIEREMISEENCIRCULATION","IMMATRICULATION","NOTE","FOURNISSEUR","NUMERO","VOLUME","MONTANT","TYPE","VIN","MARQUE","MODELE","ANNEE","NOMBREDEPLACES","NOMBREDEPORTES","PUISSANCEFISCALE","BAILLEUR","VALEURINITIALE","DATEDEBUT","DURREEENMOIS","MENSUALITE","VENDEUR","PRIX","DATEDACHAT","NUMERODIMMOBILISATION","DUREEDAMORTISSEMENTENMOIS","PNEUS","BATTERIE","HUILEMOTEUR","HUILEBOITEDEVITESSE","TYPEDECARBURANT","CONSOMMATION","UNITEDECONSOMMATION","IDINGREDIENTLIB","TYPEDECARBURANTLIB","UNITEDECONSOMMATIONLIB") AS
(
    select
    ia."ID",ia."IDINGREDIENT",ia."DESCRIPTION",ia."NUMERODEPARC",ia."DATEPREMIEREMISEENCIRCULATION",ia."IMMATRICULATION",ia."NOTE",ia."FOURNISSEUR",ia."NUMERO",ia."VOLUME",ia."MONTANT",ia."TYPE",ia."VIN",ia."MARQUE",ia."MODELE",ia."ANNEE",ia."NOMBREDEPLACES",ia."NOMBREDEPORTES",ia."PUISSANCEFISCALE",ia."BAILLEUR",ia."VALEURINITIALE",ia."DATEDEBUT",ia."DURREEENMOIS",ia."MENSUALITE",ia."VENDEUR",ia."PRIX",ia."DATEDACHAT",ia."NUMERODIMMOBILISATION",ia."DUREEDAMORTISSEMENTENMOIS",ia."PNEUS",ia."BATTERIE",ia."HUILEMOTEUR",ia."HUILEBOITEDEVITESSE",ia."TYPEDECARBURANT",ia."CONSOMMATION",ia."UNITEDECONSOMMATION",
    ing.libelle as idingredientLib,
    tc.val as typeDeCarburantLib,
    uc.val as unitedeconsommationLib
    from INFOSAUTO ia
    left join AS_INGREDIENTS ing on ia.idingredient=ing.id
    left join TYPECARBURANT tc on tc.id=ia.TYPEDECARBURANT
    left join UNITECONSO uc on uc.id=ia.unitedeconsommation
)
;
-- [339/1309] INSERTION_FACTURE_FOURNISSEUR
CREATE OR REPLACE FORCE VIEW "INSERTION_FACTURE_FOURNISSEUR" ("ID","IDFOURNISSEUR","IDMODEPAIEMENT","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","REFERENCE","IDBC","DEVISE","TAUX","IDMAGASIN","IDDEVISE") AS
SELECT 
f."ID",f."IDFOURNISSEUR",f."IDMODEPAIEMENT",f."DATY",f."DESIGNATION",f."DATEECHEANCEPAIEMENT",f."ETAT",f."REFERENCE",f."IDBC",f."DEVISE",f."TAUX",f."IDMAGASIN",
cast(' ' AS varchar(100)) AS iddevise
FROM FACTUREFOURNISSEUR f
;
-- [340/1309] INSERTION_VENTE
CREATE OR REPLACE FORCE VIEW "INSERTION_VENTE" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","IDDEVISE","ESTPREVU","DATYPREVU","IDRESERVATION","ECHEANCEFACTURE","MODEPAIEMENT","MODELIVRAISON","FRAISLIVRAISON","REFERENCEFACT","LIEULIVRAISON","DATELIVRAISON","IDREPRESENTANT") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       v.IDORIGINE,
       v.IDCLIENT,
       CAST(' ' AS varchar(100)) AS iddevise,
       v.ESTPREVU,
       v.DATYPREVU,
       v.IDRESERVATION,
       v.echeancefacture,
       v.modepaiement,
       v.modelivraison,
       v.fraislivraison,
       v.referencefact,
       v.LIEULIVRAISON,
       v.DATELIVRAISON,
       V.IDREPRESENTANT
FROM VENTE v
;
-- [341/1309] INSERTION_VENTEAUTOCOMPLETE
CREATE OR REPLACE FORCE VIEW "INSERTION_VENTEAUTOCOMPLETE" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","IDDEVISE","ESTPREVU","DATYPREVU","IDRESERVATION","ECHEANCEFACTURE","MODEPAIEMENT","MODELIVRAISON","FRAISLIVRAISON","REFERENCEFACT","LIEULIVRAISON","DATELIVRAISON") AS
SELECT 
i.ID,
i.DESIGNATION,
i.IDMAGASIN,
i.DATY,
i.REMARQUE,
i.ETAT,
i.IDORIGINE,
CASE
	WHEN i.IDCLIENT IS NULL 
	THEN i.IDCLIENT
	ELSE i.IDCLIENT||'---'||c.nom 
END AS IDCLIENT ,
i.IDDEVISE,
i.ESTPREVU,
i.DATYPREVU,
i.IDRESERVATION,
i.ECHEANCEFACTURE,
i.MODEPAIEMENT,
i.MODELIVRAISON,
i.FRAISLIVRAISON,
i.REFERENCEFACT,
i.LIEULIVRAISON,
i.DATELIVRAISON
FROM INSERTION_VENTE i 
LEFT JOIN CLIENT c ON c.id = i.IDCLIENT
;
-- [342/1309] INSERTION_VENTE_PERSONNEL
CREATE OR REPLACE FORCE VIEW "INSERTION_VENTE_PERSONNEL" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","IDDEVISE","ESTPREVU","DATYPREVU","IDRESERVATION","IDCOMMERCIAL","IDMODEPAIEMENT","REMISE","REMISEMONTANT","HEURESAISIE","IDRESPONSABLE") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       v.IDORIGINE,
       v.IDCLIENT,
       CAST(' ' AS varchar(100)) AS iddevise,
       v.ESTPREVU,
       v.DATYPREVU,
       v.IDRESERVATION,
       v.idCommercial,
       v.idmodepaiement,
       v.remise,
       v.remiseMontant,
       v.HEURESAISIE,
       v.IDRESPONSABLE
FROM VENTE v
;
-- [343/1309] INSERTION_VENTE_PERSONNEL_VIDE
CREATE OR REPLACE FORCE VIEW "INSERTION_VENTE_PERSONNEL_VIDE" ("ID","DATY","DESIGNATION","IDMAGASIN","REMARQUE","ETAT","IDORIGINE","IDCLIENT","IDDEVISE","ESTPREVU","DATYPREVU","IDRESERVATION","IDCOMMERCIAL","IDMODEPAIEMENT","REMISE","REMISEMONTANT","HEURESAISIE","IDRESPONSABLE") AS
SELECT id,daty,designation,idmagasin,remarque,etat,idorigine,idclient,iddevise,estprevu,datyprevu,idreservation,idcommercial,idmodepaiement,remise,remisemontant,HEURESAISIE, IDRESPONSABLE FROM INSERTION_VENTE_PERSONNEL
;
-- [344/1309] INSPECTIONFILLELIB
CREATE OR REPLACE FORCE VIEW "INSPECTIONFILLELIB" ("ID","IDMERE","IDELEMENT","IDELEMENTLIB","IDETATINSPECTION","REMARQUE","IDETATINSPECTIONLIB","IDMACHINELIB","IDMACHINE","IDLIGNE","IDLIGNELIB") AS
(
SELECT
    ifi.id,
    ifi.idmere,
    ifi.idElement,
    eis.val     AS idElementlib,
    ifi.idEtatInspection,
    ifi.remarque,
    ei.val    AS idEtatInspectionlib,
    m.libelle AS idMachinelib,
    m.id AS idMachine,
     l.id AS idLigne,
    l.VAL AS idLigneLib
FROM InspectionFille ifi
         LEFT JOIN ElementInspection eis
                   ON ifi.idElement = eis.id
         LEFT JOIN ElementInspectionMachine ai
                   ON ai.idelementinspection = ifi.idelement
         LEFT JOIN AS_INGREDIENT_MAINTENANCE m
                   ON ai.idMachine = m.id
         LEFT JOIN EtatInspection ei
                   ON ifi.idEtatInspection = ei.id
         left join ligne l on m.IDLIGNE = l.id)
;
-- [345/1309] INSPECTIONFILLECPL
CREATE OR REPLACE FORCE VIEW "INSPECTIONFILLECPL" ("ID","IDMERE","IDELEMENT","IDETATINSPECTION","IDETATINSPECTIONLIB","IDELEMENTLIB","REMARQUE","IDMACHINELIB","IDMACHINE","IDLIGNE","IDLIGNELIB") AS
select 
    ifl.id,
    ifl.idMere,
    ifl.idElement ,
    ifl.idEtatInspection,
    ifl.idEtatInspectionlib ,
    ifl.idElementLib,
    ifl.remarque,
    ifl.idMachineLib,
    ifl.idMachine,
    l.id AS idLigne,
    l.VAL AS idLigneLib
from inspectionFIlleLib ifl 
join inspectionMere im on ifl.idMere = im.id
join as_ingredient_Maintenance am on im.IDELEMENT = am.id
left join ligne l on am.IDLIGNE = l.id
;
-- [346/1309] INSPECTIONMERELIB
CREATE OR REPLACE FORCE VIEW "INSPECTIONMERELIB" ("ID","DATY","HEURE","IDINSPECTEUR","IDELEMENT","REMARQUE","ETAT","IDINSPECTEURLIB") AS
SELECT
    i."ID",i."DATY",i."HEURE",i."IDINSPECTEUR",i."IDELEMENT",i."REMARQUE",i."ETAT",
    p.NOM AS IDINSPECTEURLIB
FROM INSPECTIONMERE i
         LEFT JOIN PERSONNEL p ON i.IDINSPECTEUR = p.ID
;
-- [347/1309] INVENTAIREDATEHEURE
CREATE OR REPLACE FORCE VIEW "INVENTAIREDATEHEURE" ("ID","DATY","DESIGNATION","IDMAGASIN","ETAT","REMARQUE","IDCATEGORIE","HEURE") AS
select i.ID, TO_DATE(TO_CHAR(i.DATY, 'YYYY-MM-DD') || ' ' || NVL(i.HEURE, '00:00:00'), 'YYYY-MM-DD HH24:MI:SS') as DATY, DESIGNATION, IDMAGASIN, ETAT, REMARQUE, IDCATEGORIE, HEURE from INVENTAIRE i
;
-- [348/1309] INVENTAIREFILLEAUTOCOMPLETE
CREATE OR REPLACE FORCE VIEW "INVENTAIREFILLEAUTOCOMPLETE" ("ID","IDINVENTAIRE","IDPRODUIT","EXPLICATION","IDJAUGE","QUANTITETHEORIQUE","QUANTITE","MVTSRC","PU","IDFOURNISSEUR","DATY") AS
SELECT
    inf.id,
    inf.idinventaire,
    CASE
        WHEN inf.idproduit IS NOT NULL
            THEN inf.idproduit||'---'||ai.libelle
        END AS idproduit,
    inf.explication AS explication,
    inf.idjauge,
    inf.quantitetheorique,
    inf.quantite,
    inf.mvtsrc,
    inf.pu,
    inf.idfournisseur,
    inf.daty
FROM inventairefille inf
         LEFT JOIN AS_INGREDIENTS ai ON ai.id=inf.idproduit
;
-- [349/1309] INVENTAIREFILLEGROUPEMERE
CREATE OR REPLACE FORCE VIEW "INVENTAIREFILLEGROUPEMERE" ("IDINVENTAIRE","MONTANTQUANTITE") AS
select f.IDINVENTAIRE,cast(sum(nvl(f.pu*f.QUANTITE,0)) as number(30,2)) as montantQuantite
from INVENTAIREFILLE f group by f.IDINVENTAIRE
;
-- [350/1309] INVENTAIREFILLELIB
CREATE OR REPLACE FORCE VIEW "INVENTAIREFILLELIB" ("ID","IDINVENTAIRE","IDPRODUIT","IDPRODUITLIB","EXPLICATION","QUANTITETHEORIQUE","QUANTITE","LIBELLEEXTACTE","PU","ECART","ETAT","ETATLIB") AS
SELECT
    i.ID ,
    i.IDINVENTAIRE ,
    i.IDPRODUIT ,
    p.libelle AS IDPRODUITLIB,
    i.EXPLICATION ,
    i.QUANTITETHEORIQUE ,
    i.QUANTITE,
    p.LIBELLEEXTACTE,
    i.pu,
    cast((i.QUANTITE - i.QUANTITETHEORIQUE) as decimal(30,2)) AS ecart,
    i.ETAT,
    CASE
        WHEN i.ETAT = 0
            THEN 'ANNUL&Eacute;E'
        WHEN i.ETAT = 1
            THEN 'CR&Eacute;&Eacute;E'
        WHEN i.ETAT = 11
            THEN 'VALID&Eacute;E'
        END AS ETATLIB
FROM INVENTAIREFILLE i
     LEFT JOIN AS_INGREDIENTS  p ON p.ID  = i.IDPRODUIT
;
-- [351/1309] INVENTAIREFILLEMERE
CREATE OR REPLACE FORCE VIEW "INVENTAIREFILLEMERE" ("ID","IDINVENTAIRE","IDPRODUIT","EXPLICATION","IDJAUGE","PU","QUANTITETHEORIQUE","QUANTITE","MVTSRC","IDMAGASIN") AS
SELECT
	i."ID",i."IDINVENTAIRE",i."IDPRODUIT",i."EXPLICATION",i."IDJAUGE",i."PU",i."QUANTITETHEORIQUE",i."QUANTITE",i."MVTSRC",
	i2.IDMAGASIN
FROM
	INVENTAIREFILLE i
JOIN INVENTAIRE i2 ON
	i.IDINVENTAIRE = i2.ID 
WHERE ETAT>0
;
-- [352/1309] INVENTAIREFILLETYPEMVT
CREATE OR REPLACE FORCE VIEW "INVENTAIREFILLETYPEMVT" ("ID","IDINVENTAIRE","IDPRODUIT","EXPLICATION","IDJAUGE","QUANTITETHEORIQUE","QUANTITE","MVTSRC","PU","IDFOURNISSEUR","DATY","TYPESTOCK") AS
select f."ID",f."IDINVENTAIRE",f."IDPRODUIT",f."EXPLICATION",f."IDJAUGE",f."QUANTITETHEORIQUE",f."QUANTITE",f."MVTSRC",f."PU",f."IDFOURNISSEUR",f."DATY",ing.TYPESTOCK from INVENTAIREFILLE f left join AS_INGREDIENTS ing on f.IDPRODUIT=ing.id
;
-- [353/1309] INVENTAIREFILLEUPDATE
CREATE OR REPLACE FORCE VIEW "INVENTAIREFILLEUPDATE" ("ID","IDINVENTAIRE","IDPRODUIT","EXPLICATION","IDJAUGE","QUANTITETHEORIQUE","QUANTITE","MVTSRC","PU","IDFOURNISSEUR","DATY") AS
SELECT
    inf.id,
    inf.idinventaire,
    CASE
        WHEN inf.idproduit IS NOT NULL
            THEN inf.idproduit||'---'||ai.libelle
        END AS idproduit,
    ai.LIBELLE ||' - '|| inf.explication AS explication,
    inf.idjauge,
    inf.quantitetheorique,
    inf.quantite,
    inf.mvtsrc,
    inf.pu,
    inf.idfournisseur,
    inf.daty
FROM inventairefille inf
         LEFT JOIN AS_INGREDIENTS ai ON ai.id=inf.idproduit
;
-- [354/1309] INVENTAIREMEREVIDE
CREATE OR REPLACE FORCE VIEW "INVENTAIREMEREVIDE" ("ID","DATY","DESIGNATION","IDMAGASIN","ETAT") AS
select 'invVide' as id, TO_DATE('01/01/2026', 'DD-MM-YYYY') as daty, 'inventaire vide' as designation,'' as idmagasin,11 as etat from dual
;
-- [355/1309] INVENTAIREMEREVIDEMAGASIN
CREATE OR REPLACE FORCE VIEW "INVENTAIREMEREVIDEMAGASIN" ("ID","DATY","DESIGNATION","IDMAGASIN","ETAT","REMARQUE","IDCATEGORIE") AS
select inventaireMereVide.id, daty, designation, magasin2.id as idmagasin, inventaireMereVide.etat,'inv vide' as remarque,null as idcategorie from inventaireMereVide,magasin2
;
-- [356/1309] INVENTAIREAVECVIDE
CREATE OR REPLACE FORCE VIEW "INVENTAIREAVECVIDE" ("ID","DATY","DESIGNATION","IDMAGASIN","ETAT","REMARQUE","IDCATEGORIE") AS
select "ID","DATY","DESIGNATION","IDMAGASIN","ETAT","REMARQUE","IDCATEGORIE" from INVENTAIRE union all select "ID","DATY","DESIGNATION","IDMAGASIN","ETAT","REMARQUE","IDCATEGORIE" from inventaireMereVideMagasin
;
-- [357/1309] INVENTAIRE_FILLE_CPL
CREATE OR REPLACE FORCE VIEW "INVENTAIRE_FILLE_CPL" ("ID","IDINVENTAIRE","IDPRODUIT","IDPRODUITLIB","EXPLICATION","QUANTITETHEORIQUE","QUANTITE","DATY","IDMAGASIN","IDJAUGE","ETAT","MVTSRC") AS
SELECT
i.ID ,
i.IDINVENTAIRE ,
i.IDPRODUIT ,
p.LIBELLE AS IDPRODUITLIB,
i.EXPLICATION ,
i.QUANTITETHEORIQUE ,
i.QUANTITE ,
i2.DATY ,
i2.IDMAGASIN ,
i.idJauge,
i2.ETAT,
i.MVTSRC
FROM INVENTAIREFILLE i
LEFT JOIN AS_INGREDIENTS  p ON p.ID  = i.IDPRODUIT
LEFT JOIN INVENTAIRE i2 ON i2.ID  = i.IDINVENTAIRE
;
-- [358/1309] INVENTAIRE_FILLE_CPL_VALIDE
CREATE OR REPLACE FORCE VIEW "INVENTAIRE_FILLE_CPL_VALIDE" ("ID","IDINVENTAIRE","IDPRODUIT","IDPRODUITLIB","EXPLICATION","QUANTITETHEORIQUE","QUANTITE","DATY","IDMAGASIN","IDJAUGE","MVTSRC","ETAT") AS
SELECT
i."ID",i."IDINVENTAIRE",i."IDPRODUIT",i."IDPRODUITLIB",i."EXPLICATION",i."QUANTITETHEORIQUE",i."QUANTITE",i."DATY",i."IDMAGASIN",i."IDJAUGE",i.MVTSRC,i."ETAT"
FROM INVENTAIRE_FILLE_CPL i
JOIN INVENTAIRE inventaire ON inventaire.ID  = i.IDINVENTAIRE
WHERE inventaire.ETAT >=11
;
-- [359/1309] JOURS_PAR_MOIS
CREATE OR REPLACE FORCE VIEW "JOURS_PAR_MOIS" ("ANNEE","MOIS","NB_JOUR","CONGE_JOURNALIER") AS
SELECT
    EXTRACT(YEAR FROM ADD_MONTHS(DATE '2019-01-01', LEVEL - 1)) AS annee,
    EXTRACT(MONTH FROM ADD_MONTHS(DATE '2019-01-01', LEVEL - 1)) AS mois,
    TO_NUMBER(TO_CHAR(LAST_DAY(ADD_MONTHS(DATE '2019-01-01', LEVEL - 1)), 'DD')) AS nb_jour,
    ROUND(2.5 / TO_NUMBER(TO_CHAR(LAST_DAY(ADD_MONTHS(DATE '2019-01-01', LEVEL - 1)), 'DD')), 6) AS conge_journalier
FROM dual
    CONNECT BY ADD_MONTHS(DATE '2019-01-01', LEVEL - 1) < SYSDATE
;
-- [360/1309] LIAISONCODELIB
CREATE OR REPLACE FORCE VIEW "LIAISONCODELIB" ("ID","IDCODEIMPOT","IDCOMPTE","FORMULE","TAXABLE","IDCODEIMPOTLIB") AS
SELECT
    ls.id,
    ls.idCodeImpot,
    ls.idCompte,
    ls.FORMULE,
    CASE
        WHEN ls.TAXABLE = 1 THEN 'Oui'
        WHEN ls.TAXABLE = 0 THEN 'Non'
        ELSE NULL
        END AS TAXABLE,
      i.rubrique AS IDCODEIMPOTLIB
FROM LiaisonCodeImpot ls
LEFT JOIN imprimedeclaration i ON  ls.idcodeimpot=i.id
;
-- [361/1309] LIAISONCODESAISIE
CREATE OR REPLACE FORCE VIEW "LIAISONCODESAISIE" ("ID","IDCODEIMPOT","IDCOMPTE","VALEUR","FORMULE","TAXABLE") AS
SELECT
    id,
    idCodeImpot,
    idCompte,
    ' ' AS valeur,
    FORMULE,
    TAXABLE
FROM LiaisonCodeImpot
;
-- [362/1309] LIAISONPAIEMENTMVTCAISSEGRP
CREATE OR REPLACE FORCE VIEW "LIAISONPAIEMENTMVTCAISSEGRP" ("IDMVTCAISSE","MONTANT") AS
select id1 as idmvtcaisse, sum(MONTANT) as montant from LIAISONPAIEMENT where etat = 11
group by id1
;
-- [363/1309] LIAISONPAIEMENTMVTCAISSEGRP2
CREATE OR REPLACE FORCE VIEW "LIAISONPAIEMENTMVTCAISSEGRP2" ("IDMVTCAISSE","MONTANT") AS
select id1 as idmvtcaisse, cast(sum(nvl(MONTANT, 0)) as number(30,2)) as montant from LIAISONPAIEMENT where etat = 11
