;
-- [367/1309] LOG_PERSONNEL_INFOCOMPLET3
CREATE OR REPLACE FORCE VIEW "LOG_PERSONNEL_INFOCOMPLET3" ("ID","PERMIS_CONDUIRE","CHEMIN_PERMIS","REMARQUE","ID_PERS","NOM","PRENOM","DATE_NAISSANCE","SEXE","NUMERO_CIN","DATE_CIN","DATE_DUPL_CIN","NATIONALITE","ADRESSE","FOKOTANY","ACTE_NAISSANCE","DIRECTION","SERVICE","IDINFO","DATESAISIE","MATRICULE","LIEU_NAISSANCE_COMMUNE","LIEU_DELIVRANCE_CIN","SITUATION_MATRIMONIAL","INITIALE","CTURGENCE_NOM_PRENOM","CTURGENCE_TELEPHONE1","CTURGENCE_TELEPHONE2","CTURGENCE_TELEPHONE3","IDCONJOINT","CODE_AGENCE_BANQUE","BANQUE_NUMERO_COMPTE","BANQUE_COMPTE_CLE","DATEEMBAUCHE","IDFONCTION","IDCATEGORIE","MODE_PAIEMENT","ETAT") AS
select log_personnel.ID,log_personnel.PERMIS_CONDUIRE,log_personnel.CHEMIN_PERMIS,log_personnel.REMARQUE,log_personnel.ID_PERS,log_personnel.NOM,log_personnel.PRENOM,log_personnel.DATE_NAISSANCE,log_personnel.SEXE,log_personnel.NUMERO_CIN,log_personnel.DATE_CIN,log_personnel.DATE_DUPL_CIN,log_personnel.NATIONALITE,log_personnel.ADRESSE,log_personnel.FOKOTANY,log_personnel.ACTE_NAISSANCE,log_personnel.DIRECTION,log_personnel.SERVICE,
       paie_info_personnel.id as idinfo,
       paie_info_personnel.datesaisie,
       paie_info_personnel.matricule,
       paie_info_personnel.lieu_naissance_commune,
       paie_info_personnel.lieu_delivrance_cin,
       paie_info_personnel.situation_matrimonial,
       paie_info_personnel.initiale,
       paie_info_personnel.cturgence_nom_prenom,
       paie_info_personnel.cturgence_telephone1,
       paie_info_personnel.cturgence_telephone2,
       paie_info_personnel.cturgence_telephone3,
       paie_info_personnel.idconjoint,
       paie_info_personnel.code_agence_banque,
       paie_info_personnel.banque_numero_compte,
       paie_info_personnel.banque_compte_cle,
       paie_info_personnel.dateembauche,
       fuc.val as idfonction,
       paie_info_personnel.idcategorie,
       paie_info_personnel.mode_paiement,
       paie_info_personnel.etat
from log_personnel join
     paie_info_personnel on (log_personnel.id = paie_info_personnel.id)
                   left join paie_fonction fuc on(paie_info_personnel.idfonction=fuc.id)
                   left join log_personnel_non_valide on log_personnel.id_pers = log_personnel_non_valide.idlogpers
WHERE log_personnel.id != '1002067'
;
-- [368/1309] LOG_PERSONNEL_INFOPOINTAGE
CREATE OR REPLACE FORCE VIEW "LOG_PERSONNEL_INFOPOINTAGE" ("ID","PERMIS_CONDUIRE","CHEMIN_PERMIS","REMARQUE","ID_PERS","NOM","PRENOM","DATE_NAISSANCE","SEXE","NUMERO_CIN","DATE_CIN","DATE_DUPL_CIN","NATIONALITE","ADRESSE","FOKOTANY","ACTE_NAISSANCE","DIRECTION","SERVICE","IDINFO","DATESAISIE","MATRICULE","LIEU_NAISSANCE_COMMUNE","LIEU_DELIVRANCE_CIN","SITUATION_MATRIMONIAL","INITIALE","CTURGENCE_NOM_PRENOM","CTURGENCE_TELEPHONE1","CTURGENCE_TELEPHONE2","CTURGENCE_TELEPHONE3","IDCONJOINT","CODE_AGENCE_BANQUE","BANQUE_NUMERO_COMPTE","BANQUE_COMPTE_CLE","DATEEMBAUCHE","DATE_DEPART","IDFONCTION","FONCTION","IDCATEGORIE","MODE_PAIEMENT","ETAT","TEMPORAIRE","IDGROUPEFONCTION","SERVICE_LIBELLE") AS
select log_personnel.ID,log_personnel.PERMIS_CONDUIRE,log_personnel.CHEMIN_PERMIS,log_personnel.REMARQUE,log_personnel.ID_PERS,log_personnel.NOM,log_personnel.PRENOM,log_personnel.DATE_NAISSANCE,log_personnel.SEXE,log_personnel.NUMERO_CIN,log_personnel.DATE_CIN,log_personnel.DATE_DUPL_CIN,log_personnel.NATIONALITE,log_personnel.ADRESSE,log_personnel.FOKOTANY,log_personnel.ACTE_NAISSANCE,log_personnel.DIRECTION,log_personnel.SERVICE,
       paie_info_personnel.id as idinfo,
       paie_info_personnel.datesaisie,
       paie_info_personnel.matricule,
       paie_info_personnel.lieu_naissance_commune,
       paie_info_personnel.lieu_delivrance_cin,
       paie_info_personnel.situation_matrimonial,
       paie_info_personnel.initiale,
       paie_info_personnel.cturgence_nom_prenom,
       paie_info_personnel.cturgence_telephone1,
       paie_info_personnel.cturgence_telephone2,
       paie_info_personnel.cturgence_telephone3,
       paie_info_personnel.idconjoint,
       paie_info_personnel.code_agence_banque,
       paie_info_personnel.banque_numero_compte,
       paie_info_personnel.banque_compte_cle,
       paie_info_personnel.dateembauche,
       paie_info_personnel.date_depart,
       fuc.val as idfonction,
       paie_info_personnel.idfonction as fonction,
       paie_info_personnel.idcategorie,
       paie_info_personnel.mode_paiement,
       paie_info_personnel.etat, paie_info_personnel.temporaire,
       fuc.IDGROUPEFONCTION,
       ls.CODE_SERVICE||' '|| ls.LIBELLE as service_libelle
from log_personnel LEFT join paie_info_personnel on (log_personnel.id = paie_info_personnel.id)
                   LEFT join log_service ls on ls.id=log_personnel.SERVICE
                   join paie_fonction fuc on(paie_info_personnel.idfonction=fuc.id) where log_personnel.id != '1002067'
;
-- [369/1309] LOG_PERS_NON_VALIDE_LIB
CREATE OR REPLACE FORCE VIEW "LOG_PERS_NON_VALIDE_LIB" ("ID","IDLOGPERS","SEXE","DATEAPPLICATION","IDTYPEDEBAUCHE","ETAT","IDUSER","MATRICULE","DATE_DECISION","REFDECISION","ETATLIB") AS
SELECT
	    lpnv.id,
	    lp.nom || ' ' || lp.prenom AS idlogpers,
	    lp.sexe,
	    lpnv.dateapplication,
	    td.val AS idtypedebauche,
	    lpnv.etat,
	    lpnv.iduser,
	    pif.matricule,
	    lpnv.date_decision,
	    lpnv.refdecision,
	    CASE
	        WHEN lpnv.etat = 1 THEN
	            'Cree'
	        WHEN lpnv.etat = 11 THEN
	            'Valide'
	        WHEN lpnv.etat = 0 THEN
	            'Annule'
	        ELSE
	            'Inconnu'
	        END AS etatLib
	FROM log_personnel_non_valide lpnv
	         LEFT JOIN type_depart td
	                   ON td.id = lpnv.idtypedebauche
	         LEFT JOIN paie_info_personnel pif
	                   ON pif.id = lpnv.idlogpers
	         LEFT JOIN log_personnel lp
	                   ON lp.id = lpnv.idlogpers
	WHERE lpnv.date_reintegration IS NULL
;
-- [370/1309] LOG_PERS_NON_VALIDE_LIB_3
CREATE OR REPLACE FORCE VIEW "LOG_PERS_NON_VALIDE_LIB_3" ("ID","IDLOGPERS","DATEAPPLICATION","DATE_DECISION","IDTYPEDEBAUCHE","TYPEDEBAUCHE","REFDECISION","IDAVANCEMENT","MOTIF","SEXE","ETAT","PERSONNELID","MATRICULE") AS
SELECT lpnv.id,
       lp.id AS idlogpers,
       lpnv.dateapplication,
       lpnv.date_decision,
       lpnv.idtypedebauche,
       ddt.val AS typedebauche,
       lpnv.refdecision,
       lpnv.idavancement,
       lpnv.motif,
       lp.sexe,
       lpnv.etat,
       lpnv.idlogpers AS personnelid,
       pif.matricule
FROM log_personnel_non_valide lpnv
         JOIN paie_info_personnel pif ON pif.id = lpnv.idlogpers
         JOIN log_personnel lp ON lpnv.idlogpers = lp.id
         JOIN dec_decision_type ddt ON ddt.id = lpnv.idtypedebauche
WHERE lpnv.date_reintegration IS NULL
;
-- [371/1309] LOG_PERS_NON_VALIDE_LIB_4
CREATE OR REPLACE FORCE VIEW "LOG_PERS_NON_VALIDE_LIB_4" ("ID","IDLOGPERS","DATEAPPLICATION","DATE_DECISION","IDTYPEDEBAUCHE","TYPEDEBAUCHE","REFDECISION","IDAVANCEMENT","MOTIF","SEXE","ETAT","PERSONNELID","MATRICULE") AS
SELECT lpnv.id,
       lp.id AS idlogpers,
       lpnv.dateapplication,
       lpnv.date_decision,
       lpnv.idtypedebauche,
       ddt.val AS typedebauche,
       lpnv.refdecision,
       lpnv.idavancement,
       lpnv.motif,
       lp.sexe,
       lpnv.etat,
       (lp.nom || ' ') || lp.prenom AS personnelid,
       pif.matricule
FROM log_personnel_non_valide lpnv
         JOIN paie_info_personnel pif ON pif.id = lpnv.idlogpers
         JOIN log_personnel lp ON lpnv.idlogpers = lp.id
         JOIN type_depart ddt ON ddt.id = lpnv.idtypedebauche
WHERE lpnv.date_reintegration IS NULL
;
-- [372/1309] LOG_PERS_NON_VALIDE_LIB_5
CREATE OR REPLACE FORCE VIEW "LOG_PERS_NON_VALIDE_LIB_5" ("ID","IDLOGPERS","DATEAPPLICATION","DATE_DECISION","IDTYPEDEBAUCHE","TYPEDEBAUCHE","REFDECISION","IDAVANCEMENT","MOTIF","SEXE","ETAT","PERSONNELID","PASSATIONIB","MATRICULE","IDPASSATION") AS
SELECT lpnv.id,
       lp.id AS idlogpers,
       lpnv.dateapplication,
       lpnv.date_decision,
       lpnv.idtypedebauche,
       ddt.val AS typedebauche,
       lpnv.refdecision,
       lpnv.idavancement,
       lpnv.motif,
       lp.sexe,
       lpnv.etat,
       (lp.nom || ' ') || lp.prenom AS personnelid,
       (lp2.nom || ' ') || lp2.prenom AS passationib,
       pif.matricule,
       lpnv.idpassation
FROM log_personnel_non_valide lpnv
         JOIN paie_info_personnel pif ON pif.id = lpnv.idlogpers
         JOIN log_personnel lp ON lpnv.idlogpers = lp.id
         LEFT JOIN log_personnel lp2 ON lpnv.idpassation = lp2.id
         JOIN type_depart ddt ON ddt.id = lpnv.idtypedebauche
WHERE lpnv.date_reintegration IS NULL
;
-- [373/1309] LOG_PERS_NON_VALIDE_LIB_5_TEST
CREATE OR REPLACE FORCE VIEW "LOG_PERS_NON_VALIDE_LIB_5_TEST" ("ID","IDLOGPERS","DATEAPPLICATION","DATE_DECISION","IDTYPEDEBAUCHE","TYPEDEBAUCHE","REFDECISION","IDAVANCEMENT","MOTIF","SEXE","ETAT","PERSONNELID","PASSATIONIB","MATRICULE","IDPASSATION") AS
(
SELECT lpnv.id,
    lp.id AS idlogpers,
    lpnv.dateapplication,
    lpnv.date_decision,
    lpnv.idtypedebauche,
    ddt.val AS typedebauche,
    lpnv.refdecision,
    lpnv.idavancement,
    lpnv.motif,
    lp.sexe,
    lpnv.etat,
    (lp.nom || ' ') || lp.prenom AS personnelid,
    (lp2.nom || ' ') || lp2.prenom AS passationib,
    pif.matricule,
    lpnv.idpassation
   FROM log_personnel_non_valide lpnv
     LEFT JOIN paie_info_personnel pif ON pif.id = lpnv.idlogpers
     LEFT JOIN log_personnel lp ON lpnv.idlogpers = lp.id
     LEFT JOIN log_personnel lp2 ON lpnv.idpassation = lp2.id
     LEFT JOIN type_depart ddt ON ddt.id = lpnv.idtypedebauche
)
;
