-- [380/1309] LOG_SERVICE_LIB
CREATE OR REPLACE FORCE VIEW "LOG_SERVICE_LIB" ("ID","CODE_DR","DR_RATTACHE","LIBELLE","CODE_SERVICE","LIBELLEDIRECTION") AS
SELECT
    ls.ID ,
    ls.CODE_DR ,
    ls.DR_RATTACHE ,
    ls.LIBELLE ,
    ls.CODE_SERVICE ,
    ld.val AS libelleDirection

FROM LOG_SERVICE ls
         LEFT JOIN LOG_DIRECTION ld ON ld.id = ls.DR_RATTACHE
