-- [381/1309] LOG_SERVICE_LIBELLE
CREATE OR REPLACE FORCE VIEW "LOG_SERVICE_LIBELLE" ("ID","LIBELLE","CODE_DR","DR_RATTACHE","CODE_SERVICE") AS
SELECT ls.id,
       ls.libelle,
       sd.val AS code_dr,
       ls.dr_rattache,
       ls.code_service
FROM log_service ls
         LEFT JOIN sig_dr sd ON ls.code_dr = sd.id AND ls.id <> 'SERV00001'
;
-- [382/1309] MAGASIN
CREATE OR REPLACE FORCE VIEW "MAGASIN" ("ID","VAL","DESCE","IDPOINT","IDPRODUIT","IDTYPEMAGASIN","ETAT") AS
select p.ID,
    p.VAL,
    p.DESCE,
    p.id as idPoint,
    '-' as idProduit,
    '' as idtypemagasin,
    11 as etat
    from point p
;
-- [383/1309] AS_BONDELIVRAISONCLIENT_LIBCPL
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISONCLIENT_LIBCPL" ("ID","REMARQUE","IDVENTE","IDBC","DATY","ETAT","MAGASIN","IDORIGINE","IDCLIENT","IDMAGASINLIB","IDCLIENTLIB","ETATLIB","MOTSCLESSS") AS
SELECT AB.ID,
       AB.REMARQUE,
       AB.IDVENTE,
       AB.IDBC,
       AB.DATY,
       AB.ETAT,
       AB.MAGASIN,
       AB.IDORIGINE,
       AB.IDCLIENT,
       M.VAL   AS IDMAGASINLIB,
       C.NOM   AS IDCLIENTLIB,
       CASE
           WHEN AB.ETAT = 0 THEN '<span style=color: green;>ANNUL&Eacute;</span>'
           WHEN AB.ETAT = 1 THEN '<span style=color: green;>CR&Eacute;&Eacute;</span>'
           WHEN AB.ETAT = 11 THEN '<span style=color: green;>VALID&Eacute;</span>'
           END AS ETATLIB,
       (
           AB.ID || ' | ' || C.NOM || ' | ' || M.VAL || ' | ' || AB.REMARQUE
           )   AS MOTSCLESSS
FROM AS_BONDELIVRAISON_CLIENT AB
         LEFT JOIN MAGASIN2 M ON AB.MAGASIN = M.ID
         LEFT JOIN CLIENT C ON C.ID = AB.IDCLIENT
;
-- [384/1309] AS_BONDELIVRAISONC_LIBCPL_A
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISONC_LIBCPL_A" ("ID","REMARQUE","IDVENTE","IDBC","DATY","ETAT","MAGASIN","IDORIGINE","IDCLIENT","IDMAGASINLIB","IDCLIENTLIB","ETATLIB") AS
SELECT "ID","REMARQUE","IDVENTE","IDBC","DATY","ETAT","MAGASIN","IDORIGINE","IDCLIENT","IDMAGASINLIB","IDCLIENTLIB","ETATLIB" FROM AS_BONDELIVRAISONCLIENT_LIBCPL WHERE etat=0
;
-- [385/1309] AS_BONDELIVRAISONC_LIBCPL_C
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISONC_LIBCPL_C" ("ID","REMARQUE","IDVENTE","IDBC","DATY","ETAT","MAGASIN","IDORIGINE","IDCLIENT","IDMAGASINLIB","IDCLIENTLIB","ETATLIB","MOTSCLESSS") AS
SELECT v."ID",v."REMARQUE",v."IDVENTE",v."IDBC",v."DATY",v."ETAT",v."MAGASIN",v."IDORIGINE",v."IDCLIENT",v."IDMAGASINLIB",v."IDCLIENTLIB",v."ETATLIB",v."MOTSCLESSS"
FROM AS_BONDELIVRAISONCLIENT_LIBCPL v
WHERE ETAT = 1
;
-- [386/1309] AS_BONDELIVRAISONC_LIBCPL_V
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISONC_LIBCPL_V" ("ID","REMARQUE","IDVENTE","IDBC","DATY","ETAT","MAGASIN","IDORIGINE","IDCLIENT","IDMAGASINLIB","IDCLIENTLIB","ETATLIB","MOTSCLESSS") AS
SELECT v."ID",v."REMARQUE",v."IDVENTE",v."IDBC",v."DATY",v."ETAT",v."MAGASIN",v."IDORIGINE",v."IDCLIENT",v."IDMAGASINLIB",v."IDCLIENTLIB",v."ETATLIB",v."MOTSCLESSS"
FROM AS_BONDELIVRAISONCLIENT_LIBCPL v
WHERE ETAT = 11
;
-- [387/1309] AS_BONDELIVRAISON_CLIENT_MF
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISON_CLIENT_MF" ("IDMERE","REMARQUE","IDVENTE","IDBC","DATY","ETAT","MAGASIN","IDFILLE","PRODUIT","NUMBL","QUANTITE","IDVENTEDETAIL","UNITE","IDBC_FILLE") AS
SELECT 
m.id AS idmere, m.remarque, m.idvente, m.idbc, m.daty, m.etat, m.magasin,
f.id AS idfille, f.produit, f.numbl, f.quantite, f.idventedetail, f.unite, f.idbc_fille 
FROM AS_BONDELIVRAISON_CLIENT m,AS_BONDELIVRAISON_CLIENT_FILLE f WHERE m.id=f.numbl
;
-- [388/1309] ETATSTOCKLIB
CREATE OR REPLACE FORCE VIEW "ETATSTOCKLIB" ("ID","IDPRODUIT","IDPRODUITLIB","IDMAGASIN","IDMAGASINLIB","IDPOINT","IDPOINTLIB","IDTYPEPRODUIT","IDTYPEPRODUITLIB","IDUNITE","IDUNITELIB","REPORT","ENTREE","SORTIE","RESTE","DATY") AS
SELECT 
e.ID ,
e.IDPRODUIT ,
p.VAL AS IDPRODUITLIB,
e.IDMAGASIN ,
m.VAL AS IDMAGASINLIB,
e.IDPOINT ,
p2.VAL AS IDPOINTLIB,
e.IDTYPEPRODUIT ,
tp.VAL AS IDTYPEPRODUITLIB,
e.IDUNITE ,
u.VAL AS IDUNITELIB,
e.REPORT ,
e.ENTREE ,
e.SORTIE ,
e.RESTE ,
e.DATY 
FROM ETATSTOCK e 
LEFT JOIN PRODUIT p ON p.ID = e.IDPRODUIT 
LEFT JOIN MAGASIN m ON m.ID = e.IDMAGASIN 
LEFT JOIN POINT p2 ON p2.ID = e.IDPOINT 
LEFT JOIN TYPE_PRODUIT tp ON tp.ID = e.IDTYPEPRODUIT 
LEFT JOIN UNITE u ON u.ID = e.IDUNITE
;
-- [389/1309] FACTUREFOURNISSEURCPL
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURCPL" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","IDDEVISE","MONTANTTVA","MONTANTHT","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTPAYEAR","MONTANTRESTEAR","MONTANTRESTE","MONTANTAVOIR","TAUXDECHANGE","IDPREVISION","ESTPREVULIB","IDOBJET","IDREF","IDTYPEFACTURE","TYPEFACTURE","NUMERO","TYPEACHAT","IDFACTUREPRINCIPALE","IDSERVICELIB","SERVICE","TYPEFACTUREFOURNISSEUR","TYPEFACTUREFOURNISSEURLIB","IDECRITURE","TYPEACHATLIB","REMISE") AS
SELECT
    f.ID,
    f.IDFOURNISSEUR,
    f2.NOM  AS IDFOURNISSEURLIB,
    f.IDMODEPAIEMENT,
    m.VAL   AS IDMODEPAIEMENTLIB,
    f.DATY,
    f.DESIGNATION,
    f.DATEECHEANCEPAIEMENT,
    f.ETAT,
    CASE
        WHEN f.ETAT = 1
            THEN 'CR&Eacute;&Eacute;E'
        WHEN f.ETAT = 0
            THEN 'ANNUL&Eacute;E'
        WHEN f.ETAT = 11
            THEN 'VIS&Eacute;E'
        END AS ETATLIB,
    nvl(f.REFERENCE, reff.reference) as reference,
    f.IDBC,
    f.IDMAGASIN,
    f.DEVISE,
    case
        when f.TAUX=0 then 1
        else f.TAUX
        end as taux,
    p.VAL   AS idMagasinLib,
    f.IDDEVISE,
    cast(f.MONTANTTVA as number(30,5)) as MONTANTTVA,
    CAST(f.MONTANTHT as number(30,5)) AS MONTANTHT,
    cast(f.MONTANTTTC as number(30,5)) as montantttc,
    cast(f.MONTANTTTCAR as number(30,5)) as MONTANTTTCAR,
    cast(nvl(mv.MONTANT,0) AS number(30,5)) AS montantpaye,
    cast(nvl(mv.MONTANT,0)*nvl(f.TAUX,1) AS number(30,5)) AS montantpayeAr,
    cast(f.MONTANTTTCAR-((nvl(mv.MONTANT,0)-nvl(av.montantTTC,0))*nvl(f.TAUX,1)) AS number(30,5)) AS montantresteAr,
    cast(f.MONTANTTTC-nvl(mv.MONTANT,0)-nvl(av.montantTTC,0) AS number(30,5)) AS montantreste,
    cast(av.montantTTC as number(30,2)) as montantAvoir,
    cast(f.TAUX AS  number(30,2)) AS tauxdechange,
    prev.id as idPrevision,
    CASE
        WHEN f.estprevu=0 THEN 'NON'
        ELSE 'OUI'
        END
        AS estprevulib,
    f.IDOBJET,
    f.IDREF,
    f.IDTYPEFACTURE,
    tf.VAL as typefacture,
    f.numero,
    f.typeachat,
    f.idfactureprincipale,
    s.libelle AS idServiceLib,
    f.SERVICE,
    f.TYPEFACTUREFOURNISSEUR,
    tff.DESCE AS TYPEFACTUREFOURNISSEURLIB,
    ce.id AS idecriture,
    ta.VAL AS typeachatlib,
    f.REMISE
FROM FactFournisseurCalc f
    LEFT JOIN TYPEACHAT ta ON ta.DESCE = f.TYPEACHAT
    LEFT JOIN FOURNISSEUR f2 ON f2.ID = f.IDFOURNISSEUR
    LEFT JOIN MODEPAIEMENT m ON m.ID = f.IDMODEPAIEMENT
    LEFT JOIN MAGASIN p ON p.ID = f.IDMAGASIN
    LEFT JOIN LIAISONPAIEMENTTOTAL mv ON f.id=mv.ID2
    left join AvoirAChatCalcGroupeOrigine av on av.IDFACTURE=f.ID
    LEFT JOIN prevision prev ON prev.idfacture=f.id
    left join type_facture tf on tf.id = f.IDTYPEFACTURE
    LEFT JOIN SERVICE s ON f.SERVICE = s.COMPTE
    LEFT JOIN referencefacture reff ON f.id=reff.idfacture
    LEFT JOIN typefacturefournisseur tff ON tff.id = f.TYPEFACTUREFOURNISSEUR
    LEFT JOIN COMPTA_ECRITURE ce ON ce.idobjet=f.id
;
-- [390/1309] FACTUREFOURNISSEURCPL_ANNULEE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURCPL_ANNULEE" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB") AS
