-- [392/1309] FACTUREFOURNISSEURCPL_EUR
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURCPL_EUR" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","IDDEVISE","MONTANTTVA","MONTANTHT","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","TAUXDECHANGE","IDTYPEFACTURE","IDFACTUREPRINCIPALE","IDSERVICELIB") AS
