-- [393/1309] FACTUREFOURNISSEURCPL_EUR_FAE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURCPL_EUR_FAE" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","IDDEVISE","MONTANTTVA","MONTANTHT","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","TAUXDECHANGE","IDTYPEFACTURE","IDFACTUREPRINCIPALE","IDSERVICELIB","TYPEFACTURE") AS
SELECT
