-- [394/1309] FACTUREFOURNISSEURCPL_FD
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURCPL_FD" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","IDDEVISE","MONTANTTVA","MONTANTHT","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","TAUXDECHANGE","IDPREVISION","IDBL") AS
SELECT
	f.ID,
	f.IDFOURNISSEUR,
	f.IDFOURNISSEURLIB,
	f.IDMODEPAIEMENT,
	f.IDMODEPAIEMENTLIB,
	f.DATY,
	f.DESIGNATION,
	f.DATEECHEANCEPAIEMENT,
	f.ETAT,
	f.ETATLIB,
	f.REFERENCE,
	f.IDBC,
	f.IDMAGASIN,
	f.DEVISE,
	f.TAUX,
	f.IDMAGASINLIB,
	f.IDDEVISE,
	f.MONTANTTVA,
	f.MONTANTHT,
	f.MONTANTTTC,
	f.MONTANTTTCAR,
	f.MONTANTPAYE,
	f.MONTANTRESTE,
	f.TAUXDECHANGE,
	f.IDPREVISION,
	bl.id AS idbl
FROM
	FACTUREFOURNISSEURCPL f
LEFT JOIN AS_BONDELIVRAISON bl ON
	f.id = bl.IDFACTUREFOURNISSEUR
LEFT JOIN liaisonfacturefournisseurs l ON
	(f.id = l.id1
		OR f.id = l.id2)
WHERE
	bl.id IS NULL
	AND l.id IS NULL
;
-- [395/1309] FACTUREFOURNISSEURCPL_LIER
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURCPL_LIER" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","IDDEVISE","MONTANTTVA","MONTANTHT","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","TAUXDECHANGE","IDPREVISION","ID1") AS
SELECT
