	f.DATEECHEANCEPAIEMENT,
	f.ETAT,
	f.ETATLIB,
	f.REFERENCE,
	f.IDBC,
	f.IDMAGASIN,
	f.DEVISE,
	f.TAUX,
	f.IDMAGASINLIB,
	f.IDDEVISE,
	f.MONTANTTVA,
	f.MONTANTHT,
	f.MONTANTTTC,
	f.MONTANTTTCAR,
	f.MONTANTPAYE,
