-- [399/1309] DEPENSEDFACTUREFOURNISSEUR
CREATE OR REPLACE FORCE VIEW "DEPENSEDFACTUREFOURNISSEUR" ("ID","IDBC","DESIGNATION","IDFOURNISSEURLIB","IDDEVISE","DATY","MONTANTTTC","MONTANTPAYE","MONTANTRESTE","DATEECHEANCEPAIEMENT","IDSERVICELIB","ETATLIB","IDFOURNISSEUR","IDMODEPAIEMENT","DEVISE","TAUX","IDMAGASIN","ETATFACTURE","IDBONDELIVRAISON","REMARQUEBONDELIVRAISON","MAGASIN","IDDEPENSEDIVERS","IDDEPENSEDIVERSREF","DATYDEPENSE","FOURNISSEURDEPENSE","REMARQUEDEPENSE","IDMODEPAIEMENTDEPENSE","COMPTECHEQUE","ACHETEUR","IDMAGASINDEPENSE","IDCATEGORIE","ETATDEPENSE") AS
SELECT
    ff.ID                     AS ID,
    ff.IDBC,
    ff.DESIGNATION,
    ff.IDFOURNISSEURLIB,
    ff.IDDEVISE               AS IDDEVISE,
    ff.DATY,
    ff.MONTANTTTC,
    ff.MONTANTPAYE,
    ff.MONTANTRESTE,
    ff.DATEECHEANCEPAIEMENT,
    ff.IDSERVICELIB,
    ff.ETATLIB,

    ff.IDFOURNISSEUR,
    ff.IDMODEPAIEMENT,
    ff.DEVISE,
    ff.TAUX,
    ff.IDMAGASIN,
    ff.ETAT                   AS ETATFACTURE,

    bl.ID                     AS IDBONDELIVRAISON,
    bl.REMARQUE               AS REMARQUEBONDELIVRAISON,
    bl.MAGASIN,
    bl.IDDEPENSEDIVERS,

    dd.ID                     AS IDDEPENSEDIVERSREF,
    dd.DATY                   AS DATYDEPENSE,
    dd.FOURNISSEUR            AS FOURNISSEURDEPENSE,
    dd.REMARQUE               AS REMARQUEDEPENSE,
    dd.IDMODEPAIEMENT         AS IDMODEPAIEMENTDEPENSE,
    dd.COMPTECHEQUE,
    dd.ACHETEUR,
    dd.IDMAGASIN              AS IDMAGASINDEPENSE,
    dd.IDCATEGORIE,
    dd.ETAT                   AS ETATDEPENSE

FROM AS_BONDELIVRAISON bl
INNER JOIN FACTUREFOURNISSEURCPL_TOUS ff
    ON ff.ID = bl.IDFACTUREFOURNISSEUR
LEFT JOIN DEPENSEDIVERS dd
    ON dd.ID = bl.IDDEPENSEDIVERS
;
