FROM FACTUREFOURNISSEURCPL f
WHERE f.ETAT = 11
;
-- [404/1309] FACTUREFOURNISSEUR_RECAP_JOUR
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_RECAP_JOUR" ("DATY","MONTANTTTC","MONTANTPAYE","MONTANTRESTE","NOMBRE","MONTANTRESTEACEJOUR") AS
WITH BORNES AS (
    SELECT
        DATE '2026-06-01' AS DATE_MIN,
        TRUNC(SYSDATE) AS DATE_MAX
    FROM DUAL
),
CALENDRIER AS (
    SELECT
        DATE_MIN + LEVEL - 1 AS DATY
    FROM BORNES
    CONNECT BY LEVEL <= DATE_MAX - DATE_MIN + 1
),
FACTURE_JOUR AS (
    SELECT
        TRUNC(DATY) AS DATY,
        SUM(NVL(MONTANTTTC, 0)) AS MONTANTTTC,
        SUM(NVL(MONTANTPAYE, 0)) AS MONTANTPAYE,
        SUM(NVL(MONTANTRESTE, 0)) AS MONTANTRESTE,
        COUNT(*) AS NOMBRE
    FROM FACTUREFOURNISSEURCPL_TOUS_FAE
    WHERE IDTYPEFACTURE = 'TPF0002'
      AND ETAT = 11
      AND DATY >= DATE '2026-06-01'
    GROUP BY TRUNC(DATY)
)
SELECT
    c.DATY,

    CAST(NVL(f.MONTANTTTC, 0) AS NUMBER(30,5)) AS MONTANTTTC,
    CAST(NVL(f.MONTANTPAYE, 0) AS NUMBER(30,5)) AS MONTANTPAYE,
    CAST(NVL(f.MONTANTRESTE, 0) AS NUMBER(30,5)) AS MONTANTRESTE,
    CAST(NVL(f.NOMBRE, 0) AS NUMBER(10,0)) AS NOMBRE,

    CAST(
        SUM(NVL(f.MONTANTRESTE, 0))
        OVER (
            ORDER BY c.DATY
            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
        )
        AS NUMBER(30,5)
    ) AS MONTANTRESTEACEJOUR

FROM CALENDRIER c
LEFT JOIN FACTURE_JOUR f
    ON c.DATY = f.DATY
;
-- [405/1309] FACTURESTANDARD
CREATE OR REPLACE FORCE VIEW "FACTURESTANDARD" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","IDMAGASINLIB","DEVISE","IDDEVISE","ETAT","TAUX","MONTANTTVA","MONTANTHT","TAUXDECHANGE","MONTANTTTC","MONTANTPAYE","MONTANTRESTE","IDOBJET","IDREF","TYPEACHAT","IDECRITURE","COMPTE","NUMERO") AS
SELECT
    fcpl.id,
    fcpl.idfournisseur,
    fcpl.idfournisseurlib,
    fcpl.idmodepaiement,
    fcpl.idmodepaiementlib,
    fcpl.daty,
    fcpl.designation,
    fcpl.dateecheancepaiement,
    fcpl.etatlib,
    fcpl.reference,
    fcpl.idbc,
    fcpl.idmagasin,
    fcpl.idmagasinlib,
    fcpl.devise,
    fcpl.iddevise,
    fcpl.etat,
    fcpl.taux,
    fcpl.montanttva,
    fcpl.montantht,
    fcpl.tauxdechange,
    fcpl.montantttc AS MONTANTTTC,
    nvl((fcpl.montantpaye * fcpl.TAUXDECHANGE), 0) AS MONTANTPAYE,
    nvl((fcpl.montantreste * fcpl.TAUXDECHANGE), 0) AS MONTANTRESTE,
    fcpl.IDOBJET,
    fcpl.IDREF,
    fcpl.typeachat,
    ce.id AS idecriture,
    '-' AS compte,
    fcpl.numero AS numero
FROM
    FACTUREFOURNISSEURCPL fcpl
        LEFT JOIN compta_ecriture ce ON
        ce.idobjet = fcpl.id
/*  LEFT JOIN compta_compte cc ON cc.idjournal=ce.journal */
WHERE
    fcpl.typeachat = 'PS'
;
-- [406/1309] FFFILLECPL_MONTANT
CREATE OR REPLACE FORCE VIEW "FFFILLECPL_MONTANT" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","IDPRODUITLIB","QTE","PU","REMISES","IDBCDETAIL","TVA","MONTANTTOTAL","MONTANTTTC","IDPOINT","IDPOINTLIB","IDMAGASIN","IDMAGASINLIB","IDCATEGORIE","IDCATEGORIELIB","DATY","IDDEVISE") AS
SELECT 
f.ID ,
f.IDFACTUREFOURNISSEUR ,
f.IDPRODUIT ,
nvl(i.LIBELLE,p.VAL) AS IDPRODUITLIB,
f.QTE ,
CAST(f.PU AS NUMBER(30,5)) AS PU ,
CAST(f.REMISES AS NUMBER(30,5)) AS REMISES ,
f.IDBCDETAIL,
CAST(f.TVA AS NUMBER(10,5)) AS TVA,
CAST(nvl(f.QTE*f.PU,0)  AS NUMBER(30,5))  AS MONTANTTOTAL,
CAST(
    nvl(
        ((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU)))
        + (((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU))) * NVL(f.TVA, 0) / 100)
    , 0) 
AS NUMBER(30,5)) AS MONTANTTTC,
p2.ID AS IDPOINT,
p2.VAL AS IDPOINTLIB,
m.ID AS IDMAGASIN,
m.VAL AS IDMAGASINLIB,
c.ID AS IDCATEGORIE,
c.VAL AS IDCATEGORIELIB,
f2.DATY AS daty,
f.IDDEVISE
FROM FACTUREFOURNISSEURFILLE f 
LEFT JOIN FACTUREFOURNISSEUR f2 ON f2.ID = f.IDFACTUREFOURNISSEUR 
LEFT JOIN MAGASIN m ON m.ID = f2.IDMAGASIN 
LEFT JOIN POINT p2 ON m.IDPOINT = p2.ID  
LEFT JOIN PRODUIT p ON p.ID = f.IDPRODUIT
LEFT JOIN CATEGORIE c ON p.IDCATEGORIE = c.ID
LEFT JOIN AS_INGREDIENTS i ON i.ID = f.IDPRODUIT
;
-- [407/1309] JAUGELIB
CREATE OR REPLACE FORCE VIEW "JAUGELIB" ("ID","IDMAGASIN","IDMAGASINLIB","QTE","DATY","ETAT","ETATLIB") AS
SELECT 
j.ID ,
j.IDMAGASIN ,
m.VAL AS IDMAGASINLIB,
j.QTE ,
j.DATY ,
j.ETAT ,
CASE 
	WHEN j.ETAT = 0 
	THEN 'ANNULEE'
	WHEN j.ETAT = 1 
	THEN 'CREE'
	WHEN j.ETAT = 11 
	THEN 'VALIDEE'
END AS ETATLIB
FROM JAUGE j 
JOIN MAGASIN m ON m.ID  = j.IDMAGASIN
;
-- [408/1309] JAUGE_LIB_ANNULEE
CREATE OR REPLACE FORCE VIEW "JAUGE_LIB_ANNULEE" ("ID","IDMAGASIN","IDMAGASINLIB","QTE","DATY","ETAT","ETATLIB") AS
SELECT 
j."ID",j."IDMAGASIN",j."IDMAGASINLIB",j."QTE",j."DATY",j."ETAT",j."ETATLIB"
FROM JAUGELIB j 
WHERE j.ETAT = 0
;
