-- [411/1309] MAGASIN2_ACTIF
CREATE OR REPLACE FORCE VIEW "MAGASIN2_ACTIF" ("ID","VAL","DESCE","IDPOINT","IDPRODUIT","IDTYPEMAGASIN","ETAT","CAPACITE","COMPTEUR","IDMAGASINMERE","IDLIGNE","ACTIF") AS
select "ID","VAL","DESCE","IDPOINT","IDPRODUIT","IDTYPEMAGASIN","ETAT","CAPACITE","COMPTEUR","IDMAGASINMERE","IDLIGNE","ACTIF" from magasin2 where ACTIF = 1
;
-- [412/1309] MAGASINLIB
CREATE OR REPLACE FORCE VIEW "MAGASINLIB" ("ID","VAL","DESCE","IDPOINT","IDPOINTLIB","IDTYPEMAGASIN","IDTYPEMAGASINLIB","IDPRODUIT","IDPRODUITLIB","IDLIGNE","IDLIGNELIB") AS
SELECT
    m.ID ,
    m.VAL ,
    m.DESCE ,
    m.IDPOINT ,
    p.VAL AS IDPOINTLIB,
    m.IDTYPEMAGASIN ,
    t.VAL AS IDTYPEMAGASINLIB,
    m.IDPRODUIT ,
    p2.LIBELLE AS IDPRODUITLIB,
    m.idLigne,
    lig.val as idLigneLib
FROM MAGASIN2 m
         LEFT JOIN POINT p ON p.ID = m.IDPOINT
         LEFT JOIN TYPEMAGASIN t ON t.ID = m.IDTYPEMAGASIN
         LEFT JOIN AS_INGREDIENTS p2 ON p2.ID = m.IDPRODUIT
        LEFT JOIN Ligne lig ON lig.id = m.idLigne
;
-- [413/1309] AS_BONDELIVRAISONCLIENT_LIB
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISONCLIENT_LIB" ("ID","REMARQUE","IDBC","DATY","ETAT","MAGASIN","MAGASINLIB","ETATLIB") AS
select bl.ID,
       bl.REMARQUE,
       bl.IDBC,
       bl.DATY,
       bl.ETAT,
       bl.MAGASIN,
       m.VAL as MAGASINlib,
       case
           when bl.etat = 1 then 'CREE(E)'
           when bl.etat = 11 then 'VISE(E)'
           end as etatlib
from AS_BONDELIVRAISON_CLIENT bl
    left join MAGASIN m on bl.MAGASIN = m.ID
;
-- [414/1309] AS_BONDELIVRAISONCLIENT_lib
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISONCLIENT_lib" ("ID","REMARQUE","IDBC","DATY","ETAT","MAGASIN","MAGASINLIB","ETATLIB") AS
select bl.ID,
       bl.REMARQUE,
       bl.IDBC,
       bl.DATY,
       bl.ETAT,
       bl.MAGASIN,
       m.VAL as MAGASINlib,
       case
           when bl.etat = 1 then 'CREE(E)'
           when bl.etat = 11 then 'VISE(E)'
           end as etatlib
from AS_BONDELIVRAISON_CLIENT bl
    left join MAGASIN m on bl.MAGASIN = m.ID
;
-- [415/1309] AS_BONDELIVRAISON_FILLE_VIDE
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISON_FILLE_VIDE" ("ID","PRODUIT","PRODUITLIB","QUANTITE","UNITE","NUMBL","IDDETAILSFACTUREFOURNISSEUR","IDBC_FILLE","REMARQUE","IDBC","DATY","ETAT","MAGASIN","UNITELIB","MAGASINLIB","PU","DESIGNATION","TAUXDECHANGE") AS
SELECT
	    cast(' ' as varchar(100)) AS ID,
	    cast(' ' as varchar(255)) AS PRODUIT,
	    cast(' ' as varchar(255)) AS PRODUITLIB ,
	    cast(-1 as NUMBER(10,2) ) AS QUANTITE ,
	    cast(' ' as varchar(100)) AS UNITE,
	    cast(' ' as varchar(100)) AS NUMBL,
	    cast(' ' as varchar(100)) AS IDDETAILSFACTUREFOURNISSEUR,
	    cast(' ' as varchar(100)) AS IDBC_FILLE ,
	    cast(' ' as varchar(200)) AS REMARQUE ,
	    cast(' ' as varchar(100)) AS IDBC ,
	    cast(NULL as DATE ) AS DATY ,
	    cast(-1 as int ) AS ETAT,
	    cast(' ' as varchar(500)) AS MAGASIN ,
	    cast(' ' as varchar(255)) AS UNITELIB ,
	    cast(' ' as varchar(255)) AS MAGASINLIB,
	    cast(-1 as NUMBER(10,2) ) AS pu ,
	    cast(' ' as varchar(255)) AS designation,
	    cast(-1 as NUMBER(10,2) ) AS tauxdechange
	FROM dual
;
-- [416/1309] AS_BONDELIVRAISON_LIB
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISON_LIB" ("ID","REMARQUE","IDBC","DATY","ETAT","MAGASIN","MAGASINLIB","ETATLIB","IDFOURNISSEUR","IDFOURNISSEURLIB","IDFACTUREFOURNISSEUR") AS
select bl.ID,
       bl.REMARQUE,
       bl.IDBC,
       bl.DATY,
       bl.ETAT,
       bl.MAGASIN,
       m.VAL as MAGASINlib,
       case
           when bl.etat = 1 then 'CR&Eacute;&Eacute;(E)'
           when bl.etat = 11 then 'VIS&Eacute;(E)'
           end as etatlib,
       bl.idfournisseur,
       f.nom AS idfournisseurlib,
       bl.IDFACTUREFOURNISSEUR
from AS_BONDELIVRAISON bl
         left join MAGASIN2 m on bl.MAGASIN = m.ID
         LEFT JOIN fournisseur f ON f.id=bl.idfournisseur
;
-- [417/1309] AS_BONDELIVRAISON_LIBCPL
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISON_LIBCPL" ("ID","PRODUIT","NUMBL","QUANTITE","IDDETAILSFACTUREFOURNISSEUR","UNITE","IDBC_FILLE","REMARQUE","IDBC","DATY","ETAT","MAGASIN","PRODUITLIB","UNITELIB","MAGASINLIB","LIBELLEEXTACTE","PU","DESIGNATION","MONTANT","PUAR","TAUXDECHANGE","IDFACTUREFOURNISSEUR") AS
SELECT
	    bl.ID,
	    bl.PRODUIT,
	    bl.NUMBL,
	    bl.QUANTITE,
	    bl.IDDETAILSFACTUREFOURNISSEUR,
	    bl.UNITE,
	    bl.IDBC_FILLE,
	    AB.REMARQUE,
	    AB.IDBC,
	    AB.DATY,
	    AB.ETAT,
	    AB.MAGASIN,
	    p.libelle AS PRODUITlib,
	    u.VAL AS UNITElib,
	    m.VAL AS magasinlib,
	    p.LIBELLEEXTACTE,
	    bl.pu,
	    bl.DESIGNATION,
	    cast(nvl(bl.QUANTITE*bl.PU,0) AS  NUMBER(30,2)) AS MONTANT,
	    cast(nvl(bl.tauxdechange*bl.PU,0) AS  NUMBER(30,2)) AS PUAR,
	    bl.tauxdechange,
        AB.IDFACTUREFOURNISSEUR -- nanampy colonne IDFACTUREFOURNISSEUR pour rapprochement BL - FF
	FROM
	    As_BonDeLivraison_Fille bl
	        LEFT JOIN AS_BONDELIVRAISON AB ON
	        AB.ID = bl.NUMBL
	        LEFT JOIN AS_INGREDIENTS p ON
	        bl.PRODUIT = p.ID
	        LEFT JOIN AS_UNITE  u ON
	        bl.UNITE = u.ID
	        LEFT JOIN MAGASIN m ON
	        ab.MAGASIN = m.ID
;
-- [418/1309] BLC_NONFACTURE
CREATE OR REPLACE FORCE VIEW "BLC_NONFACTURE" ("ID","REMARQUE","IDBC","DATY","ETAT","MAGASIN","MAGASINLIB","ETATLIB","IDVENTE","IDVENTELIB","IDCLIENT","IDCLIENTLIB") AS
SELECT
	ID,
	REMARQUE,
	IDBC,
	DATY,
	ETAT,
	MAGASIN,
	MAGASINLIB,
	ETATLIB,
	IDVENTE,
	IDVENTELIB,
	IDCLIENT ,
    IDCLIENTLIB
FROM
	AS_BONDELIVRAISONCLIENT_LIB
WHERE
	idVente IS NULL AND ETAT >=11
;
-- [419/1309] BL_NONFACTURE
CREATE OR REPLACE FORCE VIEW "BL_NONFACTURE" ("ID","REMARQUE","IDBC","DATY","ETAT","MAGASIN","MAGASINLIB","ETATLIB","IDFOURNISSEUR","IDFOURNISSEURLIB") AS
SELECT
	    abl.ID,abl.REMARQUE,abl.IDBC,abl.DATY,abl.ETAT,abl.MAGASIN,abl.MAGASINLIB,abl.ETATLIB,abl.IDFOURNISSEUR,abl.IDFOURNISSEURLIB
	FROM AS_BONDELIVRAISON_LIB abl
	WHERE abl.IDFACTUREFOURNISSEUR IS NULL
;
-- [420/1309] COMPTEURELECTRICITECPL
CREATE OR REPLACE FORCE VIEW "COMPTEURELECTRICITECPL" ("ID","DATY","IDLIGNE","VALEUR","ECART","IDCATEGORIE","IDMAGASIN","ETAT","ANCIEN","REMARQUE","HEURE","IDMACHINE","IDMERE","LIGNE","CATEGORIELIB","MAGASINLIB","MACHINELIB","LIGNELIB") AS
SELECT c2.ID,c2.DATY,c2.IDLIGNE,c2.VALEUR,c2.ECART,c2.IDCATEGORIE,c2.IDMAGASIN,c2.ETAT,c2.ANCIEN,c2.REMARQUE,c2.HEURE
  ,c2.IDMACHINE,c2.IDMERE, c.LIGNE   ,ai.libelle as CATEGORIELIB, m2.val AS MAGASINLIB,
  aim.libelle AS MACHINELIB,
  l.val AS LIGNELIB
  FROM COMPTEURELECTRICITEMERE c
	JOIN COMPTEURELECTRICITE c2 ON c.ID = c2.IDMERE
	LEFT JOIN as_ingredients ai ON ai.id = c2.IDCATEGORIE
	LEFT JOIN magasin2 m2 ON m2.id = c2.IDMAGASIN
	LEFT JOIN as_ingredient_machine aim ON aim.id = c2.IDMACHINE
	LEFT JOIN ligne l ON l.id = c2.IDLIGNE
;
-- [421/1309] COMPTEURCPLRECENTELECTRICITE
CREATE OR REPLACE FORCE VIEW "COMPTEURCPLRECENTELECTRICITE" ("ID","DATY","IDLIGNE","VALEUR","ECART","IDCATEGORIE","IDMAGASIN","ETAT","ANCIEN","REMARQUE","HEURE","IDMACHINE","IDMERE","LIGNE","CATEGORIELIB","MAGASINLIB","MACHINELIB","LIGNELIB","RN") AS
SELECT ID,DATY,IDLIGNE,VALEUR,ECART,IDCATEGORIE,IDMAGASIN,ETAT,ANCIEN,
       REMARQUE,HEURE,IDMACHINE,IDMERE,LIGNE,CATEGORIELIB,MAGASINLIB,
       MACHINELIB,LIGNELIB,RN
FROM (
    SELECT
        cm.ID,
        cm.DATY,
        cm.IDLIGNE,
        cm.VALEUR,
        cm.ECART,
        cm.IDCATEGORIE,
        cm.IDMAGASIN,
        cm.ETAT,
        cm.ANCIEN,
        cm.REMARQUE,
        cm.HEURE,
        cm.IDMACHINE,
        cm.IDMERE,
        cm.LIGNE,
        cm.CATEGORIELIB,
        cm.MAGASINLIB,
        cm.MACHINELIB,
        cm.LIGNELIB,
        ROW_NUMBER() OVER (
            PARTITION BY cm.IDLIGNE, cm.IDCATEGORIE, cm.IDMAGASIN
            ORDER BY cm.DATY DESC
        ) AS rn

    FROM COMPTEURELECTRICITECPL cm
)
WHERE rn = 1
;
-- [422/1309] DEPENSEBONDELIVRAISON
CREATE OR REPLACE FORCE VIEW "DEPENSEBONDELIVRAISON" ("ID","REMARQUE","IDBC","DATY","ETAT","IDFOURNISSEUR","MAGASIN","IDFACTUREFOURNISSEUR","IDDEPENSEDIVERS","DATYDEPENSE","FOURNISSEURDEPENSE","REMARQUEDEPENSE","IDMODEPAIEMENT","COMPTECHEQUE","ACHETEUR","IDMAGASIN","IDCATEGORIE","ETATDEPENSE","MAGASINLIB") AS
SELECT
    bl.ID,
    bl.REMARQUE,
    bl.IDBC,
    bl.DATY,
    bl.ETAT,
    bl.IDFOURNISSEUR,
    bl.MAGASIN,
    bl.IDFACTUREFOURNISSEUR,
    bl.IDDEPENSEDIVERS,

    dd.DATY          AS DATYDEPENSE,
    dd.FOURNISSEUR   AS FOURNISSEURDEPENSE,
    dd.REMARQUE      AS REMARQUEDEPENSE,
    dd.IDMODEPAIEMENT,
    dd.COMPTECHEQUE,
    dd.ACHETEUR,
    dd.IDMAGASIN,
    dd.IDCATEGORIE,
    dd.ETAT          AS ETATDEPENSE,
    m2.val AS magasinlib

FROM AS_BONDELIVRAISON bl
LEFT JOIN DEPENSEDIVERS dd ON dd.ID = bl.IDDEPENSEDIVERS
        LEFT join MAGASIN2 m2 ON m2.id = bl.MAGASIN
;
-- [423/1309] MAGASINLIBCOMPTA
CREATE OR REPLACE FORCE VIEW "MAGASINLIBCOMPTA" ("ID","VAL","DESCE","IDPOINT","IDPOINTLIB","IDTYPEMAGASIN","IDTYPEMAGASINLIB","IDPRODUIT","IDPRODUITLIB","COMPTE","IDMAGASINCOMPTE") AS
SELECT
	    m.ID ,
	    m.VAL ,
	    m.DESCE ,
	    m.IDPOINT ,
	    p.VAL AS IDPOINTLIB,
	    m.IDTYPEMAGASIN ,
	    t.VAL AS IDTYPEMAGASINLIB,
	    m.IDPRODUIT ,
	    p2.LIBELLE AS IDPRODUITLIB,
	    mc.DESCE as compte,
	    mc.id as idMagasincompte
	FROM MAGASIN2 m
	         LEFT JOIN POINT p ON p.ID = m.IDPOINT
	         LEFT JOIN TYPEMAGASIN t ON t.ID = m.IDTYPEMAGASIN
	         LEFT JOIN AS_INGREDIENTS p2 ON p2.ID = m.IDPRODUIT
	         LEFT JOIN magasin_compte mc ON mc.VAL = m.ID
;
-- [424/1309] MAGASINLIB_ILOT
CREATE OR REPLACE FORCE VIEW "MAGASINLIB_ILOT" ("ID","VAL","DESCE","IDPOINT","IDPOINTLIB","IDTYPEMAGASIN","IDTYPEMAGASINLIB","IDPRODUIT","IDPRODUITLIB") AS
SELECT 
m."ID",m."VAL",m."DESCE",m."IDPOINT",m."IDPOINTLIB",m."IDTYPEMAGASIN",m."IDTYPEMAGASINLIB",m."IDPRODUIT",m."IDPRODUITLIB"
FROM MAGASINLIB m 
WHERE m.IDTYPEMAGASIN = 'TYPMG000023'
;
-- [425/1309] MAGASINPOINT
CREATE OR REPLACE FORCE VIEW "MAGASINPOINT" ("ID","VAL","DESCE","IDPRODUIT","IDTYPEMAGASIN","IDPOINT","ETAT") AS
SELECT
    m.ID AS ID,
    m.VAL,
    m.DESCE,
    m.IDPRODUIT,
    m.IDTYPEMAGASIN,
    m.IDPOINT,
    m.ETAT
FROM MAGASIN2 m where m.ACTIF=1 UNION ALL SELECT
    p.ID AS ID,
    p.VAL,
    p.DESCE,
    NULL AS IDPRODUIT,
    NULL AS IDTYPEMAGASIN,
    p.ID AS IDPOINT,
    11 AS ETAT
FROM POINT p
WHERE p.ACTIF=1 and p.ID NOT IN (
    SELECT m.IDPOINT FROM MAGASIN2 m WHERE m.IDPOINT IS NOT NULL
)
;
-- [426/1309] AS_BONDELIVRAISON_CLIENT_CPL
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISON_CLIENT_CPL" ("ID","REMARQUE","IDVENTE","DESIGNATION","IDBC","DATY","ETAT","IDMAGASIN","MAGASIN","IDRESERVATION","IDCLIENTLIB","VEHICULE","CHAUFFEUR","DESCRIPTION","IDCLIENT") AS
SELECT bl.id, bl.remarque,
v.id AS idvente,
v.designation,
bl.idbc, bl.daty, bl.etat,
m.id AS idmagasin,
m.val AS magasin,
v.IDRESERVATION,
c.nom AS IDCLIENTlib,
bl.vehicule,
bl.chauffeur,
bl.description,
c.id AS idClient
FROM AS_BONDELIVRAISON_CLIENT bl
LEFT JOIN MAGASINPOINT m ON bl.magasin=m.id
LEFT JOIN vente v ON v.id=bl.idvente
LEFT JOIN client c ON c.ID = bl.IDCLIENT
;
-- [427/1309] AS_BONDELIVRAISON_CLIENT_CPL2
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISON_CLIENT_CPL2" ("ID","REMARQUE","IDVENTE","DESIGNATION","IDBC","DATY","ETAT","IDMAGASIN","MAGASIN","IDRESERVATION","IDCLIENTLIB","VEHICULE","CHAUFFEUR","DESCRIPTION","IDCLIENT") AS
SELECT bl.id, bl.remarque,
       v.id AS idvente,
       v.designation,
       bl.idbc, bl.daty, bl.etat,
       m.id AS idmagasin,
       m.val AS magasin,
       v.IDRESERVATION,
       c.nom AS IDCLIENTlib,
       bl.vehicule,
       bl.chauffeur,
       bl.description,
       c.id AS idClient
FROM AS_BONDELIVRAISON_CLIENT bl
         LEFT JOIN MAGASINPOINT m ON bl.magasin=m.id
         LEFT JOIN vente v ON v.idOrigine=bl.IDBC
         LEFT JOIN client c ON c.ID = bl.IDCLIENT
;
-- [428/1309] AS_INGREDIENTS_MAGASIN
CREATE OR REPLACE FORCE VIEW "AS_INGREDIENTS_MAGASIN" ("ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT","LIBELLEEXTACTE","TVA","FILEPATH","RESTE","TYPESTOCK","IDMAGASIN") AS
SELECT ai.ID,ai.LIBELLE,ai.SEUIL,ai.UNITE,ai.QUANTITEPARPACK,ai.PU,ai.ACTIF,ai.PHOTO,ai.CALORIE,ai.DURRE,ai.COMPOSE,ai.CATEGORIEINGREDIENT,ai.IDFOURNISSEUR,ai.DATY,ai.QTELIMITE,ai.PV,ai.LIBELLEVENTE,ai.SEUILMIN,ai.SEUILMAX,ai.PUACHATUSD,ai.PUACHATEURO,ai.PUACHATAUTREDEVISE,ai.PUVENTEUSD,ai.PUVENTEEURO,ai.PUVENTEAUTREDEVISE,ai.ISVENTE,ai.ISACHAT,ai.COMPTE_VENTE,ai.COMPTE_ACHAT,ai.LIBELLEEXTACTE,ai.TVA,ai.FILEPATH,ai.RESTE,ai.TYPESTOCK,
	m.ID  AS IDMAGASIN FROM AS_INGREDIENTS ai ,MAGASINPOINT m
;
-- [429/1309] DEMANDETRANSFERTCPL
CREATE OR REPLACE FORCE VIEW "DEMANDETRANSFERTCPL" ("ID","DESIGNATION","IDMAGASINDEPART","IDMAGASINDEPARTLIB","IDMAGASINARRIVE","IDMAGASINARRIVELIB","DATY","ETAT","IDOF","CATEGORIEINGREDIENT","CATEGORIEINGREDIENTLIB","MONTANTQUANTITE","ETATLIB") AS
SELECT
    t.ID ,
    t.DESIGNATION ,
    t.IDMAGASINDEPART ,
    m.VAL AS IDMAGASINDEPARTLIB,
    t.IDMAGASINARRIVE ,
    m2.VAL AS IDMAGASINARRIVELIB,
    t.DATY ,
    t.ETAT ,
    t.idof,
    t.CATEGORIEINGREDIENT,
    c.VAL  AS CATEGORIEINGREDIENTLIB,
    CAST(dfg.montantQuantite AS NUMBER(30,2)) AS montantQuantite,
    CASE
        WHEN t.ETAT = 0
            THEN 'Annul&eacute;'
        WHEN t.ETAT = 1
            THEN 'Cr&eacute;&eacute;'
        WHEN t.ETAT = 11
            THEN 'Vis&eacute;'
        END AS ETATLIB
FROM demandetransfert t
         LEFT JOIN MAGASINPOINT m ON m.ID = t.IDMAGASINDEPART
         LEFT JOIN MAGASINPOINT m2 ON m2.ID = t.IDMAGASINARRIVE
         LEFT JOIN CATEGORIEINGREDIENT c ON c.ID = t.CATEGORIEINGREDIENT
         LEFT JOIN DEMTRANSFILLEGROUPEMERE dfg ON dfg.IDDEMANDETRANSFERT = t.id
;
-- [430/1309] FABRICATIONCPL
CREATE OR REPLACE FORCE VIEW "FABRICATIONCPL" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","IDOFFILLE","IDOF","LANCEPARLIB","CIBLELIB","ETAT","LANCEUR","LANCEURLIB","ETATLIB","FABRICATIONPREC","FABRICATIONSUIV","MOTSCLESSS") AS
SELECT F.ID,
       F.LANCEPAR,
       F.CIBLE,
       F.REMARQUE,
       F.LIBELLE,
       F.BESOIN,
       F.DATY,
       F.IDOFFILLE,
       NVL(F.IDOF, OFF.IDMERE) AS IDOF,
       P.VAL                   AS LANCEPARLIB,
       P2.VAL                  AS CIBLELIB,
       F.ETAT                  AS ETAT,
       F.LANCEUR,
       LP.PRENOM || LP.NOM     AS LANCEURLIB,
       CASE
           WHEN F.ETAT = 1 THEN 'CREE'
           WHEN F.ETAT = 11 THEN 'VALIDE'
           WHEN F.ETAT = 0 THEN 'ANNULE'
           WHEN F.ETAT = 21 THEN 'ENTAME'
           WHEN F.ETAT = 31 THEN 'BLOQUE'
           WHEN F.ETAT = 41 THEN 'TERMINE'
           END                 AS ETATLIB,
       F.FABRICATIONPREC,
       F.FABRICATIONSUIV,
       (
           F.ID || ' | ' || P.VAL || ' | ' || P2.VAL || ' | ' || F.REMARQUE || ' | ' || IDOF || ' | ' || IDOFFILLE
           )                   AS MOTSCLESSS
FROM FABRICATION F
         LEFT JOIN MAGASINPOINT P ON P.ID = F.LANCEPAR
         LEFT JOIN MAGASINPOINT P2 ON P2.ID = F.CIBLE
         LEFT JOIN OFFILLE OFF ON F.IDOFFILLE = OFF.ID
         LEFT JOIN LOG_PERSONNEL LP ON LP.ID = F.LANCEUR
;
-- [431/1309] FABNONRATTACHE
CREATE OR REPLACE FORCE VIEW "FABNONRATTACHE" ("IDFABRICATION","DATY","IDPRODUIT","IDPRODUITLIB","QTE","QTEPETRI","IDLIGNE","LIGNE") AS
SELECT
	f.id AS idfabrication,
	f.daty AS daty,
	ffille.IDINGREDIENTS AS idproduit,
	ai.LIBELLE AS idproduitLib,
	ffille.qte AS qte,
	ffille.qte AS qtepetri,
	l.id AS idligne,
	l.VAL AS ligne
FROM 
FABRICATIONCPL f
LEFT JOIN FABRICATIONFILLE ffille ON f.ID =FFILLE.IDMERE
LEFT JOIN AS_INGREDIENTS ai ON ai.id=ffille.IDINGREDIENTS
LEFT JOIN AS_INGREDIENT_MAINTENANCE aim ON aim.id=ffille.IDMACHINE
LEFT JOIN LIGNE l ON l.id=aim.IDLIGNE
LEFT JOIN RELEVEFAB rfab ON RFAB.IDFAB = f.id
where ai.ispetri=1
;
-- [432/1309] FABRICATIONCPLANNULE
CREATE OR REPLACE FORCE VIEW "FABRICATIONCPLANNULE" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","IDOFFILLE","IDOF","LANCEPARLIB","CIBLELIB","ETAT","ETATLIB","FABRICATIONPREC","FABRICATIONSUIV") AS
SELECT 
ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM FABRICATIONCPL f 
WHERE etat = 0
;
-- [433/1309] FABRICATIONCPLBLOQUEE
CREATE OR REPLACE FORCE VIEW "FABRICATIONCPLBLOQUEE" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","IDOFFILLE","IDOF","LANCEPARLIB","CIBLELIB","ETAT","ETATLIB","FABRICATIONPREC","FABRICATIONSUIV") AS
SELECT 
ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM FABRICATIONCPL f 
WHERE etat = 31
;
-- [434/1309] FABRICATIONCPLBTERMINEE
CREATE OR REPLACE FORCE VIEW "FABRICATIONCPLBTERMINEE" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","IDOFFILLE","IDOF","LANCEPARLIB","CIBLELIB","ETAT","ETATLIB","FABRICATIONPREC","FABRICATIONSUIV") AS
SELECT 
ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM FABRICATIONCPL f 
WHERE etat = 41
;
-- [435/1309] FABRICATIONCPLCREE
CREATE OR REPLACE FORCE VIEW "FABRICATIONCPLCREE" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","IDOFFILLE","IDOF","LANCEPARLIB","CIBLELIB","ETAT","ETATLIB","FABRICATIONPREC","FABRICATIONSUIV") AS
SELECT 
ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM FABRICATIONCPL f 
WHERE etat = 1
;
-- [436/1309] FABRICATIONCPLENTAMEE
CREATE OR REPLACE FORCE VIEW "FABRICATIONCPLENTAMEE" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","IDOFFILLE","IDOF","LANCEPARLIB","CIBLELIB","ETAT","ETATLIB","FABRICATIONPREC","FABRICATIONSUIV") AS
SELECT 
ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM FABRICATIONCPL f 
WHERE etat = 21
;
-- [437/1309] FABRICATIONCPLVISEE
CREATE OR REPLACE FORCE VIEW "FABRICATIONCPLVISEE" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","IDOFFILLE","IDOF","LANCEPARLIB","CIBLELIB","ETAT","ETATLIB","FABRICATIONPREC","FABRICATIONSUIV") AS
SELECT 
ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM FABRICATIONCPL f 
WHERE etat = 11
;
-- [438/1309] INVENTAIRELIB
CREATE OR REPLACE FORCE VIEW "INVENTAIRELIB" ("ID","DATY","DESIGNATION","IDMAGASIN","IDMAGASINLIB","ETAT","HEURE","ETATLIB","IDCATEGORIE","IDCATEGORIELIB","MOTSCLESSS","REMARQUE","MONTANTQUANTITE") AS
SELECT
    i.ID ,
    i.DATY ,
    i.DESIGNATION ,
    i.IDMAGASIN ,
    m.VAL AS IDMAGASINLIB,
    i.ETAT , i.heure,
    CASE
        WHEN i.ETAT = 0
            THEN 'ANNUL&Eacute;'
        WHEN i.ETAT = 1
            THEN 'CR&Eacute;&Eacute;'
        WHEN i.ETAT = 11
            THEN 'VALID&Eacute;'
        END AS ETATLIB,
    i.idcategorie,
    c.VAL AS idcategorieLib,
    UPPER(
            NVL(i.DESIGNATION, '') || ' ' ||
            NVL(m.VAL, '') || ' ' ||
            NVL(c.VAL, '') || ' ' ||
            NVL(i.ID, '') || ' ' ||
            TO_CHAR(i.DATY, 'DD/MM/YYYY') || ' ' ||
            NVL(
                    CASE
                        WHEN i.ETAT = 0 THEN 'ANNUL&Eacute;'
                        WHEN i.ETAT = 1 THEN 'CR&Eacute;&Eacute;'
                        WHEN i.ETAT = 11 THEN 'VALID&Eacute;'
                        END
                , '')
    ) AS MOTSCLESSS,
    i.REMARQUE,
    CAST(ifgm.montantQuantite AS NUMBER(30,2) ) AS montantQuantite
FROM INVENTAIRE i
         LEFT JOIN MAGASINPOINT m ON m.ID = i.IDMAGASIN
         LEFT JOIN CATEGORIEINGREDIENT c ON c.id = i.idcategorie
         LEFT JOIN INVENTAIREFILLEGROUPEMERE ifgm ON ifgm.IDINVENTAIRE = i.id
order by daty desc
;
-- [439/1309] ECART_CARBU_GRAPH
CREATE OR REPLACE FORCE VIEW "ECART_CARBU_GRAPH" ("IDMAGASINLIB","DATY","ECART") AS
(
SELECT
    i.IDMAGASINLIB AS IDMAGASINLIB,
    i.DATY AS daty,
    ifc.QUANTITETHEORIQUE - ifc.QUANTITE AS ecart
FROM INVENTAIRELIB i
JOIN INVENTAIRE_FILLE_CPL ifc ON ifc.IDINVENTAIRE = i.ID
JOIN MAGASIN m ON m.id = i.IDMAGASIN
)
;
-- [440/1309] INVENTAIRELIB_ANNULEE
CREATE OR REPLACE FORCE VIEW "INVENTAIRELIB_ANNULEE" ("ID","DATY","DESIGNATION","IDMAGASIN","IDMAGASINLIB","ETAT","ETATLIB","MOTSCLESSS","MONTANTQUANTITE") AS
SELECT 
i.ID,i.DATY,i.DESIGNATION,i.IDMAGASIN,i.IDMAGASINLIB,i.ETAT,i.ETATLIB,i.MOTSCLESSS,i.montantQuantite
FROM INVENTAIRELIB i 
WHERE i.ETAT = 0
;
-- [441/1309] INVENTAIRELIB_CREE
CREATE OR REPLACE FORCE VIEW "INVENTAIRELIB_CREE" ("ID","DATY","DESIGNATION","IDMAGASIN","IDMAGASINLIB","ETAT","ETATLIB","MOTSCLESSS","MONTANTQUANTITE") AS
SELECT 
i.ID,i.DATY,i.DESIGNATION,i.IDMAGASIN,i.IDMAGASINLIB,i.ETAT,i.ETATLIB,i.MOTSCLESSS,i.montantQuantite
FROM INVENTAIRELIB i 
WHERE i.ETAT = 1
;
-- [442/1309] INVENTAIRELIB_VALIDEE
CREATE OR REPLACE FORCE VIEW "INVENTAIRELIB_VALIDEE" ("ID","DATY","DESIGNATION","IDMAGASIN","IDMAGASINLIB","ETAT","ETATLIB","MOTSCLESSS","MONTANTQUANTITE") AS
SELECT 
i.ID,i.DATY,i.DESIGNATION,i.IDMAGASIN,i.IDMAGASINLIB,i.ETAT,i.ETATLIB,i.MOTSCLESSS,i.montantQuantite
FROM INVENTAIRELIB i 
WHERE i.ETAT = 11
;
-- [443/1309] INVENTAIRE_FILLE_CPL_ING
CREATE OR REPLACE FORCE VIEW "INVENTAIRE_FILLE_CPL_ING" ("ID","IDINVENTAIRE","IDPRODUIT","IDPRODUITLIB","EXPLICATION","QUANTITETHEORIQUE","QUANTITE","DATY","IDMAGASIN","IDJAUGE","ETAT") AS
SELECT
i.ID ,
i.IDINVENTAIRE ,
NVL(i.IDPRODUIT,p.ID) AS IDPRODUIT,
p.LIBELLE AS IDPRODUITLIB,
NVL(i.EXPLICATION,'Inventaire 0') AS  EXPLICATION,
NVL(i.QUANTITETHEORIQUE,0) AS QUANTITETHEORIQUE,
NVL(i.QUANTITE,0) AS QUANTITE ,
NVL(i2.DATY, TO_DATE('01-01-2001', 'DD-MM-YYYY')) AS DATY ,
NVL(i2.IDMAGASIN, p.IDMAGASIN) AS IDMAGASIN ,
i.idJauge,
NVL(i2.ETAT,11) AS ETAT
FROM AS_INGREDIENTS_MAGASIN p
LEFT JOIN INVENTAIREFILLE i ON p.ID  = i.IDPRODUIT
LEFT JOIN INVENTAIRE i2 ON i2.ID  = i.IDINVENTAIRE
;
-- [444/1309] MAGASINVENTE
CREATE OR REPLACE FORCE VIEW "MAGASINVENTE" ("ID","VAL","DESCE","IDPOINT","IDPRODUIT","IDTYPEMAGASIN","ETAT","CAPACITE","COMPTEUR","IDMAGASINMERE") AS
select "ID","VAL","DESCE","IDPOINT","IDPRODUIT","IDTYPEMAGASIN","ETAT","CAPACITE","COMPTEUR","IDMAGASINMERE" from MAGASIN2 where ACTIF=1
;
-- [445/1309] MAGASIN_COMPTE_CPL
CREATE OR REPLACE FORCE VIEW "MAGASIN_COMPTE_CPL" ("ID","VAL","DESCE","NOMCOMPTE") AS
select m."ID",m."VAL",m."DESCE", c.LIBELLE as nomCompte
	from MAGASIN_COMPTE m
	         left join COMPTA_COMPTE c on m.DESCE = c.COMPTE
;
-- [446/1309] MAGASIN_SANSRESERVOIR
CREATE OR REPLACE FORCE VIEW "MAGASIN_SANSRESERVOIR" ("ID","VAL","DESCE","IDPOINT","IDPRODUIT","IDTYPEMAGASIN") AS
SELECT 
m."ID",m."VAL",m."DESCE",m."IDPOINT",m."IDPRODUIT",m."IDTYPEMAGASIN"
FROM MAGASIN m 
WHERE m.IDTYPEMAGASIN != 'TYPMG000001'
;
-- [447/1309] METIERLIB
CREATE OR REPLACE FORCE VIEW "METIERLIB" ("ID","VAL","DESCE","IDCODEROME","IDCODEROMELIB","IDSOUSFAMILLEPROLIB","IDFAMILLEPROLIB") AS
SELECT
    m.ID,m.VAL,m.DESCE,m.idcoderome,
    cr.code AS idcoderomelib,
    sfp.val AS idsousfamilleprolib,
    fp.val AS idfamilleprolib
FROM metier m
         LEFT JOIN code_rome cr ON cr.id=m.idcoderome
         LEFT JOIN sous_famille_pro sfp ON sfp.id=cr.idsousfamille
         LEFT JOIN famille_professionnelle fp ON fp.id=sfp.idfamille
;
-- [448/1309] EMPLOI_LIB
CREATE OR REPLACE FORCE VIEW "EMPLOI_LIB" ("ID","VAL","DESCE","IDMETIER","IDMETIERLIB","IDCODEROMELIB","IDSOUSFAMILLEPROLIB","IDFAMILLEPROLIB") AS
(
       select
       e.ID,e.VAL,e.DESCE,e.IDMETIER,
       m.val as idmetierlib,
       m.idcoderomelib,
       m.idsousfamilleprolib,
       m.idfamilleprolib
       from
       emploi e
       left join metierlib m on e.idmetier=m.id
)
;
-- [449/1309] MIRAGEDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "MIRAGEDETAIL_LIB" ("ID","IDMERE","IDBATIMENT","IDPARQUET","IDQUALITEMIRAGE","QTE","REMARQUE","IDBATIMENTLIB","IDPARQUETLIB","IDQUALITEMIRAGELIB") AS
SELECT d."ID",
       d."IDMERE",
       d."IDBATIMENT",
       d."IDPARQUET",
       d."IDQUALITEMIRAGE",
       d."QTE",
       d."REMARQUE",
       b."NOMBATIMENT" AS "IDBATIMENTLIB",
       p."VAL"         AS "IDPARQUETLIB",
       qm."VAL"        AS "IDQUALITEMIRAGELIB"
FROM "MIRAGEDETAIL" d
LEFT JOIN "BATIMENT" b ON b."ID" = d."IDBATIMENT"
LEFT JOIN "PARQUET" p ON p."ID" = d."IDPARQUET"
LEFT JOIN "QUALITEMIRAGE" qm ON qm."ID" = d."IDQUALITEMIRAGE"
;
-- [450/1309] MIRAGE_LIB
CREATE OR REPLACE FORCE VIEW "MIRAGE_LIB" ("ID","DATY","NOMBREOEUFSINITIAL","IDMACHINE","IDMACHINELIB") AS
SELECT m."ID",
       m."DATY",
       m."NOMBREOEUFSINITIAL",
       m."IDMACHINE",
       ma."VAL" AS "IDMACHINELIB"
FROM "MIRAGE" m
LEFT JOIN "MACHINE" ma ON ma."ID" = m."IDMACHINE"
;
-- [451/1309] MISEENINCUBATEURDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "MISEENINCUBATEURDETAIL_LIB" ("ID","IDMERE","IDLOT","IDBATIMENT","IDPARQUET","HEUREDEMARRAGE","HEUREFIN","DATEPONTE","QTE","POIDSMOYEN","IDLOTLIB","IDBATIMENTLIB","IDPARQUETLIB") AS
SELECT d."ID",
       d."IDMERE",
       d."IDLOT",
       d."IDBATIMENT",
       d."IDPARQUET",
       d."HEUREDEMARRAGE",
       d."HEUREFIN",
       d."DATEPONTE",
       d."QTE",
       d."POIDSMOYEN",
       l."NOMLOT"      AS "IDLOTLIB",
       b."NOMBATIMENT" AS "IDBATIMENTLIB",
       p."VAL"         AS "IDPARQUETLIB"
FROM "MISEENINCUBATEURDETAIL" d
LEFT JOIN "LOT" l ON l."ID" = d."IDLOT"
LEFT JOIN "BATIMENT" b ON b."ID" = d."IDBATIMENT"
LEFT JOIN "PARQUET" p ON p."ID" = d."IDPARQUET"
;
-- [452/1309] MISEENINCUBATEUR_LIB
CREATE OR REPLACE FORCE VIEW "MISEENINCUBATEUR_LIB" ("ID","DATEMISEENMACHINE","DATEECLOSIONPREVUE","IDINCUBATEUR","IDRESPONSABLE","TEMPERATEURCIBLE","HUMIDITECIBLE","HEUREPRECHAUFFAGE","HEUREDEBUTINCUBATION","IDINCUBATEURLIB","IDRESPONSABLELIB") AS
SELECT m."ID",
       m."DATEMISEENMACHINE",
       m."DATEECLOSIONPREVUE",
       m."IDINCUBATEUR",
       m."IDRESPONSABLE",
       m."TEMPERATEURCIBLE",
       m."HUMIDITECIBLE",
       m."HEUREPRECHAUFFAGE",
       m."HEUREDEBUTINCUBATION",
       inc."VAL"                       AS "IDINCUBATEURLIB",
       resp."NOM" || ' ' || resp."PRENOM" AS "IDRESPONSABLELIB"
FROM "MISEENINCUBATEUR" m
LEFT JOIN "INCUBATEUR" inc ON inc."ID" = m."IDINCUBATEUR"
LEFT JOIN "LOG_PERSONNEL" resp ON resp."ID" = m."IDRESPONSABLE"
;
-- [453/1309] MODEPAIEMENTMAJ
CREATE OR REPLACE FORCE VIEW "MODEPAIEMENTMAJ" ("ID","VAL","DESCE") AS
select id, upper(val) as val, upper(desce) as desce from MODEPAIEMENT
;
-- [454/1309] MONTANTAPAYER
CREATE OR REPLACE FORCE VIEW "MONTANTAPAYER" ("MONTANTAPAYER","IDFACTUREFOURNISSEUR","IDORIGINE") AS
SELECT 
 	sum(DEBIT) AS montantapayer,
 	f.id AS idfacturefournisseur,
 	m.IDORIGINE AS IDORIGINE 
 FROM MOUVEMENTCAISSE m 
 LEFT JOIN FACTUREFOURNISSEUR f ON m.IDORIGINE =f.ID 
 GROUP BY f.ID , m.IDORIGINE
;
-- [455/1309] FACTUREFOURNISSEURCPL_MONTANT
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURCPL_MONTANT" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","MONTANT","MONTANTPAYER","MONTANTRESTE") AS
SELECT f.ID,
       f.IDFOURNISSEUR,
       f2.NOM                                                                      AS IDFOURNISSEURLIB,
       f.IDMODEPAIEMENT,
       m.VAL                                                                       AS IDMODEPAIEMENTLIB,
       f.DATY,
       f.DESIGNATION,
       f.DATEECHEANCEPAIEMENT,
       f.ETAT,
       CASE
           WHEN f.ETAT = 1
               THEN 'CREE'
           WHEN f.ETAT = 0
               THEN 'ANNULEE'
           WHEN f.ETAT = 11
               THEN 'VISEE'
           WHEN f.ETAT = 9
               THEN 'ENCAISEE'
           END                                                                     AS ETATLIB,
       f.REFERENCE,
       f.IDBC,
       f.IDMAGASIN,
       f.DEVISE,
       f.TAUX,
       p.VAL                                                                       AS idMagasinLib,
       cast(mon.montant as NUMBER(30, 2))                                          as montant,
       cast(nvl(m.montantapayer, 0) as NUMBER(30, 2))                              as montantpayer,
       case
           when mon.montant < nvl(m.montantapayer, 0) then 0
           else cast((mon.montant - nvl(m.montantapayer, 0)) as NUMBER(30, 2)) end as montantreste
FROM FACTUREFOURNISSEUR f
         LEFT JOIN FOURNISSEUR f2 ON f2.ID = f.IDFOURNISSEUR
         LEFT JOIN MODEPAIEMENT m ON m.ID = f.IDMODEPAIEMENT
         LEFT JOIN MAGASIN p ON p.ID = f.IDMAGASIN
         left join FACTUREFOURNISSEUR_montant mon on mon.IDFACTUREFOURNISSEUR = f.id
         LEFT JOIN montantapayer m ON f.ID = m.idfacturefournisseur
;
-- [456/1309] FACTUREFOURNISSEUR_LIVRENONPAY
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_LIVRENONPAY" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","MONTANT","MONTANTPAYER","MONTANTRESTE") AS
SELECT "ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","MONTANT","MONTANTPAYER","MONTANTRESTE"
FROM FACTUREFOURNISSEURCPL_montant
WHERE ETAT = 13
;
-- [457/1309] FACTUREFOURNISSEUR_PAYELIVRE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_PAYELIVRE" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","MONTANT","MONTANTPAYER","MONTANTRESTE") AS
SELECT "ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","MONTANT","MONTANTPAYER","MONTANTRESTE"FROM FACTUREFOURNISSEURCPL_montant
WHERE ETAT = 14
;
-- [458/1309] FACTUREFOURNISSEUR_PAYENOLIVRE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_PAYENOLIVRE" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","MONTANT","MONTANTPAYER","MONTANTRESTE") AS
SELECT "ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","MONTANT","MONTANTPAYER","MONTANTRESTE"
FROM FACTUREFOURNISSEURCPL_montant
WHERE ETAT = 12
;
-- [459/1309] MONTANTENCAISSEMENT
CREATE OR REPLACE FORCE VIEW "MONTANTENCAISSEMENT" ("IDENCAISSEMENT","IDORIGINE","MONTANTTOTALENCAISSEMENT") AS
SELECT 
ed.IDENCAISSEMENT ,
ed.IDORIGINE,
sum( nvl( ed.MONTANT ,0 ) ) AS montantTotalEncaissement
FROM ENCAISSEMENT_DETAILS ed 
GROUP BY ed.IDENCAISSEMENT,ed.IDORIGINE
;
-- [460/1309] MONTANTPRECISIONENCAISSEMENT
CREATE OR REPLACE FORCE VIEW "MONTANTPRECISIONENCAISSEMENT" ("IDENCAISSEMENT","IDCATEGORIECAISSE","MONTANTTOTALPRECISION") AS
SELECT 
pde.IDENCAISSEMENT ,
pde.IDCATEGORIECAISSE ,
sum( nvl(pde.MONTANT , 0) ) AS montantTotalPrecision 
FROM PRECISION_DETAIL_ENCAISSEMENT pde 
GROUP BY pde.IDENCAISSEMENT , pde.IDCATEGORIECAISSE
;
-- [461/1309] ENCAISSEMENT_PRECISION_TOTAL
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_PRECISION_TOTAL" ("ID","IDENCAISSEMENT","IDCATEGORIECAISSE","MONTANT","REMARQUE","MONTANTTOTALPRECISION") AS
SELECT 
ed.ID ,
ed.IDENCAISSEMENT ,
ed.IDCATEGORIECAISSE ,
ed.MONTANT ,
ed.REMARQUE ,
nvl(pde.montantTotalPrecision,0) AS montantTotalPrecision
FROM ENCAISSEMENT_DETAILS ed 
LEFT JOIN MONTANTPRECISIONENCAISSEMENT pde ON pde.IDENCAISSEMENT = ed.IDENCAISSEMENT AND pde.IDCATEGORIECAISSE = ed.IDCATEGORIECAISSE 
WHERE ed.IDCATEGORIECAISSE != 'CTC004'
;
-- [462/1309] MOTRAVAUXLIB
CREATE OR REPLACE FORCE VIEW "MOTRAVAUXLIB" ("ID","IDPERSONNEL","IDTRAVAUX","DUREEESTIMATIF","TAUXHORAIRE","DUREEESTIMATIFLIB","MONTANT","IDPERSONNELLIB") AS
SELECT
    mo."ID",mo."IDPERSONNEL",mo."IDTRAVAUX",mo."DUREEESTIMATIF",mo."TAUXHORAIRE",
    LPAD(FLOOR(TO_NUMBER(mo.DUREEESTIMATIF) / 3600), 2, '0') || ':' ||
    LPAD(FLOOR(MOD(TO_NUMBER(mo.DUREEESTIMATIF), 3600) / 60), 2, '0') || ':' ||
    LPAD(MOD(TO_NUMBER(mo.DUREEESTIMATIF), 60), 2, '0')
                                               AS dureeEstimatifLib,
    ((mo.DUREEESTIMATIF/60)/60)*mo.TAUXHORAIRE AS montant,
    p.NOM AS idPersonnelLib
FROM MOTRAVAUX mo
         LEFT JOIN PERSONNEL p ON p.ID = mo.IDPERSONNEL
;
-- [463/1309] MOUVEMENTCAISSEAUTOCOMPLETE
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSEAUTOCOMPLETE" ("ID","DESIGNATION","IDCAISSE","IDVENTEDETAIL","IDVIREMENT","DATY","ETAT","IDOP","IDORIGINE","IDDEVISE","IDTIERS","COMPTE","IDPREVISION","IDTRAITE","ETATVERSEMENT","IDMODEPAIEMENT","IDMVTCAISSEMERE","REFERENCE","UPDATED_AT","DATYCOMPTABILISATION","ACQUEREUR","IDTYPEPAIEMENT","DEBIT","CREDIT","TAUX","HEURE","IDREPORT","IDCAISSIER","MONTANTRETOURNER") AS
SELECT
    mc.ID,
    mc.DESIGNATION,
    mc.IDCAISSE,
    mc.IDVENTEDETAIL,
    mc.IDVIREMENT,
    mc.DATY,
    mc.ETAT,
    mc.IDOP,
    mc.IDORIGINE,
    mc.IDDEVISE,
    CASE
        WHEN mc.IDTIERS IS NOT NULL
            THEN mc.IDTIERS||'---'||c.nom
        END AS IDTIERS,
    mc.COMPTE,
    CASE
        WHEN mc.IDPREVISION IS NOT NULL
            THEN mc.IDPREVISION||'---'||p.designation
        END AS IDPREVISION,
    mc.IDTRAITE,
    mc.ETATVERSEMENT,
    mc.IDMODEPAIEMENT,
    mc.IDMVTCAISSEMERE,
    mc.REFERENCE,
    mc.UPDATED_AT,
    mc.DATYCOMPTABILISATION,
    mc.ACQUEREUR,
    mc.IDTYPEPAIEMENT,
    mc.DEBIT,
    mc.CREDIT,
    mc.TAUX,
    mc.HEURE,
    mc.idReport,
    mc.idCaissier,
    mc.montantRetourner
FROM mouvementcaisse mc
     LEFT JOIN CLIENT c ON c.id=mc.IDTIERS
     LEFT JOIN prevision p ON p.id=mc.IDPREVISION
;
-- [464/1309] MOUVEMENTCAISSEAVECHEURE
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSEAVECHEURE" ("ID","DESIGNATION","IDCAISSE","IDVENTEDETAIL","IDVIREMENT","DATY","ETAT","IDOP","IDORIGINE","IDDEVISE","IDTIERS","COMPTE","IDPREVISION","IDTRAITE","ETATVERSEMENT","IDMODEPAIEMENT","IDMVTCAISSEMERE","REFERENCE","UPDATED_AT","DATYCOMPTABILISATION","ACQUEREUR","IDTYPEPAIEMENT","DEBIT","CREDIT","TAUX","HEURE","IDREPORT") AS
SELECT
    m.ID,
    m.DESIGNATION,
    m.IDCAISSE,
    m.IDVENTEDETAIL,
    m.IDVIREMENT,
    CASE
        WHEN m.HEURE IS NOT NULL AND m.HEURE != '00:00:00'
        THEN m.DATY + (TO_NUMBER(SUBSTR(m.HEURE, 1, 2)) / 24)
                   + (TO_NUMBER(SUBSTR(m.HEURE, 4, 2)) / 1440)
                   + (TO_NUMBER(SUBSTR(m.HEURE, 7, 2)) / 86400)
        ELSE m.DATY
    END AS DATY,
    m.ETAT,
    m.IDOP,
    m.IDORIGINE,
    m.IDDEVISE,
    m.IDTIERS,
    m.COMPTE,
    m.IDPREVISION,
    m.IDTRAITE,
    m.ETATVERSEMENT,
    m.IDMODEPAIEMENT,
    m.IDMVTCAISSEMERE,
    m.REFERENCE,
    m.UPDATED_AT,
    m.DATYCOMPTABILISATION,
    m.ACQUEREUR,
    m.IDTYPEPAIEMENT,
    m.DEBIT,
    m.CREDIT,
    m.TAUX,
    m.HEURE,
    m.idReport
FROM MOUVEMENTCAISSE m
;
-- [465/1309] MOUVEMENTCAISSEFILLECPL
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSEFILLECPL" ("ID","DESIGNATION","IDCAISSE","IDVENTEDETAIL","IDVIREMENT","DATY","ETAT","IDOP","IDORIGINE","IDDEVISE","IDTIERS","COMPTE","IDPREVISION","IDTRAITE","ETATVERSEMENT","IDMODEPAIEMENT","IDMVTCAISSEMERE","REFERENCE","UPDATED_AT","DATYCOMPTABILISATION","ACQUEREUR","IDTYPEPAIEMENT","DEBIT","CREDIT","TAUX","HEURE","IDREPORT","IDCAISSIER","MONTANTRETOURNER","IDCAISSELIB") AS
select m."ID",m."DESIGNATION",m."IDCAISSE",m."IDVENTEDETAIL",m."IDVIREMENT",m."DATY",m."ETAT",m."IDOP",m."IDORIGINE",m."IDDEVISE",m."IDTIERS",m."COMPTE",m."IDPREVISION",m."IDTRAITE",m."ETATVERSEMENT",m."IDMODEPAIEMENT",m."IDMVTCAISSEMERE",m."REFERENCE",m."UPDATED_AT",m."DATYCOMPTABILISATION",m."ACQUEREUR",m."IDTYPEPAIEMENT",m."DEBIT",m."CREDIT",m."TAUX",m."HEURE",m."IDREPORT",m."IDCAISSIER",m."MONTANTRETOURNER", c.VAL as idCaisseLib from mouvementcaisse m
left join caisse c on m.IDCAISSE = c.id
;
-- [466/1309] MOUVEMENTCAISSEGROUPEFACTURE
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSEGROUPEFACTURE" ("IDORIGINE","CREDIT","DEBIT","IDDEVISE") AS
select idorigine, sum(credit) as credit,sum(debit) as debit, C.IDDEVISE from mouvementcaisse m
LEFT JOIN caisse c on  c.id=idcaisse
  where m.etat>=11 and idorigine is not null
group by idorigine,c.iddevise
;
-- [467/1309] FACTUREDECLARATIONCPL
CREATE OR REPLACE FORCE VIEW "FACTUREDECLARATIONCPL" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","COMPTE","TAUX","IDMAGASINLIB","IDDEVISE","MONTANTTVA","MONTANTHT","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","TAUXDECHANGE","IDPREVISION","ESTPREVULIB","IDOBJET","IDREF","IDTYPEFACTURE","TYPEFACTURE","NUMERO","TYPEACHAT") AS
SELECT
             f.ID,
             f.IDFOURNISSEUR,
             f2.NOM AS IDFOURNISSEURLIB,

             f.IDMODEPAIEMENT,
             m.VAL AS IDMODEPAIEMENTLIB,

             f.DATY,
             f.DESIGNATION,
             f.DATEECHEANCEPAIEMENT,

             f.ETAT,
             CASE
                 WHEN f.ETAT = 1  THEN 'CREE'
                 WHEN f.ETAT = 0  THEN 'ANNULEE'
                 WHEN f.ETAT = 11 THEN 'VISEE'
                 END AS ETATLIB,

             f.REFERENCE,
             f.IDBC,
             f.IDMAGASIN,
             f.DEVISE,
             f2.COMPTE,

             NVL(NULLIF(f.TAUX,0),1) AS TAUX,

             p.VAL AS IDMAGASINLIB,

             f.IDDEVISE,

             CAST(NVL(f3.MONTANTTVA,0) AS NUMBER(30,2)) AS MONTANTTVA,
             CAST(NVL(f3.MONTANTTTC,0) - NVL(f3.MONTANTTVA,0) AS NUMBER(30,2)) AS MONTANTHT,
             CAST(NVL(f3.MONTANTTTC,0) AS NUMBER(30,2)) AS MONTANTTTC,

             CAST(
                     NVL(f3.MONTANTTTC,0) * NVL(f3.tauxdechange,1)
                 AS NUMBER(30,2)
             ) AS MONTANTTTCAR,

             CAST(NVL(mv.debit,0) AS NUMBER(30,2)) AS MONTANTPAYE,
             CAST(NVL(f3.MONTANTTTC,0) - NVL(mv.debit,0) AS NUMBER(30,2)) AS MONTANTRESTE,

             CAST(NVL(f3.tauxdechange,1) AS NUMBER(30,2)) AS TAUXDECHANGE,

             prev.ID AS IDPREVISION,

             CASE
                 WHEN f.estprevu = 0 THEN 'NON'
                 ELSE 'OUI'
                 END AS ESTPREVULIB,

             f.IDOBJET,
             f.IDREF,
             f.IDTYPEFACTURE,
             tf.VAL AS TYPEFACTURE,
             f.NUMERO,
             f.TYPEACHAT

         FROM FACTUREDECLARATION f
                  LEFT JOIN FOURNISSEUR f2 ON f2.ID = f.IDFOURNISSEUR
                  LEFT JOIN MODEPAIEMENT m ON m.ID = f.IDMODEPAIEMENT
                  LEFT JOIN MAGASIN p ON p.ID = f.IDMAGASIN
                  LEFT JOIN FACTUREDECLARATIONMONTANT f3 ON f.ID = f3.ID
                  LEFT JOIN MOUVEMENTCAISSEGROUPEFACTURE mv ON f.ID = mv.IDORIGINE
                  LEFT JOIN PREVISION prev ON prev.IDFACTURE = f.ID
                  LEFT JOIN TYPE_FACTURE tf ON tf.ID = f.IDTYPEFACTURE
;
-- [468/1309] DECLARATIONTVALIB
CREATE OR REPLACE FORCE VIEW "DECLARATIONTVALIB" ("ID","DESIGNATION","DATYDEBUT","DATYFIN","ETAT","ETATLIB","MONTANTPAYER","PAYEMENTLIB") AS
SELECT
             de.id,
             de.designation,
             de.datyDebut,
             de.datyFin,
             de.etat,
             CASE
                 WHEN de.etat = 1 THEN 'Cree'
                 WHEN de.etat = 11 THEN 'Valide'
                 ELSE 'Inconnu'
                 END AS etatLib,
             nvl(mv.DEBIT,nvl(fd.MONTANTTTC,0)) as montantpayer,
             case
                 when mv.IDORIGINE is null then case when fd.IDBC='CREDIT' then 'Reporte' else 'Non paye' end
                 else 'Paye'
                 END as payementLib
         FROM DeclarationTVA de left join FACTUREDECLARATIONCPL fd on de.id=fd.IDOBJET left join mouvementcaisse mv on mv.IDORIGINE=fd.id
;
-- [469/1309] FACTUREFOURNISSEURAVECMACHINE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURAVECMACHINE" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","IDDEVISE","MONTANTTVA","MONTANTHT","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","TAUXDECHANGE","IDPREVISION","ESTPREVULIB","IDOBJET","IDREF","IDOBJETLIB","IDENTITE","IDLIGNE","IDLIGNELIB") AS
SELECT f.ID,
       f.IDFOURNISSEUR,
       f2.NOM  AS IDFOURNISSEURLIB,
       f.IDMODEPAIEMENT,
       m.VAL   AS IDMODEPAIEMENTLIB,
       f.DATY,
       f.DESIGNATION,
       f.DATEECHEANCEPAIEMENT,
       f.ETAT,
       CASE
           WHEN f.ETAT = 1
               THEN 'CREEE'
           WHEN f.ETAT = 0
               THEN 'ANNULEE'
           WHEN f.ETAT = 11
               THEN 'VISEE'
           END AS ETATLIB,
       f.REFERENCE,
       f.IDBC,
       f.IDMAGASIN,
       f.DEVISE,
       case
           when f.TAUX=0 then 1
           else f.TAUX
           end as taux,
       p.VAL   AS idMagasinLib,
       f3.IDDEVISE,
       cast(f3.MONTANTTVA as number(30,2)) as MONTANTTVA,
       CAST(f3.MONTANTTTC-f3.MONTANTTVA as number(30,2)) AS MONTANTHT,
       cast(f3.MONTANTTTC as number(30,2)) as montantttc,
       cast(f3.MONTANTTTC*f3.tauxdechange as number(30,2)) as MONTANTTTCAR,
       cast(nvl(mv.debit,0) AS NUMBER(30,2)) AS montantpaye,
       cast(f3.MONTANTTTC-nvl(mv.debit,0) AS NUMBER(30,2)) AS montantreste,
       cast(nvl(f3.tauxdechange,0) AS  NUMBER(30,2)) AS tauxdechange,
       prev.id as idPrevision,
       CASE
           WHEN f.estprevu=0 THEN 'NON'
           ELSE 'OUI'
           END
           AS estprevulib,
       f.IDOBJET,
       f.IDREF,
       machine.LIBELLE AS idObjetLib,
       machine.IDENTITE,
       ligne.id AS idligne,
       ligne.val AS idlignelib
FROM FACTUREFOURNISSEUR f
         LEFT JOIN FOURNISSEUR f2 ON f2.ID = f.IDFOURNISSEUR
         LEFT JOIN MODEPAIEMENT m ON m.ID = f.IDMODEPAIEMENT
         LEFT JOIN MAGASIN p ON p.ID = f.IDMAGASIN
         JOIN FACTUREFOURNISSEURMONTANT f3 ON f.ID = f3.id
         LEFT JOIN mouvementcaisseGroupeFacture mv ON f.id=mv.IDORIGINE
         LEFT JOIN prevision prev ON prev.idfacture=f.id
         JOIN AS_INGREDIENT_MAINTENANCE machine ON machine.ID = f.IDOBJET
         LEFT JOIN LIGNE ligne ON ligne.id=machine.idLIGNE
;
-- [470/1309] FACTUREFOURNISSEURCPL_M
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURCPL_M" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","IDDEVISE","MONTANTTVA","MONTANTHT","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","TAUXDECHANGE","IDPREVISION","ESTPREVULIB","IDOBJET","IDREF") AS
SELECT f.ID,
       f.IDFOURNISSEUR,
       f2.NOM  AS IDFOURNISSEURLIB,
       f.IDMODEPAIEMENT,
       m.VAL   AS IDMODEPAIEMENTLIB,
       f.DATY,
       f.DESIGNATION,
       f.DATEECHEANCEPAIEMENT,
       f.ETAT,
       CASE
           WHEN f.ETAT = 1
               THEN 'CREEE'
           WHEN f.ETAT = 0
               THEN 'ANNULEE'
           WHEN f.ETAT = 11
               THEN 'VISEE'
           END AS ETATLIB,
       f.REFERENCE,
       f.IDBC,
       f.IDMAGASIN,
       f.DEVISE,
       case
           when f.TAUX=0 then 1
           else f.TAUX
           end as taux,
       p.VAL   AS idMagasinLib,
       f3.IDDEVISE,
       cast(f3.MONTANTTVA as number(30,2)) as MONTANTTVA,
       CAST(f3.MONTANTTTC-f3.MONTANTTVA as number(30,2)) AS MONTANTHT,
       cast(f3.MONTANTTTC as number(30,2)) as montantttc,
       cast(f3.MONTANTTTC*f3.tauxdechange as number(30,2)) as MONTANTTTCAR,
       cast(nvl(mv.debit,0) AS NUMBER(30,2)) AS montantpaye,
       cast(f3.MONTANTTTC-nvl(mv.debit,0) AS NUMBER(30,2)) AS montantreste,
       cast(nvl(f3.tauxdechange,0) AS  NUMBER(30,2)) AS tauxdechange,
       prev.id as idPrevision,
       CASE
           WHEN f.estprevu=0 THEN 'NON'
           ELSE 'OUI'
           END
           AS estprevulib,
       f.IDOBJET,
       f.IDREF
FROM FACTUREFOURNISSEUR f
         LEFT JOIN FOURNISSEUR f2 ON f2.ID = f.IDFOURNISSEUR
         LEFT JOIN MODEPAIEMENT m ON m.ID = f.IDMODEPAIEMENT
         LEFT JOIN MAGASIN p ON p.ID = f.IDMAGASIN
         JOIN FACTUREFOURNISSEURMONTANT f3 ON f.ID = f3.id
         LEFT JOIN mouvementcaisseGroupeFacture mv ON f.id=mv.IDORIGINE
         LEFT JOIN prevision prev ON prev.idfacture=f.id
;
-- [471/1309] FACTUREFOURNISSEURCPL_TOUS_M
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURCPL_TOUS_M" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","IDMAGASINLIB","DEVISE","IDDEVISE","ETAT","TAUX","MONTANTTVA","MONTANTHT","TAUXDECHANGE","MONTANTTTC","MONTANTPAYE","MONTANTRESTE","IDOBJET","IDREF") AS
SELECT
    fcpl.id,
    fcpl.idfournisseur,
    fcpl.idfournisseurlib,
    fcpl.idmodepaiement,
    fcpl.idmodepaiementlib,
    fcpl.daty,
    fcpl.designation,
    fcpl.dateecheancepaiement,
    fcpl.etatlib,
    fcpl.reference,
    fcpl.idbc,
    fcpl.idmagasin,
    fcpl.idmagasinlib,
    fcpl.devise,
    fcpl.iddevise,
    fcpl.etat,
    fcpl.taux,
    fcpl.montanttva,
    fcpl.montantht,
    fcpl.tauxdechange,
    fcpl.montantttc AS  MONTANTTTC,
    nvl((fcpl.montantpaye * fcpl.TAUXDECHANGE),0) AS MONTANTPAYE,
    nvl((fcpl.montantreste * fcpl.TAUXDECHANGE),0) AS MONTANTRESTE,
    fcpl.IDOBJET,
    fcpl.IDREF
FROM FACTUREFOURNISSEURCPL_M fcpl
;
-- [472/1309] FACTUREFOURNISSEURCPL_TRAVAUX
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURCPL_TRAVAUX" ("ID","IDFOURNISSEUR","IDFOURNISSEURLIB","IDMODEPAIEMENT","IDMODEPAIEMENTLIB","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","ETATLIB","REFERENCE","IDBC","IDMAGASIN","DEVISE","TAUX","IDMAGASINLIB","IDDEVISE","MONTANTTVA","MONTANTHT","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","TAUXDECHANGE","IDPREVISION","ESTPREVULIB","IDOBJET","IDREF","IDTYPEFACTURE","TYPEFACTURE","NUMERO","TYPEACHAT","IDTRAVAUX") AS
SELECT f.ID,
	       f.IDFOURNISSEUR,
	       f2.NOM  AS IDFOURNISSEURLIB,
	       f.IDMODEPAIEMENT,
	       m.VAL   AS IDMODEPAIEMENTLIB,
	       f.DATY,
	       f.DESIGNATION,
	       f.DATEECHEANCEPAIEMENT,
	       f.ETAT,
	       CASE
	           WHEN f.ETAT = 1
	               THEN 'CREEE'
	           WHEN f.ETAT = 0
	               THEN 'ANNULEE'
	           WHEN f.ETAT = 11
	               THEN 'VISEE'
	           END AS ETATLIB,
	       f.REFERENCE,
	       f.IDBC,
	       f.IDMAGASIN,
	       f.DEVISE,
	       case
	           when f.TAUX=0 then 1
	           else f.TAUX
	           end as taux,
	       p.VAL   AS idMagasinLib,
	       f3.IDDEVISE,
	       cast(f3.MONTANTTVA as number(30,2)) as MONTANTTVA,
	       CAST(f3.MONTANTTTC-f3.MONTANTTVA as number(30,2)) AS MONTANTHT,
	       cast(f3.MONTANTTTC as number(30,2)) as montantttc,
	       cast(f3.MONTANTTTC*f3.tauxdechange as number(30,2)) as MONTANTTTCAR,
	       cast(nvl(mv.debit,0) AS NUMBER(30,2)) AS montantpaye,
	       cast(f3.MONTANTTTC-nvl(mv.debit,0) AS NUMBER(30,2)) AS montantreste,
	       cast(nvl(f3.tauxdechange,0) AS  NUMBER(30,2)) AS tauxdechange,
	       prev.id as idPrevision,
	       CASE
	           WHEN f.estprevu=0 THEN 'NON'
	           ELSE 'OUI'
	           END
	           AS estprevulib,
	       f.IDOBJET,
	       f.IDREF,
	       f.IDTYPEFACTURE,
	       tf.VAL as typefacture,
	       f.numero,
	       f.typeachat,
	       t.id AS idTravaux
	FROM FACTUREFOURNISSEUR f
	         LEFT JOIN FOURNISSEUR f2 ON f2.ID = f.IDFOURNISSEUR
	         LEFT JOIN MODEPAIEMENT m ON m.ID = f.IDMODEPAIEMENT
	         LEFT JOIN MAGASIN p ON p.ID = f.IDMAGASIN
	         JOIN FACTUREFOURNISSEURMONTANT f3 ON f.ID = f3.id
	         LEFT JOIN mouvementcaisseGroupeFacture mv ON f.id=mv.IDORIGINE
	         LEFT JOIN prevision prev ON prev.idfacture=f.id
	         left join type_facture tf on tf.id = f.IDTYPEFACTURE
	         LEFT JOIN dmdAchat d ON f.idDmdAchat = d.id
	         LEFT JOIN TRAVAUX t ON d.idObjet = t.id
;
-- [473/1309] MOUVEMENTCAISSEGROUPERESA
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSEGROUPERESA" ("IDORIGINE","CREDIT","DEBIT","IDDEVISE") AS
select m.idop as idorigine, sum(credit) as credit,sum(debit) as debit, C.IDDEVISE from mouvementcaisse m
LEFT JOIN caisse c on  c.id=idcaisse
  where m.etat>=11 and idop is not null
group by m.idop,c.iddevise
;
-- [474/1309] MOUVEMENTCAISSEGRPAVOIR_LP
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSEGRPAVOIR_LP" ("IDORIGINE","MONTANT","IDDEVISE") AS
select m.id1 as idorigine, sum(montant) as montant, 'AR' as IDDEVISE
from LIAISONPAIEMENT m
where m.etat >= 11
  and id1 is not null
group by m.id1
;
-- [475/1309] MOUVEMENTCAISSEMERELIB
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSEMERELIB" ("ID","DESIGNATION","IDMODEPAIEMENT","CREDIT","DEBIT","IDTIERS","IDORIGINE","DATY","ETAT","IDMODEPAIEMENTLIB","IDTIERSLIB","ETATLIB") AS
SELECT
    m."ID",m."DESIGNATION",m."IDMODEPAIEMENT",m."CREDIT",m."DEBIT",m."IDTIERS",m."IDORIGINE",m."DATY",m."ETAT",
    mp.VAL AS idmodepaiementlib,
    c.NOM AS idtierslib,
    CASE
        WHEN m.ETAT = 1 THEN 'CREEE'
        WHEN m.ETAT = 11 THEN 'VISEE'
        WHEN m.ETAT = 0 THEN 'ANNULEE'
        END AS etatlib
FROM mouvementcaissemere m
         LEFT JOIN MODEPAIEMENT mp ON mp.id = m.idmodepaiement
         LEFT JOIN CLIENT c ON c.id = m.idtiers
;
-- [476/1309] MOUVEMENTCAISSE_VISE
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSE_VISE" ("ID","DESIGNATION","IDCAISSE","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDORIGINE","IDDEVISE","TAUX","IDTIERS","COMPTE","IDPREVISION","IDTRAITE","ETATVERSEMENT","IDMODEPAIEMENT","IDMVTCAISSEMERE","REFERENCE") AS
select "ID","DESIGNATION","IDCAISSE","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDORIGINE","IDDEVISE","TAUX","IDTIERS","COMPTE","IDPREVISION","IDTRAITE","ETATVERSEMENT","IDMODEPAIEMENT","IDMVTCAISSEMERE","REFERENCE" from MOUVEMENTCAISSE
WHERE ETAT=11
;
-- [477/1309] MTBFDETAIL
CREATE OR REPLACE FORCE VIEW "MTBFDETAIL" ("ID","IDMACHINE","IDMACHINELIB","DATY","ECART") AS
select
    otf.id,
    otf.IDINGREDIENTS as idMachine,
    ai.LIBELLE as idMachineLib,
    ot.DATY,
    nvl(
            ot.DATY - lead(ot.DATY) over (
                partition by otf.IDINGREDIENTS
                order by ot.DATY desc
                ),
            0
    ) as ecart
from ORDRETRAVAUX ot
         left join ORDRETRAVAUXFILLE otf
                   on otf.IDMERE = ot.ID
         left join AS_INGREDIENT_MAINTENANCE ai
                   on ai.ID = otf.IDINGREDIENTS
;
-- [478/1309] MVTCAISSEGROUPEFACTURE_PDF
CREATE OR REPLACE FORCE VIEW "MVTCAISSEGROUPEFACTURE_PDF" ("IDORIGINE","DEBIT","CREDIT","MONTANTRETOURNER","IDDEVISE") AS
select id2 AS idorigine, sum(l.MONTANT ) as debit, sum(m.credit) as credit, sum(m.montantretourner) as montantretourner, c.IDDEVISE
from LIAISONPAIEMENT l
         left join MOUVEMENTCAISSE m on m.id = l.id1
         left join caisse c on c.ID = m.idcaisse
where l.etat >= 11
  and id1 is not NULL
group BY id2, c.IDDEVISE, m.montantretourner
;
-- [479/1309] MVTCAISSEPREVISIONVISE
CREATE OR REPLACE FORCE VIEW "MVTCAISSEPREVISIONVISE" ("ID","ID1","ID2","MONTANTMERE","ETAT","REMARQUE","MONTANTCREDIT","DEVISE","TAUX") AS
select "ID","ID1","ID2","MONTANTMERE","ETAT","REMARQUE","MONTANTCREDIT","DEVISE","TAUX" from MVTCAISSEPREVISION where etat>=1
;
-- [480/1309] MVTCAISSEGROUPPREVISIONSOM
CREATE OR REPLACE FORCE VIEW "MVTCAISSEGROUPPREVISIONSOM" ("ID","ID1","ID2","ETAT","REMARQUE","MONTANTMERE","MONTANTCREDIT","TAUX","DEVISE") AS
SELECT '-' AS id, id1,'' AS id2,etat,'-' AS remarque,sum(montantMere) AS montantMere,sum(montantCredit) AS montantCredit,nvl(max(taux),1) AS taux,devise 
FROM MVTCAISSEPREVISIONVise GROUP BY id1,etat,devise
;
-- [481/1309] MVTCAISSESOMPREVISIONGROUP
CREATE OR REPLACE FORCE VIEW "MVTCAISSESOMPREVISIONGROUP" ("ID","ID1","ID2","ETAT","REMARQUE","MONTANTMERE","MONTANTCREDIT","TAUX","DEVISE") AS
SELECT '-' AS id, '' AS id1,id2,etat,'-' AS remarque,sum(montantMere) AS montantMere,sum(montantCredit) AS montantCredit,nvl(max(taux),1) AS taux,devise  
FROM MVTCAISSEPREVISIONVise GROUP BY id2,etat,devise
;
-- [482/1309] MVTCONGEBYMOISANNEE
CREATE OR REPLACE FORCE VIEW "MVTCONGEBYMOISANNEE" ("IDPERSONNEL","PLUS","MOIS","ANNEE") AS
SELECT
    m.IDPERSONNEL,
    SUM(m.PLUS) AS plus,
    m.MOIS,
    m.ANNEE
FROM MOUVEMENTABSENCE m
GROUP BY m.IDPERSONNEL, m.MOIS, m.ANNEE
;
-- [483/1309] MVTINTRACAISSETRAITE
CREATE OR REPLACE FORCE VIEW "MVTINTRACAISSETRAITE" ("ID","DATY","CAISSEDEPART","CAISSEARRIVEE","MONTANT","MODEPAIEMENT","REMARQUE","ETAT","DESIGNATION","IDTRAITE","ETATVERSEMENT","IDFINALEDESTINATION","DATETRAITE","DATEECHEANCE","MONTANTTRAITE") AS
select
    mit.ID,mit.DATY,mit.CAISSEDEPART,mit.CAISSEARRIVEE,mit.MONTANT,mit.MODEPAIEMENT,mit.REMARQUE,mit.ETAT,mit.DESIGNATION,mit.IDTRAITE,mit.ETATVERSEMENT,mit.IDFINALEDESTINATION,
    t.daty as datetraite,
    t.dateecheance,
    t.montant as montanttraite
from MvtIntraCaisse mit
         left join Traite t on t.id = mit.idtraite
;
-- [484/1309] MVTINTRACAISSETRAITENONVERSEE
CREATE OR REPLACE FORCE VIEW "MVTINTRACAISSETRAITENONVERSEE" ("ID","DATY","CAISSEDEPART","CAISSEARRIVEE","MONTANT","MODEPAIEMENT","REMARQUE","ETAT","DESIGNATION","IDTRAITE","ETATVERSEMENT","IDFINALEDESTINATION","DATEECHEANCE") AS
SELECT
    mic.ID,mic.DATY,mic.CAISSEDEPART,mic.CAISSEARRIVEE,mic.MONTANT,mic.MODEPAIEMENT,mic.REMARQUE,mic.ETAT,mic.DESIGNATION,mic.IDTRAITE,mic.ETATVERSEMENT,mic.IDFINALEDESTINATION,
    t.DATEECHEANCE
from mvtintracaisse mic
         JOIN traite t on t.id = mic.idtraite
;
-- [485/1309] MVTINTRACAISSETRAITEVCAISSE
CREATE OR REPLACE FORCE VIEW "MVTINTRACAISSETRAITEVCAISSE" ("ID","DATY","CAISSEDEPART","CAISSEARRIVEE","MONTANT","MODEPAIEMENT","REMARQUE","ETAT","DESIGNATION","IDTRAITE","ETATVERSEMENT","IDFINALEDESTINATION","DATEECHEANCE") AS
SELECT
    mic.ID,
    mic.DATY,
    mic.CAISSEDEPART,
    mic.CAISSEARRIVEE,
    CAST(mic.MONTANT AS NUMBER(30,2)) AS MONTANT,
    mic.MODEPAIEMENT,
    mic.REMARQUE,
    mic.ETAT,
    mic.DESIGNATION,
    mic.IDTRAITE,
    mic.ETATVERSEMENT,
    mic.IDFINALEDESTINATION,
    t.DATEECHEANCE
FROM
    mvtintracaisse mic
        JOIN traite t ON
        t.id = mic.idtraite
WHERE
    mic.etatversement IN (11, -2)
;
-- [486/1309] MVTINTRACAISSE_LIB
CREATE OR REPLACE FORCE VIEW "MVTINTRACAISSE_LIB" ("ID","DATY","CAISSEDEPARTLIB","CAISSEARRIVEELIB","CAISSEDEPART","CAISSEARRIVEE","MONTANT","MODEPAIEMENT","REMARQUE","ETAT","DESIGNATION") AS
select mv.id,
       daty,
       mv.CAISSEDEPART  as caissedepartlib,
       mv.CAISSEARRIVEE as caissearriveelib,
       ca.VAL as caissedepart,
       ca1.VAL as caissearrivee,
       montant,
       mp.VAL as modepaiement,
       remarque,
       etat ,
       mv.designation
from mvtintracaisse mv
         left join CAISSE ca on ca.id=mv.caissedepart
         left join CAISSE ca1 on ca1.id=mv.caissearrivee
         left join MODEPAIEMENT mp on mp.id=mv.modepaiement
;
-- [487/1309] MVTINTRACAISSE_LIBCOMPLET
CREATE OR REPLACE FORCE VIEW "MVTINTRACAISSE_LIBCOMPLET" ("ID","DATY","CAISSEDEPART","CAISSEARRIVEE","MONTANT","MODEPAIEMENT","REMARQUE","ETAT","CAISSEDEPARTLIB","CAISSEARRIVEELIB","MODEPAIEMENTLIB") AS
select mv.ID,mv.DATY,mv.CAISSEDEPART,mv.CAISSEARRIVEE,mv.MONTANT,mv.MODEPAIEMENT,mv.REMARQUE,mv.ETAT,
       ca.VAL  as caissedepartlib,
       ca1.VAL as caissearriveelib,
       mp.VAL  as modepaiementlib
from mvtintracaisse mv
         left join CAISSE ca on ca.id = mv.caissedepart
         left join CAISSE ca1 on ca1.id = mv.caissearrivee
         left join MODEPAIEMENT mp on mp.id = mv.modepaiement
;
-- [488/1309] MVTINTRACAISSE_LIB_CREE
CREATE OR REPLACE FORCE VIEW "MVTINTRACAISSE_LIB_CREE" ("ID","DATY","CAISSEDEPART","CAISSEARRIVEE","MONTANT","MODEPAIEMENT","REMARQUE","ETAT") AS
select ID,DATY,CAISSEDEPART,CAISSEARRIVEE,MONTANT,MODEPAIEMENT,REMARQUE,ETAT
from mvtintracaisse_lib
where ETAT=1
;
-- [489/1309] MVTINTRACAISSE_LIB_VISEE
CREATE OR REPLACE FORCE VIEW "MVTINTRACAISSE_LIB_VISEE" ("ID","DATY","CAISSEDEPART","CAISSEARRIVEE","MONTANT","MODEPAIEMENT","REMARQUE","ETAT") AS
select ID,DATY,CAISSEDEPART,CAISSEARRIVEE,MONTANT,MODEPAIEMENT,REMARQUE,ETAT
from mvtintracaisse_lib
where ETAT=11
;
-- [490/1309] MVTSTOCKAUTOCOMPLETE
CREATE OR REPLACE FORCE VIEW "MVTSTOCKAUTOCOMPLETE" ("ID","DESIGNATION","IDMAGASIN","IDVENTE","IDTRANSFERT","IDTYPEMVSTOCK","DATY","ETAT","IDPOINT","IDOBJET","FABPRECEDENT","IDCATEGORIESTOCK") AS
SELECT
m.ID,
m.DESIGNATION,
m.IDMAGASIN,
m.IDVENTE,
m.IDTRANSFERT,
m.IDTYPEMVSTOCK,
m.DATY,
m.ETAT,
m.IDPOINT,
m.IDOBJET,
CASE 
	WHEN m.FABPRECEDENT IS NOT NULL 
	THEN m.FABPRECEDENT||'---'||f.LIBELLE 
	ELSE m.FABPRECEDENT
END AS FABPRECEDENT,
m.IDCATEGORIESTOCK
FROM MVTSTOCK m 
LEFT JOIN FABRICATION f ON f.id = m.FABPRECEDENT
;
-- [491/1309] MVTSTOCKDATEHEURE
CREATE OR REPLACE FORCE VIEW "MVTSTOCKDATEHEURE" ("ID","DESIGNATION","IDMAGASIN","IDVENTE","IDTRANSFERT","IDTYPEMVSTOCK","DATY","ETAT","IDPOINT","IDOBJET","FABPRECEDENT","IDCATEGORIESTOCK","HEURE") AS
select m.ID, DESIGNATION, IDMAGASIN, IDVENTE, IDTRANSFERT, IDTYPEMVSTOCK, TO_DATE(TO_CHAR(m.DATY, 'YYYY-MM-DD') || ' ' || NVL(m.HEURE, '00:00:00'), 'YYYY-MM-DD HH24:MI:SS') as DATY, ETAT, IDPOINT, IDOBJET, FABPRECEDENT, IDCATEGORIESTOCK, HEURE from MVTSTOCK m
;
-- [492/1309] MVTSTOCKENTREEAVECRESTEGROUPE
CREATE OR REPLACE FORCE VIEW "MVTSTOCKENTREEAVECRESTEGROUPE" ("IDINGREDIENT","QUANTITE") AS
SELECT 
m.IDPRODUIT AS idingredient,
sum(nvl(m.reste,m.ENTREE)) AS quantite
FROM MVTSTOCKFILLE m 
LEFT JOIN MVTSTOCK mp ON mp.id = m.IDMVTSTOCK
WHERE m.ENTREE > 0
GROUP BY m.IDPRODUIT
;
-- [493/1309] MVTSTOCKFILLEAUTOCOMPLETE
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEAUTOCOMPLETE" ("ID","IDMVTSTOCK","IDPRODUIT","IDVENTEDETAIL","IDTRANSFERTDETAIL","MVTSRC","DESIGNATION","ENTREE","SORTIE","PU","RESTE","IDINVENTAIREFILLE","DATEINVENTAIRE","QTEINVENTAIRE") AS
SELECT 
m.ID,
m.IDMVTSTOCK,
CASE 
	WHEN m.IDPRODUIT IS NOT NULL 
	THEN m.IDPRODUIT||'---'||a.libelle 
END AS IDPRODUIT,
m.IDVENTEDETAIL,
m.IDTRANSFERTDETAIL,
m.MVTSRC,
m.DESIGNATION,
m.ENTREE,
m.SORTIE,
m.PU,
m.RESTE,
m.IDINVENTAIREFILLE,
m.DATEINVENTAIRE,
m.QTEINVENTAIRE
FROM MVTSTOCKFILLE m 
LEFT JOIN AS_INGREDIENTS a ON a.id = m.IDPRODUIT
;
-- [494/1309] MVTSTOCKFILLEAVECSOURCE
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEAVECSOURCE" ("ID","IDMVTSTOCK","IDPRODUIT","IDVENTEDETAIL","IDTRANSFERTDETAIL","MVTSRC","DESIGNATION","ENTREE","SORTIE","PU","RESTE") AS
select mf.ID,
    mf.IDMVTSTOCK,
    mf.IDPRODUIT,
    mf.IDVENTEDETAIL ,
    mf.IDTRANSFERTDETAIL,
    nvl(mf.MVTSRC,mf.id) as MVTSRC,
    mf.DESIGNATION,
    mf.ENTREE,
    mf.SORTIE,
    mf.PU,
    mf.RESTE
    from MVTSTOCKFILLE mf
;
-- [495/1309] MVTSTOCKFILLECPTSTOCK
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLECPTSTOCK" ("ID","IDMVTSTOCK","IDPRODUIT","IDVENTEDETAIL","IDTRANSFERTDETAIL","MVTSRC","DESIGNATION","ENTREE","SORTIE","PU","RESTE","IDINVENTAIREFILLE","DATEINVENTAIRE","QTEINVENTAIRE","COMPTE_STOCK","COMPTE_SORTIE_STOCK") AS
select msf."ID",msf."IDMVTSTOCK",msf."IDPRODUIT",msf."IDVENTEDETAIL",msf."IDTRANSFERTDETAIL",msf."MVTSRC",msf."DESIGNATION",msf."ENTREE",msf."SORTIE",msf."PU",msf."RESTE",msf."IDINVENTAIREFILLE",msf."DATEINVENTAIRE",msf."QTEINVENTAIRE",ing.COMPTE_STOCK,ing.COMPTE_SORTIE_STOCK from MVTSTOCKFILLE msf left join AS_INGREDIENTS ing on ing.id=msf.IDPRODUIT
;
-- [496/1309] MVTSTOCKFILLEFAB
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEFAB" ("ID","IDMVTSTOCK","IDPRODUIT","ENTREE","SORTIE","IDVENTEDETAIL","IDTRANSFERTDETAIL","PU","MVTSRC","RESTE","DESIGNATION","IDFAB") AS
select st."ID",st."IDMVTSTOCK",st."IDPRODUIT",st."ENTREE",st."SORTIE",st."IDVENTEDETAIL",st."IDTRANSFERTDETAIL",st."PU",st."MVTSRC",st."RESTE",st."DESIGNATION",m.IDOBJET as idFab from MVTSTOCKFILLE st left join MVTSTOCK m on st.IDMVTSTOCK=m.ID
;
-- [497/1309] MVTSTOCKFILLEENTREEFAB
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEENTREEFAB" ("ID","IDMVTSTOCK","IDPRODUIT","IDPRODUITLIB","ENTREE","SORTIE","IDVENTEDETAIL","IDTRANSFERTDETAIL","PU","MVTSRC","RESTE","DESIGNATION","IDFAB") AS
select st.ID,st.IDMVTSTOCK,st.IDPRODUIT,ai.LIBELLE AS IDPRODUITLIB,st.ENTREE,st.SORTIE,st.IDVENTEDETAIL,st.IDTRANSFERTDETAIL,st.PU,st.MVTSRC,st.RESTE,st.DESIGNATION,st.IDFAB 
from MVTSTOCKFILLEFAB st
LEFT JOIN AS_INGREDIENTS ai
ON st.IDPRODUIT = ai.id
WHERE st.SORTIE <= 0
;
-- [498/1309] MVTSTOCKFILLEFABVISE
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEFABVISE" ("ID","IDMVTSTOCK","IDPRODUIT","ENTREE","SORTIE","IDVENTEDETAIL","IDTRANSFERTDETAIL","PU","MVTSRC","RESTE","DESIGNATION","IDFAB") AS
select st."ID",st."IDMVTSTOCK",st."IDPRODUIT",st."ENTREE",st."SORTIE",st."IDVENTEDETAIL",st."IDTRANSFERTDETAIL",st."PU",st."MVTSRC",st."RESTE",st."DESIGNATION",m.IDOBJET as idFab
from MVTSTOCKFILLE st left join MVTSTOCK m on st.IDMVTSTOCK=m.ID  where m.etat>=11
;
-- [499/1309] MVTSTOCKFILLEFABOFCATVISE
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEFABOFCATVISE" ("ID","IDMVTSTOCK","IDPRODUIT","ENTREE","SORTIE","IDVENTEDETAIL","IDTRANSFERTDETAIL","PU","MVTSRC","RESTE","DESIGNATION","IDFAB","CATEGORIEINGREDIENT","IDOF","LIBELLE","IDOFF","PV","MONTANTENTREE","MONTANTSORTIE") AS
select m."ID",m."IDMVTSTOCK",m."IDPRODUIT",m."ENTREE",m."SORTIE",m."IDVENTEDETAIL",m."IDTRANSFERTDETAIL",m."PU",m."MVTSRC",m."RESTE",m."DESIGNATION",m."IDFAB",cat.VAL as CATEGORIEINGREDIENT,fille.IDMERE as idOf,ing.LIBELLE,fille.id as idoff,ing.pv, cast(nvl(m.ENTREE*m.PU,0) as number(30,2)) as montantEntree ,cast(nvl(m.sortie*m.PU,0) as number(30,2)) as montantSortie
    from MVTSTOCKFILLEFABVISE m left join AS_INGREDIENTS ing on m.IDPRODUIT=ing.ID
left join CATEGORIEINGREDIENT cat on ing.CATEGORIEINGREDIENT=cat.id
left join fabrication fab on m.IDFAB=fab.id
left join OFFILLE fille on fab.IDOFFILLE=fille.ID
where ing.COMPOSE=0
;
-- [500/1309] MVTSTFILLEFABCATVISEGROUPE
CREATE OR REPLACE FORCE VIEW "MVTSTFILLEFABCATVISEGROUPE" ("IDFAB","ENTREE","SORTIE","MONTANT","IDPRODUIT","CATEGORIEINGREDIENT","LIBELLE") AS
select idfab,cast(sum(ENTREE) as number(30,2)) as entree,cast(sum(sortie) as number(30,2)) as sortie,
           cast(sum(nvl(pu*ENTREE,0)) as number(30,2)) as montant, IDPRODUIT,CATEGORIEINGREDIENT,LIBELLE
    from MVTSTOCKFILLEFABOFCATVISE
    group by idfab,IDPRODUIT,CATEGORIEINGREDIENT,LIBELLE
;
-- [501/1309] FABRICATIONENCOURS
CREATE OR REPLACE FORCE VIEW "FABRICATIONENCOURS" ("IDINGREDIENTS","FABENCOURS") AS
SELECT 
    fab.IDINGREDIENTS, 
    CAST(
        GREATEST(
            NVL(SUM(fab.QTE), 0) - NVL(SUM(mvt.ENTREE), 0), 
            0
        ) 
        AS NUMBER(30,2)
    ) AS FabEncours
FROM fabricationFilleFabriqueVise fab
LEFT JOIN MVTSTFILLEFABCATVISEGROUPE mvt 
    ON mvt.IDFAB = fab.IDMERE 
    AND mvt.IDPRODUIT = fab.IDINGREDIENTS
GROUP BY fab.IDINGREDIENTS
;
-- [502/1309] AS_RECOFFVUESTFAB
CREATE OR REPLACE FORCE VIEW "AS_RECOFFVUESTFAB" ("ID","IDINGREDIENTS","UNITE","QTEAV","QUANTITE","IDPRODUITS","IDUNITE","COMPOSE","NIVEAU","LIBINGREDIENTS","RESTESTOCK","RAF","FABENCOURS","TYPESTOCK") AS
SELECT
    a."ID",
    a."IDINGREDIENTS",
    a."UNITE",
    a."QTEAV",
    a."QUANTITE",
    a."IDPRODUITS",
    a."IDUNITE",
    a."COMPOSE",
    a."NIVEAU",
    a."LIBINGREDIENTS",
    a."RESTESTOCK",
    CAST(a.RAF AS NUMBER(30,10)) AS RAF,
    NVL(f.FabEncours,0) AS FabEncours,
    a.TYPESTOCK
  FROM as_recOffVueResteSt a
  LEFT JOIN FabricationEncours f
    ON f.IDINGREDIENTS = a.IDINGREDIENTS
;
-- [503/1309] MVTSTFILLEOFCATVISEGROUPE
CREATE OR REPLACE FORCE VIEW "MVTSTFILLEOFCATVISEGROUPE" ("IDOF","ENTREE","SORTIE","MONTANT","IDPRODUIT","CATEGORIEINGREDIENT","LIBELLE") AS
select idOf,cast(sum(ENTREE) as number(30,2)) as entree,cast(sum(sortie) as number(30,2)) as sortie,
    cast(sum(nvl(pu*ENTREE,0)) as number(30,2)) as montant     ,IDPRODUIT,CATEGORIEINGREDIENT,LIBELLE
    from MVTSTOCKFILLEFABOFCATVISE
    group by idOf,IDPRODUIT,CATEGORIEINGREDIENT,LIBELLE
;
-- [504/1309] MVTSTFILLEOFFCATVISEGROUPE
CREATE OR REPLACE FORCE VIEW "MVTSTFILLEOFFCATVISEGROUPE" ("IDOFF","ENTREE","SORTIE","MONTANT","MONTANTSORTIE","PV") AS
select m.idoff,cast(sum(m.ENTREE) as number(30,2)) as entree,cast(sum(m.sortie) as number(30,2)) as sortie,
           sum(m.montantEntree) as montant,sum(m.montantSortie) as montantSortie, cast(avg(m.pv) as number(30,2)) as pv
    from MVTSTOCKFILLEFABOFCATVISE m
    group by m.idoff
;
-- [505/1309] MVTSTFILLEOFFCATVISEGROUPEDEP
CREATE OR REPLACE FORCE VIEW "MVTSTFILLEOFFCATVISEGROUPEDEP" ("IDOFF","ENTREE","SORTIE","MONTANT","MONTANTSORTIE","PV") AS
select nvl(m.idoff,c.idoff) as idoff,m.entree,m.sortie,m.montant,cast (nvl(m.montantSortie,0)+nvl(c.montantsortie,0) as number(30,2)) as montantsortie,m.pv from MVTSTFILLEOFFCATVISEGROUPE m full outer join chargeGroupByOff c on m.idoff=c.idoff
;
-- [506/1309] MVTSTOCKFILLEFABOFCATVISETOUS
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEFABOFCATVISETOUS" ("ID","IDMVTSTOCK","IDPRODUIT","ENTREE","SORTIE","IDVENTEDETAIL","IDTRANSFERTDETAIL","PU","MVTSRC","RESTE","DESIGNATION","IDFAB","CATEGORIEINGREDIENT","IDOF","LIBELLE","IDOFF","PV","MONTANTENTREE","MONTANTSORTIE") AS
select m."ID",m."IDMVTSTOCK",m."IDPRODUIT",m."ENTREE",m."SORTIE",m."IDVENTEDETAIL",m."IDTRANSFERTDETAIL",m."PU",m."MVTSRC",m."RESTE",m."DESIGNATION",m."IDFAB",cat.VAL as CATEGORIEINGREDIENT,fille.IDMERE as idOf,ing.LIBELLE,fille.id as idoff,ing.pv, cast(nvl(m.ENTREE*m.PU,0) as number(30,2)) as montantEntree ,cast(nvl(m.sortie*m.PU,0) as number(30,2)) as montantSortie
    from MVTSTOCKFILLEFABVISE m left join AS_INGREDIENTS ing on m.IDPRODUIT=ing.ID
left join CATEGORIEINGREDIENT cat on ing.CATEGORIEINGREDIENT=cat.id
left join fabrication fab on m.IDFAB=fab.id
left join OFFILLE fille on fab.IDOFFILLE=fille.ID
;
-- [507/1309] MVTSTOCKFILLEGROUPEMERE
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEGROUPEMERE" ("IDMVTSTOCK","MONTANTENTREE","MONTANTSORTIE") AS
select f.IDMVTSTOCK,cast(sum(nvl(f.pu*f.ENTREE,0)) as number(30,2)) as montantEntree,
    cast(sum(nvl(f.pu*f.sortie,0)) as number(30,2)) as montantSortie
           from MVTSTOCKFILLE f group by f.IDMVTSTOCK
;
-- [508/1309] MVTSTOCKFILLEGRP
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEGRP" ("IDMVTSTOCK","ENTREE","SORTIE","COMPTE_STOCK","COMPTE_SORTIE_STOCK") AS
SELECT
    f.IDMVTSTOCK,
    SUM(f.ENTREE * f.PU) AS entree,
    SUM(f.SORTIE * f.PU) AS SORTIE,
    ing.compte_stock,
    compte_sortie_stock
FROM MVTSTOCKFILLE f
         LEFT JOIN AS_INGREDIENTS ing ON ing.ID = f.IDPRODUIT
GROUP BY f.IDMVTSTOCK, ing.compte_stock,compte_sortie_stock
;
-- [509/1309] MVTSTOCKFILLEGRPVARIATION
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEGRPVARIATION" ("IDMVTSTOCK","ENTREE","SORTIE","COMPTE_STOCK","COMPTE_SORTIE_STOCK") AS
SELECT
    f.IDMVTSTOCK,
    SUM(f.ENTREE * f.PU) AS entree,
    SUM(f.SORTIE * f.PU) AS SORTIE,
     null as compte_stock,
    ing.compte_sortie_stock
FROM MVTSTOCKFILLE f
         LEFT JOIN AS_INGREDIENTS ing ON ing.ID = f.IDPRODUIT
GROUP BY f.IDMVTSTOCK, ing.compte_sortie_stock
;
-- [510/1309] MVTSTOCKFILLELIB
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLELIB" ("ID","IDMVTSTOCK","IDPRODUIT","IDPRODUITLIB","ENTREE","SORTIE","IDVENTEDETAIL","IDVENTEDETAILLIB","IDTRANSFERTDETAIL","IDTRANSFERTDETAILLIB","DATY","IDMAGASIN","IDMAGASINLIB","PU","MONTANT","LIBELLE","MVTSRC","LIBELLEEXACTE","DATESQL","IDOBJET","IDTYPEMVSTOCK","ETAT","ETATLIB","IDUNITE","IDUNITELIB") AS
SELECT
    m.ID ,
    m.IDMVTSTOCK ,
    m.IDPRODUIT ,
    p.libelle  AS IDPRODUITLIB,
    m.ENTREE ,
    m.SORTIE ,
    m.IDVENTEDETAIL ,
    '' AS IDVENTEDETAILLIB,
    m.IDTRANSFERTDETAIL ,
    '' AS IDTRANSFERTDETAILLIB,
    m2.DATY ,
    m2.IDMAGASIN ,
    m3.VAL AS IDMAGASINLIB,
    m.pu,
    cast(m.pu*m.ENTREE+(m.pu*m.sortie) as number(20,5)) as montant,
    p.LIBELLE,
    m.MVTSRC,
    p.libelle AS libelleexacte,
    m2.DATY AS dateSql,
    m2.idobjet,
    m2.IDTYPEMVSTOCK,
    m2.etat,
    CASE
        WHEN m2.ETAT = 1 THEN 'CR&Eacute;&Eacute;'
        WHEN m2.ETAT = 11 THEN 'VIS&Eacute;'
        WHEN m2.ETAT = 11 THEN 'ANNUL&Eacute;'
        END    AS ETATLIB,
    p.UNITE AS idunite,
    asu.VAL AS idunitelib
FROM MVTSTOCKFILLE m
         LEFT JOIN AS_INGREDIENTS  p ON p.ID = m.IDPRODUIT
         LEFT JOIN MVTSTOCK m2 ON m2.ID = m.IDMVTSTOCK
         LEFT JOIN MAGASIN2 m3 ON m3.ID = m2.IDMAGASIN
         LEFT JOIN AS_UNITE asu ON asu.ID = p.UNITE
;
-- [511/1309] MVTSTOCKFILLELIB_VISE
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLELIB_VISE" ("ID","IDMVTSTOCK","IDPRODUIT","IDPRODUITLIB","ENTREE","SORTIE","IDVENTEDETAIL","IDVENTEDETAILLIB","IDTRANSFERTDETAIL","IDTRANSFERTDETAILLIB","DATY","IDMAGASIN","IDMAGASINLIB") AS
SELECT m.ID,
       m.IDMVTSTOCK,
       m.IDPRODUIT,
       p.LIBELLE  AS IDPRODUITLIB,
       m.ENTREE,
       m.SORTIE,
       m.IDVENTEDETAIL,
       ''     AS IDVENTEDETAILLIB,
       m.IDTRANSFERTDETAIL,
       ''     AS IDTRANSFERTDETAILLIB,
       m2.DATY,
       m2.IDMAGASIN,
       m3.VAL AS IDMAGASINLIB
FROM MVTSTOCKFILLE m
         LEFT JOIN AS_INGREDIENTS  p ON p.ID = m.IDPRODUIT
         LEFT JOIN MVTSTOCK m2 ON m2.ID = m.IDMVTSTOCK
         LEFT JOIN MAGASIN m3 ON m3.ID = m2.IDMAGASIN
where m2.ETAT=11
;
-- [512/1309] MVTSTOCKFILLEMONTANT
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEMONTANT" ("ID","IDMVTSTOCK","IDPRODUIT","ENTREE","SORTIE","IDVENTEDETAIL","IDTRANSFERTDETAIL","PU","MVTSRC","RESTE","DESIGNATION","MONTANTENTREE","MONTANTSORTIE") AS
select mf."ID",mf."IDMVTSTOCK",mf."IDPRODUIT",mf."ENTREE",mf."SORTIE",mf."IDVENTEDETAIL",mf."IDTRANSFERTDETAIL",mf."PU",mf."MVTSRC",mf."RESTE",mf."DESIGNATION",cast(mf.PU*mf.ENTREE as number(30,5)) as montantEntree,cast(mf.PU*mf.SORTIE as number(30,5)) as montantSortie from MVTSTOCKFILLE mf
;
-- [513/1309] MONTANT_STOCK
CREATE OR REPLACE FORCE VIEW "MONTANT_STOCK" ("IDPRODUIT","ENTREE","SORTIE","QUANTITE","MONTANTENTREE","MONTANTSORTIE","MONTANT","IDMAGASIN") AS
SELECT
    mf.IDPRODUIT,
    SUM(NVL(mf.ENTREE,0)) AS ENTREE,
    SUM(NVL(mf.SORTIE,0)) AS SORTIE,
    SUM(NVL(mf.ENTREE,0)) - SUM(NVL(mf.SORTIE,0)) AS quantite,
    cast(sum(mf.montantEntree) as number(30,2))  AS montantEntree,
    cast(sum(mf.montantSortie) as number(30,2))  AS montantSortie,
    CAST(NVL(ai.PU, 0) * (SUM(NVL(mf.ENTREE,0)) - SUM(NVL(mf.SORTIE,0))) AS NUMBER(30,2)) AS montant,
    m.IDMAGASIN
FROM
    mvtStockFilleMontant mf
        JOIN MVTSTOCK m ON m.id = mf.IDMVTSTOCK
        JOIN AS_INGREDIENTS ai ON ai.ID = mf.IDPRODUIT
WHERE
    m.ETAT >= 11
  AND mf.IDPRODUIT IS NOT NULL
GROUP BY
    mf.IDPRODUIT,
    ai.PU,m.IDMAGASIN
;
-- [514/1309] MVTSTOCKFILLEMONTANT_ENG
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEMONTANT_ENG" ("ID","IDMVTSTOCK","IDPRODUIT","ENTREE","SORTIE","IDVENTEDETAIL","IDTRANSFERTDETAIL","PU","MVTSRC","RESTE","DESIGNATION","MONTANTENTREE","MONTANTSORTIE") AS
select mf.ID,
       mf.IDMVTSTOCK,
       mf.IDPRODUIT,
       mf.ENTREE,
       mf.SORTIE,
       mf.IDVENTEDETAIL,
       mf.IDTRANSFERTDETAIL,
       mf.PU,
       mf.MVTSRC,
       mf.RESTE,
       mf.DESIGNATION,
       cast(mf.PU * mf.ENTREE as number(30, 5)) as montantEntree,
       cast(mf.PU * mf.SORTIE as number(30, 5)) as montantSortie
from MVTSTOCKFILLE mf
union all
select mf.ID,
       mf.IDMVTSTOCK,
       mf.IDPRODUIT,
       mf.ENTREE,
       mf.SORTIE,
       mf.IDVENTEDETAIL,
       mf.IDTRANSFERTDETAIL,
       mf.PU,
       mf.MVTSRC,
       mf.RESTE,
       mf.DESIGNATION,
       cast(mf.PU * mf.ENTREE as number(30, 5)) as montantEntree,
       cast(mf.PU * mf.SORTIE as number(30, 5)) as montantSortie
from stock_engage_FILLE mf
;
-- [515/1309] MVTSTOCKFILLEOFENTREEPRFINI
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEOFENTREEPRFINI" ("ENTREE","IDOFF","IDPRODUIT") AS
select cast(sum(ENTREE) as number(30,2)) as entree,idoff,IDPRODUIT from MVTSTOCKFILLEFABOFCATVISETous m group by idoff, IDPRODUIT
;
-- [516/1309] MVTSTOCKFILLEPARDATE
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEPARDATE" ("DATY","IDMAGASIN","IDPRODUIT","ENTREE","SORTIE") AS
select
    m.daty,
    m.IDMAGASIN,
    mf.IDPRODUIT,
    cast(nvl(sum(mf.ENTREE),0) as number(30,3)) as entree,
    CAST(NVL(SUM(mf.SORTIE), 0) AS NUMBER(30,3)) AS sortie
from MVTSTOCKFILLE mf
left join mvtstock m ON m.id = mf.IDMVTSTOCK
where m.ETAT >= 11
group by m.daty, mf.IDPRODUIT, m.IDMAGASIN
;
-- [517/1309] MVTSTOCKFILLESANSINVENTAIRE
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLESANSINVENTAIRE" ("ID","IDMVTSTOCK","IDPRODUIT","IDVENTEDETAIL","IDTRANSFERTDETAIL","MVTSRC","DESIGNATION","ENTREE","SORTIE","PU","RESTE","IDINVENTAIREFILLE") AS
select mf."ID",mf."IDMVTSTOCK",mf."IDPRODUIT",mf."IDVENTEDETAIL",mf."IDTRANSFERTDETAIL",mf."MVTSRC",mf."DESIGNATION",mf."ENTREE",mf."SORTIE",mf."PU",mf."RESTE",mf."IDINVENTAIREFILLE" from mvtStockFille mf
    left join mvtStock m on m.id=mf.IDMVTSTOCK
    where m.ETAT>=11 and mf.entree>0
      and not exists(select invf.id from INVENTAIREFILLE invf left join INVENTAIRE im on im.ID=invf.IDINVENTAIRE where invf.IDPRODUIT=mf.IDPRODUIT and invf.MVTSRC=mf.id and im.IDMAGASIN=m.IDMAGASIN)
;
-- [518/1309] INVENTAIREFILLEVIDE
CREATE OR REPLACE FORCE VIEW "INVENTAIREFILLEVIDE" ("ID","IDINVENTAIRE","IDPRODUIT","EXPLICATION","IDJAUGE","QUANTITETHEORIQUE","QUANTITE","MVTSOURCE","PU","IDFOURNISSEUR","DATY") AS
select 'invvidef'||mfv.ID as id,'invVide' as idinventaire,mfv.IDPRODUIT,'inv Auto Vide' as explication,null as idjauge,cast( 0 as number(30,10)) as QUANTITETHEORIQUE,cast(0 as number(30,10)) as quantite,mfv.ID as mvtsource
         ,cast(1 as number(30,5)) as pu,null as idfournisseur, null as daty from mvtStockFilleSansInventaire mfv
;
-- [519/1309] INVENTAIREFILLEAVECVIDE
CREATE OR REPLACE FORCE VIEW "INVENTAIREFILLEAVECVIDE" ("ID","IDINVENTAIRE","IDPRODUIT","EXPLICATION","IDJAUGE","QUANTITETHEORIQUE","QUANTITE","MVTSRC","PU","IDFOURNISSEUR","DATY") AS
select "ID","IDINVENTAIRE","IDPRODUIT","EXPLICATION","IDJAUGE","QUANTITETHEORIQUE","QUANTITE","MVTSRC","PU","IDFOURNISSEUR","DATY" from INVENTAIREFILLE union all select "ID","IDINVENTAIRE","IDPRODUIT","EXPLICATION","IDJAUGE","QUANTITETHEORIQUE","QUANTITE","MVTSOURCE","PU","IDFOURNISSEUR","DATY" from inventaireFilleVide
;
-- [520/1309] MVTSTOCKFILLESORITEFAB
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLESORITEFAB" ("ID","IDMVTSTOCK","IDPRODUIT","IDPRODUITLIB","ENTREE","SORTIE","IDVENTEDETAIL","IDTRANSFERTDETAIL","PU","MVTSRC","RESTE","DESIGNATION","IDFAB") AS
select st.ID,st.IDMVTSTOCK,st.IDPRODUIT,ai.LIBELLE AS IDPRODUITLIB,st.ENTREE,st.SORTIE,st.IDVENTEDETAIL,st.IDTRANSFERTDETAIL,st.PU,st.MVTSRC,st.RESTE,st.DESIGNATION,st.idFab
from MVTSTOCKFILLEFAB st
LEFT JOIN AS_INGREDIENTS ai
ON st.IDPRODUIT = ai.id
WHERE st.ENTREE  <= 0
;
-- [521/1309] MVTSTOCKFILLERESIDUFAB
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLERESIDUFAB" ("ID","IDPRODUIT","IDPRODUITLIB","ENTREE","PU","RESTE","DESIGNATION","IDFAB") AS
SELECT
    entree.ID ,
    entree.IDPRODUIT,
    entree.IDPRODUITLIB,
    entree.ENTREE,
    entree.PU AS PU,
    entree.RESTE AS RESTE,
    entree.DESIGNATION,
    entree.IDFAB
FROM
    MVTSTOCKFILLEENTREEFAB entree
JOIN
    MVTSTOCKFILLESORITEFAB sortie
ON
    entree.IDPRODUIT = sortie.IDPRODUIT
AND
    entree.IDFAB = sortie.IDFAB
;
-- [522/1309] MVTSTOCKFILLERESIDUOF
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLERESIDUOF" ("IDPRODUIT","IDPRODUITLIB","ENTREE","PU","RESTE","IDOF") AS
SELECT mf.IDPRODUIT, mf.IDPRODUITLIB, sum(nvl(mf.ENTREE,0)) AS ENTREE, sum(nvl(mf.PU ,0)) AS PU,sum(nvl(mf.RESTE ,0)) AS RESTE, o.IDMERE AS IDOF
FROM 
	MVTSTOCKFILLERESIDUFAB mf
JOIN FABRICATION f ON f.ID = mf.IDFAB 
JOIN OFFILLE o ON f.IDOFFILLE = o.id
GROUP BY mf.IDPRODUIT, mf.IDPRODUITLIB,o.IDMERE
;
-- [523/1309] MVTSTOCKFILLETRANSFERT
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLETRANSFERT" ("IDTRANSFERTDETAIL","ENTREE","SORTIE") AS
SELECT 
m.idtransfertdetail,
CAST(sum(nvl(m.entree ,0)) AS NUMBER(30,5))  as entree,
CAST(sum(nvl(m.sortie ,0)) AS NUMBER(30,5)) as sortie
FROM mvtstockfillelib m
left JOIN mvtstock mv ON mv.id = m.idmvtstock
WHERE mv.etat >=11 
GROUP BY m.idtransfertdetail
;
-- [524/1309] MVTSTOCKFILLEVRAISOURCE
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLEVRAISOURCE" ("ID","IDMVTSTOCK","IDPRODUIT","IDVENTEDETAIL","IDTRANSFERTDETAIL","MVTSRC","SOURCE2","DESIGNATION","ENTREE","SORTIE","PU","RESTE","IDINVENTAIREFILLE") AS
select ms.ID, ms.IDMVTSTOCK, ms.IDPRODUIT, ms.IDVENTEDETAIL, ms.IDTRANSFERTDETAIL,
       case when  (me.MVTSRC is not null and ms.SORTIE>0)
           then me.MVTSRC
           else ms.MVTSRC
        end as mvtsrc
     ,me.MVTSRC as source2
     , ms.DESIGNATION, ms.ENTREE, ms.SORTIE, ms.PU, ms.RESTE, ms.IDINVENTAIREFILLE from MVTSTOCKFILLE ms left  join
(select m.id, m.idmvtstock, m.idproduit, m.idventedetail, m.idtransfertdetail, m.mvtsrc, m.designation, m.entree, m.sortie, m.pu, m.reste, m.idinventairefille
 from MVTSTOCKFILLE m
where m.entree>0 and m.MVTSRC is not null) me
on me.ID=ms.MVTSRC
left join MVTSTOCK m on m.id=ms.IDMVTSTOCK
where m.IDTYPEMVSTOCK!='TPMVST000023'
;
-- [525/1309] MVTSTOCKFILLE_ENG
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLE_ENG" ("ID","IDMVTSTOCK","IDPRODUIT","IDVENTEDETAIL","IDTRANSFERTDETAIL","MVTSRC","DESIGNATION","ENTREE","SORTIE","PU","RESTE") AS
select ID, IDMVTSTOCK, IDPRODUIT, IDVENTEDETAIL, IDTRANSFERTDETAIL, MVTSRC, DESIGNATION, ENTREE, SORTIE, PU, RESTE from MVTSTOCKFILLE
    union all
select ID, IDMVTSTOCK, IDPRODUIT, IDVENTEDETAIL, IDTRANSFERTDETAIL, MVTSRC, DESIGNATION, ENTREE, SORTIE, PU, RESTE from stock_engage_FILLE
;
-- [526/1309] MVTSTOCKLIB
CREATE OR REPLACE FORCE VIEW "MVTSTOCKLIB" ("ID","DESIGNATION","IDMAGASIN","IDOBJET","IDMAGASINLIB","IDVENTE","IDVENTELIB","IDTRANSFERT","IDTRANSFERTLIB","IDTYPEMVSTOCK","IDTYPEMVSTOCKLIB","DATY","ETAT","HEURE","ETATLIB","IDRESERVATION","MONTANTENTREE","MONTANTSORTIE","IDCATEGORIESTOCK","IDCATEGORIESTOCKLIB","MOTSCLESSS") AS
SELECT
m.ID ,
m.DESIGNATION ,
m.IDMAGASIN ,
m.IDOBJET ,
m2.VAL  AS idMagasinlib,
m.IDVENTE ,
v.DESIGNATION  AS idVentelib,
m.IDTRANSFERT ,
CAST('' AS VARCHAR2(255)) AS idTransfertlib,
m.IDTYPEMVSTOCK ,
t.VAL AS idTypeMvStocklib ,
m.DATY ,
m.ETAT ,
m.heure,
CASE
	WHEN m.ETAT = 0
	THEN 'ANNUL&Eacute;'
	WHEN m.ETAT = 1
	THEN 'CR&Eacute;&Eacute;'
	WHEN m.ETAT = 11
	THEN 'VALID&Eacute;'
END AS etatlib,
v.IDRESERVATION,
CAST(COALESCE(gm.montantEntree,0) AS NUMBER(30,5)) AS  montantEntree,
CAST(COALESCE(gm.montantSortie,0) AS NUMBER(30,5)) AS  montantSortie,
m.IDCATEGORIESTOCK,
cs.val as idCategorieStockLib,
m.ID || '' || m.DESIGNATION || '' || m.IDMAGASIN || '' || m2.VAL || '' || m.IDVENTE || '' || v.DESIGNATION || '' || t.VAL || '' || cs.val || '' || m.DATY AS MOTSCLESSS
FROM MVTSTOCK m
LEFT JOIN TYPEMVTSTOCK t ON t.ID = m.IDTYPEMVSTOCK
LEFT JOIN VENTE v ON v.ID = m.IDVENTE
LEFT JOIN MAGASIN2 m2 ON m2.ID = m.IDMAGASIN
left join mvtStockFilleGroupeMere gm on gm.IDMVTSTOCK=m.ID
LEFT JOIN categorieStock cs ON m.IDCATEGORIESTOCK = cs.id
;
-- [527/1309] MVTSTOCKLIBANNULER
CREATE OR REPLACE FORCE VIEW "MVTSTOCKLIBANNULER" ("ID","DESIGNATION","IDMAGASIN","IDOBJET","IDMAGASINLIB","IDVENTE","IDVENTELIB","IDTRANSFERT","IDTRANSFERTLIB","IDTYPEMVSTOCK","IDTYPEMVSTOCKLIB","DATY","ETAT","HEURE","ETATLIB","IDRESERVATION","MONTANTENTREE","MONTANTSORTIE","IDCATEGORIESTOCK","IDCATEGORIESTOCKLIB","MOTSCLESSS") AS
SELECT
    m.ID,
    m.DESIGNATION,
    m.IDMAGASIN,
    m.IDOBJET,
    m.IDMAGASINLIB,
    m.IDVENTE,
    m.IDVENTELIB,
    m.IDTRANSFERT,
    m.IDTRANSFERTLIB,
    m.IDTYPEMVSTOCK,
    m.IDTYPEMVSTOCKLIB,
    m.DATY,
    m.ETAT,
    m.HEURE,
    m.ETATLIB,
    m.IDRESERVATION,
    m.MONTANTENTREE,
    m.MONTANTSORTIE,
    m.IDCATEGORIESTOCK,
    m.IDCATEGORIESTOCKLIB,
    m.MOTSCLESSS
FROM MVTSTOCKLIB m
WHERE m.ETAT = 0
;
-- [528/1309] MVTSTOCKLIBCREER
CREATE OR REPLACE FORCE VIEW "MVTSTOCKLIBCREER" ("ID","DESIGNATION","IDMAGASIN","IDOBJET","IDMAGASINLIB","IDVENTE","IDVENTELIB","IDTRANSFERT","IDTRANSFERTLIB","IDTYPEMVSTOCK","IDTYPEMVSTOCKLIB","DATY","ETAT","HEURE","ETATLIB","IDRESERVATION","MONTANTENTREE","MONTANTSORTIE","IDCATEGORIESTOCK","IDCATEGORIESTOCKLIB","MOTSCLESSS") AS
SELECT
    m.ID,
    m.DESIGNATION,
    m.IDMAGASIN,
    m.IDOBJET,
    m.IDMAGASINLIB,
    m.IDVENTE,
    m.IDVENTELIB,
    m.IDTRANSFERT,
    m.IDTRANSFERTLIB,
    m.IDTYPEMVSTOCK,
    m.IDTYPEMVSTOCKLIB,
    m.DATY,
    m.ETAT,
    m.HEURE,
    m.ETATLIB,
    m.IDRESERVATION,
    m.MONTANTENTREE,
    m.MONTANTSORTIE,
    m.IDCATEGORIESTOCK,
    m.IDCATEGORIESTOCKLIB,
    m.MOTSCLESSS
FROM MVTSTOCKLIB m
