;
-- [529/1309] MVTSTOCKLIBFACTURE
CREATE OR REPLACE FORCE VIEW "MVTSTOCKLIBFACTURE" ("ID","DESIGNATION","IDMAGASIN","IDOBJET","IDMAGASINLIB","IDVENTE","IDVENTELIB","IDTRANSFERT","IDTRANSFERTLIB","IDTYPEMVSTOCK","IDTYPEMVSTOCKLIB","DATY","ETAT","HEURE","ETATLIB","IDRESERVATION","MONTANTENTREE","MONTANTSORTIE","IDCATEGORIESTOCK","IDCATEGORIESTOCKLIB","MOTSCLESSS","IDFACTUREFOURNISSEUR") AS
select m."ID",m."DESIGNATION",m."IDMAGASIN",m."IDOBJET",m."IDMAGASINLIB",m."IDVENTE",m."IDVENTELIB",m."IDTRANSFERT",m."IDTRANSFERTLIB",m."IDTYPEMVSTOCK",m."IDTYPEMVSTOCKLIB",m."DATY",m."ETAT",m."HEURE",m."ETATLIB",m."IDRESERVATION",m."MONTANTENTREE",m."MONTANTSORTIE",m."IDCATEGORIESTOCK",m."IDCATEGORIESTOCKLIB",m."MOTSCLESSS",
       f.id as IDFACTUREFOURNISSEUR
from MVTSTOCKlib m
         LEFT JOIN AS_BONDELIVRAISON ab ON ab.id = m.IDOBJET
         LEFT JOIN facturefournisseur f ON f.id = ab.IDFACTUREFOURNISSEUR
;
-- [530/1309] MVTSTOCKLIBVALIDER
CREATE OR REPLACE FORCE VIEW "MVTSTOCKLIBVALIDER" ("ID","DESIGNATION","IDMAGASIN","IDOBJET","IDMAGASINLIB","IDVENTE","IDVENTELIB","IDTRANSFERT","IDTRANSFERTLIB","IDTYPEMVSTOCK","IDTYPEMVSTOCKLIB","DATY","ETAT","HEURE","ETATLIB","IDRESERVATION","MONTANTENTREE","MONTANTSORTIE","IDCATEGORIESTOCK","IDCATEGORIESTOCKLIB","MOTSCLESSS") AS
SELECT
    m.ID,
    m.DESIGNATION,
    m.IDMAGASIN,
    m.IDOBJET,
    m.IDMAGASINLIB,
    m.IDVENTE,
    m.IDVENTELIB,
    m.IDTRANSFERT,
    m.IDTRANSFERTLIB,
    m.IDTYPEMVSTOCK,
    m.IDTYPEMVSTOCKLIB,
    m.DATY,
    m.ETAT,
    m.HEURE,
    m.ETATLIB,
    m.IDRESERVATION,
    m.MONTANTENTREE,
    m.MONTANTSORTIE,
    m.IDCATEGORIESTOCK,
    m.IDCATEGORIESTOCKLIB,
    m.MOTSCLESSS
FROM MVTSTOCKLIB m
WHERE m.ETAT >= 11
;
-- [531/1309] MVTSTOCKPRODUIT
CREATE OR REPLACE FORCE VIEW "MVTSTOCKPRODUIT" ("IDOBJET","IDINGREDIENT","IDINGREDIENTLIB","UNITE","IDOFFILLE","ENTREE","SORTIE","PU") AS
SELECT 
    m2.idobjet ,
    m.IDPRODUIT AS idingredient ,
    ai.LIBELLE AS idingredientlib,
    ai.UNITE,
    f.IDOFFILLE,
    sum(m.ENTREE) AS entree ,
    sum(m.SORTIE) AS sortie ,
    nvl(sum(m.pu),0) AS pu 
FROM 
    MVTSTOCKFILLE m
    LEFT JOIN MVTSTOCK m2 ON m2.id = m.IDMVTSTOCK
    LEFT JOIN AS_INGREDIENTS ai ON ai.id = m.idproduit
    LEFT JOIN FABRICATION f ON f.id = m2.idobjet
GROUP BY  m2.idobjet ,
    m.IDPRODUIT , ai.LIBELLE ,ai.UNITE , f.IDOFFILLE
;
-- [532/1309] FABRICATIONFILLEPRATIQUE
CREATE OR REPLACE FORCE VIEW "FABRICATIONFILLEPRATIQUE" ("IDINGREDIENTS","LIBINGREDIENTS","IDOFFILLE","QTE","PU","MONTANT","IDUNITE","IDUNITELIB") AS
SELECT 
    idingredient AS idingredients ,
    idingredientlib AS libIngredients,
    IDOFFILLE,
    (sortie - entree) AS qte,
    pu,
    (sortie - entree) * pu AS montant ,
    unite AS idunite ,
    au.val AS idunitelib
FROM 
    mvtstockproduit
    LEFT JOIN AS_UNITE au ON au.id = mvtstockproduit.unite
WHERE 
    (sortie - entree) > 0
;
-- [533/1309] MVTSTOCK_ENG
CREATE OR REPLACE FORCE VIEW "MVTSTOCK_ENG" ("ID","DESIGNATION","IDMAGASIN","IDVENTE","IDTRANSFERT","IDTYPEMVSTOCK","DATY","ETAT","IDPOINT","IDOBJET","FABPRECEDENT") AS
select ID, DESIGNATION, IDMAGASIN, IDVENTE, IDTRANSFERT, IDTYPEMVSTOCK, DATY, ETAT, IDPOINT, IDOBJET, FABPRECEDENT from MVTSTOCK
    union all
select ID, DESIGNATION, IDMAGASIN, IDVENTE, IDTRANSFERT, IDTYPEMVSTOCK, DATY, ETAT, IDPOINT, IDOBJET, FABPRECEDENT from stock_engage
;
-- [534/1309] MONTANT_STOCK_ENG
CREATE OR REPLACE FORCE VIEW "MONTANT_STOCK_ENG" ("IDPRODUIT","ENTREE","SORTIE","QUANTITE","MONTANTENTREE","MONTANTSORTIE","MONTANT","IDMAGASIN","IDMVTSTOCK") AS
SELECT
    mf.IDPRODUIT,
    SUM(NVL(mf.ENTREE,0)) AS ENTREE,
    SUM(NVL(mf.SORTIE,0)) AS SORTIE,
    SUM(NVL(mf.ENTREE,0)) - SUM(NVL(mf.SORTIE,0)) AS quantite,
    cast(sum(mf.montantEntree) as number(30,2))  AS montantEntree,
    cast(sum(mf.montantSortie) as number(30,2))  AS montantSortie,
    CAST(NVL(ai.PU, 0) * (SUM(NVL(mf.ENTREE,0)) - SUM(NVL(mf.SORTIE,0))) AS NUMBER(30,2)) AS montant,
    m.IDMAGASIN,
    MAX(mf.IDMVTSTOCK) AS IDMVTSTOCK
FROM
    mvtStockFilleMontant_eng mf
        JOIN MVTstock_eng m ON m.id = mf.IDMVTSTOCK
        JOIN AS_INGREDIENTS ai ON ai.ID = mf.IDPRODUIT
WHERE
    m.ETAT >= 11
  AND mf.IDPRODUIT IS NOT NULL
GROUP BY
    mf.IDPRODUIT,
    ai.PU,m.IDMAGASIN
;
-- [535/1309] MVTSTOCKFILLELIB_ENG
CREATE OR REPLACE FORCE VIEW "MVTSTOCKFILLELIB_ENG" ("ID","IDMVTSTOCK","IDPRODUIT","IDPRODUITLIB","ENTREE","SORTIE","IDVENTEDETAIL","IDVENTEDETAILLIB","IDTRANSFERTDETAIL","IDTRANSFERTDETAILLIB","DATY","IDMAGASIN","IDMAGASINLIB","PU","MONTANT","LIBELLE","MVTSRC","LIBELLEEXACTE") AS
SELECT
    m.ID ,
    m.IDMVTSTOCK ,
    m.IDPRODUIT ,
    p.libelle  AS IDPRODUITLIB,
    m.ENTREE ,
    m.SORTIE ,
    m.IDVENTEDETAIL ,
    '' AS IDVENTEDETAILLIB,
    m.IDTRANSFERTDETAIL ,
    '' AS IDTRANSFERTDETAILLIB,
    m2.DATY ,
    m2.IDMAGASIN ,
    m3.VAL AS IDMAGASINLIB,
    m.pu,
    cast(m.pu*m.ENTREE+(m.pu*m.sortie) as number(20,5)) as montant,
    p.LIBELLE,
    m.MVTSRC,
    p.libelle AS libelleexacte
FROM MVTSTOCKFILLE_ENG m
         LEFT JOIN AS_INGREDIENTS  p ON p.ID = m.IDPRODUIT
         LEFT JOIN MVTSTOCK_ENG m2 ON m2.ID = m.IDMVTSTOCK
         LEFT JOIN MAGASIN2 m3 ON m3.ID = m2.IDMAGASIN
;
-- [536/1309] NET_MOISANNEE
CREATE OR REPLACE FORCE VIEW "NET_MOISANNEE" ("MOIS","ANNEE","MONTANT") AS
SELECT pe.mois,
       pe.annee,
       CAST(sum(pe.gain) AS NUMBER(15,2)) AS montant
FROM paie_edition pe
WHERE pe.idelementpaie = 'PR000210A'
GROUP BY pe.mois, pe.annee
;
-- [537/1309] NOMBRE_PANNE_MACHINE
CREATE OR REPLACE FORCE VIEW "NOMBRE_PANNE_MACHINE" ("ID","IDENTITE","IDSITUATION","IDMACHINE","DATY","DATEBESOIN","PRIORITE","ESTEXISTANT","DESCRIPTION","ETAT","DEMANDEUR","CAUSE","IDDEPARTEMENT","IDDEPARTEMENTMAINTENANCE","IDMACHINELIB","QTE") AS
SELECT
    d."ID",
    d."IDENTITE",
    d."IDSITUATION",
    d."IDMACHINE",
    d."DATY",
    d."DATEBESOIN",
    d."PRIORITE",
    d."ESTEXISTANT",
    d."DESCRIPTION",
    d."ETAT",
    d."DEMANDEUR",
    d."CAUSE",
    d."IDDEPARTEMENT",
    d."IDDEPARTEMENTMAINTENANCE",
    ai.LIBELLE AS idMachineLib,

    COUNT(*) OVER (PARTITION BY d.IDMACHINE, d.DATY) AS qte

FROM DEMANDETRAVAUX d
         LEFT JOIN AS_INGREDIENT_MAINTENANCE m
                   ON d.IDMACHINE = m.ID
         LEFT JOIN AS_INGREDIENTS ai
                   ON m.IDINGREDIENT = ai.ID
;
-- [538/1309] NOTIFICATIONLIBCPLT
CREATE OR REPLACE FORCE VIEW "NOTIFICATIONLIBCPLT" ("ID","RECEIVER","RECEIVERLIB","MESSAGE","DATY","HEURE","ETAT","REF","REFLIB","ETATLIB","LIEN","ECARTDATE") AS
SELECT n.id,
       n.receiver,
       u.nomuser AS receiverlib,
       n.message,
       n.daty,
       n.heure,
       n.etat,
       n.ref,
       '' AS reflib,
       CASE
           WHEN n.etat = 11 THEN 'LU'
           WHEN n.etat = 1 THEN 'NON LU'
           ELSE NULL
           END AS etatlib,
       n.lien,
       CASE
           WHEN ( (SYSDATE - (TO_DATE(TO_CHAR(n.daty,'YYYY-MM-DD') || ' ' || n.heure, 'YYYY-MM-DD HH24:MI:SS'))) * 24 * 60 * 60 ) < 60
               THEN 'il y a moins d''une minute'
           WHEN ( (SYSDATE - (TO_DATE(TO_CHAR(n.daty,'YYYY-MM-DD') || ' ' || n.heure, 'YYYY-MM-DD HH24:MI:SS'))) * 24 * 60 * 60 ) < 3600
               THEN 'il y a ' || FLOOR(((SYSDATE - (TO_DATE(TO_CHAR(n.daty,'YYYY-MM-DD') || ' ' || n.heure, 'YYYY-MM-DD HH24:MI:SS'))) * 24 * 60)) || ' mn'
           WHEN ( (SYSDATE - (TO_DATE(TO_CHAR(n.daty,'YYYY-MM-DD') || ' ' || n.heure, 'YYYY-MM-DD HH24:MI:SS'))) * 24 * 60 * 60 ) < 86400
               THEN 'il y a ' || FLOOR(((SYSDATE - (TO_DATE(TO_CHAR(n.daty,'YYYY-MM-DD') || ' ' || n.heure, 'YYYY-MM-DD HH24:MI:SS'))) * 24)) || ' h'
           ELSE 'il y a ' || FLOOR((SYSDATE - (TO_DATE(TO_CHAR(n.daty,'YYYY-MM-DD') || ' ' || n.heure, 'YYYY-MM-DD HH24:MI:SS')))) || ' jrs'
           END AS ecartdate
FROM notification2 n
         LEFT JOIN utilisateur u ON u.refuser = n.receiver order by DATY desc
;
-- [539/1309] NOTIFICATIONLIBNONLU
CREATE OR REPLACE FORCE VIEW "NOTIFICATIONLIBNONLU" ("ID","RECEIVER","MESSAGE","DATY","HEURE","ETAT","REF","ETATLIB","RECEIVERLIB","LIEN","ECARTDATE","LIEN_HTML") AS
SELECT n.id,
       n.receiver,
       n.message,
       n.daty,
       n.heure,
       n.etat,
       n.ref,
       n.etatlib,
       n.receiverlib,
       n.lien,
       n.ecartdate,
       '<a href=XX?but=' || n.lien || '&id=' || n.ref || '>' || n.ref || '</a>' AS lien_html
FROM notificationlibcplt n
WHERE n.etat = 1
;
-- [540/1309] OBJECTIF_ANNUEL_LIB
CREATE OR REPLACE FORCE VIEW "OBJECTIF_ANNUEL_LIB" ("ID","IDPERSONNEL","TITRE","DATY","IDPERSONNELLIB","MATRICULE","IDFONCTION","IDFONCTIONLIB") AS
SELECT
    oa.ID,oa.IDPERSONNEL,oa.TITRE,oa.DATY,
    lp.NOM || ' ' || lp.PRENOM AS idPersonnelLib,
    pip.MATRICULE AS matricule,
    pip.IDFONCTION AS idFonction,
    pf.VAL AS idFonctionLib
FROM OBJECTIF_ANNUEL oa
-- Jointure pour les informations de base du personnel
         LEFT JOIN LOG_PERSONNEL lp
                   ON oa.IDPERSONNEL = lp.ID
-- Jointure pour recuperer l'ID Fonction depuis la paie
         LEFT JOIN PAIE_INFO_PERSONNEL pip
                   ON oa.IDPERSONNEL = pip.ID
-- Jointure pour recuperer le libelle de la fonction
         LEFT JOIN PAIE_FONCTION pf
                   ON pip.IDFONCTION = pf.ID
;
-- [541/1309] OFABLIB
CREATE OR REPLACE FORCE VIEW "OFABLIB" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","ETAT","LANCEUR","LANCEURLIB","ETATLIB","MOTSCLESSS") AS
SELECT OFL.ID,
       P1.VAL     AS LANCEPAR,
       P2.VAL     AS CIBLE,
       OFL.REMARQUE,
       OFL.LIBELLE,
       OFL.BESOIN,
       OFL.DATY,
       OFL.ETAT,
       OFL.LANCEUR,
       LP.NOMUSER AS LANCEURLIB,
       CASE
           WHEN OFL.ETAT = 1 THEN 'Cr&eacute;&eacute;'
           WHEN OFL.ETAT = 11 THEN 'Valid&eacute;'
           WHEN OFL.ETAT = 0 THEN 'Annul&eacute;'
           WHEN OFL.ETAT = 21 THEN 'Entam&eacute;'
           WHEN OFL.ETAT = 31 THEN 'Bloqu&eacute;'
           WHEN OFL.ETAT = 41 THEN 'Termin&eacute;'
           END    AS ETATLIB,
       (
           OFL.id || ' | ' || libelle || ' | ' ||  besoin || ' | ' || LP.NOMUSER || ' | ' || ' | ' || P2.VAL || ' | ' ||  remarque
           )      AS MOTSCLESSS
FROM OFAB OFL
         LEFT JOIN MAGASINPOINT P1 ON P1.ID = OFL.LANCEPAR
         LEFT JOIN MAGASINPOINT P2 ON P2.ID = OFL.CIBLE
         LEFT JOIN UTILISATEUR LP ON LP.REFUSER = OFL.LANCEUR
;
-- [542/1309] OFFILLEEQUIVALENCE
CREATE OR REPLACE FORCE VIEW "OFFILLEEQUIVALENCE" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","IDBCFILLE","EQUIVALENCE") AS
select o."ID",o."IDINGREDIENTS",o."LIBELLE",o."REMARQUE",o."IDMERE",o."DATYBESOIN",o."QTE",o."IDUNITE",o."IDBCFILLE",cast(nvl(e.QTE,1) as number(20,2)) as equivalence from OFFILLE o left join EQUIVALENCE e on o.IDINGREDIENTS=e.IDPRODUIT and o.IDUNITE=e.IDUNITE
;
-- [543/1309] OFFILLELIB
CREATE OR REPLACE FORCE VIEW "OFFILLELIB" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","QTEFABRIQUE","QTERESTE","LIBELLEEXACTE") AS
SELECT
	ofll.ID,
	ofll.IDINGREDIENTS,
	nvl(ofll.LIBELLE,ai.LIBELLE)  AS LIBELLE,
	ofll.REMARQUE,
	ofll.IDMERE,
	ofll.DATYBESOIN,
	ofll.QTE,
	nvl(au.VAL, 'unite') AS IDUNITE,
	fmf.qte AS qteFabrique,
	(ofll.qte-nvl(fmf.qte, 0)) AS qteReste,
	nvl(ofll.LIBELLE,nvl(ai.LIBELLEEXTACTE, ai.LIBELLE)) AS libelleexacte
FROM
	OFFILLE ofll
LEFT JOIN AS_INGREDIENTS ai ON
	ai.ID = ofll.IDINGREDIENTS
LEFT JOIN AS_UNITE au ON
	au.ID = ofll.IDUNITE
LEFT JOIN FabricationMereFille fmf ON
	fmf.IDOFFILLE = ofll.ID
	AND fmf.IDINGREDIENTS = ofll.IDINGREDIENTS
	AND fmf.IDBCFILLE = OFLL.IDBCFILLE
;
-- [544/1309] OFFILLELIBQTERESTE
CREATE OR REPLACE FORCE VIEW "OFFILLELIBQTERESTE" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","QTEFABRIQUE","QTERESTE","LIBELLEMERE","DATY","IDBCFILLE") AS
SELECT
	ofll.ID,
	ofll.IDINGREDIENTS,
	ai.LIBELLE ||' '|| ofll.LIBELLE as LIBELLE,
	ai.LIBELLE as remarque,
	ofll.IDMERE,
	ofll.DATYBESOIN,
	(ofll.qte-nvl(fmf.qte,0)) as QTE,
	nvl(au.ID,'UNT00005') AS IDUNITE,
-- 	au.id as lele,
	fmf.qte AS qteFabrique,(ofll.qte-fmf.qte) AS qteReste,
	ofa.LIBELLE as libelleMere,fmf.daty,
	ofll.IDBCFILLE

FROM OFFILLE ofll
	LEFT JOIN AS_INGREDIENTS ai ON ai.ID = ofll.IDINGREDIENTS
	LEFT JOIN AS_UNITE au ON au.ID = ofll.IDUNITE
    LEFT JOIN FabricationMereFille fmf on fmf.IDOF=ofll.IDMERE and fmf.IDINGREDIENTS=ofll.IDINGREDIENTS
left join OFAB ofa on ofa.id=ofll.IDMERE
;
-- [545/1309] OFFILLELIBSTOCK
CREATE OR REPLACE FORCE VIEW "OFFILLELIBSTOCK" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","QTEFABRIQUE","QTERESTE","LIBELLEEXACTE","PV","MONTANTENTREE","MONTANTSORTIE","POURC","MOTSCLESSS","DATY") AS
SELECT SQ.ID,
       SQ.IDINGREDIENTS,
       SQ.LIBELLE,
       SQ.REMARQUE,
       SQ.IDMERE,
       SQ.DATYBESOIN,
       SQ.QTE,
       SQ.IDUNITE,
       SQ.QTEFABRIQUE,
       SQ.QTERESTE,
       SQ.LIBELLEEXACTE,
       SQ.PV,
       SQ.MONTANTENTREE,
       SQ.MONTANTSORTIE,
       SQ.POURC,
       (
           ID || ' | ' || IDINGREDIENTS || ' | ' || LIBELLEEXACTE || ' | ' || IDUNITE
           ) AS MOTSCLESSS,
       SQ.DATY
FROM (SELECT OFLL.ID,
             OFLL.IDINGREDIENTS,
             NVL(OFLL.LIBELLE, AI.LIBELLE)                         AS LIBELLE,
             OFLL.REMARQUE,
             OFLL.IDMERE,
             OB.DATY                                               AS DATYBESOIN,
             OFLL.QTE,
             NVL(AU.VAL, 'unite')                                  AS IDUNITE,
             CAST(NVL(MV.ENTREE, 0) AS NUMBER(30, 5))              AS QTEFABRIQUE,
             CAST(OFLL.QTE - NVL(MV.ENTREE, 0) AS NUMBER(30, 5))   AS QTERESTE,
             NVL(OFLL.LIBELLE, NVL(AI.LIBELLEEXTACTE, AI.LIBELLE)) AS LIBELLEEXACTE,
             CAST(OFLL.PRIXVENTE AS NUMBER(30, 5))                 AS PV,
             CAST(NVL(MV.ENTREE, 0) * AI.PV AS NUMBER(30, 5))      AS MONTANTENTREE,
             CAST(NVL(MVT.MONTANTSORTIE, 0) AS NUMBER(30, 5))      AS MONTANTSORTIE,
             CASE
                 WHEN NVL(MV.ENTREE, 0) = 0 OR AI.PV = 0 THEN 0
                 ELSE (1 - (MVT.MONTANTSORTIE / (NVL(MV.ENTREE, 0) * AI.PV))) * 100
                 END                                               AS POURC,
             OB.DATY                                               AS DATY
      FROM OFFILLE OFLL
               LEFT JOIN AS_INGREDIENTS AI ON AI.ID = OFLL.IDINGREDIENTS
               LEFT JOIN AS_UNITE AU ON AU.ID = OFLL.IDUNITE
               LEFT JOIN MVTSTFILLEOFFCATVISEGROUPEDEP MVT ON OFLL.ID = MVT.IDOFF
               LEFT JOIN MVTSTOCKFILLEOFENTREEPRFINI MV
                         ON MV.IDOFF = OFLL.ID
                             AND MV.IDPRODUIT = OFLL.IDINGREDIENTS
               LEFT JOIN OFAB OB ON OB.ID = OFLL.IDMERE) SQ
;
-- [546/1309] COUT_FAB_PAR_OF
CREATE OR REPLACE FORCE VIEW "COUT_FAB_PAR_OF" ("IDMERE","DATYBESOIN","INGREDIENTS","COUTDEPRODUCTION") AS
SELECT 
    base.IDMERE,
    base.DATYBESOIN,
    base.IDINGREDIENTS AS INGREDIENTS,
    ROUND(
        SUM(
            CASE 
                WHEN base.QTEFABRIQUE = 0 OR base.QTEFABRIQUE IS NULL THEN 0
                ELSE base.MONTANTSORTIE / base.QTEFABRIQUE
            END
        ) , 2
    ) / 1000000 AS COUTDEPRODUCTION
FROM 
    OFFILLELIBSTOCK base
    JOIN OFAB fb ON fb.id = base.idmere AND fb.etat >= 11
GROUP BY 
    base.IDMERE,
    base.DATYBESOIN,
    base.IDINGREDIENTS
ORDER BY 
    base.IDMERE
;
-- [547/1309] COUT_FAB_PAR_OF_TEMP
CREATE OR REPLACE FORCE VIEW "COUT_FAB_PAR_OF_TEMP" ("IDMERE","DATYBESOIN","INGREDIENTS","COUTDEPRODUCTION","MOTSCLESSS") AS
SELECT SQ.IDMERE,SQ.DATYBESOIN,SQ.INGREDIENTS,CAST(SQ.COUTDEPRODUCTION AS NUMBER(30,5)) AS COUTDEPRODUCTION ,
	  (NVL(TO_CHAR(IDMERE),'') || ' | ' || NVL(TO_CHAR(DATYBESOIN,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(INGREDIENTS),'') || ' | ' || NVL(TO_CHAR(COUTDEPRODUCTION),'')) AS MOTSCLESSS
	FROM (
	  SELECT 
	    base.IDMERE,
	    base.DATYBESOIN,
	    base.IDINGREDIENTS AS INGREDIENTS,
	    ROUND(
	        SUM(montantsortie) , 2
	    )  AS COUTDEPRODUCTION
	FROM 
	    OFFILLELIBSTOCK base
	    JOIN OFAB fb ON fb.id = base.idmere AND fb.etat >= 11
	GROUP BY 
	    base.IDMERE,
	    base.DATYBESOIN,
	    base.IDINGREDIENTS
	ORDER BY 
	    base.IDMERE
	 
	) SQ
;
-- [548/1309] OFFILLELIBSTOCKIA
CREATE OR REPLACE FORCE VIEW "OFFILLELIBSTOCKIA" ("ID","IDPRODUIT","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","QTEFABRIQUE","QTERESTE","LIBELLEEXACTE","PV","MONTANTENTREE","MONTANTSORTIE","POURC","IDPRODUITLIB","MOTSCLESSS","DATY") AS
SELECT SQ.ID,SQ.IDPRODUIT,SQ.LIBELLE,SQ.REMARQUE,SQ.IDMERE,SQ.DATYBESOIN,SQ.QTE,SQ.IDUNITE,SQ.QTEFABRIQUE,SQ.QTERESTE,SQ.LIBELLEEXACTE,SQ.PV,SQ.MONTANTENTREE,SQ.MONTANTSORTIE,SQ.POURC, SQ.IDPRODUITLIB,
       (NVL(TO_CHAR("ID"),'') || ' | ' || NVL(TO_CHAR(IDPRODUIT),'') || ' | ' || NVL(TO_CHAR(LIBELLE),'') || ' | ' || NVL(TO_CHAR(REMARQUE),'') || ' | ' || NVL(TO_CHAR(IDMERE),'') || ' | ' || NVL(TO_CHAR(DATYBESOIN,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(QTE),'') || ' | ' || NVL(TO_CHAR(IDUNITE),'') || ' | ' || NVL(TO_CHAR(QTEFABRIQUE),'') || ' | ' || NVL(TO_CHAR(QTERESTE),'') || ' | ' || NVL(TO_CHAR(LIBELLEEXACTE),'') || ' | ' || NVL(TO_CHAR(PV),'') || ' | ' || NVL(TO_CHAR(MONTANTENTREE),'') || ' | ' || NVL(TO_CHAR(MONTANTSORTIE),'') || ' | ' || NVL(TO_CHAR(POURC),'')) AS MOTSCLESSS,daty
FROM (
         SELECT
             ofll.ID,
             ofll.IDINGREDIENTS AS IDPRODUIT,
             nvl(ofll.LIBELLE,ai.LIBELLE)  AS LIBELLE,
             ofll.REMARQUE,
             ofll.IDMERE,
             ob.daty AS  DATYBESOIN,
             ofll.QTE,
             nvl(au.VAL, 'unite') AS IDUNITE,
             cast(nvl(mv.entree,0) as number(30,5)) as qteFabrique,
             cast(ofll.QTE-nvl(mv.ENTREE,0)as number(30,5)) as qteReste,
             nvl(ofll.LIBELLE,nvl(ai.LIBELLEEXTACTE, ai.LIBELLE)) AS libelleexacte,
             ai.pv,
             cast(nvl(mv.ENTREE,0)*ai.pv as number(30,2)) as montantEntree,
             cast(nvl(mvt.montantSortie,0) as number(30,5)) as montantSortie,
             CASE
                 WHEN (nvl(mv.ENTREE,0)=0 or ai.pv=0) THEN 0
                 ELSE (1-(mvt.montantSortie/(nvl(mv.ENTREE,0)*ai.pv)))*100
                 END AS pourc,
             ob.daty,
             ai.libelle AS IDPRODUITLIB
         FROM
             OFFILLE ofll
                 LEFT JOIN AS_INGREDIENTS ai ON
                 ai.ID = ofll.IDINGREDIENTS
                 LEFT JOIN AS_UNITE au ON
                 au.ID = ofll.IDUNITE
                 left join MVTSTFILLEOFFCATVISEGROUPEDEP mvt on ofll.id=mvt.IDOFf
                 left join mvtStockFilleOfEntreePrFini mv on mv.idoff=ofll.id and mv.IDPRODUIT=ofll.IDINGREDIENTS
                 LEFT JOIN OFAB ob ON ob.id =  ofll.idmere

     ) SQ
;
-- [549/1309] OFFILLERESTELIB
CREATE OR REPLACE FORCE VIEW "OFFILLERESTELIB" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","QTEFABRIQUE","QTERESTE") AS
SELECT o."ID",o."IDINGREDIENTS",o."LIBELLE",o."REMARQUE",o."IDMERE",o."DATYBESOIN",o."QTE",o."IDUNITE",fmf.qte AS qteFabrique,(o.qte-fmf.qte) AS qteReste FROM FabricationMereFille fmf JOIN OfFilleLib o ON fmf.idof=o.IDMERE  AND fmf.IDINGREDIENTS=o.IDINGREDIENTS
;
-- [550/1309] OFFILLESTOCK_RECAP_JOUR
CREATE OR REPLACE FORCE VIEW "OFFILLESTOCK_RECAP_JOUR" ("DATY","NOMBRE","QTE","QTEFABRIQUE","QTERESTE") AS
SELECT
    TRUNC(DATY) AS DATY,
    COUNT(*) AS NOMBRE,
    CAST(SUM(NVL(QTE, 0)) AS NUMBER(30,5)) AS QTE,
    CAST(SUM(NVL(QTEFABRIQUE, 0)) AS NUMBER(30,5)) AS QTEFABRIQUE,
    CAST(SUM(NVL(QTERESTE, 0)) AS NUMBER(30,5)) AS QTERESTE
FROM OFFILLELIBSTOCK
GROUP BY TRUNC(DATY)
;
-- [551/1309] OFFRE_EMPLOILIB
CREATE OR REPLACE FORCE VIEW "OFFRE_EMPLOILIB" ("ID","IDFICHEPOSTE","IDFICHEPOSTELIB","TITRE","DESCRIPTION","MISSION","EXIGENCEPOSTE","IDTYPECONTRAT","IDTYPECONTRATLIB","SALAIREMIN","SALAIREMAX","ETAT","DATEPUBLICATION","DATEFERMETURE","ETATLIB") AS
SELECT 
    o.id,
    o.idFichePoste,
    fp.titre AS idFichePostelib,
    o.titre,
    o.description,
    o.mission,
    o.exigencePoste,
    o.idTypeContrat,
    tc.val AS idTypeContratlib,
    o.salaireMin,
    o.salaireMax,
    o.etat,
    o.datePublication,
    o.dateFermeture,
     CASE
           WHEN o.ETAT = 1 THEN 'Cr&eacute;e'
           WHEN o.ETAT = 11 THEN 'Vis&eacute;e'
           WHEN o.ETAT = 0 THEN 'ANNUL&eacute;E'
           END
            AS ETATLIB

FROM offre_emploi o

LEFT JOIN type_contrat tc 
    ON o.idTypeContrat = tc.id

LEFT JOIN fiche_poste fp 
    ON o.idFichePoste = fp.id
;
-- [552/1309] OFGROUPBYIDBC
CREATE OR REPLACE FORCE VIEW "OFGROUPBYIDBC" ("IDBCFILLE","QTE") AS
SELECT 
    f.IDBCFILLE,
    SUM(f.QTE) AS qte
FROM OFFILLE f
LEFT JOIN OFAB m ON m.ID = f.IDMERE
WHERE m.ETAT >= 11
GROUP BY f.IDBCFILLE
;
-- [553/1309] BONDECOMMANDE_CLIENT_FILLE_CPL
CREATE OR REPLACE FORCE VIEW "BONDECOMMANDE_CLIENT_FILLE_CPL" ("ID","IDBC","IDDEVISE","MONTANT","PRODUIT","PU","QUANTITE","REMISE","TVA","UNITE","QTEOF","QTEOFRESTANTE","QTEFAB","QTEFABRESTANTE","QTELIVRE","QTENONLIVRE","LIBELLEPRODUIT","ETAT","DATY","IDCLIENT","MOTSCLESSS") AS
SELECT SQ."ID",SQ."IDBC",SQ."IDDEVISE",SQ."MONTANT",SQ."PRODUIT",SQ."PU",SQ."QUANTITE",SQ."REMISE",SQ."TVA",SQ."UNITE",SQ."QTEOF",SQ."QTEOFRESTANTE",SQ."QTEFAB",SQ."QTEFABRESTANTE",SQ."QTELIVRE",SQ."QTENONLIVRE",SQ."LIBELLEPRODUIT",SQ."ETAT",SQ."DATY",SQ."IDCLIENT",
       (NVL(TO_CHAR("ID"),'') || ' | ' || NVL(TO_CHAR(IDBC),'') || ' | ' || NVL(TO_CHAR(IDDEVISE),'') || ' | ' || NVL(TO_CHAR(MONTANT),'') || ' | ' || NVL(TO_CHAR(PRODUIT),'') || ' | ' || NVL(TO_CHAR(PU),'') || ' | ' || NVL(TO_CHAR(QUANTITE),'') || ' | ' || NVL(TO_CHAR(REMISE),'') || ' | ' || NVL(TO_CHAR(TVA),'') || ' | ' || NVL(TO_CHAR(UNITE),'') || ' | ' || NVL(TO_CHAR(QTEOF),'') || ' | ' || NVL(TO_CHAR(QTEOFRESTANTE),'') || ' | ' || NVL(TO_CHAR(QTEFAB),'') || ' | ' || NVL(TO_CHAR(QTEFABRESTANTE),'') || ' | ' || NVL(TO_CHAR(QTELIVRE),'') || ' | ' || NVL(TO_CHAR(QTENONLIVRE),'') || ' | ' || NVL(TO_CHAR(LIBELLEPRODUIT),'')) AS MOTSCLESSS
FROM (
         SELECT
             bcf.id,
             bcf.IDBC,
             bcf.IDDEVISE,
             avg(bcf.MONTANT) as montant,
             bcf.PRODUIT,
             avg(bcf.PU) as pu,
             avg(bcf.QUANTITE) as quantite,
             avg(bcf.REMISE) as remise,
             avg(bcf.TVA) as tva,
             ing.UNITE as unite,

             nvl(avg(o.QTE),0) AS QTEOF,
             NVL(sum(bcf.QUANTITE) - nvl(avg(o.QTE),0), 0) AS QTEOFRESTANTE,

             nvl(avg(f.QTE),0) AS QTEFAB,
             NVL(sum(bcf.QUANTITE) - nvl(avg(f.QTE),0), 0) AS QTEFABRESTANTE,

             AVG(NVL(abcf.QUANTITE, 0)) AS QTELIVRE,
             NVL(avg(bcf.QUANTITE) - AVG(NVL(abcf.QUANTITE,0)), 0) AS QTENONLIVRE,
             ing.LIBELLE as libelleProduit,
             bccli.ETAT,
             bccli.daty,
             bccli.idclient

         FROM BONDECOMMANDE_CLIENT_FILLE bcf



                  LEFT JOIN BONDECOMMANDE_CLIENT bccli ON bccli.id = bcf.IDBC
                  LEFT JOIN OfGroupByIdbc o ON o.IDBCFILLE = bcf.ID


                  LEFT JOIN fabrGroupByIdbc f ON f.IDBCFILLE = bcf.ID

                  LEFT JOIN BLGroupByIdbc abcf ON abcf.IDBC_FILLE = bcf.ID

                  left join AS_INGREDIENTS ing on ing.id=bcf.PRODUIT

         GROUP BY
             bcf.IDBC,
             bcf.id,
             bcf.IDDEVISE,
             bcf.PRODUIT,
             ing.LIBELLE, ing.UNITE,
             bccli.ETAT,
             bccli.DATY,
             bccli.idclient
     ) SQ
;
-- [554/1309] BC_CLIENT_FILLE_CPL_LIB_VISEE
CREATE OR REPLACE FORCE VIEW "BC_CLIENT_FILLE_CPL_LIB_VISEE" ("ID","IDBC","IDDEVISE","MONTANT","PRODUIT","PU","QUANTITE","REMISE","TVA","UNITE","QTEOF","QTEOFRESTANTE","QTEFAB","QTEFABRESTANTE","QTELIVRE","QTENONLIVRE","LIBELLEPRODUIT","PRODUITLIB") AS
select bc."ID",bc."IDBC",bc."IDDEVISE",bc."MONTANT",bc."PRODUIT",bc."PU",bc."QUANTITE",bc."REMISE",bc."TVA",bc."UNITE",bc."QTEOF",bc."QTEOFRESTANTE",bc."QTEFAB",bc."QTEFABRESTANTE",bc."QTELIVRE",bc."QTENONLIVRE",bc."LIBELLEPRODUIT",i.LIBELLE as produitlib
from BONDECOMMANDE_CLIENT_FILLE_CPL bc
join AS_INGREDIENTS i
on i.ID = bc.PRODUIT
JOIN BONDECOMMANDE_CLIENT mere
on mere.ID = bc.IDBC
where ETAT >=11
;
-- [555/1309] OFNONRATTACHE
CREATE OR REPLACE FORCE VIEW "OFNONRATTACHE" ("IDOFFILLE","DATY","IDPRODUIT","IDPRODUITLIB","QTE","QTEPETRI","IDLIGNE","LIGNE","LANCEPAR") AS
SELECT
        offille.id AS idoffille,
        o.daty AS daty,
        offille.IDINGREDIENTS AS idproduit,
        ai.LIBELLE AS idproduitLib,
        offille.qte AS qte,
       (offille.qte/e.NBCARTON) AS qtepetri,
        l.id AS idligne,
        l.VAL AS ligne,
        o.lancepar
        FROM ofab o
LEFT join offille offille ON o.id=offille.idmere
LEFT JOIN AS_INGREDIENTS ai ON ai.id=offille.IDINGREDIENTS
LEFT JOIN TYPE_PRODUIT tp ON tp.ID = ai.typeproduit 
LEFT JOIN LIGNE l ON l.id=tp.IDLIGNE 
LEFT JOIN EQUIVALENCECARTON e ON e.IDCARTON = offille.IDINGREDIENTS 
WHERE o.etat = 11
;
-- [556/1309] OFNONRATTACHEREEL
CREATE OR REPLACE FORCE VIEW "OFNONRATTACHEREEL" ("IDOFFILLE","DATY","IDPRODUIT","IDPRODUITLIB","QTE","QTEPETRI","IDLIGNE","LIGNE","LANCEPAR") AS
SELECT
        offille.id AS idoffille,
        o.daty AS daty,
        offille.IDINGREDIENTS AS idproduit,
        ai.LIBELLE AS idproduitLib,
        offille.qtefabrique as qte,
        (offille.qtefabrique/e.NBCARTON) AS qtepetri,
        l.id AS idligne,
        l.VAL AS ligne,
        o.lancepar
        FROM ofab o
LEFT join OfFilleLibStock offille ON o.id=offille.idmere
LEFT JOIN AS_INGREDIENTS ai ON ai.id=offille.IDINGREDIENTS
LEFT JOIN TYPE_PRODUIT tp ON tp.ID = ai.typeproduit 
LEFT JOIN LIGNE l ON l.id=tp.IDLIGNE 
LEFT JOIN EQUIVALENCECARTON e ON e.IDCARTON = offille.IDINGREDIENTS
WHERE o.etat = 11
;
-- [557/1309] OFRATTACHE
CREATE OR REPLACE FORCE VIEW "OFRATTACHE" ("ID","IDOFFILLE","DATY","IDPRODUIT","IDPRODUITLIB","QTE","QTEPETRI","IDLIGNE","LIGNE","IDRELEVE","POURCENTAGE") AS
SELECT 
  r.ID,
    ofn.IDOFFILLE,
    ofn.DATY,
    ofn.IDPRODUIT,
    ofn.IDPRODUITLIB,
    ofn.QTE,
    ofn.QTEPETRI,
    ofn.IDLIGNE,
    ofn.LIGNE,
    r.IDRELEVE,
    -- Pourcentage de QTEPETRI par IDRELEVE
    CAST((ofn.QTEPETRI / SUM(ofn.QTEPETRI) OVER (PARTITION BY r.IDRELEVE)) * 100 AS NUMBER(30,2) ) AS POURCENTAGE
FROM ofnonrattachereel ofn
JOIN RELEVEFAB r 
    ON r.IDFAB = ofn.IDOFFILLE
;
-- [558/1309] ONBOARDING_MERE_LIB
CREATE OR REPLACE FORCE VIEW "ONBOARDING_MERE_LIB" ("ID","NOM","DESCRIPTION","IDFONCTION","IDFONCTIONLIB") AS
SELECT
    m.ID,m.NOM,m.DESCRIPTION,m.IDFONCTION,
    f.val AS idFonctionLib
FROM
    ONBOARDING_MERE m
        LEFT JOIN
    PAIE_FONCTION f ON m.idFonction = f.id
;
-- [559/1309] ONBOARDING_MERE_TC
CREATE OR REPLACE FORCE VIEW "ONBOARDING_MERE_TC" ("ID","NOM","DESCRIPTION","IDFONCTION") AS
SELECT ID,NOM,DESCRIPTION,IDFONCTION
FROM ONBOARDING_MERE
WHERE IDFONCTION IS NULL
;
-- [560/1309] ORDRETRAVAUXCPL
CREATE OR REPLACE FORCE VIEW "ORDRETRAVAUXCPL" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","ETAT","IDBC","TYPEMAINTENANCE") AS
(
	SELECT
		o.ID,o.LANCEPAR,o.CIBLE,o.REMARQUE,o.LIBELLE,o.BESOIN,o.DATY,o.ETAT,o.IDBC,
		p.idtypemaintenance AS typemaintenance
	FROM ORDRETRAVAUX o
	LEFT JOIN DEMANDETRAVAUX d ON d.id=o.idbc
	LEFT JOIN PLANNING p ON p.id=d.idplanning
)
;
-- [561/1309] OTRAVFILLELIBSTOCK
CREATE OR REPLACE FORCE VIEW "OTRAVFILLELIBSTOCK" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","QTEFABRIQUE","QTERESTE","LIBELLEEXACTE","PV","MONTANTENTREE","MONTANTSORTIE","POURC") AS
SELECT
    ofll.ID,
    ofll.IDINGREDIENTS,
    nvl(ofll.LIBELLE,ai.LIBELLE)  AS LIBELLE,
    ofll.REMARQUE,
    ofll.IDMERE,
    ob.daty AS  DATYBESOIN,
    ofll.QTE,
    nvl(au.VAL, 'unite') AS IDUNITE,
    cast(nvl(mv.entree,0) as number(30,2)) as qteFabrique,
    cast(ofll.QTE-nvl(mv.ENTREE,0)as number(30,2)) as qteReste,
    nvl(ofll.LIBELLE,nvl(ai.LIBELLE, ai.LIBELLE)) AS libelleexacte,
    0 AS pv,
    cast(0 as number(30,2)) as montantEntree,
    mvt.montantSortie,
    0 AS pourc
FROM
    ORDRETRAVAUXFILLE ofll
        LEFT JOIN AS_INGREDIENT_MAINTENANCE ai ON
        ai.ID = ofll.IDINGREDIENTS
        LEFT JOIN AS_UNITE au ON
        au.ID = ofll.IDUNITE
        left join MVTSTFILLEOFFCATVISEGROUPEDEP mvt on ofll.id=mvt.IDOFf
        left join mvtStockFilleOfEntreePrFini mv on mv.idoff=ofll.id and mv.IDPRODUIT=ofll.IDINGREDIENTS
        LEFT JOIN OFAB ob ON ob.id =  ofll.idmere
;
-- [562/1309] OTRAVLIB
CREATE OR REPLACE FORCE VIEW "OTRAVLIB" ("ID","IDBC","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","ETAT","ETATLIB") AS
SELECT ofl.ID,
       ofl.IDBC,
       p1.VAL  AS LANCEPAR,
       p2.VAL  AS CIBLE,
       ofl.REMARQUE,
       ofl.LIBELLE,
       ofl.BESOIN,
       ofl.DATY,
       ofl.ETAT,
       CASE
           WHEN ofl.ETAT=1
               THEN 'CREE'
           WHEN ofl.ETAT=11
               THEN 'VALIDE'
           WHEN ofl.ETAT=0
               THEN 'ANNULE'
           WHEN ofl.ETAT=21
               THEN 'ENTAME'
           WHEN ofl.ETAT=31
               THEN 'BLOQUE'
           WHEN ofl.ETAT=41
               THEN 'TERMINE'
           END AS ETATLIB
FROM ORDRETRAVAUX ofl
         LEFT JOIN ENTITE p1 ON p1.ID = ofl.LANCEPAR
         LEFT JOIN MAGASIN p2 ON p2.ID = ofl.CIBLE
;
-- [563/1309] PACKINGLISTACHATFILLELIB
CREATE OR REPLACE FORCE VIEW "PACKINGLISTACHATFILLELIB" ("ID","IDMERE","IDPRODUIT","DESIGNATION","QTE","IDPRODUITLIB") AS
SELECT
    p.ID,
    p.IDMERE,
    p.IDPRODUIT,
    p.DESIGNATION,
    p.QTE,
    ai.LIBELLE as idproduitlib
FROM PACKINGLISTACHATFILLE p
LEFT JOIN AS_INGREDIENTS ai on ai.id = p.IDPRODUIT
;
-- [564/1309] PACKINGLISTACHATFILLEUNITE
CREATE OR REPLACE FORCE VIEW "PACKINGLISTACHATFILLEUNITE" ("ID","IDMERE","IDPRODUIT","DESIGNATION","QTE","IDUNITELIB") AS
(
select pl."ID",pl."IDMERE",pl."IDPRODUIT",pl."DESIGNATION",pl."QTE", u.val as idUniteLib
from PACKINGLISTACHATFILLE pl
         left join as_ingredients as_i on as_i.ID = pl.IDPRODUIT
         left join AS_UNITE u on u.ID = as_i.UNITE
    )
;
-- [565/1309] PACKINGLISTACHATLIB
CREATE OR REPLACE FORCE VIEW "PACKINGLISTACHATLIB" ("ID","IDBR","DATY","ETAT","ETATLIB") AS
SELECT p.ID,
       p.IDBR,
       p.DATY,
       p.ETAT,
       case
           when p.etat = 1 then 'CREEE'
           when p.etat = 11 then 'VISEE'
       end as etatlib
FROM PACKINGLISTACHAT p
;
-- [566/1309] PAIEPERS_ELP_CPL
CREATE OR REPLACE FORCE VIEW "PAIEPERS_ELP_CPL" ("ID","MATRICULE","ID_CODE_RUBRIQUE","NOMRUBRIQUE","DATE_DEBUT","DATE_FIN","GAIN","RETENUE","REMARQUE","NOMPERSONNEL","ETAT","ID_OBJET","IDUSER","MOISREGULARISATION","ANNEEREGULARISATION","IDCATEGORIE_QUALIFICATION","IDFONCTION","POURCENTAGE","IDPERSONNEL","ETATLIB") AS
SELECT
    ppe.id,
    pip2.matricule,
    pr.id as id_code_rubrique,
    pr.val AS nomRubrique,
    ppe.date_debut,
    ppe.date_fin,
    ppe.gain,
    ppe.retenue,
    ppe.remarque,
    pip.nom || ' ' || pip.prenom AS nomPersonnel,
    ppe.etat,
    ppe.id_objet,
    ppe.iduser,
    ppe.moisregularisation,
    ppe.anneeregularisation,
    cq.idcategorielib || ' ' || cq.categorie_qualificationlib AS idcategorie_qualification,
    pf.desce AS idfonction,
    ppe.pourcentage,
    ppe.idpersonnel,
    CASE
        WHEN ppe.etat = 1 THEN 'CREE'
        WHEN ppe.etat = 11 THEN 'VISEE'
        ELSE 'INCONNU'
        END AS etatLib
FROM paie_personnel_elementpaie ppe
         LEFT JOIN log_personnel pip ON TO_CHAR(pip.id) = TO_CHAR(ppe.idpersonnel)
         LEFT JOIN categorie_qualification_libc cq ON TO_CHAR(ppe.idcategorie_qualification) = TO_CHAR(cq.id)
         LEFT JOIN paie_fonction pf ON TO_CHAR(ppe.idfonction) = TO_CHAR(pf.id)
         LEFT JOIN paie_rubrique pr ON TO_CHAR(pr.id) = TO_CHAR(ppe.code_rubrique)
         JOIN paie_info_personnel pip2 ON TO_CHAR(pip.id) = TO_CHAR(pip2.id)
;
-- [567/1309] HS_GROUPE
CREATE OR REPLACE FORCE VIEW "HS_GROUPE" ("ID","MATRICULE","DATE_DEBUT","DATE_FIN","RETENUE","REMARQUE","NOMPERSONNEL","ETAT","ID_OBJET","IDUSER","MOISREGULARISATION","ANNEEREGULARISATION","IDCATEGORIE_QUALIFICATION","IDFONCTION","POURCENTAGE","ETATLIB","HS_30_NI","HS_30_I","HS_50_NI","HS_50_I") AS
SELECT "ID","MATRICULE","DATE_DEBUT","DATE_FIN","RETENUE","REMARQUE","NOMPERSONNEL","ETAT","ID_OBJET","IDUSER","MOISREGULARISATION","ANNEEREGULARISATION","IDCATEGORIE_QUALIFICATION","IDFONCTION","POURCENTAGE","ETATLIB","HS_30_NI","HS_30_I","HS_50_NI","HS_50_I"
FROM (
         SELECT
             p.idpersonnel as id,
             p.matricule,
             p.id_code_rubrique,
--         p.nomRubrique,
             p.date_debut,
             p.date_fin,
             p.gain,
             p.retenue,
             p.remarque,
             p.nomPersonnel,
             p.etat,
             p.id_objet,
             p.iduser,
             p.moisregularisation,
             p.anneeregularisation,
             p.idcategorie_qualification,
             p.idfonction,
             p.pourcentage,
             p.etatLib
         FROM PAIEPERS_ELP_CPL p
     )
         PIVOT (
                SUM(gain)
    FOR id_code_rubrique IN (
        'PR0000130'  AS "HS_30_NI",
        'PR0000130I' AS "HS_30_I",
        'PR0000150'  AS "HS_50_NI",
        'PR0000150I' AS "HS_50_I"
        )
        ) ORDER BY matricule ASC
;
-- [568/1309] PAIE_AVANCEMENT_LIBELLE2
CREATE OR REPLACE FORCE VIEW "PAIE_AVANCEMENT_LIBELLE2" ("ID","MOTIF","IDMOTIF","ID_LOGPERS","MATRICULE","IDPERS","DATEDECISION","REFDECISION","DATE_APPLICATION","DIRECTION","SERVICE","IDFONCTION","CTG","IDCATEGORIE","ECHELON","CLASSEE","INDICEGRADE","INDICE_FONCTIONNEL","STATUT","VEHICULEE","REMARQUE","SEXE","ETAT","MATRICULE_PATRON","DROIT_HS","INDICE_CT","CODE_BANQUE","FONCTIONLIB","ETATLIB") AS
SELECT pav.id,
	       dt.val AS motif,
	       dt.id AS idmotif,
	       (lp.nom || ' ') || lp.prenom AS id_logpers,
	       lpad(pip.matricule, 5, '0') AS matricule,
	       pip.id AS idpers,
	       pav.datedecision,
	       pav.refdecision,
	       pav.date_application,
	       ld.val AS direction,
	       ls.code_service AS service,
	       pf.id AS idfonction,
	       pav.ctg,
	       pg.val AS idcategorie,
	       pav.echelon,
	       pav.classee,
	       pav.indicegrade,
	       pav.indice_fonctionnel,
	       CASE
	           WHEN pip.temporaire = -1 THEN 'Temporaire'
	           WHEN pip.temporaire = 0 THEN 'Permanent'
	           WHEN pip.temporaire = 1 THEN 'Cadre'
	           ELSE NULL
	           END AS statut,
	       pav.vehiculee,
	       pav.remarque,
	       lp.sexe,
	       pav.etat,
	       pav.matricule_patron,
	       pav.droit_hs,
	       pav.indice_ct,
	       pav.code_banque,
	       pf.desce AS fonctionLib,
	       CASE
	           WHEN pav.etat = 1 THEN 'NON VALIDE'
	           WHEN pav.etat = 11 THEN 'VALIDEE'
	           ELSE 'AUTRE'
	           END AS etatLib
	FROM paie_avancement pav
	         LEFT JOIN dec_decision_type dt ON dt.id = pav.motif
	         JOIN log_personnel lp ON lp.id = pav.id_logpers
	         LEFT JOIN paie_info_personnel pip ON pip.id = pav.id_logpers
	         LEFT JOIN log_direction ld ON ld.id = pav.direction
	         LEFT JOIN log_service ls ON ls.id = pav.service
	         LEFT JOIN paie_fonction pf ON pf.id = pav.idfonction
	         LEFT JOIN paie_categorie pg ON pg.id = pav.idcategorie
;
-- [569/1309] PAIE_AVANCEMENT_LIBELLE4
CREATE OR REPLACE FORCE VIEW "PAIE_AVANCEMENT_LIBELLE4" ("ID","MOTIF","IDMOTIF","ID_LOGPERS","MATRICULE","IDPERS","DATEDECISION","REFDECISION","DATE_APPLICATION","DIRECTION","SERVICE","IDFONCTION","CTG","IDCATEGORIE","ECHELON","CLASSEE","INDICEGRADE","INDICE_FONCTIONNEL","STATUT","VEHICULEE","REMARQUE","SEXE","ETAT","MATRICULE_PATRON","DROIT_HS","INDICE_CT","REGION","REGIONLIB","VEHICULEE_STR","CODE_BANQUE","FONCTIONLIB","IDTYPEAVANCEMENT","IDTYPEAVANCEMENTLIB","MODEPAIEMENT","MODEPAIEMENTLIB","UNITE","UNITELIB") AS
SELECT pav.id,
       dt.val AS motif,
       dt.id AS idmotif,
       (lp.nom || ' ') || lp.prenom AS id_logpers,
       lpad(pip.matricule, 5, '0') AS matricule,
       pip.id AS idpers,
       pav.datedecision,
       pav.refdecision,
       pav.date_application,
       ld.val AS direction,
       ls.libelle AS service,
       pf.val AS idfonction,
       pav.ctg,
       pg.val AS idcategorie,
       pav.echelon,
       pav.classee,
       pav.indicegrade,
       pav.indice_fonctionnel,
       pav.statut,
       pav.vehiculee,
       pav.remarque,
       lp.sexe,
       pav.etat,
       pav.matricule_patron,
       pav.droit_hs,
       pav.indice_ct,
       pav.region,
       rg.val AS regionlib,
       CASE pav.vehiculee
           WHEN 0 THEN 'non'
           WHEN 1 THEN 'oui'
           ELSE NULL
           END AS vehiculee_str,
       pav.code_banque,
       pf.desce AS fonctionLib,
       pav.idTypeAvancement,
        ta.val as idTypeAvancementLib,
        pav.modepaiement,
        mp.val as MODEPAIEMENTLIB,
        pav.unite,
        lu.val as unitelib
FROM paie_avancement pav
         LEFT JOIN dec_decision_type dt ON dt.id = pav.motif
         LEFT JOIN log_personnel lp ON lp.id = pav.id_logpers
         LEFT JOIN paie_info_personnel pip ON pip.id = pav.id_logpers
         LEFT JOIN log_direction ld ON ld.id = pav.direction
         LEFT JOIN log_service ls ON ls.id = pav.service
         LEFT JOIN paie_fonction pf ON pf.id = pav.idfonction
         LEFT JOIN region rg ON rg.id = pav.region
         LEFT JOIN paie_categorie pg ON pg.id = pav.idcategorie
         LEFT JOIN TYPE_AVANCEMENT ta ON ta.id = pav.idTypeAvancement
        LEFT JOIN MODEPAIEMENT mp ON mp.id = pav.MODEPAIEMENT
        LEFT JOIN LOG_UNITE lu ON lu.id = pav.unite
;
-- [570/1309] PAIE_EDITIONMOISANNEE_LIB
CREATE OR REPLACE FORCE VIEW "PAIE_EDITIONMOISANNEE_LIB" ("ID","IDPERSONNEL","MOIS","ANNEE","GAIN","RETENUE","IDUSER","IDDIRECTION","DATY","MOIS_STRING","ETAT","MONTANT") AS
SELECT pae.id,
       (log.nom || ' ') || log.prenom AS idpersonnel,
       pae.mois,
       pae.annee,
       pae.gain,
       pae.retenue,
       u.nomuser AS iduser,
       dir.val AS iddirection,
       pae.daty,
       CASE
           WHEN pae.mois = 1 THEN 'Janvier'
           WHEN pae.mois = 2 THEN 'Fevrier'
           WHEN pae.mois = 3 THEN 'Mars'
           WHEN pae.mois = 4 THEN 'Avril'
           WHEN pae.mois = 5 THEN 'Mai'
           WHEN pae.mois = 6 THEN 'Juin'
           WHEN pae.mois = 7 THEN 'Juillet'
           WHEN pae.mois = 8 THEN 'Aout'
           WHEN pae.mois = 9 THEN 'Septembre'
           WHEN pae.mois = 10 THEN 'Octobre'
           WHEN pae.mois = 11 THEN 'Novembre'
           WHEN pae.mois = 12 THEN 'Decembre'
           WHEN pae.mois = 13 THEN '13eme MOIS'
           WHEN pae.mois = 14 THEN '13eme MOIS BIS'
           ELSE NULL
           END AS mois_string,
       pae.etat,
       CAST(round(net.montant, 2) AS NUMBER(15,2)) AS montant
FROM paie_editionmoisannee pae
         LEFT JOIN log_personnel log ON log.id_pers = pae.idpersonnel
         LEFT JOIN log_direction dir ON dir.id = pae.iddirection
         LEFT JOIN utilisateur u ON u.refuser = pae.iduser
         LEFT JOIN net_moisannee net ON pae.mois = net.mois AND pae.annee = net.annee
ORDER BY pae.annee DESC, pae.mois DESC
;
-- [571/1309] PAIE_EDITIONMOISANNEE_LIB_2
CREATE OR REPLACE FORCE VIEW "PAIE_EDITIONMOISANNEE_LIB_2" ("ID","IDPERSONNEL","MOIS","ANNEE","GAIN","RETENUE","IDUSER","IDDIRECTION","DATY","MOIS_STRING","ETAT","MONTANT") AS
SELECT pae.id,
       (log.nom || ' ') || log.prenom AS idpersonnel,
       pae.mois,
       pae.annee,
       pae.gain,
       pae.retenue,
       u.nomuser AS iduser,
       dir.val AS iddirection,
       pae.daty,
       CASE
           WHEN pae.mois = 1 THEN 'Janvier'
           WHEN pae.mois = 2 THEN 'Fevrier'
           WHEN pae.mois = 3 THEN 'Mars'
           WHEN pae.mois = 4 THEN 'Avril'
           WHEN pae.mois = 5 THEN 'Mai'
           WHEN pae.mois = 6 THEN 'Juin'
           WHEN pae.mois = 7 THEN 'Juillet'
           WHEN pae.mois = 8 THEN 'Aout'
           WHEN pae.mois = 9 THEN 'Septembre'
           WHEN pae.mois = 10 THEN 'Octobre'
           WHEN pae.mois = 11 THEN 'Novembre'
           WHEN pae.mois = 12 THEN 'Decembre'
           WHEN pae.mois = 13 THEN '13eme MOIS'
           WHEN pae.mois = 14 THEN '13eme MOIS BIS'
           ELSE NULL
           END AS mois_string,
       pae.etat,
       CAST(ROUND(net.montant, 0) AS NUMBER(15, 0)) AS montant
FROM paie_editionmoisannee pae
         LEFT JOIN log_personnel log ON log.id_pers = pae.idpersonnel
         LEFT JOIN log_direction dir ON dir.id = pae.iddirection
         LEFT JOIN utilisateur u ON u.refuser = pae.iduser
         LEFT JOIN net_moisannee net ON pae.mois = net.mois AND pae.annee = net.annee
ORDER BY pae.annee DESC, pae.mois DESC
;
-- [572/1309] PAIE_EDITIONMOISANNEE_LIB_3
CREATE OR REPLACE FORCE VIEW "PAIE_EDITIONMOISANNEE_LIB_3" ("ID","IDPERSONNEL","MOIS","ANNEE","GAIN","RETENUE","IDUSER","IDDIRECTION","DATY","MOIS_STRING","ETAT","IDPERIODEPAIE","DATEDEBUT","DATEFIN","MONTANT","CATEGORIE") AS
SELECT pae.id,
       (log.nom || ' ') || log.prenom AS idpersonnel,
       pae.mois,
       pae.annee,
       pae.gain,
       pae.retenue,
       u.nomuser AS iduser,
       dir.val AS iddirection,
       pae.daty,
       TO_CHAR(

               TO_DATE(TO_CHAR(pae.mois, 'FM00'), 'MM'),

               'FMMonth',

               'NLS_DATE_LANGUAGE=FRENCH'

       ) AS mois_string,
       pae.etat,
       pae.idperiodepaie,
       pp.datedebut,
       pp.datefin,
       CAST(ROUND(net.montant, 0) AS NUMBER(15, 0)) AS montant,
       cps.val AS categorie

FROM paie_editionmoisannee pae
         LEFT JOIN log_personnel log ON log.id_pers = pae.idpersonnel
         LEFT JOIN log_direction dir ON dir.id = pae.iddirection
         LEFT JOIN utilisateur u ON u.refuser = pae.iduser
         LEFT JOIN net_moisannee net ON pae.mois = net.mois AND pae.annee = net.annee
         LEFT JOIN periodepaie pp ON pp.id = pae.id
         LEFT JOIN categorie_paie_salaire cps ON cps.id = pp.idcategoriepaie
ORDER BY pae.annee DESC, pae.mois DESC
;
-- [573/1309] PAIE_EDITION_CNAPS
CREATE OR REPLACE FORCE VIEW "PAIE_EDITION_CNAPS" ("IDPERSONNEL","MOIS","ANNEE","BRUT","CNAPS_TRAVAILLEUR","CNAPS_EMPLOYEUR") AS
SELECT
    pe.idpersonnel,
    pe.mois,
    pe.annee,
    ROUND(SUM(pe.gain), 2) AS brut,
    NVL(edc.cnaps_travailleur, 0) AS cnaps_travailleur,
    CASE
        WHEN NVL(edc.cnaps_travailleur, 0) = 0 THEN 0
        ELSE
            CASE
                WHEN (
                         SELECT plafond
                         FROM conf_cnaps
                         WHERE conf_cnaps.daty >= pe.datefin
                           AND ROWNUM = 1
                     ) < (SUM(pe.gain) * 0.13) THEN (
                    SELECT plafond
                    FROM conf_cnaps
                    WHERE conf_cnaps.daty >= pe.datefin
                      AND ROWNUM = 1
                )
                ELSE ROUND(LEAST(NVL(edc.cnaps_travailleur, 0) * 13, SUM(pe.gain) * 0.13), 2)
                END
        END AS cnaps_employeur
FROM paie_edition pe
         JOIN paie_rubrique pr
              ON pe.idelementpaie = pr.id
                  AND pr.typerubrique = 'G'
                  AND pr.imposable = 'I'
         LEFT JOIN (
    SELECT
        pe_1.idpersonnel,
        pe_1.mois,
        pe_1.annee,
        pe_1.retenue AS cnaps_travailleur
    FROM paie_edition pe_1
    WHERE pe_1.idelementpaie = 'PR000101'
) edc
                   ON pe.idpersonnel = edc.idpersonnel
                       AND pe.mois = edc.mois
                       AND pe.annee = edc.annee
GROUP BY
    pe.idpersonnel, pe.mois, pe.annee, edc.cnaps_travailleur,  pe.datefin
;
-- [574/1309] PAIE_EDITION_ECRITURE_LIGNE
CREATE OR REPLACE FORCE VIEW "PAIE_EDITION_ECRITURE_LIGNE" ("IDPERSONNEL","IDELEMENTPAIE","MOIS","ANNEE","GAIN","RETENUE","DATEDEBUT","IDEDITION","COMPTEGEN_DB","COMPTEGEN_CR","COMPTEANA_DB","COMPTEANA_CR","TYPERUBRIQUE","RUBRIQUE_LIBELLE","IDDIRECTION","CODE","IMPOSABLE") AS
SELECT pe.idpersonnel,
       pe.idelementpaie,
       pema.mois,
       pema.annee,
       pe.gain,
       pe.retenue,
       pe.datedebut,
       pe.idedition,
       pe.comptegen_db,
       pe.comptegen_cr,
       pe.compteana_db,
       pe.compteana_cr,
       pr.typerubrique,
       pr.val AS rubrique_libelle,
       pema.iddirection,
       pr.code,
       pr.imposable
FROM paie_edition pe
         JOIN paie_rubrique pr ON pr.id = pe.idelementpaie
         JOIN paie_info_personnel pip ON pip.id = pe.idpersonnel
         JOIN paie_editionmoisannee pema ON pema.id = pe.idedition
;
-- [575/1309] ECRITURE_DELA_PAIE
CREATE OR REPLACE FORCE VIEW "ECRITURE_DELA_PAIE" ("IDELEMENTPAIE","MOIS","ANNEE","GAIN","RETENUE","IDEDITION","COMPTEGEN_DB","COMPTEGEN_CR","COMPTEANA_DB","COMPTEANA_CR","TYPERUBRIQUE","RUBRIQUE_LIBELLE","IDDIRECTION","IMPOSABLE") AS
SELECT peel.idelementpaie,
       peel.mois,
       peel.annee,
       sum(peel.gain) AS gain,
       sum(peel.retenue) AS retenue,
       peel.idedition,
       peel.comptegen_db,
       peel.comptegen_cr,
       peel.compteana_db,
       peel.compteana_cr,
       peel.typerubrique,
       peel.rubrique_libelle,
       peel.iddirection,
       peel.imposable
FROM paie_edition_ecriture_ligne peel
GROUP BY peel.idelementpaie, peel.mois, peel.annee, peel.idedition, peel.comptegen_db, peel.comptegen_cr, peel.compteana_db, peel.compteana_cr, peel.typerubrique, peel.rubrique_libelle, peel.iddirection, peel.code, peel.imposable
ORDER BY peel.typerubrique DESC, peel.code
;
-- [576/1309] ECRITURE_DELA_PAIE_CREDIT
CREATE OR REPLACE FORCE VIEW "ECRITURE_DELA_PAIE_CREDIT" ("MOIS","ANNEE","GAIN","RETENUE","IDEDITION","COMPTEGEN_DEBIT","COMPTEGEN_CREDIT","TYPERUBRIQUE","IDDIRECTION") AS
SELECT e.mois,
       e.annee,
       sum(e.gain) AS gain,
       sum(e.retenue) AS retenue,
       e.idedition,
       CAST('''' AS varchar(250)) AS comptegen_debit,
       e.comptegen_cr AS comptegen_credit,
       e.typerubrique,
       e.iddirection
FROM ecriture_dela_paie e
WHERE e.comptegen_cr IS NOT NULL
GROUP BY e.mois, e.annee, e.idedition, e.comptegen_cr, e.typerubrique, e.iddirection
;
-- [577/1309] ECRITURE_DELA_PAIE_DEBIT
CREATE OR REPLACE FORCE VIEW "ECRITURE_DELA_PAIE_DEBIT" ("MOIS","ANNEE","GAIN","RETENUE","IDEDITION","COMPTEGEN_DEBIT","COMPTEGEN_CREDIT","TYPERUBRIQUE","IDDIRECTION") AS
SELECT e.mois,
       e.annee,
       sum(e.gain) AS gain,
       sum(e.retenue) AS retenue,
       e.idedition,
       e.comptegen_db AS comptegen_debit,
       CAST('''' AS varchar(250)) AS comptegen_credit,
       e.typerubrique,
       e.iddirection
FROM ecriture_dela_paie e
WHERE e.comptegen_db IS NOT NULL
GROUP BY e.mois, e.annee, e.idedition, e.comptegen_db, e.typerubrique, e.iddirection
;
-- [578/1309] ECRITURE_DELA_PAIE_REGR
CREATE OR REPLACE FORCE VIEW "ECRITURE_DELA_PAIE_REGR" ("MOIS","ANNEE","GAIN","RETENUE","IDEDITION","COMPTEGEN_DEBIT","COMPTEGEN_CREDIT","TYPERUBRIQUE","IDDIRECTION") AS
SELECT ed.mois,
       ed.annee,
       ed.gain,
       ed.retenue,
       ed.idedition,
       ed.comptegen_debit,
       ed.comptegen_credit,
       ed.typerubrique,
       ed.iddirection
FROM ecriture_dela_paie_debit ed
UNION
SELECT ec.mois,
       ec.annee,
       ec.gain,
       ec.retenue,
       ec.idedition,
       ec.comptegen_debit,
       ec.comptegen_credit,
       ec.typerubrique,
       ec.iddirection
FROM ecriture_dela_paie_credit ec
;
-- [579/1309] ECRITURE_DELA_PAIE_REGR_COMPTE
CREATE OR REPLACE FORCE VIEW "ECRITURE_DELA_PAIE_REGR_COMPTE" ("MOIS","ANNEE","GAIN","RETENUE","IDEDITION","COMPTEGEN_DEBIT","COMPTEGEN_CREDIT","TYPERUBRIQUE","IDDIRECTION","COMPTELIBELLE") AS
SELECT edpr.mois,
       edpr.annee,
       edpr.gain,
       edpr.retenue,
       edpr.idedition,
       edpr.comptegen_debit,
       edpr.comptegen_credit,
       edpr.typerubrique,
       edpr.iddirection,
       cc.libelle AS comptelibelle
FROM ecriture_dela_paie_regr edpr
         LEFT JOIN compta_compte cc ON cc.compte = COALESCE(edpr.comptegen_debit, edpr.comptegen_credit)
;
-- [580/1309] PAIE_EDITION_ELTPAIE
CREATE OR REPLACE FORCE VIEW "PAIE_EDITION_ELTPAIE" ("ID","IDPERSONNEL","IDELEMENTPAIE","IDEDITION","MOIS","ANNEE","DROITS","RETENUES","DATEDEBUT","DATEFIN","REMARQUE","ELEMENT","CODE","RANG","RUBRIQUEDESCE","IMPOSABLE","RANGBULLETIN","AFFICHER","HEURENORMAL","HEURESUPNORMAL","HEURESUPNUIT","HEURESUPFERIE","HEURESUPWEEKEND","ABSENCE","SALAIREBASE") AS
SELECT
    ed.id,
    ed.idpersonnel,
    ed.idelementpaie,
    ed.idedition,
    ed.mois,
    ed.annee,
    ed.gain AS droits,
    ed.retenue AS retenues,
    ed.datedebut,
    ed.datefin,
    ed.remarque,
    r.val AS element,
    r.code,
    r.rang,
    r.desce AS rubriquedesce,
    r.imposable,
    r.rangbulletin,
    r.afficher,
    p.HEURENORMAL,
    p.HEURESUPNORMAL,
    p.HEURESUPNUIT,
    p.HEURESUPFERIE,
    p.HEURESUPWEEKEND,
    p.ABSENCE,
    c.montant AS salairebase
FROM paie_edition ed
         LEFT JOIN paie_rubrique r
                   ON ed.idelementpaie = r.id
         LEFT JOIN pointage p
                   ON p.idpersonnel = ed.idpersonnel
                       AND p.mois = ed.mois
                       AND p.annee = ed.annee
                       AND p.etat = 11
         LEFT JOIN categorie_qualification c
                   ON c.remarque = ed.idpersonnel
;
-- [581/1309] PAIE_EDITION_GAIN_IMP
CREATE OR REPLACE FORCE VIEW "PAIE_EDITION_GAIN_IMP" ("IDPERSONNEL","MOIS","ANNEE","IMPOSABLE") AS
SELECT paie_edition.idpersonnel,
       paie_edition.mois,
       paie_edition.annee,
       CAST(sum(paie_edition.gain) AS NUMBER(15,2)) AS imposable
FROM paie_edition
WHERE (paie_edition.idelementpaie IN ( SELECT paie_rubrique.id
                                       FROM paie_rubrique
                                       WHERE paie_rubrique.typerubrique = 'G' AND paie_rubrique.imposable = 'I' AND paie_rubrique.id NOT LIKE  '%AV%'))
GROUP BY paie_edition.idpersonnel, paie_edition.mois, paie_edition.annee
;
-- [582/1309] PAIE_EDITION_GRP_PERSONNE2
CREATE OR REPLACE FORCE VIEW "PAIE_EDITION_GRP_PERSONNE2" ("GAIN","IDPERSONNEL") AS
SELECT (grp2.gain + sfrm.montant) AS gain,
       grp2.idpersonnel
FROM ( SELECT CAST(sum(paie_edition.gain) AS NUMBER(15,2)) AS gain,
              paie_edition.idpersonnel
       FROM paie_edition
       WHERE paie_edition.idelementpaie NOT LIKE  '%PR000FRM%' AND paie_edition.annee > 2023
       GROUP BY paie_edition.idpersonnel) grp2
         LEFT JOIN solde_frm_2023 sfrm ON grp2.idpersonnel = sfrm.idpersonnel
;
-- [583/1309] PAIE_EDITION_LIBCOMPLET
CREATE OR REPLACE FORCE VIEW "PAIE_EDITION_LIBCOMPLET" ("ID","IDPERSONNEL","IDELEMENTPAIE","MOIS","ANNEE","GAIN","RETENUE","DATEDEBUT","DATEFIN","IDEDITION","REMARQUE","IDPERSONNELLIB","IDELEMENTPAIELIB","MATRICULE","CODERUBRIQUE","MOISLIB") AS
SELECT pe.id,
       pe.idpersonnel,
       pe.idelementpaie,
       pe.mois,
       pe.annee,
       pe.gain,
       pe.retenue,
       pe.datedebut,
       pe.datefin,
       pe.idedition,
       pe.remarque,
       (lp.nom || ' ') || lp.prenom AS idpersonnellib,
       (pr.code || ' ') || pr.val AS idelementpaielib,
       lp.matricule,
       pr.code AS coderubrique,
       TO_CHAR(
               TO_DATE(TO_CHAR(pe.mois, 'FM00'), 'MM'),
               'FMMonth',
               'NLS_DATE_LANGUAGE=FRENCH'
       ) AS moisLib
FROM paie_edition pe
         LEFT JOIN log_personnel_infocomplet lp ON lp.id = pe.idpersonnel
         LEFT JOIN paie_rubrique pr ON pr.id = pe.idelementpaie
         LEFT JOIN paie_editionmoisannee p ON pe.idedition = p.id
;
-- [584/1309] PAIE_FONCTIONLIBELLE
CREATE OR REPLACE FORCE VIEW "PAIE_FONCTIONLIBELLE" ("ID","VAL","DESCE","IDGROUPEFONCTION") AS
SELECT p.id,
       p.val,
       p.desce,
       pg.val AS idgroupefonction
FROM paie_fonction p
         LEFT JOIN paie_groupefonction pg ON p.idgroupefonction = pg.id
;
-- [585/1309] PAIE_INFO_EMBAUCHE
CREATE OR REPLACE FORCE VIEW "PAIE_INFO_EMBAUCHE" ("ID","DATESAISIE","MATRICULE","LIEU_NAISSANCE_COMMUNE","LIEU_DELIVRANCE_CIN","SITUATION_MATRIMONIAL","INITIALE","CTURGENCE_NOM_PRENOM","CTURGENCE_TELEPHONE1","CTURGENCE_TELEPHONE2","CTURGENCE_TELEPHONE3","IDCONJOINT","CODE_AGENCE_BANQUE","BANQUE_NUMERO_COMPTE","BANQUE_COMPTE_CLE","DATEEMBAUCHE","IDFONCTION","IDCATEGORIE","MODE_PAIEMENT","CLASSEE","INDICEGRADE","INDICE_FONCTIONNEL","MATRICULE_PATRON","STATUT","DROIT_HS","VEHICULEE","ECHELON","ETAT","CTG","IDUSER","INDICE_CT","DATEPROMOTION","NUMERO_CNAPS","NUMERO_OSTIE","TEMPORAIRE","N_EMBAUCHE","DATE_DEPART","N_DEPART","NBENFANT","HEUREJOURNALIER","HEUREHEBDOMADAIRE","HEUREMENSUEL","DIRECTION") AS
SELECT pip.id,
       pip.datesaisie,
       pip.matricule,
       pip.lieu_naissance_commune,
       pip.lieu_delivrance_cin,
       pip.situation_matrimonial,
       pip.initiale,
       pip.cturgence_nom_prenom,
       pip.cturgence_telephone1,
       pip.cturgence_telephone2,
       pip.cturgence_telephone3,
