    pip.situation_matrimonial,
    pip.initiale,
    pip.cturgence_nom_prenom,
    pip.cturgence_telephone1,
    pip.cturgence_telephone2,
    pip.cturgence_telephone3,
    pip.idconjoint,
    pip.code_agence_banque,
    pip.banque_numero_compte,
    pip.banque_compte_cle,
    pip.dateembauche,
    pip.idfonction,
    pip.idcategorie,
    pip.mode_paiement,
    pip.classee,
    pip.indicegrade,
    pip.indice_fonctionnel,
    pip.matricule_patron,
    pip.statut,
    pip.droit_hs,
    pip.vehiculee,
    pip.echelon,
    pip.etat,
    pip.ctg,
    pip.iduser,
    pip.indice_ct,
    pip.datepromotion,
    pip.numero_cnaps,
    pip.numero_ostie,
    pip.temporaire,
    pip.n_embauche,
    pip.date_depart,
    pip.n_depart,
    pip.nbenfant,
    pip.heurejournalier,
    pip.heurehebdomadaire,
    pip.heuremensuel,
    pip.indesirable,
    pip.duree,
    pip.telephone,
    pip.mail,
    pip.adresse_ligne1,
    pip.adresse_ligne2,
    pip.code_postal,
    pip.region,
    pip.idcategorie_paie,
    pip.idqualification,
    pip.formation,
    pip.discipline,
    pip.anneeexperience,
    pip.personnel_etat,
    pip.periode_essai,
    pip.permis_conduire,
    pip.chemin_permis,
    pip.remarque,
    pip.id_pers,
    pip.nom,
    pip.prenom,
    pip.date_naissance,
    pip.sexe,
    CASE
        WHEN pip.sexe = '0' THEN 'Madame'
        ELSE 'Monsieur'
        END AS sexepdf,
    CASE
        WHEN pip.sexe = '0' THEN 'elle'
        ELSE 'il'
        END AS pronompersonnelsujet,
    CASE
        WHEN pip.sexe = '0' THEN 'Elle'
        ELSE 'Il'
        END AS genrepdf,
    pip.numero_cin,
    pip.date_cin,
    pip.date_dupl_cin,
    pip.nationalite,
    pip.adresse,
    pip.fokotany,
    pip.acte_naissance,
    pip.direction,
    pip.service,
    cq.montant,
    qp.val AS categorie_qualificationlib,
    cp.val AS categorie_paielib,
    cq.date_debut,
    cq.date_fin,
    cq.avenant,
    pf.desce AS fonctionlib,
    pip.debutcontrat,
    pip.fincontrat,
    cq.numero
FROM
    categ_quali_contrat_2 cq
        LEFT JOIN paie_info_personnel_libcomplet pip ON pip.id = cq.remarque
        LEFT JOIN categorie_paie cp ON cp.id = pip.idcategorie_paie
        LEFT JOIN qualification_paie qp ON qp.id = pip.idqualification
        LEFT JOIN paie_fonction pf ON pf.id = pip.idfonction
;
