       pip.matricule_patron,
       pip.statut,
       pip.droit_hs,
       pip.vehiculee,
       pip.echelon,
       pip.etat,
       pip.ctg,
       pip.iduser,
       pip.indice_ct,
       pip.datepromotion,
       pip.numero_cnaps,
       pip.numero_ostie,
       pip.temporaire,
       pip.n_embauche,
       pip.date_depart,
       pip.n_depart,
       pip.nbenfant,
       pip.heurejournalier,
