-- [611/1309] PAIE_INFO_PERSONNELDIRECT
CREATE OR REPLACE FORCE VIEW "PAIE_INFO_PERSONNELDIRECT" ("ID","NATIONALITE","DATESAISIE","MATRICULE","LIEU_NAISSANCE_COMMUNE","LIEU_DELIVRANCE_CIN","SITUATION_MATRIMONIAL","INITIALE","CTURGENCE_NOM_PRENOM","CTURGENCE_TELEPHONE1","CTURGENCE_TELEPHONE2","CTURGENCE_TELEPHONE3","IDCONJOINT","CODE_AGENCE_BANQUE","BANQUE_NUMERO_COMPTE","BANQUE_COMPTE_CLE","DATEEMBAUCHE","IDFONCTION","IDCATEGORIE","MODE_PAIEMENT","CLASSEE","INDICEGRADE","INDICE_FONCTIONNEL","MATRICULE_PATRON","STATUT","DROIT_HS","VEHICULEE","ECHELON","ETAT","CTG","IDUSER","INDICE_CT","DATEPROMOTION","NUMERO_CNAPS","NUMERO_OSTIE","TEMPORAIRE","N_EMBAUCHE","DATE_DEPART","N_DEPART","NBENFANT","HEUREJOURNALIER","HEUREHEBDOMADAIRE","HEUREMENSUEL","DIRECTION","SERVICE","PERIODE_ESSAI","SEXE","DATE_NAISSANCE","IDCATEGORIE_PAIE","IDQUALIFICATION","IDDEPARTEMENT","SALAIRE_BASE") AS
SELECT p.id,
       l.nationalite,
       p.datesaisie,
       p.matricule,
       p.lieu_naissance_commune,
       p.lieu_delivrance_cin,
       p.situation_matrimonial,
       p.initiale,
       p.cturgence_nom_prenom,
       p.cturgence_telephone1,
       p.cturgence_telephone2,
       p.cturgence_telephone3,
       p.idconjoint,
       p.code_agence_banque,
       p.banque_numero_compte,
       p.banque_compte_cle,
       p.dateembauche,
       p.idfonction,
       p.idcategorie,
       p.mode_paiement,
       p.classee,
       p.indicegrade,
       p.indice_fonctionnel,
       p.matricule_patron,
       p.statut,
       p.droit_hs,
       p.vehiculee,
       p.echelon,
       p.etat,
       p.ctg,
       p.iduser,
       p.indice_ct,
       p.datepromotion,
       p.numero_cnaps,
       p.numero_ostie,
       p.temporaire,
       p.n_embauche,
       p.date_depart,
       p.n_depart,
       p.nbenfant,
       p.heurejournalier,
       p.heurehebdomadaire,
       p.heuremensuel,
       l.direction,
       l.service,
       p.periode_essai,
       l.sexe,
       l.date_naissance,
       p.idcategorie_paie,
       p.idqualification,
       p.IDDEPARTEMENT,
       CAST(COALESCE(pips.montant, 0) AS NUMBER(30,2)) AS salaire_base
FROM paie_info_personnel p,
     log_personnel l,
     paie_info_personnel_sb pips
WHERE l.id = p.id AND p.id = pips.id
;
-- [612/1309] PAIEINFOPERSELTPAIECOMPLET2
CREATE OR REPLACE FORCE VIEW "PAIEINFOPERSELTPAIECOMPLET2" ("ID","CODE_RUBRIQUE","DATE_DEBUT","DATE_FIN","MOISREGULARISATION","ANNEEREGULARISATION","GAIN","RETENUE","QUANTITE","UNITE","REMARQUE","IDPERSONNEL","VAL","DESCE","RANG","COMPTEPCG","CODE","TYPERUBRIQUE","BCS","BG","IMPOSABLE","NATURE","AVANTAGE","CPT_GEN_DB","CPT_GEN_CR","CPT_ANA_DB","CPT_ANA_CR","ISRAPPEL","ISCONFELTFIXE","MOIS","ANNEE","DATESAISIE","MATRICULE","LIEU_NAISSANCE_COMMUNE","LIEU_DELIVRANCE_CIN","SITUATION_MATRIMONIAL","INITIALE","CTURGENCE_NOM_PRENOM","CTURGENCE_TELEPHONE1","CTURGENCE_TELEPHONE2","CTURGENCE_TELEPHONE3","IDCONJOINT","CODE_AGENCE_BANQUE","BANQUE_NUMERO_COMPTE","BANQUE_COMPTE_CLE","DATEEMBAUCHE","IDFONCTION","IDGROUPEFONCTION","IDCATEGORIE","MODE_PAIEMENT","CLASSEE","INDICEGRADE","INDICE_FONCTIONNEL","MATRICULE_PATRON","STATUT","DROIT_HS","ETAT_ELEMENT","NATIONALITE","SERVICE","DIRECTION","DATEAPPLICATION","DATEFININVALID","DATE_DECISION","IDTYPEDEBAUCHE","NBENFANT","ID_OBJET","ETAT","TEMPORAIRE","PERIODE_ESSAI","POINTINDICE","REMARQUE_ELEMENT","FORMU","REGROUPEMENT","ARRONDI","INSERTED","SOMMABLE","BENEFICIAIRE","REMARQUEFORMULE","UNITEFORMULE","QTEFORMULE","IDCATEGORIE_PAIE","IDQUALIFICATION","IDDEPARTEMENT") AS
SELECT elt.id,
       elt.code_rubrique,
       elt.date_debut,
       elt.date_fin,
       elt.moisregularisation,
       elt.anneeregularisation,
       elt.gain,
       elt.retenue,
       elt.quantite,
       elt.unite,
       r.isinfini AS remarque,
       elt.idpersonnel,
       r.val,
       r.desce,
       r.rang,
       r.comptepcg,
       r.code,
       r.typerubrique,
       r.bcs,
       r.bg,
       r.imposable,
       r.nature,
       r.avantage,
       r.cpt_gen_db,
       r.cpt_gen_cr,
       r.cpt_ana_db,
       r.cpt_ana_cr,
       0 AS israppel,
       1 AS isconfeltfixe,
       EXTRACT(MONTH FROM elt.date_debut) AS mois,
       EXTRACT(YEAR FROM elt.date_debut) AS annee,
       info.datesaisie,
       info.matricule,
       info.lieu_naissance_commune,
       info.lieu_delivrance_cin,
       info.situation_matrimonial,
       info.initiale,
       info.cturgence_nom_prenom,
       info.cturgence_telephone1,
       info.cturgence_telephone2,
       info.cturgence_telephone3,
       info.idconjoint,
       info.code_agence_banque,
       info.banque_numero_compte,
       info.banque_compte_cle,
       info.dateembauche,
       info.idfonction,
       fonc.idgroupefonction,
       info.idcategorie,
       info.mode_paiement,
       info.classee,
       info.indicegrade,
       info.indice_fonctionnel,
       info.matricule_patron,
       info.statut,
       info.droit_hs,
       elt.etat AS etat_element,
       info.nationalite,
       info.service,
       info.direction,
       invalid.dateapplication,
       invalid.datefin AS datefininvalid,
       invalid.date_decision,
       invalid.idtypedebauche,
       info.nbenfant,
       elt.id_objet,
       info.etat,
       info.temporaire,
       info.periode_essai,
       c.valmin AS pointindice,
       elt.remarque AS remarque_element,
       formu.id AS formu,
       r.regroupement,
       r.arrondi,
       r.inserted,
       r.sommable,
       r.beneficiaire,
       r.remarque AS remarqueformule,
       r.uniteformule,
       r.qteformule,
       info.idcategorie_paie,
       info.idqualification,
       info.IDDEPARTEMENT
FROM paie_personnel_elementpaie elt
         JOIN paie_rubrique r ON elt.code_rubrique = r.id
         LEFT JOIN paie_info_personneldirect info ON elt.idpersonnel = info.id
         LEFT JOIN paie_fonction fonc ON info.idfonction = fonc.id AND info.id <> '1002067'
         LEFT JOIN dernier_debauche_by_employe invalid ON invalid.idlogpers = info.id
         LEFT JOIN configuration c ON c.id = 'CONF000250'
         LEFT JOIN detformu formu ON elt.id = formu.mere
;
-- [613/1309] PAIEINFOPERSELTPAIECOMPLET4
CREATE OR REPLACE FORCE VIEW "PAIEINFOPERSELTPAIECOMPLET4" ("ID","CODE_RUBRIQUE","DATE_DEBUT","DATE_FIN","MOISREGULARISATION","ANNEEREGULARISATION","GAIN","RETENUE","QUANTITE","UNITE","REMARQUE","IDPERSONNEL","VAL","DESCE","RANG","COMPTEPCG","CODE","TYPERUBRIQUE","BCS","BG","IMPOSABLE","NATURE","AVANTAGE","CPT_GEN_DB","CPT_GEN_CR","CPT_ANA_DB","CPT_ANA_CR","ISRAPPEL","ISCONFELTFIXE","MOIS","ANNEE","DATESAISIE","MATRICULE","LIEU_NAISSANCE_COMMUNE","LIEU_DELIVRANCE_CIN","SITUATION_MATRIMONIAL","INITIALE","CTURGENCE_NOM_PRENOM","CTURGENCE_TELEPHONE1","CTURGENCE_TELEPHONE2","CTURGENCE_TELEPHONE3","IDCONJOINT","CODE_AGENCE_BANQUE","BANQUE_NUMERO_COMPTE","BANQUE_COMPTE_CLE","DATEEMBAUCHE","IDFONCTION","IDGROUPEFONCTION","IDCATEGORIE","MODE_PAIEMENT","CLASSEE","INDICEGRADE","INDICE_FONCTIONNEL","MATRICULE_PATRON","STATUT","DROIT_HS","ETAT_ELEMENT","NATIONALITE","SERVICE","DIRECTION","DATEAPPLICATION","DATEFININVALID","DATE_DECISION","IDTYPEDEBAUCHE","NBENFANT","ID_OBJET","ETAT","TEMPORAIRE","PERIODE_ESSAI","POINTINDICE","REMARQUE_ELEMENT","FORMU","REGROUPEMENT","ARRONDI","INSERTED","SOMMABLE","BENEFICIAIRE","REMARQUEFORMULE","UNITEFORMULE","QTEFORMULE","IDCATEGORIE_PAIE","IDQUALIFICATION","IDDEPARTEMENT") AS
SELECT
    MIN(p.id) AS id,
    p.code_rubrique,
    p.date_debut,
    p.date_fin,
    MAX(p.moisregularisation) AS moisregularisation,
    MAX(p.anneeregularisation) AS anneeregularisation,
    SUM(p.gain) AS gain,
    SUM(p.retenue) AS retenue,
    SUM(p.quantite) AS quantite,
    MAX(p.unite) AS unite,
    MAX(p.remarque) AS remarque,
    p.idpersonnel,
    MAX(p.val) AS val,
    MAX(p.desce) AS desce,
    MAX(p.rang) AS rang,
    MAX(p.comptepcg) AS comptepcg,
    MAX(p.code) AS code,
    p.typerubrique,
    MAX(p.bcs) AS bcs,
    MAX(p.bg) AS bg,
    MAX(p.imposable) AS imposable,
    MAX(p.nature) AS nature,
    MAX(p.avantage) AS avantage,
    MAX(p.cpt_gen_db) AS cpt_gen_db,
    MAX(p.cpt_gen_cr) AS cpt_gen_cr,
    MAX(p.cpt_ana_db) AS cpt_ana_db,
    MAX(p.cpt_ana_cr) AS cpt_ana_cr,
    MAX(p.israppel) AS israppel,
    MAX(p.isconfeltfixe) AS isconfeltfixe,
    MAX(p.mois) AS mois,
    MAX(p.annee) AS annee,
    MAX(p.datesaisie) AS datesaisie,
    MAX(p.matricule) AS matricule,
    MAX(p.lieu_naissance_commune) AS lieu_naissance_commune,
    MAX(p.lieu_delivrance_cin) AS lieu_delivrance_cin,
    MAX(p.situation_matrimonial) AS situation_matrimonial,
    MAX(p.initiale) AS initiale,
    MAX(p.cturgence_nom_prenom) AS cturgence_nom_prenom,
    MAX(p.cturgence_telephone1) AS cturgence_telephone1,
    MAX(p.cturgence_telephone2) AS cturgence_telephone2,
    MAX(p.cturgence_telephone3) AS cturgence_telephone3,
    MAX(p.idconjoint) AS idconjoint,
    MAX(p.code_agence_banque) AS code_agence_banque,
    MAX(p.banque_numero_compte) AS banque_numero_compte,
    MAX(p.banque_compte_cle) AS banque_compte_cle,
    MAX(p.dateembauche) AS dateembauche,
    MAX(p.idfonction) AS idfonction,
    MAX(p.idgroupefonction) AS idgroupefonction,
    MAX(p.idcategorie) AS idcategorie,
    MAX(p.mode_paiement) AS mode_paiement,
    MAX(p.classee) AS classee,
    MAX(p.indicegrade) AS indicegrade,
    MAX(p.indice_fonctionnel) AS indice_fonctionnel,
    MAX(p.matricule_patron) AS matricule_patron,
    MAX(p.statut) AS statut,
    MAX(p.droit_hs) AS droit_hs,
    MAX(p.etat_element) AS etat_element,
    MAX(p.nationalite) AS nationalite,
    MAX(p.service) AS service,
    MAX(p.direction) AS direction,
    MAX(p.dateapplication) AS dateapplication,
    MAX(p.datefininvalid) AS datefininvalid,
    MAX(p.date_decision) AS date_decision,
    MAX(p.idtypedebauche) AS idtypedebauche,
    MAX(p.nbenfant) AS nbenfant,
    MAX(p.id_objet) AS id_objet,
    MAX(p.etat) AS etat,
    MAX(p.temporaire) AS temporaire,
    MAX(p.periode_essai) AS periode_essai,
    MAX(p.pointindice) AS pointindice,
    MAX(p.remarque_element) AS remarque_element,
    MAX(p.formu) AS formu,
    MAX(p.regroupement) AS regroupement,
    MAX(p.arrondi) AS arrondi,
    MAX(p.inserted) AS inserted,
    MAX(p.sommable) AS sommable,
    MAX(p.beneficiaire) AS beneficiaire,
    MAX(p.remarqueformule) AS remarqueformule,
    MAX(p.uniteformule) AS uniteformule,
    MAX(p.qteformule) AS qteformule,
    MAX(p.idcategorie_paie) AS idcategorie_paie,
    MAX(p.idqualification) AS idqualification,
    MAX(p.IDDEPARTEMENT) AS iddepartement
FROM PAIEINFOPERSELTPAIECOMPLET2 p
GROUP BY
    p.idpersonnel,
    p.code_rubrique,
    p.date_debut,
    p.date_fin,
    p.typerubrique
;
