-- [617/1309] PAIE_MODEPAIEMENT
CREATE OR REPLACE FORCE VIEW "PAIE_MODEPAIEMENT" ("ID","VAL","DESCE") AS
SELECT 
"ID","VAL","DESCE"
FROM MODEPAIEMENT m 
WHERE m.id IN ('0001',
'0002',
'0003')
;
-- [618/1309] PAIE_PERSONNEL_ELEMENTPAIE_LIB
CREATE OR REPLACE FORCE VIEW "PAIE_PERSONNEL_ELEMENTPAIE_LIB" ("ID","CODE_RUBRIQUE","DATE_DEBUT","DATE_FIN","GAIN","RETENUE","REMARQUE","IDPERSONNEL","ETAT","ID_OBJET","IDUSER","MOISREGULARISATION","ANNEEREGULARISATION","IDCATEGORIE_QUALIFICATION","IDFONCTION","POURCENTAGE") AS
SELECT ppe.id,
       pr.val AS code_rubrique,
       ppe.date_debut,
       ppe.date_fin,
       ppe.gain,
       ppe.retenue,
       ppe.remarque,
       (pip.nom || ' ') || pip.prenom AS idpersonnel,
       ppe.etat,
       ppe.id_objet,
       ppe.iduser,
       ppe.moisregularisation,
       ppe.anneeregularisation,
       (cq.idcategorielib || ' ') || cq.categorie_qualificationlib AS idcategorie_qualification,
       pf.val AS idfonction,
       ppe.pourcentage
FROM paie_personnel_elementpaie ppe
         LEFT JOIN log_personnel pip ON pip.id = ppe.idpersonnel
         LEFT JOIN categ_quali_libcomplet cq ON ppe.idcategorie_qualification = cq.id
         LEFT JOIN paie_fonction pf ON ppe.idfonction = pf.id
         LEFT JOIN paie_rubrique pr ON pr.id = ppe.code_rubrique
;
-- [619/1309] PAIE_PERS_ELTPAIE_LIB2
CREATE OR REPLACE FORCE VIEW "PAIE_PERS_ELTPAIE_LIB2" ("ID","MATRICULE","ID_CODE_RUBRIQUE","CODE_RUBRIQUE","DATE_DEBUT","DATE_FIN","GAIN","RETENUE","REMARQUE","IDPERSONNEL","ETAT","ID_OBJET","IDUSER","MOISREGULARISATION","ANNEEREGULARISATION","RUBRIQUE","MOISLIB","IDCATEGORIE_QUALIFICATION","IDFONCTION","POURCENTAGE","ETATLIB") AS
SELECT
    ppe.id,
    pip2.matricule,
    pr.id AS id_code_rubrique,
    pr.val AS code_rubrique,
    ppe.date_debut,
    ppe.date_fin,
    ppe.gain,
    ppe.retenue,
    ppe.remarque,
    pip.nom || ' ' || pip.prenom AS idpersonnel,
    ppe.etat,
    ppe.id_objet,
    ppe.iduser,
    ppe.moisregularisation,
    ppe.anneeregularisation,
    pr.VAL as rubrique,

    TO_CHAR(
            TO_DATE(TO_CHAR(ppe.moisregularisation, 'FM00'), 'MM'),
            'FMMonth',
            'NLS_DATE_LANGUAGE=FRENCH'
    ) AS moisLib,

    cq.idcategorielib || ' ' || cq.categorie_qualificationlib AS idcategorie_qualification,
    pf.desce AS idfonction,
    ppe.pourcentage,

    CASE
        WHEN ppe.etat = '1' THEN 'CREE'
        WHEN ppe.etat = '11' THEN 'VALIDE'
        WHEN ppe.etat = '0' THEN 'ANNULE'
        ELSE 'INCONNU'
        END AS etatlib

FROM paie_personnel_elementpaie ppe
         LEFT JOIN log_personnel pip
                   ON TO_CHAR(pip.id) = TO_CHAR(ppe.idpersonnel)
         LEFT JOIN categorie_qualification_libc cq
                   ON TO_CHAR(ppe.idcategorie_qualification) = TO_CHAR(cq.id)
         LEFT JOIN paie_fonction pf
                   ON TO_CHAR(ppe.idfonction) = TO_CHAR(pf.id)
         LEFT JOIN paie_rubrique pr
                   ON TO_CHAR(pr.id) = TO_CHAR(ppe.code_rubrique)
         JOIN paie_info_personnel pip2
              ON TO_CHAR(pip.id) = TO_CHAR(pip2.id) WHERE ppe.CODE_RUBRIQUE!='PR0000150HS'
;
-- [620/1309] PAIE_PERS_ELTPAIE_LIB_AV
CREATE OR REPLACE FORCE VIEW "PAIE_PERS_ELTPAIE_LIB_AV" ("ID","MATRICULE","ID_CODE_RUBRIQUE","CODE_RUBRIQUE","DATE_DEBUT","DATE_FIN","GAIN","RETENUE","REMARQUE","IDPERSONNEL","ETAT","ID_OBJET","IDUSER","MOISREGULARISATION","ANNEEREGULARISATION","IDCATEGORIE_QUALIFICATION","IDFONCTION","POURCENTAGE","MOISREGULARISATIONLIB") AS
SELECT
    pp."ID",
    pp."MATRICULE",
    pp."ID_CODE_RUBRIQUE",
    pp."CODE_RUBRIQUE",
    pp."DATE_DEBUT",
    pp."DATE_FIN",
    pp."GAIN",
    pp."RETENUE",
    pp."REMARQUE",
    pp."IDPERSONNEL",
    pp."ETAT",
    pp."ID_OBJET",
    pp."IDUSER",
    pp."MOISREGULARISATION",
    pp."ANNEEREGULARISATION",
    pp."IDCATEGORIE_QUALIFICATION",
    pp."IDFONCTION",
    pp."POURCENTAGE",
    -- Libelle du mois
    TO_CHAR(TO_DATE(pp.MOISREGULARISATION, 'MM'), 'MONTH', 'NLS_DATE_LANGUAGE=FRENCH')
        AS MOISREGULARISATIONLIB
FROM PAIE_PERS_ELTPAIE_LIB2 pp
WHERE pp.ID_CODE_RUBRIQUE = 'PRU0447'
;
-- [621/1309] PAIE_PERS_ELTPAIE_LIB_IND
CREATE OR REPLACE FORCE VIEW "PAIE_PERS_ELTPAIE_LIB_IND" ("ID","MATRICULE","CODE_RUBRIQUE","DATE_DEBUT","DATE_FIN","GAIN","RETENUE","REMARQUE","IDPERSONNEL","ETAT","ETATLIB","ID_OBJET","IDUSER","MOISREGULARISATION","ANNEEREGULARISATION","IDCATEGORIE_QUALIFICATION","IDFONCTION","POURCENTAGE","MOISREGULARISATIONLIB") AS
SELECT ID,
       MATRICULE,
       CODE_RUBRIQUE,
       DATE_DEBUT,
       DATE_FIN,
       GAIN,
       RETENUE,
       REMARQUE,
       IDPERSONNEL,
       ETAT,
       ETATLIB,
       ID_OBJET,
       IDUSER,
       MOISREGULARISATION,
       ANNEEREGULARISATION,
       IDCATEGORIE_QUALIFICATION,
       IDFONCTION,
       POURCENTAGE,
       -- Libelle du mois
       TO_CHAR(TO_DATE(pp.MOISREGULARISATION, 'MM'), 'MONTH', 'NLS_DATE_LANGUAGE=FRENCH')
           AS MOISREGULARISATIONLIB
FROM PAIE_PERS_ELTPAIE_LIB2 pp
WHERE pp.id_code_rubrique = 'PR000021'
;
-- [622/1309] PARQUET_BATIMENT_LIB
CREATE OR REPLACE FORCE VIEW "PARQUET_BATIMENT_LIB" ("ID","VAL","IDBATIMENT") AS
SELECT DISTINCT
       bd.IDPARQUET   AS ID,
       p.VAL          AS VAL,
       bd.IDMERE      AS IDBATIMENT
FROM BATIMENTDETAIL bd
JOIN PARQUET p ON p.ID = bd.IDPARQUET
;
-- [623/1309] PERIODEPAIELIB
CREATE OR REPLACE FORCE VIEW "PERIODEPAIELIB" ("ID","MOIS","DATEDEBUT","DATEFIN","IDCATEGORIEPAIE","ANNEE","ETAT","MOISLIB","CATEGORIELIB") AS
SELECT
    p.id,
    p.mois,
    p.datedebut,
    p.datefin,
    p.idcategoriepaie,
    p.annee,
    p.etat,
    TO_CHAR(
            TO_DATE(TO_CHAR(p.mois, 'FM00'), 'MM'),
            'FMMonth',
            'NLS_DATE_LANGUAGE=FRENCH'
    ) AS moisLib,
    categ.VAL as categorieLib
FROM PERIODEPAIE p
         LEFT JOIN CATEGORIE_PAIE categ on categ.id = p.IDCATEGORIEPAIE
;
-- [624/1309] PERSONNELDEMAINTENANCE
CREATE OR REPLACE FORCE VIEW "PERSONNELDEMAINTENANCE" ("ID","NOM","PRENOM","SERVICE","SERVICELIB") AS
SELECT
    lp.id,
    nom,
    prenom,
    service,
    ls.libelle AS serviceLib
FROM log_personnel lp
         LEFT JOIN LOG_SERVICE ls ON lp.service = ls.id
WHERE
    service LIKE 'SERVM%'
;
-- [625/1309] PERSONNEL_MATRICULE
CREATE OR REPLACE FORCE VIEW "PERSONNEL_MATRICULE" ("ID","NOM","MAIL","TELEPHONE","ADRESSE","REMARQUE","COMPTE") AS
SELECT p.id, p.NOM, p.MAIL, pip.MATRICULE AS TELEPHONE , p.ADRESSE, p.REMARQUE, p.COMPTE FROM PERSONNEL p 
JOIN PAIE_INFO_PERSONNEL pip 
ON pip.id  = p.id
;
-- [626/1309] PERSONNEMAINTENANCECPL
CREATE OR REPLACE FORCE VIEW "PERSONNEMAINTENANCECPL" ("ID","NOM","TELEPHONE","MAIL","ADRESSE","REMARQUE","COMPTE","IDDEPARTEMENT","IDDEPARTEMENTLIB","IDDEPARTEMENTDESCE") AS
select p."ID",p."NOM",p."TELEPHONE",p."MAIL",p."ADRESSE",p."REMARQUE",p."COMPTE",p."IDDEPARTEMENT", dm.VAL as iddepartementlib, dm.DESCE as iddepartementdesce from PERSONNEL p
                                                                                left join DEPARTEMENTMAINTENANCE dm on p.IDDEPARTEMENT = dm.ID
where p.IDDEPARTEMENT is not null
;
-- [627/1309] PERTE_GRPORIGINE_FACT
CREATE OR REPLACE FORCE VIEW "PERTE_GRPORIGINE_FACT" ("IDORIGINE","TAUX","MONTANT","MONTANTAR","IDBCDETAIL") AS
select lf.id1 as idorigine, FFC.taux, sum(ffc.MONTANTHT) as montant, sum(ffc.montantHTAr) as montantar,LISTAGG(id2, ';;') WITHIN GROUP (ORDER BY id2) AS idbcDetail
from LIAISONFACTUREFOURNISSEURS lf
         LEFT JOIN FactFournisseurCalc FFC on FFC.id = lf.id2
    where not exists (select 1 from perteGainUtilise p where p.VAL=lf.ID2)
group by lf.id1, FFC.taux
;
-- [628/1309] FACTUREFOURNISSEUR_PERTE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_PERTE" ("ID","IDFOURNISSEUR","IDMODEPAIEMENT","DATY","DESIGNATION","DATEECHEANCEPAIEMENT","ETAT","REFERENCE","IDBC","DEVISE","TAUX","IDMAGASIN","IDDEVISE","ESTPREVU","DATYPREVU","MONTANTPERTEGAIN","NUMERO","TYPEACHAT","IDTYPEFACTURE","IDOBJET","IDREF","IDDMDACHAT","IDFACTUREPRINCIPALE","SERVICE","TYPEFACTUREFOURNISSEUR") AS
SELECT f.ID,
       f.IDFOURNISSEUR,
       f.IDMODEPAIEMENT,
       f.DATY,
       f.DESIGNATION,
       f.DATEECHEANCEPAIEMENT,
       f.ETAT,
       f.REFERENCE,
       f.IDBC,
       f.DEVISE,
       f.TAUX,
       f.IDMAGASIN,
       f.IDDEVISE,
       f.ESTPREVU,
       f.DATYPREVU,
       cast (nvl(p.MONTANTAR, 0) as number(30,2)) AS MONTANTPERTEGAIN,
       f.numero ,
       f.TYPEACHAT ,
       f.IDTYPEFACTURE ,
       f.IDOBJET ,
       f.IDREF ,
       f.IDDMDACHAT ,
       f.IDFACTUREPRINCIPALE ,
       f.SERVICE ,
       f.TYPEFACTUREFOURNISSEUR
FROM FACTUREFOURNISSEUR f
         left JOIN perte_grporigine_fact p ON p.idorigine = f.id
;
-- [629/1309] FFAVECPERTE_FF_IDPG
CREATE OR REPLACE FORCE VIEW "FFAVECPERTE_FF_IDPG" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","QTE","PU","REMISES","IDBCDETAIL","TVA","DEVISE","TAUXDECHANGE","IDDEVISE","DESIGNATION","COMPTE","MONTANTPERTEGAIN","IDFOURNISSEUR","ETAT","DATY","PUPERTEGAIN","MONTANTAVECPERTEGAIN","LIBELLEPRODUIT") AS
SELECT
    ff.ID,
    ff.IDFACTUREFOURNISSEUR,
    ff.IDPRODUIT,
    ff.QTE,
    ff.PU,
    ff.REMISES,
    p.IDBCDETAIL as IDBCDETAIL,
    ff.TVA,
    ff.DEVISE,
    ff.TAUXDECHANGE,
    ff.IDDEVISE,
    ff.DESIGNATION,
    ff.COMPTE,
    CAST( nvl((CASE WHEN fg.MONTANTPERTEGAIN =0 THEN NULL ELSE  ff.MONTANTPERTEGAIN end),(p.montantAr*qte*p.TAUX*ff.pu/fg.montanttotal)) AS NUMBER(30,2) ) AS MONTANTPERTEGAIN ,
    ff.IDFOURNISSEUR,
    ff.ETAT,ff.DATY,
    CAST( (qte*ff.pu*TAUXDECHANGE+nvl((CASE WHEN fg.MONTANTPERTEGAIN =0 THEN NULL ELSE  ff.MONTANTPERTEGAIN end),0))/qte AS NUMBER(30,2) ) AS pupertegain ,
    CAST( (qte*ff.pu*TAUXDECHANGE+nvl((CASE WHEN fg.MONTANTPERTEGAIN =0 THEN NULL ELSE  ff.MONTANTPERTEGAIN end),0)) AS NUMBER(30,2) ) AS montantavecpertegain,
    asi.LIBELLE AS LIBELLEPRODUIT
FROM
    FACTUREFOURNISSEUR_mf ff
        left JOIN perte_grporigine_fact p ON p.idorigine=ff.idfacturefournisseur
        LEFT JOIN ff_grpmere fg ON fg.idfacturefournisseur=ff.idfacturefournisseur
        LEFT JOIN AS_INGREDIENTS asi ON ASI.ID = ff.IDPRODUIT
;
-- [630/1309] PIECEMACHINELIB
CREATE OR REPLACE FORCE VIEW "PIECEMACHINELIB" ("ID","IDPIECE","IDMACHINE","IDPIECELIB","IDMACHINELIB") AS
SELECT
    pm."ID",pm."IDPIECE",pm."IDMACHINE",
    p.LIBELLE AS IDPIECELIB,
    m.LIBELLE AS IDMACHINELIB
FROM PIECEMACHINE pm
         JOIN AS_INGREDIENT_MAINTENANCE p
              ON p.ID = pm.IDPIECE
         JOIN AS_INGREDIENT_MAINTENANCE m
              ON m.ID = pm.IDMACHINE
;
-- [631/1309] PLANFORMATIONANNUELLELIB
CREATE OR REPLACE FORCE VIEW "PLANFORMATIONANNUELLELIB" ("ID","ANNEE","LIBELLE","ETAT","ETATLIB","BUDGETTOTALPREVISIONEL","DATY") AS
SELECT
    p.ID,
    p.ANNEE,
    p.LIBELLE,
    p.ETAT,
    CASE 
        WHEN p.ETAT = 1 THEN 'Cree'
        WHEN p.ETAT = 11 THEN 'Valide'
        WHEN p.ETAT = 0 THEN 'Annule'
        ELSE 'Inconnu'
    END AS ETATLIB,

    p.BUDGETTOTALPREVISIONEL,
    p.DATY
FROM PLAN_FORMATION_ANNUEL p
;
-- [632/1309] PLANNING_CPL
CREATE OR REPLACE FORCE VIEW "PLANNING_CPL" ("ID","REFOBJET","ESTPERIODIQUE","IDTYPEMAINTENANCE","IDMACHINE","IDLIGNE","IDLIGNELIB","IDSITUATION","IDSITUATIONLIB","UNITE","FREQUENCE","DATEDEBUT","DATEFIN","DUREE","ETAT","HEURE","IDSOURCE","IDMACHINELIB","IDTYPEMAINTENANCELIB","ESTPERIODIQUELIB","ETATLIB","UNITELIB","PRIORITE","PRIORITELIB","IDDEMANDETRAVAUX","IDORDRETRAVAUX","IDORDRETRAVAUXFILLE","IDTRAVAUX","IDENTITE","IDENTITELIB","ETATDEMANDETRAVAUX","ETATORDRETRAVAUX","ETATTRAVAUX","ETATDEMANDETRAVAUXLIB","ETATORDRETRAVAUXLIB","ETATTRAVAUXLIB","COUT","IDDEPARTEMENT","IDDEPARTEMENTLIB","MOTSCLESSS") AS
SELECT P.ID,
       P.REFOBJET,
       P.ESTPERIODIQUE,
       P.IDTYPEMAINTENANCE,
       P.IDMACHINE,
       P.IDLIGNE,
       li.VAL as IDLIGNELIB,
       P.IDSITUATION,
       sit.VAL AS IDSITUATIONLIB,
       P.UNITE,
       P.FREQUENCE,
       P.DATEDEBUT,
       P.DATEFIN,
       P.DUREE,
       P.ETAT,
       P.HEURE,
       P.IDSOURCE,
       AI.LIBELLE                         AS IDMACHINELIB,
       T.VAL                              AS IDTYPEMAINTENANCELIB,
       CASE
           WHEN P.ESTPERIODIQUE = 1 THEN 'OUI'
           ELSE 'NON'
           END                               ESTPERIODIQUELIB,
       CASE
           WHEN P.ETAT = 11 THEN 'VALID&Eacute;E'
           ELSE 'CR&Eacute;E'
           END                               ETATLIB,
       U.VAL                              AS UNITELIB,
       D.PRIORITE,
       D.PRIORITELIB,
       D.ID                               AS IDDEMANDETRAVAUX,
       O.ID                               AS IDORDRETRAVAUX,
       OTF.ID                             AS IDORDRETRAVAUXFILLE,
       TR.ID                              AS IDTRAVAUX,
       E.ID                               AS IDENTITE,
       E.VAL                              AS IDENTITELIB,
       D.ETAT                             AS ETATDEMANDETRAVAUX,
       O.ETAT                             AS ETATORDRETRAVAUX,
       TR.ETAT                            AS ETATTRAVAUX,
       CASE D.ETAT
           WHEN 1 THEN 'Creee'
           WHEN 11 THEN 'Visee'
           ELSE 'Aucun'
           END                            AS ETATDEMANDETRAVAUXLIB,
       CASE O.ETAT
           WHEN 1 THEN 'Creee'
           WHEN 11 THEN 'Visee'
           ELSE 'Aucun'
           END                            AS ETATORDRETRAVAUXLIB,
       CASE TR.ETAT
           WHEN 1 THEN 'Creee'
           WHEN 11 THEN 'Visee'
           WHEN 21 THEN 'Entamee'
           WHEN 41 THEN 'Terminee'
           ELSE 'Aucun'
           END                            AS ETATTRAVAUXLIB,
       COALESCE(SUM(FFF.PU * FFF.QTE), 0) AS COUT,
       AI.PARFUMS                         AS IDDEPARTEMENT,
       dept.VAL                            AS IDDEPARTEMENTLIB,
       (
           NVL(TO_CHAR(P.ID), '') || ' | ' ||
           NVL(TO_CHAR(P.REFOBJET), '') || ' | ' ||
           NVL(TO_CHAR(P.ESTPERIODIQUE), '') || ' | ' ||
           NVL(TO_CHAR(P.IDTYPEMAINTENANCE), '') || ' | ' ||
           NVL(TO_CHAR(P.IDMACHINE), '') || ' | ' ||
           NVL(TO_CHAR(P.UNITE), '') || ' | ' ||
           NVL(TO_CHAR(P.FREQUENCE), '') || ' | ' ||
           NVL(TO_CHAR(P.DATEDEBUT, 'YYYY-MM-DD HH24:MI:SS'), '') || ' | ' ||
           NVL(TO_CHAR(P.DATEFIN, 'YYYY-MM-DD HH24:MI:SS'), '') || ' | ' ||
           NVL(TO_CHAR(P.DUREE), '') || ' | ' ||
           NVL(TO_CHAR(P.ETAT), '') || ' | ' ||
           NVL(TO_CHAR(P.HEURE), '') || ' | ' ||
           NVL(TO_CHAR(P.IDSOURCE), '') || ' | ' ||
           NVL(TO_CHAR(AI.LIBELLE), '') || ' | ' ||
           NVL(TO_CHAR(T.VAL), '') || ' | ' ||
           NVL(TO_CHAR(
                       CASE
                           WHEN P.ESTPERIODIQUE = 1 THEN 'OUI'
                           ELSE 'NON'
                           END
               ), '') || ' | ' ||
           NVL(TO_CHAR(
                       CASE
                           WHEN P.ETAT = 11 THEN 'VALID&Eacute;E'
                           ELSE 'CR&Eacute;E'
                           END
               ), '') || ' | ' ||
           NVL(TO_CHAR(U.VAL), '') || ' | ' ||
           NVL(TO_CHAR(D.PRIORITE), '') || ' | ' ||
           NVL(TO_CHAR(D.PRIORITELIB), '') || ' | ' ||
           NVL(TO_CHAR(D.ID), '') || ' | ' ||
           NVL(TO_CHAR(O.ID), '') || ' | ' ||
           NVL(TO_CHAR(OTF.ID), '') || ' | ' ||
           NVL(TO_CHAR(TR.ID), '') || ' | ' ||
           NVL(TO_CHAR(E.ID), '') || ' | ' ||
           NVL(TO_CHAR(E.VAL), '') || ' | ' ||
           NVL(TO_CHAR(D.ETAT), '') || ' | ' ||
           NVL(TO_CHAR(O.ETAT), '') || ' | ' ||
           NVL(TO_CHAR(TR.ETAT), '') || ' | ' ||
           NVL(TO_CHAR(
                       CASE D.ETAT
                           WHEN 1 THEN 'Creee'
                           WHEN 11 THEN 'Visee'
                           ELSE 'Aucun'
                           END
               ), '') || ' | ' ||
           NVL(TO_CHAR(
                       CASE O.ETAT
                           WHEN 1 THEN 'Creee'
                           WHEN 11 THEN 'Visee'
                           ELSE 'Aucun'
                           END
               ), '') || ' | ' ||
           NVL(TO_CHAR(
                       CASE TR.ETAT
                           WHEN 1 THEN 'Creee'
                           WHEN 11 THEN 'Visee'
                           WHEN 21 THEN 'Entamee'
                           WHEN 41 THEN 'Terminee'
                           ELSE 'Aucun'
                           END
               ), '') || ' | ' ||
           NVL(TO_CHAR(COALESCE(SUM(FFF.PU * FFF.QTE), 0)), '') || ' | ' ||
           NVL(TO_CHAR(AI.PARFUMS), '')
           )                              AS MOTSCLESSS
FROM PLANNING P
         LEFT JOIN AS_INGREDIENT_MAINTENANCE AIM ON AIM.ID = P.IDMACHINE
         LEFT JOIN AS_INGREDIENTS AI ON AI.ID = AIM.IDINGREDIENT
         LEFT JOIN TYPEMAINTENANCE T ON T.ID = P.IDTYPEMAINTENANCE
         LEFT JOIN UNITEMAINTENANCE U ON U.ID = P.UNITE
         LEFT JOIN DEMANDETRAVAUX_CPL D ON D.ID = P.IDSOURCE
         LEFT JOIN ORDRETRAVAUX O ON O.IDBC = D.ID
         LEFT JOIN ORDRETRAVAUXFILLE OTF ON OTF.IDMERE = O.ID
         LEFT JOIN TRAVAUX TR ON TR.IDOFFILLE = OTF.ID
         LEFT JOIN TRAVAUXFILLE TRF ON TRF.IDMERE = TR.ID
         LEFT JOIN ENTITE E ON E.ID = AIM.IDENTITE
         LEFT JOIN FACTUREFOURNISSEUR F ON F.IDREF = TR.ID
         LEFT JOIN FACTUREFOURNISSEURFILLE FFF ON FFF.IDFACTUREFOURNISSEUR = F.ID
         LEFT JOIN DEPARTEMENT dept ON dept.ID = AI.PARFUMS
         LEFT JOIN SITUATION sit ON sit.ID = P.IDSITUATION
         LEFT JOIN LIGNE li ON li.ID = P.IDLIGNE
GROUP BY P.ID, P.REFOBJET, P.ESTPERIODIQUE, P.IDTYPEMAINTENANCE, P.IDMACHINE, P.UNITE,
         P.FREQUENCE, P.DATEDEBUT, P.DATEFIN, P.DUREE, P.ETAT, P.HEURE, P.IDSOURCE,
         AI.LIBELLE, T.VAL, U.VAL,
         D.PRIORITE, D.PRIORITELIB, D.ID, D.ETAT,
         O.ID, O.ETAT,
         OTF.ID,
         TR.ID, TR.ETAT,
         E.ID, E.VAL, AI.PARFUMS, dept.VAL, sit.VAL, li.VAL, P.IDLIGNE, P.IDSITUATION
ORDER BY P.DATEDEBUT
;
-- [633/1309] PLANNING_CR
CREATE OR REPLACE FORCE VIEW "PLANNING_CR" ("NOMBREDEMANDE","NOMBREREALISE","POURCENTAGE") AS
SELECT
    CAST(NULL AS NUMBER(1)) AS NOMBREDEMANDE,
    CAST(NULL AS NUMBER) AS NOMBREREALISE,
    CAST(NULL AS NUMBER(30, 2)) AS pourcentage
FROM DUAL
;
-- [634/1309] PLANNING_DUREENONPROGRAMME
CREATE OR REPLACE FORCE VIEW "PLANNING_DUREENONPROGRAMME" ("DATEDEBUT","ID","IDMACHINELIB","DUREE","DUREENONPROGRAMME") AS
SELECT
    PC.DATEDEBUT,
    PC.IDMACHINE AS ID,
    PC.IDMACHINELIB,
    SUM(PC.DUREE) AS DUREE,
    COALESCE((
         SELECT SUM(T.DUREEESTIMATIF)
         FROM TRAVAUX T
                  LEFT JOIN ORDRETRAVAUXFILLE OT ON T.IDOFFILLE = OT.ID
         WHERE T.ETAT = 11
           AND PC.IDMACHINE = OT.IDINGREDIENTS
           AND T.DATY = PC.DATEDEBUT
    ),0) AS DUREENONPROGRAMME
FROM PLANNING_CPL PC
GROUP BY PC.DATEDEBUT, PC.IDMACHINE, PC.IDMACHINELIB
;
-- [635/1309] PLANPAIEMENTACHATLIB
CREATE OR REPLACE FORCE VIEW "PLANPAIEMENTACHATLIB" ("ID","IDFOURNISSEUR","IDBCF","IDTYPEDEPART","DUREE","TAUX","IDFOURNISSEURLIB","IDTYPEDEPARTLIB") AS
SELECT
    p."ID",p."IDFOURNISSEUR",p."IDBCF",p."IDTYPEDEPART",p."DUREE",p."TAUX",
    f.nom as idFournisseurLib,
    t.val as idTypeDepartLib
FROM planPaiementAchat p
LEFT JOIN FOURNISSEUR f ON f.id = p.idFournisseur
LEFT JOIN typeDepart t on p.idTypeDepart = t.id
;
-- [636/1309] POINTAGECANTINE_CPL
CREATE OR REPLACE FORCE VIEW "POINTAGECANTINE_CPL" ("ID","IDPERSONNEL","IDDEPARTEMENT","MOIS","ANNEE","NOMBRE","DATY","ETAT","MOISLIB","NOMPERSONNEL","MATRICULE","DEPARTEMENTLIB","ETATLIB") AS
SELECT
    pt.ID,
    pt.IDPERSONNEL,
    pt.IDDEPARTEMENT,
    pt.MOIS,
    pt.ANNEE,
    pt.NOMBRE,
    pt.DATY,
    pt.ETAT,

    TO_CHAR(
        TO_DATE(TO_CHAR(pt.mois, 'FM00'), 'MM'),
        'FMMonth',
        'NLS_DATE_LANGUAGE=FRENCH'
    ) AS moisLib,

    log.nom || ' ' || log.prenom AS nomPersonnel,
    pip.matricule,
    dp.val AS departementLib,

    CASE
        WHEN pt.etat = 1 THEN 'CREE'
        WHEN pt.etat = 11 THEN 'VALIDE'
        WHEN pt.etat = 0 THEN 'ANNULE'
        ELSE 'INCONNU'
    END AS etatLib

FROM POINTAGECANTINE pt
LEFT JOIN LOG_PERSONNEL log
ON log.id = pt.idpersonnel

LEFT JOIN PAIE_INFO_PERSONNEL pip
ON pip.id = pt.idpersonnel

LEFT JOIN DEPARTEMENT dp
ON dp.id = pt.iddepartement
;
-- [637/1309] POINTAGEVISEE_VISA_MULTIPLE
CREATE OR REPLACE FORCE VIEW "POINTAGEVISEE_VISA_MULTIPLE" ("ID","IDPERSONNEL","MATRICULE","PERSONNEL","MOISLIB","MOIS","ANNEE","HEURENORMAL","HEURESUPNORMAL","HEURESUPNUIT","HEURESUPFERIE","HEURESUPWEEKEND","ABSENCE","ETAT","DIRECTION","DIRECTIONLIB") AS
SELECT pp.id as id,pp.IDPERSONNEL,lpad(pif.matricule, 5, '0') as matricule, lg.nom || ' ' || lg.prenom as personnel,
       case
           when pp.mois=1 then
               'Janvier'
           when pp.mois=2
               then
               'Fevrier'
           when pp.mois=3
               then
               'Mars'
           when pp.mois=4
               then
               'Avril'
           when pp.mois=5
               then
               'Mai'
           when pp.mois=6
               then
               'Juin'
           when pp.mois=7
               then
               'Juillet'
           when pp.mois=8
               then
               'Aout'
           when pp.mois=9
               then
               'Septembre'
           when pp.mois=10
               then
               'Octobre'
           when pp.mois=11
               then
               'Novembre'
           when pp.mois=12
               then
               'Decembre'
           end as moisLib,
       pp.mois as mois,
       pp.annee,
       sum(nvl(pp.HEURENORMAL,0)) as HEURENORMAL,
       sum(nvl(pp.HEURESUPNORMAL,0)) as HEURESUPNORMAL,
       sum(nvl(pp.HEURESUPNUIT,0)) as HEURESUPNUIT,
       sum(nvl(pp.HEURESUPFERIE,0)) as HEURESUPFERIE,
       sum(nvl(pp.HEURESUPWEEKEND,0)) as HEURESUPWEEKEND,
       sum(nvl(pp.ABSENCE,0)) as ABSENCE,
       pp.etat,
       lg.direction,
       ld.VAL AS directionLib
FROM LOG_PERSONNEL lg
         JOIN Pointage pp ON lg.id = pp.idpersonnel
         JOIN paie_info_personnel pif ON pif.id = lg.id
         LEFT JOIN LOG_DIRECTION ld ON ld.id = pp.DIRECTION
GROUP BY lpad(pif.matricule, 5, '0'), lg.nom || ' ' || lg.prenom, pp.mois, pp.annee, pp.etat,pp.ID,pp.IDPERSONNEL,pp.mois,lg.direction, ld.val
;
-- [638/1309] POINTAGEVISEE_VISA_MULTIPLE_1
CREATE OR REPLACE FORCE VIEW "POINTAGEVISEE_VISA_MULTIPLE_1" ("ID","IDPERSONNEL","MATRICULE","PERSONNEL","MOISLIB","MOIS","ANNEE","HEURENORMAL","HEURESUPNORMAL","HEURESUPNUIT","HEURESUPFERIE","HEURESUPWEEKEND","ABSENCE","ETAT","DIRECTION") AS
SELECT
    pp.id AS id,
    pp.IDPERSONNEL,
    pif.matricule AS matricule,
    CAST(lg.nom || ' ' || lg.prenom AS VARCHAR2(4000)) AS personnel,
    CASE
        WHEN pp.mois = 1 THEN 'Janvier'
        WHEN pp.mois = 2 THEN 'Fevrier'
        WHEN pp.mois = 3 THEN 'Mars'
        WHEN pp.mois = 4 THEN 'Avril'
        WHEN pp.mois = 5 THEN 'Mai'
        WHEN pp.mois = 6 THEN 'Juin'
        WHEN pp.mois = 7 THEN 'Juillet'
        WHEN pp.mois = 8 THEN 'Aout'
        WHEN pp.mois = 9 THEN 'Septembre'
        WHEN pp.mois = 10 THEN 'Octobre'
        WHEN pp.mois = 11 THEN 'Novembre'
        WHEN pp.mois = 12 THEN 'Decembre'
        END AS moisLib,
    pp.mois AS mois,
    pp.annee,
    SUM(NVL(pp.HEURENORMAL, 0)) AS HEURENORMAL,
    SUM(NVL(pp.HEURESUPNORMAL, 0)) AS HEURESUPNORMAL,
    SUM(NVL(pp.HEURESUPNUIT, 0)) AS HEURESUPNUIT,
    SUM(NVL(pp.HEURESUPFERIE, 0)) AS HEURESUPFERIE,
    SUM(NVL(pp.HEURESUPWEEKEND, 0)) AS HEURESUPWEEKEND,
    SUM(NVL(pp.ABSENCE, 0)) AS ABSENCE,
    pp.etat,
    lg.direction
FROM
    LOG_PERSONNEL lg
        JOIN
    Pointage pp ON lg.id = pp.idpersonnel
        JOIN
    paie_info_personnel pif ON pif.id = lg.id
GROUP BY
    pif.matricule,
    CAST(lg.nom || ' ' || lg.prenom AS VARCHAR2(4000)),
    pp.mois,
    pp.annee,
    pp.etat,
    pp.ID,
    pp.IDPERSONNEL,
    lg.direction
;
-- [639/1309] POINTAGE_LIB
CREATE OR REPLACE FORCE VIEW "POINTAGE_LIB" ("ID","IDPERSONNEL","DIRECTION","ANNEE","MOIS","HEURENORMAL","HEURESUPFERIE","HEURESUPNORMAL","HEURESUPNUIT","HEURESUPWEEKEND","ABSENCE","DATY","ETAT","DIRECTIONLIB","MOISLIB","MATRICULE","NOMPERSONNEL") AS
SELECT
    p.ID,
    p.IDPERSONNEL,
    p.direction,
    p.ANNEE,
    p.MOIS,
    p.HEURENORMAL,
    p.HEURESUPFERIE,
    p.HEURESUPNORMAL,
    p.HEURESUPNUIT,
    p.HEURESUPWEEKEND,
    p.ABSENCE,
    p.DATY,
    p.ETAT,
    ld.VAL AS directionLib,
    TO_CHAR(
            TO_DATE(TO_CHAR(p.mois, 'FM00'), 'MM'),
            'FMMonth',
            'NLS_DATE_LANGUAGE=FRENCH'
    ) AS moisLib,
    ec.MATRICULE ,
    ec.nom || ' ' || ec.PRENOM AS nomPersonnel
FROM POINTAGE p
         LEFT JOIN LOG_DIRECTION ld ON ld.id = p.DIRECTION
         LEFT JOIN EMPLOYE_COMPLET ec ON ec.id = p.IDPERSONNEL
;
-- [640/1309] POINT_ACTIF
CREATE OR REPLACE FORCE VIEW "POINT_ACTIF" ("ID","VAL","DESCE","ACTIF") AS
select "ID","VAL","DESCE","ACTIF" from point where actif = 1
;
-- [641/1309] POMPISTELIB
CREATE OR REPLACE FORCE VIEW "POMPISTELIB" ("REFUSER","LOGINUSER","PWDUSER","NOMUSER","ADRUSER","TELUSER","IDROLE") AS
SELECT 
    "REFUSER","LOGINUSER","PWDUSER","NOMUSER","ADRUSER","TELUSER","IDROLE"
FROM 
    UTILISATEUR u 
    where
u.IDROLE = 'pompiste'
;
-- [642/1309] PRECISDETENCAISSEMENT_LIB
CREATE OR REPLACE FORCE VIEW "PRECISDETENCAISSEMENT_LIB" ("ID","IDENCAISSEMENT","IDENCAISSEMENTLIB","IDCATEGORIECAISSE","IDCATEGORIECAISSELIB","IDCLIENT","IDCLIENTLIB","MONTANT","REFERENCE","DATY","IDCAISSE") AS
SELECT
	pde.ID ,
	pde.IDENCAISSEMENT ,
	e.DESIGNATION AS IDENCAISSEMENTLIB,
	pde.IDCATEGORIECAISSE ,
	c.VAL AS IDCATEGORIECAISSELIB,
	pde.IDCLIENT ,
	c2.NOM AS IDCLIENTLIB,
	pde.MONTANT ,
	pde.REFERENCE ,
	pde.DATY,
	e.IDCAISSE 
FROM
	PRECISION_DETAIL_ENCAISSEMENT pde
LEFT JOIN ENCAISSEMENT e ON
	e.ID = pde.IDENCAISSEMENT
LEFT JOIN CATEGORIECAISSE c ON
	c.ID = pde.IDCATEGORIECAISSE
LEFT JOIN CLIENT c2 ON
	c2.ID = pde.IDCLIENT
;
-- [643/1309] PRELEVEMENTCPL
CREATE OR REPLACE FORCE VIEW "PRELEVEMENTCPL" ("ID","IDPRELEVEMENTANTERIEUR","COMPTEUR","DATY","HEURE","IDPOMPISTE","IDPOMPE","ETAT","ETATLIB","IDCAISSE","IDMAGASIN","IDPRODUIT","PUVENTE","MAXPOMPE") AS
SELECT 
p.ID ,
p.IDPRELEVEMENTANTERIEUR ,
p.COMPTEUR ,
p.DATY ,
p.HEURE ,
p.IDPOMPISTE ,
p.IDPOMPE ,
p.ETAT ,
CASE 
	WHEN p.ETAT = 0 
	THEN 'ANNULEE'
	WHEN p.ETAT = 1 
	THEN 'CREE'
	WHEN p.ETAT = 11 
	THEN 'VALIDEE'
END AS ETATLIB,
c.ID AS IDCAISSE,
p2.IDMAGASIN ,
p3.ID AS IDPRODUIT , 
p3.PUVENTE,
p2.MAX AS maxPompe
FROM PRELEVEMENT p 
LEFT JOIN CAISSE c ON c.IDPOMPISTE =  p.IDPOMPISTE 
LEFT JOIN POMPE p2 ON p2.ID = p.IDPOMPE 
LEFT JOIN MAGASIN m ON m.ID = p2.IDMAGASIN 
LEFT JOIN PRODUIT p3 ON p3.ID  = m.IDPRODUIT
;
-- [644/1309] PRELEVEMENTLIB
CREATE OR REPLACE FORCE VIEW "PRELEVEMENTLIB" ("ID","IDPRELEVEMENTANTERIEUR","COMPTEUR","DATY","HEURE","IDPOMPISTE","IDPOMPE","NOMUSER","IDROLE","NOMMAGASIN","DESCRIPTIONMAGASIN","ETAT","ETATLIB","DESIGNATION") AS
SELECT 
    p.ID AS ID,
    p.IDPRELEVEMENTANTERIEUR AS IDPRELEVEMENTANTERIEUR,
    p.COMPTEUR AS COMPTEUR,
    CASE 
  		WHEN p.HEURE IS NULL AND p.DATY IS NOT NULL  
  		THEN TO_DATE((TO_CHAR(p.DATY, 'YYYY-MM-DD') ||' '||'00:00'), 'YYYY-MM-DD HH24:MI')  
  		ELSE 
  		TO_DATE((TO_CHAR(p.DATY, 'YYYY-MM-DD') || ' ' || p.HEURE), 'YYYY-MM-DD HH24:MI')
    END AS DATY,
    p.HEURE AS HEURE,
    p.IDPOMPISTE AS IDPOMPISTE,
    p.IDPOMPE AS IDPOMPE,
    u.NOMUSER AS NOMUSER,
    u.IDROLE AS IDROLE,
    m.VAL AS NOMMAGASIN,
    m.DESCE AS DESCRIPTIONMAGASIN,
    p.ETAT ,
CASE 
	WHEN p.ETAT = 0 
	THEN 'ANNULEE'
	WHEN p.ETAT = 1 
	THEN 'CREE'
	WHEN p.ETAT = 11 
	THEN 'VALIDEE'
	WHEN p.ETAT = 22 
	THEN 'ENCAISSEE'
END AS ETATLIB,
p.DESIGNATION 
FROM 
    PRELEVEMENT p
JOIN 
    UTILISATEUR u ON u.REFUSER = p.IDPOMPISTE
JOIN 
    POMPE p2 ON p2.ID = p.IDPOMPE 
JOIN 
    MAGASINLIB m ON m.ID = p2.IDMAGASIN 
WHERE 
    u.IDROLE = 'pompiste'
;
-- [645/1309] PRELEVEMENTLIB_ANNULEE
CREATE OR REPLACE FORCE VIEW "PRELEVEMENTLIB_ANNULEE" ("ID","IDPRELEVEMENTANTERIEUR","COMPTEUR","DATY","HEURE","IDPOMPISTE","IDPOMPE","NOMUSER","IDROLE","NOMMAGASIN","DESCRIPTIONMAGASIN","ETAT","ETATLIB","DESIGNATION") AS
SELECT 
p."ID",p."IDPRELEVEMENTANTERIEUR",p."COMPTEUR",p."DATY",p."HEURE",p."IDPOMPISTE",p."IDPOMPE",p."NOMUSER",p."IDROLE",p."NOMMAGASIN",p."DESCRIPTIONMAGASIN",p."ETAT",p."ETATLIB",p."DESIGNATION"
FROM PRELEVEMENTLIB p 
WHERE p.ETAT = 0
;
-- [646/1309] PRELEVEMENTLIB_CREE
CREATE OR REPLACE FORCE VIEW "PRELEVEMENTLIB_CREE" ("ID","IDPRELEVEMENTANTERIEUR","COMPTEUR","DATY","HEURE","IDPOMPISTE","IDPOMPE","NOMUSER","IDROLE","NOMMAGASIN","DESCRIPTIONMAGASIN","ETAT","ETATLIB","DESIGNATION") AS
SELECT 
p."ID",p."IDPRELEVEMENTANTERIEUR",p."COMPTEUR",p."DATY",p."HEURE",p."IDPOMPISTE",p."IDPOMPE",p."NOMUSER",p."IDROLE",p."NOMMAGASIN",p."DESCRIPTIONMAGASIN",p."ETAT",p."ETATLIB",p."DESIGNATION"
FROM PRELEVEMENTLIB p 
WHERE p.ETAT = 1
;
-- [647/1309] PRELEVEMENTLIB_ENCAISSEE
CREATE OR REPLACE FORCE VIEW "PRELEVEMENTLIB_ENCAISSEE" ("ID","IDPRELEVEMENTANTERIEUR","COMPTEUR","DATY","HEURE","IDPOMPISTE","IDPOMPE","NOMUSER","IDROLE","NOMMAGASIN","DESCRIPTIONMAGASIN","ETAT","ETATLIB","DESIGNATION") AS
SELECT 
p."ID",p."IDPRELEVEMENTANTERIEUR",p."COMPTEUR",p."DATY",p."HEURE",p."IDPOMPISTE",p."IDPOMPE",p."NOMUSER",p."IDROLE",p."NOMMAGASIN",p."DESCRIPTIONMAGASIN",p."ETAT",p."ETATLIB",p."DESIGNATION"
FROM PRELEVEMENTLIB p 
WHERE p.ETAT = 22
;
-- [648/1309] PRELEVEMENTLIB_VALIDE
CREATE OR REPLACE FORCE VIEW "PRELEVEMENTLIB_VALIDE" ("ID","IDPRELEVEMENTANTERIEUR","COMPTEUR","DATY","HEURE","IDPOMPISTE","IDPOMPE","NOMUSER","IDROLE","NOMMAGASIN","DESCRIPTIONMAGASIN","ETAT","ETATLIB","DESIGNATION","IDPOMPELIB") AS
SELECT
	p.ID,
	p.IDPRELEVEMENTANTERIEUR,
	p.COMPTEUR,
	p.DATY,
	p.HEURE,
	p.IDPOMPISTE,
	p.IDPOMPE,
	p.NOMUSER,
	p.IDROLE,
	p.NOMMAGASIN,
	p.DESCRIPTIONMAGASIN,
	p.ETAT,
	p.ETATLIB,
	p.DESIGNATION,
	p2.val AS IDPOMPELIB
	
FROM
	PRELEVEMENTLIB p
	LEFT JOIN POMPE p2 ON p2.ID = p.IDPOMPE 
WHERE
	p.ETAT >= 11
;
-- [649/1309] PRELEVEMENTLIB_VISEE
CREATE OR REPLACE FORCE VIEW "PRELEVEMENTLIB_VISEE" ("ID","IDPRELEVEMENTANTERIEUR","COMPTEUR","DATY","HEURE","IDPOMPISTE","IDPOMPE","NOMUSER","IDROLE","NOMMAGASIN","DESCRIPTIONMAGASIN","ETAT","ETATLIB","DESIGNATION","IDPOMPELIB") AS
SELECT
	p.ID,
	p.IDPRELEVEMENTANTERIEUR,
	p.COMPTEUR,
	p.DATY,
	p.HEURE,
	p.IDPOMPISTE,
	p.IDPOMPE,
	p.NOMUSER,
	p.IDROLE,
	p.NOMMAGASIN,
	p.DESCRIPTIONMAGASIN,
	p.ETAT,
	p.ETATLIB,
	p.DESIGNATION,
	p2.val AS IDPOMPELIB
	
FROM
	PRELEVEMENTLIB p
	LEFT JOIN POMPE p2 ON p2.ID = p.IDPOMPE 
WHERE
	p.ETAT = 11
;
-- [650/1309] PRELEVEMENTLIB_VISEE_POP
CREATE OR REPLACE FORCE VIEW "PRELEVEMENTLIB_VISEE_POP" ("ID","IDPRELEVEMENTANTERIEUR","COMPTEUR","DATY","HEURE","IDPOMPISTE","IDPOMPE","IDPOMPELIB","NOMUSER","IDROLE","NOMMAGASIN","DESCRIPTIONMAGASIN","ETAT","ETATLIB","DESIGNATION","COMPTEURINIT","DATYINIT") AS
SELECT 
pv.ID,
pv.IDPRELEVEMENTANTERIEUR,
pv.COMPTEUR,
pv.DATY,
pv.HEURE,
pv2.IDPOMPISTE ,
pv2.IDPOMPE ,
pv2.IDPOMPELIB ,
pv2.NOMUSER  ,
pv.IDROLE ,
pv.NOMMAGASIN ,
pv.DESCRIPTIONMAGASIN ,
pv.ETAT ,
pv.ETATLIB ,
pv.DESIGNATION ,
pv2.COMPTEUR AS compteurinit ,
pv2.DATY AS datyinit
FROM PRELEVEMENTLIB_VALIDE pv 
LEFT JOIN PRELEVEMENTLIB_VALIDE pv2 ON pv2.ID = pv.IDPRELEVEMENTANTERIEUR 
WHERE NOT EXISTS (SELECT * FROM  PRELEVEMENT_ENCAISSE pe  WHERE pv.ID =pe.IDPRELEVEMENT)
AND pv.IDPRELEVEMENTANTERIEUR IS NOT  NULL
;
-- [651/1309] PRELEVEMENT_POMPISTE
CREATE OR REPLACE FORCE VIEW "PRELEVEMENT_POMPISTE" ("INDEXF","INDEXO","VENTE","PRODUIT","PU","MONTANT","ID") AS
SELECT 
p2.compteur AS indexF,
p.compteur AS indexO,
p.compteur - p2.compteur AS vente ,
pro.val AS produit,
pro.puvente AS pu,
(p.compteur - p2.compteur) * pro.puvente AS montant,
pe.IDENCAISSEMENT AS ID
FROM PRELEVEMENT p 
JOIN PRELEVEMENT p2 ON p2.id = p.idprelevementanterieur 
JOIN POMPE po ON po.id = p.idpompe 
JOIN MAGASIN m ON m.id = po.idmagasin
JOIN PRODUIT pro ON pro.id = m.idproduit
JOIN PRELEVEMENT_ENCAISSE pe ON pe.IDPRELEVEMENT = p.ID
;
-- [652/1309] PREVISIONFERMEVIDE
CREATE OR REPLACE FORCE VIEW "PREVISIONFERMEVIDE" ("ID","IDPRODUIT","IDPRODUITLIB","IDMAGASIN","DATY","DATYDEBUT","DATYFIN","QTEINITIAL","ENTREE","SORTIE","QTEFINAL","GROUPERPAR") AS
SELECT
    ''  AS id,
    ''  AS idProduit,
    ''  AS idProduitLib,
    ''  AS idMagasin,
    CAST(NULL AS DATE) AS daty,
    CAST(NULL AS DATE) AS datyDebut,
    CAST(NULL AS DATE) AS datyFin,
    CAST(0 AS NUMBER(30,3)) AS qteInitial,
    CAST(0 AS NUMBER(30,3)) AS entree,
    CAST(0 AS NUMBER(30,3)) AS sortie,
    CAST(0 AS NUMBER(30,3)) AS qteFinal,
    '' AS grouperPar
FROM DUAL
;
-- [653/1309] PREVISIONGROUPE
CREATE OR REPLACE FORCE VIEW "PREVISIONGROUPE" ("IDFACTURE","REFERENCE","DATY","DEBIT","CREDIT") AS
SELECT
    COALESCE(v.id, ff.idFactureFournisseur) AS idFacture,
    CASE
        WHEN v.id IS NOT NULL
            THEN 'vente/vente-fiche.jsp&id=' || v.id
        WHEN ff.idFactureFournisseur IS NOT NULL
            THEN 'facturefournisseur/facturefournisseur-fiche.jsp&id=' || ff.idFactureFournisseur
        ELSE NULL
        END AS reference,
    p.daty,
    SUM(p.debit)  AS debit,
    SUM(p.credit) AS credit

FROM prevision p

         LEFT JOIN vente v
                   ON v.id = p.idfacture

         LEFT JOIN facturefournisseurfille ff
                   ON ff.idFactureFournisseur = p.idfacture

GROUP BY
    v.id,
    ff.idFactureFournisseur,
    p.daty
;
-- [654/1309] PREVISIONVALIDE
CREATE OR REPLACE FORCE VIEW "PREVISIONVALIDE" ("ID","DESIGNATION","IDCAISSE","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDORIGINE","IDDEVISE","TAUX","IDTIERS","COMPTE","IDFACTURE") AS
SELECT "ID","DESIGNATION","IDCAISSE","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDORIGINE","IDDEVISE","TAUX","IDTIERS","COMPTE","IDFACTURE" FROM prevision WHERE etat>=1
;
-- [655/1309] PREVISIONAVECMVTCAISSE
CREATE OR REPLACE FORCE VIEW "PREVISIONAVECMVTCAISSE" ("ID","DESIGNATION","IDCAISSE","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDORIGINE","IDDEVISE","TAUX","IDTIERS","COMPTE","IDFACTURE","EFFECTIFDEB","EFFECTIFCRED") AS
SELECT p."ID",p."DESIGNATION",p."IDCAISSE",p."IDVENTEDETAIL",p."IDVIREMENT",p."DEBIT",p."CREDIT",p."DATY",p."ETAT",p."IDOP",p."IDORIGINE",p."IDDEVISE",
  p."TAUX",p."IDTIERS",p."COMPTE",p."IDFACTURE",nvl(m.montantMere*nvl(m.taux,1),0) AS effectifdeb,nvl(m.montantCredit*nvl(m.taux,1),0) AS effectifCred 
FROM PREVISIONVALIDE p LEFT JOIN MvtCaisseSomPrevisionGroup m ON p.id=m.id2
;
-- [656/1309] PREVISION_CPL
CREATE OR REPLACE FORCE VIEW "PREVISION_CPL" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","IDFACTURE","IDRESERVATION","DATEINITIAL","DUREERETARD","MOIS","ANNEE","MOISLIB","SERVICE","IDSERVICELIB") AS
select
	    p.id,
	    p.designation,
	    p.idcaisse,
	    c.val as idcaisselib,
	    p.idventedetail,
	    v.IDVENTE,
	    v2.designation as idventelib,
	    p.idvirement,
	    p.debit,
	    p.credit,
	    p.daty,
	    p.etat,
	    p.idop,
	    o.DESIGNATION as idoplib ,
	    p.idorigine,
	    p.iddevise,
	    p.designation as iddeviselib,
	    p.taux,
	    p.idtiers,
	    p.compte,
	    p.idfacture,
	    v2.IDRESERVATION,
	    p.dateinitial,
	    p.dureeretard,
	    p.mois,
	    p.annee,
	    TO_CHAR(
	            TO_DATE(TO_CHAR(p.mois, 'FM00'), 'MM'),
	            'FMMonth',
	            'NLS_DATE_LANGUAGE=FRENCH'
	    ) AS moisLib,
	    p.SERVICE,
	    s.libelle AS idServiceLib
	from PREVISION p
	         left join caisse c on p.idcaisse = c.id
	         left join VENTE_DETAILS v on p.IDVENTEDETAIL=v.ID
	         left join vente v2 on v2.id=v.IDVENTE
	         left join ORDONNERPAIEMENT o on o.id=p.IDOP
	         LEFT JOIN SERVICE s ON p.SERVICE = s.COMPTE
	         left join devise d on d.id=p.IDDEVISE
;
-- [657/1309] BUDGET_DEPENSE_SUM_VIEW
CREATE OR REPLACE FORCE VIEW "BUDGET_DEPENSE_SUM_VIEW" ("COMPTE","MOIS","ANNEE","MOISLIB","DEPENSES","IDSERVICELIB","SERVICE") AS
select COMPTE,
	       mois,
	       annee,
	       moislib,
	       sum(debit) as depenses,
	       IDSERVICELIB,
	       SERVICE
	from PREVISION_CPL
	group by COMPTE, mois, annee, moislib, IDSERVICELIB, SERVICE
;
-- [658/1309] BUDGET_DEPENSE_SUM_VIEW_BUDGET
CREATE OR REPLACE FORCE VIEW "BUDGET_DEPENSE_SUM_VIEW_BUDGET" ("COMPTE","MOIS","ANNEE","MOISLIB","DEPENSES","IDSERVICELIB","SERVICE") AS
SELECT "COMPTE","MOIS","ANNEE","MOISLIB","DEPENSES","IDSERVICELIB","SERVICE" FROM budget_depense_sum_view WHERE mois IS NOT NULL AND ANNEE IS NOT NULL
;
-- [659/1309] BUDGET_RECETTE_SUM_VIEW
CREATE OR REPLACE FORCE VIEW "BUDGET_RECETTE_SUM_VIEW" ("COMPTE","MOIS","ANNEE","MOISLIB","DEPENSES","IDSERVICELIB","SERVICE") AS
SELECT SQ.COMPTE,
       SQ.MOIS,
       SQ.ANNEE,
       SQ.MOISLIB,
       SQ.DEPENSES,
       SQ.IDSERVICELIB,
       SQ.SERVICE
FROM (
    select COMPTE,
        mois,
        annee,
        moislib,
        sum(credit) as depenses,
        IDSERVICELIB,
        SERVICE
    from PREVISION_CPL
    where mois is not null and ANNEE is not null
    group by COMPTE, mois, annee, moislib, IDSERVICELIB, SERVICE
) SQ
;
-- [660/1309] PREVISION_EFFECTIF
CREATE OR REPLACE FORCE VIEW "PREVISION_EFFECTIF" ("IDPREVISION","EFFECTIFDEBIT","EFFECTIFCREDIT") AS
SELECT 
	p.id AS idprevision,   
	SUM(m.debit) as effectifDebit, 
	SUM(m.credit) as effectifCredit
FROM Prevision p 
join MOUVEMENTCAISSE m on m.idPrevision=p.id 
GROUP BY p.id
;
-- [661/1309] PRIX_MO_PRODUIT
CREATE OR REPLACE FORCE VIEW "PRIX_MO_PRODUIT" ("ID","LIBELLE","PU","CATEGORIEINGREDIENT","CATEGORIELIB") AS
SELECT a.IDPRODUITS AS ID ,a.LIBELLEPRODUIT AS LIBELLE  , SUM(PU) AS PU,CATEGORIEINGREDIENT ,CATEGORIELIB  FROM 
	AS_RECETTE_LIB_CAT a WHERE CATEGORIEINGREDIENT = 'CAT002'
	GROUP BY IDPRODUITS , CATEGORIELIB ,LIBELLEPRODUIT,CATEGORIEINGREDIENT
;
-- [662/1309] PROCESSFABPETRI
CREATE OR REPLACE FORCE VIEW "PROCESSFABPETRI" ("IDHISTORIQUE","DATEHISTORIQUE","HEURE","OBJET","ACTION","IDUTILISATEUR","REFOBJET","ACTEUR","REMARQUE","ECART") AS
SELECT 
p."IDHISTORIQUE",p."DATEHISTORIQUE",p."HEURE",p."OBJET",p."ACTION",p."IDUTILISATEUR",p."REFOBJET",p."ACTEUR",p."REMARQUE",p."ECART" 
FROM PROCESS p 
LEFT JOIN FABRICATION f ON f.ID = p.REFOBJET 
LEFT JOIN FABRICATIONFILLE f2 ON f2.IDMERE = f.ID 
LEFT JOIN AS_INGREDIENTS ai ON ai.id = f2.IDINGREDIENTS  
WHERE ai.IDFOURNISSEUR ='oui' 
AND  p."ACTION"  = 'terminer'
;
-- [663/1309] PROCESSLIB
CREATE OR REPLACE FORCE VIEW "PROCESSLIB" ("IDHISTORIQUE","DATEHISTORIQUE","HEURE","OBJET","REFOBJET","REMARQUE","IDUTILISATEUR","ACTION","ECART","ECARTMINUTES","ACTEUR") AS
SELECT
    p.IDHISTORIQUE ,
    p.DATEHISTORIQUE ,
    p.HEURE ,
    p.OBJET ,
    p.REFOBJET ,
    p.REMARQUE ,
    p.IDUTILISATEUR ,
    p."ACTION" ,
    p.ECART ,
    p.ecart / 60 AS ecartMinutes,
    pers.NOM || ' ' || pers.TELEPHONE AS acteur
FROM
    PROCESS p
        LEFT JOIN PERSONNEL pers ON
        p.acteur = pers.id
;
-- [664/1309] PROCESSMAINTENANCELIB
CREATE OR REPLACE FORCE VIEW "PROCESSMAINTENANCELIB" ("ID","IDPERSONNEL","IDTRAVAUX","DATEDEBUT","DATEFIN","HEUREDEBUT","HEUREFIN","DATETIME_DEBUT","DATETIME_FIN","ECART_SECONDE","ECART_HMS","IDPERSONNELLIB") AS
SELECT
    prc."ID",prc."IDPERSONNEL",prc."IDTRAVAUX",prc."DATEDEBUT",prc."DATEFIN",prc."HEUREDEBUT",prc."HEUREFIN",prc."DATETIME_DEBUT",prc."DATETIME_FIN",
    /* Ecart en secondes */
    ROUND((prc.datetime_fin - prc.datetime_debut) * 86400) AS ecart_seconde,
    /* Ecart format HH:MM:SS */
    LPAD(FLOOR(ROUND((prc.datetime_fin - prc.datetime_debut) * 86400) / 3600), 2, '0')
        || ':' ||
    LPAD(FLOOR(MOD(ROUND((prc.datetime_fin - prc.datetime_debut) * 86400), 3600) / 60), 2, '0')
        || ':' ||
    LPAD(MOD(ROUND((prc.datetime_fin - prc.datetime_debut) * 86400), 60), 2, '0')
                                                           AS ecart_hms,
    p.NOM AS idPersonnelLib
FROM (
         SELECT
             prc.*,

             /* Date + Heure debut */
             prc.DATEDEBUT
                 + (TO_DATE(prc.HEUREDEBUT, 'HH24:MI:SS')
                 - TRUNC(TO_DATE(prc.HEUREDEBUT, 'HH24:MI:SS')))
                 AS datetime_debut,

             /* Date + Heure fin */
             prc.DATEFIN
                 + (TO_DATE(prc.HEUREFIN, 'HH24:MI:SS')
                 - TRUNC(TO_DATE(prc.HEUREFIN, 'HH24:MI:SS')))
                 AS datetime_fin

         FROM ProcessMaintenance prc
     ) prc
         LEFT JOIN PERSONNEL p ON p.ID = prc.IDPERSONNEL
;
-- [665/1309] PROCESSMAINTENANCEGLOBAL
CREATE OR REPLACE FORCE VIEW "PROCESSMAINTENANCEGLOBAL" ("IDTRAVAUX","IDPERSONNEL","DUREEREEL","DUREEREELHMS") AS
SELECT
    pr.IDTRAVAUX,
    pr.IDPERSONNEL,
    sum(pr.ecart_seconde) as dureeReel,
    LPAD(FLOOR(TO_NUMBER(sum(pr.ecart_seconde)) / 3600), 2, '0') || ':' ||
    LPAD(FLOOR(MOD(TO_NUMBER(sum(pr.ecart_seconde)), 3600) / 60), 2, '0') || ':' ||
    LPAD(MOD(TO_NUMBER(sum(pr.ecart_seconde)), 60), 2, '0')
                          AS dureeReelHMS
FROM PROCESSMAINTENANCELIB pr
group by pr.IDTRAVAUX, pr.IDPERSONNEL
;
-- [666/1309] PRODUITCOMMANDE
CREATE OR REPLACE FORCE VIEW "PRODUITCOMMANDE" ("IDBC","PRODUIT","QUANTITEBC") AS
SELECT 
bcf.IDBC ,
bcf.PRODUIT,
sum(bcf.QUANTITE) AS  QUANTITEBC
FROM BONDECOMMANDE_CLIENT_FILLE bcf  
GROUP BY bcf.IDBC,bcf.PRODUIT
;
-- [667/1309] PRODUITCOMMANDEFILLECARTON
CREATE OR REPLACE FORCE VIEW "PRODUITCOMMANDEFILLECARTON" ("ID","IDBC","PRODUITLIB","PRODUIT","QUANTITEBCF","QUANTITECARTONFILLE","RESTECARTONFILLE") AS
SELECT 
bc.ID ,
bc.idbc AS idbc ,
ai.LIBELLE AS produitlib,
ai.id AS produit,
nvl(bc.QUANTITE,0) AS quantiteBCF ,
nvl(c.QUANTITE,0) AS quantitecartonfille,
nvl(bc.QUANTITE,0) - nvl(c.QUANTITE,0) AS restecartonfille
FROM BONDECOMMANDE_CLIENT_FILLE bc 
LEFT JOIN CARTONFILLE c  ON c.IDBCFILLE = bc.ID 
LEFT JOIN AS_INGREDIENTS ai ON ai.ID = bc.PRODUIT
GROUP BY bc.ID, bc.idbc, ai.LIBELLE, ai.id, bc.QUANTITE, c.QUANTITE
;
-- [668/1309] PRODUITSOUSCARTON
CREATE OR REPLACE FORCE VIEW "PRODUITSOUSCARTON" ("IDBC","IDINGREDIENT","QUANTITECARTON") AS
SELECT 
c2.IDBC  ,
c.IDINGREDIENT ,
sum(c.QUANTITE) AS  QUANTITEcarton
FROM CARTONFILLE c 
LEFT JOIN CARTON c2 ON c2.ID =c.IDMERE 
GROUP BY c2.IDBC  , c.IDINGREDIENT
;
-- [669/1309] PRODUITCOMMANDECARTON
CREATE OR REPLACE FORCE VIEW "PRODUITCOMMANDECARTON" ("IDBC","PRODUITLIB","QUANTITEBC","QUANTITECARTON","RESTECARTON") AS
SELECT 
pc.IDBC,
ai.LIBELLE AS produitlib,
nvl(pc.QUANTITEBC,0) AS QUANTITEBC,
nvl(ps.QUANTITEcarton,0) AS QUANTITEcarton,
nvl(pc.QUANTITEBC,0) - nvl(ps.QUANTITEcarton,0) AS restecarton
FROM produitcommande pc 
LEFT JOIN produitsouscarton ps ON ps.IDBC = pc.IDBC AND pc.PRODUIT = ps.IDINGREDIENT 
LEFT JOIN AS_INGREDIENTS ai ON ai.ID = pc.PRODUIT
;
-- [670/1309] PRODUIT_LIB
CREATE OR REPLACE FORCE VIEW "PRODUIT_LIB" ("ID","VAL","DESCE","IDTYPEPRODUIT","IDTYPEPRODUITLIB","PUACHAT","PUVENTE","IDUNITE","IDUNITELIB","IDCATEGORIE","IDCATEGORIELIB","IDSOUSCATEGORIELIB","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT") AS
SELECT p.ID,
       p.LIBELLE as val,
       p.LIBELLE as DESCE,
       '-' as IDTYPEPRODUIT,
       '-' AS IDTYPEPRODUITLIB,
       p.PU as PUACHAT,
       p.pv as PUVENTE,
       p.UNITE as idunite,
       u.VAL  AS IDUNITELIB,
       p.CATEGORIEINGREDIENT as IDCATEGORIE,
       c.VAL  AS IDCATEGORIELIB,
       '-'  AS IDSOUSCATEGORIELIB,
       p.seuilmin,
       p.seuilmax,
       p.puAchatUsd,
  	   p.puAchatEuro,
	   p.puAchatAutreDevise,
	   p.puVenteUsd,
	   p.puVenteEuro,
	   p.puVenteAutreDevise,
	   p.isvente,
	   p.isachat,
	   p.compte_vente,
	   p.compte_achat
FROM AS_INGREDIENTS p
         LEFT JOIN CATEGORIEINGREDIENT c ON c.ID = p.CATEGORIEINGREDIENT
         LEFT JOIN as_UNITE u ON u.ID = p.unite
;
-- [671/1309] AS_BLCLIENTFILLEINSERTION
CREATE OR REPLACE FORCE VIEW "AS_BLCLIENTFILLEINSERTION" ("PRODUITLIB","ID","PRODUIT","NUMBL","QUANTITE","UNITELIB","IDVENTEDETAIL","UNITE","IDBC_FILLE") AS
SELECT
pl.VAL AS PRODUITLIB,
bl.id,
bl.PRODUIT,
bl.NUMBL,
bl.QUANTITE,
pl.IDUNITELIB AS UNITELIB,
bl.IDVENTEDETAIL,
bl.UNITE,
bl.IDBC_FILLE
FROM 
AS_BONDELIVRAISON_CLIENT_FILLE bl
JOIN PRODUIT_LIB pl ON bl.PRODUIT = pl.ID
;
-- [672/1309] PRODUIT_ACHAT_LIB_MGA
CREATE OR REPLACE FORCE VIEW "PRODUIT_ACHAT_LIB_MGA" ("ID","VAL","DESCE","IDTYPEPRODUIT","IDTYPEPRODUITLIB","PUACHAT","PUVENTE","IDUNITE","IDUNITELIB","IDCATEGORIE","IDCATEGORIELIB","IDSOUSCATEGORIELIB","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","TAUX","ISVENTE","COMPTE") AS
SELECT 
 pl.ID,
       pl.VAL,
       pl.DESCE,
       pl.IDTYPEPRODUIT,
       pl.IDTYPEPRODUITLIB,
       CAST(pl.PUACHAT*1 AS number(30,2)) AS  PUACHAT,
       CAST(pl.PUVENTE*1 AS number(30,2)) AS PUVENTE,
       pl.IDUNITE,
       pl.IDUNITELIB,
       pl.IDCATEGORIE,
       pl.IDCATEGORIELIB,
       pl.IDSOUSCATEGORIELIB,
       pl.seuilmin,
       pl.seuilmax,
       pl.puAchatUsd,
  	   pl.puAchatEuro,
	   pl.puAchatAutreDevise,
	   pl.puVenteUsd,
	   pl.puVenteEuro,
	   pl.puVenteAutreDevise,
	   1 AS taux,
	   pl.isvente,
	   pl.compte_achat AS compte
FROM PRODUIT_LIB pl 
WHERE pl.isAchat=1
;
-- [673/1309] PRODUIT_LIBCPL
CREATE OR REPLACE FORCE VIEW "PRODUIT_LIBCPL" ("ID","LIBELLE","PU","PV","UNITE","CATEGORIEINGREDIENT","COMPTE_VENTE","IDUNITELIB","CATEGORIELIB","SEUILMIN","SEUILMAX") AS
select p.ID,p.LIBELLE ,p.pu,p.pv,p.UNITE ,p.CATEGORIEINGREDIENT , p.COMPTE_VENTE ,
       uni.VAL as idunitelib,
       ga.VAL as categorielib,
       p.seuilmin,
       p.seuilmax
from AS_INGREDIENTS p 
         left join AS_UNITE uni on uni.ID = p.UNITE 
         left join CATEGORIEINGREDIENT ga on ga.ID = p.CATEGORIEINGREDIENT
;
-- [674/1309] AVOIR_MF
CREATE OR REPLACE FORCE VIEW "AVOIR_MF" ("ID","IDAVOIRFC","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDCLIENT","MONTANTHT","MONTANTTVA","MONTANTTTC","TAUXDECHANGE","COMPTE") AS
select vd.ID,vd.idavoirfc,vd.IDPRODUIT,vd.IDORIGINE,vd.QTE,vd.PU,vd.REMISE,vd.TVA,vd.PUACHAT,vd.PUVENTE,
		v.DESIGNATION,
       v.IDMAGASIN,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       v.IDCLIENT,
         cast((vd.PU * vd.qte) as NUMBER(30, 2)) as montantHT,
       cast((vd.PU * vd.qte*(vd.tva/100)) as NUMBER(30, 2)) as montantTVA,
       cast(vd.PU * vd.qte + (vd.PU * vd.qte*(vd.tva/100))  as NUMBER(30, 2)) as montantTTC,
       vd.TAUXDECHANGE AS tauxdechange,
       p.COMPTE_VENTE AS compte
from avoirfcfille vd
 left outer join AVOIRFC  V on V.ID = vd.idavoirfc
         left outer join PRODUIT_LIBCPL p on p.ID = vd.IDPRODUIT
;
-- [675/1309] AVOIRFC_GRP_TOUS
CREATE OR REPLACE FORCE VIEW "AVOIRFC_GRP_TOUS" ("IDAVOIRFC","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","ETAT","TAUXDECHANGE") AS
select idavoirfc,
       compte,
       cast(sum(montantHT) as NUMBER(30, 2)) as montantHT,
       cast(sum(montantTVA) as NUMBER(30, 2)) as montantTVA,
       cast(sum(montantTTC) as NUMBER(30, 2)) as montantTTC,
       cast(sum(montantHT * TAUXDECHANGE) as NUMBER(30, 2)) as montantHTAR,
       cast(sum(montantTVA * TAUXDECHANGE) as NUMBER(30, 2)) as montantTVAAR,
       cast(sum(montantTTC * TAUXDECHANGE) as NUMBER(30, 2)) as montantTTCAR,
       ETAT,
       max(TAUXDECHANGE) AS TAUXDECHANGE 
from AVOIR_MF
group by idavoirfc, compte, etat
;
-- [676/1309] AVOIRFC_GRP_ANNULEE
CREATE OR REPLACE FORCE VIEW "AVOIRFC_GRP_ANNULEE" ("IDAVOIRFC","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","ETAT","TAUXDECHANGE") AS
select "IDAVOIRFC","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","ETAT","TAUXDECHANGE" from AVOIRFC_GRP_TOUS where etat < 1
;
-- [677/1309] AVOIRFC_GRP_CREEE
CREATE OR REPLACE FORCE VIEW "AVOIRFC_GRP_CREEE" ("IDAVOIRFC","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","ETAT","TAUXDECHANGE") AS
select "IDAVOIRFC","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","ETAT","TAUXDECHANGE" from AVOIRFC_GRP_TOUS where etat = 1
;
-- [678/1309] AVOIRFC_GRP_VISEE
CREATE OR REPLACE FORCE VIEW "AVOIRFC_GRP_VISEE" ("IDAVOIRFC","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","ETAT","TAUXDECHANGE") AS
select "IDAVOIRFC","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","ETAT","TAUXDECHANGE" from AVOIRFC_GRP_TOUS where etat >= 11
;
-- [679/1309] AVOIRFC_MERE_MONTANT
CREATE OR REPLACE FORCE VIEW "AVOIRFC_MERE_MONTANT" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","TAUXDECHANGE","CLIENTLIB","COMPTE") AS
select v.ID,v.DESIGNATION,v.IDMAGASIN,v.DATY,v.REMARQUE,v.ETAT,v.IDORIGINE,v.IDCLIENT,
       vt.MONTANTHT,
       vt.MONTANTTVA,
       vt.MONTANTTTC,
       vt.MONTANTHTAR,
       vt.MONTANTTVAAR,
       vt.MONTANTTTCAR,
       vt.TAUXDECHANGE,
        CL.NOM AS CLIENTLIB,
       CL.COMPTE
from AVOIRFC v
left join AVOIRFC_GRP_TOUS vt on vt.IDAVOIRFC = v.id
left join CLIENT CL on CL.ID = v.IDCLIENT
;
-- [680/1309] FACTUREDECLARATION_FILLECPL
CREATE OR REPLACE FORCE VIEW "FACTUREDECLARATION_FILLECPL" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","QTE","PU","REMISES","IDBCDETAIL","TVA","PRODUITLIB","COMPTE","ETAT","IDDEVISE","TAUXDECHANGE") AS
select ff.ID,
       ff.IDFACTUREFOURNISSEUR,
       ff.IDPRODUIT,
       ff.QTE,
       ff.PU,
       ff.REMISES,
       ff.IDBCDETAIL,
       ff.TVA,
       p.LIBELLE as produitlib,
       ff.compte,
       f.ETAT,
       ff.iddevise,
       ff.tauxdechange
from FACTUREDECLARATIONFILLE ff
         left join PRODUIT_LIBCPL p on p.id = ff.idproduit
         left join FACTUREDECLARATION F on F.ID = ff.IDFACTUREFOURNISSEUR
;
-- [681/1309] FACTUREDECLARATION_FILLECOMPTE
CREATE OR REPLACE FORCE VIEW "FACTUREDECLARATION_FILLECOMPTE" ("COMPTE","IDFACTUREFOURNISSEUR","ETAT","MONTANTHT","MONTANTTVA","MONTANTTTC","IDDEVISE","TAUXDECHANGE") AS
select ff.COMPTE,
       ff.IDFACTUREFOURNISSEUR,
       ff.etat,
       cast(sum(pu * QTE) as number(30, 2))                            as montantht,
       cast(sum(pu * QTE * (tva / 100)) as number(30, 2))              as montanttva,
       cast(sum((pu * QTE) + pu * QTE * (tva / 100)) as number(30, 2)) as montantttc,
       ff.iddevise,
       ff.tauxdechange
from FACTUREDECLARATION_FILLECPL ff
group by COMPTE, IDFACTUREFOURNISSEUR, ff.etat,ff.iddevise,ff.tauxdechange
;
-- [682/1309] FACTUREDECLARATION_FILLE_VISE
CREATE OR REPLACE FORCE VIEW "FACTUREDECLARATION_FILLE_VISE" ("COMPTE","IDFACTUREFOURNISSEUR","ETAT","MONTANTHT","MONTANTTVA","MONTANTTTC","IDDEVISE","TAUXDECHANGE") AS
select COMPTE,IDFACTUREFOURNISSEUR,ETAT,MONTANTHT,MONTANTTVA,MONTANTTTC,iddevise,tauxdechange
from FACTUREDECLARATION_FILLECOMPTE
where etat = 11
;
-- [683/1309] FACTUREFOURNISSEUR_FILLECPL
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_FILLECPL" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","QTE","PU","REMISES","IDBCDETAIL","TVA","PRODUITLIB","COMPTE","ETAT","IDDEVISE","TAUXDECHANGE","MOIS","ANNEE") AS
select ff.ID,
	       ff.IDFACTUREFOURNISSEUR,
	       ff.IDPRODUIT,
	       ff.QTE,
	       ff.PU,
	       ff.REMISES,
	       ff.IDBCDETAIL,
	       ff.TVA,
	       p.LIBELLE as produitlib,
	       ff.compte,
	       f.ETAT,
	       ff.iddevise,
	       ff.tauxdechange,
	       ff.MOIS,
	       ff.ANNEE
	from FACTUREFOURNISSEURFILLE ff
	    left join PRODUIT_LIBCPL p on p.id = ff.idproduit
	    left join FACTUREFOURNISSEUR F on F.ID = ff.IDFACTUREFOURNISSEUR
;
-- [684/1309] FACTUREFOURNISSEURFILLE_PAYE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURFILLE_PAYE" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","QTE","PU","REMISES","IDBCDETAIL","TVA","PRODUITLIB","COMPTE","COMPTEREGR","ETAT","IDDEVISE","TAUXDECHANGE","MONTANTTTC","MOIS","ANNEE","DATY","POURCENTAGEPAYE","MONTANTFILLEPAYE","RESTEAPAYERFILLE","MONTANTFILLEPAYEAR","MONTANTFILLE","SERVICE") AS
SELECT FFF.ID,
	       FFF.IDFACTUREFOURNISSEUR,
	       FFF.IDPRODUIT,
	       FFF.QTE,
	       FFF.PU,
	       FFF.REMISES,
	       FFF.IDBCDETAIL,
	       FFF.TVA,
	       FFF.PRODUITLIB,
	       FFF.COMPTE,
	       FFF.COMPTE                                                               AS compteregr,
	       FFF.ETAT,
	       FFF.IDDEVISE,
	       FFF.TAUXDECHANGE,
	       FF.MONTANTTTC,
	       FFF.MOIS,
	       FFF.ANNEE,
	       FF.DATY,
	       FF.MONTANTPAYE * 100 / NULLIF(FF.MONTANTTTC, 0)                                                     AS pourcentagepaye,
	       (FF.MONTANTPAYE / NULLIF(FF.MONTANTTTC, 0)) * (FFF.QTE * FFF.PU)                                    AS MontantFillePaye,
	       (FFF.QTE * FFF.PU) - ((FF.MONTANTPAYE / NULLIF(FF.MONTANTTTC, 0)) * (FFF.QTE * FFF.PU))             AS resteapayerfille,
	       ((FF.MONTANTPAYE / NULLIF(FF.MONTANTTTC, 0)) * (FFF.QTE * FFF.PU)) * FFF.TAUXDECHANGE               AS MontantFillePayeAr,
	       (FFF.QTE * FFF.PU)                                                                                   AS montantfille,
	       FF.SERVICE
	FROM FACTUREFOURNISSEUR_FILLECPL FFF
	         LEFT JOIN FACTUREFOURNISSEURCPL FF ON FF.ID = FFF.IDFACTUREFOURNISSEUR
;
-- [685/1309] FACTUREFOURNISSEUR_COMPTEREGR
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_COMPTEREGR" ("COMPTEREGR","MOIS","ANNEE","MONTANT","MONTANTPAYE","RESTEAPAYER") AS
select compteregr,
	       mois,
	       annee,
	       sum(montantfille * TAUXDECHANGE)     as montant,
	       sum(MontantFillePaye * TAUXDECHANGE) as montantpaye,
	       sum(resteapayerfille * TAUXDECHANGE) as resteapayer
	from facturefournisseurfille_paye
	group by compteregr, mois, annee
;
-- [686/1309] FACTUREFOURNISSEUR_FILLE_ECR
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_FILLE_ECR" ("COMPTE","IDFACTUREFOURNISSEUR","ETAT","MONTANTHT","MONTANTTVA","MONTANTTTC","IDDEVISE","TAUXDECHANGE","IDPRODUIT") AS
select ff.COMPTE,
       ff.IDFACTUREFOURNISSEUR,
       ff.etat,
       cast(sum(ff.pu * ff.QTE) as number(30, 2))                            as montantht,
       cast(sum(ff.pu * ff.QTE * (ff.tva / 100)) as number(30, 2))              as montanttva,
       cast(sum((ff.pu * ff.QTE) + ff.pu * ff.QTE * (ff.tva / 100)) as number(30, 2)) as montantttc,
       ff.iddevise,
       ff.tauxdechange,
       ing.ID as IDPRODUIT
from FACTUREFOURNISSEUR_FILLECPL ff left join AS_INGREDIENTS ing on ing.id=ff.IDPRODUIT
group by COMPTE, IDFACTUREFOURNISSEUR, ff.etat,ff.iddevise,ff.tauxdechange, ing.ID
;
-- [687/1309] FACTUREFOURNISSEUR_FILLE_MERE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_FILLE_MERE" ("IDFACTUREFOURNISSEUR","MONTANT") AS
select IDFACTUREFOURNISSEUR,
       cast(sum(PU * QTE) as number(30, 2)) as montant
from FACTUREFOURNISSEUR_FILLECPL
group by IDFACTUREFOURNISSEUR
;
-- [688/1309] FACTUREFOURNISSEUR_FL_COMPTE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_FL_COMPTE" ("COMPTE","IDFACTUREFOURNISSEUR","MONTANTHT","IDDEVISE","TAUXDECHANGE") AS
SELECT 
ff.compte,
ff.idfacturefournisseur,
cast(sum(ff.pu * ff.QTE) as number(30, 2))                            as montantht,
ff.iddevise,
ff.tauxdechange
FROM FACTUREFOURNISSEUR_FILLECPL ff
GROUP BY compte, IDFACTUREFOURNISSEUR, iddevise, tauxdechange
;
-- [689/1309] FACTUREFOURNISSEUR_FL_TVA
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_FL_TVA" ("COMPTE","IDFACTUREFOURNISSEUR","MONTANTHT","IDDEVISE","TAUXDECHANGE") AS
SELECT
    nvl(ai.compte_tva, '445600') AS compte,
    ff.idfacturefournisseur,
    cast(sum(ff.pu * ff.QTE * (ff.tva / 100)) as number(30, 2))              as montanttva,
    ff.iddevise,
    ff.tauxdechange
FROM FACTUREFOURNISSEUR_FILLECPL ff
         LEFT JOIN AS_INGREDIENTS ai ON ai.id = ff.idproduit
GROUP BY ai.compte_tva, IDFACTUREFOURNISSEUR, iddevise, tauxdechange
;
-- [690/1309] FACTUREFOURNISSEUR_FL_ERITURE
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEUR_FL_ERITURE" ("COMPTE","IDFACTUREFOURNISSEUR","MONTANTHT","IDDEVISE","TAUXDECHANGE") AS
select "COMPTE","IDFACTUREFOURNISSEUR",cast (MONTANTHT as NUMBER(32,2)) as montantHT,"IDDEVISE","TAUXDECHANGE" from (
SELECT "COMPTE","IDFACTUREFOURNISSEUR",cast (MONTANTHT as NUMBER(32,2)) as montantHT,"IDDEVISE","TAUXDECHANGE" FROM FACTUREFOURNISSEUR_FL_COMPTE UNION ALL
SELECT "COMPTE","IDFACTUREFOURNISSEUR",cast ("MONTANTHT"as NUMBER(32,2)) as montantHT,"IDDEVISE","TAUXDECHANGE" FROM FACTUREFOURNISSEUR_FL_TVA)
;
-- [691/1309] PRODUIT_LIB_MGA
CREATE OR REPLACE FORCE VIEW "PRODUIT_LIB_MGA" ("ID","VAL","DESCE","IDTYPEPRODUIT","IDTYPEPRODUITLIB","PUACHAT","PUVENTE","IDUNITE","IDUNITELIB","IDCATEGORIE","IDCATEGORIELIB","IDSOUSCATEGORIELIB","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","TAUX","ISVENTE","COMPTE") AS
SELECT
	   pl.ID,
       pl.VAL,
       pl.DESCE,
       pl.IDTYPEPRODUIT,
       pl.IDTYPEPRODUITLIB,
       pl.PUACHAT*1 AS  PUACHAT,
       pl.PUVENTE*1 AS PUVENTE,
       pl.IDUNITE,
       pl.IDUNITELIB,
       pl.IDCATEGORIE,
       pl.IDCATEGORIELIB,
       pl.IDSOUSCATEGORIELIB,
       pl.seuilmin,
       pl.seuilmax,
       pl.puAchatUsd,
  	   pl.puAchatEuro,
	   pl.puAchatAutreDevise,
	   pl.puVenteUsd,
	   pl.puVenteEuro,
	   pl.puVenteAutreDevise,
	   1 AS taux,
	   pl.isvente,
	   pl.compte_vente AS compte
FROM PRODUIT_LIB pl
WHERE pl.PUVENTE>0
;
-- [692/1309] PRODUIT_LIB_MGAASYNC
CREATE OR REPLACE FORCE VIEW "PRODUIT_LIB_MGAASYNC" ("ID","VAL","DESCE","IDTYPEPRODUIT","IDTYPEPRODUITLIB","PUACHAT","PUVENTE","IDUNITE","IDUNITELIB","IDCATEGORIE","IDCATEGORIELIB","IDSOUSCATEGORIELIB","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","TAUX","ISVENTE","COMPTE") AS
SELECT
	   pl.ID,
       pl.VAL,
       pl.DESCE,
       pl.IDTYPEPRODUIT,
       pl.IDTYPEPRODUITLIB,
       pl.PUACHAT*1 AS  PUACHAT,
       pl.PUVENTE*1 AS PUVENTE,
       pl.IDUNITE,
       pl.IDUNITELIB,
       pl.IDCATEGORIE,
       pl.IDCATEGORIELIB,
       pl.IDSOUSCATEGORIELIB,
       pl.seuilmin,
       pl.seuilmax,
       pl.puAchatUsd,
  	   pl.puAchatEuro,
	   pl.puAchatAutreDevise,
	   pl.puVenteUsd,
	   pl.puVenteEuro,
	   pl.puVenteAutreDevise,
	   1 AS taux,
	   pl.isvente,
	   pl.compte_vente AS compte
FROM PRODUIT_LIB pl
WHERE pl.isvente=1
;
-- [693/1309] PROFORMACOMMADER
CREATE OR REPLACE FORCE VIEW "PROFORMACOMMADER" ("PRODUIT","QUANTITE","IDPROFORMA") AS
select PRODUIT, sum(QUANTITE) as quantite, bc.IDPROFORMA from BONDECOMMANDE_CLIENT_FILLE bcf join BONDECOMMANDE_CLIENT bc on bc.id=bcf.IDBC where bc.ETAT>=11 group by PRODUIT, bc.IDPROFORMA
;
-- [694/1309] PROFORMADETAILS_CPL
CREATE OR REPLACE FORCE VIEW "PROFORMADETAILS_CPL" ("ID","IDPROFORMA","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","COMPTE","PUREVIENT","IDDEMANDEPRIXFILLE","IDPROFORMALIB","IDPRODUITLIB","PUTOTAL","UNITE","UNITELIB","REMISEMONTANT","MONTANTRISTOURNE","FRAISTRANSPORT","MONTANTTOTAL","MONTANTTVA","MONTANTTTC","DATEDEBUT","CALORIE","RISTOURNE","POIDSPARKILO","FRAISLIVRAISON","POIDSTOTAL","RESTEBC","REMISEARBIOCHEM","RISTOURNEARBIOCHEM") AS
SELECT vd.ID,
       vd.IDPROFORMA,
       vd.IDPRODUIT,
       vd.IDORIGINE,
       vd.QTE,
       vd.PU,
       vd.REMISE,
       vd.TVA,
       vd.PUACHAT,
       vd.PUVENTE,
       v.IDDEVISE,
       vd.TAUXDECHANGE,
       vd.DESIGNATION,
       vd.COMPTE,
       vd.PUREVIENT,
       vd.IDDEMANDEPRIXFILLE,
       v.DESIGNATION                                                                                       AS IDPROFORMALIB,
       nvl(p.LIBELLEVENTE,p.libelle)                                                                                           AS IDPRODUITLIB,
       cast((vd.QTE * vd.PU) as NUMBER(30, 2))                                                             AS puTotal,
       vd.unite,
       au.val                                                                                              AS uniteLib,
       cast(((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2))                                 AS remisemontant,
       cast((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) * nvl(vd.ristourne, 0) /
             100) as number(30, 2))                                                                                               as montantristourne,
       cast(nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0) as number(30, 2))                                as fraistransport,
       cast((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
             (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) * nvl(vd.ristourne, 0) /
              100)) -
            nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0) as number(30 ,2))                                                       as montanttotal,
       cast((nvl(vd.TVA, 0) / 100) *
            ((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
              (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) *
               nvl(vd.ristourne, 0) /
               100)) -
             nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0)) as number(30,2))                                                     as montanttva,
       cast(((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
              (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) *
               nvl(vd.ristourne, 0) /
               100)) - nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0)) + (nvl(vd.TVA, 0) / 100) *
                                                                        ((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
                                                                          (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) *
                                                                           nvl(vd.ristourne, 0) / 100)) -
                                                                         p.CALORIE * vd.QTE *
                                                                         v.fraislivraison) as number(30, 2))                      as montantttc,
       vd.datedebut,
       cast(nvl(p.calorie, 0) as number(10,2))                                                                                   as CALORIE,
       vd.ristourne                                                                                        as ristourne,
       cast(p.CALORIE as number(30, 2))                                                                    as poidsparkilo,
       cast(v.fraislivraison as number(30, 2))                                                             as fraislivraison,
       cast(p.CALORIE * vd.QTE as number(30, 2))                                                           as poidstotal,
       ((nvl(vd.qte,0) - nvl(pfc.QUANTITE,0) ) +  nvl(bcr.QUANTITE,0) )as restebc,
       vd.remiseArbiochem,
       vd.ristourneArbiochem
--       d2.id AS idDevis
FROM PROFORMA_DETAILS vd
         LEFT JOIN PROFORMA v ON v.ID = vd.IDPROFORMA
         LEFT JOIN AS_INGREDIENTS p ON p.ID = vd.IDPRODUIT
         LEFT JOIN AS_UNITE au ON au.id = vd.unite
         LEFT JOIN PROFORMACOMMADER pfc on pfc.IDPROFORMA=v.ID and vd.IDPRODUIT=pfc.PRODUIT
         LEFT JOIN BONDECOMMANDEFACTURER bcr on v.id=bcr.IDPROFORMA and bcr.PRODUIT=vd.IDPRODUIT
order by p.LIBELLEVENTE asc
;
-- [695/1309] PROFORMADETAILS_CPL2
CREATE OR REPLACE FORCE VIEW "PROFORMADETAILS_CPL2" ("ID","IDPROFORMA","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","COMPTE","PUREVIENT","IDDEMANDEPRIXFILLE","IDPROFORMALIB","IDPRODUITLIB","PUTOTAL","UNITE","UNITELIB","REMISEMONTANT","MONTANTRISTOURNE","FRAISTRANSPORT","MONTANTTOTAL","MONTANTTVA","MONTANTTTC","DATEDEBUT","CALORIE","RISTOURNE","POIDSPARKILO","FRAISLIVRAISON","POIDSTOTAL","RESTEBC","REMISEARBIOCHEM","RISTOURNEARBIOCHEM") AS
SELECT vd.ID,
       vd.IDPROFORMA,
       vd.IDPRODUIT,
       vd.IDORIGINE,
       vd.QTE,
       vd.PU,
       vd.REMISE,
       vd.TVA,
       vd.PUACHAT,
       vd.PUVENTE,
       v.IDDEVISE,
       vd.TAUXDECHANGE,
       vd.DESIGNATION,
       vd.COMPTE,
       vd.PUREVIENT,
       vd.IDDEMANDEPRIXFILLE,
       v.DESIGNATION AS IDPROFORMALIB,
       NVL(p.LIBELLEVENTE, p.libelle) AS IDPRODUITLIB,
       CAST((vd.QTE * vd.PU) AS NUMBER(30, 2)) AS puTotal,
       vd.unite,
       au.val AS uniteLib,
       CAST(((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0))) AS NUMBER(30, 2)) AS remisemontant,
       CAST((
           ((vd.QTE * vd.PU - ((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0)))) * NVL(vd.ristourne, 0) / 100)
               + (vd.QTE * NVL(vd.ristourneArbiochem, 0))
           ) AS NUMBER(30, 2)) AS montantristourne,
       CAST(NVL(p.CALORIE * vd.QTE * v.fraislivraison, 0) AS NUMBER(30, 2)) AS fraistransport,
       CAST((
           (vd.QTE * vd.PU)
               - ((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0)))
               - (
               ((vd.QTE * vd.PU - ((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0)))) * NVL(vd.ristourne, 0) / 100)
                   + (vd.QTE * NVL(vd.ristourneArbiochem, 0))
               )
               - NVL(p.CALORIE * vd.QTE * v.fraislivraison, 0)
           ) AS NUMBER(30, 2)) AS montanttotal,
       CAST((
           (NVL(vd.TVA, 0) / 100) * (
               (vd.QTE * vd.PU)
                   - ((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0)))
                   - (
                   ((vd.QTE * vd.PU - ((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0)))) * NVL(vd.ristourne, 0) / 100)
                       + (vd.QTE * NVL(vd.ristourneArbiochem, 0))
                   )
                   - NVL(p.CALORIE * vd.QTE * v.fraislivraison, 0)
               )
           ) AS NUMBER(30, 2)) AS montanttva,
       CAST((
           (
               (vd.QTE * vd.PU)
                   - ((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0)))
                   - (
                   ((vd.QTE * vd.PU - ((vd.QTE * vd.PU * NVL(vd.remise, 0) / 100) + (vd.QTE * NVL(vd.remiseArbiochem, 0)))) * NVL(vd.ristourne, 0) / 100)
                       + (vd.QTE * NVL(vd.ristourneArbiochem, 0))
                   )
                   - NVL(p.CALORIE * vd.QTE * v.fraislivraison, 0)
               ) * (1 + NVL(vd.TVA, 0) / 100)
           ) AS NUMBER(30, 2)) AS montantttc,
       vd.datedebut,
       CAST(NVL(p.calorie, 0) AS NUMBER(10, 2)) AS CALORIE,
       vd.ristourne AS ristourne,
       CAST(p.CALORIE AS NUMBER(30, 2)) AS poidsparkilo,
       CAST(v.fraislivraison AS NUMBER(30, 2)) AS fraislivraison,
       CAST(p.CALORIE * vd.QTE AS NUMBER(30, 2)) AS poidstotal,
       ((NVL(vd.qte, 0) - NVL(pfc.QUANTITE, 0)) + NVL(bcr.QUANTITE, 0)) AS restebc,
       CAST(NVL(vd.remiseArbiochem, 0) AS NUMBER(30, 2)) AS remiseArbiochem,
       CAST(NVL(vd.ristourneArbiochem, 0) AS NUMBER(30, 2)) AS ristourneArbiochem
FROM PROFORMA_DETAILS vd
         LEFT JOIN PROFORMA v ON v.ID = vd.IDPROFORMA
         LEFT JOIN AS_INGREDIENTS p ON p.ID = vd.IDPRODUIT
         LEFT JOIN AS_UNITE au ON au.id = vd.unite
         LEFT JOIN PROFORMACOMMADER pfc ON pfc.IDPROFORMA = v.ID AND vd.IDPRODUIT = pfc.PRODUIT
         LEFT JOIN BONDECOMMANDEFACTURER bcr ON v.id = bcr.IDPROFORMA AND bcr.PRODUIT = vd.IDPRODUIT
ORDER BY p.LIBELLEVENTE ASC
;
-- [696/1309] PROFORMADETAILS_CPL_ING
CREATE OR REPLACE FORCE VIEW "PROFORMADETAILS_CPL_ING" ("ID","IDPROFORMA","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","COMPTE","PUREVIENT","IDDEMANDEPRIXFILLE","IDPROFORMALIB","IDPRODUITLIB","PUTOTAL","UNITE","UNITELIB","REMISEMONTANT","MONTANTRISTOURNE","FRAISTRANSPORT","MONTANTTOTAL","MONTANTTVA","MONTANTTTC","DATEDEBUT","CALORIE","RISTOURNE","POIDSPARKILO","FRAISLIVRAISON","POIDSTOTAL","PUINGREDIENT","CONTENUE") AS
SELECT vd.ID,
       vd.IDPROFORMA,
       vd.IDPRODUIT,
       vd.IDORIGINE,
       vd.QTE,
       vd.PU,
       vd.REMISE,
       vd.TVA,
       vd.PUACHAT,
       vd.PUVENTE,
       v.IDDEVISE,
       vd.TAUXDECHANGE,
       vd.DESIGNATION,
       vd.COMPTE,
       vd.PUREVIENT,
       vd.IDDEMANDEPRIXFILLE,
       v.DESIGNATION                                                                                       AS IDPROFORMALIB,
       p.LIBELLEVENTE                                                                                           AS IDPRODUITLIB,
       cast((vd.QTE * vd.PU) as NUMBER(30, 2))                                                             AS puTotal,
       vd.unite,
       au.val                                                                                              AS uniteLib,
       cast(((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2))                                 AS remisemontant,
       cast((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) * nvl(vd.ristourne, 0) /
             100) as number(30, 2))                                                                                               as montantristourne,
       cast(nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0) as number(30, 2))                                as fraistransport,
       cast((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
             (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) * nvl(vd.ristourne, 0) /
              100)) -
            nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0) as number(30 ,2))                                                       as montanttotal,
       cast((nvl(vd.TVA, 0) / 100) *
            ((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
              (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) *
               nvl(vd.ristourne, 0) /
               100)) -
             nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0)) as number(30,2))                                                     as montanttva,
       cast(((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
              (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) *
               nvl(vd.ristourne, 0) /
               100)) - nvl(p.CALORIE * vd.QTE * v.fraislivraison, 0)) + (nvl(vd.TVA, 0) / 100) *
                                                                        ((cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) -
                                                                          (cast((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100 as NUMBER(30, 2)) *
                                                                           nvl(vd.ristourne, 0) / 100)) -
                                                                         p.CALORIE * vd.QTE *
                                                                         v.fraislivraison) as number(30, 2))                      as montantttc,
       vd.datedebut,
       cast(nvl(p.calorie, 0) as number(10,2))                                                                                   as CALORIE,
       vd.ristourne                                                                                        as ristourne,
       cast(p.CALORIE as number(30, 2))                                                                    as poidsparkilo,
       cast(v.fraislivraison as number(30, 2))                                                             as fraislivraison,
       cast(p.CALORIE * vd.QTE as number(30, 2))                                                           as poidstotal,
       p.pu as puingredient,
       nvl(eq.QUANTITE,1) as contenue
--       d2.id AS idDevis
FROM PROFORMA_DETAILS vd
         LEFT JOIN PROFORMA v ON v.ID = vd.IDPROFORMA
         LEFT JOIN AS_INGREDIENTS p ON p.ID = vd.IDPRODUIT
         LEFT JOIN AS_UNITE au ON au.id = vd.unite
         LEFT JOIN EQUIVALENCEVENTE eq on eq.IDPRODUIT1=p.ID
;
-- [697/1309] PROFORMADETAILS_CPL_ING_PDF
CREATE OR REPLACE FORCE VIEW "PROFORMADETAILS_CPL_ING_PDF" ("ID","IDPROFORMA","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","COMPTE","PUREVIENT","IDDEMANDEPRIXFILLE","IDPROFORMALIB","IDPRODUITLIB","PUTOTAL","UNITE","UNITELIB","REMISEMONTANT","MONTANTRISTOURNE","FRAISTRANSPORT","MONTANTTOTAL","MONTANTREMISE","MONTANTTVA","MONTANTTTC","DATEDEBUT","CALORIE","RISTOURNE","POIDSPARKILO","FRAISLIVRAISON","POIDSTOTAL","PUINGREDIENT","CONTENUE","UNITE2","REMISEARBIOCHEM") AS
SELECT
    vd.ID,
    vd.IDPROFORMA,
    vd.IDPRODUIT,
    vd.IDORIGINE,
    vd.QTE,
    vd.PU,
    vd.REMISE,
    vd.TVA,
    vd.PUACHAT,
    vd.PUVENTE,
    v.IDDEVISE,
    vd.TAUXDECHANGE,
    vd.DESIGNATION,
    vd.COMPTE,
    vd.PUREVIENT,
    vd.IDDEMANDEPRIXFILLE,

    v.DESIGNATION AS IDPROFORMALIB,

    NVL(p.LIBELLEVENTE, p.LIBELLE) AS IDPRODUITLIB,

    CAST(
        vd.QTE * vd.PU
        AS NUMBER(30,2)
    ) AS PUTOTAL,

    vd.UNITE,

    au.VAL AS UNITELIB,

    /* REMISE TOTALE */
    CAST(
        (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
        + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
        AS NUMBER(30,2)
    ) AS REMISEMONTANT,

    /* RISTOURNE */
    CAST(
        (
            (vd.QTE * vd.PU)
            - (
                (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
                + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
            )
        ) * NVL(vd.RISTOURNE,0) / 100
        AS NUMBER(30,2)
    ) AS MONTANTRISTOURNE,

    /* FRAIS TRANSPORT */
    CAST(
        NVL(
            p.CALORIE * vd.QTE * v.FRAISLIVRAISON,
            0
        )
        AS NUMBER(30,2)
    ) AS FRAISTRANSPORT,

    /* MONTANT TOTAL HT */
    CAST(
        (vd.QTE * vd.PU)
        - (
            (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
            + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
        )
        - (
            (
                (vd.QTE * vd.PU)
                - (
                    (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
                    + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
                )
            ) * NVL(vd.RISTOURNE,0) / 100
        )
        - NVL(
            p.CALORIE * vd.QTE * v.FRAISLIVRAISON,
            0
        )
        AS NUMBER(30,2)
    ) AS MONTANTTOTAL,

    /* MONTANT REMISE */
    CAST(
        (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
        + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
        AS NUMBER(30,2)
    ) AS MONTANTREMISE,

    /* TVA */
    CAST(
        (NVL(vd.TVA,0) / 100) *
        (
            (vd.QTE * vd.PU)
            - (
                (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
                + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
            )
            - (
                (
                    (vd.QTE * vd.PU)
                    - (
                        (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
                        + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
                    )
                ) * NVL(vd.RISTOURNE,0) / 100
            )
            - NVL(
                p.CALORIE * vd.QTE * v.FRAISLIVRAISON,
                0
            )
        )
        AS NUMBER(30,2)
    ) AS MONTANTTVA,

    /* TTC */
    CAST(
        (
            (
                (vd.QTE * vd.PU)
                - (
                    (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
                    + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
                )
                - (
                    (
                        (vd.QTE * vd.PU)
                        - (
                            (vd.QTE * vd.PU * NVL(vd.REMISE,0) / 100)
                            + (vd.QTE * NVL(vd.REMISEARBIOCHEM,0))
                        )
                    ) * NVL(vd.RISTOURNE,0) / 100
                )
                - NVL(
                    p.CALORIE * vd.QTE * v.FRAISLIVRAISON,
                    0
                )
            )
            * (1 + NVL(vd.TVA,0) / 100)
        )
        AS NUMBER(30,2)
    ) AS MONTANTTTC,

    vd.DATEDEBUT,

    CAST(
        NVL(p.CALORIE,0)
        AS NUMBER(10,2)
    ) AS CALORIE,

    vd.RISTOURNE,

    CAST(
        p.CALORIE
        AS NUMBER(30,2)
    ) AS POIDSPARKILO,

    CAST(
        v.FRAISLIVRAISON
        AS NUMBER(30,2)
    ) AS FRAISLIVRAISON,

    CAST(
        p.CALORIE * vd.QTE
        AS NUMBER(30,2)
    ) AS POIDSTOTAL,

    CAST(
        vd.PU / NVL(eq.QUANTITE,1)
        AS NUMBER(30,2)
    ) AS PUINGREDIENT,

    NVL(eq.QUANTITE,1) AS CONTENUE,

    p.UNITE2,
    vd.remisearbiochem

FROM PROFORMA_DETAILS vd

LEFT JOIN PROFORMA v
    ON v.ID = vd.IDPROFORMA

LEFT JOIN AS_INGREDIENTS p
    ON p.ID = vd.IDPRODUIT

LEFT JOIN AS_UNITE au
    ON au.ID = vd.UNITE

LEFT JOIN EQUIVALENCEVENTE eq
    ON eq.IDPRODUIT1 = p.ID
;
-- [698/1309] PROFORMAMONTANT2
CREATE OR REPLACE FORCE VIEW "PROFORMAMONTANT2" ("ID","POIDSTOTAL","MONTANT","MONTANTREMISE","MONTANTRISTOURNE","FRAISTRANSPORT","MONTANTTOTAL","MONTANTTOTALACHAT","MONTANTTVA","MONTANTTTC","IDDEVISE","TAUXDECHANGE","MONTANTTTCAR","MONTANTREVIENT","IDRESERVATION") AS
SELECT v.ID,
       cast(SUM(poidstotal) as number(30, 2))                            AS poidstotal,
       cast(SUM(puTotal) as number(30, 2))                               AS montant,
       cast(SUM(remisemontant) as number(30, 2))                         as montantremise,
       cast(SUM(montantristourne) as number(30, 2))                      as montantristourne,
       cast(SUM(vd.fraistransport) as number(30, 2))                     as fraistransport,
       cast(SUM(montanttotal) as number(30, 2))                          AS montanttotal,
       cast(SUM((NVL(vd.QTE, 0) * NVL(vd.PuAchat, 0))) as number(30, 2)) AS montanttotalachat,
       cast(SUM(montanttva) as number(30, 2))                            AS montantTva,
       cast(SUM(montantttc) as number(30, 2))                            as montantTTC,
       NVL(vd.IDDEVISE, 'AR')                                            AS IDDEVISE,
       NVL(avg(vd.tauxDeChange), 1)                                      AS tauxDeChange,
       cast(SUM(montantttc * vd.TAUXDECHANGE) as number(30, 2))          as montantTTCAR,
       cast(sum(vd.PUREVIENT * vd.QTE) as number(20, 2))                 as montantRevient,
       v.IDRESERVATION
FROM PROFORMADETAILS_CPL vd
         LEFT JOIN PROFORMA v ON v.ID = vd.IDPROFORMA
GROUP BY v.ID, vd.IDDEVISE, v.IDRESERVATION
;
-- [699/1309] PROFORMAMONTANTLEGER
CREATE OR REPLACE FORCE VIEW "PROFORMAMONTANTLEGER" ("ID","MONTANTTOTAL","MONTANTREMISE","FRAIS","MONTANTTOTALACHAT","MONTANTTVA","MONTANTTTC","IDDEVISE","TAUXDECHANGE","MONTANTTTCAR","MONTANTREVIENT","IDRESERVATION","POIDS","COLIS","MONTANTRISTOURNE") AS
SELECT v.ID,
       cast(SUM((NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE)) as number(30, 2))                          AS montanttotal,
       cast(SUM((NVL(vd.QTE, 0) * NVL(vd.PU, 0))) -
            SUM((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0))) as number(30, 2))                  AS montantremise,
       cast(sum(nvl(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(vd.QTE, 0)) as number(30, 5)   )      as frais,
       cast(SUM((NVL(vd.QTE, 0) * NVL(vd.PuAchat, 0))) as number(30, 2))                                             AS montanttotalachat,
       cast(SUM(((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE)) * (NVL(VD.TVA, 0)) /
                100) as number(30, 2))                                                                               AS montantTva,
       cast(SUM(((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                 (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE)) * (NVL(VD.TVA, 0)) / 100) +
            SUM((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE)) as number(30, 2))                          as montantTTC,
       NVL(vd.IDDEVISE, 'AR')                                                                                        AS IDDEVISE,
       NVL(avg(vd.tauxDeChange), 1)                                                                                  AS tauxDeChange,
       cast((SUM(((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                 (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE)) * (NVL(VD.TVA, 0)) / 100) +
            SUM((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE))*NVL(avg(vd.tauxDeChange), 1) ) as number(30, 2)) as montantTTCAR,
       cast(sum(vd.PUREVIENT * vd.QTE) as number(20, 2))                                                             as montantRevient,
       v.IDRESERVATION,nvl(sum(vd.QTE*ing.CALORIE),0) as poids,sum(vd.QTE) as colis,
       cast(sum((vd.QTE * vd.PU) - ((vd.QTE * vd.PU) * NVL(vd.remise, 0)) / 100  * nvl(vd.ristourne, 0) /100) as number(30, 2)) as montantristourne
FROM PROFORMA_DETAILS vd
         LEFT JOIN PROFORMA v ON v.ID = vd.IDPROFORMA
         left join AS_INGREDIENTS ing on ing.id = vd.IDPRODUIT
GROUP BY v.id, vd.IDDEVISE, v.IDRESERVATION order by v.id asc
;
-- [700/1309] PROFORMAMONTANTLEGER2
CREATE OR REPLACE FORCE VIEW "PROFORMAMONTANTLEGER2" ("ID","MONTANTTOTAL","MONTANTREMISE","FRAIS","MONTANTTOTALACHAT","MONTANTTVA","MONTANTTTC","IDDEVISE","TAUXDECHANGE","MONTANTTTCAR","MONTANTREVIENT","IDRESERVATION","POIDS","COLIS","MONTANTRISTOURNE") AS
SELECT
    v.ID,

    CAST(SUM(
            (NVL(vd.QTE,0) * NVL(vd.PU,0))
                - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))
                - (
                (((NVL(vd.QTE,0) * NVL(vd.PU,0)) - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))) * NVL(vd.ristourne,0) / 100)
                    + (NVL(vd.QTE,0) * NVL(vd.ristourneArbiochem,0))
                )
                - NVL(ing.CALORIE * vd.QTE * v.fraislivraison, 0)
         ) AS NUMBER(30,2)) AS montanttotal,

    CAST(SUM(
            (NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0))
         ) AS NUMBER(30,2)) AS montantremise,

    CAST(SUM(NVL(v.fraislivraison,0) * NVL(ing.CALORIE,0) * NVL(vd.QTE,0)) AS NUMBER(30,5)) AS frais,

    CAST(SUM(NVL(vd.QTE,0) * NVL(vd.PUACHAT,0)) AS NUMBER(30,2)) AS montanttotalachat,

    CAST(SUM(
            NVL(vd.TVA,0) / 100 * (
                (NVL(vd.QTE,0) * NVL(vd.PU,0))
                    - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))
                    - (
                    (((NVL(vd.QTE,0) * NVL(vd.PU,0)) - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))) * NVL(vd.ristourne,0) / 100)
                        + (NVL(vd.QTE,0) * NVL(vd.ristourneArbiochem,0))
                    )
                    - NVL(ing.CALORIE * vd.QTE * v.fraislivraison, 0)
                )
         ) AS NUMBER(30,2)) AS montantTva,

    CAST(SUM(
            (NVL(vd.TVA,0) / 100 + 1) * (
                (NVL(vd.QTE,0) * NVL(vd.PU,0))
                    - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))
                    - (
                    (((NVL(vd.QTE,0) * NVL(vd.PU,0)) - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))) * NVL(vd.ristourne,0) / 100)
                        + (NVL(vd.QTE,0) * NVL(vd.ristourneArbiochem,0))
                    )
                    - NVL(ing.CALORIE * vd.QTE * v.fraislivraison, 0)
                )
         ) AS NUMBER(30,2)) AS montantTTC,

    NVL(v.IDDEVISE, 'AR') AS IDDEVISE,

    NVL(AVG(vd.tauxDeChange), 1) AS tauxDeChange,

    CAST(
            SUM(
                    (NVL(vd.TVA,0) / 100 + 1) * (
                        (NVL(vd.QTE,0) * NVL(vd.PU,0))
                            - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))
                            - (
                            (((NVL(vd.QTE,0) * NVL(vd.PU,0)) - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))) * NVL(vd.ristourne,0) / 100)
                                + (NVL(vd.QTE,0) * NVL(vd.ristourneArbiochem,0))
                            )
                            - NVL(ing.CALORIE * vd.QTE * v.fraislivraison, 0)
                        )
            ) * NVL(AVG(vd.tauxDeChange), 1)
        AS NUMBER(30,2)) AS montantTTCAR,

    CAST(SUM(vd.PUREVIENT * vd.QTE) AS NUMBER(20,2)) AS montantRevient,

    v.IDRESERVATION,

    NVL(SUM(vd.QTE * ing.CALORIE), 0) AS poids,

    SUM(vd.QTE) AS colis,

    CAST(SUM(
            (((NVL(vd.QTE,0) * NVL(vd.PU,0)) - ((NVL(vd.QTE,0) * NVL(vd.PU,0) * NVL(vd.remise,0) / 100) + (NVL(vd.QTE,0) * NVL(vd.remiseArbiochem,0)))) * NVL(vd.ristourne,0) / 100)
                + (NVL(vd.QTE,0) * NVL(vd.ristourneArbiochem,0))
         ) AS NUMBER(30,2)) AS montantristourne

FROM PROFORMA_DETAILS vd
         LEFT JOIN PROFORMA v ON v.ID = vd.IDPROFORMA
         LEFT JOIN AS_INGREDIENTS ing ON ing.ID = vd.IDPRODUIT
GROUP BY v.id, v.IDDEVISE, v.IDRESERVATION
ORDER BY v.id ASC
;
-- [701/1309] PROFORMA_CPL
CREATE OR REPLACE FORCE VIEW "PROFORMA_CPL" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","IDDEVISE","IDCLIENT","CODECLIENT","IDCLIENTLIB","ADRESSE","CONTACT","POIDSTOTAL","MONTANT","MONTANTREMISE","MONTANTRISTOURNE","FRAISLIVRAISON","FRAISTRANSPORT","MONTANTTOTAL","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","IDORIGINE","REMISE","NUMEROPROFORMA","IDCOMMANDE","MODELIVRAISONLIB","LIEULIVRAISON","DATELIVRAISON","REFERENCE","MOTSCLESSS") AS
SELECT V.ID,
       V.DESIGNATION,
       V.IDMAGASIN,
       M.VAL                                                                                  AS IDMAGASINLIB,
       V.DATY,
       V.REMARQUE,
       V.ETAT,
       CASE
           WHEN V.ETAT = 1 THEN 'CR&Eacute;&Eacute;'
           WHEN V.ETAT = 11 THEN 'VIS&Eacute;'
           WHEN V.ETAT = 0 THEN 'ANNUL&Eacute;E'
           WHEN V.ETAT = 12 THEN '<span style=color: green;>CL&Ocirc;TUR&Eacute;</span>'
           END                                                                                AS ETATLIB,
       V2.IDDEVISE,
       V.IDCLIENT,
       C.CODECLIENT,
       C.NOM                                                                                  AS IDCLIENTLIB,
       C.ADRESSE,
       C.TELEPHONE                                                                            AS CONTACT,
       CAST(V2.POIDS AS NUMBER(30, 2))                                                        AS POIDSTOTAL,
       CAST(V2.MONTANTTOTAL AS NUMBER(30, 2))                                                 AS MONTANT,
       CAST(V2.MONTANTREMISE AS NUMBER(30, 2))                                                AS MONTANTREMISE,
       CAST(V2.MONTANTRISTOURNE AS NUMBER(30, 2))                                             AS MONTANTRISTOURNE,
       CAST(NVL(V.FRAISLIVRAISON, 0) AS NUMBER(10, 2))                                        AS FRAISLIVRAISON,
       CAST(V2.FRAIS AS NUMBER(30, 2))                                                        AS FRAISTRANSPORT,
       CAST(V2.MONTANTTOTAL AS NUMBER(30, 2))                                                 AS MONTANTTOTAL,
       CAST(V2.MONTANTTVA AS NUMBER(30, 2))                                                   AS MONTANTTVA,
       CAST(V2.MONTANTTTC AS NUMBER(30, 2))                                                   AS MONTANTTTC,
       CAST(V2.MONTANTTTCAR AS NUMBER(30, 2))                                                 AS MONTANTTTCAR,
       CAST(0 AS NUMBER(30, 2))                                                               AS MONTANTPAYE,
       CAST(0 AS NUMBER(30, 2))                                                               AS MONTANTRESTE,
       0                                                                                      AS AVOIR,
       CAST(V2.TAUXDECHANGE AS NUMBER(10, 2))                                                 AS TAUXDECHANGE,
       CAST(V2.MONTANTREVIENT AS NUMBER(20, 5))                                               AS MONTANTREVIENT,
       CAST((COALESCE(V2.MONTANTTTCAR, 0) - COALESCE(V2.MONTANTREVIENT, 0)) AS NUMBER(20, 5)) AS MARGEBRUTE,
       V.IDRESERVATION,
       V.IDORIGINE,
       NVL(V.REMISE, 0)                                                                       AS REMISE,
       V.NUMEROPROFORMA,
       V.IDCOMMANDE,
       CASE
           WHEN V.MODELIVRAISON = 1 THEN 'LIVRAISON'
           WHEN V.MODELIVRAISON = 2 THEN 'RECUPERATION'
           END                                                                                AS MODELIVRAISONLIB,
       V.LIEULIVRAISON                                                                        AS LIEULIVRAISON,
       V.DATELIVRAISON                                                                        AS DATELIVRAISON,
       V.REFERENCE,
       (
           V.ID || ' | ' || NUMEROPROFORMA || ' | ' || C.NOM || ' | ' || M.VAL
           )                                                                                  AS MOTSCLESSS
FROM PROFORMA V
         LEFT JOIN CLIENT C ON C.ID = V.IDCLIENT
         LEFT JOIN MAGASIN2 M ON M.ID = V.IDMAGASIN
         JOIN PROFORMAMONTANTLEGER V2 ON V2.ID = V.ID
;
-- [702/1309] PROFORMA_CPL2
CREATE OR REPLACE FORCE VIEW "PROFORMA_CPL2" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","IDDEVISE","IDCLIENT","CODECLIENT","IDCLIENTLIB","ADRESSE","CONTACT","POIDSTOTAL","MONTANT","MONTANTREMISE","MONTANTRISTOURNE","FRAISLIVRAISON","FRAISTRANSPORT","MONTANTTOTAL","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","IDORIGINE","REMISE","NUMEROPROFORMA","IDCOMMANDE","MODELIVRAISONLIB","LIEULIVRAISON","DATELIVRAISON","REFERENCE","MOTSCLESSS") AS
SELECT V.ID,
       V.DESIGNATION,
       V.IDMAGASIN,
       M.VAL                                                                                  AS IDMAGASINLIB,
       V.DATY,
       V.REMARQUE,
       V.ETAT,
       CASE
           WHEN V.ETAT = 1 THEN 'CR&Eacute;&Eacute;'
           WHEN V.ETAT = 11 THEN 'VIS&Eacute;'
           WHEN V.ETAT = 0 THEN 'ANNUL&Eacute;E'
           WHEN V.ETAT = 12 THEN '<span style=color: green;>CL&Ocirc;TUR&Eacute;</span>'
           END                                                                                AS ETATLIB,
       V2.IDDEVISE,
       V.IDCLIENT,
       C.CODECLIENT,
       C.NOM                                                                                  AS IDCLIENTLIB,
       C.ADRESSE,
       C.TELEPHONE                                                                            AS CONTACT,
       CAST(V2.POIDS AS NUMBER(30, 2))                                                        AS POIDSTOTAL,
       CAST((V2.MONTANTTOTAL+V2.MONTANTREMISE )AS NUMBER(30, 2))                                                 AS MONTANT,
       CAST(V2.MONTANTREMISE AS NUMBER(30, 2))                                                AS MONTANTREMISE,
       CAST(V2.MONTANTRISTOURNE AS NUMBER(30, 2))                                             AS MONTANTRISTOURNE,
       CAST(NVL(V.FRAISLIVRAISON, 0) AS NUMBER(10, 2))                                        AS FRAISLIVRAISON,
       CAST(V2.FRAIS AS NUMBER(30, 2))                                                        AS FRAISTRANSPORT,
       CAST(V2.MONTANTTOTAL AS NUMBER(30, 2))                                                 AS MONTANTTOTAL,
       CAST(V2.MONTANTTVA AS NUMBER(30, 2))                                                   AS MONTANTTVA,
       CAST(V2.MONTANTTTC AS NUMBER(30, 2))                                                   AS MONTANTTTC,
       CAST(V2.MONTANTTTCAR AS NUMBER(30, 2))                                                 AS MONTANTTTCAR,
       CAST(0 AS NUMBER(30, 2))                                                               AS MONTANTPAYE,
       CAST(0 AS NUMBER(30, 2))                                                               AS MONTANTRESTE,
       0                                                                                      AS AVOIR,
       CAST(V2.TAUXDECHANGE AS NUMBER(10, 2))                                                 AS TAUXDECHANGE,
       CAST(V2.MONTANTREVIENT AS NUMBER(20, 5))                                               AS MONTANTREVIENT,
       CAST((COALESCE(V2.MONTANTTTCAR, 0) - COALESCE(V2.MONTANTREVIENT, 0)) AS NUMBER(20, 5)) AS MARGEBRUTE,
       V.IDRESERVATION,
       V.IDORIGINE,
       NVL(V.REMISE, 0)                                                                       AS REMISE,
       V.NUMEROPROFORMA,
       V.IDCOMMANDE,
       CASE
           WHEN V.MODELIVRAISON = 1 THEN 'LIVRAISON'
           WHEN V.MODELIVRAISON = 2 THEN 'RECUPERATION'
           END                                                                                AS MODELIVRAISONLIB,
       V.LIEULIVRAISON                                                                        AS LIEULIVRAISON,
       V.DATELIVRAISON                                                                        AS DATELIVRAISON,
       V.REFERENCE,
       (
           V.ID || ' | ' || NUMEROPROFORMA || ' | ' || C.NOM || ' | ' || M.VAL
           )                                                                                  AS MOTSCLESSS
FROM PROFORMA V
         LEFT JOIN CLIENT C ON C.ID = V.IDCLIENT
         LEFT JOIN MAGASIN2 M ON M.ID = V.IDMAGASIN
         JOIN PROFORMAMONTANTLEGER2 V2 ON V2.ID = V.ID
;
-- [703/1309] PROFORMA_CPL_CREE
CREATE OR REPLACE FORCE VIEW "PROFORMA_CPL_CREE" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","IDDEVISE","IDCLIENT","CODECLIENT","IDCLIENTLIB","ADRESSE","CONTACT","POIDSTOTAL","MONTANT","MONTANTREMISE","MONTANTRISTOURNE","FRAISLIVRAISON","FRAISTRANSPORT","MONTANTTOTAL","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","IDORIGINE","REMISE","NUMEROPROFORMA","IDCOMMANDE","MODELIVRAISONLIB","LIEULIVRAISON","DATELIVRAISON","REFERENCE","MOTSCLESSS") AS
SELECT V."ID",V."DESIGNATION",V."IDMAGASIN",V."IDMAGASINLIB",V."DATY",V."REMARQUE",V."ETAT",V."ETATLIB",V."IDDEVISE",V."IDCLIENT",V."CODECLIENT",V."IDCLIENTLIB",V."ADRESSE",V."CONTACT",V."POIDSTOTAL",V."MONTANT",V."MONTANTREMISE",V."MONTANTRISTOURNE",V."FRAISLIVRAISON",V."FRAISTRANSPORT",V."MONTANTTOTAL",V."MONTANTTVA",V."MONTANTTTC",V."MONTANTTTCAR",V."MONTANTPAYE",V."MONTANTRESTE",V."AVOIR",V."TAUXDECHANGE",V."MONTANTREVIENT",V."MARGEBRUTE",V."IDRESERVATION",V."IDORIGINE",V."REMISE",V."NUMEROPROFORMA",V."IDCOMMANDE",V."MODELIVRAISONLIB",V."LIEULIVRAISON",V."DATELIVRAISON",V."REFERENCE",V."MOTSCLESSS"
FROM PROFORMA_CPL V
WHERE ETAT = 1
;
-- [704/1309] PROFORMA_CPL_VISEE
CREATE OR REPLACE FORCE VIEW "PROFORMA_CPL_VISEE" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","IDDEVISE","IDCLIENT","CODECLIENT","IDCLIENTLIB","ADRESSE","CONTACT","POIDSTOTAL","MONTANT","MONTANTREMISE","MONTANTRISTOURNE","FRAISLIVRAISON","FRAISTRANSPORT","MONTANTTOTAL","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","IDORIGINE","REMISE","NUMEROPROFORMA","IDCOMMANDE","MODELIVRAISONLIB","LIEULIVRAISON","DATELIVRAISON","REFERENCE","MOTSCLESSS") AS
SELECT V."ID",V."DESIGNATION",V."IDMAGASIN",V."IDMAGASINLIB",V."DATY",V."REMARQUE",V."ETAT",V."ETATLIB",V."IDDEVISE",V."IDCLIENT",V."CODECLIENT",V."IDCLIENTLIB",V."ADRESSE",V."CONTACT",V."POIDSTOTAL",V."MONTANT",V."MONTANTREMISE",V."MONTANTRISTOURNE",V."FRAISLIVRAISON",V."FRAISTRANSPORT",V."MONTANTTOTAL",V."MONTANTTVA",V."MONTANTTTC",V."MONTANTTTCAR",V."MONTANTPAYE",V."MONTANTRESTE",V."AVOIR",V."TAUXDECHANGE",V."MONTANTREVIENT",V."MARGEBRUTE",V."IDRESERVATION",V."IDORIGINE",V."REMISE",V."NUMEROPROFORMA",V."IDCOMMANDE",V."MODELIVRAISONLIB",V."LIEULIVRAISON",V."DATELIVRAISON",V."REFERENCE",V."MOTSCLESSS"
FROM PROFORMA_CPL V
WHERE ETAT = 11
;
-- [705/1309] PROFORMA_DETAILS_VIDE
CREATE OR REPLACE FORCE VIEW "PROFORMA_DETAILS_VIDE" ("ID","IDPROFORMA","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","COMPTE","PUREVIENT","IDDEMANDEPRIXFILLE","UNITE","DATEDEBUT","UNITELIB","PUNET","MONTANTHT","MONTANTTTC","RISTOURNE","CALORIE","REMISEARBIOCHEM","RISTOURNEARBIOCHEM") AS
select p.ID,
       p.IDPROFORMA,
       p.IDPRODUIT,
       p.IDORIGINE,
       p.QTE,
       p.PU,
       p.REMISE,
       p.TVA,
       p.PUACHAT,
       p.PUVENTE,
       p.IDDEVISE,
       p.TAUXDECHANGE,
       p.DESIGNATION,
       p.COMPTE,
       p.PUREVIENT,
       p.IDDEMANDEPRIXFILLE,
       p.UNITE,
       p.DATEDEBUT,
       u.val as unitelib,
       0  as punet,
       0  as montantht,
       0  as montantttc,
       p.RISTOURNE,
       ing.CALORIE,
       p.remiseArbiochem,
       p.ristourneArbiochem
from PROFORMA_DETAILS p
         LEFT JOIN as_unite u ON p.unite=u.id
         LEFT JOIN  AS_INGREDIENTS ing ON p.IDPRODUIT = ing.ID
;
-- [706/1309] PROGRAMMEZOOTECHNIQUEDT_LIB
CREATE OR REPLACE FORCE VIEW "PROGRAMMEZOOTECHNIQUEDT_LIB" ("ID","IDMERE","AGE","IDSEXE","ALIMENT","POIDS","MORTALITE","PONTEHEBDOMADAIRE","PONTECUMULEE","OEUFCUMULE","OACPOURCENTAGE","OACHH","POIDSOEUF","TAUXECLOSION","POUSSINS","CONSOALIMENTFEMELLE","FEMELLEBW","MALEBW","RATIOPRODUCTION","FERTILITE","IDSEXELIB","CONSOMMATIONEAU","TEMPERATUREMIN","TEMPERATUREMAX","HUMIDITEMIN","HUMIDITEMAX","DUREEECLAIRAGE","UNIFORMITECIBLE","CVMAX") AS
SELECT
	d."ID",
	d."IDMERE",
	d."AGE",
	d."IDSEXE",
	d."ALIMENT",
	d."POIDS",
	d."MORTALITE",
	d."PONTEHEBDOMADAIRE",
	d."PONTECUMULEE",
	d."OEUFCUMULE",
	d."OACPOURCENTAGE",
	d."OACHH",
	d."POIDSOEUF",
	d."TAUXECLOSION",
	d."POUSSINS",
	d."CONSOALIMENTFEMELLE",
	d."FEMELLEBW",
	d."MALEBW",
	d."RATIOPRODUCTION",
	d."FERTILITE",
	sx."VAL" AS "IDSEXELIB",
	d."CONSOMMATIONEAU", 
	d."TEMPERATUREMIN", 
	d."TEMPERATUREMAX", 
	d."HUMIDITEMIN", 
	d."HUMIDITEMAX", 
	d."DUREEECLAIRAGE", 
	d."UNIFORMITECIBLE", 
	d."CVMAX"
	
FROM
	"PROGRAMMEZOOTECHNIQUEDETAILS" d
LEFT JOIN "SEXE" sx ON
	sx."ID" = d."IDSEXE"
;
-- [707/1309] PROGRAMMEZOOTECHNIQUE_LIB
CREATE OR REPLACE FORCE VIEW "PROGRAMMEZOOTECHNIQUE_LIB" ("ID","CODE","IDSOUCHE","VERSION","DATY","IDSOUCHELIB","ETATLIB") AS
SELECT p."ID",p."CODE",p."IDSOUCHE",p."VERSION",p."DATY",
       s."VAL" AS "IDSOUCHELIB",
       CASE
             WHEN p.ETAT = 1 THEN 'CR&Eacute;&Eacute;'
             WHEN p.ETAT = 11 THEN 'VIS&Eacute;'
             WHEN p.ETAT = 0 THEN 'ANNUL&Eacute;'
          END
             AS ETATLIB
FROM "PROGRAMMEZOOTECHNIQUE" p
         LEFT JOIN "SOUCHE" s ON s."ID" = p."IDSOUCHE"
;
-- [708/1309] LOT_LIB
CREATE OR REPLACE FORCE VIEW "LOT_LIB" ("ID","NOMLOT","REFERENCE","DATEECLOSION","DATEARRIVEE","SOURCE","IDFERME","IDARTICLE","IDORIGINE","IDPROGRAMME","ETAT","IDFERMELIB","IDARTICLELIB","IDORIGINELIB","IDPROGRAMMELIB","IDSOUCHELIB","ETATLIB","IDCATEGORIELOTLIB","DATECLOTURE","AGEJOUR","AGESEMAINE") AS
SELECT l.ID,l.NOMLOT,l.REFERENCE,l.DATEECLOSION,l.DATEARRIVEE,l.SOURCE,l.IDFERME,l.IDARTICLE,l.IDORIGINE,l.IDPROGRAMME,l.ETAT,
       m.VAL      AS IDFERMELIB,
       ai.LIBELLE AS IDARTICLELIB,
       o.VAL      AS IDORIGINELIB,
       pz.CODE || '-' || pz.IDSOUCHELIB AS IDPROGRAMMELIB,
       s.val AS idsouchelib,
       CASE l.ETAT
           WHEN 1  THEN 'CR&Eacute;&Eacute;'
           WHEN 11 THEN 'VALID&Eacute;'
           WHEN 0  THEN 'ANULL&Eacute;'
           WHEN 17  THEN 'CL&Ocirc;TUR&Eacute;'
           END AS ETATLIB,
       cl.val AS idcategorielotlib,
       l.datecloture AS datecloture,
       TRUNC(SYSDATE) - TRUNC(dateEclosion) + 1 AS ageJour,
       FLOOR((TRUNC(SYSDATE) - TRUNC(dateEclosion) + 1 - 1) / 7) + 1 AS ageSemaine
FROM LOT l
         LEFT JOIN MAGASIN2 m ON m.ID = l.IDFERME
         LEFT JOIN AS_INGREDIENTS ai ON ai.ID = l.IDARTICLE
         LEFT JOIN ORIGINELOT o ON o.ID = l.IDORIGINE
         LEFT JOIN PROGRAMMEZOOTECHNIQUE_LIB pz ON pz.ID = l.IDPROGRAMME
         LEFT JOIN SOUCHE s ON s.id=l.idsouche
         LEFT JOIN CATEGORIELOT cl ON cl.id=l.idcategorielot
;
-- [709/1309] PESEEPOUSSIN_LIB
CREATE OR REPLACE FORCE VIEW "PESEEPOUSSIN_LIB" ("ID","DATEPESEE","IDTYPEPESEE","IDRESPONSABLE","IDFERME","IDBATIMENT","IDLOT","IDPARQUET","IDSEXE","REMARQUE","ETAT","IDTYPEPESEELIB","IDRESPONSABLELIB","IDFERMELIB","IDBATIMENTLIB","IDLOTLIB","IDPARQUETLIB","IDSOUCHELIB","IDSEXELIB","DATEECLOSION","AGEJOUR","AGESEMAINE","NOMBREOISEAUXPESES","POIDSTOTAL","POIDSMOYEN","ECARTTYPE","COEFFICIENTVARIATION","LIMITEBASSEUNIFORMITE","LIMITEHAUTEUNIFORMITE","NOMBREOISEAUXDANSPLAGE","UNIFORMITE","ETATLIB") AS
WITH agg AS (
    SELECT "IDMERE",
           SUM("NOMBREOISEAUX")                       AS NOMBREOISEAUXPESES,
           SUM("POIDS" * "NOMBREOISEAUX")              AS POIDSTOTAL,
           SUM("NOMBREOISEAUX" * "POIDS" * "POIDS")     AS SUM_N_P2,
           SUM("NOMBREOISEAUX" * "POIDS")               AS SUM_N_P
    FROM "PESEEPOUSSINDETAIL"
    GROUP BY "IDMERE"
),
stats AS (
    SELECT "IDMERE",
           NOMBREOISEAUXPESES,
           POIDSTOTAL,
           CASE WHEN NOMBREOISEAUXPESES > 0
                THEN POIDSTOTAL / NOMBREOISEAUXPESES
                ELSE NULL END AS POIDSMOYEN,
           CASE WHEN NOMBREOISEAUXPESES > 1
                THEN SQRT( (SUM_N_P2 - (POWER(SUM_N_P,2) / NOMBREOISEAUXPESES)) / (NOMBREOISEAUXPESES - 1) )
                ELSE NULL END AS ECARTTYPE
    FROM agg
),
stats2 AS (
    SELECT s.*,
           CASE WHEN POIDSMOYEN IS NOT NULL AND POIDSMOYEN <> 0
                THEN (ECARTTYPE / POIDSMOYEN) * 100
                ELSE NULL END AS COEFFICIENTVARIATION,
           POIDSMOYEN * 0.90 AS LIMITEBASSEUNIFORMITE,
           POIDSMOYEN * 1.10 AS LIMITEHAUTEUNIFORMITE
    FROM stats s
),
plage AS (
    SELECT s2."IDMERE",
           SUM(CASE WHEN d."POIDS" >= s2.LIMITEBASSEUNIFORMITE
                     AND d."POIDS" <= s2.LIMITEHAUTEUNIFORMITE
                    THEN d."NOMBREOISEAUX" ELSE 0 END) AS NOMBREOISEAUXDANSPLAGE
    FROM stats2 s2
    JOIN "PESEEPOUSSINDETAIL" d ON d."IDMERE" = s2."IDMERE"
    GROUP BY s2."IDMERE"
)
SELECT p."ID",p."DATEPESEE",p."IDTYPEPESEE",p."IDRESPONSABLE",p."IDFERME",p."IDBATIMENT",p."IDLOT",p."IDPARQUET",p."IDSEXE",p."REMARQUE",p."ETAT",
       tp."VAL"                                        AS "IDTYPEPESEELIB",
       lp."NOM" || ' ' || lp."PRENOM"                   AS "IDRESPONSABLELIB",
       fm."VAL"                                         AS "IDFERMELIB",
       b."NOMBATIMENT"                                          AS "IDBATIMENTLIB",
       l."NOMLOT"                                       AS "IDLOTLIB",
       pq."VAL"                                         AS "IDPARQUETLIB",
       pz."IDSOUCHELIB"                                 AS "IDSOUCHELIB",
       sx."VAL"                                         AS "IDSEXELIB",
       l."DATEECLOSION"                                 AS "DATEECLOSION",
       (p."DATEPESEE" - l."DATEECLOSION")                AS "AGEJOUR",
       (p."DATEPESEE" - l."DATEECLOSION") / 7             AS "AGESEMAINE",
       s2.NOMBREOISEAUXPESES                             AS "NOMBREOISEAUXPESES",
       s2.POIDSTOTAL                                     AS "POIDSTOTAL",
       s2.POIDSMOYEN                                     AS "POIDSMOYEN",
       s2.ECARTTYPE                                      AS "ECARTTYPE",
       s2.COEFFICIENTVARIATION                           AS "COEFFICIENTVARIATION",
       s2.LIMITEBASSEUNIFORMITE                          AS "LIMITEBASSEUNIFORMITE",
       s2.LIMITEHAUTEUNIFORMITE                          AS "LIMITEHAUTEUNIFORMITE",
       pl.NOMBREOISEAUXDANSPLAGE                         AS "NOMBREOISEAUXDANSPLAGE",
       CASE WHEN s2.NOMBREOISEAUXPESES > 0
                THEN pl.NOMBREOISEAUXDANSPLAGE / s2.NOMBREOISEAUXPESES * 100
            ELSE NULL END                                AS "UNIFORMITE",
       CASE p."ETAT"
           WHEN 1  THEN 'CREE'
           WHEN 11 THEN 'VALIDEE'
           END                                                AS "ETATLIB"
FROM "PESEEPOUSSIN" p
         LEFT JOIN "TYPEPESEE" tp ON tp."ID" = p."IDTYPEPESEE"
         LEFT JOIN "LOG_PERSONNEL" lp ON lp."ID" = p."IDRESPONSABLE"
         LEFT JOIN "MAGASIN2" fm ON fm."ID" = p."IDFERME"
         LEFT JOIN "BATIMENT" b ON b."ID" = p."IDBATIMENT"
         LEFT JOIN "LOT" l ON l."ID" = p."IDLOT"
         LEFT JOIN "PARQUET" pq ON pq."ID" = p."IDPARQUET"
         LEFT JOIN "SEXE" sx ON sx."ID" = p."IDSEXE"
         LEFT JOIN "PROGRAMMEZOOTECHNIQUE_LIB" pz ON pz."ID" = l."IDPROGRAMME"
         LEFT JOIN stats2 s2 ON s2."IDMERE" = p."ID"
         LEFT JOIN plage pl ON pl."IDMERE" = p."ID"
;
-- [710/1309] PESEEPOUSSINDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "PESEEPOUSSINDETAIL_LIB" ("ID","IDMERE","POIDS","NOMBREOISEAUX","POIDSNOMBRE","DANSPLAGEUNIFORMITE","POURCENTAGEOISEAUX") AS
SELECT d."ID",d."IDMERE",d."POIDS",d."NOMBREOISEAUX",
       (d."POIDS" * d."NOMBREOISEAUX")                  AS "POIDSNOMBRE",
       CASE WHEN d."POIDS" >= m."LIMITEBASSEUNIFORMITE"
           AND d."POIDS" <= m."LIMITEHAUTEUNIFORMITE"
                THEN 'Oui' ELSE 'Non' END                   AS "DANSPLAGEUNIFORMITE",
       CASE WHEN m."NOMBREOISEAUXPESES" > 0
                THEN d."NOMBREOISEAUX" / m."NOMBREOISEAUXPESES" * 100
            ELSE NULL END                                AS "POURCENTAGEOISEAUX"
FROM "PESEEPOUSSINDETAIL" d
         LEFT JOIN "PESEEPOUSSIN_LIB" m ON m."ID" = d."IDMERE"
;
-- [711/1309] PV_VISA_MULTIPLE_CREE
CREATE OR REPLACE FORCE VIEW "PV_VISA_MULTIPLE_CREE" ("ID","IDPERSONNEL","MATRICULE","PERSONNEL","MOIS","MOISLIB","ANNEE","HEURENORMAL","HEURESUPNORMAL","HEURESUPNUIT","HEURESUPFERIE","HEURESUPWEEKEND","ABSENCE","ETAT","DIRECTION","DIRECTIONLIB") AS
SELECT
