    IDPERSONNEL,
    MATRICULE,
    PERSONNEL,
    MOIS,
    MOISLIB,
    ANNEE,
    CAST(HEURENORMAL AS NUMBER(20,2)) AS HEURENORMAL,
    CAST(HEURESUPNORMAL AS NUMBER(20,2)) AS HEURESUPNORMAL,
    CAST(HEURESUPNUIT AS NUMBER(20,2)) AS HEURESUPNUIT,
    CAST(HEURESUPFERIE AS NUMBER(20,2)) AS HEURESUPFERIE,
    CAST(HEURESUPWEEKEND AS NUMBER(20,2)) AS HEURESUPWEEKEND,
    CAST(ABSENCE AS NUMBER(20,2)) AS ABSENCE,
    ETAT,
    DIRECTION,
    DIRECTIONLIB
FROM
    POINTAGEVISEE_VISA_MULTIPLE
WHERE
    etat = 1
;
-- [712/1309] PV_VISA_MULTIPLE_VISEE
CREATE OR REPLACE FORCE VIEW "PV_VISA_MULTIPLE_VISEE" ("ID","IDPERSONNEL","MATRICULE","PERSONNEL","MOIS","MOISLIB","ANNEE","HEURENORMAL","HEURESUPNORMAL","HEURESUPNUIT","HEURESUPFERIE","HEURESUPWEEKEND","ABSENCE","ETAT","DIRECTION","DIRECTIONLIB") AS
SELECT
