-- [713/1309] QTEFABANDRESTFABBYIDBC
CREATE OR REPLACE FORCE VIEW "QTEFABANDRESTFABBYIDBC" ("IDFABFILLE","IDBCFILLE","IDMERE","QTEFAB","QTEFABRESTANTE") AS
SELECT  
	f.ID AS IDFABFILLE,
	f.IDBCFILLE ,
	f.IDMERE ,
	f.QTE AS QTEFAB, 
    NVL(f.QTE, 0) - NVL(bcf.QUANTITE, 0) AS QTEFABRESTANTE
FROM FABRICATIONFILLE f 
LEFT JOIN BONDECOMMANDE_CLIENT_FILLE bcf 
	ON bcf.ID = f.IDBCFILLE
;
-- [714/1309] QTEOFANDRESTOFBYIDBC
CREATE OR REPLACE FORCE VIEW "QTEOFANDRESTOFBYIDBC" ("IDOFFILLE","IDBCFILLE","IDMERE","QTEOF","QTEOFRESTANTE") AS
SELECT  
    o.ID AS IDOFFILLE, 
    o.IDBCFILLE, 
    o.IDMERE, 
    o.QTE AS QTEOF, 
    NVL(o.QTE, 0) - NVL(bcf.QUANTITE, 0) AS QTEOFRESTANTE
FROM OFFILLE o 
LEFT JOIN BONDECOMMANDE_CLIENT_FILLE bcf 
    ON bcf.ID = o.IDBCFILLE
;
-- [715/1309] RAPPROCHEMENTBCETAT
CREATE OR REPLACE FORCE VIEW "RAPPROCHEMENTBCETAT" ("ID","IDSOUSECRITURE","IDRELEVERDETAIL","VALEURSOUSECRITURE","VALEURRELEVERDETAIL","DATY","ETAT","IDMERE") AS
select rp.id,rp.IDSOUSECRITURE,rp.IDRELEVERDETAIL,rp.VALEURSOUSECRITURE,rp.VALEURRELEVERDETAIL,rp.DATY,rpm.ETAT,rp.IDMERE from RapprochementBC rp join RAPPROCHEMENTBCMERE rpm on rp.IDMERE=rpm.ID
;
-- [716/1309] RAPPROCHEMENTBCMERELIB
CREATE OR REPLACE FORCE VIEW "RAPPROCHEMENTBCMERELIB" ("ID","IDBANQUE","VALEUR","DATY","ETAT","IDBANQUELIB","ETATLIB") AS
select
    rp."ID",rp."IDBANQUE",rp."VALEUR",rp."DATY",rp."ETAT",
    ca.VAL as idbanquelib,
    CASE
        WHEN rp.ETAT = 1 THEN 'CREEE'
        WHEN rp.ETAT = 11 THEN 'VISEE'
        WHEN rp.ETAT = 0 THEN 'ANNULEE'
        END
           AS ETATLIB
from RAPPROCHEMENTBCMERE rp join CAISSE ca on ca.id=rp.idBanque
;
-- [717/1309] RAPPROCHEMENTGLOBALE_PIE
CREATE OR REPLACE FORCE VIEW "RAPPROCHEMENTGLOBALE_PIE" ("ID","VAL","DESCE","MONTANT") AS
select c.id, c.VAL , c.DESCE ,sum(f.pu * f.qte) as montant from FACTUREFOURNISSEURFILLE  f
                                                                    left join AS_INGREDIENTS a on f.IDPRODUIT = a.ID
                                                                    left join CATEGORIEINGREDIENT c on c.ID = a.CATEGORIEINGREDIENT
where c.id is not null
group by c.id, c.VAL,c.DESCE
;
-- [718/1309] RAPPROCHEMENTTRAVAUX
CREATE OR REPLACE FORCE VIEW "RAPPROCHEMENTTRAVAUX" ("ID","IDTRAVAUX","IDPERSONNEL","IDPERSONNELLIB","DUREEESTIMATIF_HMS","DUREEREEL_HMS","ECART_HMS","DUREEESTIMATIF_SECONDE","DUREEREEL_SECONDE","ECART_SECONDE","MONTANTESTIMATIF","MONTANTREEL","MONTANTECART","MOTSCLESSS") AS
SELECT SQ.ID,SQ.IDTRAVAUX,SQ.IDPERSONNEL,SQ.IDPERSONNELLIB,SQ.DUREEESTIMATIF_HMS,SQ.DUREEREEL_HMS,SQ.ECART_HMS,SQ.DUREEESTIMATIF_SECONDE,SQ.DUREEREEL_SECONDE,SQ.ECART_SECONDE,SQ.MONTANTESTIMATIF,SQ.MONTANTREEL,SQ.MONTANTECART,
	       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(IDTRAVAUX),'') || ' | ' || NVL(TO_CHAR(IDPERSONNEL),'') || ' | ' || NVL(TO_CHAR(IDPERSONNELLIB),'') || ' | ' || NVL(TO_CHAR(DUREEESTIMATIF_HMS),'') || ' | ' || NVL(TO_CHAR(DUREEREEL_HMS),'') || ' | ' || NVL(TO_CHAR(ECART_HMS),'') || ' | ' || NVL(TO_CHAR(DUREEESTIMATIF_SECONDE),'') || ' | ' || NVL(TO_CHAR(DUREEREEL_SECONDE),'') || ' | ' || NVL(TO_CHAR(ECART_SECONDE),'') || ' | ' || NVL(TO_CHAR(MONTANTESTIMATIF),'') || ' | ' || NVL(TO_CHAR(MONTANTREEL),'') || ' | ' || NVL(TO_CHAR(MONTANTECART),'')) AS MOTSCLESSS
	FROM (
	         SELECT
	             '' AS ID,
	             mo.IDTRAVAUX,
	             mo.IDPERSONNEL,
	             mo.idPersonnelLib,
	             mo.dureeEstimatifLib AS dureeEstimatif_hms,
	             pr.dureeReelHMS AS dureeReel_hms,
	             -- Ecart HMS calcule avec ABS pour eviter le signe -
	             LPAD(FLOOR(ABS(TO_NUMBER(mo.DUREEESTIMATIF - pr.dureeReel)) / 3600), 2, '0') || ':' ||
	             LPAD(FLOOR(MOD(ABS(TO_NUMBER(mo.DUREEESTIMATIF - pr.dureeReel)), 3600) / 60), 2, '0') || ':' ||
	             LPAD(MOD(ABS(TO_NUMBER(mo.DUREEESTIMATIF - pr.dureeReel)), 60), 2, '0')
	                 AS ecart_hms,
	             mo.DUREEESTIMATIF AS dureeEstimatif_seconde,
	             pr.dureeReel AS dureeReel_seconde,
	             -- Ecart Seconde en valeur absolue
	             ABS(mo.DUREEESTIMATIF - pr.dureeReel) AS ecart_seconde,
	             mo.montant AS montantEstimatif,
	             ((pr.dureeReel/60)/60)*mo.TAUXHORAIRE AS montantReel,
	             -- Ecart Montant en valeur absolue
	             ABS(mo.montant - (((pr.dureeReel/60)/60)*mo.TAUXHORAIRE)) AS montantEcart
	         FROM MOTRAVAUXLIB mo
	                  LEFT JOIN ProcessMaintenanceGlobal pr ON pr.IDPERSONNEL = mo.IDPERSONNEL AND pr.IDTRAVAUX = mo.IDTRAVAUX
	     ) SQ
;
-- [719/1309] RAPPROCHEMENT_BF_FOURNISSEUR
CREATE OR REPLACE FORCE VIEW "RAPPROCHEMENT_BF_FOURNISSEUR" ("ID","PRODUIT","NUMBL","QUANTITE","IDDETAILSFACTUREFOURNISSEUR","UNITE","IDBC_FILLE","REMARQUE","IDBC","DATY","ETAT","MAGASIN","PRODUITLIB","UNITELIB","MAGASINLIB","LIBELLEEXACTE","QTEENTREE","RESTEASORTIR","PU","PUAR","RESTEAENTRER") AS
SELECT
        abcc.ID,
        abcc.PRODUIT,
        abcc.NUMBL,
        abcc.QUANTITE,
        abcc.IDDETAILSFACTUREFOURNISSEUR,
        abcc.UNITE,
        abcc.IDBC_FILLE,
        abcc.REMARQUE,
        abcc.IDBC,
        abcc.DATY,
        abcc.ETAT,
        abcc.MAGASIN,
        abcc.PRODUITLIB,
        abcc.UNITELIB,
        abcc.MAGASINLIB,
        abcc.LIBELLEEXTACTE AS LIBELLEEXACTE,

        NVL(SUM(mvf.entree),0) AS QTEENTREE,

        NVL(abcc.QUANTITE,0) - NVL(SUM(mvf.entree),0) AS RESTEASORTIR,

        abcc.pu,
        abcc.puar,

        NVL(abcc.QUANTITE,0) - NVL(SUM(mvf.entree),0) AS RESTEAENTRER

    FROM AS_BONDELIVRAISON_LIBCPL abcc
    LEFT JOIN MVTSTOCKLIBVALIDER mv 
        ON mv.idobjet = abcc.numbl 
    LEFT JOIN mvtstockfille mvf 
        ON mv.id = mvf.idmvtstock  AND mvf.idproduit = abcc.produit

    GROUP BY 
        abcc.ID,
        abcc.PRODUIT,
        abcc.NUMBL,
        abcc.QUANTITE,
        abcc.IDDETAILSFACTUREFOURNISSEUR,
        abcc.UNITE,
        abcc.IDBC_FILLE,
        abcc.REMARQUE,
        abcc.IDBC,
        abcc.DATY,
        abcc.ETAT,
        abcc.MAGASIN,
        abcc.PRODUITLIB,
        abcc.UNITELIB,
        abcc.MAGASINLIB,
        abcc.LIBELLEEXTACTE,
        abcc.pu,
        abcc.puar
;
-- [720/1309] RAPPROCHEMENT_BF_LIVREE
CREATE OR REPLACE FORCE VIEW "RAPPROCHEMENT_BF_LIVREE" ("ID","PRODUIT","NUMBL","QUANTITE","IDDETAILSFACTUREFOURNISSEUR","UNITE","IDBC_FILLE","REMARQUE","IDBC","DATY","ETAT","MAGASIN","PRODUITLIB","UNITELIB","MAGASINLIB","LIBELLEEXACTE","QTEENTREE","RESTEASORTIR","PU","PUAR","RESTEAENTRER","MOTSCLESSS") AS
SELECT 
    SQ.ID,
    SQ.PRODUIT,
    SQ.NUMBL,
    SQ.QUANTITE,
    SQ.IDDETAILSFACTUREFOURNISSEUR,
    SQ.UNITE,
    SQ.IDBC_FILLE,
    SQ.REMARQUE,
    SQ.IDBC,
    SQ.DATY,
    SQ.ETAT,
    SQ.MAGASIN,
    SQ.PRODUITLIB,
    SQ.UNITELIB,
    SQ.MAGASINLIB,
    SQ.LIBELLEEXACTE,
    SQ.QTEENTREE,
    SQ.RESTEASORTIR,
    SQ.PU,
    SQ.PUAR,
    SQ.RESTEAENTRER,

    (
        NVL(TO_CHAR(SQ.ID),'') || ' | ' ||
        NVL(TO_CHAR(SQ.PRODUIT),'') || ' | ' ||
        NVL(TO_CHAR(SQ.NUMBL),'') || ' | ' ||
        NVL(TO_CHAR(SQ.QUANTITE),'') || ' | ' ||
        NVL(TO_CHAR(SQ.IDDETAILSFACTUREFOURNISSEUR),'') || ' | ' ||
        NVL(TO_CHAR(SQ.UNITE),'') || ' | ' ||
        NVL(TO_CHAR(SQ.IDBC_FILLE),'') || ' | ' ||
        NVL(TO_CHAR(SQ.REMARQUE),'') || ' | ' ||
        NVL(TO_CHAR(SQ.IDBC),'') || ' | ' ||
        NVL(TO_CHAR(SQ.DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' ||
        NVL(TO_CHAR(SQ.ETAT),'') || ' | ' ||
        NVL(TO_CHAR(SQ.MAGASIN),'') || ' | ' ||
        NVL(TO_CHAR(SQ.PRODUITLIB),'') || ' | ' ||
        NVL(TO_CHAR(SQ.UNITELIB),'') || ' | ' ||
        NVL(TO_CHAR(SQ.MAGASINLIB),'') || ' | ' ||
        NVL(TO_CHAR(SQ.LIBELLEEXACTE),'') || ' | ' ||
        NVL(TO_CHAR(SQ.QTEENTREE),'') || ' | ' ||
        NVL(TO_CHAR(SQ.RESTEASORTIR),'') || ' | ' ||
        NVL(TO_CHAR(SQ.PU),'') || ' | ' ||
        NVL(TO_CHAR(SQ.PUAR),'') || ' | ' ||
        NVL(TO_CHAR(SQ.RESTEAENTRER),'')
    ) AS MOTSCLESSS

FROM (
    SELECT
        abcc.ID,
        abcc.PRODUIT,
        abcc.NUMBL,
        abcc.QUANTITE,
        abcc.IDDETAILSFACTUREFOURNISSEUR,
        abcc.UNITE,
        abcc.IDBC_FILLE,
        abcc.REMARQUE,
        abcc.IDBC,
        abcc.DATY,
        abcc.ETAT,
        abcc.MAGASIN,
        abcc.PRODUITLIB,
        abcc.UNITELIB,
        abcc.MAGASINLIB,
        abcc.LIBELLEEXTACTE AS LIBELLEEXACTE,

        NVL(SUM(mvf.entree),0) AS QTEENTREE,

        NVL(abcc.QUANTITE,0) - NVL(SUM(mvf.entree),0) AS RESTEASORTIR,

        abcc.pu,
        abcc.puar,

        NVL(abcc.QUANTITE,0) - NVL(SUM(mvf.entree),0) AS RESTEAENTRER

    FROM AS_BONDELIVRAISON_LIBCPL abcc
    LEFT JOIN MVTSTOCKLIBVALIDER mv 
        ON mv.idobjet = abcc.numbl 
    LEFT JOIN mvtstockfille mvf 
        ON mv.id = mvf.idmvtstock  
       AND mvf.idproduit = abcc.produit

    GROUP BY 
        abcc.ID,
        abcc.PRODUIT,
        abcc.NUMBL,
        abcc.QUANTITE,
        abcc.IDDETAILSFACTUREFOURNISSEUR,
        abcc.UNITE,
        abcc.IDBC_FILLE,
        abcc.REMARQUE,
        abcc.IDBC,
        abcc.DATY,
        abcc.ETAT,
        abcc.MAGASIN,
        abcc.PRODUITLIB,
        abcc.UNITELIB,
        abcc.MAGASINLIB,
        abcc.LIBELLEEXTACTE,
        abcc.pu,
        abcc.puar
) SQ

WHERE SQ.RESTEAENTRER > 0
;
-- [721/1309] RAPPROCHEMENT_FFOURNISSEUR
CREATE OR REPLACE FORCE VIEW "RAPPROCHEMENT_FFOURNISSEUR" ("ID","PRODUIT","NUMBL","IDDETAILSFACTUREFOURNISSEUR","UNITE","IDBC_FILLE","REMARQUE","IDBC","DATY","ETAT","MAGASIN","PRODUITLIB","UNITELIB","MAGASINLIB","LIBELLEEXACTE","PU","PUAR","QUANTITE","QTEFACTURER","RESTEAFACTURER") AS
SELECT
        abcc.ID,
        abcc.PRODUIT,
        abcc.NUMBL,
        abcc.IDDETAILSFACTUREFOURNISSEUR,
        abcc.UNITE,
        abcc.IDBC_FILLE,
        abcc.REMARQUE,
        abcc.IDBC,
        abcc.DATY,
        abcc.ETAT,
        abcc.MAGASIN,
        abcc.PRODUITLIB,
        abcc.UNITELIB,
        abcc.MAGASINLIB,
        abcc.LIBELLEEXTACTE AS LIBELLEEXACTE,
        abcc.pu,
        abcc.puar,
        abcc.QUANTITE,
        NVL(SUM(ffv.qte),0) AS qtefacturer,
        abcc.QUANTITE - NVL(SUM(ffv.qte),0)  as resteAfacturer
    FROM AS_BONDELIVRAISON_LIBCPL abcc
    left join FACTUREFOURNISSEURFILLEValide  ffv on ffv.idfacturefournisseur = abcc.IDFACTUREFOURNISSEUR
    GROUP BY 
        abcc.ID,
        abcc.PRODUIT,
        abcc.NUMBL,
        abcc.QUANTITE,
        abcc.IDDETAILSFACTUREFOURNISSEUR,
        abcc.UNITE,
        abcc.IDBC_FILLE,
        abcc.REMARQUE,
        abcc.IDBC,
        abcc.DATY,
        abcc.ETAT,
        abcc.MAGASIN,
        abcc.PRODUITLIB,
        abcc.UNITELIB,
        abcc.MAGASINLIB,
        abcc.LIBELLEEXTACTE,
        abcc.pu,
        abcc.puar
;
-- [722/1309] RAPPROCHEMENT_FFOURNISSEURGRP
CREATE OR REPLACE FORCE VIEW "RAPPROCHEMENT_FFOURNISSEURGRP" ("NUMBL","TOTALLIVRER","TOTALFACTURER") AS
SELECT bc.NUMBL, sum (bc.quantite ) AS totallivrer , sum (bc.qtefacturer ) AS totalFacturer FROM RAPPROCHEMENT_FFOURNISSEUR bc GROUP BY bc.NUMBL
;
-- [723/1309] AS_BONDELIVRAISON_TRAITE
CREATE OR REPLACE FORCE VIEW "AS_BONDELIVRAISON_TRAITE" ("ID","REMARQUE","IDBC","DATY","ETAT","MAGASIN","MAGASINLIB","ETATLIB","IDFOURNISSEUR","IDFOURNISSEURLIB","IDFACTUREFOURNISSEUR","IDTRAITE","TRAITE") AS
SELECT
    abm."ID",abm."REMARQUE",abm."IDBC",abm."DATY",abm."ETAT",abm."MAGASIN",abm."MAGASINLIB",abm."ETATLIB",abm."IDFOURNISSEUR",abm."IDFOURNISSEURLIB",abm."IDFACTUREFOURNISSEUR",
    CASE
        WHEN abrcp.totalFacturer = 0 THEN '0'
        WHEN abrcp.totallivrer > abrcp.totalFacturer THEN '1'
        WHEN abrcp.totalFacturer = abrcp.totallivrer THEN '2'
        WHEN abrcp.totallivrer < abrcp.totalFacturer THEN '3'
    END AS IDTRAITE,
    CASE
        WHEN abrcp.totalFacturer = 0 THEN 'Non Trait&eacute;'
        WHEN abrcp.totallivrer > abrcp.totalFacturer  THEN 'Trait&eacute; Partiellement'
        WHEN abrcp.totalFacturer = abrcp.totallivrer THEN 'Trait&eacute;'
        WHEN abrcp.totallivrer < abrcp.totalFacturer THEN 'Trait&eacute; avec surplus'
    END AS TRAITE
FROM AS_BONDELIVRAISON_LIB abm
         left join RAPPROCHEMENT_FFOURNISSEURGRP abrcp on abrcp.NUMBL = abm.id
;
-- [724/1309] RECAP_SAL_ALL
CREATE OR REPLACE FORCE VIEW "RECAP_SAL_ALL" ("MOIS","ANNEE","SALAIRE","INDEMNITE","AVANTAGE_EN_NATURE","SALAIRE_BRUT","IRSA","CNAPS_TRAVAILLEUR","MONTANT_NET_PAYER","CNAPS_EMPLOYEUR","CNAPS_A_PAYER","ID") AS
SELECT
    pe.mois,
    pe.annee,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie = 'PR000041' THEN NVL(pe.gain, 0)
                  ELSE 0
        END), 2) AS salaire,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie IN ('PR000021', 'PR000061', 'PR000081', 'PR000001') THEN NVL(pe.gain, 0)
                  ELSE 0
        END), 2) AS indemnite,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie = 'PR000201' THEN NVL(pe.gain, 0)
                  ELSE 0
        END), 2) AS avantage_en_nature,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie = 'PRUNI' THEN NVL(pegi.imposable, 0)
                  ELSE 0
        END), 2) AS salaire_brut,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie = 'PR000141' THEN NVL(pe.retenue, 0)
                  ELSE 0
        END), 2) AS irsa,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie = 'PR000101' THEN NVL(pe.retenue, 0)
                  ELSE 0
        END), 2) AS cnaps_travailleur,

    CAST(ROUND(SUM(CASE
                       WHEN pe.idelementpaie = 'PR000210A' THEN NVL(pe.gain, 0)
                       ELSE 0
        END), 2) AS NUMBER(30, 2))  AS montant_net_payer,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie = 'PR000101' THEN NVL(pe.retenue, 0)
                  ELSE 0
        END) * 13, 2) AS cnaps_employeur,

    ROUND(SUM(CASE
                  WHEN pe.idelementpaie = 'PR000101' THEN NVL(pe.retenue, 0)
                  ELSE 0
        END) * 14, 2) AS cnaps_a_payer,
    pe.idedition AS id

FROM paie_edition pe
         LEFT JOIN paie_edition_gain_imp pegi
                   ON pe.idpersonnel = pegi.idpersonnel
                       AND pe.mois = pegi.mois
                       AND pe.annee = pegi.annee
                       AND pe.idelementpaie IN (
                                                'PR000041', 'PR000021', 'PR000061', 'PR000081', 'PR000001',
                                                'PR000201', 'PRUNI', 'PR000141', 'PR000101', 'PR000210A'
                           )
GROUP BY pe.annee, pe.mois, pe.IDEDITION
;
-- [725/1309] RECAPITULATIF_SALAIRE_ALL
CREATE OR REPLACE FORCE VIEW "RECAPITULATIF_SALAIRE_ALL" ("MOIS","ANNEE","SALAIRE","INDEMNITE","AVANTAGE_EN_NATURE","SALAIRE_BRUT","IRSA","CNAPS_TRAVAILLEUR","MONTANT_NET_PAYER","CNAPS_EMPLOYEUR","CNAPS_A_PAYER","ID") AS
SELECT recap_sal_all.mois,
       recap_sal_all.annee,
       recap_sal_all.salaire AS salaire,
       recap_sal_all.indemnite AS indemnite,
       recap_sal_all.avantage_en_nature AS avantage_en_nature,
       recap_sal_all.salaire_brut AS salaire_brut,
       recap_sal_all.irsa AS irsa,
       recap_sal_all.cnaps_travailleur AS cnaps_travailleur,
       CAST(recap_sal_all.montant_net_payer AS NUMBER(30, 2)) AS montant_net_payer,
       recap_sal_all.cnaps_employeur AS cnaps_employeur,
       recap_sal_all.cnaps_a_payer AS cnaps_a_payer,
       recap_sal_all.id
FROM recap_sal_all
;
-- [726/1309] RECAPITULATIF_ALL_FINAL
CREATE OR REPLACE FORCE VIEW "RECAPITULATIF_ALL_FINAL" ("MOIS","ANNEE","SALAIRE","INDEMNITE","AVANTAGE_EN_NATURE","SALAIRE_BRUT","IRSA","CNAPS_TRAVAILLEUR","MONTANT_NET_PAYER","CNAPS_EMPLOYEUR","CNAPS_A_PAYER","TOTAL_FRM","ID","MOISLIB") AS
SELECT rs.mois,
       rs.annee,
       rs.salaire,
       rs.indemnite,
       rs.avantage_en_nature,
       rs.salaire_brut,
       rs.irsa,
       rs.cnaps_travailleur,
       CAST(rs.montant_net_payer AS NUMBER(30, 2)) AS MONTANT_NET_PAYER,
       rs.cnaps_employeur,
       rs.cnaps_a_payer,
       frm.total_frm,
       rs.id,
       TO_CHAR(TO_DATE(rs.mois, 'MM'), 'MONTH', 'NLS_DATE_LANGUAGE=FRENCH') AS MOISLIB
FROM recapitulatif_salaire_all rs
         LEFT JOIN frm_mois_annee frm ON rs.mois = frm.mois AND rs.annee = frm.annee
;
-- [727/1309] RECEPTIONOACDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "RECEPTIONOACDETAIL_LIB" ("ID","IDMERE","IDLOT","IDBATIMENT","IDPARQUET","IDQUALITETRIAGEOEUF","QTERECUS","IDLOTLIB","IDBATIMENTLIB","IDPARQUETLIB","IDQUALITETRIAGEOEUFLIB") AS
SELECT d."ID",
       d."IDMERE",
       d."IDLOT",
       d."IDBATIMENT",
       d."IDPARQUET",
       d."IDQUALITETRIAGEOEUF",
       d."QTERECUS",
       l."NOMLOT"       AS "IDLOTLIB",
       b."NOMBATIMENT"  AS "IDBATIMENTLIB",
       p."VAL"          AS "IDPARQUETLIB",
       qt."VAL"         AS "IDQUALITETRIAGEOEUFLIB"
FROM "RECEPTIONOACDETAIL" d
         LEFT JOIN "LOT" l ON l."ID" = d."IDLOT"
         LEFT JOIN "BATIMENT" b ON b."ID" = d."IDBATIMENT"
         LEFT JOIN "PARQUET" p ON p."ID" = d."IDPARQUET"
         LEFT JOIN "QUALITETRIAGEOEUF" qt ON qt."ID" = d."IDQUALITETRIAGEOEUF"
;
-- [728/1309] RECEPTIONOAC_LIB
CREATE OR REPLACE FORCE VIEW "RECEPTIONOAC_LIB" ("ID","DATERECEPTION","DATEPONTE","DATECOLLECTE","IDNUMEROCOLLECTE","HEUREDEPARTFERME","HEUREARRIVEECOUVOIR","IDRESPONSABLE","IDCHAMBREFROIDE","IDCHAUFFEUR","IDVEHICULE","TEMPERATUREMINVEHICULE","TEMPERATUREMAXVEHICULE","IDPROVENANCE","ETAT","IDNUMEROCOLLECTELIB","IDRESPONSABLELIB","IDCHAMBREFROIDELIB","IDCHAUFFEURLIB","IDVEHICULELIB","ETATLIB") AS
SELECT r."ID",
       r."DATERECEPTION",
       r."DATEPONTE",
       r."DATECOLLECTE",
       r."IDNUMEROCOLLECTE",
       r."HEUREDEPARTFERME",
       r."HEUREARRIVEECOUVOIR",
       r."IDRESPONSABLE",
       r."IDCHAMBREFROIDE",
       r."IDCHAUFFEUR",
       r."IDVEHICULE",
       r."TEMPERATUREMINVEHICULE",
       r."TEMPERATUREMAXVEHICULE",
       r."IDPROVENANCE",
       r."ETAT",
       nc."VAL"                          AS "IDNUMEROCOLLECTELIB",
       resp."NOM" || ' ' || resp."PRENOM" AS "IDRESPONSABLELIB",
       cf."VAL"                          AS "IDCHAMBREFROIDELIB",
       chf."NOM" || ' ' || chf."PRENOM"  AS "IDCHAUFFEURLIB",
       v."VAL"                           AS "IDVEHICULELIB",
       CASE r."ETAT"
            WHEN 1  THEN 'CREE'
            WHEN 11 THEN 'VALIDE'
            WHEN 0  THEN 'ANULLE'
       END                                AS "ETATLIB"
FROM "RECEPTIONOAC" r
         LEFT JOIN "NUMEROCOLLECTE" nc ON nc."ID" = r."IDNUMEROCOLLECTE"
         LEFT JOIN "LOG_PERSONNEL" resp ON resp."ID" = r."IDRESPONSABLE"
         LEFT JOIN "MAGASIN2" cf ON cf."ID" = r."IDCHAMBREFROIDE"
         LEFT JOIN "LOG_PERSONNEL" chf ON chf."ID" = r."IDCHAUFFEUR"
         LEFT JOIN "VEHICULE" v ON v."ID" = r."IDVEHICULE" WHERE r.IDPROVENANCE IS NULL
;
-- [729/1309] RECEPTIONPOUSSINAEDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "RECEPTIONPOUSSINAEDETAIL_LIB" ("ID","IDMERE","IDQUALITEPOUSSIN","IDSEXE","QTE","IDQUALITEPOUSSINLIB","IDSEXELIB","IDLOT") AS
SELECT
    rd."ID",rd."IDMERE",rd."IDQUALITEPOUSSIN",rd."IDSEXE",rd."QTE",
    qp.val AS idQualitePoussinLib,
    s.val  AS idSexeLib,
    mere.idlot AS idlot
FROM receptionPoussinAeroportDetail rd
         LEFT JOIN qualitePoussin qp ON rd.idQualitePoussin = qp.id
         LEFT JOIN sexe s ON rd.idSexe = s.id
		LEFT JOIN receptionpoussinaeroport mere ON mere.id=rd.idmere
;
-- [730/1309] QTE_DISPO_LOT_SEXE_QUALITELIB
CREATE OR REPLACE FORCE VIEW "QTE_DISPO_LOT_SEXE_QUALITELIB" ("IDLOT","IDQUALITE","IDSEXE","QTE") AS
SELECT
    rpd.IDLOT              AS IDLOT,
    rpd.IDQUALITEPOUSSIN   AS IDQUALITE,
    rpd.IDSEXE             AS IDSEXE,
    SUM(rpd.QTE)           AS QTE
FROM RECEPTIONPOUSSINAEDETAIL_LIB rpd
GROUP BY rpd.IDLOT, rpd.IDQUALITEPOUSSIN, rpd.IDSEXE
;
-- [731/1309] RECEPTIONPOUSSINAEROPORT_LIB
CREATE OR REPLACE FORCE VIEW "RECEPTIONPOUSSINAEROPORT_LIB" ("ID","IDLOT","DATY","QTERECUS","REMARQUE","HEUREDEPART","HEUREARRIVE","IDLOTLIB","NBRCARTONMALE","NBRCARTONFEMELLE","NBRCARTONTOTAL","ETAT","ETATLIB") AS
SELECT
    r.ID,r.IDLOT,r.DATY,r.QTERECUS,r.REMARQUE, r.heureDepart,r.heureArrive,
    l.nomLot AS idLotLib,
    NVL(r.nbrCartonMale, 0) AS nbrcartonmale,
    NVL(r.nbrCartonFemelle, 0) AS nbrcartonfemelle,
    NVL(r.nbrCartonMale, 0) + NVL(r.nbrCartonFemelle, 0) AS nbrCartonTotal,
    r.etat AS etat,
    CASE
        WHEN r.ETAT = 1 THEN 'CR&Eacute;&Eacute;'
        WHEN r.ETAT = 11 THEN 'VALID&Eacute;'
        END
        AS ETATLIB
FROM receptionPoussinAeroport r
         LEFT JOIN lot l ON r.idLot = l.id
;
-- [732/1309] RECETTEMONTANT
CREATE OR REPLACE FORCE VIEW "RECETTEMONTANT" ("ID","IDPRODUITS","IDINGREDIENTS","QUANTITE","UNITE","LIBINGREDIENTS","IDUNITE","SOURCE","COMPOSE","QTEAV","QTETOTAL","TYPESTOCK","REFPOST","REFQUALIFICATION","CATEGORIEINGREDIENT","NIVEAU") AS
select
    rec.ID,rec.IDPRODUITS,rec.IDINGREDIENTS,cast(rec.QUANTITE as number(30,10)) as QUANTITE,rec.UNITE,'-' as libIngredients,'-' as IDUNITE,'' as source,0 as COMPOSE,
    cast(0 as number(30,10)) as qteav,
    cast(0 as number(30,10)) as qtetotal,
    i.TYPESTOCK,
    i.REFPOST,
    i.REFQUALIFICATION,
    i.CATEGORIEINGREDIENT ,
    0 as niveau
from as_recette rec
         left join AS_INGREDIENTS i on rec.IDINGREDIENTS=i.ID
;
-- [733/1309] RECETTE_FILLE_LIB
CREATE OR REPLACE FORCE VIEW "RECETTE_FILLE_LIB" ("ID","IDMERE","IDINGREDIENT","IDUNITE","QTE","IDINGREDIENTLIB","IDUNITELIB") AS
SELECT
    rf."ID",rf."IDMERE",rf."IDINGREDIENT",rf."IDUNITE",rf."QTE",
    i.LIBELLE AS IDINGREDIENTLIB,
    u.VAL AS IDUNITELIB
FROM RECETTE_FILLE rf
         LEFT JOIN AS_INGREDIENTS i
                   ON rf.IDINGREDIENT = i.ID
         LEFT JOIN AS_UNITE u
                   ON rf.IDUNITE = u.ID
;
-- [734/1309] RECETTE_MERE_LIB
CREATE OR REPLACE FORCE VIEW "RECETTE_MERE_LIB" ("ID","IDPRODUIT","DATY","NOMRECETTE","VERSION","IDPRODUITLIB") AS
SELECT
    rm."ID",rm."IDPRODUIT",rm."DATY",rm."NOMRECETTE",rm."VERSION",
    i.LIBELLE AS IDPRODUITLIB
FROM RECETTE_MERE rm
         LEFT JOIN AS_INGREDIENTS i
                   ON rm.IDPRODUIT = i.ID
;
-- [735/1309] RECLAMATIONLIB
CREATE OR REPLACE FORCE VIEW "RECLAMATIONLIB" ("ID","IDVENTEFILLE","DATY","IDTYPE","ETAT","ETATLIB","IDTYPELIB","IDVENTE","QTE") AS
SELECT
    r.ID,
    r.idVenteFille,
    r.daty,
    r.idType,
    r.etat,

    CASE r.etat
        WHEN 1  THEN 'Cree'
        WHEN 7 THEN 'Valide'
        WHEN 11 THEN 'Cloture'
        WHEN 0 THEN 'Rejete'
        ELSE 'Autre'
        END AS etatLib,

    tr.VAL AS idTypeLib,
    vd.IDVENTE,
    r.qte
FROM reclamation r
         LEFT JOIN TYPERECLAMATION tr
                   ON tr.ID = r.idType
         LEFT JOIN vente_details vd on vd.id = r.IDVENTEFILLE
;
-- [736/1309] RELEVERDETAILCPL
CREATE OR REPLACE FORCE VIEW "RELEVERDETAILCPL" ("ID","IDMERE","DATY","DATYVALEUR","DESIGNATION","DEBIT","CREDIT","IDCAISSE","COMPTE") AS
select rd."ID",rd."IDMERE",rd."DATY",rd."DATYVALEUR",rd."DESIGNATION",rd."DEBIT",rd."CREDIT" , r.IDCAISSE, cai.COMPTE from ReleverDetail rd join RELEVER r on rd.IDMERE = r.id left join CAISSE cai on cai.id=r.IDCAISSE
;
-- [737/1309] RELEVERDETAILNR
CREATE OR REPLACE FORCE VIEW "RELEVERDETAILNR" ("ID","DESIGNATION","DEBIT","CREDIT","DATYVALEUR","IDCAISSE","COMPTE") AS
SELECT
    rd.ID,
    rd.DESIGNATION,
    rd.DEBIT,
    rd.CREDIT,
    rd.DATYVALEUR,
    r.IDCAISSE, cai.COMPTE
FROM RELEVERDETAIL rd
         JOIN RELEVER r ON r.ID = rd.IDMERE
         left join CAISSE cai on cai.id=r.IDCAISSE
WHERE
    r.ETAT >= 11
  AND rd.ID NOT IN (
    SELECT rpf.IDRELEVERDETAIL
    FROM RAPPROCHEMENTBC rpf join RAPPROCHEMENTBCMERE rp on rpf.idmere=rp.id
    WHERE rpf.IDRELEVERDETAIL IS NOT NULL AND rp.ETAT>=11
)
;
-- [738/1309] RELEVERDETAILNRMVT
CREATE OR REPLACE FORCE VIEW "RELEVERDETAILNRMVT" ("ID","DESIGNATION","DEBIT","CREDIT","DATYVALEUR","IDCAISSE","COMPTE","MOUVEMENT") AS
SELECT
    ID,
    DESIGNATION,
    CAST(DEBIT AS NUMBER(32,2)) AS DEBIT,
    CAST(CREDIT AS NUMBER(32,2)) AS CREDIT,
    DATYVALEUR,
    IDCAISSE,
    COMPTE,
    CASE
        WHEN DEBIT > 0 THEN 1
        WHEN CREDIT > 0 THEN 2
        ELSE 0
        END AS MOUVEMENT
FROM RELEVERDETAILNR
;
-- [739/1309] RELEVERDETAILORDER
CREATE OR REPLACE FORCE VIEW "RELEVERDETAILORDER" ("ID","IDMERE","DATY","DATYVALEUR","DESIGNATION","DEBIT","CREDIT","SOLDE") AS
select "ID","IDMERE","DATY","DATYVALEUR","DESIGNATION","DEBIT","CREDIT","SOLDE" from ReleverDetail ORDER BY TO_NUMBER(REGEXP_REPLACE(id, '[^0-9]', '')) ASC
;
-- [740/1309] RELEVERDETAILR
CREATE OR REPLACE FORCE VIEW "RELEVERDETAILR" ("ID","DESIGNATION","DEBIT","CREDIT","DATYVALEUR","IDCAISSE","COMPTE") AS
SELECT
    rd.ID,
    rd.DESIGNATION,
    rd.DEBIT,
    rd.CREDIT,
    rd.DATYVALEUR,
    r.IDCAISSE, cai.COMPTE
FROM RELEVERDETAIL rd
         JOIN RELEVER r ON r.ID = rd.IDMERE
         left join CAISSE cai on cai.id=r.IDCAISSE
WHERE
    r.ETAT >= 11
  AND rd.ID IN (
    SELECT rpf.IDRELEVERDETAIL
    FROM RAPPROCHEMENTBC rpf join RAPPROCHEMENTBCMERE rp on rpf.idmere=rp.id
    WHERE rpf.IDRELEVERDETAIL IS NOT NULL AND rp.ETAT>=11
)
;
-- [741/1309] RELEVERDETAILRMVT
CREATE OR REPLACE FORCE VIEW "RELEVERDETAILRMVT" ("ID","DESIGNATION","DEBIT","CREDIT","DATYVALEUR","IDCAISSE","COMPTE","MOUVEMENT") AS
SELECT
    ID,
    DESIGNATION,
    CAST(DEBIT AS NUMBER(32,2)) AS DEBIT,
    CAST(CREDIT AS NUMBER(32,2)) AS CREDIT,
    DATYVALEUR,
    IDCAISSE,
    COMPTE,
    CASE
        WHEN DEBIT > 0 THEN 1
        WHEN CREDIT > 0 THEN 2
        ELSE 0
        END AS MOUVEMENT
FROM RELEVERDETAILR
;
-- [742/1309] RELEVERFABCPL
CREATE OR REPLACE FORCE VIEW "RELEVERFABCPL" ("ID","DATY","IDFAB","IDRELEVE","ETAT","IDCATEGORIE") AS
SELECT
    R."ID",R."DATY",R."IDFAB",R."IDRELEVE",R."ETAT",
    C.IDCATEGORIE
FROM RELEVEFAB R
    LEFT JOIN COMPTEURMAINTENANCE C ON C.ID = R.IDRELEVE
;
-- [743/1309] RELEVERLIB
CREATE OR REPLACE FORCE VIEW "RELEVERLIB" ("ID","DATY","IDCAISSE","ETAT","IDCAISSELIB","DATYDEBUT","DATYFIN","ETATLIB") AS
select
    r."ID",r."DATY",r."IDCAISSE",r."ETAT" ,
    c.val as idcaisselib,
    r.DATYDEBUT,
    r.DATYFIN,
    CASE
        WHEN r.ETAT = 1 THEN 'CREEE'
        WHEN r.ETAT = 11 THEN 'VISEE'
        WHEN r.ETAT = 0 THEN 'ANNULEE'
        END
          AS ETATLIB
from Relever r
         join caisse c on c.id = r.idcaisse
;
-- [744/1309] RELEVER_CLIENT_OPT
CREATE OR REPLACE FORCE VIEW "RELEVER_CLIENT_OPT" ("DATY","COMPTE_AUX","LIBELLE","SOLDE_INITIAL","DEBIT","CREDIT","SOLDE_FINAL") AS
SELECT
    e.DATY                  AS daty,
    se.COMPTE_AUX            AS compte_aux,
    se.LIBELLEPIECE          AS libelle,
    0                        AS solde_initial,
    se.DEBIT                 AS debit,
    se.CREDIT                AS credit,
    0                        AS solde_final
FROM COMPTA_SOUS_ECRITURE se
         JOIN COMPTA_ECRITURE e ON e.ID = se.IDMERE
WHERE se.COMPTE_AUX IS NOT NULL
;
-- [745/1309] REMBOURSEMENTLIB
CREATE OR REPLACE FORCE VIEW "REMBOURSEMENTLIB" ("ID","IDAVANCE","MOIS","ANNEE","MONTANT","REMARQUE","DATY","ETAT","PERSONNEL","TYPEAVANCELIB","ETATLIB","MATRICULE","MOISLIB","MOTSCLESSS") AS
SELECT SQ.ID,SQ.IDAVANCE,SQ.MOIS,SQ.ANNEE,SQ.MONTANT,SQ.REMARQUE,SQ.DATY,SQ.ETAT,SQ.PERSONNEL,SQ.TYPEAVANCELIB,SQ.ETATLIB,SQ.MATRICULE,SQ.MOISLIB,
	  (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(IDAVANCE),'') || ' | ' || NVL(TO_CHAR(MOIS),'') || ' | ' || NVL(TO_CHAR(ANNEE),'') || ' | ' || NVL(TO_CHAR(MONTANT),'') || ' | ' || NVL(TO_CHAR(REMARQUE),'') || ' | ' || NVL(TO_CHAR(DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(ETAT),'') || ' | ' || NVL(TO_CHAR(PERSONNEL),'') || ' | ' || NVL(TO_CHAR(TYPEAVANCELIB),'') || ' | ' || NVL(TO_CHAR(ETATLIB),'') || ' | ' || NVL(TO_CHAR(MATRICULE),'') || ' | ' || NVL(TO_CHAR(MOISLIB),'')) AS MOTSCLESSS
	FROM (
	  SELECT pr.id,
	       pr.idavance,
	       pr.mois,
	       pr.annee,
	       pr.montant,
	       pr.remarque,
	       pr.daty,
	       pr.etat,
	       lp.nom || ' ' || lp.prenom  AS personnel,
	       t.val AS typeavancelib,
	       CASE
	           WHEN pr.etat = 1 THEN 'CREE'
	           WHEN pr.etat = 11 THEN 'VALIDE'
	           ELSE NULL
	           END AS etatlib,
	       pip.matricule,
	       TO_CHAR(
	               TO_DATE(TO_CHAR(pr.mois, 'FM00'), 'MM'),
	               'FMMonth',
	               'NLS_DATE_LANGUAGE=FRENCH'
	       ) AS moisLib
	FROM remboursement pr
	         LEFT JOIN avance a ON a.id = pr.idavance
	         LEFT JOIN typeavance t ON t.id = a.idtypeavance
	         LEFT JOIN paie_info_personnel pip ON pip.id = a.idpersonnel
	         LEFT JOIN log_personnel lp ON lp.id=a.idpersonnel
	 
	) SQ
;
-- [746/1309] REMISEFILLELIB
CREATE OR REPLACE FORCE VIEW "REMISEFILLELIB" ("ID","REMISE","IDCATEGORIECLIENT","IDCATEGORIECLIENTLIB","IDPRODUIT","IDPRODUITLIB","CATEGORIEPRODUIT","CATEGORIEPRODUITLIB","IDPOINT","IDPOINTLIB","IDREMISE") AS
SELECT 
	rf.id,
	rf.remise,
	rf.idCategorieClient,
	tp.val AS idCategorieClientlib,
	rf.idProduit,
	ai.libelle,
	rf.cateGorieProduit,
	cti.val AS CATEGORIEPRODUITLIB,
	rf.idPoint,
	p.val AS idPointLib,
	rf.idRemise
FROM RemiseFille rf
LEFT JOIN typeclient tp ON tp.id = rf.idCategorieClient
LEFT JOIN as_ingredients ai ON ai.id = rf.idProduit
LEFT JOIN point p ON p.id = rf.idPoint
LEFT JOIN categorieingredient cti ON cti.id = rf.CATEGORIEPRODUIT
;
-- [747/1309] REMISEFILLEMERE
CREATE OR REPLACE FORCE VIEW "REMISEFILLEMERE" ("ID","REMISE","IDCATEGORIECLIENT","IDPRODUIT","CATEGORIEPRODUIT","IDPOINT","IDREMISE","NOM","DATY","DATEDEBUT","DATEFIN","ETAT") AS
select rf."ID",rf."REMISE",rf."IDCATEGORIECLIENT",rf."IDPRODUIT",rf."CATEGORIEPRODUIT",rf."IDPOINT",rf."IDREMISE",r.nom,r.daty,r.dateDebut,r.dateFin,r.etat from remiseFille rf left join remise r on r.id=rf.idremise
;
-- [748/1309] REMISEFILLEMERELIB
CREATE OR REPLACE FORCE VIEW "REMISEFILLEMERELIB" ("IDMERE","IDFILLE","DATY","NOM","DATEDEBUT","DATEFIN","ETAT","REMISE","IDCATEGORIECLIENT","IDCATEGORIECLIENTLIB","IDPRODUIT","IDPRODUITLIB","CATEGORIEPRODUIT","CATEGORIEPRODUITLIB","IDPOINT","IDPOINTLIB") AS
SELECT 
r.id AS idmere,
rf.id AS idfille,
r.daty,
r.nom,
r.datedebut,
r.datefin,
r.etat,
rf.remise,
rf.idCategorieClient,
tp.val AS idCategorieClientLib,
rf.idProduit,
ai.libelle AS idProduitLib,
rf.cateGorieProduit,
cti.val AS cateGorieProduitLib,
rf.idPoint,
p.val AS idPointLib
FROM Remise r 
LEFT JOIN RemiseFille rf ON r.id = rf.idRemise
LEFT JOIN typeclient tp ON tp.id = rf.idCategorieClient
LEFT JOIN as_ingredients ai ON ai.id = rf.idProduit
LEFT JOIN point p ON p.id = rf.idPoint
LEFT JOIN categorieingredient cti ON cti.id = rf.CATEGORIEPRODUIT
;
-- [749/1309] REMISEFILLEMEREVISE
CREATE OR REPLACE FORCE VIEW "REMISEFILLEMEREVISE" ("ID","REMISE","IDCATEGORIECLIENT","IDPRODUIT","CATEGORIEPRODUIT","IDPOINT","IDREMISE","NOM","DATY","DATEDEBUT","DATEFIN","ETAT") AS
select rf."ID",rf."REMISE",rf."IDCATEGORIECLIENT",rf."IDPRODUIT",rf."CATEGORIEPRODUIT",rf."IDPOINT",rf."IDREMISE",r.nom,r.daty,r.dateDebut,r.dateFin,r.etat from remiseFille rf left join remise r on r.id=rf.idremise where r.etat>=11
;
-- [750/1309] REMISELIB
CREATE OR REPLACE FORCE VIEW "REMISELIB" ("ID","DATY","NOM","DATEDEBUT","DATEFIN","ETAT","ETATLIB") AS
SELECT
	rem.ID , 
	rem.DATY , 
	rem.NOM, 
	rem.DATEDEBUT , 
	rem.DATEFIN , 
	rem.ETAT,
	CASE
		WHEN rem.ETAT = 1
            THEN 'CR&Eacute;&Eacute;E'
		WHEN rem.ETAT = 0
            THEN 'ANNUL&Eacute;E'
		WHEN rem.ETAT = 11
            THEN 'VIS&Eacute;E'
	END AS ETATLIB
FROM
	REMISE rem
;
-- [751/1309] REMISELIB_A
CREATE OR REPLACE FORCE VIEW "REMISELIB_A" ("ID","DATY","NOM","DATEDEBUT","DATEFIN","ETAT","ETATLIB") AS
SELECT
	rem.ID , 
	rem.DATY , 
	rem.NOM, 
	rem.DATEDEBUT , 
