	CASE
		WHEN rem.ETAT = 1
            THEN 'CR&Eacute;&Eacute;E'
		WHEN rem.ETAT = 0
            THEN 'ANNUL&Eacute;E'
		WHEN rem.ETAT = 11
            THEN 'VIS&Eacute;E'
	END AS ETATLIB
FROM
	REMISE rem
	WHERE rem.ETAT = 0
;
