-- [754/1309] REPARTIRIONPGGROUPEE
CREATE OR REPLACE FORCE VIEW "REPARTIRIONPGGROUPEE" ("IDFACTUREFILLE","MONTANT") AS
SELECT
    r.IDFACTUREFILLE ,
    NVL(SUM(r.montant), 0) AS montant
FROM REPARTIRIONPG r
GROUP BY r.IDFACTUREFILLE
;
-- [755/1309] FACTUREFOURNISSEURFILLECPL
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURFILLECPL" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","IDPRODUITLIB","QTE","PU","REMISES","IDBCDETAIL","TVA","COMPTE","IDDEVISE","DATY","MONTANT","MONTANTTOTAL","MONTANTREMISE","MONTANTHT","MONTANTTVA","MONTANTTTC","FRAISACCESOIRE","MONTANTAVECFRAISACCESSOIRE","PUAVECFRAISACCESSOIRE","LIBELLEEXACTE","IDPREVISION","IDPOINT","IDPOINTLIB","IDMAGASIN","IDMAGASINLIB","IDCATEGORIE","IDCATEGORIELIB","DESIGNATION") AS
(
SELECT f.ID,
       f.IDFACTUREFOURNISSEUR,
       f.IDPRODUIT,
       p.LIBELLE                                                         AS IDPRODUITLIB,
       f.QTE,
       f.PU,
       f.REMISES,
       f.IDBCDETAIL,
       f.TVA,
       f.COMPTE,
       f.IDDEVISE,
       f2.DATY,

       ----------------------------------------------------------
       -- 1 Montant HT brut
       ----------------------------------------------------------
       CAST(f.QTE * f.PU AS NUMBER(30, 2))                               AS montant,
       CAST(f.QTE * f.PU AS NUMBER(30, 2))                               AS montanttotal,

       ----------------------------------------------------------
       -- 2 Montant remise (appliquee sur HT)
       ----------------------------------------------------------
       CAST((NVL(f.remises, 0) / 100) * (f.QTE * f.PU) AS NUMBER(30, 2)) AS montantRemise,

       ----------------------------------------------------------
       -- 3 Montant HT net apres remise
       ----------------------------------------------------------
       CAST((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU))
           AS NUMBER(30, 2))                                             AS montantht,

       ----------------------------------------------------------
       -- 4 TVA sur montant HT net
       ----------------------------------------------------------
       CAST(
               ((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU)))
                   * f.TVA / 100
           AS NUMBER(30, 2)
       )                                                                 AS montanttva,

       ----------------------------------------------------------
       -- 5 Montant TTC net (HT net + TVA)
       ----------------------------------------------------------
       CAST(
               ((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU)))
                   + (
                   ((f.QTE * f.PU) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU)))
                       * f.TVA / 100
                   )
           AS NUMBER(30, 2)
       )                                                                 AS montantttc,

       ----------------------------------------------------------
       -- 6 Frais accessoires
       ----------------------------------------------------------
       NVL(r.montant, 0)                                                 AS fraisaccesoire,

       ----------------------------------------------------------
       -- 7 Montant total avec frais (TTC + accessoires)
       ----------------------------------------------------------
       CAST(
               (
                   ((f.QTE * f.PU * f.TAUXDECHANGE) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU * f.TAUXDECHANGE)))
                   )
                   + NVL(r.montant, 0)
           AS NUMBER(30, 2)
       )                                                                 AS montantavecfraisaccessoire,

       ----------------------------------------------------------
       -- 8 PU unitaire HT + accessoires
       ----------------------------------------------------------
       CAST(
               (
                   (
                       ((f.QTE * f.PU * f.TAUXDECHANGE) - ((NVL(f.remises, 0) / 100) * (f.QTE * f.PU * f.TAUXDECHANGE)))
                       )
                       + NVL(r.montant, 0)
                   ) / f.QTE
           AS NUMBER(30, 2)
       )                                                                 AS puavecfraisaccessoire,

       ----------------------------------------------------------
       -- Info produit & localisation
       ----------------------------------------------------------
       NVL(p.LIBELLEEXTACTE, p.LIBELLE)                                  AS libelleexacte,
       f.IDPREVISION,
       p2.ID                                                             AS idpoint,
       p2.VAL                                                            AS idpointlib,
       m.ID                                                              AS idmagasin,
       m.VAL                                                             AS idmagasinlib,
       c.ID                                                              AS idcategorie,
       c.VAL                                                             AS idcategorielib,
       f.designation

FROM FACTUREFOURNISSEURFILLE f
         LEFT JOIN FACTUREFOURNISSEUR f2
                   ON f2.ID = f.IDFACTUREFOURNISSEUR
         LEFT JOIN MAGASIN m
                   ON m.ID = f2.IDMAGASIN
         LEFT JOIN POINT p2
                   ON p2.ID = m.IDPOINT
         LEFT JOIN AS_INGREDIENTS p
                   ON p.ID = f.IDPRODUIT
         LEFT JOIN CATEGORIEINGREDIENT c
                   ON c.ID = p.CATEGORIEINGREDIENT
         LEFT JOIN REPARTIRIONPGGROUPEE r
                   ON r.IDFACTUREFILLE = f.ID
    )
;
-- [756/1309] COMPARAISONPRIXFACTBC
CREATE OR REPLACE FORCE VIEW "COMPARAISONPRIXFACTBC" ("ID","IDPRODUIT","IDPRODUITLIB","IDFACTUREFOURNISSEUR","PUFACT","PUBC","ECART") AS
SELECT
    f.idFactureFournisseur as id,
    f.idProduit,
    f.idProduitLib,
    f.idFactureFournisseur,
    f.pu          AS puFact,
    ASB.pu        AS puBc,
    f.pu - ASB.pu AS ecart
FROM FACTUREFOURNISSEURFILLECPL f

         LEFT JOIN FACTUREFOURNISSEUR ff
                   ON ff.ID = f.IDFACTUREFOURNISSEUR

         LEFT JOIN AS_BONDECOMMANDE_CPL ASB
                   ON ASB.IDBC = ff.IDBC

WHERE ff.IDBC IS NOT NULL
;
-- [757/1309] FACTUREFOURNISSEURFILLECPLC
CREATE OR REPLACE FORCE VIEW "FACTUREFOURNISSEURFILLECPLC" ("ID","IDFACTUREFOURNISSEUR","IDPRODUIT","IDPRODUITLIB","QTE","PU","REMISES","IDBCDETAIL","TVA","IDDEVISE","DATY","MONTANT","MONTANTREMISE","MONTANTHT","MONTANTTVA","MONTANTTTC","FRAISACCESOIRE","MONTANTAVECFRAISACCESSOIRE","PUAVECFRAISACCESSOIRE","LIBELLEEXACTE","IDPREVISION","COMPTE") AS
SELECT
    f."ID",f."IDFACTUREFOURNISSEUR",f."IDPRODUIT",f."IDPRODUITLIB",f."QTE",f."PU",f."REMISES",f."IDBCDETAIL",f."TVA",f."IDDEVISE",f."DATY",f."MONTANT",f."MONTANTREMISE",f."MONTANTHT",f."MONTANTTVA",f."MONTANTTTC",f."FRAISACCESOIRE",f."MONTANTAVECFRAISACCESSOIRE",f."PUAVECFRAISACCESSOIRE",f."LIBELLEEXACTE",f."IDPREVISION" ,
    f2.COMPTE
FROM FACTUREFOURNISSEURFILLECPL f
         LEFT JOIN FACTUREFOURNISSEURFILLE f2
                   ON f.ID  = f2.ID
;
-- [758/1309] REPORTCAISSEAVECHEURE
CREATE OR REPLACE FORCE VIEW "REPORTCAISSEAVECHEURE" ("ID","IDCAISSE","MONTANT","MONTANTTHEORIQUE","DATY","ETAT","REMARQUE","HEURE") AS
select r.ID,
       IDCAISSE,
       MONTANT,
       MONTANTTHEORIQUE,
       TO_DATE(TO_CHAR(DATY, 'YYYY-MM-DD') || ' ' || NVL(HEURE, '00:00:00'), 'YYYY-MM-DD HH24:MI:SS') as DATY,
       ETAT,
       REMARQUE,
       HEURE
from REPORTCAISSE r
;
-- [759/1309] REPORTCAISSELIB
CREATE OR REPLACE FORCE VIEW "REPORTCAISSELIB" ("ID","IDCAISSE","IDCAISSELIB","MONTANT","MONTANTTHEORIQUE","DATY","ETAT","HEURE","ETATLIB") AS
SELECT
r.ID ,
r.IDCAISSE ,
c.VAL AS IDCAISSELIB,
CAST(r.MONTANT AS NUMBER(30,5)) AS MONTANT ,
CAST(r.MONTANTTHEORIQUE AS NUMBER(30,5)) AS MONTANTTHEORIQUE ,
r.DATY ,
r.ETAT ,r.heure,
CASE
	WHEN r.ETAT = 0
	THEN 'ANNULEE'
	WHEN r.ETAT = 1
	THEN 'CREE'
	WHEN r.ETAT = 11
	THEN 'VALIDEE'
END AS ETATLIB
FROM REPORTCAISSE r
LEFT JOIN CAISSE c ON c.ID  = r.IDCAISSE
;
-- [760/1309] REPORTCAISSELIB_ANNULE
CREATE OR REPLACE FORCE VIEW "REPORTCAISSELIB_ANNULE" ("ID","IDCAISSE","IDCAISSELIB","MONTANT","MONTANTTHEORIQUE","DATY","ETAT","ETATLIB") AS
SELECT
		ID,IDCAISSE,IDCAISSELIB,MONTANT,MONTANTTHEORIQUE,DATY,ETAT,ETATLIB
	FROM 
		reportcaisselib v 
	WHERE 
		v.etat = 0
;
-- [761/1309] REPORTCAISSELIB_CREE
CREATE OR REPLACE FORCE VIEW "REPORTCAISSELIB_CREE" ("ID","IDCAISSE","IDCAISSELIB","MONTANT","MONTANTTHEORIQUE","DATY","ETAT","ETATLIB") AS
SELECT
		ID,IDCAISSE,IDCAISSELIB,MONTANT,MONTANTTHEORIQUE,DATY,ETAT,ETATLIB
	FROM 
		reportcaisselib v 
	WHERE 
		v.etat = 1
;
-- [762/1309] REPORTCAISSELIB_VALIDER
CREATE OR REPLACE FORCE VIEW "REPORTCAISSELIB_VALIDER" ("ID","IDCAISSE","IDCAISSELIB","MONTANT","MONTANTTHEORIQUE","DATY","ETAT","ETATLIB") AS
SELECT
		ID,IDCAISSE,IDCAISSELIB,MONTANT,MONTANTTHEORIQUE,DATY,ETAT,ETATLIB
	FROM 
		reportcaisselib v 
	WHERE 
		v.etat = 11
;
-- [763/1309] REPORTCAISSE_DEVISE
CREATE OR REPLACE FORCE VIEW "REPORTCAISSE_DEVISE" ("ID","IDCAISSE","IDCAISSELIB","MONTANT","MONTANTTHEORIQUE","DATY","ETAT","IDDEVISE","ETATLIB") AS
SELECT
r.ID ,
r.IDCAISSE ,
c.VAL AS IDCAISSELIB,
r.MONTANT ,
r.MONTANTTHEORIQUE ,
r.DATY ,
r.ETAT ,
c.iddevise,
CASE
	WHEN r.ETAT = 0
	THEN 'ANNULEE'
	WHEN r.ETAT = 1
	THEN 'CREE'
	WHEN r.ETAT = 11
	THEN 'VALIDEE'
END AS ETATLIB
FROM REPORTCAISSE r
LEFT JOIN (select * from CAISSE where id not in ('CAIS001')) c ON c.ID  = r.IDCAISSE
;
-- [764/1309] REPORTSOLDE
CREATE OR REPLACE FORCE VIEW "REPORTSOLDE" ("ID","COMPTE","LIBELLE_COMPTE","DEBIT","CREDIT","DATY","TYPECOMPTE","MOIS","ANNEE") AS
SELECT ce.id, cse.COMPTE, cc.libelle, cse.debit, cse.credit, ce.daty, cc.typecompte,
       EXTRACT(MONTH from ce.daty), EXTRACT(YEAR from ce.daty)
from
    compta_sous_ecriture cse, compta_ecriture ce, compta_compte cc, compta_journal jrn
where
    cse.idmere = ce.id and cc.COMPTE = cse.compte and ce.journal = 'COMP000015'
  and ce.etat = 11 and jrn.id = cse.journal
UNION
SELECT ce.id, cse.ANALYTIQUE, cc.libelle, cse.debit, cse.credit, ce.daty, cc.typecompte,
       EXTRACT(MONTH from ce.daty), EXTRACT(YEAR from ce.daty)
from
    compta_sous_ecriture cse, compta_ecriture ce, compta_compte cc, compta_journal jrn
where
    cse.idmere = ce.id and cc.COMPTE = cse.analytique and ce.journal = 'COMP000015'
  and ce.etat = 11 and jrn.id = cse.journal
;
-- [765/1309] COMPTA_MOUVEMENT_ANALYTIQUE
CREATE OR REPLACE FORCE VIEW "COMPTA_MOUVEMENT_ANALYTIQUE" ("DEBIT","CREDIT","COMPTE","ETAT","LIBELLE_COMPTE","TYPECOMPTE","MOIS","ANNEE","CHIFFRE3","CHIFFRE2") AS
SELECT
    CAST(sum(debit) AS NUMBER(30,
        2)) AS debit,
    CAST(sum(credit) AS NUMBER(30,
        2)) AS credit,
    compte,
    etat,
    libelle_compte,
    typecompte,
    mois,
    annee,
    chiffre3,
    chiffre2
FROM
    (
        SELECT
            cse.id,
            cse.debit AS debit,
            cse.credit AS credit,
            cse.analytique AS compte,
            cc.LIBELLE AS libelle_compte,
            cse.daty AS daty,
            cse.etat,
            cc.typecompte AS typecompte,
            EXTRACT(MONTH FROM cse.daty) AS mois,
            EXTRACT(YEAR FROM cse.daty) AS annee,
            substr(analytique, 1, 3)|| substr(analytique, 5, 1) AS chiffre3,
            substr(analytique, 1, 2) AS chiffre2
        FROM
            compta_sous_ecriture cse
                JOIN compta_compte cc ON
                cc.compte = cse.analytique
        WHERE
            cse.journal!='COMP000015'
          AND (cse.debit + cse.credit)>0
          AND cse.etat = 11
          AND NOT EXISTS(
            SELECT
                rs.id
            FROM
                reportsolde rs
            WHERE
                rs.id = cse.id
        )

        --group by   ce.id, cse.analytique, ce.daty, cse.etat, cc.LIBELLE, cc.typecompte , extract(month from cse.daty),
        --extract(year from cse.daty)
    )
GROUP BY compte,
         etat,
         libelle_compte,
         typecompte,
         mois,
         annee,
         chiffre3,
         chiffre2
ORDER BY
    chiffre3 ASC
;
-- [766/1309] COMPTA_MOUVEMENT_GENERAL
CREATE OR REPLACE FORCE VIEW "COMPTA_MOUVEMENT_GENERAL" ("DEBIT","CREDIT","COMPTE","ETAT","LIBELLE_COMPTE","TYPECOMPTE","MOIS","ANNEE","CHIFFRE3","CHIFFRE2") AS
SELECT
    CAST(sum(debit)AS NUMBER(30,
        2)) AS debit,
    CAST(sum(credit) AS NUMBER(30,
        2)) AS credit,
    compte,
    etat,
    libelle_compte,
    typecompte,
    mois,
    annee,
    chiffre3,
    chiffre2
FROM
    (
        SELECT
            cse.id,
            cse.debit AS debit,
            cse.credit AS credit,
            cse.compte AS compte,
            cc.LIBELLE AS libelle_compte,
            cse.daty AS daty,
            cse.etat,
            cc.typecompte AS typecompte,
            EXTRACT(MONTH FROM cse.daty) AS mois,
            EXTRACT(YEAR FROM cse.daty) AS annee,
            CASE
                WHEN substr(cse.compte, 1, 4) = '4007' THEN '407'
                ELSE substr(cse.compte, 1, 2)|| substr(cse.compte, 5, 1)
                END AS chiffre3,
            substr(cse.compte, 1, 2) AS chiffre2
        FROM
            compta_sous_ecriture cse
                JOIN compta_compte cc ON
                cc.compte = cse.compte
                JOIN compta_journal cj ON
                cj.id = cse.JOURNAL
        WHERE
            (cse.debit + cse.credit)>0
          AND NOT EXISTS(
            SELECT
                rs.id
            FROM
                reportsolde rs
            WHERE
                rs.id = cse.id
        )
    )
GROUP BY compte,
         etat,
         libelle_compte,
         typecompte,
         mois,
         annee,
         chiffre3,
         chiffre2
ORDER BY
    chiffre3 ASC
;
-- [767/1309] REPORTSOLDE_ANALYTIQUE
CREATE OR REPLACE FORCE VIEW "REPORTSOLDE_ANALYTIQUE" ("COMPTE","LIBELLE","DEBIT","CREDIT","TYPECOMPTE","DATY","CHIFFRE3","CHIFFRE2") AS
SELECT
    COMPTE,
    LIBELLE,
    CAST(DEBIT AS NUMBER(30,
                         2)),
    CAST(CREDIT AS NUMBER(30,
                          2)),
    TYPECOMPTE,
    daty,
    CHIFFRE3,
    CHIFFRE2
FROM
    (
        SELECT
            cse.ANALYTIQUE AS COMPTE,
            cc.libelle,
            sum(cse.debit) AS DEBIT,
            sum(cse.credit) AS CREDIT,
            cc.typecompte,
            cse.daty,
            substr(analytique, 1, 3)|| substr(analytique, 5, 1) AS chiffre3,
            substr(cse.ANALYTIQUE, 1, 2) AS chiffre2
        FROM
            compta_sous_ecriture cse,
            compta_compte cc,
            compta_journal jrn
        WHERE
            cc.COMPTE = cse.ANALYTIQUE
          AND cse.etat = 11
          AND cse.JOURNAL = jrn.id
        GROUP BY
            cse.ANALYTIQUE,
            cc.libelle,
            cc.typecompte,
            cse.daty

    )
;
-- [768/1309] REPORTSOLDE_GENERAL
CREATE OR REPLACE FORCE VIEW "REPORTSOLDE_GENERAL" ("COMPTE","LIBELLE_COMPTE","DEBIT","CREDIT","TYPECOMPTE","MOIS","ANNEE","CHIFFRE3","CHIFFRE2") AS
SELECT
    COMPTE,
    LIBELLE,
    CAST(DEBIT AS NUMBER(30,
        2)),
    CAST(CREDIT AS NUMBER(30,
        2)),
    TYPECOMPTE,
    MOIS,
    ANNEE,
    CHIFFRE3,
    CHIFFRE2
FROM
    (
        SELECT
            cse.COMPTE,
            cc.libelle,
            sum(cse.debit) AS debit,
            sum(cse.credit) AS credit,
            cc.typecompte,
            EXTRACT(MONTH FROM cse.daty) AS mois,
            EXTRACT(YEAR FROM cse.daty) AS annee,
            CASE
                WHEN substr(cse.compte, 1, 4) = '4007' THEN '407'
                ELSE substr(cse.compte, 1, 2)|| substr(cse.compte, 5, 1)
                END AS CHIFFRE3,
            substr(cse.compte, 1, 2) AS CHIFFRE2
        FROM
            compta_sous_ecriture cse,
            compta_compte cc,
            compta_journal jrn
        WHERE
            cc.COMPTE = cse.compte
          AND cse.etat = 11
          AND cse.JOURNAL = jrn.id
        GROUP BY
            cse.COMPTE,
            cc.libelle,
            cc.typecompte,
            EXTRACT(MONTH FROM cse.daty),
            EXTRACT(YEAR FROM cse.daty)
    )
;
-- [769/1309] REPORTSOLDE_GENERAL_V1
CREATE OR REPLACE FORCE VIEW "REPORTSOLDE_GENERAL_V1" ("COMPTE","LIBELLE","DEBIT","CREDIT","TYPECOMPTE","DATY","CHIFFRE3","CHIFFRE2") AS
SELECT
	COMPTE,
	LIBELLE,
	CAST(DEBIT AS NUMBER(30, 2)) AS debit,
	CAST(CREDIT AS NUMBER(30, 2)) AS credit,
	TYPECOMPTE,
	daty,
	CHIFFRE3,
	CHIFFRE2
FROM
	(
	SELECT
		cse.COMPTE,
		cc.libelle,
		sum(cse.debit) AS debit,
		sum(cse.credit) AS credit,
		cc.typecompte,
		cse.daty,
		CASE
			WHEN substr(cse.compte, 1, 4) = '4007' THEN '407'
			ELSE substr(cse.compte, 1, 2) || substr(cse.compte, 5, 1)
		END AS CHIFFRE3,
		substr(cse.compte, 1, 2) AS CHIFFRE2
	FROM
		compta_sous_ecriture cse,
		compta_compte cc,
		compta_journal jrn
	WHERE
		cc.COMPTE = cse.compte
		AND cse.etat = 11
		AND cse.JOURNAL = jrn.id
	GROUP BY
		cse.COMPTE,
		cc.libelle,
		cc.typecompte,
		cse.daty

    )
;
-- [770/1309] REPORTSOLDE_JANVIER
CREATE OR REPLACE FORCE VIEW "REPORTSOLDE_JANVIER" ("COMPTE","LIBELLE_COMPTE","DEBIT","CREDIT","TYPECOMPTE","MOIS","ANNEE","CHIFFRE3","CHIFFRE2") AS
SELECT COMPTE,
       LIBELLE,
       CAST(sum(DEBIT) AS NUMBER(30, 2)),
       CAST(sum(CREDIT) AS NUMBER(30, 2)),
       TYPECOMPTE,
       MOIS,
       ANNEE,
       CHIFFRE3,
       CHIFFRE2
FROM (SELECT cse.COMPTE,
             cc.libelle,
             cse.debit,
             cse.credit,
             cc.typecompte,
             EXTRACT(MONTH from cse.daty)                                      AS MOIS,
             EXTRACT(YEAR from cse.daty)                                       AS ANNEE,
             CASE
                 WHEN TYPECOMPTE = 3 THEN SUBSTR(CSE.COMPTE, 1, 3) || SUBSTR(CSE.COMPTE, 5, 1)
                 WHEN TYPECOMPTE = 1 AND SUBSTR(CSE.COMPTE, 1, 4) = '4007' THEN '407'
                 ELSE SUBSTR(CSE.COMPTE, 1, 2) || SUBSTR(CSE.COMPTE, 5, 1) END as chiffre3,
             substr(cse.compte, 1, 2)                                          as chiffre2
      from compta_sous_ecriture cse,
           compta_compte cc,
           compta_journal jrn
      where cc.COMPTE = cse.compte
        and cse.journal = 'COMP000015'
        AND cse.etat = 11
        AND jrn.id = cse.journal
      UNION
      SELECT cse.ANALYTIQUE,
             cc.libelle,
             cse.debit                                                                 as debit,
             cse.credit                                                                as credit,
             cc.typecompte,
             EXTRACT(MONTH from cse.daty),
             EXTRACT(YEAR from cse.daty),
             CASE
                 WHEN TYPECOMPTE = 3 THEN SUBSTR(cse.ANALYTIQUE, 1, 3) || SUBSTR(cse.ANALYTIQUE, 5, 1)
                 ELSE SUBSTR(cse.ANALYTIQUE, 1, 2) || SUBSTR(cse.ANALYTIQUE, 5, 1) END as chiffre3,
             substr(cse.ANALYTIQUE, 1, 2)                                              as chiffre2
      from compta_sous_ecriture cse,
           compta_compte cc,
           compta_journal jrn
      where cc.COMPTE = cse.analytique
        and cse.journal = 'COMP000015'
        and cse.etat = 11
        and jrn.id = cse.journal)
group by COMPTE, LIBELLE, TYPECOMPTE, MOIS, ANNEE, CHIFFRE3, CHIFFRE2
;
-- [771/1309] REQUETE_A_ENVOYER_SERVEUR
CREATE OR REPLACE FORCE VIEW "REQUETE_A_ENVOYER_SERVEUR" ("ID","ACTION","TABLECONCERNE","REQUETE","DATY","HEURE","SERVEUR") AS
SELECT rae.ID, rae.ACTION, rae.TABLECONCERNE, rae.REQUETE, rae.DATY, rae.HEURE, rae.SERVEUR
FROM REQUETE_A_ENVOYER rae
;
-- [772/1309] REQUETE_EXECUTE_SERVEUR
CREATE OR REPLACE FORCE VIEW "REQUETE_EXECUTE_SERVEUR" ("ID","ACTION","TABLECONCERNE","REQUETE","DATY","HEURE","SERVEUR") AS
SELECT rae.ID, rae.ACTION, rae.TABLECONCERNE, rae.REQUETE, rae.DATY, rae.HEURE, re.SERVEUR
FROM REQUETE_A_ENVOYER rae
JOIN REQUETE_EXECUTE re on rae.ID = re.IDREQUETE
;
-- [773/1309] RESERVATIONDETAILSAVECMERE
CREATE OR REPLACE FORCE VIEW "RESERVATIONDETAILSAVECMERE" ("ID","IDPRODUIT","QTE","DATY","IDCLIENT","ETAT","LIBELLECLIENT","IDMERE","LIBELLEPRODUIT") AS
select rd.id,ing.id as IDPRODUIT,rd.qte,rd.daty,r.IDCLIENT,r.ETAT as etat,c.nom||' '||c.TELEPHONE as libelleclient ,rd.IDMERE,ing.LIBELLE as libelleproduit from AS_INGREDIENTS ing
    left join reservationDetails rd on rd.idproduit=ing.ID
    left join reservation r on r.id=rd.IDMERE
left join CLIENT c on c.id=r.IDCLIENT
;
-- [774/1309] RESERVATIONDETAILSMAXDATE
CREATE OR REPLACE FORCE VIEW "RESERVATIONDETAILSMAXDATE" ("ID","IDMERE","IDPRODUIT","QTE","DATY","PU","REMARQUE","ETAT","HEURE","RN") AS
SELECT "ID","IDMERE","IDPRODUIT","QTE","DATY","PU","REMARQUE","ETAT","HEURE","RN"
FROM (
    SELECT r.*,
           ROW_NUMBER() OVER (PARTITION BY IDMERE ORDER BY daty DESC) AS rn
    FROM RESERVATIONDETAILS r
)
WHERE rn = 1
;
-- [775/1309] RESERVATIONDETAILS_LIB
CREATE OR REPLACE FORCE VIEW "RESERVATIONDETAILS_LIB" ("ID","IDMERE","QTE","DATY","IDPRODUIT","LIBELLEPRODUIT","CATEGORIEPRODUIT","PU","MONTANT","TVA","MONTANTTVA","MONTANTTTC","CATEGORIEPRODUITLIB","HEURE") AS
SELECT
r.ID,
r.IDMERE,
r.QTE,
r.DATY,
r.IDPRODUIT,
ai.LIBELLE AS libelleproduit,
ai.idCATEGORIEINGREDIENT AS categorieproduit,
r.PU,
r.QTE * r.PU AS  montant,
ai.tva as tva,
cast(r.qte*r.pu*(nvl(ai.tva,0)/100) as number(20,2)) as montantTva,
cast((r.QTE * r.PU)+(r.qte*r.pu*(nvl(ai.tva,0)/100)) as number(20,2)) as montantttc,
ai.CATEGORIEINGREDIENT AS categorieproduitlib,
r.heure AS heure
FROM RESERVATIONDETAILS r
LEFT JOIN AS_INGREDIENTS_LIB ai ON ai.id = r.IDPRODUIT
;
-- [776/1309] RESERVATIONDETAILS_LIBGROUPE
CREATE OR REPLACE FORCE VIEW "RESERVATIONDETAILS_LIBGROUPE" ("ID","IDMERE","QTE","DATY","IDPRODUIT","LIBELLEPRODUIT","CATEGORIEPRODUIT","PU","MONTANT","TVA","MONTANTTVA","MONTANTTTC","CATEGORIEPRODUITLIB","HEURE") AS
SELECT
min(r.ID) as id,
r.IDMERE,
sum(r.QTE) as qte,
min(r.DATY) as daty,
r.IDPRODUIT,
r.libelleproduit AS libelleproduit,
r.categorieproduit AS categorieproduit,
avg(r.PU) as pu,
sum(r.QTE * r.PU) AS  montant,
avg(r.tva) as tva,
cast(sum(montantTva) as number(20,2)) as montantTva,
cast(sum(montantttc) as number(20,2)) as montantttc,
r.categorieproduitlib AS categorieproduitlib,
min(r.heure) AS heure
FROM RESERVATIONDETAILS_LIB r

group by r.idmere,r.idproduit,r.libelleproduit,r.categorieproduit,r.categorieproduitlib
;
-- [777/1309] RESERVATIONDETSANSCI
CREATE OR REPLACE FORCE VIEW "RESERVATIONDETSANSCI" ("ID","IDMERE","IDPRODUIT","QTE","DATY","PU","REMARQUE","ETAT","IDCLIENT") AS
SELECT
	rd."ID",
	rd."IDMERE",
	rd."IDPRODUIT",
	rd."QTE",
	rd."DATY",
	rd."PU",
	rd."REMARQUE",
	rd."ETAT",
	r."IDCLIENT"
FROM
	reservationDetails rd
	JOIN RESERVATION r
	ON rd.IDMERE = r.ID
WHERE
	rd.idmere NOT IN (
	SELECT
		c.reservation
	FROM
		checkin c
	WHERE
		c.etat >= 11
		AND c.IDPRODUIT = rd.idproduit)
;
-- [778/1309] RESERVATIONMONTANT
CREATE OR REPLACE FORCE VIEW "RESERVATIONMONTANT" ("IDMERE","MONTANT","MONTANTTVA","MONTANTTTC") AS
SELECT 
r.IDMERE,
cast(sum(r.montant) as number(20,2)) AS montant,
cast(sum(r.MONTANTTVA)as number(20,2)) as MONTANTTVA,
cast(sum(r.MONTANTTTC) as number(20,2))as MONTANTTTC
FROM reservationdetails_lib r 
GROUP BY r.IDMERE
;
-- [779/1309] RESERVATIONSIMPLE
CREATE OR REPLACE FORCE VIEW "RESERVATIONSIMPLE" ("ID","IDCLIENT","DATY","REMARQUE","ETAT","IDPRODUIT","QTE") AS
select
    rs."ID",rs."IDCLIENT",rs."DATY",rs."REMARQUE",rs."ETAT",
    rsdt.IDPRODUIT,
    rsdt.QTE
from RESERVATION rs
join RESERVATIONDETAILS rsdt on rs.ID = rsdt.IDMERE
where 1> 2
;
-- [780/1309] RESERVATION_LIB
CREATE OR REPLACE FORCE VIEW "RESERVATION_LIB" ("ID","IDCLIENT","IDCLIENTLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANT","MONTANTTTC","MONTANTTVA","PAYE","RESTEAPAYER") AS
SELECT 
r.id,
r.idClient,
c.NOM AS idclientlib,
r.daty,
r.remarque,
r.etat,
CASE 
	WHEN r.etat = 1 
	THEN 'CREE'
	WHEN r.etat = 0 
	THEN 'ANNULEE'
	WHEN r.etat = 11 
	THEN 'VISEE'
END AS etatlib,
rm.montant,
rm.MONTANTTTC,
rm.MONTANTTVA,
mvt.CREDIT as paye,
cast(rm.MONTANTTTC-mvt.CREDIT as number(20,2)) as resteAPayer
FROM RESERVATION r 
LEFT JOIN CLIENT c ON c.id = r.idClient 
LEFT JOIN reservationmontant rm ON rm.idmere = r.id
left join MOUVEMENTCAISSEGROUPERESA mvt on mvt.IDORIGINE=r.ID
;
-- [781/1309] RESERVATION_LIB_AVECMAXDATE
CREATE OR REPLACE FORCE VIEW "RESERVATION_LIB_AVECMAXDATE" ("ID","IDCLIENT","IDCLIENTLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANT","MONTANTTTC","MONTANTTVA","PAYE","RESTEAPAYER","DATYFINPOTENTIEL") AS
select rl."ID",rl."IDCLIENT",rl."IDCLIENTLIB",rl."DATY",rl."REMARQUE",rl."ETAT",rl."ETATLIB",rl."MONTANT",rl."MONTANTTTC",rl."MONTANTTVA",rl."PAYE",rl."RESTEAPAYER", rdmd.DATY as DATYFINPOTENTIEL
from RESERVATION_LIB rl
         left join RESERVATIONDETAILSMAXDATE rdmd on rl.id = rdmd.IDMERE
;
-- [782/1309] RESRECLAMATIONLIB
CREATE OR REPLACE FORCE VIEW "RESRECLAMATIONLIB" ("ID","IDRECLAMATION","DATY","IDTYPE","ETAT","ETATLIB","IDTYPELIB","QTE") AS
SELECT
    r.ID,
    r.IDRECLAMATION,
    r.daty,
    r.idType,
    r.etat,

    CASE r.etat
        WHEN 1  THEN 'Cree'
        WHEN 11 THEN 'Valide'
        WHEN 0 THEN 'Rejete'
        ELSE 'Autre'
        END AS etatLib,

    tr.VAL AS idTypeLib,
    r.qte
FROM resreclamation r
         LEFT JOIN TYPEresRECLAMATION tr
                   ON tr.ID = r.idType
;
-- [783/1309] RESSOURCEPARFABRICATIONCOMPLET
CREATE OR REPLACE FORCE VIEW "RESSOURCEPARFABRICATIONCOMPLET" ("ID","DATY","IDFABRICATION","IDPOSTEDEFAUT","IDRESSOURCE","MATRICULE","IDOF","ETAT","TEMPORAIRE","IDQUALIFICATION","IDCATEGORIE","IDPOSTE","IDPOSTELIB","IDQUALIFICATIONEFFECTIVE","TAUXHORAIRE","HS","MN","JF","HD","IF","ETATLIB","IDRESSOURCELIB") AS
SELECT
    r.id,
    r.daty,
    r.idFabrication,
    r.idPoste AS idPosteDefaut,
    r.idRessource,
    p.matricule,
    f.IDOF,
    r.etat ,
    p.TEMPORAIRE,
    p.IDQUALIFICATION AS IdQualification,
    c.IDCATEGORIE,
    c.idPoste ,
    po.VAL AS idPostelib,
    p.IDQUALIFICATION AS IdQualificationEffective,
    CAST(c.montant/((40*52)/12) AS NUMBER(30,2) ) AS tauxhoraire,
    h.HS ,
    h.MN ,
    h.JF ,
    h.HD ,
    h.IF ,
    CASE
        WHEN r.etat = 0
            THEN 'ANNULEE'
        WHEN r.etat = 1
            THEN 'CREE'
        WHEN r.etat = 11
            THEN 'VISEE'
        END AS etatlib,
    p.MATRICULE AS idRessourcelib
FROM ressourceParFabrication r
         LEFT JOIN PAIE_INFO_PERSONNEL p ON p.id = r.idRessource
         LEFT JOIN CATEGORIE_QUALIFICATION c
                   ON c.IDQUALIFICATION = r.IDQUALIFICATION
                       AND c.IDCATEGORIE = p.IDCATEGORIE
                       AND (
                          (c.REMARQUE IS NULL)
                              OR (c.REMARQUE = r.IDRESSOURCE)
                          ) AND c.etat = 1
         LEFT JOIN FABRICATION f ON f.id = r.idFabrication
         LEFT JOIN heureSupFabrication h ON h.idRessParFab = r.id
         LEFT JOIN POSTE po ON po.id =  c.idPoste
;
-- [784/1309] HEURESUPFABRICATION_CPL
CREATE OR REPLACE FORCE VIEW "HEURESUPFABRICATION_CPL" ("ID","IDRESSPARFAB","HEURENORMALE","HS","MN","JF","HD","IF","ETAT","REMARQUE","IDPERSONNE","IDFABRICATION","DATEFABRICATION","ETATLIB","IDPERSONNELIB","MATRICULE","TAUXHORAIRE","TAUXHORAIREEFFECTIVE","TEMPORAIRE","MONTANT","IDQUALIFICATION","MONTANTJF","MONTANTHD","MONTANTIF","MONTANTMN","MONTANTHN","IDDEPARTEMENT","DEPARTEMENTLIB","POSTE","POSTELIB","DATEIMPORT","MONTANTHEURESUPP") AS
SELECT
    h.ID,h.IDRESSPARFAB,h.HEURENORMALE ,h.HS,h.MN,h.JF,h.HD,h.IF,h.ETAT,h.REMARQUE,
    p.id AS  idPersonne,
    h.idFabrication,
    h.daty as dateFabrication,
    CASE
        WHEN h.etat=0
            THEN 'ANNULE'
        WHEN h.etat=1
            THEN 'CREE'
        WHEN h.etat=11
            THEN 'VISE'
        END AS etatlib,
    pm.NOM || ' ' || pm.PRENOM AS idPersonnelib,
    p.MATRICULE,
    h.TAUXHORAIRE,
    CAST(nvl(c.montant,0)/((40*52)/12) AS NUMBER(30,2) ) AS TAUXHORAIREEFFECTIVE,
    p.temporaire,
    h.MONTANT,
    r.IDQUALIFICATION,
    NVL(h.montantJF, 0) as montantJF,
    NVL(h.montantHD, 0) as montantHD,
    NVL(h.montantIF,0) as montantIF,
    NVL(h.montantMN, 0) as montantMN,
    NVL(h.MONTANTHN, 0) as montantHN,
    p.IDDEPARTEMENT,
    d.val as departementLib,
    h.poste,
    pf.val as PosteLib,
    h.DATEIMPORT,
    h.MONTANTHEURESUPP
FROM HEURESUPFABRICATION h
         LEFT JOIN RESSOURCEPARFABRICATIONCOMPLET r ON r.id = h.IDRESSPARFAB
         LEFT JOIN PAIE_INFO_PERSONNEL p ON p.id = r.idRessource
         LEFT JOIN CATEGORIE_QUALIFICATION c
                   ON c.IDQUALIFICATION = r.IDQUALIFICATION
                       AND c.IDCATEGORIE = r.IDCATEGORIE
                       AND (
                          (c.REMARQUE IS NULL)
                              OR (c.REMARQUE = r.IDRESSOURCE)
                          ) AND c.etat = 1
         LEFT JOIN LOG_PERSONNEL pm ON pm.id = r.IDRESSOURCE
         LEFT JOIN FABRICATION fab ON fab.ID = h.IDFABRICATION
         LEFT JOIN DEPARTEMENT d on d.id = p.IDDEPARTEMENT
         LEFT JOIN PAIE_FONCTION pf on pf.id = h.poste
;
-- [785/1309] HEURESUPFABRICATION_CPL_VISEE
CREATE OR REPLACE FORCE VIEW "HEURESUPFABRICATION_CPL_VISEE" ("ID","IDRESSPARFAB","HEURENORMALE","HS","MN","JF","HD","IF","ETAT","REMARQUE","IDPERSONNE","IDFABRICATION","DATEFABRICATION","ETATLIB","IDPERSONNELIB","MATRICULE","TAUXHORAIRE","TAUXHORAIREEFFECTIVE","TEMPORAIRE","MONTANTTOTAL","IDQUALIFICATION","VALEURJF","VALEURHD","VALEURIF","VALEURMN","VALEURHN","VALEURHS","IDDEPARTEMENT","DEPARTEMENTLIB") AS
SELECT
    hs.ID,
    hs.IDRESSPARFAB,
    hs.HEURENORMALE,
    hs.HS,
    hs.MN,
    hs.JF,
    hs.HD,
    hs.IF,
    hs.ETAT,
    hs.REMARQUE,
    hs.IDPERSONNE,
    hs.IDFABRICATION,
    hs.DATEFABRICATION,
    hs.ETATLIB,
    hs.IDPERSONNELIB,
    hs.MATRICULE,
    CAST(hs.TAUXHORAIRE AS NUMBER(30,2)) as TAUXHORAIRE,
    hs.TAUXHORAIREEFFECTIVE,
    hs.TEMPORAIRE,
    CAST(hs.MONTANT AS NUMBER(30,2)) AS montantTotal,
    hs.IDQUALIFICATION,
    hs.MONTANTJF AS valeurJF,
    hs.MONTANTHD AS valeurHD,
    hs.MONTANTIF AS valeurIF,
    hs.MONTANTMN AS valeurMN,
    hs.MONTANTHN AS valeurHN,
    hs.MONTANTHEURESUPP AS valeurHS,
    hs.IDDEPARTEMENT,
    hs.DEPARTEMENTLIB
FROM HEURESUPFABRICATION_CPL hs
WHERE hs.ETAT = 11
;
-- [786/1309] CHARGEPERSONNEL_CPL
CREATE OR REPLACE FORCE VIEW "CHARGEPERSONNEL_CPL" ("ID","IDRESSPARFAB","HEURENORMALE","HS","MN","JF","HD","IF","ETAT","REMARQUE","IDPERSONNE","IDFABRICATION","DATEFABRICATION","ETATLIB","IDPERSONNELIB","MATRICULE","TAUXHORAIRE","TAUXHORAIREEFFECTIVE","TEMPORAIRE","MONTANTTOTAL","IDQUALIFICATION","VALEURJF","VALEURHD","VALEURIF","VALEURMN","VALEURHN","VALEURHS","IDDEPARTEMENT","DEPARTEMENTLIB","TH") AS
SELECT
    hs."ID",hs."IDRESSPARFAB",hs."HEURENORMALE",hs."HS",hs."MN",hs."JF",hs."HD",hs."IF",hs."ETAT",hs."REMARQUE",hs."IDPERSONNE",hs."IDFABRICATION",hs."DATEFABRICATION",hs."ETATLIB",hs."IDPERSONNELIB",hs."MATRICULE",hs."TAUXHORAIRE",hs."TAUXHORAIREEFFECTIVE",hs."TEMPORAIRE",hs."MONTANTTOTAL",hs."IDQUALIFICATION",hs."VALEURJF",hs."VALEURHD",hs."VALEURIF",hs."VALEURMN",hs."VALEURHN",hs."VALEURHS",hs."IDDEPARTEMENT",hs."DEPARTEMENTLIB",
    hs.TAUXHORAIRE as th

FROM HEURESUPFABRICATION_CPL_VISEE hs
;
-- [787/1309] HEURESUPFABRICATION_CUMUL
CREATE OR REPLACE FORCE VIEW "HEURESUPFABRICATION_CUMUL" ("IDPERSONNE","IDPERSONNELIB","MATRICULE","SEMAINE","JOUR","HEUREJOUR","HEUREDEJACUMULEES") AS
SELECT
    p.id AS idPersonne,
    pm.NOM AS idPersonnelib,
    p.MATRICULE,
    TO_CHAR(h.daty, 'IYYY-IW') AS semaine,
    h.daty AS jour,
    SUM(h.HS) AS heureJour,
    SUM(SUM(h.HS)) OVER (
        PARTITION BY p.id, TO_CHAR(h.daty, 'IYYY-IW')
        ORDER BY h.daty
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) - SUM(h.HS) AS heureDejaCumulees
FROM HEURESUPFABRICATION h
         LEFT JOIN RESSOURCEPARFABRICATIONCOMPLET r ON r.id = h.IDRESSPARFAB
         LEFT JOIN PAIE_INFO_PERSONNEL p ON p.id = r.idRessource
         LEFT JOIN PERSONNEL_MATRICULE pm ON pm.id = r.IDRESSOURCE
         LEFT JOIN FABRICATION fab ON fab.ID = h.IDFABRICATION
WHERE h.ETAT >= 11
GROUP BY p.id, pm.NOM, p.MATRICULE, h.daty
;
-- [788/1309] HEURESUPFABRICATION_TOTAL
CREATE OR REPLACE FORCE VIEW "HEURESUPFABRICATION_TOTAL" ("IDPERSONNE","IDPERSONNELIB","MATRICULE","TAUXHORAIRE","TAUXHORAIREEFFECTIVE","TEMPORAIRE","SEMAINE","TOTALHEURESEMAINE") AS
SELECT
    p.id AS idPersonne,
    pm.NOM AS idPersonnelib,
    p.MATRICULE,
    r.TAUXHORAIRE,
    CAST(NVL(c.montant,0)/((40*52)/12) AS NUMBER(30,2)) AS TAUXHORAIREEFFECTIVE,
    p.temporaire,
    TO_CHAR(h.daty, 'IYYY-IW') AS semaine,
    SUM(h.HS) AS totalHeureSemaine
FROM HEURESUPFABRICATION h
         LEFT JOIN RESSOURCEPARFABRICATIONCOMPLET r ON r.id = h.IDRESSPARFAB
         LEFT JOIN PAIE_INFO_PERSONNEL p ON p.id = r.idRessource
         LEFT JOIN CATEGORIE_QUALIFICATION c ON c.IDQUALIFICATION = p.IDQUALIFICATION
         LEFT JOIN PERSONNEL_MATRICULE pm ON pm.id = r.IDRESSOURCE
         LEFT JOIN FABRICATION fab ON fab.ID = h.IDFABRICATION
GROUP BY p.id, pm.NOM, p.MATRICULE, r.TAUXHORAIRE, p.temporaire,
         TO_CHAR(h.daty, 'IYYY-IW'), c.montant
;
-- [789/1309] HS_FABRICATION_SEMAINE
CREATE OR REPLACE FORCE VIEW "HS_FABRICATION_SEMAINE" ("IDPERSONNE","ANNEE","MOIS","SEMAINE","HS_TOTAL","HS30","HS50","IF","JF","MN","HD") AS
SELECT
    hp.idPersonne,
    p.annee,
    p.mois,
    TO_CHAR(hp.DATEFABRICATION, 'IYYY-IW') AS semaine,
    SUM(hp.HS) AS hs_total,
    LEAST(SUM(hp.HS), 8) AS hs30,
    GREATEST(SUM(hp.HS) - 8, 0) AS hs50,
    SUM( hp.IF) AS if, sum(hp.JF) as JF, SUM(hp.MN) as MN , SUM( hp.HD) as HD
FROM HEURESUPFABRICATION_CPL hp
         LEFT JOIN FABRICATION f ON f.id = hp.IDFABRICATION
         LEFT JOIN PERIODEPAIE p ON hp.DATEFABRICATION BETWEEN p.datedebut AND p.datefin
GROUP BY hp.idPersonne, p.annee, p.mois, TO_CHAR(hp.DATEFABRICATION, 'IYYY-IW')
;
-- [790/1309] HS_FABBRICATION_SEMAINECPL
CREATE OR REPLACE FORCE VIEW "HS_FABBRICATION_SEMAINECPL" ("ID","IDPERSONNE","ANNEE","MOIS","SEMAINE","HS_TOTAL","HS30","HS50","MATRICULE","NOMPERSONNEL","DATEDEBUTSEMAINE","DATEFINSEMAINE","IF","JF","MN","HD","HS") AS
SELECT
    hs."IDPERSONNE" as id, hs."IDPERSONNE",hs."ANNEE",hs."MOIS",hs."SEMAINE",hs."HS_TOTAL",hs."HS30",hs."HS50",
    pip.matricule,
    log.nom || ' ' || log.prenom as nomPersonnel,
    CAST(
            TRUNC(TO_DATE(SUBSTR(hs.SEMAINE, 1, 4) || '-01-04', 'YYYY-MM-DD'), 'IW')
                + (TO_NUMBER(SUBSTR(hs.SEMAINE, 6, 2)) - 1) * 7
        AS DATE
    ) AS DATEDEBUTSEMAINE,
    CAST(
            TRUNC(TO_DATE(SUBSTR(hs.SEMAINE, 1, 4) || '-01-04', 'YYYY-MM-DD'), 'IW')
                + (TO_NUMBER(SUBSTR(hs.SEMAINE, 6, 2)) - 1) * 7
                + 6
        AS DATE
    ) AS DATEFINSEMAINE,
    hs.IF AS IF,
    hs.JF AS JF,
    hs.MN AS MN,
    hs.HD AS HD,
    hs.hs_total AS HS
FROM HS_FABRICATION_SEMAINE hs

         LEFT JOIN PAIE_INFO_PERSONNEL pip ON pip.id = hs.IDPERSONNE

         LEFT JOIN LOG_PERSONNEL log ON log.id = hs.IDPERSONNE
;
-- [791/1309] HS_MOIS
CREATE OR REPLACE FORCE VIEW "HS_MOIS" ("IDPERSONNEL","ANNEE","MOIS","HS30_MOIS","HS50_MOIS","IDDEPARTEMENT","IDCATEGORIE") AS
SELECT
    IDPERSONNE as idPersonnel,
    annee,
    mois,
    SUM(hs30) AS hs30_mois,
    SUM(hs50) AS hs50_mois,
    pip.IDDEPARTEMENT,
    pip.IDCATEGORIE_PAIE as idCategorie
FROM HS_FABRICATION_SEMAINE hs
         LEFT JOIN PAIE_INFO_PERSONNEL pip on pip.id = hs.idPersonne
GROUP BY idPersonne, annee, mois, pip.IDDEPARTEMENT, pip.IDCATEGORIE_PAIE
;
-- [792/1309] HS_MOIS_PARTRANCHE
CREATE OR REPLACE FORCE VIEW "HS_MOIS_PARTRANCHE" ("IDPERSONNE","ANNEE","MOIS","HS30_MOIS","HS50_MOIS","IDDEPARTEMENT","IDCATEGORIE") AS
SELECT
    idPersonne,
    annee,
    mois,

    SUM(hs30) AS hs30_mois,
    SUM(hs50) AS hs50_mois,

    pip.IDDEPARTEMENT,
    pip.IDCATEGORIE_PAIE AS idCategorie

FROM HS_FABRICATION_SEMAINE hs
         LEFT JOIN PAIE_INFO_PERSONNEL pip
                   ON pip.id = hs.idPersonne

GROUP BY
    idPersonne,
    annee,
    mois,
    pip.IDDEPARTEMENT,
    pip.IDCATEGORIE_PAIE
;
-- [793/1309] HS_NON_PAYE
CREATE OR REPLACE FORCE VIEW "HS_NON_PAYE" ("ID","IDRESSPARFAB","HS","MN","JF","HD","IF","ETAT","IDPERSONNE","IDFABRICATION","ETATLIB","NOMPERSONNEL","MONTANTJF","MONTANTHD","TOTAL","MATRICULE") AS
SELECT hs.ID,hs.IDRESSPARFAB,hs.HS,hs.MN,hs.JF,hs.HD,hs.IF,hs.ETAT,hs.IDPERSONNE,hs.IDFABRICATION,hs.ETATLIB,hs.IDPERSONNELIB AS nomPersonnel,hsf.MONTANTJF ,hsf.MONTANTHD ,hsf.MONTANTJF+hsf.MONTANTHD AS total,hsf.MATRICULE
FROM HEURESUPFABRICATION_CPL_VISEE hs
         LEFT JOIN HEURESUPFABRICATION_CPL hsf ON hsf.id=hs.id
WHERE hs.ID NOT IN (
    SELECT IDHS
    FROM PAIEMENTHEURESUP
    WHERE IDHS IS NOT NULL
)
;
-- [794/1309] RESSOURCEPARFABCOMPLET_VISEE
CREATE OR REPLACE FORCE VIEW "RESSOURCEPARFABCOMPLET_VISEE" ("ID","IDFABRICATION","IDPOSTEEFFECTIVE","IDRESSOURCE","MATRICULE","IDOF","ETAT","TEMPORAIRE","IDQUALIFICATIONEFFECTIVE","IDCATEGORIE","IDPOSTEDEFAUT","IDQUALIFICATIONDEFAUT","TAUXHORAIRE","HS","MN","JF","HD","IF","ETATLIB") AS
SELECT 
r."ID",r."IDFABRICATION",r."IDPOSTEEFFECTIVE",r."IDRESSOURCE",r."MATRICULE",r."IDOF",r."ETAT",r."TEMPORAIRE",r."IDQUALIFICATIONEFFECTIVE",r."IDCATEGORIE",r."IDPOSTEDEFAUT",r."IDQUALIFICATIONDEFAUT",r."TAUXHORAIRE",r."HS",r."MN",r."JF",r."HD",r."IF",r."ETATLIB"
FROM  ressourceParFabricationComplet r 
WHERE r.etat = 11
;
-- [795/1309] RESSOURCEPARFAB_CPL_RECTIF
CREATE OR REPLACE FORCE VIEW "RESSOURCEPARFAB_CPL_RECTIF" ("ID","DATY","IDFABRICATION","IDPOSTEDEFAUT","IDRESSOURCE","MATRICULE","IDPOSTE","IDPOSTELIB","ETATLIB") AS
SELECT
	    r.id,
	    r.daty,
	    r.idFabrication,
	    r.idPoste AS idPosteDefaut,
	    r.idRessource,
	    p.MATRICULE,
	    r.IDPOSTE,
	    poste.val as idPosteLib,
	    CASE
	        WHEN r.etat = 0
	            THEN 'ANNULEE'
	        WHEN r.etat = 1
	            THEN 'CREEE'
	        WHEN r.etat = 11
	            THEN 'VISEE'
	        END AS etatlib
	FROM ressourceParFabrication r
	         LEFT JOIN PAIE_INFO_PERSONNEL p ON p.id = r.idRessource
	         LEFT JOIN POSTE poste ON poste.id = r.IDPOSTE
;
-- [796/1309] RESULTATFABRICATION
CREATE OR REPLACE FORCE VIEW "RESULTATFABRICATION" ("ID","IDOFFILLE","IDFABRICATION","IDPRODUIT","IDPRODUITLIB","QTE","IDINGREDIENTS","QTEINGREDIENTS","IDLIGNE","DATY","ENTREEDECHET") AS
SELECT
    OFF.IDMERE AS ID,
    OFF.ID AS IDOFFILLE,
    F.ID AS IDFABRICATION,
    OFF.IDINGREDIENTS AS IDPRODUIT,
    OFF.LIBELLE AS IDPRODUITLIB,
    OFF.QTE AS QTE,
    FF.IDINGREDIENTS,
    FF.QTE AS QTEINGREDIENTS,
    M.IDLIGNE,
    F.DATY,
    COALESCE((SELECT SUM(ENTREE)
              FROM MVTSTFILLEFABCATVISEGROUPE WHERE IDFAB = F.ID AND ENTREE > 0 and CATEGORIEINGREDIENT ='Dechets'
             ),0) AS ENTREEDECHET
FROM FABRICATIONFILLE FF
         LEFT JOIN FABRICATION F ON F.ID = FF.IDMERE
         LEFT JOIN OFFILLELIBSTOCK OFF ON OFF.ID = F.IDOFFILLE
         LEFT JOIN MACHINE M ON M.ID = FF.IDMACHINE
WHERE F.ETAT = 11 AND OFF.IDINGREDIENTS IS NOT NULL
;
-- [797/1309] RESULTATMAINTENANCELIB
CREATE OR REPLACE FORCE VIEW "RESULTATMAINTENANCELIB" ("ID","DATY","IDORDRETRAVAUX","IDPERSONNEL","ETATMACHINE","DESIGNATION","PROCHAINEETAPE","PROCHAINEDATY","IDPERSONNELLIB","ETATMACHINELIB") AS
SELECT
    rm."ID",rm."DATY",rm."IDORDRETRAVAUX",rm."IDPERSONNEL",rm."ETATMACHINE",rm."DESIGNATION",rm."PROCHAINEETAPE",rm."PROCHAINEDATY",
    u.nomuser AS idpersonnelLib,
    em.val AS etatmachineLib
FROM resultatmaintenance rm
         LEFT JOIN utilisateur u ON rm.idpersonnel = u.REFUSER
         LEFT JOIN etatmachine em ON rm.etatmachine = em.id
;
-- [798/1309] RESULTATPREVISIONNEL
CREATE OR REPLACE FORCE VIEW "RESULTATPREVISIONNEL" ("DATY","DEBIT","CREDIT") AS
SELECT 
daty,
sum(debit) AS debit, 
sum(credit) AS credit 
FROM PREVISIONvalide p  group by daty
;
-- [799/1309] RESULTATPREVISIONNELEFFECTIF
CREATE OR REPLACE FORCE VIEW "RESULTATPREVISIONNELEFFECTIF" ("DATY","DEBIT","CREDIT") AS
SELECT daty,
sum(debit) AS debit, 
sum(credit) AS credit
FROM MOUVEMENTCAISSE_VISE  group by daty
;
-- [800/1309] RESULTATPREVISIONNELMVT
CREATE OR REPLACE FORCE VIEW "RESULTATPREVISIONNELMVT" ("DATY","DEBIT","CREDIT") AS
SELECT 
daty,
greatest(sum(debit-effectifdeb),0) AS debit, 
greatest(sum(credit-effectifCred),0) AS credit 
FROM PrevisionAvecMvtCaisse p  group by daty
;
-- [801/1309] RESULTATRAPPROCHEMENT
CREATE OR REPLACE FORCE VIEW "RESULTATRAPPROCHEMENT" ("ID","IDSOUSECRITURE","IDRELEVERDETAIL","DEBIT","CREDIT","DATY","DESIGNATIONSOUSECRITURE","DESIGNATIONRELEVEDETAIL") AS
select
    '' as id,
    '' as idSousEcriture,
    '' as idReleverDetail,
    0 as debit,
    0 as credit,
    null as daty,
    '' as designationSousEcriture,
    '' as designationReleveDetail
from dual
;
-- [802/1309] RETRAIT_FRAIS_MEDICAUX_ANALYSE
CREATE OR REPLACE FORCE VIEW "RETRAIT_FRAIS_MEDICAUX_ANALYSE" ("DIRECTION","DIRECTIONLIB","MOIS","ANNEE","DATEVAL","DATEDESC","DATELIB","GAIN","DEPENSE") AS
SELECT
    ld.id AS direction,
    ld.val AS directionlib,
    pe.mois,
    pe.annee,
    CASE
        WHEN pe.mois = 13 THEN TO_DATE('01-12-' || pe.annee, 'DD-MM-YYYY')
        ELSE TO_DATE('01-' || LPAD(pe.mois, 2, '0') || '-' || pe.annee, 'DD-MM-YYYY')
        END AS dateval,
    pe.annee || '-' || LPAD(pe.mois, 2, '0') AS datedesc,
    CASE
        WHEN pe.mois = 1 THEN 'Janvier'
        WHEN pe.mois = 2 THEN 'Fevrier'
        WHEN pe.mois = 3 THEN 'Mars'
        WHEN pe.mois = 4 THEN 'Avril'
        WHEN pe.mois = 5 THEN 'Mai'
        WHEN pe.mois = 6 THEN 'Juin'
        WHEN pe.mois = 7 THEN 'Juillet'
        WHEN pe.mois = 8 THEN 'Aout'
        WHEN pe.mois = 9 THEN 'Septembre'
        WHEN pe.mois = 10 THEN 'Octobre'
        WHEN pe.mois = 11 THEN 'Novembre'
        WHEN pe.mois = 12 THEN 'Decembre'
        WHEN pe.mois = 13 THEN '13 eme'
        ELSE NULL
        END || '-' || pe.annee AS datelib,
    SUM(pe.gain) AS gain,
    NVL(SUM(rf.montant), 0) AS depense
FROM paie_edition pe
         LEFT JOIN paie_info_personnel_libcomplet pf ON pf.id = pe.idpersonnel
         LEFT JOIN log_direction ld ON ld.id = pf.direction
         LEFT JOIN retrait_frais_medicaux rf
                   ON pe.mois = EXTRACT(MONTH FROM rf.daty)
                       AND pe.annee = EXTRACT(YEAR FROM rf.daty)
                       AND rf.etat >= 11
WHERE pe.idelementpaie NOT LIKE '%PR000FRM%'
GROUP BY
    pe.mois,
    pe.annee,
    ld.id,
    ld.val
;
-- [803/1309] RETRAIT_FRAIS_MEDICAUX_LIB
CREATE OR REPLACE FORCE VIEW "RETRAIT_FRAIS_MEDICAUX_LIB" ("ID","DATY","IDPERSONNEL","DESCRIPTION","MONTANT","ETAT","IDPERSONNELLIB","ETATLIB","MATRICULE") AS
SELECT rfm.id,
       rfm.daty,
       pipl.id AS idpersonnel,
       rfm.description,
       rfm.montant,
       rfm.etat,
       (pipl.nom || ' ') || pipl.prenom AS idpersonnellib,
       CASE
           WHEN rfm.etat = 1 THEN 'CREE(E)'
           WHEN rfm.etat = 10 THEN 'VALIDE(E)'
           WHEN rfm.etat >= 11 THEN 'VISE(E)'
           ELSE NULL
           END AS etatlib,
       pipl.matricule
FROM retrait_frais_medicaux rfm
         LEFT JOIN paie_info_personnel_libcomplet pipl ON rfm.idpersonnel = pipl.id
;
-- [804/1309] RETRAIT_FRAIS_MEDIC_GRPPERS
CREATE OR REPLACE FORCE VIEW "RETRAIT_FRAIS_MEDIC_GRPPERS" ("MONTANT","IDPERSONNEL") AS
SELECT sum(retrait_frais_medicaux.montant) AS montant,
       retrait_frais_medicaux.idpersonnel
FROM retrait_frais_medicaux
WHERE retrait_frais_medicaux.etat >= 9
GROUP BY retrait_frais_medicaux.idpersonnel
;
-- [805/1309] PERSONNE_GAIN_SORTIE_RESTE
CREATE OR REPLACE FORCE VIEW "PERSONNE_GAIN_SORTIE_RESTE" ("ID","DATESAISIE","MATRICULE","LIEU_NAISSANCE_COMMUNE","LIEU_DELIVRANCE_CIN","SITUATION_MATRIMONIAL","INITIALE","CTURGENCE_NOM_PRENOM","CTURGENCE_TELEPHONE1","CTURGENCE_TELEPHONE2","CTURGENCE_TELEPHONE3","IDCONJOINT","CODE_AGENCE_BANQUE","BANQUE_NUMERO_COMPTE","BANQUE_COMPTE_CLE","DATEEMBAUCHE","IDFONCTION","IDCATEGORIE","MODE_PAIEMENT","CLASSEE","INDICEGRADE","INDICE_FONCTIONNEL","MATRICULE_PATRON","STATUT","DROIT_HS","VEHICULEE","ECHELON","ETAT","CTG","IDUSER","INDICE_CT","DATEPROMOTION","NUMERO_CNAPS","NUMERO_OSTIE","TEMPORAIRE","N_EMBAUCHE","DATE_DEPART","N_DEPART","NBENFANT","HEUREJOURNALIER","HEUREHEBDOMADAIRE","HEUREMENSUEL","INDESIRABLE","DUREE","TELEPHONE","MAIL","ADRESSE_LIGNE1","ADRESSE_LIGNE2","CODE_POSTAL","REGION","IDCATEGORIE_PAIE","IDQUALIFICATION","FORMATION","DISCIPLINE","ANNEEEXPERIENCE","PERSONNEL_ETAT","PERIODE_ESSAI","PERMIS_CONDUIRE","CHEMIN_PERMIS","REMARQUE","ID_PERS","NOM","PRENOM","DATE_NAISSANCE","SEXE","NUMERO_CIN","DATE_CIN","DATE_DUPL_CIN","NATIONALITE","ADRESSE","FOKOTANY","ACTE_NAISSANCE","DIRECTION","SERVICE","GAIN","MONTANT","RESTE") AS
SELECT pip.id,
       pip.datesaisie,
       pip.matricule,
       pip.lieu_naissance_commune,
       pip.lieu_delivrance_cin,
       pip.situation_matrimonial,
       pip.initiale,
       pip.cturgence_nom_prenom,
       pip.cturgence_telephone1,
       pip.cturgence_telephone2,
       pip.cturgence_telephone3,
       pip.idconjoint,
       pip.code_agence_banque,
       pip.banque_numero_compte,
       pip.banque_compte_cle,
       pip.dateembauche,
       pip.idfonction,
       pip.idcategorie,
       pip.mode_paiement,
       pip.classee,
       pip.indicegrade,
       pip.indice_fonctionnel,
       pip.matricule_patron,
       pip.statut,
       pip.droit_hs,
       pip.vehiculee,
       pip.echelon,
       pip.etat,
       pip.ctg,
       pip.iduser,
       pip.indice_ct,
       pip.datepromotion,
       pip.numero_cnaps,
       pip.numero_ostie,
       pip.temporaire,
       pip.n_embauche,
       pip.date_depart,
       pip.n_depart,
       pip.nbenfant,
       pip.heurejournalier,
       pip.heurehebdomadaire,
       pip.heuremensuel,
       pip.indesirable,
       pip.duree,
       pip.telephone,
       pip.mail,
       pip.adresse_ligne1,
       pip.adresse_ligne2,
       pip.code_postal,
       pip.region,
       pip.idcategorie_paie,
       pip.idqualification,
       pip.formation,
       pip.discipline,
       pip.anneeexperience,
       pip.personnel_etat,
       pip.periode_essai,
       pip.permis_conduire,
       pip.chemin_permis,
       pip.remarque,
       pip.id_pers,
       pip.nom,
       pip.prenom,
       pip.date_naissance,
       pip.sexe,
       pip.numero_cin,
       pip.date_cin,
       pip.date_dupl_cin,
       pip.nationalite,
       pip.adresse,
       pip.fokotany,
       pip.acte_naissance,
       pip.direction,
       pip.service,
       COALESCE(pep.gain, 0) AS gain,
       COALESCE(pe.montant, 0) AS montant,
       COALESCE(pep.gain, 0) - COALESCE(pe.montant, 0) AS reste
FROM paie_info_personnel_libcomplet pip
         LEFT JOIN paie_edition_grp_personne2 pep ON pip.id = pep.idpersonnel
         LEFT JOIN retrait_frais_medic_grppers pe ON pe.idpersonnel = pip.id
;
-- [806/1309] RETRAIT_FRAIS_MEDICAUX_RESTE
CREATE OR REPLACE FORCE VIEW "RETRAIT_FRAIS_MEDICAUX_RESTE" ("ID","DATY","IDPERSONNEL","DESCRIPTION","MONTANT","ETAT","RESTE") AS
SELECT rfm.id,
       rfm.daty,
       rfm.idpersonnel,
       rfm.description,
       rfm.montant,
       rfm.etat,
       p.reste
FROM retrait_frais_medicaux rfm
         LEFT JOIN personne_gain_sortie_reste p ON rfm.idpersonnel = p.id
;
-- [807/1309] RISTOURNEDETAILS_LIB
CREATE OR REPLACE FORCE VIEW "RISTOURNEDETAILS_LIB" ("ID","IDRISTOURNE","IDPRODUIT","TAUX1","TAUX2","IDORIGINE","IDPRODUITLIB","QTE","PU") AS
SELECT
    r.Id,
    r.idristourne,
    r.idproduit,
    r.taux1,
    r.taux2,
    r.idorigine,
    nvl(ai.libellevente,ai.LIBELLE) AS idproduitlib,
    r.QTE,
    r.PU
FROM RISTOURNEDETAILS r
         LEFT JOIN AS_INGREDIENTS ai ON ai.id=r.idproduit
;
-- [808/1309] RISTOURNELIB
CREATE OR REPLACE FORCE VIEW "RISTOURNELIB" ("ID","DESIGNATION","IDCLIENT","DATY","DATEDEBUTRISTOURNE","DATEFINRISTOURNE","IDORIGINE","ETAT","IDCLIENTLIB","ETATLIB","MOTSCLESSS") AS
SELECT SQ.ID,
       SQ.DESIGNATION,
       SQ.IDCLIENT,
       SQ.DATY,
       SQ.DATEDEBUTRISTOURNE,
       SQ.DATEFINRISTOURNE,
       SQ.IDORIGINE,
       SQ.ETAT,
       SQ.IDCLIENTLIB,
       SQ.ETATLIB,
       (
           id || ' | ' || designation || ' | ' || SQ.IDCLIENTLIB
           ) AS MOTSCLESSS
FROM (SELECT R.ID,
             R.DESIGNATION,
             R.IDCLIENT,
             R.DATY,
             R.DATEDEBUTRISTOURNE,
             R.DATEFINRISTOURNE,
             R.IDORIGINE,
             R.ETAT,
             C.NOM   AS IDCLIENTLIB,
             CASE
                 WHEN R.ETAT = 0
                     THEN 'ANNUL&Eacute;E'
                 WHEN R.ETAT = 1
                     THEN 'CR&Eacute;&Eacute;E'
                 WHEN R.ETAT = 11
                     THEN 'VIS&Eacute;E'
                 END AS ETATLIB
      FROM RISTOURNE R
               LEFT JOIN CLIENT C ON R.IDCLIENT = C.ID) SQ
;
-- [809/1309] SALAIREBASEMOIS
CREATE OR REPLACE FORCE VIEW "SALAIREBASEMOIS" ("IDPERSONNEL","MOIS","ANNEE","SALAIREBASE") AS
SELECT IDPERSONNEL,mois,annee,round(sum(gain),0) AS salairebase FROM paie_edition WHERE IDELEMENTPAIE IN (
    SELECT id FROM PAIE_RUBRIQUE pr WHERE TYPERUBRIQUE='G' AND IMPOSABLE = 'I'
) GROUP BY IDPERSONNEL,mois,annee
;
-- [810/1309] SALAIRECATEGORIE_ACTIF
CREATE OR REPLACE FORCE VIEW "SALAIRECATEGORIE_ACTIF" ("ID","IDCATEGORIE","IDQUALIFICATION","REMARQUE","MONTANT","DATE_DEBUT","ETAT") AS
SELECT
    cq.id,
    cq.idcategorie,
    cq.idqualification,
    cq.remarque,
    cq.montant,
    cq.date_debut,
    cq.etat
FROM CATEGORIE_QUALIFICATION cq
WHERE cq.etat = 1
;
-- [811/1309] SECTIONLIB
CREATE OR REPLACE FORCE VIEW "SECTIONLIB" ("ID","IDSERVICE","VAL","DESCE","IDSERVICELIB") AS
SELECT 
    s."ID",s."IDSERVICE",s."VAL",s."DESCE",
    sv.LIBELLE AS idServiceLib
FROM SECTION s
LEFT JOIN SERVICE sv 
    ON s.IDSERVICE = sv.ID
;
-- [812/1309] SECTION_LIB
CREATE OR REPLACE FORCE VIEW "SECTION_LIB" ("ID","IDSERVICE","VAL","DESCE","LIBELLE","COMPTE") AS
SELECT
    s."ID",s."IDSERVICE",s."VAL",s."DESCE",
    ser.LIBELLE AS libelle,
    ''  AS compte
FROM SECTION s
         LEFT JOIN departementDivers ser
                   ON s.IDSERVICE = ser.ID
;
-- [813/1309] SERVICEMAINTENANCE
CREATE OR REPLACE FORCE VIEW "SERVICEMAINTENANCE" ("ID","VAL","DESCE") AS
SELECT
    LOG_SERVICE.id,
    LOG_SERVICE.libelle AS val,
    LOG_SERVICE.libelle AS desce
FROM LOG_SERVICE
WHERE
    id LIKE 'SERVM%'
;
-- [814/1309] SESSION_FORMATION_LIB
CREATE OR REPLACE FORCE VIEW "SESSION_FORMATION_LIB" ("ID","IDACTIONFORMATION","IDACTIONFORMATIONLIB","INTITULE","REFERENCE","DATEDEBUT","DATEFIN","NBHEUREPREVUE","ETAT","ETATLIB","REMARQUE") AS
SELECT
    sf.ID,
    sf.IDACTIONFORMATION,
    af.REFERENCE || ' - ' || af.INTITULE AS IDACTIONFORMATIONLIB,
    af.INTITULE,
    af.REFERENCE,
    sf.DATEDEBUT,
    sf.DATEFIN,
    sf.NBHEUREPREVUE,
    sf.ETAT,
    CASE 
        WHEN sf.ETAT = 1 THEN 'Cree'
        WHEN sf.ETAT = 11 THEN 'Valide'
        WHEN sf.ETAT = 0 THEN 'Annule'
        ELSE 'Inconnu'
    END AS ETATLIB,
    sf.REMARQUE
FROM SESSION_FORMATION sf
LEFT JOIN ACTION_FORMATION af
    ON sf.IDACTIONFORMATION = af.ID
;
-- [815/1309] SITUATIONDEMANDE
CREATE OR REPLACE FORCE VIEW "SITUATIONDEMANDE" ("ID","IDPERSONNEL","IDTYPEDEMANDE","TITRE","HORAIRENORMAL","HEUREDEPART","HEUREARRIVE","IDTYPEABSENCE","MOTIF","NUMERO","DESCE","ETAT","DATY","DUREE","DATEDEPART","DATERETOUR","OBSERVATION","REMARQUE","DATEHISTORIQUE","HEUREHISTORIQUE","VALETATHIERARCHIE","RANG") AS
SELECT d.id,
       d.idpersonnel,
       d.idtypedemande,
       d.titre,
       d.horairenormal,
       d.heuredepart,
       d.heurearrive,
       d.idtypeabsence,
       d.motif,
       d.numero,
       d.desce,
       d.etat,
       d.daty,
       d.duree,
       d.datedepart,
       d.dateretour,
       d.observation,
       d.remarque,
       h.daty AS datehistorique,
       h.heure AS heurehistorique,
       e.valetathierarchie,
       e.rang
FROM demande d
         JOIN historiquedemandemax h ON h.iddemande = d.id
         JOIN etatdemande_etat e ON e.idtypedemande = d.idtypedemande AND d.etat = e.etatvisa OR d.etat = e.etatannule
;
-- [816/1309] SITUATIONDEMANDE_SUIVANT
CREATE OR REPLACE FORCE VIEW "SITUATIONDEMANDE_SUIVANT" ("ID","IDPERSONNEL","IDTYPEDEMANDE","TITRE","HORAIRENORMAL","HEUREDEPART","HEUREARRIVE","IDTYPEABSENCE","MOTIF","NUMERO","DESCE","ETAT","DATY","DUREE","DATEDEPART","DATERETOUR","OBSERVATION","REMARQUE","DATEHISTORIQUE","HEUREHISTORIQUE","VALETATHIERARCHIE","RANG","RANGSUIVANT","VALETATHIERARCHIESUIVANT","IDETATHIERARCHIE") AS
SELECT s.id,
       s.idpersonnel,
       s.idtypedemande,
       s.titre,
       s.horairenormal,
       s.heuredepart,
       s.heurearrive,
       s.idtypeabsence,
       s.motif,
       s.numero,
       s.desce,
       s.etat,
       s.daty,
       s.duree,
       s.datedepart,
       s.dateretour,
       s.observation,
       s.remarque,
       s.datehistorique,
       s.heurehistorique,
       s.valetathierarchie,
       s.rang,
       e.rang AS rangsuivant,
       e.valetathierarchie AS valetathierarchiesuivant,
       e.idetathierarchie
FROM situationdemande s
         JOIN etatdemande_etat e ON e.idtypedemande = s.idtypedemande AND e.rang = (s.rang + 1)
;
-- [817/1309] SITUATION_ARTICLE
CREATE OR REPLACE FORCE VIEW "SITUATION_ARTICLE" ("ID","PRODUIT","IDBC","QUANTITE","PU","MONTANT","TVA","UNITE","REMISE","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","FOURNISSEUR","REFERENCE","QTE_RESTE") AS
select bc."ID",bc."PRODUIT",bc."IDBC",bc."QUANTITE",bc."PU",bc."MONTANT",bc."TVA",bc."UNITE",bc."REMISE",bc."DATY",bc."ETAT",bc."REMARQUE",bc."DESIGNATION",bc."MODEPAIEMENT",bc."FOURNISSEUR",bc."REFERENCE",
       BC.QUANTITE - nvl(AB.qte_livre,0) AS QTE_reste
from AS_BONDECOMMANDE_MF bc
         left join AS_BONDELIVRAISON_LIVRE AB on AB.IDBC_FILLE = bc.id
;
-- [818/1309] SITUATION_BUDGET_DEPENSES
CREATE OR REPLACE FORCE VIEW "SITUATION_BUDGET_DEPENSES" ("ID","COMPTE","SERVICE","MOIS","ANNEE","MOISLIB","BUDGET","MONTANTFACTURE","PAIEMENT","RESTEAPAYER","ECARTFACTUREBUDGET","ECARTBUDGETPAIEMENT","MOTSCLESSS") AS
SELECT SQ.ID,SQ.COMPTE,SQ.SERVICE,SQ.MOIS,SQ.ANNEE,SQ.MOISLIB,SQ.BUDGET,SQ.MONTANTFACTURE,SQ.PAIEMENT,SQ.RESTEAPAYER,SQ.ECARTFACTUREBUDGET,SQ.ECARTBUDGETPAIEMENT,
	       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(COMPTE),'') || ' | ' || NVL(TO_CHAR(SERVICE),'') || ' | ' || NVL(TO_CHAR(MOIS),'') || ' | ' || NVL(TO_CHAR(ANNEE),'') || ' | ' || NVL(TO_CHAR(MOISLIB),'') || ' | ' || NVL(TO_CHAR(BUDGET),'') || ' | ' || NVL(TO_CHAR(MONTANTFACTURE),'') || ' | ' || NVL(TO_CHAR(PAIEMENT),'') || ' | ' || NVL(TO_CHAR(RESTEAPAYER),'') || ' | ' || NVL(TO_CHAR(ECARTFACTUREBUDGET),'') || ' | ' || NVL(TO_CHAR(ECARTBUDGETPAIEMENT),'')) AS MOTSCLESSS
	FROM (
	         select
	             '-' as id,
	             bdsv.COMPTE,
	             IDSERVICELIB as service,
	             bdsv.mois,
	             bdsv.annee,
	             bdsv.moislib,
	             bdsv.depenses as budget,
	             ffc.montant as montantfacture,
	             ffc.montantpaye as paiement,
	             ffc.resteapayer,
	             bdsv.depenses - ffc.montant as ecartfacturebudget,
	             bdsv.depenses - ffc.montantpaye as ecartbudgetpaiement
	         from budget_depense_sum_view bdsv
	                  left join (
	             select
	                 SUBSTR(compteregr, 1, LENGTH(bdsv_inner.COMPTE)) as compteregr_groupe,
	                 mois,
	                 annee,
	                 SERVICE,
	                 sum(montantfille * TAUXDECHANGE)     as montant,
	                 sum(MontantFillePaye * TAUXDECHANGE) as montantpaye,
	                 sum(resteapayerfille * TAUXDECHANGE) as resteapayer
	             from facturefournisseurfille_paye ffp
	                      cross join (select distinct COMPTE from budget_depense_sum_view_budget) bdsv_inner
	             where SUBSTR(ffp.compteregr, 1, LENGTH(bdsv_inner.COMPTE)) = bdsv_inner.COMPTE
	             group by SUBSTR(compteregr, 1, LENGTH(bdsv_inner.COMPTE)), mois, annee, SERVICE
	         ) ffc
	                            on ffc.compteregr_groupe like bdsv.COMPTE||'%'
	                                and ffc.mois = bdsv.mois
	                                and ffc.annee = bdsv.annee
	                                and ffc.SERVICE = bdsv.SERVICE
	     ) SQ
;
-- [819/1309] SITUATION_BUDGET_DEPENSES_VIDE
CREATE OR REPLACE FORCE VIEW "SITUATION_BUDGET_DEPENSES_VIDE" ("ID","COMPTE","SERVICE","ANNEE","MOISDEBUT","MOISDEBUTLIB","MOISFIN","MOISFINLIB","BUDGET","MONTANTFACTURE","PAIEMENT","RESTEAPAYER","ECARTFACTUREBUDGET","ECARTBUDGETPAIEMENT") AS
select id, compte, service, annee, 6 as moisdebut,moisdebutlib, 8 as moisfin,moisfinlib, budget, montantfacture, paiement, resteapayer, ECARTFACTUREBUDGET, ECARTBUDGETPAIEMENT from
	    (select ID,
	            COMPTE,
	            SERVICE,
	            ANNEE,
	            sum(nvl(BUDGET, 0)) as budget,
	            sum(nvl(MONTANTFACTURE, 0)) as montantfacture,
	            sum(nvl(PAIEMENT, 0)) as paiement,
	            SUM(nvl(RESTEAPAYER, 0)) as resteapayer,
	            SUM(nvl(ECARTFACTUREBUDGET, 0)) as ECARTFACTUREBUDGET,
	            SUM(nvl(ECARTBUDGETPAIEMENT, 0)) as ECARTBUDGETPAIEMENT,
	            TO_CHAR(
	                    TO_DATE(TO_CHAR(6, 'FM00'), 'MM'),
	                    'FMMonth',
	                    'NLS_DATE_LANGUAGE=FRENCH'
	            ) AS moisdebutlib,
	            TO_CHAR(
	                    TO_DATE(TO_CHAR(8, 'FM00'), 'MM'),
	                    'FMMonth',
	                    'NLS_DATE_LANGUAGE=FRENCH'
	            ) AS moisfinlib
	     from situation_budget_depenses where mois between 6 and 8 group by ID, COMPTE, SERVICE, ANNEE)
;
-- [820/1309] SITUATION_SALAIRE_AUTRE
CREATE OR REPLACE FORCE VIEW "SITUATION_SALAIRE_AUTRE" ("IDPERSONNEL","IDEDITION","MOIS","ANNEE","HEURESUPP30NI","HEURESUPP30I","HEURESUPP50NI","HEURESUPP50I","MAJNUIT","MAJFERIE","MAJWEEKEND","ABBATEMENT") AS
SELECT
    idpersonnel,
    idedition,
    mois,
    annee,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR0000130'  THEN gain ELSE 0 END) AS heuresupp30ni,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR0000130I' THEN gain ELSE 0 END) AS heuresupp30i,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR0000150'  THEN gain ELSE 0 END) AS heuresupp50ni,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR0000150I'  THEN gain ELSE 0 END) AS heuresupp50i,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR0000221' THEN gain ELSE 0 END) AS majnuit,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR0000222'  THEN gain ELSE 0 END) AS majferie,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR0000223'  THEN gain ELSE 0 END) AS majweekend,
    SUM(CASE WHEN IDELEMENTPAIE = 'PR000181'  THEN gain ELSE 0 END) AS abbatement
FROM PAIE_EDITION pe
GROUP BY
    idpersonnel,idedition,mois,annee
;
-- [821/1309] SITUATION_SALAIRE_EDITION_DIST
CREATE OR REPLACE FORCE VIEW "SITUATION_SALAIRE_EDITION_DIST" ("ID","IDEDITION","NBENFANT","MATRICULE","NOM","PRENOM","PERSONNEL","FONCTION","IDFONCTION","CLASSIFICATION","IDCATEGORIE","IDDIRECTION","DIRECTION","SECTION","SECTION_NUMERO","SECTION_LIBELLE","SALAIRE","SALAIREBRUTE","HEUREMOIS","HEUREPRESENCE","TAUXHORAIRE","SALAIREMOIS","HEURESUP","RAPPEL","RETENUABSC","PRIME","CONGEPAYER","PREAVIS","NETPAYER","NETPAYERARR","INDAMDIVFIXE","CNAPS","OSTIE","NETIMPOSABLE","NETIMPOSABLEARR","IRSA","IRSANET","ALLOCATION","AVANCESALAIRE","AVANCEEXCEP","ANNEE","MOIS") AS
SELECT DISTINCT
    lp.ID,
    pe.idedition AS idedition,
    pip.nbenfant,
    pip.MATRICULE,
    trim(TRAILING ' ' FROM lp.NOM) AS nom,
    trim(TRAILING ' ' FROM lp.PRENOM) AS prenom,
    trim(TRAILING ' ' FROM lp.NOM)
        || ' '
        || trim(TRAILING ' ' FROM lp.PRENOM) AS personnel,
    pf.desce AS fonction,
    pf.id AS idfonction,
    pc.VAL AS classification,
    pc.id AS idcategorie,
    ld.ID AS iddirection,
    ld.VAL AS direction,
    ls.ID AS SECTION,
    ls.CODE_SERVICE AS section_numero,
    ls.libelle AS section_libelle,
    nvl(SALAIREDEBASE.salairedebase, 0) AS salaire,
    nvl(totalgain.gain,0) as salairebrute,
    173.33 as heuremois,
    nvl(poi.HEURENORMAL, 0) AS heurepresence,
    nvl(pe.tauxhoraire, 0) AS tauxhoraire,
    nvl(salaire.gain, 0) AS salairemois,
    nvl(heuresup.gain, 0) AS heuresup,
    nvl(rappel.gain, 0) AS rappel,
    nvl(retenuabsc.retenue, 0) AS retenuabsc,
    nvl(prime.gain, 0) AS prime,
    nvl(congepayer.gain, 0) AS congepayer,
    nvl(preavis.gain, 0) AS preavis,
    nvl(netpayer.gain, 0) AS netpayer,
    nvl(netpayerarr.gain, 0) AS netpayerarr,
    nvl(indamdivfixe.gain, 0) AS indamdivfixe,
    nvl(cnaps.retenue, 0) AS cnaps,
    nvl(ostie.retenue, 0) AS ostie,
    nvl(netimposable.retenue, 0) AS netimposable,
    nvl(netimposablearr.retenue, 0) AS netimposablearr,
    nvl(irsa.retenue, 0) AS irsa,
    nvl(irsanet.retenue, 0) AS irsanet,
    nvl(allocation.gain,0) as allocation,
    nvl(avancesalaire.retenue, 0) AS avancesalaire,
    nvl(avanceexcep.retenue, 0) AS avanceexcep,
    pe.annee,
    pe.mois
FROM -- select * from
     paie_edition pe
         INNER JOIN log_personnel lp ON
         lp.id = pe.idpersonnel
         INNER JOIN paie_info_personnel pip ON
         pip.id = pe.idpersonnel
         INNER JOIN log_direction ld ON
         pe.DIRECTION = ld.ID
         INNER JOIN log_service ls ON
         pe.SERVICE = ls.ID
         INNER JOIN CATEGORIE_PAIE pc ON
         pe.IDCATEGORIE = pc.ID
         INNER JOIN paie_fonction pf ON
         pe.IDFONCTION = pf.ID
         INNER JOIN POINTAGE poi ON
         pe.IDPERSONNEL = poi.IDPERSONNEL
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 1
         GROUP BY
             idpersonnel,
             mois,
             annee) salaire
                   ON
                       salaire.idpersonnel = lp.id
                           AND salaire.annee = pe.annee
                           AND salaire.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             max(SALAIREDEBASE) AS salairedebase,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 18
         GROUP BY
             idpersonnel,
             mois,
             annee) salairedebase
                   ON
                       salairedebase.idpersonnel = lp.id
                           AND salairedebase.annee = pe.annee
                           AND salairedebase.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 2
         GROUP BY
             idpersonnel,
             mois,
             annee) heuresup
                   ON
                       heuresup.idpersonnel = lp.id
                           AND heuresup.annee = pe.annee
                           AND heuresup.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 3
         GROUP BY
             idpersonnel,
             mois,
             annee) rappel
                   ON
                       rappel.idpersonnel = lp.id
                           AND rappel.annee = pe.annee
                           AND rappel.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(RETENUE) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 4
         GROUP BY
             idpersonnel,
             mois,
             annee) retenuabsc
                   ON
                       retenuabsc.idpersonnel = lp.id
                           AND retenuabsc.annee = pe.annee
                           AND retenuabsc.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 5
         GROUP BY
             idpersonnel,
             mois,
             annee) prime
                   ON
                       prime.idpersonnel = lp.id
                           AND prime.annee = pe.annee
                           AND prime.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             PAIE_EDITION_LIBCOMPLET pe
         WHERE
             CODERUBRIQUE IN ('403', '4030')
         GROUP BY
             idpersonnel,
             mois,
             annee) hs30
                   ON
                       hs30.idpersonnel = lp.id
                           AND hs30.annee = pe.annee
                           AND hs30.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             PAIE_EDITION_LIBCOMPLET pe
         WHERE
             CODERUBRIQUE IN ('405', '4050')
         GROUP BY
             idpersonnel,
             mois,
             annee) hs50
                   ON
                       hs50.idpersonnel = lp.id
                           AND hs50.annee = pe.annee
                           AND hs50.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 6
         GROUP BY
             idpersonnel,
             mois,
             annee) congepayer
                   ON
                       congepayer.idpersonnel = lp.id
                           AND congepayer.annee = pe.annee
                           AND congepayer.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 7
         GROUP BY
             idpersonnel,
             mois,
             annee) preavis
                   ON
                       preavis.idpersonnel = lp.id
                           AND preavis.annee = pe.annee
                           AND preavis.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 8
         GROUP BY
             idpersonnel,
             mois,
             annee) indamdivfixe
                   ON
                       indamdivfixe.idpersonnel = lp.id
                           AND indamdivfixe.annee = pe.annee
                           AND indamdivfixe.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 9
         GROUP BY
             idpersonnel,
             mois,
             annee) totalgain
                   ON
                       totalgain.idpersonnel = lp.id
                           AND totalgain.annee = pe.annee
                           AND totalgain.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 10
         GROUP BY
             idpersonnel,
             mois,
             annee) cnaps
                   ON
                       cnaps.idpersonnel = lp.id
                           AND cnaps.annee = pe.annee
                           AND cnaps.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             PAIE_EDITION_LIBCOMPLET pe
         WHERE
             CODERUBRIQUE IN ('700', '701')
         GROUP BY
             idpersonnel,
             mois,
             annee) cnaps_sans_complementaire
                   ON
                       cnaps_sans_complementaire.idpersonnel = lp.id
                           AND cnaps_sans_complementaire.annee = pe.annee
                           AND cnaps_sans_complementaire.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             PAIE_EDITION_LIBCOMPLET pe
         WHERE
             CODERUBRIQUE IN ('705', '706')
         GROUP BY
             idpersonnel,
             mois,
             annee) cnaps_complementaire
                   ON
                       cnaps_complementaire.idpersonnel = lp.id
                           AND cnaps_complementaire.annee = pe.annee
                           AND cnaps_complementaire.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 11
         GROUP BY
             idpersonnel,
             mois,
             annee) ostie
                   ON
                       ostie.idpersonnel = lp.id
                           AND ostie.annee = pe.annee
                           AND ostie.mois = pe.mois
         LEFT JOIN (
