             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 14
         GROUP BY
             idpersonnel,
             mois,
             annee) irsa
                   ON
                       irsa.idpersonnel = lp.id
                           AND irsa.annee = pe.annee
                           AND irsa.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 15
         GROUP BY
             idpersonnel,
             mois,
             annee) irsanet
                   ON
                       irsanet.idpersonnel = lp.id
                           AND irsanet.annee = pe.annee
                           AND irsanet.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(RETENUE) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 16
         GROUP BY
             idpersonnel,
             mois,
             annee) avancesalaire
                   ON
                       avancesalaire.idpersonnel = lp.id
                           AND avancesalaire.annee = pe.annee
                           AND avancesalaire.mois = pe.mois
         LEFT JOIN (
