             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 18
         GROUP BY
             idpersonnel,
             mois,
             annee) netpayer
                   ON
                       netpayer.idpersonnel = lp.id
                           AND netpayer.annee = pe.annee
                           AND netpayer.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 19
         GROUP BY
             idpersonnel,
             mois,
             annee) netpayerarr
                   ON
                       netpayerarr.idpersonnel = lp.id
                           AND netpayerarr.annee = pe.annee
                           AND netpayerarr.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 20
         GROUP BY
             idpersonnel,
             mois,
             annee) allocation
                   ON
                       allocation.idpersonnel = lp.id
                           AND allocation.annee = pe.annee
                           AND allocation.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             regroupement = 100
         GROUP BY
             idpersonnel,
             mois,
             annee) net_a_payer
                   ON
                       net_a_payer.idpersonnel = lp.id
                           AND net_a_payer.annee = pe.annee
                           AND net_a_payer.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe
         WHERE
             (regroupement != 100
                 OR regroupement IS NULL)
         GROUP BY
             idpersonnel,
             mois,
             annee) salaire_brute
                   ON
                       salaire_brute.idpersonnel = lp.id
                           AND salaire_brute.annee = pe.annee
                           AND salaire_brute.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(retenue) AS retenue,
             mois,
             annee
         FROM
             paie_edition pe
         GROUP BY
             idpersonnel,
             mois,
             annee) total_retenue
                   ON
                       total_retenue.idpersonnel = lp.id
                           AND total_retenue.annee = pe.annee
                           AND total_retenue.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             paie_edition pe,
             paie_rubrique pr
         WHERE
             pr.id = pe.idelementpaie
           AND pr.imposable = 'I'
         GROUP BY
             idpersonnel,
             mois,
             annee) montant_brute_imposable
                   ON
                       montant_brute_imposable.idpersonnel = lp.id
                           AND montant_brute_imposable.annee = pe.annee
                           AND montant_brute_imposable.mois = pe.mois
         LEFT JOIN (
         SELECT
             idpersonnel,
             sum(gain) AS gain,
             mois,
             annee
         FROM
             PAIE_EDITION_LIBCOMPLET pe
         WHERE
             CODERUBRIQUE IN ('205')
         GROUP BY
             idpersonnel,
             mois,
             annee) indemnite_logement
                   ON
                       indemnite_logement.idpersonnel = lp.id
                           AND indemnite_logement.annee = pe.annee
                           AND indemnite_logement.mois = pe.mois
GROUP BY
    lp.ID,
    lpad(pe.MATRICULE, 5, '0'),
    pc.id,
    trim(TRAILING ' ' FROM lp.NOM),
    trim(TRAILING ' ' FROM lp.PRENOM),
    lp.NOM || ' ' || lp.PRENOM ,
    pf.DESCE,
    pf.id,
    pc.VAL ,
    ld.ID,
    ld.VAL,
    ls.ID,
    ls.CODE_SERVICE,
    ls.LIBELLE,
    pe.temporaire,
    nvl(SALAIREDEBASE.salairedebase, 0),
    nvl(heuresup.gain, 0),
    nvl(rappel.gain, 0),
    nvl(retenuabsc.retenue, 0),
    nvl(prime.gain, 0),
    nvl(net_a_payer.gain, 0),
    nvl(montant_brute_imposable.gain, 0),
    nvl(congepayer.gain, 0),
    nvl(preavis.gain, 0),
    nvl(hs30.gain, 0),
    nvl(hs50.gain, 0),
    nvl(indamdivfixe.gain, 0),
    nvl(totalgain.gain, 0),
    nvl(cnaps.retenue, 0),
    nvl(ostie.retenue, 0),
    nvl(salaire_brute.gain, 0),
    nvl(cnaps.retenue, 0),
    nvl(ostie.retenue, 0),
    nvl(irsa.retenue, 0),
    nvl(irsanet.retenue, 0),
    nvl(netimposable.retenue, 0),
    nvl(netimposablearr.retenue, 0),
    nvl(total_retenue.retenue, 0),
    nvl(avancesalaire.retenue, 0),
    nvl(avanceexcep.retenue, 0),
    nvl(cnaps_sans_complementaire.retenue, 0),
    nvl(cnaps_complementaire.retenue, 0),
    nvl(rappel.gain, 0),
    nvl(netpayer.gain, 0),
    nvl(netpayerarr.gain, 0),
    nvl(indemnite_logement.gain, 0),
    nvl(pe.tauxhoraire, 0),
    pip.MATRICULE,
    nvl(totalgain.gain,0),
    nvl(allocation.gain,0),
    173.33,
    nvl(poi.HEURENORMAL, 0),
    nvl(salaire.gain, 0),
    0,
    pip.nbenfant,
    pe.annee,
    pe.mois,
    pe.idedition
;
-- [822/1309] SOCOBISMAINTENANCE0203
CREATE OR REPLACE FORCE VIEW "SOCOBISMAINTENANCE0203" ("ID","IDELEMENTINSPECTION","IDMACHINE","IDELEMENTINSPECTIONLIB","IDMACHINELIB") AS
(
    SELECT
        eim.id,
        eim.idElementInspection as idElementInspection,
        eim.idMachine as idMachine,
        ei.val      AS idElementInspectionLib,
        m.libelle       AS idMachineLib
    FROM ElementInspectionMachine eim
             LEFT JOIN ElementInspection ei
                       ON eim.idElementInspection = ei.id
             LEFT JOIN AS_INGREDIENT_MAINTENANCE  m
                       ON eim.idMachine = m.id
)
;
-- [823/1309] SOLDECONGE_FIN_2023
CREATE OR REPLACE FORCE VIEW "SOLDECONGE_FIN_2023" ("IDPERSONNEL","ID","MATRICULE","CONGE") AS
SELECT pip.id AS idpersonnel,
       cf.id,
       cf.matricule,
       cf.conge
FROM conge_fin_2023 cf
         LEFT JOIN paie_info_personnel pip ON pip.matricule = cf.matricule
;
-- [824/1309] DROITDECONGE_PARPERS
CREATE OR REPLACE FORCE VIEW "DROITDECONGE_PARPERS" ("IDPERSONNEL","CONGE") AS
SELECT cd.idpersonnel AS idpersonnel,
       sum(cd.conge) AS conge
FROM soldeconge_fin_2023 cd
GROUP BY cd.idpersonnel
;
-- [825/1309] DROITDECONGE_PARPERSONNE
CREATE OR REPLACE FORCE VIEW "DROITDECONGE_PARPERSONNE" ("IDPERSONNEL","CONGE") AS
SELECT dp.idpersonnel,
       round((dp.conge + pij.jourconge) * 2) / 2 - 1.5 AS conge
FROM droitdeconge_parpers dp
         LEFT JOIN paie_info_jours_mois3_bis pij ON dp.idpersonnel = pij.id
;
-- [826/1309] LOG_PERSONNEL_FIN
CREATE OR REPLACE FORCE VIEW "LOG_PERSONNEL_FIN" ("ID","PERMIS_CONDUIRE","CHEMIN_PERMIS","REMARQUE","ID_PERS","NOM","PRENOM","DATE_NAISSANCE","SEXE","NUMERO_CIN","DATE_CIN","DATE_DUPL_CIN","NATIONALITE","ADRESSE","FOKOTANY","ACTE_NAISSANCE","DIRECTION","SERVICE","CODE_DR","MATRICULE","IDCATEGORIE","CTG","INDICEGRADE","INDICE_FONCTIONNEL","STATUT","CATEGORIEVAL","CTGVAL","NUMERO_CNAPS","NUMERO_OSTIE","TEMPORAIRE","DROIT","PRIE","RESTECONGE","ETAT","IDPERSONNEL","IDDIRECTION","DEPARTEMENTLIB","IDDEPARTEMENT","IDQUALIFICATION","QUALIFICATIONLIB","IDCATEGORIE_PAIE") AS
SELECT l.id,
       l.permis_conduire,
       l.chemin_permis,
       l.remarque,
       l.id_pers,
       l.nom,
       l.prenom,
       l.date_naissance,
       sex.desce AS sexe,
       l.numero_cin,
       l.date_cin,
       l.date_dupl_cin,
       l.nationalite,
       l.adresse,
       l.fokotany,
       l.acte_naissance,
       d.val AS direction,
       s.code_service AS service,
       s.code_dr,
       TO_CHAR(paie.matricule) AS matricule,
       paie.idcategorie,
       paie.ctg,
       paie.indicegrade,
       paie.indice_fonctionnel,
       paie.statut,
       c.taux AS categorieval,
       '''' AS ctgval,
       paie.numero_cnaps,
       paie.numero_ostie,
       CASE
           WHEN paie.temporaire = -1 THEN 'Temporaire'
           WHEN paie.temporaire = 0 THEN 'Permanent'
           WHEN paie.temporaire = 1 THEN 'Cadre'
           ELSE NULL
           END AS temporaire,
       NVL(dr.conge, 0) AS droit,
       NVL(cg.conge, 0) AS prie,
       NVL(dr.conge, 0) - NVL(cg.conge, 0) AS resteconge,
       paie.etat,
       l.id AS idpersonnel,
       l.direction AS iddirection,
       dp.val as departementLib,
       paie.IDDEPARTEMENT,
       paie.IDQUALIFICATION,
       qp.val AS qualificationLib,
       paie.IDCATEGORIE_PAIE
FROM log_personnel l
         LEFT JOIN log_service s ON l.service = s.id
         LEFT JOIN paie_info_personnel paie ON paie.id = l.id
         LEFT JOIN sexe sex ON l.sexe = sex.id
         LEFT JOIN log_direction d ON d.id = l.direction
         LEFT JOIN paie_categorie c ON c.id = paie.idcategorie
         LEFT JOIN droitdeconge_parpersonne dr ON dr.idpersonnel = l.id
         LEFT JOIN congeprisgroupbypers cg ON cg.idpersonnel = l.id
         LEFT JOIN DEPARTEMENT dp ON dp.id = paie.IDDEPARTEMENT
         LEFT JOIN QUALIFICATION_PAIE qp ON qp.id = paie.IDQUALIFICATION
;
-- [827/1309] CATEGORIEQUALIFICATION_LIB
CREATE OR REPLACE FORCE VIEW "CATEGORIEQUALIFICATION_LIB" ("ID","MATRICULE","NOMPERSONNEL","MONTANT","CATEGORIELIB","QUALIFICATIONLIB") AS
SELECT
	    log.id,
	    log.MATRICULE,
	    log.nom || ' ' || log.prenom as nomPersonnel,
	    c.MONTANT,
	    cp.val as categorieLib,
	    qp.val as qualificationLib
	FROM LOG_PERSONNEL_FIN log
	         LEFT JOIN CATEGORIE_QUALIFICATION c
	                   ON c.IDQUALIFICATION = log.IDQUALIFICATION
	                       AND c.IDCATEGORIE = log.IDCATEGORIE_PAIE
	                       AND (
	                          (c.REMARQUE IS NULL)
	                              OR (c.REMARQUE = log.ID)
	                          ) AND c.etat = 1
	         LEFT JOIN CATEGORIE_PAIE cp ON cp.id = c.IDCATEGORIE
	         LEFT JOIN QUALIFICATION_PAIE qp ON qp.id = c.IDQUALIFICATION
;
-- [828/1309] EMPLOYE_COMPLET_PDF
CREATE OR REPLACE FORCE VIEW "EMPLOYE_COMPLET_PDF" ("ID","NOM","PRENOM","ID_PERS","INITIALE","MATRICULE","DATE_NAISSANCE","LIEU_NAISSANCE_COMMUNE","SEXE","NUMERO_CIN","DATE_CIN","DATE_DUPL_CIN","LIEU_DELIVRANCE_CIN","ADRESSE","FOKOTANY","NATIONALITE","ACTE_NAISSANCE","SITUATION_MATRIMONIAL","IDCONJOINT","DIRECTION","SERVICE","IDFONCTION","CTG","IDCATEGORIE","CLASSEE","INDICEGRADE","INDICE_FONCTIONNEL","MATRICULE_PATRON","STATUT","MODE_PAIEMENT","CODE_AGENCE_BANQUE","BANQUE_NUMERO_COMPTE","BANQUE_COMPTE_CLE","PERMIS_CONDUIRE","REMARQUE","CHEMIN_PERMIS","CTURGENCE_NOM_PRENOM","CTURGENCE_TELEPHONE1","CTURGENCE_TELEPHONE2","CTURGENCE_TELEPHONE3","DATEEMBAUCHE","DATESAISIE","CODE_DR","BANQUE_CODE","ECHELON","ETAT","VEHICULEE","DATE_DERNIERPROMO","DROIT_HS","HEUREJOURNALIER","HEUREHEBDOMADAIRE","HEUREMENSUEL","NUMERO_CNAPS","NUMERO_OSTIE","TEMPORAIRE","NBENFANT","INDESIRABLE","DUREE","TELEPHONE","MAIL","IDCATEGORIE_PAIE","IDQUALIFICATION","DISCIPLINE","FORMATION","ANNEEEXPERIENCE","MONTANT","CONGER") AS
SELECT logp.id,
       logp.nom,
       logp.prenom,
       logp.id_pers,
       paie.initiale,
       paie.matricule,
       logp.date_naissance,
       paie.lieu_naissance_commune,
       logp.sexe,
       logp.numero_cin,
       logp.date_cin,
       logp.date_dupl_cin,
       paie.lieu_delivrance_cin,
       paie.adresse_ligne1 AS adresse,
       logp.fokotany,
       logp.nationalite,
       logp.acte_naissance,
       paie.situation_matrimonial,
       paie.idconjoint,
       logp.direction,
       logp.service,
       fonct.desce AS idfonction,
       paie.ctg,
       paie.idcategorie,
       paie.classee,
       paie.indicegrade,
       paie.indice_fonctionnel,
       paie.matricule_patron,
       paie.statut,
       paie.mode_paiement,
       paie.code_agence_banque,
       paie.banque_numero_compte,
       paie.banque_compte_cle,
       logp.permis_conduire,
       logp.remarque,
       logp.chemin_permis,
       paie.cturgence_nom_prenom,
       paie.cturgence_telephone1,
       paie.cturgence_telephone2,
       paie.cturgence_telephone3,
       paie.dateembauche,
       paie.datesaisie,
       ld.val AS code_dr,
       trs.val AS banque_code,
       paie.echelon,
       paie.etat,
       paie.vehiculee,
       tab.date_dernierpromo,
       paie.droit_hs,
       paie.heurejournalier,
       paie.heurehebdomadaire,
       paie.heuremensuel,
       paie.numero_cnaps,
       paie.numero_ostie,
       paie.temporaire,
       paie.nbenfant,
       paie.indesirable,
       cp.essaie AS duree,
       paie.telephone,
       paie.mail,
       cp.val AS idcategorie_paie,
       qp.val AS idqualification,
       paie.discipline,
       paie.formation,
       paie.anneeexperience,
       cq.montant,
       cd.resteconge AS conger
FROM log_personnel logp
         LEFT JOIN ( SELECT paie_avancement.id_logpers,
                            max(paie_avancement.datedecision) AS date_dernierpromo
                     FROM paie_avancement
                     GROUP BY paie_avancement.id_logpers) tab ON logp.id = tab.id_logpers
         LEFT JOIN paie_info_personnel paie ON logp.id = paie.id
         LEFT JOIN log_service serv ON serv.id = logp.service
         LEFT JOIN trs_banques_agences trs ON paie.code_agence_banque = trs.id
         LEFT JOIN paie_fonction fonct ON fonct.id = paie.idfonction
         LEFT JOIN categorie_paie cp ON cp.id = paie.idcategorie_paie
         LEFT JOIN qualification_paie qp ON qp.id = paie.idqualification
         LEFT JOIN categorie_qualification cq ON cq.idcategorie = paie.idcategorie_paie AND cq.idqualification = paie.idqualification AND cq.remarque = logp.id AND cq.etat = 1
         LEFT JOIN log_direction ld ON ld.id = logp.direction
         LEFT JOIN log_personnel_fin cd ON cd.id = logp.id
;
-- [829/1309] LOG_PERSONNEL_GRAPHE
