-- [830/1309] EFFECTIF_LOG_PERSONNEL
CREATE OR REPLACE FORCE VIEW "EFFECTIF_LOG_PERSONNEL" ("SEXE","NOMBRE","IDCATEGORIE","IDCATEGORIELIB","IDDEPARTEMENT","DEPARTEMENTLIB") AS
SELECT
    CASE
        WHEN sexe = 'Masculin' THEN 'Masculin'
        WHEN sexe = 'Feminin' THEN 'Feminin'
        ELSE 'Non defini'
    END AS sexe,
    COUNT(*) AS nombre,
    idCategorie,
    idCategorieLib,
    IDDEPARTEMENT AS idDepartement,
    departementLib
FROM LOG_PERSONNEL_GRAPHE
GROUP BY
    CASE
        WHEN sexe = 'Masculin' THEN 'Masculin'
        WHEN sexe = 'Feminin' THEN 'Feminin'
        ELSE 'Non defini'
    END,
    idCategorie,
    idCategorieLib,
    IDDEPARTEMENT,
    departementLib
;
-- [831/1309] LOG_PERSONNEL_V
