-- [833/1309] EMPLOYEEONBOARDINGSESSIONSCPL
CREATE OR REPLACE FORCE VIEW "EMPLOYEEONBOARDINGSESSIONSCPL" ("ID","DATEDEBUT","DATEFIN","ETAT","PROGRESSION","IDPERSONNEL","PERSONNELLIB","IDONBOARDING","ONBOARDINGLIB") AS
SELECT
    s.id,
    s.dateDebut,
    s.dateFin,
    s.etat,
    s.progression,

    p.id AS idPersonnel,
    p.nom as personnelLib,

    o.id AS idOnboarding,
    o.nom as onboardinglib
FROM employee_onboarding_sessions s
         JOIN log_personnel_v2 p ON s.idPersonnel = p.id
         JOIN onboarding_mere o ON s.idOnboarding = o.id
;
-- [834/1309] EMP_ONBOARDING_COM
CREATE OR REPLACE FORCE VIEW "EMP_ONBOARDING_COM" ("ID","DATEDEBUT","DATEFIN","ETAT","PROGRESSION","IDPERSONNEL","PERSONNELLIB","IDONBOARDING","ONBOARDINGLIB","IDFONCTION","IDFONCTIONLIB") AS
SELECT
    eos.ID,eos.DATEDEBUT,eos.DATEFIN,eos.ETAT,eos.PROGRESSION,eos.IDPERSONNEL,eos.PERSONNELLIB,eos.IDONBOARDING,eos.ONBOARDINGLIB,
    om.idFonction,
    pf.val AS idFonctionLib
FROM EMPLOYEEONBOARDINGSESSIONSCPL eos
         LEFT JOIN onboarding_mere om
                   ON om.id = eos.IDONBOARDING
         LEFT JOIN paie_fonction pf
                   ON pf.id = om.idFonction
WHERE om.idFonction IS NULL
;
-- [835/1309] EMP_ONBOARDING_SPEC
CREATE OR REPLACE FORCE VIEW "EMP_ONBOARDING_SPEC" ("ID","DATEDEBUT","DATEFIN","ETAT","PROGRESSION","IDPERSONNEL","PERSONNELLIB","IDONBOARDING","ONBOARDINGLIB","IDFONCTION","IDFONCTIONLIB") AS
SELECT
    eos.ID,eos.DATEDEBUT,eos.DATEFIN,eos.ETAT,eos.PROGRESSION,eos.IDPERSONNEL,eos.PERSONNELLIB,eos.IDONBOARDING,eos.ONBOARDINGLIB,
    om.idFonction,
    pf.val AS idFonctionLib
FROM EMPLOYEEONBOARDINGSESSIONSCPL eos
         LEFT JOIN onboarding_mere om
                   ON om.id = eos.IDONBOARDING
         LEFT JOIN paie_fonction pf
                   ON pf.id = om.idFonction
WHERE om.idFonction IS NOT NULL
;
-- [836/1309] ENFANTPERSONNEL_CPL
CREATE OR REPLACE FORCE VIEW "ENFANTPERSONNEL_CPL" ("ID","IDPERSONNEL","NOM","DATENAISSANCE","GENRELIB","NOMPERSONNEL","MATRICULE","AGE","ESTSCOLARISELIB") AS
SELECT
    e.ID,
    e.IDPERSONNEL,
    e.NOM,
    e.DATENAISSANCE,
    CASE
        WHEN e.GENRE = 1 THEN 'Masculin'
        ELSE 'F&eacute;minin'
    END AS GENRELIB,
    log.nom || ' ' || log.prenom AS nomPersonnel,
    log.matricule,
    FLOOR(MONTHS_BETWEEN(SYSDATE, e.dateNaissance) / 12) AS age,
    CASE 
    	WHEN e.estScolarise  = 1 
    	THEN 'Oui'
    	WHEN e.estScolarise  = 0
    	THEN 'Non'
    END AS estScolariseLib
FROM ENFANTPERSONNEL e
LEFT JOIN LOG_PERSONNEL_V2 log
    ON e.idpersonnel = log.id
;
-- [837/1309] EVALUATION_ANNUELLE_LIB
CREATE OR REPLACE FORCE VIEW "EVALUATION_ANNUELLE_LIB" ("ID","IDPERSONNEL","IDPERSONNELLIB","MATRICULE","IDFONCTION","IDFONCTIONLIB","ANNEE","NOTEGLOBALE","COMMENTAIRE","ETAT","ETATLIB") AS
SELECT
    ea.ID,
    ea.IDPERSONNEL,
    lp.NOM || ' ' || lp.PRENOM AS IDPERSONNELLIB,
    pip.MATRICULE AS MATRICULE,
    pip.IDFONCTION AS IDFONCTION,
    pf.VAL AS IDFONCTIONLIB,
    ea.ANNEE,
    ea.NOTEGLOBALE,
    ea.COMMENTAIRE,
    ea.ETAT,
    CASE
        WHEN ea.ETAT = 1 THEN 'En cours'
        WHEN ea.ETAT = 11 THEN 'Termin&eacute;e'
        WHEN ea.ETAT = 0 THEN 'ANNUL&Eacute;E'
        END AS ETATLIB
FROM EVALUATION_ANNUELLE ea
         LEFT JOIN LOG_PERSONNEL_V2 lp
                   ON ea.IDPERSONNEL = lp.ID
         LEFT JOIN PAIE_INFO_PERSONNEL pip
                   ON ea.IDPERSONNEL = pip.ID
         LEFT JOIN PAIE_FONCTION pf
                   ON pip.IDFONCTION = pf.ID
;
-- [838/1309] LOG_PERSONNEL_V2_USER
CREATE OR REPLACE FORCE VIEW "LOG_PERSONNEL_V2_USER" ("ID","PERMIS_CONDUIRE","CHEMIN_PERMIS","REMARQUE","ID_PERS","NOM","PRENOM","DATE_NAISSANCE","SEXE","NUMERO_CIN","DATE_CIN","DATE_DUPL_CIN","NATIONALITE","ADRESSE","FOKOTANY","ACTE_NAISSANCE","DIRECTION","SERVICE","CODE_DR","MATRICULE","IDCATEGORIE","CTG","INDICEGRADE","INDICE_FONCTIONNEL","STATUT","CATEGORIEVAL","CTGVAL","NUMERO_CNAPS","NUMERO_OSTIE","TEMPORAIRE","RESTECONGE","CATEGORIE","QUALIFICATION","IDDIRECTION","IDDEPARTEMENT","IDCATEGORIE_PAIE","IDUTILISATEUR") AS
Select
    l.ID,l.PERMIS_CONDUIRE,l.CHEMIN_PERMIS,l.REMARQUE,l.ID_PERS,l.NOM,l.PRENOM,l.DATE_NAISSANCE,l.SEXE,l.NUMERO_CIN,l.DATE_CIN,l.DATE_DUPL_CIN,l.NATIONALITE,l.ADRESSE,l.FOKOTANY,l.ACTE_NAISSANCE,l.DIRECTION,l.SERVICE,l.CODE_DR,l.MATRICULE,l.IDCATEGORIE,l.CTG,l.INDICEGRADE,l.INDICE_FONCTIONNEL,l.STATUT,l.CATEGORIEVAL,l.CTGVAL,l.NUMERO_CNAPS,l.NUMERO_OSTIE,l.TEMPORAIRE,l.RESTECONGE,l.CATEGORIE,l.QUALIFICATION,l.IDDIRECTION,l.IDDEPARTEMENT,l.IDCATEGORIE_PAIE,
    up.idUtilisateur as idutilisateur
from log_personnel_v2 l
         JOIN utilisateur_personnel up ON up.idpersonnel=l.id
;
-- [839/1309] LOG_PERSONNEL_V_FRAIS_MEDICAUX
CREATE OR REPLACE FORCE VIEW "LOG_PERSONNEL_V_FRAIS_MEDICAUX" ("ID","PERMIS_CONDUIRE","CHEMIN_PERMIS","REMARQUE","ID_PERS","NOM","PRENOM","DATE_NAISSANCE","SEXE","NUMERO_CIN","DATE_CIN","DATE_DUPL_CIN","NATIONALITE","ADRESSE","FOKOTANY","ACTE_NAISSANCE","DIRECTION","SERVICE","CODE_DR","MATRICULE","IDCATEGORIE","CTG","INDICEGRADE","INDICE_FONCTIONNEL","STATUT","CATEGORIEVAL","CTGVAL","NUMERO_CNAPS","NUMERO_OSTIE","TEMPORAIRE","RESTECONGE","RESTE_FRAIS_MEDICAUX") AS
SELECT lp.id,
       lp.permis_conduire,
       lp.chemin_permis,
       lp.remarque,
       lp.id_pers,
       lp.nom,
       lp.prenom,
       lp.date_naissance,
       lp.sexe,
       lp.numero_cin,
       lp.date_cin,
       lp.date_dupl_cin,
       lp.nationalite,
       lp.adresse,
       lp.fokotany,
       lp.acte_naissance,
       lp.direction,
       lp.service,
       lp.code_dr,
       lp.matricule,
       lp.idcategorie,
       lp.ctg,
       lp.indicegrade,
       lp.indice_fonctionnel,
       lp.statut,
       lp.categorieval,
       lp.ctgval,
       lp.numero_cnaps,
       lp.numero_ostie,
       lp.temporaire,
       lp.resteconge,
       COALESCE(p.reste, 0) AS reste_frais_medicaux
FROM log_personnel_v lp
         LEFT JOIN personne_gain_sortie_reste p ON lp.id = p.id
;
-- [840/1309] NB_PERS_VALIDE
CREATE OR REPLACE FORCE VIEW "NB_PERS_VALIDE" ("NBPERSONNELVALIDE") AS
SELECT COUNT(*) AS NBPERSONNELVALIDE FROM LOG_PERSONNEL_V
;
-- [841/1309] PAIEPERS_ELTFILLE
CREATE OR REPLACE FORCE VIEW "PAIEPERS_ELTFILLE" ("ID","IDPERSONNEL","PERSONNELLIB","MATRICULE","MONTANT","REMARQUE","IDDEPARTEMENT","IDDIRECTION") AS
SELECT
    '' as ID,
    v.ID as idPersonnel,
    v.NOM || ' ' || v.PRENOM as personnelLib,
    v.MATRICULE,
    0 as montant,
    null as remarque,
    v.IDDEPARTEMENT,
    v.IDDIRECTION
FROM LOG_PERSONNEL_V2 v
;
-- [842/1309] PARTICIPATION_FORMATION_LIB
CREATE OR REPLACE FORCE VIEW "PARTICIPATION_FORMATION_LIB" ("ID","IDACTIONFORMATION","IDPERSONNEL","DATEINSCRIPTION","REMARQUE","ETAT","PERSONNEL","MATRICULE","CATEGORIEEMPLOYE","IDACTIONFORMATIONLIB","ETATLIB") AS
SELECT
    pf.ID,pf.IDACTIONFORMATION,pf.IDPERSONNEL,pf.DATEINSCRIPTION,pf.REMARQUE,pf.ETAT,
    lp.nom || ' '|| lp.prenom as personnel,
    pip.matricule,
    cp.val AS categorieEmploye,
    af.intitule AS idActionFormationLib,
    CASE
        WHEN pf.etat = 1 THEN 'INSCRIT'
        WHEN pf.etat = 11 THEN 'VALIDE'
        ELSE 'INCONNU'
        END AS etatLib
FROM PARTICIPATION_FORMATION pf
         LEFT JOIN PAIE_INFO_PERSONNEL pip
                   ON pip.id = pf.idpersonnel
         LEFT JOIN CATEGORIE_PAIE cp
                   ON pip.idcategorie_paie = cp.id
         LEFT JOIN ACTION_FORMATION af
                   ON af.id = pf.idactionformation
        LEFT JOIN log_personnel_v2 lp ON pip.id = lp.id
;
-- [843/1309] SANCTION_CPL
CREATE OR REPLACE FORCE VIEW "SANCTION_CPL" ("ID","IDPERSONNE","NOMPERSONNEL","DATEDEBUT","DATY","DUREE","NIVEAUSANCTION","LIBELLEFAUTE","SANCTION","REGLEMENTLIB","NUMEROREGLE","ETAT","MATRICULE") AS
SELECT
    s.id,
    s.IDPERSONNE,
    lpr.nom || ' ' || lpr.prenom AS nomPersonnel,
    s.datedebut,
    s.daty,
    s.duree,
    s.niveausanction,
    tf.val AS libelleFaute,
    ts.val AS sanction,
    ri.DESCRIPTIONREGLE AS reglementLib,
    ri.NUMEROREGLE AS numeroRegle,
    s.etat AS etat,
    lpr.MATRICULE
FROM SANCTION s
         LEFT JOIN LOG_PERSONNEL_V2 lpr ON s.idpersonne = lpr.id
         LEFT JOIN TYPEFAUTE tf ON s.TYPEFAUTE = tf.ID
         LEFT JOIN typesanction ts ON s.typesanction = ts.id
         LEFT JOIN REGLEMENTINTERIEUR ri ON s.IDREGLEENFREINTE = ri.id
;
-- [844/1309] SOLDECONGEPRIS_PERS
CREATE OR REPLACE FORCE VIEW "SOLDECONGEPRIS_PERS" ("ID","PLUS","CONGEPRIS","NOMPERSONNEL","MATRICULE","IDDIRECTION") AS
SELECT
    lp.ID AS ID,
    CAST(sum(nvl(m.PLUS,0)) AS NUMBER(30, 2)) AS plus ,
    CAST(sum(nvl(m.MOINS ,0)) AS NUMBER(30, 2)) AS congepris ,
    lp.nom || ' ' || lp.prenom AS nomPersonnel,
    lp.matricule AS matricule,
    lp.iddirection AS idDirection
FROM MOUVEMENTABSENCE m
         LEFT JOIN LOG_PERSONNEL_V2 lp ON lp.ID = m.IDPERSONNEL
GROUP BY lp.NOM ,
         lp.PRENOM , lp.ID, lp.matricule, lp.IDDIRECTION
;
-- [845/1309] SOLDECONGE_PERS
CREATE OR REPLACE FORCE VIEW "SOLDECONGE_PERS" ("PLUS","MOINS","SOLDE","NOM","PRENOM","IDPERSONNEL") AS
SELECT
    CAST(sum(nvl(m.PLUS,0)) AS NUMBER(30, 2)) AS plus ,
    CAST(sum(nvl(m.MOINS ,0)) AS NUMBER(30, 2)) AS moins ,
    CAST(sum(nvl(m.PLUS,0)) - sum(nvl(m.MOINS ,0)) AS NUMBER(30, 2)) AS solde ,
    lp.NOM ,
    lp.PRENOM ,
    lp.ID AS IDPERSONNEL
FROM MOUVEMENTABSENCE m
         LEFT JOIN LOG_PERSONNEL lp ON lp.ID = m.IDPERSONNEL
where m.IDSOURCE='TYP000004'
GROUP BY lp.NOM ,
         lp.PRENOM , lp.ID
;
-- [846/1309] DROITCONGE_PERS
CREATE OR REPLACE FORCE VIEW "DROITCONGE_PERS" ("ID","DROIT","NOMPERSONNEL","MATRICULE","IDDIRECTION") AS
SELECT
    sp.IDPERSONNEL AS id ,
    CAST(sp.PLUS AS NUMBER(30, 2)) AS droit,
    sp.NOM || ' ' || sp.PRENOM AS nomPersonnel,
    log.matricule ,
    log.iddirection
FROM SOLDECONGE_PERS sp
         LEFT JOIN LOG_PERSONNEL_V2 log ON log.id = sp.IDPERSONNEL
;
-- [847/1309] LOG_PERSONNEL_AVECCONGE
CREATE OR REPLACE FORCE VIEW "LOG_PERSONNEL_AVECCONGE" ("ID","PERMIS_CONDUIRE","CHEMIN_PERMIS","REMARQUE","ID_PERS","NOM","PRENOM","DATE_NAISSANCE","SEXE","NUMERO_CIN","DATE_CIN","DATE_DUPL_CIN","NATIONALITE","ADRESSE","FOKOTANY","ACTE_NAISSANCE","DIRECTION","SERVICE","CODE_DR","MATRICULE","IDCATEGORIE","CTG","INDICEGRADE","INDICE_FONCTIONNEL","STATUT","CATEGORIEVAL","CTGVAL","NUMERO_CNAPS","NUMERO_OSTIE","TEMPORAIRE","DROIT","PRIE","RESTECONGE","ETAT","IDPERSONNEL","IDDIRECTION","IDDEPARTEMENT","DEPARTEMENTLIB","IDQUALIFICATION","QUALIFICATIONLIB","ETATLIB") AS
SELECT l.id,
       l.permis_conduire,
       l.chemin_permis,
       l.remarque,
       l.id_pers,
       l.nom,
       l.prenom,
       l.date_naissance,
       sex.desce AS sexe,
       l.numero_cin,
       l.date_cin,
       l.date_dupl_cin,
       l.nationalite,
       l.adresse,
       l.fokotany,
       l.acte_naissance,
       d.val AS direction,
       s.libelle AS service,
       s.code_dr,
       TO_CHAR(paie.matricule) AS matricule,
       paie.idcategorie,
       paie.ctg,
       paie.indicegrade,
       paie.indice_fonctionnel,
       paie.statut,
       c.taux AS categorieval,
       '' AS ctgval,
       paie.numero_cnaps,
       paie.numero_ostie,
       CASE
           WHEN paie.temporaire = -1 THEN 'Temporaire'
           WHEN paie.temporaire = 0 THEN 'Permanent'
           WHEN paie.temporaire = 1 THEN 'Cadre'
           ELSE NULL
           END AS temporaire,
       CAST(NVL(sc.PLUS , 0) AS NUMBER(30, 2)) AS droit ,
       CAST(NVL(sp.CONGEPRIS , 0) AS NUMBER(30, 2)) AS prie,
       CAST(NVL(sc.SOLDE, 0) AS NUMBER(30, 2)) AS resteconge,
       paie.etat,
       l.id AS idpersonnel,
       l.direction AS iddirection,
       dp.id AS idDepartement,
       dp.val AS departementlib,
       qp.id AS idQualification,
       qp.val as qualificationLib,
       CASE
           WHEN paie.etat < 1 THEN 'Debauches'
           WHEN paie.etat = 1 THEN 'A Valider'
           WHEN paie.etat = 11 THEN 'Valides'
           ELSE NULL
           END AS etatLib
FROM log_personnel l
         LEFT JOIN log_service s ON l.service = s.id
         LEFT JOIN paie_info_personnel paie ON paie.id = l.id
         LEFT JOIN sexe sex ON l.sexe = sex.id
         LEFT JOIN log_direction d ON d.id = l.direction
         LEFT JOIN paie_categorie c ON c.id = paie.idcategorie
         LEFT JOIN SOLDECONGEPRIS_PERS sp ON l.id = sp.id
         LEFT JOIN SOLDECONGE_PERS sc ON l.id = sc.idPersonnel
         LEFT JOIN departement dp ON paie.idDepartement = dp.id
         LEFT JOIN QUALIFICATION_PAIE qp ON qp.id = paie.IDQUALIFICATION
;
-- [848/1309] LOG_PERSONNEL_FIN_CONGE
CREATE OR REPLACE FORCE VIEW "LOG_PERSONNEL_FIN_CONGE" ("ID","PERMIS_CONDUIRE","CHEMIN_PERMIS","REMARQUE","ID_PERS","NOM","PRENOM","DATE_NAISSANCE","SEXE","NUMERO_CIN","DATE_CIN","DATE_DUPL_CIN","NATIONALITE","ADRESSE","FOKOTANY","ACTE_NAISSANCE","DIRECTION","SERVICE","CODE_DR","MATRICULE","IDCATEGORIE","CTG","INDICEGRADE","INDICE_FONCTIONNEL","STATUT","CATEGORIEVAL","CTGVAL","NUMERO_CNAPS","NUMERO_OSTIE","TEMPORAIRE","DROIT","PRIE","RESTECONGE","ETAT","IDPERSONNEL","IDDIRECTION","IDDEPARTEMENT","DEPARTEMENTLIB","IDQUALIFICATION","QUALIFICATIONLIB","ETATLIB") AS
SELECT l.id,
