-- [852/1309] ORGANIGRAMMELIB
CREATE OR REPLACE FORCE VIEW "ORGANIGRAMMELIB" ("ID","DESCE","VAL","NOMPERSONNE","MATRICULE","POSTE") AS
SELECT o.id,
       o.desce,
       lp.id AS val,
       (lp.nom || ' ') || lp.prenom AS nompersonne,
       lp.matricule,
       pf.desce AS poste
FROM log_personnel_fin_valide lp
         LEFT JOIN organigramme o ON lp.id = o.val
         LEFT JOIN paie_info_personnel pip ON pip.id = lp.id
         LEFT JOIN paie_fonction pf ON pf.id = pip.idfonction
ORDER BY o.desce DESC NULLS LAST
;
-- [853/1309] SOLDECONGE_PERS_CPL
CREATE OR REPLACE FORCE VIEW "SOLDECONGE_PERS_CPL" ("DROIT","CONGEPRIS","SOLDE","NOMPERSONNEL","ID","MATRICULE") AS
SELECT
    CAST(sum(nvl(m.PLUS,0)) AS NUMBER(30, 2)) AS droit ,
    CAST(sum(nvl(m.MOINS ,0)) AS NUMBER(30, 2)) AS congePris ,
    CAST(sum(nvl(m.PLUS,0)) - sum(nvl(m.MOINS ,0)) AS NUMBER(30, 2)) AS solde ,
    lp.NOM || ' ' || lp.PRENOM AS nomPersonnel,
    lp.ID ,
    pip.MATRICULE
FROM MOUVEMENTABSENCE m
         LEFT JOIN LOG_PERSONNEL lp ON lp.ID = m.IDPERSONNEL
         LEFT JOIN PAIE_INFO_PERSONNEL pip ON pip.id = lp.ID WHERE m.IDSOURCE ='TYP000004'
GROUP BY lp.NOM ,
         lp.PRENOM , lp.ID, pip.MATRICULE
;
-- [854/1309] SOLDEPERMISSION_PERS
CREATE OR REPLACE FORCE VIEW "SOLDEPERMISSION_PERS" ("IDPERSONNEL","ANNEE","PERMISSIONPRIS") AS
SELECT
    m.IDPERSONNEL ,
    m.ANNEE ,
    CAST(SUM(NVL(m.MOINS,0)) AS NUMBER(30, 2)) AS permissionPris
FROM
    MOUVEMENTABSENCE m
GROUP BY m.IDPERSONNEL , m.ANNEE
;
-- [855/1309] SOLDE_CONGE_PERS
CREATE OR REPLACE FORCE VIEW "SOLDE_CONGE_PERS" ("ID","CONGEDROIT","CONGEPRIS","CONGERESTE","NOM","PRENOM","MATRICULE","IDDEPARTEMENT","IDDEPARTEMENTLIB") AS
SELECT
    pip.id,
    CAST(SUM(NVL(mvt.plus, 0)) AS NUMBER(30,2)) AS congedroit,
    CAST(SUM(NVL(mvt.moins, 0)) AS NUMBER(30,2)) AS congepris,
    CAST(
            SUM(NVL(mvt.plus, 0)) - SUM(NVL(mvt.moins, 0))
        AS NUMBER(30,2)
    ) AS congereste,
    log.NOM,
    log.PRENOM,
    pip.MATRICULE,
    pip.IDDEPARTEMENT,
    dep.VAL AS IDDEPARTEMENTLib
FROM PAIE_INFO_PERSONNEL pip
         LEFT JOIN MOUVEMENTABSENCE mvt
                   ON mvt.IDPERSONNEL = pip.id
                       AND mvt.IDTYPE = 'TYP000004'
         LEFT JOIN log_personnel_v log
                   ON log.id = pip.id
         LEFT JOIN DEPARTEMENT dep
                   ON dep.id = pip.IDDEPARTEMENT
GROUP BY
    pip.id,
    log.NOM,
    log.PRENOM,
    pip.MATRICULE,
    pip.IDDEPARTEMENT,
    dep.VAL
;
-- [856/1309] SOLDE_FORMATION_SYNDICALE
CREATE OR REPLACE FORCE VIEW "SOLDE_FORMATION_SYNDICALE" ("ID","ANNEE","CONGEDROIT","CONGEPRIS","CONGERESTE","NOM","PRENOM","MATRICULE","IDDEPARTEMENT","IDDEPARTEMENTLIB") AS
SELECT
    pip.id,
    NVL(mvt.ANNEE, EXTRACT(YEAR FROM SYSDATE)) AS annee,
    CAST(15 AS NUMBER(30,2)) AS congedroit,

    CAST(SUM(NVL(mvt.moins, 0)) AS NUMBER(30,2)) AS congepris,

    CAST(
            15 - SUM(NVL(mvt.moins, 0))
        AS NUMBER(30,2)
    ) AS congereste,

    log.NOM,
    log.PRENOM,
    pip.MATRICULE,
    pip.IDDEPARTEMENT,
    dep.VAL AS IDDEPARTEMENTLib

FROM PAIE_INFO_PERSONNEL pip

         LEFT JOIN MOUVEMENTABSENCE mvt
                   ON mvt.IDPERSONNEL = pip.id
                       AND mvt.IDTYPE = 'TYPCOL0005'

         LEFT JOIN log_personnel_v log
                   ON log.id = pip.id

         LEFT JOIN DEPARTEMENT dep
                   ON dep.id = pip.IDDEPARTEMENT

GROUP BY
    pip.id,
    mvt.ANNEE,
    log.NOM,
    log.PRENOM,
    pip.MATRICULE,
    pip.IDDEPARTEMENT,
    dep.VAL
;
-- [857/1309] SORTIEENTREE
CREATE OR REPLACE FORCE VIEW "SORTIEENTREE" ("MVTSRC","SORTIE") AS
SELECT 
m.mvtsrc,
sum(m.sortie) AS sortie
FROM MVTSTOCKFILLE m 
LEFT JOIN MVTSTOCK mp ON mp.id = m.IDMVTSTOCK
WHERE mp.etat = 11
GROUP BY m.mvtsrc
;
-- [858/1309] MVTSTOCKENTREEAVECRESTE
CREATE OR REPLACE FORCE VIEW "MVTSTOCKENTREEAVECRESTE" ("ID","IDMVTSTOCK","IDPRODUIT","ENTREE","SORTIE","IDVENTEDETAIL","IDTRANSFERTDETAIL","PU","MVTSRC","DATY","RESTE","QUANTITE","IDMAGASIN","IDINVENTAIREFILLE","IDOBJET","IDTRANSFERT") AS
SELECT
	m.ID,
	m.IDMVTSTOCK,
	m.IDPRODUIT,
	m.ENTREE,
	s.SORTIE,
	m.IDVENTEDETAIL,
	m.IDTRANSFERTDETAIL,
	m.PU,
	m.MVTSRC,
	mp.DATY,
	NVL(m.entree,0)- NVL(s.sortie, 0) AS reste,
	NVL(m.entree,0)- NVL(s.sortie, 0) AS quantite,
	--ity no reste miasa any
 mp.IDMAGASIN,
 m.IDINVENTAIREFILLE,
 mp.IDOBJET,
 mp.IDTRANSFERT
FROM
	MVTSTOCKFILLE m
LEFT JOIN MVTSTOCK mp ON
	mp.id = m.IDMVTSTOCK
LEFT JOIN sortieEntree s ON
	s.MVTSRC = m.id 
WHERE
	m.ENTREE >0
	AND mp.ETAT >= 11
;
-- [859/1309] MVTSTOCKENTREEAVECRESTE2
CREATE OR REPLACE FORCE VIEW "MVTSTOCKENTREEAVECRESTE2" ("ID","IDMVTSTOCK","IDPRODUIT","ENTREE","SORTIE","IDVENTEDETAIL","IDTRANSFERTDETAIL","PU","MVTSRC","DATY","RESTE","QUANTITE","IDMAGASIN") AS
SELECT
	"ID","IDMVTSTOCK","IDPRODUIT","ENTREE","SORTIE","IDVENTEDETAIL","IDTRANSFERTDETAIL","PU","MVTSRC","DATY","RESTE","QUANTITE","IDMAGASIN"
FROM
	MVTSTOCKENTREEAVECRESTE
WHERE
	QUANTITE >0
;
-- [860/1309] SORTIEPRODUIT
CREATE OR REPLACE FORCE VIEW "SORTIEPRODUIT" ("IDPRODUIT","QTESORTIE") AS
SELECT
idproduit,
CAST(sum(nvl(m.SORTIE,0)) AS NUMBER(15,2))  AS qteSortie
FROM MVTSTOCKFILLE m
LEFT JOIN MVTSTOCK mp ON mp.id = m.IDMVTSTOCK
WHERE mp.etat >= 11
GROUP BY idproduit
;
-- [861/1309] SORTIEPRODUITPARORIGINE
CREATE OR REPLACE FORCE VIEW "SORTIEPRODUITPARORIGINE" ("IDPRODUIT","IDOBJET","QTESORTIE") AS
SELECT
idproduit,
idobjet,
CAST(sum(nvl(m.SORTIE,0)) AS NUMBER(15,2))  AS qteSortie
FROM MVTSTOCKFILLE m
LEFT JOIN MVTSTOCK mp ON mp.id = m.IDMVTSTOCK
WHERE mp.etat >= 11
GROUP BY idproduit, idobjet
;
-- [862/1309] SORTIEPRODUITPARVENTE
CREATE OR REPLACE FORCE VIEW "SORTIEPRODUITPARVENTE" ("IDPRODUIT","IDOBJET","QTESORTIE","IDVENTE") AS
select spo."IDPRODUIT",spo."IDOBJET",spo."QTESORTIE", abc.IDVENTE from SORTIEPRODUITparorigine spo
    left join AS_BONDELIVRAISON_CLIENT abc on abc.id = spo.idobjet
;
-- [863/1309] SORTIEPRODUITPARVENTEGRP
CREATE OR REPLACE FORCE VIEW "SORTIEPRODUITPARVENTEGRP" ("IDPRODUIT","IDVENTE","QTESORTIE") AS
select idproduit, IDVENTE, sum(qteSortie) as qteSortie from SORTIEPRODUITparvente
group by IDVENTE, idproduit
;
-- [864/1309] SORTIESTOCKFILLE
CREATE OR REPLACE FORCE VIEW "SORTIESTOCKFILLE" ("IDPRODUIT","IDVENTEDETAIL","QTELIVREE") AS
SELECT 
m.IDPRODUIT ,
m.IDVENTEDETAIL ,
CAST(nvl(sum(m.SORTIE ),0)AS NUMBER(30,2)) AS  qtelivree
FROM MVTSTOCKFILLE m 
GROUP BY m.IDPRODUIT,m.IDVENTEDETAIL
;
-- [865/1309] ASBLCLIENTCPLASINGREDIENTS
CREATE OR REPLACE FORCE VIEW "ASBLCLIENTCPLASINGREDIENTS" ("ID","PRODUIT","NUMBL","QUANTITE","IDVENTEDETAIL","UNITE","IDBC_FILLE","IDPRODUITLIB","IDVENTE","IDBC","QTELIVREE","QTERESTEALIVRER") AS
SELECT
	abcf.ID,
	abcf.PRODUIT,
	abcf.NUMBL,
	abcf.QUANTITE,
	abcf.IDVENTEDETAIL,
	abcf.UNITE,
	abcf.IDBC_FILLE,
	p.LIBELLEEXTACTE AS idproduitlib,
	vd.idvente,
	abc.idbc,
	CAST(nvl(s.qtelivree ,0)AS NUMBER(30,2)) AS qtelivree,
	CAST(nvl(abcf.QUANTITE - CAST(nvl(s.qtelivree ,0)AS NUMBER(30,2))  ,0)AS NUMBER(30,2)) AS qteResteALivrer
FROM AS_BONDELIVRAISON_CLIENT_FILLE abcf 
LEFT JOIN AS_INGREDIENTS p ON p.id = abcf.produit
LEFT JOIN VENTE_DETAILS vd ON vd.id = abcf.IDVENTEDETAIL
LEFT JOIN AS_BONDELIVRAISON_CLIENT abc ON abc.id = abcf.numbl
LEFT JOIN sortiestockfille s ON s.IDPRODUIT = abcf.produit AND s.IDVENTEDETAIL =abcf.IDVENTEDETAIL
;
-- [866/1309] AS_BL_CLIENT_CPL_ASINGREDIENTS
CREATE OR REPLACE FORCE VIEW "AS_BL_CLIENT_CPL_ASINGREDIENTS" ("ID","PRODUIT","NUMBL","QUANTITE","IDVENTEDETAIL","UNITE","IDBC_FILLE","IDPRODUITLIB","IDVENTE","IDBC","QTELIVREE","QTERESTEALIVRER") AS
SELECT
	abcf.ID,
	abcf.PRODUIT,
	abcf.NUMBL,
	abcf.QUANTITE,
	abcf.IDVENTEDETAIL,
	abcf.UNITE,
	abcf.IDBC_FILLE,
	p.LIBELLEEXTACTE AS idproduitlib,
	vd.idvente,
	abc.idbc,
	CAST(nvl(s.qtelivree ,0)AS NUMBER(30,2)) AS qtelivree,
	CAST(nvl(abcf.QUANTITE - CAST(nvl(s.qtelivree ,0)AS NUMBER(30,2))  ,0)AS NUMBER(30,2)) AS qteResteALivrer
FROM AS_BONDELIVRAISON_CLIENT_FILLE abcf 
LEFT JOIN AS_INGREDIENTS p ON p.id = abcf.produit
LEFT JOIN VENTE_DETAILS vd ON vd.id = abcf.IDVENTEDETAIL
LEFT JOIN AS_BONDELIVRAISON_CLIENT abc ON abc.id = abcf.numbl
LEFT JOIN sortiestockfille s ON s.IDPRODUIT = abcf.produit AND s.IDVENTEDETAIL =abcf.IDVENTEDETAIL
;
-- [867/1309] AS_BONLIVRFILLE_CLIENT_CPL
CREATE OR REPLACE FORCE VIEW "AS_BONLIVRFILLE_CLIENT_CPL" ("ID","PRODUIT","NUMBL","QUANTITE","IDVENTEDETAIL","UNITE","IDBC_FILLE","IDPRODUITLIB","IDVENTE","IDBC","QTELIVREE","QTERESTEALIVRER","UNITELIB","PU","QTEVENTE") AS
SELECT
    abcf.ID,
    abcf.PRODUIT,
    abcf.NUMBL,
    abcf.QUANTITE,
    abcf.IDVENTEDETAIL,
    abcf.UNITE,
    abcf.IDBC_FILLE,
    nvl(p.LIBELLEVENTE,p.libelle) AS idproduitlib,
    vd.idvente,
    abc.idbc,
    CAST(nvl(s.qtelivree ,0)AS NUMBER(30,2)) AS qtelivree,
    CAST(nvl(abcf.QUANTITE - CAST(nvl(s.qtelivree ,0)AS NUMBER(30,2))  ,0)AS NUMBER(30,2)) AS qteResteALivrer,
    u.val AS uniteLib,
    vd.PU,
    vd.qte as qtevente
FROM AS_BONDELIVRAISON_CLIENT_FILLE abcf
         LEFT JOIN as_ingredients p ON p.id = abcf.produit
         LEFT JOIN VENTE_DETAILS vd ON vd.id = abcf.IDVENTEDETAIL and vd.IDPRODUIT = abcf.PRODUIT
         LEFT JOIN AS_BONDELIVRAISON_CLIENT abc ON abc.id = abcf.numbl
         LEFT JOIN sortiestockfille s ON s.IDPRODUIT = abcf.produit AND s.IDVENTEDETAIL =abcf.IDVENTEDETAIL
         LEFT JOIN AS_UNITE u ON u.id = abcf.UNITE
;
-- [868/1309] AS_BLCLFILLEGRP_VENTE_CPL_V
CREATE OR REPLACE FORCE VIEW "AS_BLCLFILLEGRP_VENTE_CPL_V" ("PRODUIT","IDPRODUITLIB","IDVENTE","DATY","QUANTITE","UNITE","UNITELIB","ID") AS
SELECT
	    a.PRODUIT ,
	    a.IDPRODUITLIB,
	    a.IDVENTE,
	    abc.daty,
	    nvl( sum(QUANTITE) ,0) AS QUANTITE,
	    a.UNITE,
	    u.VAL AS unitelib,
	    abc.id
	FROM AS_BONLIVRFILLE_CLIENT_CPL a
	         LEFT JOIN AS_BONDELIVRAISON_CLIENT abc ON abc.id = a.numbl
	         left join AS_UNITE u on u.id = a.unite
	WHERE abc.etat = 11
	GROUP BY a.IDPRODUITLIB,
	         a.IDVENTE,a.PRODUIT,abc.daty
	        , a.UNITE,u.val, abc.id
;
-- [869/1309] AS_BONLIVRFILLE_CLIENT_CPL2
CREATE OR REPLACE FORCE VIEW "AS_BONLIVRFILLE_CLIENT_CPL2" ("ID","PRODUIT","NUMBL","QUANTITE","IDVENTEDETAIL","UNITE","IDBC_FILLE","IDPRODUITLIB","IDVENTE","IDBC","QTELIVREE","QTERESTEALIVRER","UNITELIB","PU","QTEVENTE") AS
SELECT
    abcf.ID,
    abcf.PRODUIT,
    abcf.NUMBL,
    abcf.QUANTITE,
    vd.id as IDVENTEDETAIL,
    abcf.UNITE,
    abcf.IDBC_FILLE,
    p.LIBELLE AS idproduitlib,
    abc.IDVENTE as idvente,
    abc.idbc,
    CAST(nvl(s.qtelivree ,0)AS NUMBER(30,2)) AS qtelivree,
    CAST(nvl(abcf.QUANTITE - CAST(nvl(s.qtelivree ,0)AS NUMBER(30,2))  ,0)AS NUMBER(30,2)) AS qteResteALivrer,
    u.val AS uniteLib,
    vd.PU,
    vd.qte as qtevente
FROM AS_BONDELIVRAISON_CLIENT_FILLE abcf
         LEFT JOIN as_ingredients p ON p.id = abcf.produit
         LEFT JOIN AS_BONDELIVRAISON_CLIENT_CPL2 abc ON abc.id = abcf.numbl
         LEFT JOIN VENTE_DETAILS vd ON vd.IDVENTE = abc.IDVENTE and vd.IDPRODUIT = abcf.PRODUIT
         LEFT JOIN sortiestockfille s ON s.IDPRODUIT = abcf.produit AND s.IDVENTEDETAIL =abcf.IDVENTEDETAIL
         LEFT JOIN AS_UNITE u ON u.id = abcf.UNITE
where p.ACTIF = 1
;
-- [870/1309] AS_BLCLFILLEGRP_VENTE_CPL_V2
CREATE OR REPLACE FORCE VIEW "AS_BLCLFILLEGRP_VENTE_CPL_V2" ("ID","PRODUIT","IDPRODUITLIB","IDVENTE","DATY","QUANTITE","UNITE","UNITELIB") AS
SELECT
    a.numbl as id ,
    a.PRODUIT ,
    a.IDPRODUITLIB,
    a.IDVENTE,
    abc.daty,
    nvl( sum(QUANTITE) ,0) AS QUANTITE,
    a.UNITE,
    u.VAL AS unitelib
FROM AS_BONLIVRFILLE_CLIENT_CPL2 a
         LEFT JOIN AS_BONDELIVRAISON_CLIENT abc ON abc.id = a.numbl
         left join AS_UNITE u on u.id = a.unite
WHERE abc.etat = 11
GROUP BY a.IDPRODUITLIB,
         a.IDVENTE,a.PRODUIT,abc.daty
        , a.UNITE,u.val, a.numbl
;
-- [871/1309] RAPPROCHEMENT_BF_CLIENT
CREATE OR REPLACE FORCE VIEW "RAPPROCHEMENT_BF_CLIENT" ("ID","PRODUIT","NUMBL","QUANTITE","IDVENTEDETAIL","UNITE","IDBC_FILLE","IDPRODUITLIB","IDVENTE","IDBC","QTELIVREE","QTERESTEALIVRER","QTESORTIE","RESTEASORTIR","PU","UNITELIB") AS
SELECT abcc.ID,
       abcc.PRODUIT,
       abcc.NUMBL,
       abcc.QUANTITE,
       abcc.IDVENTEDETAIL,
       abcc.UNITE,
       abcc.IDBC_FILLE,
       abcc.IDPRODUITLIB,
       abcc.IDVENTE,
       abcc.IDBC,
       abcc.QTELIVREE,
       abcc.QTERESTEALIVRER,
       nvl(m.qteSortie, 0)                 AS qteSortie,
       least(abcc.qtevente - nvl(m.qteSortie, 0), abcc.QUANTITE) AS resteASortir,
       abcc.pu,
       au.val AS unitelib
FROM AS_BONLIVRFILLE_CLIENT_CPL abcc
         LEFT JOIN SORTIEPRODUITparventegrp m ON m.idproduit = abcc.produit and m.IDVENTE = abcc.idvente
         LEFT JOIN MVTSTOCK mv ON mv.idobjet = abcc.numbl
         LEFT JOIN as_unite au ON au.id = abcc.UNITE
;
-- [872/1309] SOUSECRITURECOMPTEEXTRAIT
CREATE OR REPLACE FORCE VIEW "SOUSECRITURECOMPTEEXTRAIT" ("COMPTE","COMPTE1","COMPTE2","COMPTE3","COMPTE4","DEBIT","CREDIT","ANNEE","ETAT") AS
select
    compte,
    SUBSTR(COMPTE, 1, 1) as compte1,
    SUBSTR(COMPTE, 1, 2) as compte2,
    SUBSTR(COMPTE, 1, 3) as compte3,
    SUBSTR(COMPTE, 1, 4) as compte4,
    DEBIT,
    CREDIT,
    EXERCICE as annee,
    etat
from COMPTA_SOUS_ECRITURE
;
-- [873/1309] SOUSECRITUREGROUPCOMPTE
CREATE OR REPLACE FORCE VIEW "SOUSECRITUREGROUPCOMPTE" ("COMPTE","DEBIT","CREDIT","EXERCICE","ETAT") AS
select
    compte,
    sum(DEBIT) as DEBIT,
    sum(CREDIT) AS CREDIT,
    annee  as exercice,
    etat
from SousEcritureCompteExtrait group by compte, annee, etat
;
