-- [907/1309] ST_ARTICLELIB_PU
CREATE OR REPLACE FORCE VIEW "ST_ARTICLELIB_PU" ("ID","CODE","DESIGNATION","SEUIL","UNITE","PRESENTATION","TYPE","GROUPEE","SOUSGROUPE","CLASSEE","CODEMNEMONIQUE","PUGROS","PUDONATION") AS
select ar.id,
       ar.code,
       ar.designation,
       ar.seuil,
       uni.val as unite,
       ar.presentation,
       ta.VAL        as type,
       ga.VAL        as groupee,
       sga.VAL       as sousgroupe,
       ar.classee,
       ar.codemnemonique,
       ar.PUGROS,
       ar.PUDONATION
from ST_ARTICLE ar
         left join ST_TYPE_ARTICLE ta on ta.id = ar.TYPE
         left join ST_GROUPE_ARTICLE ga on ga.id = ar.GROUPEE
         left join ST_SOUSGROUPE_ARTICLE sga on sga.id = ar.SOUSGROUPE
         left join st_unite uni on ar.UNITE = uni.ID
;
-- [908/1309] ST_ARTICLE_EQUIVALENCE
CREATE OR REPLACE FORCE VIEW "ST_ARTICLE_EQUIVALENCE" ("ID","CODE","DESIGNATION","SEUIL","UNITE","PRESENTATION","TYPE","GROUPEE","SOUSGROUPE","CLASSEE","CODEMNEMONIQUE","PUGROS","PUDONATION","UNITEEQUIVALENCE","QTEEQUIVALENCE") AS
SELECT sa."ID",
       sa."CODE",
       sa."DESIGNATION",
       sa."SEUIL",
       sa."UNITE",
       sa."PRESENTATION",
       sa."TYPE",
       sa."GROUPEE",
       sa."SOUSGROUPE",
       sa."CLASSEE",
       sa."CODEMNEMONIQUE",
       sa."PUGROS",
       sa."PUDONATION",
       ''                         AS uniteEquivalence,
       CAST(0.0 AS NUMBER(38, 2)) as qteEquivalence
FROM ST_ARTICLE sa
;
-- [909/1309] ST_INGREDIENTSAUTO
CREATE OR REPLACE FORCE VIEW "ST_INGREDIENTSAUTO" ("ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT","COMPTE","UNITELIB") AS
SELECT
    ai.ID,ai.LIBELLE,CAST(ai.SEUIL AS NUMBER(10,5)) AS SEUIL ,au.val AS UNITE,CAST(ai.QUANTITEPARPACK AS NUMBER(10,5)) AS QUANTITEPARPACK,CAST(ai.PU AS NUMBER(30,5)) AS PU,ai.ACTIF,ai.PHOTO,ai.CALORIE,ai.DURRE,ai.COMPOSE,ai.CATEGORIEINGREDIENT,ai.IDFOURNISSEUR,ai.DATY,CAST(ai.QTELIMITE AS NUMBER(30,5)) AS QTELIMITE,CAST(ai.PV AS NUMBER(30,5)) AS PV,ai.LIBELLEVENTE,CAST(COALESCE(ai.SEUILMIN,0) AS NUMBER(30,5)) AS SEUILMIN,CAST(COALESCE(ai.SEUILMAX,0) AS NUMBER(30,5)) AS SEUILMAX,CAST(COALESCE(ai.PUACHATUSD,0) AS NUMBER(30,5)) AS PUACHATUSD,CAST(COALESCE(ai.PUACHATEURO,0) AS NUMBER(30,5)) AS PUACHATEURO,CAST(COALESCE(ai.PUACHATAUTREDEVISE,0) AS NUMBER(30,5)) AS PUACHATAUTREDEVISE,CAST(COALESCE(ai.PUVENTEUSD,0) AS NUMBER(30,5)) AS PUVENTEUSD,CAST(COALESCE(ai.PUVENTEEURO,0) AS NUMBER(30,5)) AS PUVENTEEURO,CAST(COALESCE(ai.PUVENTEAUTREDEVISE,0) AS NUMBER(30,5)) AS PUVENTEAUTREDEVISE,ai.ISVENTE,ai.ISACHAT,ai.COMPTE_VENTE,ai.COMPTE_ACHAT,
    CASE
        WHEN ai.COMPTE_VENTE IS NOT NULL THEN ai.COMPTE_VENTE
        ELSE ai.COMPTE_ACHAT
    END AS compte,
    au.VAL AS UNITELIB
FROM AS_INGREDIENTS ai
LEFT JOIN AS_UNITE au  ON au.id = ai.UNITE 
 WHERE ai.actif = 1
;
-- [910/1309] ST_INGREDIENTSAUTOACHAT_CPL
CREATE OR REPLACE FORCE VIEW "ST_INGREDIENTSAUTOACHAT_CPL" ("ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT","COMPTE","TAUX") AS
select st."ID",st."LIBELLE",st."SEUIL",st."UNITE",st."QUANTITEPARPACK",st."PU",st."ACTIF",st."PHOTO",st."CALORIE",st."DURRE",st."COMPOSE",st."CATEGORIEINGREDIENT",st."IDFOURNISSEUR",st."DATY",st."QTELIMITE",st."PV",st."LIBELLEVENTE",st."SEUILMIN",st."SEUILMAX",st."PUACHATUSD",st."PUACHATEURO",st."PUACHATAUTREDEVISE",st."PUVENTEUSD",st."PUVENTEEURO",st."PUVENTEAUTREDEVISE",st."ISVENTE",st."ISACHAT",st."COMPTE_VENTE",st."COMPTE_ACHAT",st."COMPTE", 1 as taux from ST_INGREDIENTSAUTO st
;
-- [911/1309] COMPTA_COMPTE_INGREDIENTS
CREATE OR REPLACE FORCE VIEW "COMPTA_COMPTE_INGREDIENTS" ("ID","COMPTE","LIBELLE","TYPECOMPTE","CLASSY","ANALYTIQUE_OBLI","IDJOURNAL","CODEIMPOT","IDINGREDIENT","LIBELLEINGREDIENT") AS
SELECT
	c.ID,
	c.COMPTE,
	c.LIBELLE,
	c.TYPECOMPTE,
	c.CLASSY,
	c.ANALYTIQUE_OBLI,
	c.IDJOURNAL,
	c.CODEIMPOT,
	si.ID AS idingredient,
	si.LIBELLE AS libelleIngredient
FROM
	COMPTA_COMPTE c
LEFT JOIN ST_INGREDIENTSAUTOACHAT_CPL si ON
	c.COMPTE = si.COMPTE_ACHAT
;
-- [912/1309] ST_INGREDIENTSAUTOCHAMBRE
CREATE OR REPLACE FORCE VIEW "ST_INGREDIENTSAUTOCHAMBRE" ("ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","COMPTE") AS
SELECT ai."ID",ai."LIBELLE",ai."SEUIL",ai."UNITE",ai."QUANTITEPARPACK",ai."PU",ai."ACTIF",ai."PHOTO",ai."CALORIE",ai."DURRE",ai."COMPOSE",ai."CATEGORIEINGREDIENT",ai."IDFOURNISSEUR",ai."DATY",ai."QTELIMITE",ai."PV",ai."LIBELLEVENTE",ai."SEUILMIN", ai.COMPTE_VENTE AS compte
FROM AS_INGREDIENTS ai where ai.pv>0 and ai.CATEGORIEINGREDIENT = 'CAT001'
;
-- [913/1309] ST_INGREDIENTSAUTOSERVICE
CREATE OR REPLACE FORCE VIEW "ST_INGREDIENTSAUTOSERVICE" ("ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT","COMPTE") AS
SELECT
    ai."ID",ai."LIBELLE",ai."SEUIL",ai."UNITE",ai."QUANTITEPARPACK",ai."PU",ai."ACTIF",ai."PHOTO",ai."CALORIE",ai."DURRE",ai."COMPOSE",ai."CATEGORIEINGREDIENT",ai."IDFOURNISSEUR",ai."DATY",ai."QTELIMITE",ai."PV",ai."LIBELLEVENTE",ai."SEUILMIN",ai."SEUILMAX",ai."PUACHATUSD",ai."PUACHATEURO",ai."PUACHATAUTREDEVISE",ai."PUVENTEUSD",ai."PUVENTEEURO",ai."PUVENTEAUTREDEVISE",ai."ISVENTE",ai."ISACHAT",ai."COMPTE_VENTE",ai."COMPTE_ACHAT",
    CASE
        WHEN ai.COMPTE_VENTE IS NOT NULL THEN ai.COMPTE_VENTE
        ELSE ai.COMPTE_ACHAT
    END AS compte
FROM AS_INGREDIENTS ai where ai.pv>0
and CATEGORIEINGREDIENT='CAT002'
;
-- [914/1309] ST_INGREDIENTSAUTOVENTE
CREATE OR REPLACE FORCE VIEW "ST_INGREDIENTSAUTOVENTE" ("ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT","TVA","COMPTE") AS
SELECT
    ai."ID",ai."LIBELLE",ai."SEUIL",ai."UNITE",ai."QUANTITEPARPACK",ai."PU",ai."ACTIF",ai."PHOTO",ai."CALORIE",ai."DURRE",ai."COMPOSE",ai."CATEGORIEINGREDIENT",ai."IDFOURNISSEUR",ai."DATY",ai."QTELIMITE",ai."PV",ai."LIBELLEVENTE",ai."SEUILMIN",ai."SEUILMAX",ai."PUACHATUSD",ai."PUACHATEURO",ai."PUACHATAUTREDEVISE",ai."PUVENTEUSD",ai."PUVENTEEURO",ai."PUVENTEAUTREDEVISE",ai."ISVENTE",ai."ISACHAT",ai."COMPTE_VENTE",ai."COMPTE_ACHAT", ai.TVA,
 ai.COMPTE_VENTE AS compte
FROM AS_INGREDIENTS ai where ai.pv>0
;
-- [915/1309] ST_INGREDIENTSVENTEPOS
CREATE OR REPLACE FORCE VIEW "ST_INGREDIENTSVENTEPOS" ("ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT","TVA","TAUX","COMPTE","LIBELLECOMPOSANT","COULEUR","TAILLE","CODEBARRE","REFERENCE","CODEGROS","PVGROS","UNITELIB","DESIGNATION","TYPESTOCK") AS
SELECT
    ai.ID,
    ai.LIBELLE as libelle,
    ai.SEUIL,
    ai.UNITE,
    ai.QUANTITEPARPACK,
    ai.PU,
    ai.ACTIF,
    ai.PHOTO,
    ai.CALORIE,
    ai.DURRE,
    ai.COMPOSE,
    ai.CATEGORIEINGREDIENT,
    ai.IDFOURNISSEUR,
    ai.DATY,
    ai.QTELIMITE,
    ai.PV,
    ai.LIBELLEVENTE,
    ai.SEUILMIN,
    ai.SEUILMAX,
    ai.PUACHATUSD,
    ai.PUACHATEURO,
    ai.PUACHATAUTREDEVISE,
    ai.PUVENTEUSD,
    ai.PUVENTEEURO,
    ai.PUVENTEAUTREDEVISE,
    ai.ISVENTE,
    ai.ISACHAT,
    ai.COMPTE_VENTE,
    ai.COMPTE_ACHAT,
    ai.TVA,
    1 AS taux,
    ai.COMPTE_VENTE AS compte,
    ai.LIBELLE || ' ' || ai.COULEUR || ' ' || ai.TAILLE AS libellecomposant,
    ai.COULEUR,
    ai.TAILLE,
    ai.codebarre,
    ai.REFERENCE,
    ai.codegros,
    ai.pvgros,
    u.VAL AS UNITELIB,
    CONCAT(concat(ai.libelle,' - '),u.val) AS designation,
    ai.TYPESTOCK
FROM
    AS_INGREDIENTS ai
        LEFT JOIN AS_RECETTE ar ON ar.IDPRODUITS = ai.ID
        LEFT JOIN AS_INGREDIENTS cps ON cps.ID  = ar.IDINGREDIENTS
        LEFT JOIN AS_UNITE u ON ai.unite=u.id
where AI.PV != 0 AND ai.ACTIF = 1
GROUP BY
    ai.ID,
    ai.LIBELLE,
    ai.SEUIL,
    ai.UNITE,
    ai.QUANTITEPARPACK,
    ai.PU,
    ai.ACTIF,
    ai.PHOTO,
    ai.CALORIE,
    ai.DURRE,
    ai.COMPOSE,
    ai.CATEGORIEINGREDIENT,
    ai.IDFOURNISSEUR,
    ai.DATY,
    ai.QTELIMITE,
    ai.PV,
    ai.LIBELLEVENTE,
    ai.SEUILMIN,
    ai.SEUILMAX,
    ai.PUACHATUSD,
    ai.PUACHATEURO,
    ai.PUACHATAUTREDEVISE,
    ai.PUVENTEUSD,
    ai.PUVENTEEURO,
    ai.PUVENTEAUTREDEVISE,
    ai.ISVENTE,
    ai.ISACHAT,
    ai.COMPTE_VENTE,
    ai.COMPTE_ACHAT,
    ai.TVA,
    ai.COULEUR,
    ai.TAILLE,
    ai.REFERENCE,
    ai.codebarre,
    u.val,
    ai.codegros,
    ai.pvgros,
    ai.TYPESTOCK
;
-- [916/1309] ST_INGREDIENTSVENTEPOS_REM
CREATE OR REPLACE FORCE VIEW "ST_INGREDIENTSVENTEPOS_REM" ("ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT","TVA","TAUX","COMPTE","LIBELLECOMPOSANT","COULEUR","TAILLE","CODEBARRE","REFERENCE","CODEGROS","PVGROS","UNITELIB","DESIGNATION","REMISE","PVREMISE","IDCATEGORIECLIENT","IDPOINT","IDREMISEFILLE","IDREMISE","REMISENOM","DATYREMISE","DATEDEBUTREMISE","DATEFINREMISE","TYPESTOCK") AS
SELECT
    ai.ID,
    ai.LIBELLE AS libelle,
    ai.SEUIL,
    ai.UNITE,
    ai.QUANTITEPARPACK,
    ai.PU,
    ai.ACTIF,
    ai.PHOTO,
    ai.CALORIE,
    ai.DURRE,
    ai.COMPOSE,
    ai.CATEGORIEINGREDIENT,
    ai.IDFOURNISSEUR,
    ai.DATY,
    ai.QTELIMITE,
    ai.PV,
    ai.LIBELLEVENTE,
    ai.SEUILMIN,
    ai.SEUILMAX,
    ai.PUACHATUSD,
    ai.PUACHATEURO,
    ai.PUACHATAUTREDEVISE,
    ai.PUVENTEUSD,
    ai.PUVENTEEURO,
    ai.PUVENTEAUTREDEVISE,
    ai.ISVENTE,
    ai.ISACHAT,
    ai.COMPTE_VENTE,
    ai.COMPTE_ACHAT,
    ai.TVA,
    1 AS taux,
    ai.COMPTE_VENTE AS compte,
    ai.LIBELLE || ' ' || ai.COULEUR || ' ' || ai.TAILLE AS libellecomposant,
    ai.COULEUR,
    ai.TAILLE,
    ai.codebarre,
    ai.REFERENCE,
    ai.codegros,
    ai.pvgros,
    u.VAL AS UNITELIB,
    CONCAT(CONCAT(ai.libelle, ' - '), u.val) AS designation,

    rfmv.remise,
    ai.PV - (ai.PV * NVL(rfmv.remise, 0) / 100) AS pvRemise,

    rfmv.IDCATEGORIECLIENT,
    rfmv.IDPOINT,
    rfmv.id AS idRemiseFille,
    rfmv.idRemise,
    rfmv.nom AS RemiseNom,
    rfmv.daty AS datyRemise,
    rfmv.DATEDEBUT AS datedebutRemise,
    rfmv.DATEFIN AS datefinRemise,
    ai.TYPESTOCK

FROM AS_INGREDIENTS ai

         LEFT JOIN AS_RECETTE ar
                   ON ar.IDPRODUITS = ai.ID

         LEFT JOIN AS_INGREDIENTS cps
                   ON cps.ID = ar.IDINGREDIENTS

         LEFT JOIN AS_UNITE u
                   ON ai.unite = u.id

         LEFT JOIN remiseFilleMereVise rfmv
                   ON (
                       rfmv.CATEGORIEPRODUIT = ai.CATEGORIEINGREDIENT
                           OR rfmv.idproduit = ai.id
                       )

WHERE ai.PV != 0
AND ai.ACTIF = 1
GROUP BY
    ai.ID,
    ai.LIBELLE,
    ai.SEUIL,
    ai.UNITE,
    ai.QUANTITEPARPACK,
    ai.PU,
    ai.ACTIF,
    ai.PHOTO,
    ai.CALORIE,
    ai.DURRE,
    ai.COMPOSE,
    ai.CATEGORIEINGREDIENT,
    ai.IDFOURNISSEUR,
    ai.DATY,
    ai.QTELIMITE,
    ai.PV,
    ai.LIBELLEVENTE,
    ai.SEUILMIN,
    ai.SEUILMAX,
    ai.PUACHATUSD,
    ai.PUACHATEURO,
    ai.PUACHATAUTREDEVISE,
    ai.PUVENTEUSD,
    ai.PUVENTEEURO,
    ai.PUVENTEAUTREDEVISE,
    ai.ISVENTE,
    ai.ISACHAT,
    ai.COMPTE_VENTE,
    ai.COMPTE_ACHAT,
    ai.TVA,
    ai.COULEUR,
    ai.TAILLE,
    ai.REFERENCE,
    ai.codebarre,
    u.VAL,
    ai.codegros,
    ai.pvgros,
    rfmv.remise,
    rfmv.IDCATEGORIECLIENT,
    rfmv.IDPOINT,
    rfmv.id,
    rfmv.idRemise,
    rfmv.nom,
    rfmv.daty,
    rfmv.DATEDEBUT,
    rfmv.DATEFIN,
    ai.TYPESTOCK
;
-- [917/1309] SUIVICHAMBREFROIDEDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "SUIVICHAMBREFROIDEDETAIL_LIB" ("ID","IDMERE","IDRESPONSABLE","HEURE","TEMPERATURE","HUMIDITE","REMARQUE","IDRESPONSABLELIB") AS
SELECT
	scfd.id,
	scfd.idmere,
	scfd.idresponsable,
	scfd.heure,
	scfd.temperature,
	scfd.humidite,
	scfd.remarque,
	lp.NOM || ' ' || lp.PRENOM AS idResponsableLib
FROM 
  suiviChambreFroideDetail scfd
LEFT JOIN LOG_PERSONNEL lp ON scfd.idresponsable = lp.ID
;
-- [918/1309] SUIVICHAMBREFROIDE_LIB
CREATE OR REPLACE FORCE VIEW "SUIVICHAMBREFROIDE_LIB" ("ID","DATY","IDSALLESTOCKAGEOEUF","IDSALLESTOCKAGEOEUFLIB","ETAT","ETATLIB") AS
SELECT 
	sqf.id,
	sqf.daty,
	sqf.IDSALLESTOCKAGEOEUF,
	m.VAL AS idSalleStockageOeufLib,
	sqf.etat,
    CASE
        WHEN sqf.etat = 1 THEN 'CREE'
        WHEN sqf.etat = 0 THEN 'ANNULEE'
        WHEN sqf.etat = 11 THEN 'VISEE'
    END AS etatLib
FROM
	suiviChambreFroide sqf
LEFT JOIN MAGASIN2 m ON sqf.IDSALLESTOCKAGEOEUF = m.ID
;
-- [919/1309] SUIVIJOURNALIERDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "SUIVIJOURNALIERDETAIL_LIB" ("ID","IDMERE","IDBATIMENT","IDPARQUET","AGEJOUR","ENTREE","TRI","MORTALITE","CULLS","CONSIGNESURALIMENT","EAU","TEMPERATUREMIN","TEMPERATUREMAX","IDBATIMENTLIB","IDPARQUETLIB") AS
SELECT d."ID",d."IDMERE",d."IDBATIMENT",d."IDPARQUET",d."AGEJOUR",d."ENTREE",d."TRI",d."MORTALITE",d."CULLS",d."CONSIGNESURALIMENT",d."EAU",d."TEMPERATUREMIN",d."TEMPERATUREMAX",
       b."NOMBATIMENT" AS "IDBATIMENTLIB",
       p."VAL" AS "IDPARQUETLIB"
FROM "SUIVIJOURNALIERDETAIL" d
LEFT JOIN "BATIMENT" b ON b."ID" = d."IDBATIMENT"
LEFT JOIN "PARQUET" p ON p."ID" = d."IDPARQUET"
;
-- [920/1309] SUIVIJOURNALIER_LIB
CREATE OR REPLACE FORCE VIEW "SUIVIJOURNALIER_LIB" ("ID","DATY","IDFERME","IDLOT","IDFERMELIB","IDLOTLIB","IDSOUCHELIB","ETAT","ETATLIB") AS
SELECT s.ID,s.DATY,s.IDFERME,s.IDLOT,
       m.VAL    AS IDFERMELIB,
       l.NOMLOT AS IDLOTLIB,
       so.val AS idsouchelib,
       s.ETAT AS ETAT,
       CASE s.ETAT
           WHEN 1  THEN 'CREE'
           WHEN 11 THEN 'VALIDE'
           WHEN 0  THEN 'ANULLE'
           END AS ETATLIB
FROM SUIVIJOURNALIER s
         LEFT JOIN MAGASIN2 m ON m.ID = s.IDFERME
         LEFT JOIN LOT l ON l.ID = s.IDLOT
         LEFT JOIN SOUCHE so ON so.id=l.idsouche
;
-- [921/1309] SUIVI_PRESENCE_FILLE_LIB
CREATE OR REPLACE FORCE VIEW "SUIVI_PRESENCE_FILLE_LIB" ("ID","IDSUIVIPRESENCEMERE","IDPARTICIPATIONFORMATION","IDPERSONNEL","IDACTIONFORMATION","DATESEANCE","PRESENCE","NBHEUREEFFECTUE","PERSONNELLIB","MATRICULE","CATEGORIEEMPLOYE","ACTIONFORMATIONLIB") AS
SELECT
    spf.ID,spf.IDSUIVIPRESENCEMERE,spf.IDPARTICIPATIONFORMATION,spf.IDPERSONNEL,spf.IDACTIONFORMATION,spf.DATESEANCE,spf.PRESENCE,spf.NBHEUREEFFECTUE,
    lp.nom || ' ' || lp.prenom AS personnelLib,
    pip.matricule,
    cp.val AS categorieEmploye,
    af.intitule AS actionFormationLib
FROM SUIVI_PRESENCE_FILLE spf
         LEFT JOIN LOG_PERSONNEL lp
                   ON lp.id = spf.idpersonnel
         LEFT JOIN PAIE_INFO_PERSONNEL pip
                   ON pip.id = spf.idpersonnel
         LEFT JOIN CATEGORIE_PAIE cp
                   ON pip.idcategorie_paie = cp.id
         LEFT JOIN ACTION_FORMATION af
                   ON af.id = spf.idactionformation
;
-- [922/1309] SUIVI_PRESENCE_MERE_LIB
CREATE OR REPLACE FORCE VIEW "SUIVI_PRESENCE_MERE_LIB" ("ID","IDSESSIONFORMATION","SESSIONFORMATIONLIB","DATY","ACTIONFORMATIONLIB") AS
SELECT
    spm.ID,spm.IDSESSIONFORMATION,
    sf.remarque AS sessionFormationLib,
    spm.DATY,
    af.intitule AS actionFormationLib
FROM SUIVI_PRESENCE_MERE spm
         LEFT JOIN SESSION_FORMATION sf
                   ON sf.id = spm.idsessionformation
         LEFT JOIN ACTION_FORMATION af
                   ON af.id = sf.idactionformation
;
-- [923/1309] SUM_HS_DAY
CREATE OR REPLACE FORCE VIEW "SUM_HS_DAY" ("JOUR","AVG_HS_PER_DAY","IDDEPARTEMENT","DEPARTEMENTLIB") AS
SELECT
    dateFabrication AS jour,
    SUM(HS) AS avg_hs_per_day,
    IDDEPARTEMENT,
    departementLib
FROM HEURESUPFABRICATION_CPL
GROUP BY dateFabrication, IDDEPARTEMENT, departementLib
ORDER BY dateFabrication
;
-- [924/1309] SUM_HS_MONTH
CREATE OR REPLACE FORCE VIEW "SUM_HS_MONTH" ("ANNEE","MOIS","AVG_HS_PER_MONTH","IDDEPARTEMENT","DEPARTEMENTLIB") AS
SELECT
    EXTRACT(YEAR FROM dateFabrication) AS annee,
    EXTRACT(MONTH FROM dateFabrication) AS mois,
    SUM(HS) AS avg_hs_per_month,
    IDDEPARTEMENT,
    departementLib
FROM HEURESUPFABRICATION_CPL
GROUP BY
    EXTRACT(YEAR FROM dateFabrication),
    EXTRACT(MONTH FROM dateFabrication),
    IDDEPARTEMENT,
    departementLib
ORDER BY annee, mois
;
-- [925/1309] SUM_HS_MONTH_LIB
CREATE OR REPLACE FORCE VIEW "SUM_HS_MONTH_LIB" ("ANNEE","MOIS","MONTHLIB","AVG_HS_PER_MONTH","IDDEPARTEMENT","DEPARTEMENTLIB") AS
SELECT
    EXTRACT(YEAR FROM dateFabrication) AS annee,
    EXTRACT(MONTH FROM dateFabrication) AS mois,
    TO_CHAR(dateFabrication, 'Month YYYY', 'NLS_DATE_LANGUAGE=FRENCH') AS monthLib,
    SUM(HS) AS avg_hs_per_month,
    IDDEPARTEMENT,
    departementLib
FROM HEURESUPFABRICATION_CPL
GROUP BY
    EXTRACT(YEAR FROM dateFabrication),
    EXTRACT(MONTH FROM dateFabrication),
    TO_CHAR(dateFabrication, 'Month YYYY', 'NLS_DATE_LANGUAGE=FRENCH'),
    IDDEPARTEMENT,
    departementLib
ORDER BY
    annee,
    mois
;
-- [926/1309] SUM_HS_YEAR
CREATE OR REPLACE FORCE VIEW "SUM_HS_YEAR" ("ANNEE","AVG_HS_PER_YEAR","IDDEPARTEMENT","DEPARTEMENTLIB") AS
SELECT
    EXTRACT(YEAR FROM dateFabrication) AS annee,
    SUM(HS) AS avg_hs_per_year,
    IDDEPARTEMENT,
    departementLib
FROM HEURESUPFABRICATION_CPL
GROUP BY EXTRACT(YEAR FROM dateFabrication),IDDEPARTEMENT,
         departementLib
ORDER BY annee
;
-- [927/1309] TABLEAUBORDBC
CREATE OR REPLACE FORCE VIEW "TABLEAUBORDBC" ("PRODUIT","MONTANT","PU","QUANTITE","REMISE","TVA","UNITE","QTEOF","QTEOFRESTANTE","QTEFAB","QTEFABRESTANTE","QTELIVRE","QTENONLIVRE","LIBELLEPRODUIT","DATY") AS
SELECT
 	bcf.PRODUIT,
    CAST(avg(bcf.MONTANT) AS NUMBER(30,5))  as montant,
    CAST(avg(bcf.PU) AS NUMBER(30,5)) as pu,
    CAST(avg(bcf.QUANTITE) AS NUMBER(20,5)) as quantite,
    CAST(avg(bcf.REMISE) AS NUMBER(30,5)) as remise,
    CAST(avg(bcf.TVA) AS NUMBER(30,5)) as tva,
    ing.UNITE as unite,
    CAST(nvl(avg(o.QTE),0) AS NUMBER(20,5)) AS QTEOF,
    CAST(NVL(sum(bcf.QUANTITE) - nvl(avg(o.QTE),0), 0) AS NUMBER(20,5)) AS QTEOFRESTANTE,

    CAST(nvl(avg(f.QTE),0) AS NUMBER(20,5)) AS QTEFAB,
    CAST(NVL(sum(bcf.QUANTITE) - nvl(avg(f.QTE),0), 0) AS NUMBER(20,5)) AS QTEFABRESTANTE,

    CAST(AVG(NVL(abcf.QUANTITE, 0)) AS NUMBER(20,5)) AS QTELIVRE,
	CAST(NVL(avg(bcf.QUANTITE) - AVG(NVL(abcf.QUANTITE,0)), 0) AS NUMBER(20,5)) AS QTENONLIVRE,
	ing.LIBELLE as libelleProduit,
	bc.DATY 

FROM BONDECOMMANDE_CLIENT_FILLE bcf

LEFT JOIN BONDECOMMANDE_CLIENT bc ON bc.ID = bcf.IDBC 

LEFT JOIN OfGroupByIdbc o ON o.IDBCFILLE = bcf.ID


LEFT JOIN fabrGroupByIdbc f ON f.IDBCFILLE = bcf.ID

LEFT JOIN BLGroupByIdbc abcf ON abcf.IDBC_FILLE = bcf.ID

left join AS_INGREDIENTS ing on ing.id=bcf.PRODUIT

GROUP BY
    bcf.PRODUIT,
    ing.LIBELLE, ing.UNITE,bc.DATY
;
-- [928/1309] TARIF_INGREDIENTS_LIB
CREATE OR REPLACE FORCE VIEW "TARIF_INGREDIENTS_LIB" ("ID","IDTYPECLIENT","IDINGREDIENT","DATY","PRIXUNITAIRE","IDTYPECLIENTLIB","IDINGREDIENTLIB","UNITE","UNITELIB","MOTSCLESSS") AS
SELECT TI.ID,
       TI.IDTYPECLIENT,
       TI.IDINGREDIENT,
       TI.DATY,
       TI.PRIXUNITAIRE,
       T.VAL      AS IDTYPECLIENTLIB,
       AI.LIBELLE AS IDINGREDIENTLIB,
       TI.UNITE,
       U.VAL      AS UNITELIB,
       (
           TI.ID || ' | ' || T.VAL || ' | ' || AI.LIBELLE || ' | ' || U.VAL
           )      AS MOTSCLESSS
FROM TARIF_INGREDIENTS TI
         LEFT JOIN TYPECLIENT T
                   ON TI.IDTYPECLIENT = T.ID
         LEFT JOIN AS_INGREDIENTS AI
                   ON TI.IDINGREDIENT = AI.ID
         LEFT JOIN AS_UNITE U
                   ON U.ID = TI.UNITE
;
-- [929/1309] TARIF_INGREDIENTS_MAX
CREATE OR REPLACE FORCE VIEW "TARIF_INGREDIENTS_MAX" ("IDINGREDIENT","UNITE","IDTYPECLIENT","PRIXUNITAIRE","DATY","IDMAGASIN") AS
WITH ranked_tarifs AS (
    SELECT
        IDINGREDIENT,
        UNITE,
        IDTYPECLIENT,
        CAST(PRIXUNITAIRE AS NUMBER(30,5)) AS PRIXUNITAIRE,
        DATY,
        IDMAGASIN,
        ROW_NUMBER() OVER (PARTITION BY IDINGREDIENT, UNITE, IDTYPECLIENT, IDMAGASIN ORDER BY DATY DESC) as rn
    FROM TARIF_INGREDIENTS
)
SELECT
    IDINGREDIENT,
    UNITE,
    IDTYPECLIENT,
    PRIXUNITAIRE,
    DATY,
    IDMAGASIN
FROM ranked_tarifs
WHERE rn = 1
;
-- [930/1309] AS_INGREDIENT_VENTE_LIB
CREATE OR REPLACE FORCE VIEW "AS_INGREDIENT_VENTE_LIB" ("ID","LIBELLE","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","CATEGORIEINGREDIENT","IDFOURNISSEUR","DATY","QTELIMITE","PV","LIBELLEVENTE","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","ISVENTE","ISACHAT","COMPTE_VENTE","COMPTE_ACHAT","LIBELLEEXTACTE","TVA","FILEPATH","RESTE","TYPESTOCK","REFPOST","REFQUALIFICATION","IDCHAMBRE","ISPERISHABLE","PV2","IDMAGASIN","PRIXUNITAIRE","IDTYPECLIENT","IDTYPECLIENTLIB","IDUNITE","IDUNITELIB","POIDS","QUANTITE","TARIFMAGASIN","UNITE2") AS
select ing.ID,
	       --concat(concat(ing.LIBELLE, ' '), ing.PARFUMS) as LIBELLE,
  	   nvl(ing.LIBELLEVENTE, ing.libelle) as LIBELLE,
       CAST(ing.SEUIL AS NUMBER(10,5)) AS  SEUIL,
       ing.UNITE,
       CAST(ing.QUANTITEPARPACK AS NUMBER(10,5)) AS QUANTITEPARPACK ,
       CAST(ing.PU AS NUMBER(30,5)) AS PU,
       ing.ACTIF,
       ing.PHOTO,
       ing.CALORIE,
       ing.DURRE,
       ing.COMPOSE,
       ing.CATEGORIEINGREDIENT,
       ing.IDFOURNISSEUR,
       ing.DATY,
       CAST(ing.QTELIMITE AS NUMBER(30,5)) AS QTELIMITE,
       CAST(ing.PV AS NUMBER(30,5)) AS PV,
       ing.LIBELLEVENTE,
       CAST(COALESCE(ing.SEUILMIN,0) AS NUMBER(30,5)) AS SEUILMIN,
       CAST(COALESCE(ing.SEUILMAX,0) AS NUMBER(30,5)) AS SEUILMAX,
       CAST(COALESCE(ing.PUACHATUSD,0) AS NUMBER(30,5)) AS PUACHATUSD,
       CAST(COALESCE(ing.PUACHATEURO,0) AS NUMBER(30,5)) AS PUACHATEURO,
       CAST(COALESCE(ing.PUACHATAUTREDEVISE,0) AS NUMBER(30,5)) AS PUACHATAUTREDEVISE,
       CAST(COALESCE(ing.PUVENTEUSD,0) AS NUMBER(30,5)) AS PUVENTEUSD,
       CAST(COALESCE(ing.PUVENTEEURO,0) AS NUMBER(30,5)) AS PUVENTEEURO,
       CAST(COALESCE(ing.PUVENTEAUTREDEVISE,0) AS NUMBER(30,5)) AS PUVENTEAUTREDEVISE,
       ing.ISVENTE,
       ing.ISACHAT,
       ing.COMPTE_VENTE,
       ing.COMPTE_ACHAT,
       ing.LIBELLEEXTACTE,
       CAST(ing.TVA AS NUMBER(10,5)) AS TVA,
       ing.FILEPATH,
       CAST(ing.RESTE AS NUMBER(20,5)) AS RESTE,
       ing.TYPESTOCK,
       ing.REFPOST,
       ing.REFQUALIFICATION,
       ing.IDCHAMBRE,
       ing.ISPERISHABLE,
       ing.PV2,
       ing.IDMAGASIN,
       CAST(nvl(ting.PRIXUNITAIRE,ing.PV)  AS NUMBER(30,5)) AS PRIXUNITAIRE,
       tc.ID as IDTYPECLIENT,
       tc.VAL as idtypeclientlib,
       nvl(un.id,un2.id) as idunite,
       nvl(un.VAL,un2.val) as idunitelib,
       CAST(eq.POIDS  AS NUMBER(30,5)) AS POIDS,
       CAST(eq.QUANTITE AS NUMBER(20,5)) AS QUANTITE,
       ting.IDMAGASIN as TARIFMAGASIN,
       nvl(un.VAL,un2.val) as UNITE2
from AS_INGREDIENTS ing
         cross join TYPECLIENT tc
         left join TARIF_INGREDIENTS_MAX ting on ing.ID = TING.IDINGREDIENT AND ting.IDTYPECLIENT=tc.id
         left join AS_UNITE un on un.ID = TING.UNITE
         left join AS_UNITE un2 on un2.ID = ing.UNITE
         left join EQUIVALENCEVENTE eq on eq.IDPRODUIT2 = ting.IDINGREDIENT
WHERE ing.ISVENTE = 1 AND ing.ACTIF=1
;
-- [931/1309] TARIF_INGREDIENTS_MAX_DATE_MN
CREATE OR REPLACE FORCE VIEW "TARIF_INGREDIENTS_MAX_DATE_MN" ("IDINGREDIENT","UNITE","IDTYPECLIENT","DATY","IDMAGASIN") AS
