-- [932/1309] TARIF_INGREDIENTS_MAX_DATE_MNN
CREATE OR REPLACE FORCE VIEW "TARIF_INGREDIENTS_MAX_DATE_MNN" ("IDINGREDIENT","UNITE","IDTYPECLIENT","DATY","IDMAGASIN") AS
select IDINGREDIENT, UNITE, IDTYPECLIENT, max(DATY) as daty, IDMAGASIN
