-- [933/1309] TARIF_INGREDIENTS_MAX_LIB
CREATE OR REPLACE FORCE VIEW "TARIF_INGREDIENTS_MAX_LIB" ("IDTYPECLIENT","IDINGREDIENT","DATY","PRIXUNITAIRE","IDTYPECLIENTLIB","IDINGREDIENTLIB","UNITE","UNITELIB") AS
SELECT
    ti."IDTYPECLIENT",ti."IDINGREDIENT",ti."DATY",ti."PRIXUNITAIRE" ,
    t.VAL AS idtypeclientlib,
    ai.LIBELLE AS idingredientlib,
    ti.UNITE,
    u.VAL as unitelib
FROM TARIF_INGREDIENTS_MAX ti
         LEFT JOIN TYPECLIENT t
                   ON ti.IDTYPECLIENT = t.ID
         LEFT JOIN AS_INGREDIENTS ai
                   ON ti.IDINGREDIENT = ai.ID
         left join AS_UNITE u on u.id=ti.UNITE
;
-- [934/1309] TARIF_INGREDIENTS_MAX_MN
CREATE OR REPLACE FORCE VIEW "TARIF_INGREDIENTS_MAX_MN" ("IDINGREDIENT","UNITE","IDTYPECLIENT","DATY","IDMAGASIN","PRIXUNITAIRE") AS
select timd."IDINGREDIENT",timd."UNITE",timd."IDTYPECLIENT",timd."DATY",timd."IDMAGASIN", ti.PRIXUNITAIRE
from TARIF_INGREDIENTS_MAX_date_mn timd
         left join (select * from TARIF_INGREDIENTS where idmagasin is null) ti
              on ti.DATY = timd.daty and timd.IDINGREDIENT = ti.IDINGREDIENT and timd.UNITE = ti.UNITE and timd.IDTYPECLIENT = ti.IDTYPECLIENT
;
-- [935/1309] TARIF_INGREDIENTS_MAX_MNN
CREATE OR REPLACE FORCE VIEW "TARIF_INGREDIENTS_MAX_MNN" ("IDINGREDIENT","UNITE","IDTYPECLIENT","DATY","IDMAGASIN","PRIXUNITAIRE") AS
select timd."IDINGREDIENT",timd."UNITE",timd."IDTYPECLIENT",timd."DATY",timd."IDMAGASIN", ti.PRIXUNITAIRE
from TARIF_INGREDIENTS_MAX_date_mnn timd
         left join (select * from TARIF_INGREDIENTS where idmagasin is not null) ti
              on ti.DATY = timd.daty and timd.IDINGREDIENT = ti.IDINGREDIENT and timd.UNITE = ti.UNITE and ti.idmagasin = timd.idmagasin and timd.IDTYPECLIENT = ti.IDTYPECLIENT
;
-- [936/1309] TAUXABSENTEISME
CREATE OR REPLACE FORCE VIEW "TAUXABSENTEISME" ("HEURETHEORIQUE","HEUREABSENCE","MOIS","ANNEE","TAUXABSENCE","MOISLIB","IDDIRECTION") AS
SELECT
    CAST(nb.NBPERSONNELVALIDE * 173.33 AS NUMBER(30, 2)) AS heuretheorique,
    CAST(NVL(SUM(p.ABSENCE), 0) AS NUMBER(30, 2)) AS heureabsence,
    p.mois,
    p.ANNEE,
    CAST(
            ROUND(
                    (NVL(SUM(p.ABSENCE), 0) / (nb.NBPERSONNELVALIDE * 173.33)) * 100,
                    2
            ) AS NUMBER(30, 2)
    ) AS tauxAbsence,
    TO_CHAR(
            TO_DATE(TO_CHAR(p.mois, 'FM00'), 'MM'),
            'FMMonth',
            'NLS_DATE_LANGUAGE=FRENCH'
    ) AS moisLib,
    p.DIRECTION AS iddirection
FROM
    POINTAGE p,
    NB_PERS_VALIDE nb
GROUP BY
    nb.NBPERSONNELVALIDE, p.mois, p.ANNEE, p.DIRECTION
;
-- [937/1309] TAUXDECHANGE_MAXDATY
CREATE OR REPLACE FORCE VIEW "TAUXDECHANGE_MAXDATY" ("IDDEVISE","TAUX") AS
SELECT 
  tc.IDDEVISE,
  tc.TAUX
FROM
(SELECT
IDDEVISE,
max(DATY) AS  DATY
FROM TAUXDECHANGE
GROUP BY
IDDEVISE) t1 
JOIN 
TAUXDECHANGE tc 
ON t1.idDevise = tc.IDDEVISE AND t1.daty = tc.daty
;
-- [938/1309] BONDECOMMANDE_CLIENTF_TAUX
CREATE OR REPLACE FORCE VIEW "BONDECOMMANDE_CLIENTF_TAUX" ("ID","PRODUIT","IDBC","QUANTITE","PU","MONTANT","TVA","REMISE","IDDEVISE","UNITE","TAUX") AS
SELECT bcc.ID,bcc.PRODUIT,bcc.IDBC,bcc.QUANTITE,bcc.PU,bcc.MONTANT,bcc.TVA,bcc.REMISE,bcc.IDDEVISE,bcc.UNITE, CASE WHEN 
  bcc.iddevise = 'AR' THEN 1 ELSE 
  tm.taux
  END AS taux 
  FROM BONDECOMMANDE_CLIENT_FILLE bcc,TAUXDECHANGE_MAXDATY tm 
  WHERE bcc.IDDEVISE = tm.IDDEVISE (+)
;
-- [939/1309] PRODUIT_ACHAT_LIB_EURO
CREATE OR REPLACE FORCE VIEW "PRODUIT_ACHAT_LIB_EURO" ("ID","VAL","DESCE","IDTYPEPRODUIT","IDTYPEPRODUITLIB","PUACHAT","PUVENTE","IDUNITE","IDUNITELIB","IDCATEGORIE","IDCATEGORIELIB","IDSOUSCATEGORIELIB","SEUILMIN","SEUILMAX","PUACHATUSD","PUACHATEURO","PUACHATAUTREDEVISE","PUVENTEUSD","PUVENTEEURO","PUVENTEAUTREDEVISE","TAUX","ISVENTE","COMPTE") AS
SELECT 
 pl.ID,
       pl.VAL,
       pl.DESCE,
       pl.IDTYPEPRODUIT,
       pl.IDTYPEPRODUITLIB,
       nvl(pl.puAchatUsd * t.TAUX,0)  AS PUACHAT,
       nvl(pl.puVenteUsd,0) AS PUVENTE,
       pl.IDUNITE,
       pl.IDUNITELIB,
       pl.IDCATEGORIE,
       pl.IDCATEGORIELIB,
       pl.IDSOUSCATEGORIELIB,
       pl.seuilmin,
       pl.seuilmax,
       pl.puAchatUsd,
  	   pl.puAchatEuro,
	   pl.puAchatAutreDevise,
	   pl.puVenteUsd,
	   pl.puVenteEuro,
	   pl.puVenteAutreDevise,
	   t.TAUX AS taux,
	   pl.isvente,
	   pl.compte_achat AS compte
FROM PRODUIT_LIB pl ,TAUXDECHANGE_MAXDATY t
WHERE t.IDDEVISE = 'EUR' AND pl.isAchat =1
;
