-- [945/1309] TEMPSMOYENPANNES
CREATE OR REPLACE FORCE VIEW "TEMPSMOYENPANNES" ("IDMACHINE","NOMMACHINE","IDTRAVAUX","DATY","ECART_JOURS") AS
WITH ECARTS AS (
        SELECT
            CASE
                WHEN ai.id IS NULL THEN aim.id
                ELSE ai.id
            END AS idMachine,
            CASE
                WHEN ai.libelle IS NULL THEN aim.descriptionObjet
                ELSE ai.libelle
            END AS nomMachine,
            t.ID AS IDTRAVAUX,
            t.DATY,
            NVL(
                t.DATY - LAG(t.DATY) OVER (PARTITION BY o.IDINGREDIENTS ORDER BY t.DATY),
                0
            ) AS ECART_JOURS
        FROM TRAVAUX t
        LEFT JOIN ORDRETRAVAUXFILLE o
            ON t.IDOFFILLE = o.ID
        LEFT JOIN as_ingredients ai
            ON o.IDINGREDIENTS = ai.id
        LEFT JOIN AS_INGREDIENT_MAINTENANCE aim
            ON o.IDINGREDIENTS = aim.id
    )
SELECT "IDMACHINE","NOMMACHINE","IDTRAVAUX","DATY","ECART_JOURS"
FROM ECARTS
;
-- [946/1309] MOYENNEPANNESTRAVAUX
CREATE OR REPLACE FORCE VIEW "MOYENNEPANNESTRAVAUX" ("IDMACHINE","NOMMACHINE","ECARTJOURS") AS
SELECT
    idMachine,
    nomMachine,
    cast (ROUND(AVG(ECART_JOURS), 2) as number(10,2)) AS ECARTJOURS
FROM TempsMoyenPannes
WHERE ECART_JOURS IS NOT NULL
GROUP BY idMachine, nomMachine
;
-- [947/1309] TEMPSOUVERTURELIB
CREATE OR REPLACE FORCE VIEW "TEMPSOUVERTURELIB" ("ID","IDMACHINE","TEMPS","CAPACITE","IDUNITE","IDMACHINELIB","IDUNITELIB","MOTSCLESSS") AS
SELECT
    t.ID,t.IDMACHINE,t.TEMPS,t.CAPACITE,t.IDUNITE,
    aim.LIBELLE AS idmachinelib,
    au.VAL as idunitelib,
    
    t.ID || t.IDMACHINE || t.TEMPS || t.CAPACITE || t.IDUNITE || 
    aim.LIBELLE || au.VAL  AS motsClesss
FROM tempsouverture t
         LEFT JOIN as_ingredient_maintenance aim
                   ON aim.id = t.idmachine
         LEFT JOIN AS_UNITE au
                   ON au.id = t.IDUNITE
;
-- [948/1309] TEST_SITUATION_SALAIRE_EDITION
CREATE OR REPLACE FORCE VIEW "TEST_SITUATION_SALAIRE_EDITION" ("ID","IDEDITION","NBENFANT","MATRICULE","NOM","PRENOM","PERSONNEL","FONCTION","IDFONCTION","CLASSIFICATION","IDCATEGORIE","IDDIRECTION","DIRECTION","SECTION","SECTION_NUMERO","SECTION_LIBELLE","SALAIRE","SALAIREBRUTE","HEUREMOIS","HEUREPRESENCE","TAUXHORAIRE","SALAIREMOIS","HEURESUP","RAPPEL","RETENUABSC","PRIME","CONGEPAYER","PREAVIS","NETPAYER","NETPAYERARR","INDAMDIVFIXE","CNAPS","OSTIE","NETIMPOSABLE","NETIMPOSABLEARR","IRSA","IRSANET","ALLOCATION","AVANCESALAIRE","AVANCEEXCEP","ANNEE","MOIS") AS
SELECT
    lp.ID,
    pe.idedition AS idedition,
    pip.nbenfant,
    pip.MATRICULE,
    trim(TRAILING ' ' FROM lp.NOM) AS nom,
    trim(TRAILING ' ' FROM lp.PRENOM) AS prenom,
    trim(TRAILING ' ' FROM lp.NOM)
        || ' '
        || trim(TRAILING ' ' FROM lp.PRENOM) AS personnel,
    pf.desce AS fonction,
    pf.id AS idfonction,
    pc.VAL AS classification,
    pc.id AS idcategorie,
    ld.ID AS iddirection,
    ld.VAL AS direction,
    ls.ID AS SECTION,
    ls.CODE_SERVICE AS section_numero,
    ls.libelle AS section_libelle,
    nvl(SALAIREDEBASE.salairedebase, 0) AS salaire,
    nvl(totalgain.gain,0) as salairebrute,
    173.33 as heuremois,
    nvl(poi.HEURENORMAL, 0) AS heurepresence,
    nvl(pe.tauxhoraire, 0) AS tauxhoraire,
    nvl(salaire.gain, 0) AS salairemois,
    nvl(heuresup.gain, 0) AS heuresup,
    nvl(rappel.gain, 0) AS rappel,
    nvl(retenuabsc.retenue, 0) AS retenuabsc,
    nvl(prime.gain, 0) AS prime,
    nvl(congepayer.gain, 0) AS congepayer,
    nvl(preavis.gain, 0) AS preavis,
    nvl(netpayer.gain, 0) AS netpayer,
    nvl(netpayerarr.gain, 0) AS netpayerarr,
    nvl(indamdivfixe.gain, 0) AS indamdivfixe,
    nvl(cnaps.retenue, 0) AS cnaps,
    nvl(ostie.retenue, 0) AS ostie,
    nvl(netimposable.retenue, 0) AS netimposable,
    nvl(netimposablearr.retenue, 0) AS netimposablearr,
    nvl(irsa.retenue, 0) AS irsa,
    nvl(irsanet.retenue, 0) AS irsanet,
    nvl(allocation.gain,0) as allocation,
    nvl(avancesalaire.retenue, 0) AS avancesalaire,
    nvl(avanceexcep.retenue, 0) AS avanceexcep,
    pe.annee,
    pe.mois
FROM -- select * from
    paie_edition pe
    INNER JOIN log_personnel lp ON
    lp.id = pe.idpersonnel
    INNER JOIN paie_info_personnel pip ON
    pip.id = pe.idpersonnel
    INNER JOIN log_direction ld ON
    pe.DIRECTION = ld.ID
    INNER JOIN log_service ls ON
    pe.SERVICE = ls.ID
    INNER JOIN CATEGORIE_PAIE pc ON
    pe.IDCATEGORIE = pc.ID
    INNER JOIN paie_fonction pf ON
    pe.IDFONCTION = pf.ID
    INNER JOIN POINTAGE poi ON
    pe.IDPERSONNEL = poi.IDPERSONNEL
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 1
    GROUP BY
    idpersonnel,
    mois,
    annee) salaire
    ON
    salaire.idpersonnel = lp.id
    AND salaire.annee = pe.annee
    AND salaire.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    max(SALAIREDEBASE) AS salairedebase,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 18
    GROUP BY
    idpersonnel,
    mois,
    annee) salairedebase
    ON
    salairedebase.idpersonnel = lp.id
    AND salairedebase.annee = pe.annee
    AND salairedebase.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 2
    GROUP BY
    idpersonnel,
    mois,
    annee) heuresup
    ON
    heuresup.idpersonnel = lp.id
    AND heuresup.annee = pe.annee
    AND heuresup.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 3
    GROUP BY
    idpersonnel,
    mois,
    annee) rappel
    ON
    rappel.idpersonnel = lp.id
    AND rappel.annee = pe.annee
    AND rappel.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(RETENUE) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 4
    GROUP BY
    idpersonnel,
    mois,
    annee) retenuabsc
    ON
    retenuabsc.idpersonnel = lp.id
    AND retenuabsc.annee = pe.annee
    AND retenuabsc.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 5
    GROUP BY
    idpersonnel,
    mois,
    annee) prime
    ON
    prime.idpersonnel = lp.id
    AND prime.annee = pe.annee
    AND prime.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    PAIE_EDITION_LIBCOMPLET pe
    WHERE
    CODERUBRIQUE IN ('403', '4030')
    GROUP BY
    idpersonnel,
    mois,
    annee) hs30
    ON
    hs30.idpersonnel = lp.id
    AND hs30.annee = pe.annee
    AND hs30.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    PAIE_EDITION_LIBCOMPLET pe
    WHERE
    CODERUBRIQUE IN ('405', '4050')
    GROUP BY
    idpersonnel,
    mois,
    annee) hs50
    ON
    hs50.idpersonnel = lp.id
    AND hs50.annee = pe.annee
    AND hs50.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 6
    GROUP BY
    idpersonnel,
    mois,
    annee) congepayer
    ON
    congepayer.idpersonnel = lp.id
    AND congepayer.annee = pe.annee
    AND congepayer.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 7
    GROUP BY
    idpersonnel,
    mois,
    annee) preavis
    ON
    preavis.idpersonnel = lp.id
    AND preavis.annee = pe.annee
    AND preavis.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 8
    GROUP BY
    idpersonnel,
    mois,
    annee) indamdivfixe
    ON
    indamdivfixe.idpersonnel = lp.id
    AND indamdivfixe.annee = pe.annee
    AND indamdivfixe.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 9
    GROUP BY
    idpersonnel,
    mois,
    annee) totalgain
    ON
    totalgain.idpersonnel = lp.id
    AND totalgain.annee = pe.annee
    AND totalgain.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 10
    GROUP BY
    idpersonnel,
    mois,
    annee) cnaps
    ON
    cnaps.idpersonnel = lp.id
    AND cnaps.annee = pe.annee
    AND cnaps.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    PAIE_EDITION_LIBCOMPLET pe
    WHERE
    CODERUBRIQUE IN ('700', '701')
    GROUP BY
    idpersonnel,
    mois,
    annee) cnaps_sans_complementaire
    ON
    cnaps_sans_complementaire.idpersonnel = lp.id
    AND cnaps_sans_complementaire.annee = pe.annee
    AND cnaps_sans_complementaire.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    PAIE_EDITION_LIBCOMPLET pe
    WHERE
    CODERUBRIQUE IN ('705', '706')
    GROUP BY
    idpersonnel,
    mois,
    annee) cnaps_complementaire
    ON
    cnaps_complementaire.idpersonnel = lp.id
    AND cnaps_complementaire.annee = pe.annee
    AND cnaps_complementaire.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 11
    GROUP BY
    idpersonnel,
    mois,
    annee) ostie
    ON
    ostie.idpersonnel = lp.id
    AND ostie.annee = pe.annee
    AND ostie.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 12
    GROUP BY
    idpersonnel,
    mois,
    annee) netimposable
    ON
    netimposable.idpersonnel = lp.id
    AND netimposable.annee = pe.annee
    AND netimposable.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 13
    GROUP BY
    idpersonnel,
    mois,
    annee) netimposablearr
    ON
    netimposablearr.idpersonnel = lp.id
    AND netimposablearr.annee = pe.annee
    AND netimposablearr.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 14
    GROUP BY
    idpersonnel,
    mois,
    annee) irsa
    ON
    irsa.idpersonnel = lp.id
    AND irsa.annee = pe.annee
    AND irsa.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 15
    GROUP BY
    idpersonnel,
    mois,
    annee) irsanet
    ON
    irsanet.idpersonnel = lp.id
    AND irsanet.annee = pe.annee
    AND irsanet.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(RETENUE) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 16
    GROUP BY
    idpersonnel,
    mois,
    annee) avancesalaire
    ON
    avancesalaire.idpersonnel = lp.id
    AND avancesalaire.annee = pe.annee
    AND avancesalaire.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 17
    GROUP BY
    idpersonnel,
    mois,
    annee) avanceexcep
    ON
    avanceexcep.idpersonnel = lp.id
    AND avanceexcep.annee = pe.annee
    AND avanceexcep.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 18
    GROUP BY
    idpersonnel,
    mois,
    annee) netpayer
    ON
    netpayer.idpersonnel = lp.id
    AND netpayer.annee = pe.annee
    AND netpayer.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 19
    GROUP BY
    idpersonnel,
    mois,
    annee) netpayerarr
    ON
    netpayerarr.idpersonnel = lp.id
    AND netpayerarr.annee = pe.annee
    AND netpayerarr.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 20
    GROUP BY
    idpersonnel,
    mois,
    annee) allocation
    ON
    allocation.idpersonnel = lp.id
    AND allocation.annee = pe.annee
    AND allocation.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    regroupement = 100
    GROUP BY
    idpersonnel,
    mois,
    annee) net_a_payer
    ON
    net_a_payer.idpersonnel = lp.id
    AND net_a_payer.annee = pe.annee
    AND net_a_payer.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe
    WHERE
    (regroupement != 100
    OR regroupement IS NULL)
    GROUP BY
    idpersonnel,
    mois,
    annee) salaire_brute
    ON
    salaire_brute.idpersonnel = lp.id
    AND salaire_brute.annee = pe.annee
    AND salaire_brute.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(retenue) AS retenue,
    mois,
    annee
    FROM
    paie_edition pe
    GROUP BY
    idpersonnel,
    mois,
    annee) total_retenue
    ON
    total_retenue.idpersonnel = lp.id
    AND total_retenue.annee = pe.annee
    AND total_retenue.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    paie_edition pe,
    paie_rubrique pr
    WHERE
    pr.id = pe.idelementpaie
    AND pr.imposable = 'I'
    GROUP BY
    idpersonnel,
    mois,
    annee) montant_brute_imposable
    ON
    montant_brute_imposable.idpersonnel = lp.id
    AND montant_brute_imposable.annee = pe.annee
    AND montant_brute_imposable.mois = pe.mois
    LEFT JOIN (
    SELECT
    idpersonnel,
    sum(gain) AS gain,
    mois,
    annee
    FROM
    PAIE_EDITION_LIBCOMPLET pe
    WHERE
    CODERUBRIQUE IN ('205')
    GROUP BY
    idpersonnel,
    mois,
    annee) indemnite_logement
    ON
    indemnite_logement.idpersonnel = lp.id
    AND indemnite_logement.annee = pe.annee
    AND indemnite_logement.mois = pe.mois
GROUP BY
    lp.ID,
    lpad(pe.MATRICULE, 5, '0'),
    pc.id,
    trim(TRAILING ' ' FROM lp.NOM),
    trim(TRAILING ' ' FROM lp.PRENOM),
    lp.NOM || ' ' || lp.PRENOM ,
    pf.DESCE,
    pf.id,
    pc.VAL ,
    ld.ID,
    ld.VAL,
    ls.ID,
    ls.CODE_SERVICE,
    ls.LIBELLE,
    pe.temporaire,
    nvl(SALAIREDEBASE.salairedebase, 0),
    nvl(heuresup.gain, 0),
    nvl(rappel.gain, 0),
    nvl(retenuabsc.retenue, 0),
    nvl(prime.gain, 0),
    nvl(net_a_payer.gain, 0),
    nvl(montant_brute_imposable.gain, 0),
    nvl(congepayer.gain, 0),
    nvl(preavis.gain, 0),
    nvl(hs30.gain, 0),
    nvl(hs50.gain, 0),
    nvl(indamdivfixe.gain, 0),
    nvl(totalgain.gain, 0),
    nvl(cnaps.retenue, 0),
    nvl(ostie.retenue, 0),
    nvl(salaire_brute.gain, 0),
    nvl(cnaps.retenue, 0),
    nvl(ostie.retenue, 0),
    nvl(irsa.retenue, 0),
    nvl(irsanet.retenue, 0),
    nvl(netimposable.retenue, 0),
    nvl(netimposablearr.retenue, 0),
    nvl(total_retenue.retenue, 0),
    nvl(avancesalaire.retenue, 0),
    nvl(avanceexcep.retenue, 0),
    nvl(cnaps_sans_complementaire.retenue, 0),
    nvl(cnaps_complementaire.retenue, 0),
    nvl(rappel.gain, 0),
    nvl(netpayer.gain, 0),
    nvl(netpayerarr.gain, 0),
    nvl(indemnite_logement.gain, 0),
    nvl(pe.tauxhoraire, 0),
    pip.MATRICULE,
    nvl(totalgain.gain,0),
    nvl(allocation.gain,0),
    173.33,
    nvl(poi.HEURENORMAL, 0),
    nvl(salaire.gain, 0),
    0,
    pip.nbenfant,
    pe.annee,
    pe.mois,
    pe.idedition
;
-- [949/1309] TIERS
CREATE OR REPLACE FORCE VIEW "TIERS" ("ID","NOM","COMPTE","COMPTEAUXILIAIRE") AS
select ID, NOM, COMPTE, compteauxiliaire from FOURNISSEUR
UNION ALL
select ID, NOM, COMPTE, compteauxiliaire from CLIENT
;
-- [950/1309] AVOIRFCLIB_PDF
CREATE OR REPLACE FORCE VIEW "AVOIRFCLIB_PDF" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","COMPTE","COMPTEAUXILIAIRE","IDVENTE","IDVENTELIB","IDMOTIF","IDMOTIFLIB","IDCATEGORIE","IDCATEGORIELIB","IDDEVISE","TAUXDECHANGE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","IDRESERVATION","TYPEAVOIR","CLIENTLIB","NUMAVOIR","IDRISTOURNE","NUMFACT") AS
SELECT a.ID,
       a.DESIGNATION,
       a.IDMAGASIN,
       m.VAL         AS IDMAGASINLIB,
       a.DATY,
       a.REMARQUE,
       a.ETAT,
       a.IDORIGINE,
       a.IDCLIENT,
       t.COMPTE,
       t.compteauxiliaire,
       a.IDVENTE,
       v.DESIGNATION AS IDVENTELIB,
       a.IDMOTIF,
       ma.VAL        AS IDMOTIFLIB,
       a.IDCATEGORIE,
       c.VAL         AS IDCATEGORIELIB,
       ag.IDDEVISE,
       ag.TAUXDECHANGE,
       ag.MONTANTHT,
       ag.MONTANTTVA,
       ag.MONTANTTTC,
       ag.MONTANTHTAR,
       ag.MONTANTTVAAR,
       ag.MONTANTTTCAR,
       v.IDRESERVATION,
       ta.val        as Typeavoir,
       t.NOM         as clientlib,
       a.numavoir,
       a.idristourne,
       v.NUMEROFACTURE as numfact
FROM AVOIRFC a
         LEFT JOIN magasin2 m ON m.id = a.IDMAGASIN
         LEFT JOIN VENTE v ON v.id = a.IDVENTE
         LEFT JOIN MOTIFAVOIRFC ma ON ma.id = a.IDMOTIF
         LEFT JOIN CATEGORIEAVOIRFC c ON c.id = a.IDCATEGORIE
         JOIN AVOIRFCFILLE_GRP ag ON ag.idavoirfc = a.id
         LEFT JOIN TIERS T ON T.ID = A.IDCLIENT
         left join TYPEAVOIR ta on ta.id = a.IDTYPEAVOIR
;
-- [951/1309] AVOIRFCMONTANT
CREATE OR REPLACE FORCE VIEW "AVOIRFCMONTANT" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","COMPTE","COMPTEAUXILIAIRE","IDVENTE","IDVENTELIB","IDMOTIF","IDMOTIFLIB","IDCATEGORIE","IDCATEGORIELIB","IDDEVISE","TAUXDECHANGE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","IDRESERVATION","TYPEAVOIR","CLIENTLIB","MONTANTPAYEAR") AS
SELECT a.ID,
       a.DESIGNATION,
       a.IDMAGASIN,
       ''         AS IDMAGASINLIB,
       a.DATY,
       a.REMARQUE,
       a.ETAT,
       a.IDORIGINE,
       a.IDCLIENT,
       '' as COMPTE,
        '' as compteauxiliaire,
       a.IDVENTE,
       '' AS IDVENTELIB,
       a.IDMOTIF,
       ''        AS IDMOTIFLIB,
       a.IDCATEGORIE,
       ''         AS IDCATEGORIELIB,
       ag.IDDEVISE,
       ag.TAUXDECHANGE,
       ag.MONTANTHT,
       ag.MONTANTTVA,
       ag.MONTANTTTC,
       ag.MONTANTHTAR,
       ag.MONTANTTVAAR,
       ag.MONTANTTTCAR,
        '' as IDRESERVATION,
       ''        as Typeavoir,
       ''         as clientlib,
       NVL(M.montant, 0) * NVL(ag.TAUXDECHANGE, 0)              AS MONTANTPAYEAR
FROM AVOIRFC a
         --LEFT JOIN magasin2 m ON m.id = a.IDMAGASIN
         --LEFT JOIN VENTE v ON v.id = a.IDVENTE
         --LEFT JOIN MOTIFAVOIRFC ma ON ma.id = a.IDMOTIF
         --LEFT JOIN CATEGORIEAVOIRFC c ON c.id = a.IDCATEGORIE
         JOIN AVOIRFCFILLE_GRP ag ON ag.idavoirfc = a.id
         --LEFT JOIN TIERS T ON T.ID = A.IDCLIENT
         LEFT JOIN MOUVEMENTCAISSEGRPAVOIR_LP M
                   ON A.ID = M.IDORIGINE
where a.ETAT>=11 and a.IDORIGINE is not NULL
;
-- [952/1309] AVOIRFCMONTANT_GBVENTE
CREATE OR REPLACE FORCE VIEW "AVOIRFCMONTANT_GBVENTE" ("IDVENTE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","MONTANTPAYEAR") AS
SELECT
    IDVENTE,
    SUM(NVL(MONTANTHT, 0))     AS MONTANTHT,
    SUM(NVL(MONTANTTVA, 0))    AS MONTANTTVA,
    SUM(NVL(MONTANTTTC, 0))    AS MONTANTTTC,
    SUM(NVL(MONTANTHTAR, 0))   AS MONTANTHTAR,
    SUM(NVL(MONTANTTVAAR, 0))  AS MONTANTTVAAR,
    SUM(NVL(MONTANTTTCAR, 0))  AS MONTANTTTCAR,
    SUM(NVL(MONTANTPAYEAR, 0)) AS MONTANTPAYEAR
FROM AVOIRFCMONTANT
GROUP BY IDVENTE
;
-- [953/1309] COMPTA_MOUVEMENT_DETAILAUX
CREATE OR REPLACE FORCE VIEW "COMPTA_MOUVEMENT_DETAILAUX" ("ID","CONTREP","COMPTE_AUXLIB","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO","COURSDEVISE","MONTANTDEVISE") AS
SELECT
	cse.id,
	(
	SELECT
		MIN(csec.compte) KEEP (DENSE_RANK FIRST
	ORDER BY
		GREATEST(csec.debit, csec.credit) DESC)
	FROM
		compta_sous_ecriture csec
	WHERE
		csec.idmere = cse.idmere
		AND csec.id <> cse.id
		AND (

            (cse.debit > 0
			AND csec.credit > 0)
		OR

            (cse.credit > 0
			AND csec.debit > 0)

            )

    ) AS contrep,
	t.nom AS compte_auxlib,
	t.compteauxiliaire AS compte,
	cse.debit,
	cse.credit,
	cse.libellepiece,
	cse.remarque,
	cse.idmere,
	cse.analytique AS REFERENCE_ENGAGEMENT,
	cse.compte_aux,
	lettre.lettre AS lettrage,
	cj.val AS journal,
	EXTRACT(YEAR FROM cse.daty) AS exercice,
	cse.etat,
	cse.daty,
	cse.folio,
	CAST(0 AS NUMBER(20, 2)) AS coursdevise,
	CAST(0 AS NUMBER(20, 2)) AS montantdevise
FROM
	COMPTA_SOUS_ECRITURE cse
LEFT JOIN TIERS t ON
	cse.COMPTE_AUX = t.id
LEFT JOIN COMPTA_JOURNAL_VIEW cj ON
	cj.id = cse.journal
LEFT JOIN compta_compte cc ON
	cse.compte = cc.compte
LEFT JOIN compta_type_compte ctc ON
	cc.typecompte = ctc.id
LEFT JOIN COMPTA_LETTRAGE lettre ON
	lettre.id = cse.lettrage
WHERE
	1<2
	AND cj.id <> 'COMP000015'
	AND ((cse.DEBIT>0
		AND cse.credit = 0)
	OR (cse.DEBIT = 0
		AND cse.credit>0))
;
-- [954/1309] COMPTA_MOUVEMENT_DETAILS_AUX_2
CREATE OR REPLACE FORCE VIEW "COMPTA_MOUVEMENT_DETAILS_AUX_2" ("ID","CONTREP","COMPTE","DEBIT","CREDIT","LIBELLEPIECE","REMARQUE","IDMERE","REFERENCE_ENGAGEMENT","COMPTE_AUX","LETTRAGE","JOURNAL","EXERCICE","ETAT","DATY","FOLIO","COMPTE_AUXLIB","COURSDEVISE","MONTANTDEVISE","COMPTEINT") AS
SELECT
	ID,
	CONTREP,
	COMPTE,
	DEBIT,
	CREDIT,
	LIBELLEPIECE,
	REMARQUE,
	idmere AS IDMERE,
	REFERENCE_ENGAGEMENT,
	COMPTE_AUX,
	LETTRAGE,
	JOURNAL,
	EXERCICE,
	ETAT,
	DATY,
	FOLIO,
	compte_auxlib,
	CAST(COURSDEVISE AS NUMBER(20,

        2)) AS COURSDEVISE,
	CAST(MONTANTDEVISE AS NUMBER(20,

        2)) AS MONTANTDEVISE,
	TO_NUMBER(REGEXP_SUBSTR(TRIM(compte), '^[0-9]+')) AS compteInt
FROM
	COMPTA_MOUVEMENT_DETAILAUX
WHERE
	REGEXP_LIKE(TRIM(compte), '^[0-9]+')
;
