-- [957/1309] COMPTA_SOUSECRITURE_CREE2
CREATE OR REPLACE FORCE VIEW "COMPTA_SOUSECRITURE_CREE2" ("ID","NUMERO","COMPTE","JOURNAL","IDJOURNAL","ECRITURE","DATY","CREDIT","DEBIT","DATECOMPTABLE","EXERCICE","REMARQUE","ETAT","HORSEXERCICE","OD","ORIGINE","TIERS","LIBELLEPIECE","COMPTE_AUX","FOLIO","ANALYTIQUE") AS
select
    sousecr.id,
    cpt.LIBELLE,
    cpt.COMPTE,
    jrn.val||'| '|| jrn.DESCE as JOURNAL,
    jrn.id,
    sousecr.REMARQUE ,
    SOUSECR.DATY ,
    sousecr.CREDIT,
    sousecr.DEBIT,
    sousecr.DATY as DATECOMPTABLE,
    SOUSECR.EXERCICE,
    sousecr.REMARQUE,
    sousecr.ETAT ,
    cast(0 as number) AS HORSEXERCICE,
    cast('-' as varchar(50)) AS OD,
    cast('' as varchar(50)) AS ORIGINE,
    cast('' as varchar2(50)) as tiers,
    sousecr.LIBELLEPIECE,
    cast('' as varchar(100)) as RAISONSOCIAL ,
    sousecr.folio,
    SOUSECR.ANALYTIQUE
from
    COMPTA_SOUS_ECRITURE sousecr
        join COMPTA_COMPTE cpt on  sousecr.COMPTE = cpt.COMPTE
        join COMPTA_JOURNAL jrn on sousecr.JOURNAL = jrn.ID
where sousecr.etat = 1
;
-- [958/1309] COMPTA_SOUSECRITURE_ECRITURE
