-- [967/1309] MOUVEMENTCAISSECPL_CREE
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSECPL_CREE" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","ETATLIB","IDVENTE","IDORIGINE","IDTIERS","TIERS","MOTSCLESSS") AS
