-- [968/1309] MOUVEMENTCAISSECPL_NATTACH
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSECPL_NATTACH" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","ETATLIB","IDVENTE","IDORIGINE","IDTIERS","TIERS","IDPREVISION","IDOP","TAUX","COMPTE","IDDEVISE") AS
SELECT "ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","ETATLIB","IDVENTE","IDORIGINE","IDTIERS","TIERS","IDPREVISION","IDOP","TAUX","COMPTE","IDDEVISE" FROM MOUVEMENTCAISSECPL m  
WHERE NOT EXISTS (SELECT mvp.id FROM MVTCAISSEPREVISION mvp WHERE mvp.id1=m.id) AND m.ETAT >=11
;
-- [969/1309] MOUVEMENTCAISSECPL_VALIDER
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSECPL_VALIDER" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","ETATLIB","IDVENTE","IDORIGINE","IDTIERS","TIERS","MOTSCLESSS") AS
SELECT SQ.ID,SQ.DESIGNATION,SQ.IDCAISSE,SQ.IDCAISSELIB,SQ.IDVENTEDETAIL,SQ.IDVIREMENT,SQ.DEBIT,SQ.CREDIT,SQ.DATY,SQ.ETAT,SQ.ETATLIB,SQ.IDVENTE,SQ.IDORIGINE,SQ.IDTIERS,SQ.TIERS,
	       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(DESIGNATION),'') || ' | ' || NVL(TO_CHAR(IDCAISSE),'') || ' | ' || NVL(TO_CHAR(IDCAISSELIB),'') || ' | ' || NVL(TO_CHAR(IDVENTEDETAIL),'') || ' | ' || NVL(TO_CHAR(IDVIREMENT),'') || ' | ' || NVL(TO_CHAR(DEBIT),'') || ' | ' || NVL(TO_CHAR(CREDIT),'') || ' | ' || NVL(TO_CHAR(DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(ETAT),'') || ' | ' || NVL(TO_CHAR(ETATLIB),'') || ' | ' || NVL(TO_CHAR(IDVENTE),'') || ' | ' || NVL(TO_CHAR(IDORIGINE),'') || ' | ' || NVL(TO_CHAR(IDTIERS),'') || ' | ' || NVL(TO_CHAR(TIERS),'')) AS MOTSCLESSS
	FROM (
	         SELECT
	             ID,DESIGNATION,IDCAISSE,IDCAISSELIB,IDVENTEDETAIL,IDVIREMENT,DEBIT,CREDIT,DATY,ETAT,ETATLIB,IDVENTE,IDORIGINE,IDTIERS,TIERS
	         FROM
	             MOUVEMENTCAISSECPL m
	         WHERE
	                 m.etat = 11
	
	     ) SQ
;
-- [970/1309] MOUVEMENTCAISSECPL_V_DISPATCH
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSECPL_V_DISPATCH" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","MONTANTIMPUTE","DATY","ETAT","ETATLIB","IDVENTE","IDORIGINE","IDTIERS","TIERS","IDPAIEMENT","REFERENCEPAIEMENT","DESIGNATIONPAIEMENT") AS
SELECT m.ID,
       DESIGNATION,
       IDCAISSE,
       IDCAISSELIB,
       IDVENTEDETAIL,
       IDVIREMENT,
       DEBIT,
       CREDIT,
       lp.MONTANT as montantimpute,
       DATY,
       m.ETAT,
       ETATLIB,
       IDVENTE,
       id2 as IDORIGINE,
       IDTIERS,
       TIERS,
       id1 as idpaiement,
       m.REFERENCE as referencepaiement,
       m.DESIGNATION as designationpaiement
FROM LIAISONPAIEMENT lp LEFT JOIN
    MOUVEMENTCAISSECPL m on m.id = lp.ID1
WHERE m.etat > 7
;
-- [971/1309] MVTCAISSECPLORIGINE
CREATE OR REPLACE FORCE VIEW "MVTCAISSECPLORIGINE" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","SOLDECREDIT","SOLDEDEBIT","DATY","ETAT","ETATLIB","IDVENTE","IDORIGINE","IDTIERS","TIERS","IDPREVISION","IDOP","TAUX","COMPTE","IDDEVISE","IDTRAITE","IDMODEPAIEMENTLIB","IDMVTCAISSEMERE","REFERENCE","DATYCOMPTABILISATION","UPDATED_AT","HEURE","IDREPORT","MOTSCLESS","IDECRITURE") AS
SELECT m.ID,
       m.DESIGNATION,
       m.IDCAISSE,
       c.VAL   AS IDCAISSELIB,
       m.IDVENTEDETAIL,
       m.IDVIREMENT,
       m.DEBIT,
       m.CREDIT,
       CAST(
               CASE
                   WHEN m.credit > 0 THEN NVL(m.CREDIT, 0) - NVL(l.MONTANT, 0)
                   ELSE 0
                   END AS NUMBER(36,5)
       ) AS soldecredit,
       CAST(
               CASE
                   WHEN m.debit > 0 THEN NVL(m.DEBIT, 0) - NVL(l.MONTANT, 0)
                   ELSE 0
                   END AS NUMBER(36,5)
       ) AS soldedebit,
       m.DATY,
       m.ETAT,
       CASE
           WHEN m.ETAT = 0
               THEN 'ANNULEE'
           WHEN m.ETAT = 1
               THEN 'CREEE'
           WHEN m.ETAT = 11
               THEN 'VALIDEE'
           WHEN m.ETAT = 8
               THEN 'A COMPTABILISER'
           END AS ETATLIB,
       vd.IDVENTE,
       lp.ID2 as idorigine,
       m.idtiers,
       t.NOM AS tiers,
       m.idPrevision,
       m.idOP,
       m.taux,
       m.COMPTE,
       m.IDDEVISE,
       m.idtraite,
       mp.VAL as idModePaiementLib,
       m.idmvtcaissemere,
       m.reference,
       m.datycomptabilisation,
       m.UPDATED_AT, m.heure,
       m.IDREPORT,
       m.ID || '' || m.DATY || '' || m.DESIGNATION || '' || t.NOM || '' || m.IDCAISSE || '' || c.VAL AS MOTSCLESS,
       cr.id as idecriture
FROM MOUVEMENTCAISSE m
         LEFT JOIN CAISSE c ON c.ID = m.IDCAISSE
         LEFT JOIN VENTE_DETAILS vd ON vd.ID = m.IDVENTEDETAIL
         LEFT JOIN tiers t ON t.ID = m.idtiers
         left join liaisonpaiementmvtcaissegrp l on l.idmvtcaisse=m.id
         left join modepaiement mp on m.idmodepaiement = mp.id
         LEFT JOIN COMPTA_ECRITURE cr on cr.IDOBJET=m.id
         JOIN LIAISONPAIEMENT lp ON lp.ID1 = m.ID
;
-- [972/1309] MVTCAISSECPLORIGINE_A
CREATE OR REPLACE FORCE VIEW "MVTCAISSECPLORIGINE_A" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","SOLDECREDIT","SOLDEDEBIT","DATY","ETAT","ETATLIB","IDVENTE","IDORIGINE","IDTIERS","TIERS","IDPREVISION","IDOP","TAUX","COMPTE","IDDEVISE","IDTRAITE","IDMODEPAIEMENTLIB","IDMVTCAISSEMERE","REFERENCE","DATYCOMPTABILISATION","UPDATED_AT","HEURE","IDREPORT","MOTSCLESS","IDECRITURE") AS
