-- [974/1309] MVTCAISSECPLORIGINE_CREER
CREATE OR REPLACE FORCE VIEW "MVTCAISSECPLORIGINE_CREER" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","SOLDECREDIT","SOLDEDEBIT","DATY","ETAT","ETATLIB","IDVENTE","IDORIGINE","IDTIERS","TIERS","IDPREVISION","IDOP","TAUX","COMPTE","IDDEVISE","IDTRAITE","IDMODEPAIEMENTLIB","IDMVTCAISSEMERE","REFERENCE","DATYCOMPTABILISATION","UPDATED_AT","HEURE","IDREPORT","MOTSCLESS","IDECRITURE") AS
