-- [980/1309] PERTEGAINIMPREVUELIB_NP
CREATE OR REPLACE FORCE VIEW "PERTEGAINIMPREVUELIB_NP" ("ID","DESIGNATION","IDTYPEGAINPERTE","PERTE","GAIN","IDORIGINE","DATY","ETAT","TVA","TIERS","TYPE","COMPTE","MONTANTTVA","MONTANTHT","MONTANTTTC","TIERSLIB","TIERSCOMPTE") AS
