where  EXISTS (SELECT idorigine FROM MOUVEMENTCAISSE m WHERE m.idorigine=p.id )
;
-- [982/1309] PREVISIONFERMELIB
CREATE OR REPLACE FORCE VIEW "PREVISIONFERMELIB" ("ID","DESIGNATION","IDMAGASIN","IDMVTSTOCKFILLE","PU","IDPRODUIT","ENTREE","SORTIE","DATY","ETAT","IDORIGINE","IDTIERS","IDMAGASINLIB","IDTIERSLIB","IDPRODUITLIB","SORTIEEFFECTIVE","ENTREEEFFECTIVE","ECARTENTREE","ECARTSORTIE") AS
select
    p.ID,
    p.DESIGNATION,
    p.IDMAGASIN,
    p.IDMVTSTOCKFILLE,
    p.PU,
    p.IDPRODUIT,
    p.ENTREE,
    p.SORTIE,
    p.DATY,
    p.ETAT,
    p.IDORIGINE,
    p.IDTIERS,
    m.VAL AS idMagasinLib,
    t.NOM as idTiersLib,
    ai.LIBELLE as idProduitLib,
    CAST(NVL(ms.SORTIE, 0) AS NUMBER(30,3)) AS SortieEffective,
    CAST(NVL(ms.ENTREE, 0) AS NUMBER(30,3)) AS EntreeEffective,
    CAST(NVL(p.ENTREE, 0) - NVL(ms.ENTREE, 0) AS NUMBER(30,3)) AS EcartEntree,
    CAST(NVL(p.SORTIE, 0) - NVL(ms.SORTIE, 0) AS NUMBER(30,3)) AS EcartSortie
FROM PREVISIONFERME p
LEFT JOIN magasin2 m ON m.id = p.IDMAGASIN
LEFT JOIN AS_INGREDIENTS ai ON ai.id = p.idProduit
LEFT JOIN TIERS t ON t.id = p.IDTIERS
LEFT JOIN MvtStockFilleParDate ms ON ms.DATY = p.DATY AND ms.IDMAGASIN = p.IDMAGASIN AND ms.IDPRODUIT = p.IDPRODUIT
;
-- [983/1309] PREVISION_COMPLET_CPL
CREATE OR REPLACE FORCE VIEW "PREVISION_COMPLET_CPL" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","IDTIERSLIB","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE","IDFACTUREMERE") AS
SELECT p.ID,
       p.DESIGNATION,
       p.IDCAISSE,
       p.IDCAISSELIB,
       p.IDVENTEDETAIL,
       p.IDVENTE,
       p.IDVENTELIB,
       p.IDVIREMENT,
       p.DEBIT,
       p.CREDIT,
       p.DATY,
       p.ETAT,
       p.IDOP,
       p.IDOPLIB,
       p.IDORIGINE,
       p.IDDEVISE,
       p.IDDEVISELIB,
       p.TAUX,
       p.IDTIERS,
       t.NOM                                                     as IDTIERSLIB,
       p.COMPTE,
       cast(NVL(pe.effectifDeb, 0) as number(30, 2))             AS effectifDebit,
       cast(NVL(pe.effectifCred, 0) as number(30, 2))            AS effectifCredit,
       cast(p.debit - NVL(pe.effectifDeb, 0) as number(30, 2))   AS depenseEcart,
       cast(p.credit - nVL(pe.effectifCred, 0) as number(30, 2)) AS recetteEcart,
       p.idfacture,
       COALESCE(v.IDVENTE, f.IDFACTUREFOURNISSEUR)               AS idfacturemere
FROM PREVISION_CPL p
         LEFT JOIN PrevisionAvecMvtCaisse pe ON pe.id = p.id
         LEFT JOIN VENTE_DETAILS v ON v.id = p.idfacture
         LEFT JOIN FACTUREFOURNISSEURFILLE f ON f.id = p.idfacture
         LEFT JOIN TIERS t ON t.id = p.IDTIERS
;
-- [984/1309] PREVISION_COMPLET_CPLPOSITIF
CREATE OR REPLACE FORCE VIEW "PREVISION_COMPLET_CPLPOSITIF" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE","IDFACTUREMERE") AS
SELECT "ID",
       "DESIGNATION",
       "IDCAISSE",
       "IDCAISSELIB",
       "IDVENTEDETAIL",
       "IDVENTE",
       "IDVENTELIB",
       "IDVIREMENT",
       "DEBIT",
       "CREDIT",
       "DATY",
       "ETAT",
       "IDOP",
       "IDOPLIB",
       "IDORIGINE",
       "IDDEVISE",
       "IDDEVISELIB",
       "TAUX",
       "IDTIERS",
       "COMPTE",
       "EFFECTIFDEBIT",
       "EFFECTIFCREDIT",
       cast (DEPENSEECART as  number(30,2)) as DEPENSEECART,
       cast(RECETTEECART as  number(30,2)) as RECETTEECART,
       "IDFACTURE",
       "IDFACTUREMERE"
from PREVISION_COMPLET_CPL pr
WHERE pr.DEPENSEECART > 0
   OR RECETTEECART > 0
order by daty asc
;
-- [985/1309] PREVISION_COMPLET_CPL_DEP
CREATE OR REPLACE FORCE VIEW "PREVISION_COMPLET_CPL_DEP" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE") AS
SELECT "ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE" FROM PREVISION_COMPLET_CPL pcc  WHERE 
debit > 0
;
-- [986/1309] PREVISION_COMPLET_CPL_REC
CREATE OR REPLACE FORCE VIEW "PREVISION_COMPLET_CPL_REC" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE") AS
SELECT "ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE" FROM PREVISION_COMPLET_CPL pcc  WHERE 
credit > 0
;
-- [987/1309] PREVISION_COMPLET_CPL_NR
CREATE OR REPLACE FORCE VIEW "PREVISION_COMPLET_CPL_NR" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE") AS
SELECT "ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE" FROM 
PREVISION_COMPLET_CPL_DEP
where depenseEcart > 0
UNION ALL 
 SELECT "ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE" FROM
PREVISION_COMPLET_CPL_REC
where recetteEcart > 0
;
-- [988/1309] PREVISION_TIERS
CREATE OR REPLACE FORCE VIEW "PREVISION_TIERS" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVENTE","IDVENTELIB","IDVIREMENT","DEBIT","CREDIT","DATY","ETAT","IDOP","IDOPLIB","IDORIGINE","IDDEVISE","IDDEVISELIB","TAUX","IDTIERS","COMPTE","EFFECTIFDEBIT","EFFECTIFCREDIT","DEPENSEECART","RECETTEECART","IDFACTURE","TIERSLIB") AS
select p."ID",p."DESIGNATION",p."IDCAISSE",p."IDCAISSELIB",p."IDVENTEDETAIL",p."IDVENTE",p."IDVENTELIB",p."IDVIREMENT",p."DEBIT",p."CREDIT",p."DATY",p."ETAT",p."IDOP",p."IDOPLIB",p."IDORIGINE",p."IDDEVISE",p."IDDEVISELIB",p."TAUX",p."IDTIERS",p."COMPTE",p."EFFECTIFDEBIT",p."EFFECTIFCREDIT",p."DEPENSEECART",p."RECETTEECART",p."IDFACTURE", t.nom as tierslib from PREVISION_COMPLET_CPLPositif p LEFT JOIN TIERS t on t.id = p.IDTIERS
;
-- [989/1309] REPORTSOLDE_AUX_V1
CREATE OR REPLACE FORCE VIEW "REPORTSOLDE_AUX_V1" ("COMPTE","LIBELLE","DEBIT","CREDIT","TYPECOMPTE","DATY","CHIFFRE3","CHIFFRE2") AS
SELECT
	COMPTE,
	LIBELLE,
	CAST(DEBIT AS NUMBER(30, 2)) AS debit,
	CAST(CREDIT AS NUMBER(30, 2)) AS credit,
	TYPECOMPTE,
	daty,
	CHIFFRE3,
	CHIFFRE2
FROM
	(
	SELECT
		t.COMPTEAUXILIAIRE AS COMPTE,
		t.NOM AS LIBELLE,
		SUM(cse.debit) AS debit,
		SUM(cse.credit) AS credit,
		cc.typecompte,
		cse.daty,
		CASE
			WHEN SUBSTR(t.COMPTEAUXILIAIRE, 1, 4) = '4007' THEN '407'
			ELSE SUBSTR(t.COMPTEAUXILIAIRE, 1, 2) || SUBSTR(t.COMPTEAUXILIAIRE, 5, 1)
		END AS CHIFFRE3,
		SUBSTR(t.COMPTEAUXILIAIRE, 1, 2) AS CHIFFRE2
	FROM
		compta_sous_ecriture cse
	JOIN compta_compte cc ON
		cc.COMPTE = cse.compte
	JOIN compta_journal jrn ON
		cse.JOURNAL = jrn.id
	JOIN TIERS t ON
		t.id = cse.COMPTE_AUX
	WHERE
		cse.etat = 11
	GROUP BY
		t.COMPTEAUXILIAIRE,
		t.NOM,
		cc.typecompte,
		cse.daty

    )
;
-- [990/1309] TIERSENSEMBLE
CREATE OR REPLACE FORCE VIEW "TIERSENSEMBLE" ("ID","NOM","NIF","STAT","ADRESSE","CONTACT","CODEPOSTAL","COMPTE","IDTYPEFOURNISSEUR","COMPTEAUXILIAIRE","ESTACTIF","ECHEANCE","DEVISE","MAIL","BANQUE") AS
select f.ID,
       NOM,
       NIF,
       STAT,
       ADRESSE,
       CONTACT,
       CODEPOSTAL,
       COMPTE,
       IDTYPEFOURNISSEUR,
       COMPTEAUXILIAIRE,
       ESTACTIF,
       ECHEANCE,
       DEVISE,
       MAIL,
       BANQUE
from FOURNISSEUR f
union all
select c.ID,
       c.NOM,
       c.NIF,
       c.STAT,
       c.ADRESSE,
       c.mail as contact,
       '' as codepostal,
       c.COMPTE,
       c.IDTYPECLIENT as idTypefournisseur,
       c.COMPTEAUXILIAIRE,
       c.ESTACTIF,
       ECHEANCE,
       'AR' as devise,
       c.MAIL,
       '' as banque
from CLIENT c
;
-- [991/1309] COMPTA_SOUSECRITURE_LIB
CREATE OR REPLACE FORCE VIEW "COMPTA_SOUSECRITURE_LIB" ("ID","NUMERO","COMPTE","JOURNAL","IDJOURNAL","ECRITURE","DATY","CREDIT","DEBIT","DATECOMPTABLE","EXERCICE","REMARQUE","ETAT","IDMERE","HORSEXERCICE","OD","ORIGINE","TIERS","LIBELLEPIECE","COMPTE_AUX","RAISONSOCIAL","FOLIO","LETTRAGE","ANALYTIQUE","COMPTEAUXILIAIRE","COMPTE_AUXLIB","IDOBJET") AS
select
    sousecr.id,
    cpt.LIBELLE as numero,
    cpt.COMPTE,
    jrn.val as journal ,
    jrn.id as idjournal,
    sousecr.REMARQUE as ecriture,
    sousecr.DATY,
    sousecr.CREDIT,
    sousecr.DEBIT,
    sousecr.DATY AS DATECOMPTABLE,
    sousecr.EXERCICE,
    sousecr.REMARQUE,
    sousecr.ETAT,
    sousecr.idmere,
    cast(0 as number) AS HORSEXERCICE,
    cast('-' as varchar(50)) AS OD,
    CE.ORIGINE AS ORIGINE,
    cast('' as varchar2(50)) as tiers,
    sousecr.LIBELLEPIECE,
    sousecr.COMPTE_AUX,
    cast('' as varchar(100)) as RAISONSOCIAL ,
    sousecr.folio ,
    sousecr.LETTRAGE ,
    sousecr.ANALYTIQUE,
    te.COMPTEAUXILIAIRE as compteauxiliaire,
    te.NOM as compte_auxlib,
    ce.IDOBJET as idobjet
from
    COMPTA_SOUS_ECRITURE sousecr
        join COMPTA_COMPTE cpt on  sousecr.COMPTE = cpt.COMPTE
        join COMPTA_JOURNAL jrn on sousecr.JOURNAL = jrn.ID
        left join tiersensemble te on sousecr.COMPTE_AUX=te.id
        LEFT JOIN COMPTA_ECRITURE CE ON CE.ID = sousecr.idMERE
;
-- [992/1309] COMPTASOUSECRITURECND
CREATE OR REPLACE FORCE VIEW "COMPTASOUSECRITURECND" ("ID","NUMERO","COMPTE","JOURNAL","IDJOURNAL","ECRITURE","DATY","CREDIT","DEBIT","DATECOMPTABLE","EXERCICE","REMARQUE","ETAT","IDMERE","HORSEXERCICE","OD","ORIGINE","TIERS","LIBELLEPIECE","COMPTE_AUX","RAISONSOCIAL","FOLIO","LETTRAGE","ANALYTIQUE") AS
