-- [999/1309] COMPTA_SOUSECRITURE_LETTRE
CREATE OR REPLACE FORCE VIEW "COMPTA_SOUSECRITURE_LETTRE" ("ID","NUMERO","COMPTE","JOURNAL","IDJOURNAL","ECRITURE","DATY","CREDIT","DEBIT","DATECOMPTABLE","EXERCICE","REMARQUE","ETAT","IDMERE","HORSEXERCICE","OD","ORIGINE","TIERS","LIBELLEPIECE","COMPTE_AUX","RAISONSOCIAL","FOLIO","LETTRAGE","ANALYTIQUE","IDVENTE","LETTRE","MONTANT") AS
SELECT
    lib.ID,lib.NUMERO,lib.COMPTE,lib.JOURNAL,lib.IDJOURNAL,lib.ECRITURE,lib.DATY,lib.CREDIT,lib.DEBIT,lib.DATECOMPTABLE,lib.EXERCICE,lib.REMARQUE,lib.ETAT,lib.IDMERE,lib.HORSEXERCICE,lib.OD,lib.ORIGINE,lib.TIERS,lib.LIBELLEPIECE,lib.COMPTE_AUX,lib.RAISONSOCIAL,lib.FOLIO,lib.LETTRAGE,lib.ANALYTIQUE,
    COALESCE(mtc.IDORIGINE, ecr.IDOBJET) AS IDVENTE,CLTR.lettre,
     CASE
        WHEN NVL(lib.DEBIT, 0) = 0 THEN lib.CREDIT
        WHEN NVL(lib.CREDIT, 0) = 0 THEN lib.DEBIT
        ELSE lib.DEBIT - lib.CREDIT
    END AS MONTANT
FROM
    COMPTA_SOUSECRITURE_LIB lib
        JOIN COMPTA_ECRITURE ecr ON lib.IDMERE = ecr.ID
        LEFT JOIN MOUVEMENTCAISSE mtc ON ecr.IDOBJET = mtc.ID
        LEFT JOIN compta_lettrage cltr on cltr.id=lib.lettrage
     WHERE lib.etat=11
order by IDVENTE DESC
;
-- [1000/1309] COMPTA_SOUSECRITURE_LIB_J
CREATE OR REPLACE FORCE VIEW "COMPTA_SOUSECRITURE_LIB_J" ("ID","NUMERO","COMPTE","JOURNAL","IDJOURNAL","ECRITURE","DATY","CREDIT","DEBIT","DATECOMPTABLE","EXERCICE","REMARQUE","ETAT","IDMERE","HORSEXERCICE","OD","ORIGINE","TIERS","LIBELLEPIECE","COMPTE_AUX","RAISONSOCIAL","FOLIO","LETTRAGE","ANALYTIQUE","DESIGNATIONMERE","JOUR","MOIS","ANNEE") AS
select cse."ID",cse."NUMERO",cse."COMPTE",cse."JOURNAL",cse."IDJOURNAL",cse."ECRITURE",cse."DATY",cse."CREDIT",cse."DEBIT",cse."DATECOMPTABLE",cse."EXERCICE",cse."REMARQUE",cse."ETAT",cse."IDMERE",cse."HORSEXERCICE",cse."OD",cse."ORIGINE",cse."TIERS",cse."LIBELLEPIECE",cse."COMPTE_AUX",cse."RAISONSOCIAL",cse."FOLIO",cse."LETTRAGE",cse."ANALYTIQUE",ce.DESIGNATION as designationmere,
       EXTRACT(DAY FROM cse.DATY)   AS jour,
       EXTRACT(MONTH FROM cse.DATY) AS mois,
       EXTRACT(YEAR FROM cse.DATY)  AS annee  from COMPTA_SOUSECRITURE_LIB cse join COMPTA_ECRITURE ce on cse.IDMERE=ce.ID
;
-- [1001/1309] TOUSLESDATE
CREATE OR REPLACE FORCE VIEW "TOUSLESDATE" ("DATY") AS
SELECT
    (TO_DATE('01/01/2000', 'DD/MM/YYYY') + level - 1) AS daty
FROM dual
CONNECT BY level <= 1 + (ADD_MONTHS(TRUNC(SYSDATE), 120) - TO_DATE('01/01/2000', 'DD/MM/YYYY'))
;
-- [1002/1309] RESULTATPREVEFFECTIFTOUS
CREATE OR REPLACE FORCE VIEW "RESULTATPREVEFFECTIFTOUS" ("DATY","DEBIT","CREDIT","SEMAINE","ANNEE","MOIS") AS
SELECT 
t.daty,
nvl(r.debit,0) AS debit,
nvl(r.credit,0) AS credit,
(CAST (to_char( t.daty, 'IW') AS INTEGER)) AS semaine,
extract(YEAR FROM t.daty) AS annee,
EXTRACT (MONTH FROM t.daty) AS mois
FROM tousLesDate t 
left join resultatPrevisionnelEffectif r ON t.daty=r.daty
;
-- [1003/1309] RESULTATPREVISIONNELTOUS
CREATE OR REPLACE FORCE VIEW "RESULTATPREVISIONNELTOUS" ("DATY","DEBIT","CREDIT","SEMAINE","ANNEE","MOIS") AS
SELECT 
t.daty,
nvl(r.debit,0) AS debit,
nvl(r.credit,0) AS credit,
(CAST (to_char( t.daty, 'IW') AS INTEGER)) AS semaine,
extract(YEAR FROM t.daty) AS annee,
EXTRACT (MONTH FROM t.daty) AS mois
FROM tousLesDate t  left join resultatPrevisionnel r ON t.daty=r.daty
;
-- [1004/1309] RESULTATPREVGROUPMOIS
CREATE OR REPLACE FORCE VIEW "RESULTATPREVGROUPMOIS" ("DATY","DEBIT","CREDIT","annee","mois") AS
SELECT min(r.daty) AS daty,sum(r.debit) AS debit,sum(r.CREDIT) AS credit,r."annee", r."mois" 
FROM RESULTATPREVISIONNELTOUS r GROUP BY r."annee", r."mois"
;
-- [1005/1309] RESULTATPREVGROUPSEMAINE
CREATE OR REPLACE FORCE VIEW "RESULTATPREVGROUPSEMAINE" ("DATY","DEBIT","CREDIT","semaine","annee","mois") AS
SELECT min(r.daty) AS daty,sum(r.debit) AS debit,sum(r.CREDIT) AS credit,r."semaine",r."annee", r."mois" 
FROM RESULTATPREVISIONNELTOUS r GROUP BY r."semaine",r."annee", r."mois"
;
-- [1006/1309] RESULTATPREVISIONNELTOUSMVT
CREATE OR REPLACE FORCE VIEW "RESULTATPREVISIONNELTOUSMVT" ("DATY","DEBIT","CREDIT","SEMAINE","ANNEE","MOIS") AS
SELECT 
t.daty,
nvl(r.debit,0) AS debit,
nvl(r.credit,0) AS credit,
(CAST (to_char( t.daty, 'IW') AS INTEGER)) AS semaine,
extract(YEAR FROM t.daty) AS annee,
EXTRACT (MONTH FROM t.daty) AS mois
FROM tousLesDate t  left join resultatPrevisionnelMvt r ON t.daty=r.daty
;
-- [1007/1309] TRAITEETATVERSEMENT
CREATE OR REPLACE FORCE VIEW "TRAITEETATVERSEMENT" ("IDTRAITE","ETATVERSEMENT") AS
select IDTRAITE, cast(-2 as number) as etatversement
from MVTINTRACAISSE
where IDTRAITE is not null
  and ETATVERSEMENT = -2
group by IDTRAITE
UNION ALL
select idtraite, cast(11 as number) as etatversement
from MVTINTRACAISSE
where idtraite is not null
  and ETATVERSEMENT = 11
  and IDTRAITE not in
      (select IDTRAITE from MVTINTRACAISSE where IDTRAITE is not null and ETATVERSEMENT = -2 group by IDTRAITE)
group by idtraite
;
-- [1008/1309] TRAITEMENT_PAIE_LIB
CREATE OR REPLACE FORCE VIEW "TRAITEMENT_PAIE_LIB" ("IDPERSONNEL","NOMPERSONNEL","MATRICULE","NETAPAYER","IDEDITION","MODEPAIEMENT","NUMEROCOMPTE") AS
SELECT
    ec.id AS idpersonnel ,
    ec.nom || ' ' || ec.PRENOM AS nomPersonnel,
    ec.MATRICULE ,
    pe.GAIN AS netapayer,
    pe.IDEDITION ,
    ec.MODE_PAIEMENT AS modepaiement,
    ec.BANQUE_NUMERO_COMPTE AS numeroCompte
FROM PAIE_EDITION pe
         LEFT JOIN EMPLOYE_COMPLET ec ON ec.id = pe.IDPERSONNEL
WHERE pe.IDELEMENTPAIE ='PR000210A' AND pe.etat >= 11
;
-- [1009/1309] TRAITEMTTFC
CREATE OR REPLACE FORCE VIEW "TRAITEMTTFC" ("ID","MONTANTENLEVETRAITE") AS
SELECT
    t.ID,
    cast(nvl(sum(f.montant),0) as number(30,2)) AS montantenlevetraite
FROM traite t
         LEFT JOIN LIAISONPAIEMENT f ON t.ID = f.ID2
GROUP BY t.ID
;
-- [1010/1309] TRAITE_JC
CREATE OR REPLACE FORCE VIEW "TRAITE_JC" ("ID","IDTRAITE","MONTANT","DATY","ETAT","IDJC","DATESAISIE","DATEEFFET","FOLIO","CAISSE","NUMPIECE","LIBELLE","DEBIT","CREDIT","REMARQUE","ETATJC","TIERS","IDTYPECHEQUE","DESIGNATION","IDORDRE","IDDEVISE","IDMODE","NUMCHEQUE","TYPEMVT","IDPLACEMENT","IDBANQUE","IDPLACEMENTVRAI","ETATVERSEMENT","ETATLIB","ETATVERSEMENTLIB","VALCAISSE") AS
select
    jc.id,fc.ID AS idtraite,fc.MONTANT,fc.DATY,fc.ETAT,jc.id AS IDJC,
    jc.daty as datesaisie,
    jc.daty as DATEEFFET,
    '' as FOLIO,
    jc.IDCAISSE as caisse,
    '' as NUMPIECE,
    jc.DESIGNATION as libelle ,
    jc.DEBIT,
    jc.CREDIT,
    jc.DESIGNATION as REMARQUE,
    jc.ETAT AS etatjc,
    jc.IDTIERS as TIERS,
    '' as IDTYPECHEQUE,
    jc.DESIGNATION,
    '' as IDORDRE,
    jc.IDDEVISE,
    '' as IDMODE,
    '' as NUMCHEQUE,
    '' as TYPEMVT,
    '' as IDPLACEMENT,
    fc.BANQUE as IDBANQUE,
    '' as IDPLACEMENTVRAI,
    jc.ETATVERSEMENT,
    case
        when jc.etat = 1 then 'CREEE'
        when jc.etat >= 11 then 'VISEE'
        else '' end                           as etatlib,
    case
        when jc.etatversement = -2 then 'Encaissee'
        when jc.etatversement = 11 then 'Versee'
        else '' end                           as etatversementlib,
    c.VAL AS valcaisse
from MOUVEMENTCAISSE jc
         join traite fc on fc.id = jc.IDTRAITE
          LEFT JOIN caisse c ON c.id = jc.IDCAISSE
;
-- [1011/1309] TRAITE_LIB
CREATE OR REPLACE FORCE VIEW "TRAITE_LIB" ("ID","DATY","TIERS","BANQUE","DATEECHEANCE","ETAT","MONTANT","REFERENCE","CDCLT","IDBANQUE","IDTYPEPIECE","TYPEPIECE") AS
select
    tr.id,
    tr.daty,
    ti.nom as tiers,
    ba.val as banque,
    tr.dateEcheance,
    tr.etat,
    tr.montant,
    tr.REFERENCE,
    '' as CDCLT,
    ba.ID AS idbanque,
    IDTYPEPIECE ,
    tp.val AS typepiece
from traite tr
         left join client ti on tr.tiers = ti.id
         left join banque ba on tr.banque = ba.id
         LEFT JOIN type_piece tp ON tp.id=tr.IDTYPEPIECE
;
-- [1012/1309] TRAITE_LIBMTT
CREATE OR REPLACE FORCE VIEW "TRAITE_LIBMTT" ("ID","DATY","TIERS","BANQUE","DATEECHEANCE","ETAT","MONTANT","ESCOMPTE","TOTAL","REFERENCE","CDCLT","IDBANQUE","IDTYPEPIECE","TYPEPIECE") AS
select t.ID,t.DATY,t.TIERS,t.BANQUE,t.DATEECHEANCE,t.ETAT,t.MONTANT,
       sum(nvl(e.FRAIS,0)) AS escompte,
       montant - sum(nvl(e.FRAIS, 0)) AS total, t.reference,
       t.CDCLT,
       t.idbanque,
       t.idtypepiece,
       t.typepiece
from traite_lib t
         LEFT JOIN ESCOMPTE_LIBV e ON e.IDTRAITE = t.id
GROUP BY t.id, t.DATY ,t.TIERS ,t.BANQUE ,t.DATEECHEANCE ,t.ETAT ,t.MONTANT,t.REFERENCE, t.CDCLT, t.idbanque,t.idtypepiece,
         t.typepiece
;
-- [1013/1309] TRAITEMTTRESTE
CREATE OR REPLACE FORCE VIEW "TRAITEMTTRESTE" ("ID","DATY","TIERS","BANQUE","DATEECHEANCE","ETAT","MONTANT","ESCOMPTE","TOTAL","REFERENCE","MONTANTRESTE","CDCLT","IDBANQUE","IDTYPEPIECE","TYPEPIECE","ETATVERSEMENT","ETATVERSEMENTLIB") AS
SELECT t.ID,
       t.DATY,
       t.TIERS,
       t.BANQUE,
       t.DATEECHEANCE,
       t.ETAT,
       CAST(nvl(t.MONTANT,0) AS NUMBER(30, 2))                          AS montant,
       t.ESCOMPTE,
       CAST(nvl(t.TOTAL,0) AS NUMBER(30, 2))                            AS total,
       t.REFERENCE,
       CAST((nvl(t.total,0) - nvl(tf.montantenlevetraite, 0)) AS NUMBER(30, 2)) AS montantreste,
       t.cdclt,
       t.idbanque,
       t.idtypepiece,
       t.typepiece,
       nvl(te.etatversement, 1)                                  as etatversement,
       case
           when te.etatversement = -2 then 'Encaissee'
           when te.etatversement = 11 then 'Versee'
           else
               'Non Versee' end                                  as etatversementlib
FROM TRAITE_LIBMTT t
         LEFT JOIN traitemttfc tf ON tf.id = t.id
         LEFT JOIN traiteetatversement te on te.IDTRAITE = t.ID
;
-- [1014/1309] TRAITEMTTRESTE_NONVERSEE
CREATE OR REPLACE FORCE VIEW "TRAITEMTTRESTE_NONVERSEE" ("ID","DATY","TIERS","BANQUE","DATEECHEANCE","ETAT","MONTANT","ESCOMPTE","TOTAL","REFERENCE","MONTANTRESTE","CDCLT","IDBANQUE") AS
SELECT ID,DATY,TIERS,BANQUE,DATEECHEANCE,ETAT,MONTANT,ESCOMPTE,TOTAL,REFERENCE,MONTANTRESTE,CDCLT,IDBANQUE FROM (
	SELECT t.ID,t.DATY,t.TIERS,t.BANQUE,t.DATEECHEANCE,t.ETAT,t.MONTANT,t.ESCOMPTE,t.TOTAL,t.REFERENCE,
 (t.total-tf. montantenlevetraite) AS montantreste, t.cdclt, t.idbanque
 FROM TRAITE_LIBMTT t 
 LEFT JOIN traitemttfc tf ON tf.id=t.id
) tmttrst WHERE id NOT IN (SELECT idtraite FROM MVTINTRACAISSE m WHERE m.idtraite IS NOT NULL AND m.ETATVERSEMENT = 11)
;
-- [1015/1309] TRAITE_LIBC
CREATE OR REPLACE FORCE VIEW "TRAITE_LIBC" ("ID","DATY","TIERS","BANQUE","DATEECHEANCE","ETAT","MONTANT","ETATVERSEMENT","ETATVERSEMENTLIB","MONTANTRESTE","REFERENCE") AS
SELECT ID,DATY,TIERS,BANQUE,DATEECHEANCE,ETAT,MONTANT, etatversement, etatversementlib,MONTANTRESTE,reference  from TRAITEMTTRESTE where etat = 1
;
-- [1016/1309] TRAITE_LIBENC
CREATE OR REPLACE FORCE VIEW "TRAITE_LIBENC" ("ID","DATY","TIERS","BANQUE","DATEECHEANCE","ETAT","MONTANT","ETATVERSEMENT","ETATVERSEMENTLIB","MONTANTRESTE","REFERENCE") AS
select ID,DATY,TIERS,BANQUE,DATEECHEANCE,ETAT,MONTANT, etatversement, etatversementlib,MONTANTRESTE, reference from TRAITEMTTRESTE where etatversement = -2
;
