CREATE OR REPLACE FORCE VIEW "TRAITE_LIBESC" ("ID","DATY","TIERS","BANQUE","DATEECHEANCE","ETAT","MONTANT","ETATVERSEMENT","ETATVERSEMENTLIB","MONTANTRESTE","REFERENCE") AS
select ID,DATY,TIERS,BANQUE,DATEECHEANCE,ETAT,MONTANT, etatversement, etatversementlib,MONTANTRESTE,reference from TRAITEMTTRESTE where id in (select idtraite from escompte where etat = 11)
;
-- [1018/1309] TRAITE_LIBNONENC
CREATE OR REPLACE FORCE VIEW "TRAITE_LIBNONENC" ("ID","DATY","TIERS","BANQUE","DATEECHEANCE","ETAT","MONTANT","ETATVERSEMENT","ETATVERSEMENTLIB","MONTANTRESTE","REFERENCE") AS
