;
-- [1019/1309] TRAITE_LIBV
CREATE OR REPLACE FORCE VIEW "TRAITE_LIBV" ("ID","DATY","TIERS","BANQUE","DATEECHEANCE","ETAT","MONTANT","ETATVERSEMENT","ETATVERSEMENTLIB","MONTANTRESTE","REFERENCE") AS
select ID,DATY,TIERS,BANQUE,DATEECHEANCE,ETAT,MONTANT, etatversement, etatversementlib,MONTANTRESTE,reference from TRAITEMTTRESTE where etat = 11
