CREATE OR REPLACE FORCE VIEW "TRAITE_LIBVER" ("ID","DATY","TIERS","BANQUE","DATEECHEANCE","ETAT","MONTANT","ETATVERSEMENT","ETATVERSEMENTLIB","MONTANTRESTE","REFERENCE") AS
