-- [1021/1309] TRANSFERTPOULETDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "TRANSFERTPOULETDETAIL_LIB" ("ID","IDMERE","IDSEXE","IDFERMEDEPART","IDBATIMENTDEPART","IDPARQUETDEPART","QTE","IDFERMEARRIVE","IDBATIMENTARRIVE","IDPARQUETARRIVE","IDCONTROLEUR","IDCHAUFFEUR","IDVEHICULE","IDSEXELIB","IDFERMEDEPARTLIB","IDBATIMENTDEPARTLIB","IDPARQUETDEPARTLIB","IDFERMEARRIVELIB","IDBATIMENTARRIVELIB","IDPARQUETARRIVELIB","IDCONTROLEURLIB","IDCHAUFFEURLIB","IDVEHICULELIB") AS
SELECT
    td."ID",td."IDMERE",td."IDSEXE",td."IDFERMEDEPART",td."IDBATIMENTDEPART",td."IDPARQUETDEPART",td."QTE",td."IDFERMEARRIVE",td."IDBATIMENTARRIVE",td."IDPARQUETARRIVE",td."IDCONTROLEUR",td."IDCHAUFFEUR",td."IDVEHICULE",
    s.val                              AS idSexeLib,
    mFermeDep.val                      AS idFermeDepartLib,
    bDep.nomBatiment                   AS idBatimentDepartLib,
    pDep.val                           AS idParquetDepartLib,
    mFermeArr.val                      AS idFermeArriveLib,
    bArr.nomBatiment                   AS idBatimentArriveLib,
    pArr.val                           AS idParquetArriveLib,
    (ctrl.nom || ' ' || ctrl.prenom)   AS idControleurLib,
    (chauf.nom || ' ' || chauf.prenom) AS idChauffeurLib,
    v.val                              AS idVehiculeLib
FROM transfertPouletDetail td
     LEFT JOIN sexe s              ON td.idSexe = s.id
     LEFT JOIN magasin2 mFermeDep  ON td.idFermeDepart = mFermeDep.id
     LEFT JOIN batiment bDep       ON td.idBatimentDepart = bDep.id
     LEFT JOIN parquet pDep        ON td.idParquetDepart = pDep.id
     LEFT JOIN magasin2 mFermeArr  ON td.idFermeArrive = mFermeArr.id
     LEFT JOIN batiment bArr       ON td.idBatimentArrive = bArr.id
     LEFT JOIN parquet pArr        ON td.idParquetArrive = pArr.id
     LEFT JOIN log_personnel ctrl  ON td.idControleur = ctrl.id
     LEFT JOIN log_personnel chauf ON td.idChauffeur = chauf.id
     LEFT JOIN vehicule v          ON td.idVehicule = v.id
;
-- [1022/1309] TRANSFERTPOULET_LIB
CREATE OR REPLACE FORCE VIEW "TRANSFERTPOULET_LIB" ("ID","DATY","IDLOT","REMARQUE","IDLOTLIB","IDSOUCHELIB","ETAT","ETATLIB") AS
SELECT
    t."ID",t."DATY",t."IDLOT",t."REMARQUE",
    l.nomLot AS idLotLib,
    so.val AS idsouchelib,
    t.ETAT AS ETAT,
    CASE t.ETAT
        WHEN 1  THEN 'CREE'
        WHEN 11 THEN 'VALIDE'
        WHEN 0  THEN 'ANULLE'
        END AS ETATLIB
FROM transfertPoulet t
         LEFT JOIN lot l ON t.idLot = l.id
         LEFT JOIN SOUCHE so ON so.id=l.idsouche
;
-- [1023/1309] TRANSFERTSTOCKDETAILSCPL
CREATE OR REPLACE FORCE VIEW "TRANSFERTSTOCKDETAILSCPL" ("ID","IDTRANSFERTSTOCK","IDTRANSFERTSTOCKLIB","IDPRODUIT","IDPRODUITLIB","QUANTITE","PU","IDSOURCE","UNITE") AS
SELECT
    t.ID ,
    t.IDTRANSFERTSTOCK ,
    t2.DESIGNATION AS IDTRANSFERTSTOCKLIB,
    t.IDPRODUIT ,
    p.libelle AS IDPRODUITLIB,
    CAST(t.QUANTITE AS NUMBER(30,5)) AS QUANTITE,
    CAST(t.PU AS NUMBER(30, 5)) AS PU,
    t.idsource,
    u.VAL as UNITE
FROM TRANSFERTSTOCKDETAILS t
         LEFT JOIN TRANSFERTSTOCK t2 ON t2.ID = t.IDTRANSFERTSTOCK
         LEFT JOIN AS_INGREDIENTS  p ON p.ID = t.IDPRODUIT
         left join AS_UNITE u on u.ID = p.UNITE
;
-- [1024/1309] TRANSTOCKDETAILSGROUPEMERE
CREATE OR REPLACE FORCE VIEW "TRANSTOCKDETAILSGROUPEMERE" ("IDTRANSFERTSTOCK","MONTANTQUANTITE") AS
select f.IDTRANSFERTSTOCK,cast(sum(nvl(f.pu*f.QUANTITE,0)) as number(30,2)) as montantQuantite
from TRANSFERTSTOCKDETAILS f group by f.IDTRANSFERTSTOCK
;
-- [1025/1309] TRANSFERTSTOCKCPL
CREATE OR REPLACE FORCE VIEW "TRANSFERTSTOCKCPL" ("ID","DESIGNATION","IDMAGASINDEPART","IDMAGASINDEPARTLIB","IDMAGASINARRIVE","IDMAGASINARRIVELIB","DATY","ETAT","IDOF","ETATLIB","MONTANTQUANTITE") AS
SELECT
    t.ID ,
    t.DESIGNATION ,
    t.IDMAGASINDEPART ,
    m.VAL AS IDMAGASINDEPARTLIB,
    t.IDMAGASINARRIVE ,
    m2.VAL AS IDMAGASINARRIVELIB,
    t.DATY ,
    t.ETAT ,
    t.idof,
    CASE
        WHEN t.ETAT = 0
            THEN 'ANNUL&Eacute;'
        WHEN t.ETAT = 1
            THEN 'CR&Eacute;&Eacute;'
        WHEN t.ETAT = 11
            THEN 'VIS&Eacute;'
        END AS ETATLIB,
    CAST(tgm.montantQuantite AS NUMBER(30,2)) AS montantQuantite
FROM TRANSFERTSTOCK t
         LEFT JOIN MAGASINPOINT m ON m.ID = t.IDMAGASINDEPART
         LEFT JOIN MAGASINPOINT m2 ON m2.ID = t.IDMAGASINARRIVE
         LEFT JOIN TRANSTOCKDETAILSGROUPEMERE tgm ON tgm.IDTRANSFERTSTOCK = t.id
;
-- [1026/1309] ANOMALIETRANSFERT
CREATE OR REPLACE FORCE VIEW "ANOMALIETRANSFERT" ("IDTRANSFERT","MAGASINDEPART","MAGASINDEPARTLIB","MAGASINARRIVE","MAGASINARRIVELIB","DATY","DESIGNATION","IDPRODUIT","IDPRODUITLIB","QUANTITE","MONTANT","ENVOYE","MONTANTENVOYE","RECU","MONTANTRECU","ECART","MONTANTECART","RESTE") AS
SELECT 
t.id as idTransfert,
t.IDMAGASINDEPART AS magasinDepart,
t.IDMAGASINDEPARTLIB AS  magasinDepartLib,
t.IDMAGASINARRIVE AS magasinArrive,
t.IDMAGASINARRIVELIB AS magasinArriveLib,
t.daty,
t.designation,
td.idproduit,
td.idproduitlib,
CAST(nvl(td.quantite,0) AS NUMBER(30,5))  AS quantite ,
CAST(nvl(td.pu,0)*nvl(td.quantite,0) AS NUMBER(30,5))  as montant , 
CAST(nvl(m.sortie,0) AS NUMBER(30,5))  as envoye,
CAST(nvl(td.pu,0)*nvl(m.sortie,0) AS NUMBER(30,5))  as montantEnvoye, 
CAST(nvl(m.entree,0) AS NUMBER(30,5))  as recu ,
CAST(nvl(td.pu,0)*nvl(m.entree,0) AS NUMBER(30,5))  as montantRecu,
CAST(nvl(m.sortie,0) - nvl(m.entree,0) AS NUMBER(30,5))  as ecart,
CAST(nvl(td.pu,0)*CAST(nvl(m.sortie,0) - nvl(m.entree,0) AS NUMBER(30,5)) AS NUMBER(30,5))  as montantEcart ,
CAST(nvl(td.quantite,0) - nvl(m.sortie,0) AS NUMBER(30,5))  as reste
FROM transfertstockdetailscpl td
LEFT JOIN transfertstockcpl t ON t.id = td.idtransfertstock 
LEFT JOIN mvtstockfilletransfert m ON m.idtransfertdetail = td.id
;
-- [1027/1309] TRANSFERTSTOCKCPL_ANNULEE
CREATE OR REPLACE FORCE VIEW "TRANSFERTSTOCKCPL_ANNULEE" ("ID","DESIGNATION","IDMAGASINDEPART","IDMAGASINDEPARTLIB","IDMAGASINARRIVE","IDMAGASINARRIVELIB","DATY","ETAT","IDOF","ETATLIB","MONTANTQUANTITE") AS
(
	SELECT
		t.ID,t.DESIGNATION,t.IDMAGASINDEPART,t.IDMAGASINDEPARTLIB,t.IDMAGASINARRIVE,t.IDMAGASINARRIVELIB,t.DATY,t.ETAT,t.IDOF,t.ETATLIB,t.montantQuantite
	FROM
	TransfertStockCpl t
	WHERE t.etat=0
)
;
-- [1028/1309] TRANSFERTSTOCKCPL_CREE
CREATE OR REPLACE FORCE VIEW "TRANSFERTSTOCKCPL_CREE" ("ID","DESIGNATION","IDMAGASINDEPART","IDMAGASINDEPARTLIB","IDMAGASINARRIVE","IDMAGASINARRIVELIB","DATY","ETAT","IDOF","ETATLIB","MONTANTQUANTITE") AS
(
	SELECT
		t.ID,t.DESIGNATION,t.IDMAGASINDEPART,t.IDMAGASINDEPARTLIB,t.IDMAGASINARRIVE,t.IDMAGASINARRIVELIB,t.DATY,t.ETAT,t.IDOF,t.ETATLIB,t.montantQuantite
	FROM
	TransfertStockCpl t
	WHERE t.etat=1
)
;
-- [1029/1309] TRANSFERTSTOCKCPL_VISEE
CREATE OR REPLACE FORCE VIEW "TRANSFERTSTOCKCPL_VISEE" ("ID","DESIGNATION","IDMAGASINDEPART","IDMAGASINDEPARTLIB","IDMAGASINARRIVE","IDMAGASINARRIVELIB","DATY","ETAT","IDOF","ETATLIB","MONTANTQUANTITE") AS
(
	SELECT
		t.ID,t.DESIGNATION,t.IDMAGASINDEPART,t.IDMAGASINDEPARTLIB,t.IDMAGASINARRIVE,t.IDMAGASINARRIVELIB,t.DATY,t.ETAT,t.IDOF,t.ETATLIB,montantQuantite
	FROM
	TransfertStockCpl t
	WHERE t.etat=11
)
;
-- [1030/1309] TRAVAUXCPL
CREATE OR REPLACE FORCE VIEW "TRAVAUXCPL" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","IDOFFILLE","IDOF","LANCEPARLIB","CIBLELIB","ETAT","ETATLIB","FABRICATIONPREC","FABRICATIONSUIV","IDINGREDIENTMAINTENANCE","INGREDIENTMAINTENANCELIB") AS
SELECT
    f.ID,f.LANCEPAR,f.CIBLE,f.REMARQUE,f.LIBELLE,f.BESOIN,f.DATY,f.idOffille,nvl(f.idof, off.idmere) AS idof,
    p.val AS lanceparLib,
    p2.val AS cibleLib,
    f.etat AS etat,
    CASE
        WHEN f.ETAT=1
            THEN 'CR&Eacute;E'
        WHEN f.ETAT=11
            THEN 'VALID&Eacute;E'
        WHEN f.ETAT=0
            THEN 'ANNUL&Eacute;E'
        WHEN f.ETAT=21
            THEN 'ENTAM&Eacute;E'
        WHEN f.ETAT=31
            THEN 'BLOQU&Eacute;E'
        WHEN f.ETAT=41
            THEN 'TERMIN&Eacute;E'
        END AS ETATLIB,
    f.FABRICATIONPREC,
    f.FABRICATIONSUIV,
    off.idIngredients AS idIngredientMaintenance,
    off.remarque AS ingredientMaintenanceLib
FROM TRAVAUX f
         LEFT JOIN ENTITE p ON p.id = f.lancepar
         LEFT JOIN MAGASIN p2 ON p2.id = f.cible
         LEFT JOIN ORDRETRAVAUXFILLE off ON f.idoffille = off.id
;
-- [1031/1309] TRAVAUXCPLANNULE
CREATE OR REPLACE FORCE VIEW "TRAVAUXCPLANNULE" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","IDOFFILLE","IDOF","LANCEPARLIB","CIBLELIB","ETAT","ETATLIB","FABRICATIONPREC","FABRICATIONSUIV") AS
SELECT
    ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM TRAVAUXCPL f
WHERE etat = 0
;
-- [1032/1309] TRAVAUXCPLBLOQUEE
CREATE OR REPLACE FORCE VIEW "TRAVAUXCPLBLOQUEE" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","IDOFFILLE","IDOF","LANCEPARLIB","CIBLELIB","ETAT","ETATLIB","FABRICATIONPREC","FABRICATIONSUIV") AS
SELECT
    ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM TRAVAUXCPL f
WHERE etat = 31
;
-- [1033/1309] TRAVAUXCPLCREE
CREATE OR REPLACE FORCE VIEW "TRAVAUXCPLCREE" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","IDOFFILLE","IDOF","LANCEPARLIB","CIBLELIB","ETAT","ETATLIB","FABRICATIONPREC","FABRICATIONSUIV") AS
SELECT
    ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM TRAVAUXCPL f
WHERE etat = 1
;
-- [1034/1309] TRAVAUXCPLENTAMEE
CREATE OR REPLACE FORCE VIEW "TRAVAUXCPLENTAMEE" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","IDOFFILLE","IDOF","LANCEPARLIB","CIBLELIB","ETAT","ETATLIB","FABRICATIONPREC","FABRICATIONSUIV") AS
SELECT
    ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM TRAVAUXCPL f
WHERE etat = 21
;
-- [1035/1309] TRAVAUXCPLTERMINEE
CREATE OR REPLACE FORCE VIEW "TRAVAUXCPLTERMINEE" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","IDOFFILLE","IDOF","LANCEPARLIB","CIBLELIB","ETAT","ETATLIB","FABRICATIONPREC","FABRICATIONSUIV") AS
SELECT
    ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM TRAVAUXCPL f
WHERE etat = 41
;
-- [1036/1309] TRAVAUXCPLVISEE
CREATE OR REPLACE FORCE VIEW "TRAVAUXCPLVISEE" ("ID","LANCEPAR","CIBLE","REMARQUE","LIBELLE","BESOIN","DATY","IDOFFILLE","IDOF","LANCEPARLIB","CIBLELIB","ETAT","ETATLIB","FABRICATIONPREC","FABRICATIONSUIV") AS
SELECT
    ID,LANCEPAR,CIBLE,REMARQUE,LIBELLE,BESOIN,DATY,IDOFFILLE,IDOF,LANCEPARLIB,CIBLELIB,ETAT,ETATLIB,FABRICATIONPREC,FABRICATIONSUIV
FROM TRAVAUXCPL f
WHERE etat = 11
;
-- [1037/1309] TRAVAUXFILLECPL
CREATE OR REPLACE FORCE VIEW "TRAVAUXFILLECPL" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","PU","IDINGREDIENTSLIB","OPERATEUR","IDUNITELIB","IDBCFILLE","IDMACHINE","IDMACHINELIB","OPERATEURLIB") AS
SELECT
    f.ID,
    f.IDINGREDIENTS,
    f.LIBELLE,
    f.REMARQUE,
    f.IDMERE,
    f.DATYBESOIN,
    f.QTE,
    f.IDUNITE,
    f.PU,
    ai.LIBELLE AS idingredientsLib,
    p.NOM || ' - ' || p.TELEPHONE AS operateur,
    au.val AS IDUNITELIB,
    f.IDBCFILLE ,
    f.IDMACHINE,
    m.val AS IDMACHINELIB,
    p2.NOM AS OPERATEURLiB
FROM
    TRAVAUXFILLE f
        LEFT JOIN AS_INGREDIENT_MAINTENANCE ai ON
        ai.id = f.IDINGREDIENTS
        LEFT JOIN PERSONNEL p ON
        p.ID = f.OPERATEUR
        LEFT JOIN AS_UNITE au ON
        au.id = f.IDUNITE
        LEFT JOIN MACHINE m ON
        m.ID = f.IDMACHINE
        LEFT JOIN PERSONNEL p2 ON
        p2.id = f.OPERATEUR
;
-- [1038/1309] TRAVAUXMEREFILLE
CREATE OR REPLACE FORCE VIEW "TRAVAUXMEREFILLE" ("IDINGREDIENTS","IDINGREDIENTSLIB","QTE","IDUNITE","IDOFFILLE","IDOF","LIBELLE","DATY","IDBCFILLE") AS
SELECT
    ff.IDINGREDIENTS,
    ff.IDINGREDIENTSLIB ,
    sum(ff.QTE) qte,
    ff.IDUNITE ,
    f.idOffille,
    f.IDOF,
    f.LIBELLE,
    f.DATY,
    ff.IDBCFILLE
FROM
    TRAVAUXFILLECPL ff
        JOIN TRAVAUX f ON
        f.id = ff.IDMERE
WHERE
    f.etat = 11
GROUP BY
    ff.IDINGREDIENTS,
    ff.IDINGREDIENTSLIB ,
    ff.IDUNITE ,
    f.idOffille,
    f.LIBELLE,
    f.DATY,
    ff.IDBCFILLE,
    f.IDOF
;
-- [1039/1309] ORDRETRAVAUXFILLELIB
CREATE OR REPLACE FORCE VIEW "ORDRETRAVAUXFILLELIB" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","QTEFABRIQUE","QTERESTE","LIBELLEEXACTE") AS
SELECT
    ofll.ID,
    ofll.IDINGREDIENTS,
    nvl(ofll.LIBELLE,ai.LIBELLE)  AS LIBELLE,
    ofll.REMARQUE,
    ofll.IDMERE,
    ofll.DATYBESOIN,
    ofll.QTE,
    nvl(au.VAL, 'unite') AS IDUNITE,
    fmf.qte AS qteFabrique,
    (ofll.qte-nvl(fmf.qte, 0)) AS qteReste,
    nvl(ofll.LIBELLE,nvl(ai.LIBELLE, ai.LIBELLE)) AS libelleexacte
FROM
    ORDRETRAVAUXFILLE ofll
        LEFT JOIN AS_INGREDIENT_MAINTENANCE ai ON
        ai.ID = ofll.IDINGREDIENTS
        LEFT JOIN AS_UNITE au ON
        au.ID = ofll.IDUNITE
        LEFT JOIN TRAVAUXMEREFILLE fmf ON
        fmf.IDOFFILLE = ofll.ID
            AND fmf.IDINGREDIENTS = ofll.IDINGREDIENTS
            AND fmf.IDBCFILLE = OFLL.IDBCFILLE
;
-- [1040/1309] OTRAVFILLERESTELIB
CREATE OR REPLACE FORCE VIEW "OTRAVFILLERESTELIB" ("ID","IDINGREDIENTS","LIBELLE","REMARQUE","IDMERE","DATYBESOIN","QTE","IDUNITE","QTEFABRIQUE","QTERESTE") AS
SELECT o."ID",
       o."IDINGREDIENTS",
       o."LIBELLE",
       o."REMARQUE",
       o."IDMERE",
       o."DATYBESOIN",
       o."QTE",
       o."IDUNITE",
       fmf.qte           AS qteFabrique,
       (o.qte - fmf.qte) AS qteReste
FROM TRAVAUXMEREFILLE fmf
         JOIN ORDRETRAVAUXFILLELIB o ON fmf.idof = o.IDMERE AND fmf.IDINGREDIENTS = o.IDINGREDIENTS
;
-- [1041/1309] TRAVAUX_RECAP
CREATE OR REPLACE FORCE VIEW "TRAVAUX_RECAP" ("ID","MONTANTCHARGEEXTERNE","MONTANTPIECE","MONTANTMAINDOEUVRE","MONTANTTOTAL") AS
WITH fac_agg AS (
  SELECT idtravaux,
         SUM(NVL(montantttc, 0)) AS montantChargeExterne
  FROM FACTUREFOURNISSEURCPL_TRAVAUX
  GROUP BY idtravaux
),
mvt_agg AS (
  SELECT idobjet,
         SUM(NVL(montantsortie, 0)) AS montantPiece
  FROM MVTSTOCKLIB
  GROUP BY idobjet
),
pm_agg AS (
  SELECT idtravaux,
         SUM(NVL(montantreel, 0)) AS montantMainDoeuvre
  FROM RAPPROCHEMENTTRAVAUX
  GROUP BY idtravaux
)
SELECT t.id,
       NVL(fac_agg.montantChargeExterne, 0) AS montantChargeExterne,
       NVL(mvt_agg.montantPiece, 0)         AS montantPiece,
       NVL(pm_agg.montantMainDoeuvre, 0)    AS montantMainDoeuvre,
       NVL(fac_agg.montantChargeExterne, 0)
           + NVL(mvt_agg.montantPiece, 0)
           + NVL(pm_agg.montantMainDoeuvre, 0)    AS montantTotal
FROM TRAVAUX t
         LEFT JOIN fac_agg ON fac_agg.idtravaux = t.id
         LEFT JOIN mvt_agg ON mvt_agg.idobjet   = t.id
         LEFT JOIN pm_agg  ON pm_agg.idtravaux  = t.id
;
-- [1042/1309] COUTSMAINTENANCE
CREATE OR REPLACE FORCE VIEW "COUTSMAINTENANCE" ("IDMACHINE","NOMMACHINE","IDLIGNE","IDLIGNELIB","IDTRAVAUX","DATY","COUTTOTAL") AS
SELECT
    o.IDINGREDIENTS AS idMachine,
    aim.DESCRIPTIONOBJET AS nomMachine,
    l.ID AS IDLIGNE ,
    l.VAL AS IDLIGNELIB,
    tr.ID AS idTravaux,
    t.DATY ,
    CAST (tr.MONTANTTOTAL AS NUMBER(10,2)) AS CoutTotal
FROM TRAVAUX_RECAP tr
         LEFT JOIN TRAVAUX t
                   ON tr.id = t.ID
         LEFT JOIN ORDRETRAVAUXFILLE o
                   ON t.IDOFFILLE = o.id
         LEFT JOIN AS_INGREDIENT_MAINTENANCE aim
                   ON o.IDINGREDIENTS = aim.ID
         LEFT JOIN LIGNE l
                   ON aim.IDLIGNE = l.ID
WHERE o.IDINGREDIENTS IS NOT NULL
;
-- [1043/1309] TRIAGEBATIMENTPARQUET_LIB
CREATE OR REPLACE FORCE VIEW "TRIAGEBATIMENTPARQUET_LIB" ("ID","DATY","IDLOT","DISPOMALE","DISPOFEMELLE","IDLOTLIB","IDSOUCHELIB","ETAT","ETATLIB","ECARTFEMELLE","ECARTMALE") AS
SELECT t.ID, t.DATY, t.IDLOT, t.DISPOMALE, t.DISPOFEMELLE,
       l.NOMLOT AS IDLOTLIB,
       s.val AS idsouchelib,
       t.etat AS etat,
       CASE
           WHEN t.ETAT = 1  THEN 'CR&Eacute;&Eacute;'
           WHEN t.ETAT = 11 THEN 'VALID&Eacute;'
           END AS ETATLIB,
       NVL(t.DISPOFEMELLE - (SELECT SUM(d.QTE)
            FROM TRIAGEBATIMENTPARQUETDETAIL d
            WHERE d.IDMERE = t.ID
              AND d.IDQUALITE = 'QP000001'
              AND d.IDSEXE = '0'), 0) AS ecartFemelle,
       NVL(t.DISPOMALE - (SELECT SUM(d.QTE)
            FROM TRIAGEBATIMENTPARQUETDETAIL d
            WHERE d.IDMERE = t.ID
              AND d.IDQUALITE = 'QP000001'
              AND d.IDSEXE = '1'), 0) AS ecartMale
FROM TRIAGEBATIMENTPARQUET t
         LEFT JOIN LOT l ON l.ID = t.IDLOT
         LEFT JOIN SOUCHE s ON s.id = l.idsouche
;
-- [1044/1309] TRIAGEBATPARQUETDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "TRIAGEBATPARQUETDETAIL_LIB" ("ID","IDMERE","IDBATIMENT","IDPARQUET","IDSEXE","IDQUALITE","QTE","IDBATIMENTLIB","IDPARQUETLIB","IDSEXELIB","IDQUALITELIB","IDLOT") AS
SELECT d."ID",d."IDMERE",d."IDBATIMENT",d."IDPARQUET",d."IDSEXE",d."IDQUALITE",d."QTE",
       b."NOMBATIMENT"  AS "IDBATIMENTLIB",
       p."VAL"  AS "IDPARQUETLIB",
       sx."VAL" AS "IDSEXELIB",
       q."VAL"  AS "IDQUALITELIB",
    	t.idlot AS idlot
FROM "TRIAGEBATIMENTPARQUETDETAIL" d
         LEFT JOIN "BATIMENT" b ON b."ID" = d."IDBATIMENT"
         LEFT JOIN "PARQUET" p ON p."ID" = d."IDPARQUET"
         LEFT JOIN "SEXE" sx ON sx."ID" = d."IDSEXE"
         LEFT JOIN "QUALITEPOUSSIN" q ON q."ID" = d."IDQUALITE"
		LEFT JOIN TRIAGEBATIMENTPARQUET t ON t.id=d.idmere
;
-- [1045/1309] TRIAGEOEUFDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "TRIAGEOEUFDETAIL_LIB" ("ID","IDMERE","IDTYPECOLLECTE","IDQUALITETRIAGEOEUF","QTE","IDDESTINATION","IDTYPECOLLECTELIB","IDQUALITETRIAGEOEUFLIB","IDDESTINATIONLIB") AS
SELECT d."ID",
       d."IDMERE",
       d."IDTYPECOLLECTE",
       d."IDQUALITETRIAGEOEUF",
       d."QTE",
       d."IDDESTINATION",
       tc."VAL" AS "IDTYPECOLLECTELIB",
       qt."VAL" AS "IDQUALITETRIAGEOEUFLIB",
       m."VAL"  AS "IDDESTINATIONLIB"
FROM "TRIAGEOEUFDETAIL" d
         LEFT JOIN "TYPECOLLECTE" tc ON tc."ID" = d."IDTYPECOLLECTE"
         LEFT JOIN "QUALITETRIAGEOEUF" qt ON qt."ID" = d."IDQUALITETRIAGEOEUF"
         LEFT JOIN "MAGASIN2" m ON m."ID" = d."IDDESTINATION"
;
-- [1046/1309] TRIAGEQUALITEPOUSSINDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "TRIAGEQUALITEPOUSSINDETAIL_LIB" ("ID","IDMERE","IDBATIMENT","IDPARQUET","IDQUALITE","QTE","IDBATIMENTLIB","IDPARQUETLIB","IDQUALITELIB") AS
SELECT 
	tqpd.id,
	tqpd.idmere,
	tqpd.idbatiment,
	tqpd.idparquet,
	tqpd.idqualite,
	tqpd.qte,
	b.NOMBATIMENT AS idBatimentLib,
	p.VAL AS idParquetLib,
	q.VAL AS idQualiteLib
FROM 
	triageQualitePoussinDetail tqpd
LEFT JOIN BATIMENT b ON tqpd.idbatiment = b.ID
LEFT JOIN PARQUET p ON tqpd.idparquet = p.ID
LEFT JOIN QUALITEPOUSSIN q ON tqpd.idqualite = q.ID
;
-- [1047/1309] TRIAGEQUALITEPOUSSIN_LIB
CREATE OR REPLACE FORCE VIEW "TRIAGEQUALITEPOUSSIN_LIB" ("ID","IDLOT","DATY","QTEPOUSSINACONTROLER","IDECLOSOIR","IDINCUBATEUR","IDLOTLIB","IDECLOSOIRLIB","IDINCUBATEURLIB","ETAT","ETATLIB") AS
SELECT
	tqp.id,
	tqp.idlot,
	tqp.daty,
	tqp.QTEPOUSSINACONTROLER,
	tqp.IDECLOSOIR,
	tqp.IDINCUBATEUR,
    l.nomlot AS idLotLib,
    e.VAL AS idEclosoirLib,
    i.VAL AS idIncubateurLib,
    tqp.etat,
    CASE
        WHEN tqp.etat = 1 THEN 'CREE'
        WHEN tqp.etat = 0 THEN 'ANNULEE'
        WHEN tqp.etat = 11 THEN 'VISEE'
    END AS etatLib
FROM
	triageQualitePoussin tqp
LEFT JOIN lot l ON tqp.IDLOT = l.id
LEFT JOIN ECLOSOIR e ON tqp.IDECLOSOIR = e.id
LEFT JOIN INCUBATEUR i ON tqp.IDINCUBATEUR = i.id
;
-- [1048/1309] TYPEABSENCE_CPL
CREATE OR REPLACE FORCE VIEW "TYPEABSENCE_CPL" ("ID","VAL","DESCE","NBJOUR","FREQUENCE","ETAT","FREQUENCELIB","ETATLIB") AS
SELECT
    typ."ID",typ."VAL",typ."DESCE",typ."NBJOUR",typ."FREQUENCE",typ."ETAT",
    fc.val AS frequencelib,
    CASE
        WHEN typ.etat=1 THEN 'CR&Eacute;&Eacute;'
        WHEN typ.etat=11 THEN 'VALID&Eacute;'
        END AS etatlib
FROM type_absence typ
         LEFT JOIN frequence_conge fc ON fc.id=typ.frequence
;
-- [1049/1309] TYPEMAGASIN_SANSRESERVOIR
CREATE OR REPLACE FORCE VIEW "TYPEMAGASIN_SANSRESERVOIR" ("ID","VAL","DESCE") AS
SELECT 
t."ID",t."VAL",t."DESCE"
FROM TYPEMAGASIN t  
WHERE t.ID  != 'TYPMG000001'
;
-- [1050/1309] TYPEMAINTENANCETRAVAUX
CREATE OR REPLACE FORCE VIEW "TYPEMAINTENANCETRAVAUX" ("ID","VAL","DESCE") AS
(
    SELECT
        t.id,
        dc.IDTYPEMAINTENANCE AS val,
        dc.IDTYPEMAINTENANCELIB AS desce
    FROM
    TRAVAUX t
    LEFT JOIN DEMANDETRAVAUX_CPL dc ON dc.IDOTFILLE =t.IDOFFILLE
)
;
-- [1051/1309] TYPE_PRODUIT_ACTIF
CREATE OR REPLACE FORCE VIEW "TYPE_PRODUIT_ACTIF" ("ID","VAL","DESCE","IDLIGNE","ACTIF") AS
select "ID","VAL","DESCE","IDLIGNE","ACTIF" from TYPE_PRODUIT where ACTIF=1
;
-- [1052/1309] TYPE_PRODUIT_LIB
CREATE OR REPLACE FORCE VIEW "TYPE_PRODUIT_LIB" ("ID","VAL","DESCE","IDCATEGORIE","IDCATEGORIELIB") AS
SELECT tp.ID,
       tp.VAL,
       tp.DESCE,
       '' as IDCATEGORIE,
       '' as IDCATEGORIELIB
FROM TYPE_PRODUIT tp
;
-- [1053/1309] UNITES_TRAIT
CREATE OR REPLACE FORCE VIEW "UNITES_TRAIT" ("ID","VAL","DESCE") AS
select ''  as id,
       '-' as val,
       '-' as desce
from DUAL
union
select su."ID", su."VAL", su."DESCE"
from ST_UNITE su
;
-- [1054/1309] UPDATEVENTEDETAILS
CREATE OR REPLACE FORCE VIEW "UPDATEVENTEDETAILS" ("ID","IDVENTE","IDPRODUIT","IDPRODUITLIB","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","COMPTE","IDPREVISION") AS
SELECT
	vd.ID,
	vd.IDVENTE,
	vd.IDPRODUIT,
	p.LIBELLE AS idProduitLib,
	vd.IDORIGINE,
	vd.QTE,
	vd.PU,
	vd.REMISE,
	vd.TVA,
	vd.PUACHAT,
	vd.PUVENTE,
	vd.IDDEVISE,
	vd.TAUXDECHANGE,
	vd.DESIGNATION,
	vd.COMPTE,
	vd.idprevision
FROM
	VENTE_DETAILS vd
LEFT JOIN AS_INGREDIENTS p ON
	p.ID = vd.IDPRODUIT
;
-- [1055/1309] UTILISATEURCPL
CREATE OR REPLACE FORCE VIEW "UTILISATEURCPL" ("REFUSER","IDROLE","ADRUSER","NOMUSER","LOGINUSER","PWDUSER","TELUSER","DIRECTIONLIB","IDPERSONNEL","NOMPERSONNEL") AS
SELECT
    u.REFUSER,
    u.IDROLE,
    u.ADRUSER,
    u.NOMUSER,
    u.LOGINUSER,
    u.PWDUSER,
    u.TELUSER,
    dir.DESCDIR AS directionLib,
    log.id AS idPersonnel,
    log.nom || ' ' || log.prenom AS nomPersonnel
FROM UTILISATEUR u
         LEFT JOIN direction dir ON dir.iddir = u.ADRUSER
         JOIN LOG_PERSONNEL log ON log.refuser = u.REFUSER
;
-- [1056/1309] UTILISATEURROLE
CREATE OR REPLACE FORCE VIEW "UTILISATEURROLE" ("REFUSER","LOGINUSER","PWDUSER","NOMUSER","ADRUSER","TELUSER","IDROLE","ID","RANG") AS
select u.refuser,u.LOGINUSER,u.PWDUSER,u.NOMUSER,d.ID as adruser,u.TELUSER,u.IDROLE,
       s.ID, r.rang
from utilisateur u, log_direction d, roles r, log_service s, log_personnel p, annulationutilisateur a
where u.TELUSER = p.ID
  and p.DIRECTION = d.id
  and p.SERVICE = s.id
  and u.IDROLE = r.IDROLE and
    u.refuser = a.REFUSER(+) and a.REFUSER is null
;
-- [1057/1309] UTILISATEURVALIDE
CREATE OR REPLACE FORCE VIEW "UTILISATEURVALIDE" ("REFUSER","LOGINUSER","PWDUSER","NOMUSER","ADRUSER","TELUSER","IDROLE","RANG") AS
SELECT u.REFUSER, u.LOGINUSER, u.PWDUSER, u.NOMUSER, u.ADRUSER, u.TELUSER,
       u.IDROLE,r.RANG
FROM utilisateur u ,ROLES r , annulationutilisateur a
WHERE u.IDROLE = r.IDROLE and
    u.refuser = a.REFUSER(+) and a.REFUSER is null
;
-- [1058/1309] UTILISATEURVUE
CREATE OR REPLACE FORCE VIEW "UTILISATEURVUE" ("REFUSER","LOGINUSER","PWDUSER","NOMUSER","ADRUSER","TELUSER","IDROLE","RANG") AS
SELECT
    u.refuser,
    u.LOGINUSER,
    u.PWDUSER,
    u.NOMUSER,
    d.LIBELLEDIR AS adruser,
    u.TELUSER,
    u.IDROLE,
    r.RANG
FROM utilisateur u
         JOIN direction d ON u.ADRUSER = d.IDDIR
         LEFT JOIN roles r ON r.IDROLE = u.IDROLE
;
-- [1059/1309] UTILISATEURVUEFICHE_ID
CREATE OR REPLACE FORCE VIEW "UTILISATEURVUEFICHE_ID" ("REFUSER","LOGINUSER","PWDUSER","NOMUSER","ADRUSER","TELUSER","IDROLE") AS
SELECT u.refuser AS refuser,
       u.loginuser,
       u.pwduser,
       u.nomuser,
       d.DESCDIR AS adruser,
       u.teluser,
       u.idrole
FROM utilisateur u,
     direction d
WHERE u.adruser = d.IDDIR
;
-- [1060/1309] UTILISATEUR_ACTIONROLE
CREATE OR REPLACE FORCE VIEW "UTILISATEUR_ACTIONROLE" ("ID","LOGINUSER","PWDUSER","NOMUSER","ADRUSER","TELUSER","IDROLE","RANG") AS
SELECT
    u.refuser AS id,
    u.LOGINUSER,
    u.PWDUSER,
    u.NOMUSER,
    d.LIBELLEDIR AS adruser,
    u.TELUSER,
    u.IDROLE,
    r.RANG
