     ON lp.id = s3.idpersonnel and ostie.annee=s3.annee
WHERE nvl(ostie.retenue,0)!=0
ORDER BY annee,pip.matricule
;
-- [1064/1309] V1_OSTIE_AFFICHE_T4
CREATE OR REPLACE FORCE VIEW "V1_OSTIE_AFFICHE_T4" ("NUMERO","MATRICULE","NOM","PRENOMS","SEXE","DATE_NAISSANCE","DATEEMBAUCHE","DATE_DEPART","FONCTION","CNAPS","CIN","MOIS1","MOIS2","MOIS3","SALAIRES_NON_PLAFONNES","SALAIRES_PLAFONNES","EMPLOYEUR","TRAVAILLEUR","TOTAL","ANNEE","DIRECTION") AS
SELECT
    rownum as numero,
    lpad(pip.matricule,5,'0') as matricule,
    Upper(trim(trailing ' ' from lp.NOM)) as nom,
    Upper(trim(trailing ' ' from lp.prenom)) as prenoms,
    sexe.val as sexe,
    lp.date_naissance,
    pip.dateembauche,
    case
        when extract(year from pip.date_depart)=nvl(s3.annee,nvl(s2.annee,nvl(s1.annee,0)))
            and (
                 extract(month from pip.date_depart) = 10
                     or
                 extract(month from pip.date_depart) = 11
                     or
                 extract(month from pip.date_depart) = 12
                 ) then pip.date_depart
        else
            null
        end as date_depart,
    upper(paf.desce) as fonction,
    upper(pip.NUMERO_CNAPS) as cnaps,
    lp.numero_cin as cin,
    nvl(s1.salairebase,0) as mois1,
    nvl(s2.salairebase,0) as mois2,
    nvl(s3.salairebase,0) as mois3,
    (nvl(s1.salairebase, 0)+nvl(s2.salairebase, 0)+nvl(s3.salairebase, 0)) as salaires_non_plafonnes,
    (
        case
            when nvl(s1.salairebase,0) >= (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
                then (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
            else
                nvl(s1.salairebase,0)
            end
        )+
    (
        case
            when nvl(s2.salairebase,0) >= (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
                then (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
            else
                nvl(s2.salairebase,0)
            end
        )+
    (
        case
            when nvl(s3.salairebase,0) >= (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
                then (select cast(valmin as number) as maximum from configuration where id = 'CONF000140')
            else
                nvl(s3.salairebase,0)
            end
        ) as salaires_plafonnes,
    nvl(ostie.retenue,0)*5 as employeur,
    nvl(ostie.retenue,0) as travailleur,
    (nvl(ostie.retenue,0)*5)+nvl(ostie.retenue,0) as total,
    ostie.annee,
    ostie.direction
FROM log_personnel lp
         JOIN paie_info_personnel pip ON pip.id=lp.id
         JOIN log_direction ld ON ld.id=lp.direction
         JOIN paie_fonction paf ON paf.id = pip.idfonction
         JOIN sexe ON sexe.id = lp.sexe
         LEFT JOIN
     (SELECT sum(round(retenue,0)) as retenue,idpersonnel,annee,direction FROM paie_edition WHERE
         (mois = 10 or mois=11 or mois =12) AND etat=11 AND IDELEMENTPAIE ='PRU000I710'
      group by idpersonnel,annee,direction) ostie
     ON ostie.idpersonnel = lp.id
         LEFT JOIN
     (select * from salairebasemois where mois = 10) s1
     ON lp.id = s1.idpersonnel and ostie.annee= s1.annee
         LEFT JOIN
     (select * from salairebasemois where mois = 11) s2
     ON lp.id = s2.idpersonnel and ostie.annee = s2.annee
         LEFT JOIN
     (select * from salairebasemois where mois = 12) s3
     ON lp.id = s3.idpersonnel and ostie.annee=s3.annee
WHERE nvl(ostie.retenue,0)!=0
ORDER BY annee,pip.matricule
;
-- [1065/1309] VACCINATIONPOUSSINDETAIL_LIB
CREATE OR REPLACE FORCE VIEW "VACCINATIONPOUSSINDETAIL_LIB" ("ID","IDMERE","IDBATIMENT","IDPARQUET","IDTYPEVACCINATION","IDMALADIEPOUSSIN","IDVACCIN","IDMODEADMINISTRATION","QTEDOSE","HEUREDEBUT","HEUREFIN","DATEEXPIRATION","IDBATIMENTLIB","IDPARQUETLIB","IDTYPEVACCINATIONLIB","IDMALADIEPOUSSINLIB","IDVACCINLIB","IDMODEADMINISTRATIONLIB") AS
SELECT
    vd."ID",vd."IDMERE",vd."IDBATIMENT",vd."IDPARQUET",vd."IDTYPEVACCINATION",vd."IDMALADIEPOUSSIN",vd."IDVACCIN",vd."IDMODEADMINISTRATION",vd."QTEDOSE",vd."HEUREDEBUT",vd."HEUREFIN",vd."DATEEXPIRATION",
    b.nomBatiment  AS idBatimentLib,
    p.val          AS idParquetLib,
    tv.val         AS idTypeVaccinationLib,
    mp.val         AS idMaladiePoussinLib,
    vp.val         AS idVaccinLib,
    ma.val         AS idModeAdministrationLib
FROM vaccinationPoussinDetail vd
     LEFT JOIN batiment b               ON vd.idBatiment = b.id
     LEFT JOIN parquet p                ON vd.idParquet = p.id
     LEFT JOIN typeVaccination tv       ON vd.idTypeVaccination = tv.id
     LEFT JOIN maladiePoussin mp        ON vd.idMaladiePoussin = mp.id
     LEFT JOIN VaccinPoussin vp         ON vd.idVaccin = vp.id
     LEFT JOIN modeAdministrationVaccin ma ON vd.idModeAdministration = ma.id
;
-- [1066/1309] VACCINATIONPOUSSIN_LIB
CREATE OR REPLACE FORCE VIEW "VACCINATIONPOUSSIN_LIB" ("ID","DATY","IDLOT","REMARQUE","IDLOTLIB","ETAT","ETATLIB") AS
SELECT
    v."ID",v."DATY",v."IDLOT",v."REMARQUE",
    l.nomLot AS idLotLib,
    v.ETAT AS ETAT,
    CASE v.ETAT
        WHEN 1  THEN 'CREE'
        WHEN 11 THEN 'VALIDE'
        WHEN 0  THEN 'ANULLE'
        END AS ETATLIB
FROM vaccinationPoussin v
         LEFT JOIN lot l ON v.idLot = l.id
;
-- [1067/1309] VALIDATION_ROLE_LIB_CPL
CREATE OR REPLACE FORCE VIEW "VALIDATION_ROLE_LIB_CPL" ("ID","REFOBJECT","MAPPING","NIVEAU","ROLE","PERSONNE","VALEURETAT","NOMUSER","DESCROLE") AS
select
    vr."ID",vr."REFOBJECT",vr."MAPPING",vr."NIVEAU",vr."ROLE",vr."PERSONNE",vr."VALEURETAT",
    u.NOMUSER,
    r.DESCROLE
from
    VALIDATION_ROLE vr
        left join UTILISATEUR u on u.REFUSER = vr.personne
        left join ROLES r on r.IDROLE = vr.role
;
-- [1068/1309] VENTEALIVRER
CREATE OR REPLACE FORCE VIEW "VENTEALIVRER" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","IDRESERVATION") AS
SELECT
	ID,
	DESIGNATION,
	IDMAGASIN,
	DATY,
	REMARQUE,
	ETAT,
	IDORIGINE,
	IDCLIENT,
	IDRESERVATION
FROM
	vente
WHERE
	etat <12
	OR etat = 13
;
-- [1069/1309] VENTEAPAYER
CREATE OR REPLACE FORCE VIEW "VENTEAPAYER" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","IDRESERVATION") AS
SELECT
	ID,
	DESIGNATION,
	IDMAGASIN,
	DATY,
	REMARQUE,
	ETAT,
	IDORIGINE,
	IDCLIENT,
	IDRESERVATION
FROM
	vente
WHERE
	etat <= 12
;
-- [1070/1309] VENTEDETAILS_GRP
CREATE OR REPLACE FORCE VIEW "VENTEDETAILS_GRP" ("IDVENTE","IDDEVISE","TAUXDECHANGE","MONTANTTC") AS
SELECT 
vd.IDVENTE,
vd.idDevise ,
sum(nvl(vd.TAUXDECHANGE,0) ) AS TAUXDECHANGE,
sum( nvl((vd.TAUXDECHANGE* vd.QTE * vd.PU ),0) + nvl((vd.TAUXDECHANGE* vd.QTE * vd.PU ),0) * nvl(vd.TVA,0)/100 )  AS montanttc
FROM VENTE_DETAILS vd 
GROUP BY vd.IDVENTE,idDevise
;
-- [1071/1309] VENTEDETCALC
CREATE OR REPLACE FORCE VIEW "VENTEDETCALC" ("ID","IDVENTE","IDPRODUIT","IDORIGINE","QTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","COMPTE","IDBCFILLE","UNITE","POIDS","RISTOURNE","IDPREVISION","PU","REMISE","TVA","PUACHAT","PUVENTE","PUREVIENT","IDREMISE","REMISEMONTANT","PHOTO","QTE_TMP","REFERENCE","MONTANT","REMISEARBIOCHEM","RISTOURNEARBIOCHEM","MONTANTNONREMISE","MONTANTREMISESANSTVA","MONTANTHT","PUREMISE","MONTANTHTAR","MONTANTTVA","MONTANTTVAAR","MONTANTTTC","MONTANTTTCAR","MONTANTREVIENT","MARGEBRUTE","ETAT") AS
select vd."ID",vd."IDVENTE",vd."IDPRODUIT",vd."IDORIGINE",vd."QTE",vd."IDDEVISE",vd."TAUXDECHANGE",vd."DESIGNATION",vd."COMPTE",vd."IDBCFILLE",vd."UNITE",vd."POIDS",vd."RISTOURNE",vd."IDPREVISION",vd."PU",vd."REMISE",vd."TVA",vd."PUACHAT",vd."PUVENTE",vd."PUREVIENT",vd."IDREMISE",vd."REMISEMONTANT",vd."PHOTO",vd."QTE_TMP",vd."REFERENCE",vd."MONTANT",vd.REMISEARBIOCHEM , vd.RISTOURNEARBIOCHEM,
       cast(vd.QTE * vd.pu as number(30, 2))                                     as montantNonRemise,
       cast(((vd.QTE * vd.pu *((nvl(vd.REMISE, 0) + nvl(vd.RISTOURNE, 0)) / 100)) + vd.QTE * (vd.REMISEARBIOCHEM + vd.RISTOURNEARBIOCHEM)) as number(30, 2)) as montantRemiseSansTva,
       cast(((vd.QTE * vd.pu * (1 - (nvl(vd.REMISE, 0) / 100)) *
             (1 - (nvl(vd.RISTOURNE, 0) / 100))- NVL(v.fraislivraison, 0) * NVL(vd.POIDS, 0) * NVL(vd.QTE, 0)) - vd.QTE * (vd.REMISEARBIOCHEM + vd.RISTOURNEARBIOCHEM))as number(30, 2) )                 as montantHT,
       cast((vd.pu * (1 - (nvl(vd.REMISE, 0) / 100)) *
            (1 - (nvl(vd.RISTOURNE, 0) / 100)) -(vd.REMISEARBIOCHEM + vd.RISTOURNEARBIOCHEM)) as number(30, 2))                 as puRemise,
       cast((vd.QTE * vd.pu * (1 - (nvl(vd.REMISE, 0) / 100)) * (1 - (nvl(vd.RISTOURNE, 0) / 100))- NVL(v.fraislivraison, 0) * NVL(vd.POIDS, 0) * NVL(vd.QTE, 0) - vd.QTE * (vd.REMISEARBIOCHEM + vd.RISTOURNEARBIOCHEM)) *
            nvl(vd.TAUXDECHANGE, 1) as number(30, 2))                            as montantHTAr,
       cast((vd.QTE * vd.pu * (1 - (nvl(vd.REMISE, 0) / 100)) * (1 - (nvl(vd.RISTOURNE, 0) / 100))- NVL(v.fraislivraison, 0) * NVL(vd.POIDS, 0) * NVL(vd.QTE, 0) - vd.QTE * (vd.REMISEARBIOCHEM + vd.RISTOURNEARBIOCHEM)) * nvl(vd.tva, 0) /
            100 as number(30, 2))                                                as montantTva,
       cast((vd.QTE * vd.pu * (1 - (nvl(vd.REMISE, 0) / 100)) * (1 - (nvl(vd.RISTOURNE, 0) / 100))- NVL(v.fraislivraison, 0) * NVL(vd.POIDS, 0) * NVL(vd.QTE, 0)- vd.QTE * (vd.REMISEARBIOCHEM + vd.RISTOURNEARBIOCHEM)) *
            nvl(vd.TAUXDECHANGE, 1) * nvl(vd.tva, 0) /
            100 as number(30, 2))                                                as montantTvaAr,
       cast((vd.QTE * vd.pu * (1 - (nvl(vd.REMISE, 0) / 100)) * (1 - (nvl(vd.RISTOURNE, 0) / 100))- NVL(v.fraislivraison, 0) * NVL(vd.POIDS, 0) * NVL(vd.QTE, 0) - vd.QTE * (vd.REMISEARBIOCHEM + vd.RISTOURNEARBIOCHEM)) *
            (1 + (nvl(vd.tva, 0) / 100)) as number(30, 2))                       as montantTTC,
       cast((vd.QTE * vd.pu * (1 - (nvl(vd.REMISE, 0) / 100)) * (1 - (nvl(vd.RISTOURNE, 0) / 100))- NVL(v.fraislivraison, 0) * NVL(vd.POIDS, 0) * NVL(vd.QTE, 0)) *
            (1 + (nvl(vd.tva, 0) / 100) - vd.QTE * (vd.REMISEARBIOCHEM + vd.RISTOURNEARBIOCHEM)) *
            nvl(vd.TAUXDECHANGE, 1) as number(30, 2))                            as montantTTCAr,
       cast(nvl(vd.PUREVIENT * vd.QTE, 0) as number(30, 2))                      as montantRevient,
       cast((vd.QTE * vd.pu * (1 - (nvl(vd.REMISE, 0) / 100)) * (1 - (nvl(vd.RISTOURNE, 0) / 100))- NVL(v.fraislivraison, 0) * NVL(vd.POIDS, 0) * NVL(vd.QTE, 0)- vd.QTE * (vd.REMISEARBIOCHEM + vd.RISTOURNEARBIOCHEM)) *
            (1 + (nvl(vd.tva, 0) / 100)) *
            nvl(vd.TAUXDECHANGE, 1) -
            nvl(vd.PUREVIENT * vd.QTE, 0) as number(30, 2))                    as margeBrute,v.ETAT
from VENTE_DETAILS vd join vente v on v.id=vd.IDVENTE
;
-- [1072/1309] VENTEDETCALCREMGLOVISE
CREATE OR REPLACE FORCE VIEW "VENTEDETCALCREMGLOVISE" ("ID","IDVENTE","IDVENTELIB","IDPRODUIT","IDPRODUITLIB","IDORIGINE","QTE","SUM_QTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","IDCATEGORIE","IDCATEGORIELIB","DATY","IDMAGASIN","IDMAGASINLIB","IDPOINT","IDPOINTLIB","IDDEVISELIB","IDRESERVATION","COMPTE","IDBCFILLE","UNITE","POIDS","RISTOURNE","IDPREVISION","PU","REMISE","TVA","PUACHAT","PUVENTE","PUREVIENT","IDREMISE","REMISEMONTANT","PHOTO","QTE_TMP","REFERENCE","TYPEPRODUIT","TYPEPRODUITLIB","IDPROVINCE","IDPROVINCELIB","MONTANT","MONTANTNONREMISE","MONTANTREMISESANSTVA","MONTANTHT","PUREMISE","MONTANTHTAR","MONTANTTVA","MONTANTTVAAR","MONTANTTTC","MONTANTTTCAR","MONTANTTOTAL","MONTANT_TOTAL","PUTOTAL","MONTANTREVIENT","MONTANTLIVRAISON","TOTAL_ACHAT","MARGEBRUTE","REMISEGLOBAL","IDCLIENT","IDCLIENTLIB","MOIS","LIBELLE_MOIS","ANNEE") AS
select vd.ID,
       IDVENTE,
       vd.DESIGNATION as idventeLib,
       vd.IDPRODUIT,
       ing.LIBELLE as idProduitLib,
       vd.IDORIGINE,
       QTE,
       qte as sum_qte,
       IDDEVISE,
       TAUXDECHANGE,
       vd.DESIGNATION,
       ing.CATEGORIEINGREDIENT as idcategorie,
       cat.VAL as idCategorieLib,
       v.DATY,
       v.IDMAGASIN,
       mag.VAL as idmagasinLib,
       mag.IDPOINT,
       p1.VAL as idpointLib,
       vd.IDDEVISE as idDeviseLib,
       v.IDRESERVATION,
       vd.COMPTE,
       IDBCFILLE,
       vd.UNITE,
       POIDS,
       RISTOURNE,
       IDPREVISION,
       vd.PU,
       vd.REMISE,
       vd.TVA,
       PUACHAT,
       PUVENTE,
       PUREVIENT,
       IDREMISE,
       vd.REMISEMONTANT,
       vd.PHOTO,
       QTE_TMP,
       vd.REFERENCE,
       ing.TYPEPRODUIT,tp.VAL as TYPEPRODUITLIB,
       cli.IDPROVINCE,pro.VAL as IDPROVINCELIB,
       MONTANT,
       montantNonRemise,
       montantRemiseSansTva,
       montantHT,
       puRemise,
       montantHTAr,
       montantTva,
       montantTvaAr,
       montantTTC,
       montantTTCAr,
       montantTTCAr as montantTotal,
       montantTTCAr as montant_Total,
       cast((montantHTAr - NVL(v.FRAISLIVRAISON, 0) * NVL(ing.CALORIE, 0) * NVL(vd.QTE, 0))*(1+(nvl(vd.TVA,0)/100))*(1-(nvl(v.REMISE,0)/100)) as number(30,2)) as putotal,
       montantRevient,
       cast((NVL(v.FRAISLIVRAISON, 0) * NVL(ing.CALORIE, 0) * NVL(vd.QTE, 0))*(1+(nvl(vd.TVA,0)/100)) as number(30,2)) as montantlivraison,
       montantRevient as total_achat,
       cast(margeBrute as number(30,2)) as margeBrute,v.REMISE as remiseGlobal,v.IDCLIENT,cli.NOM as idclientlib,
       EXTRACT(MONTH FROM v.DATY) AS mois,
       TO_CHAR(v.DATY, 'Month', 'NLS_DATE_LANGUAGE = FRENCH') AS libelle_mois,
       EXTRACT(YEAR FROM v.DATY)  AS annee
from VenteDetCalc vd
         join vente v on v.ID = vd.IDVENTE
         left join AS_INGREDIENTS ing on vd.IDPRODUIT=ing.id
         left join categorieIngredient cat on ing.CATEGORIEINGREDIENT=cat.id
         left join magasin2 mag on mag.ID=v.IDMAGASIN
         left join point p1 on mag.IDPOINT=p1.ID
         left join CLIENT cli on cli.id=v.IDCLIENT
         left join PROVINCE pro on pro.ID=cli.IDPROVINCE
         left join TYPE_PRODUIT tp on tp.id=ing.TYPEPRODUIT
where v.ETAT>=11 order by annee desc,EXTRACT(MONTH FROM v.DATY) desc
;
-- [1073/1309] VENTEDETMERECATINGRCATCLIENT
CREATE OR REPLACE FORCE VIEW "VENTEDETMERECATINGRCATCLIENT" ("ID","IDVENTE","IDPRODUIT","IDORIGINE","QTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","COMPTE","IDBCFILLE","UNITE","POIDS","RISTOURNE","IDPREVISION","PU","REMISE","TVA","PUACHAT","PUVENTE","PUREVIENT","IDREMISE","IDCLIENT","CATCLIENT","CATEGORIEINGREDIENTS","IDPOINT") AS
select vd."ID",vd."IDVENTE",vd."IDPRODUIT",vd."IDORIGINE",vd."QTE",vd."IDDEVISE",vd."TAUXDECHANGE",vd."DESIGNATION",vd."COMPTE",vd."IDBCFILLE",vd."UNITE",vd."POIDS",vd."RISTOURNE",vd."IDPREVISION",vd."PU",vd."REMISE",vd."TVA",vd."PUACHAT",vd."PUVENTE",vd."PUREVIENT",vd."IDREMISE",c.id as idClient,tc.id as catClient,ing.CATEGORIEINGREDIENT as categorieIngredients,v.IDMAGASIN as idpoint from VENTE_DETAILS vd
    left join vente v on v.id=vd.IDVENTE
    left join client c on v.IDCLIENT=c.ID
    left join TYPECLIENT tc on tc.id=c.IDTYPECLIENT
    left join as_ingredients ing on ing.id=vd.IDPRODUIT
;
-- [1074/1309] VENTELUBRIFIANTLIB
CREATE OR REPLACE FORCE VIEW "VENTELUBRIFIANTLIB" ("ID","IDPRODUIT","IDPRODUITLIB","QTE","PU","TAUXREMISE","IDENCAISSEMENT","IDENCAISSEMENTLIB","IDMAGASIN","DATY","REMARQUE","IDMAGASINLIB","ETAT","ETATLIB","MONTANT") AS
SELECT 
v.ID ,
v.IDPRODUIT ,
p.VAL AS IDPRODUITLIB,
v.QTE ,
v.PU ,
v.TAUXREMISE ,
v.IDENCAISSEMENT ,
e.DESIGNATION AS IDENCAISSEMENTLIB,
v.IDMAGASIN ,
v.DATY ,
v.REMARQUE ,
v.IDMAGASINLIB,
v.ETAT ,
CASE 
	WHEN v.ETAT = 0 
	THEN 'ANNULEE'
	WHEN v.ETAT = 1 
	THEN 'CREE'
	WHEN v.ETAT = 11 
	THEN 'VISEE'
END AS ETATLIB ,
CAST(v.QTE * v.PU AS NUMBER(30,2)) AS montant
FROM VENTELUBRIFIANT v 
LEFT JOIN PRODUIT p ON v.IDPRODUIT = p.ID 
LEFT JOIN ENCAISSEMENT e ON v.IDENCAISSEMENT = e.ID 
LEFT JOIN MAGASIN m ON  v.IDMAGASIN  = m.ID
;
-- [1075/1309] VENTELUBRIFIANTLIBANNULE
CREATE OR REPLACE FORCE VIEW "VENTELUBRIFIANTLIBANNULE" ("ID","IDPRODUIT","IDPRODUITLIB","QTE","PU","TAUXREMISE","IDENCAISSEMENT","IDENCAISSEMENTLIB","IDMAGASIN","DATY","REMARQUE","IDMAGASINLIB","ETAT","ETATLIB") AS
SELECT 
v."ID",v."IDPRODUIT",v."IDPRODUITLIB",v."QTE",v."PU",v."TAUXREMISE",v."IDENCAISSEMENT",v."IDENCAISSEMENTLIB",v."IDMAGASIN",v."DATY",v."REMARQUE",v."IDMAGASINLIB",v."ETAT",v."ETATLIB"
 FROM VENTELUBRIFIANTLIB v 
 WHERE v.ETAT = 0
;
-- [1076/1309] VENTELUBRIFIANTLIBCREE
CREATE OR REPLACE FORCE VIEW "VENTELUBRIFIANTLIBCREE" ("ID","IDPRODUIT","IDPRODUITLIB","QTE","PU","TAUXREMISE","IDENCAISSEMENT","IDENCAISSEMENTLIB","IDMAGASIN","DATY","REMARQUE","IDMAGASINLIB","ETAT","ETATLIB") AS
SELECT 
v."ID",v."IDPRODUIT",v."IDPRODUITLIB",v."QTE",v."PU",v."TAUXREMISE",v."IDENCAISSEMENT",v."IDENCAISSEMENTLIB",v."IDMAGASIN",v."DATY",v."REMARQUE",v."IDMAGASINLIB",v."ETAT",v."ETATLIB"
 FROM VENTELUBRIFIANTLIB v 
 WHERE v.ETAT = 1
;
-- [1077/1309] VENTELUBRIFIANTLIBVISEE
CREATE OR REPLACE FORCE VIEW "VENTELUBRIFIANTLIBVISEE" ("ID","IDPRODUIT","IDPRODUITLIB","QTE","PU","TAUXREMISE","IDENCAISSEMENT","IDENCAISSEMENTLIB","IDMAGASIN","DATY","REMARQUE","IDMAGASINLIB","ETAT","ETATLIB") AS
SELECT 
v."ID",v."IDPRODUIT",v."IDPRODUITLIB",v."QTE",v."PU",v."TAUXREMISE",v."IDENCAISSEMENT",v."IDENCAISSEMENTLIB",v."IDMAGASIN",v."DATY",v."REMARQUE",v."IDMAGASINLIB",v."ETAT",v."ETATLIB"
 FROM VENTELUBRIFIANTLIB v 
 WHERE v.ETAT = 11
;
-- [1078/1309] VENTELUBRIFIANTLIB_CV
CREATE OR REPLACE FORCE VIEW "VENTELUBRIFIANTLIB_CV" ("ID","IDPRODUIT","IDPRODUITLIB","QTE","PU","TAUXREMISE","IDENCAISSEMENT","IDENCAISSEMENTLIB","IDMAGASIN","DATY","REMARQUE","IDMAGASINLIB","ETAT","ETATLIB") AS
SELECT 
v."ID",v."IDPRODUIT",v."IDPRODUITLIB",v."QTE",v."PU",v."TAUXREMISE",v."IDENCAISSEMENT",v."IDENCAISSEMENTLIB",v."IDMAGASIN",v."DATY",v."REMARQUE",v."IDMAGASINLIB",v."ETAT",v."ETATLIB"
FROM venteLubrifiantLib v 
WHERE v.ETAT != 0
;
-- [1079/1309] VENTELUBRIFIANT_VALIDEE
CREATE OR REPLACE FORCE VIEW "VENTELUBRIFIANT_VALIDEE" ("IDENCAISSEMENT","VENTELUBRIFIANT") AS
SELECT 
v.IDENCAISSEMENT ,
sum( nvl(v.QTE  * v.PU ,0) ) AS ventelubrifiant
FROM VENTELUBRIFIANT v 
WHERE v.ETAT > 1 
GROUP BY v.IDENCAISSEMENT
;
-- [1080/1309] VENTEMONTANTLEGER
CREATE OR REPLACE FORCE VIEW "VENTEMONTANTLEGER" ("ID","MONTANTTOTAL","MONTANTREMISE","FRAIS","MONTANTTOTALACHAT","MONTANTTVA","MONTANTTTC","IDDEVISE","TAUXDECHANGE","MONTANTTTCAR","MONTANTREVIENT","IDRESERVATION","POIDS","COLIS") AS
SELECT vd.IDVENTE AS ID,

       -- montanttotal : base apres remise % et remise Arbiochem, moins frais
       cast(SUM((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE) -
                (nvl(vd.remiseArbiochem, 0) * vd.QTE)) as number(30, 2))                                             AS montanttotal,

       -- montantremise : remise % + remise Arbiochem (montant total de la remise)
       cast(SUM((NVL(vd.QTE, 0) * NVL(vd.PU, 0))) -
            SUM((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0))) +
            SUM(nvl(vd.remiseArbiochem, 0) * vd.QTE) as number(30, 2))                                               AS montantremise,

       cast(sum(nvl(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(vd.QTE, 0)) as number(30, 5)   )                                                                                                    as frais,
       cast(SUM((NVL(vd.QTE, 0) * NVL(vd.PuAchat, 0))) as number(30, 2))                                             AS montanttotalachat,

       -- montantTva : calculee sur la base deja reduite de la remise Arbiochem
       cast(SUM(((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                 (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE) -
                 (nvl(vd.remiseArbiochem, 0) * vd.QTE)) * (NVL(VD.TVA, 0)) /
                100) as number(30, 2))                                                                               AS montantTva,

       -- montantTTC : montantTva + montanttotal (bases deja reduites de la remise Arbiochem)
       cast(SUM(((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                 (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE) -
                 (nvl(vd.remiseArbiochem, 0) * vd.QTE)) * (NVL(VD.TVA, 0)) / 100) +
            SUM((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE) -
                (nvl(vd.remiseArbiochem, 0) * vd.QTE)) as number(30, 2))                                             as montantTTC,

       NVL(vd.IDDEVISE, 'AR')                                                                                        AS IDDEVISE,
       NVL(avg(vd.tauxDeChange), 1)                                                                                  AS tauxDeChange,

       -- montantTTCAR : remise Arbiochem ajoutee en suivant le meme traitement que fraislivraison (structure d'origine conservee)
       cast(SUM((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0) -
                                                 (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE) -
                                                 (nvl(vd.remiseArbiochem, 0) * vd.QTE) *
                                                 NVL(VD.TAUXDECHANGE, 1)) *
                (NVL(VD.TVA, 0)) / 100) +
            SUM(((1 - nvl(vd.remise / 100, 0)) *
                 (NVL(vd.QTE, 0) * NVL(vd.PU, 0) - (nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE) -
                  (nvl(vd.remiseArbiochem, 0) * vd.QTE)) *
                 NVL(VD.TAUXDECHANGE, 1)) -
                ((nvl(v.fraislivraison, 0) * nvl(ing.CALORIE, 0) * vd.QTE))) as number(30, 2))                        as montantTTCAR,

       cast(sum(vd.PUREVIENT * vd.QTE) as number(20, 2))                                                             as montantRevient,
       v.IDRESERVATION,nvl(sum(ing.CALORIE* vd.QTE),0) as poids,sum(vd.QTE) as colis
FROM VENTE_DETAILS vd
         LEFT JOIN VENTE v ON v.ID = vd.IDVENTE
         left join AS_INGREDIENTS ing on ing.id = vd.IDPRODUIT
GROUP BY vd.IDVENTE, vd.IDDEVISE, v.IDRESERVATION
;
-- [1081/1309] COMPTA_SOUSECRITURE_LETTRE2
CREATE OR REPLACE FORCE VIEW "COMPTA_SOUSECRITURE_LETTRE2" ("ID","NUMERO","COMPTE","JOURNAL","IDJOURNAL","ECRITURE","DATY","CREDIT","DEBIT","DATECOMPTABLE","EXERCICE","REMARQUE","ETAT","IDMERE","HORSEXERCICE","OD","ORIGINE","TIERS","LIBELLEPIECE","COMPTE_AUX","RAISONSOCIAL","FOLIO","LETTRAGE","ANALYTIQUE","MONTANTRESTE","IDVENTE","MOTSCLESSS") AS
SELECT SQ.ID,SQ.NUMERO,SQ.COMPTE,SQ.JOURNAL,SQ.IDJOURNAL,SQ.ECRITURE,SQ.DATY,SQ.CREDIT,SQ.DEBIT,SQ.DATECOMPTABLE,SQ.EXERCICE,SQ.REMARQUE,SQ.ETAT,SQ.IDMERE,SQ.HORSEXERCICE,SQ.OD,SQ.ORIGINE,SQ.TIERS,SQ.LIBELLEPIECE,SQ.COMPTE_AUX,SQ.RAISONSOCIAL,SQ.FOLIO,SQ.LETTRAGE,SQ.ANALYTIQUE,SQ.MONTANTRESTE,SQ.IDVENTE,
       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(NUMERO),'') || ' | ' || NVL(TO_CHAR(COMPTE),'') || ' | ' || NVL(TO_CHAR(JOURNAL),'') || ' | ' || NVL(TO_CHAR(IDJOURNAL),'') || ' | ' || NVL(TO_CHAR(ECRITURE),'') || ' | ' || NVL(TO_CHAR(DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(CREDIT),'') || ' | ' || NVL(TO_CHAR(DEBIT),'') || ' | ' || NVL(TO_CHAR(DATECOMPTABLE,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(EXERCICE),'') || ' | ' || NVL(TO_CHAR(REMARQUE),'') || ' | ' || NVL(TO_CHAR(ETAT),'') || ' | ' || NVL(TO_CHAR(IDMERE),'') || ' | ' || NVL(TO_CHAR(HORSEXERCICE),'') || ' | ' || NVL(TO_CHAR(OD),'') || ' | ' || NVL(TO_CHAR(ORIGINE),'') || ' | ' || NVL(TO_CHAR(TIERS),'') || ' | ' || NVL(TO_CHAR(LIBELLEPIECE),'') || ' | ' || NVL(TO_CHAR(COMPTE_AUX),'') || ' | ' || NVL(TO_CHAR(RAISONSOCIAL),'') || ' | ' || NVL(TO_CHAR(FOLIO),'') || ' | ' || NVL(TO_CHAR(LETTRAGE),'') || ' | ' || NVL(TO_CHAR(ANALYTIQUE),'') || ' | ' || NVL(TO_CHAR(MONTANTRESTE),'') || ' | ' || NVL(TO_CHAR(IDVENTE),'')) AS MOTSCLESSS
FROM (

SELECT
             lib.ID, lib.NUMERO, lib.COMPTE, lib.JOURNAL, lib.IDJOURNAL,
             lib.ECRITURE, lib.DATY, lib.CREDIT, lib.DEBIT, lib.DATECOMPTABLE,
             lib.EXERCICE, lib.REMARQUE, lib.ETAT, lib.IDMERE,
             lib.HORSEXERCICE, lib.OD, lib.ORIGINE, lib.TIERS,
             lib.LIBELLEPIECE, lib.COMPTE_AUX, lib.RAISONSOCIAL,
             lib.FOLIO, lib.LETTRAGE, lib.ANALYTIQUE,
             cast(nvl(V2.MONTANTTTC, 0) - nvl(mv.montant, 0) - nvl(ACG.MONTANTTTCAR-acg.MONTANTPAYEAR, 0) AS number(30, 5)) AS MONTANTRESTE,
             v.id as idVente
         FROM COMPTA_SOUSECRITURE_LIB_2 lib
                  JOIN VENTE v ON v.ID = lib.IDOBJET
                  JOIN VENTEMONTANTLEGER v2 ON v2.ID = v.ID
         		  LEFT JOIN LIAISONPAIEMENTTOTAL mv ON v.id = mv.id2
                  LEFT JOIN AVOIRFCMONTANT ACG on ACG.IDVENTE = v.ID
                  
                  UNION ALL
                  
                  
         -- CAS 2 : MOUVEMENTCAISSE ? VENTE
         SELECT
             lib.ID, lib.NUMERO, lib.COMPTE, lib.JOURNAL, lib.IDJOURNAL,
             lib.ECRITURE, lib.DATY, lib.CREDIT, lib.DEBIT, lib.DATECOMPTABLE,
             lib.EXERCICE, lib.REMARQUE, lib.ETAT, lib.IDMERE,
             lib.HORSEXERCICE, lib.OD, mvt.IDORIGINE, lib.TIERS,
             lib.LIBELLEPIECE, lib.COMPTE_AUX, lib.RAISONSOCIAL,
             lib.FOLIO, lib.LETTRAGE, lib.ANALYTIQUE,
             0 AS MONTANTRESTE,
             mvt.IDORIGINE as idVente
         FROM COMPTA_SOUSECRITURE_LIB_2 lib
                  JOIN MOUVEMENTCAISSE mvt ON mvt.ID = lib.IDOBJET
                  WHERE  EXISTS (SELECT 1 FROM VENTE v WHERE v.ID = mvt.IDORIGINE)

         UNION ALL

         -- CAS 3 : FACTURE FOURNISSEUR
         SELECT
             lib.ID, lib.NUMERO, lib.COMPTE, lib.JOURNAL, lib.IDJOURNAL,
             lib.ECRITURE, lib.DATY, lib.CREDIT, lib.DEBIT, lib.DATECOMPTABLE,
             lib.EXERCICE, lib.REMARQUE, lib.ETAT, lib.IDMERE,
             lib.HORSEXERCICE, lib.OD, lib.ORIGINE, lib.TIERS,
             lib.LIBELLEPIECE, lib.COMPTE_AUX, lib.RAISONSOCIAL,
             lib.FOLIO, lib.LETTRAGE, lib.ANALYTIQUE,
             CAST(nvl((cast(f3.MONTANTTTC-nvl(mv.debit,0) AS number(30,5)) * cast(nvl(f3.tauxdechange,0) AS  number(30,5))),0)  AS NUMBER(30,5))  AS MONTANTRESTE,
             v.ID as idVente
         FROM COMPTA_SOUSECRITURE_LIB_2 lib
                  JOIN FACTUREFOURNISSEUR  v ON v.ID = lib.IDOBJET
                  JOIN FACTUREFOURNISSEURMONTANT f3 ON v.ID = f3.id
    			  LEFT JOIN mouvementcaisseGroupeFacture mv ON v.id=mv.IDORIGINE

         UNION ALL

         -- CAS 4 : ECRITURE COMPTABLE SANS LIEN AVEC VENTE NI FACTURE FOURNISSEUR
         SELECT
             lib.ID, lib.NUMERO, lib.COMPTE, lib.JOURNAL, lib.IDJOURNAL,
             lib.ECRITURE, lib.DATY, lib.CREDIT, lib.DEBIT, lib.DATECOMPTABLE,
             lib.EXERCICE, lib.REMARQUE, lib.ETAT, lib.IDMERE,
             lib.HORSEXERCICE, lib.OD, lib.ORIGINE, lib.TIERS,
             lib.LIBELLEPIECE, lib.COMPTE_AUX, lib.RAISONSOCIAL,
             lib.FOLIO, lib.LETTRAGE, lib.ANALYTIQUE,
             NULL AS MONTANTRESTE,
             NULL AS idVente
         FROM COMPTA_SOUSECRITURE_LIB_2 lib
         WHERE NOT  EXISTS (SELECT 1 FROM VENTE v WHERE v.ID = lib.IDOBJET)
         AND NOT EXISTS (SELECT 1 FROM FACTUREFOURNISSEUR f WHERE f.ID = lib.IDOBJET )
                ) SQ
order by IDVENTE desc
;
-- [1082/1309] VENTE_CPL_BC_VISEE
CREATE OR REPLACE FORCE VIEW "VENTE_CPL_BC_VISEE" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","CLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","IDORIGINE","MONTANTAVOIR") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       m.VAL AS IDMAGASINLIB,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       CASE
           WHEN v.ETAT = 1 THEN 'CREE'
           WHEN v.ETAT = 11 THEN 'VISEE'
           WHEN v.ETAT = 0 THEN 'ANNULEE'
           END
             AS ETATLIB,
       v2.MONTANTTOTAL,
       v2.IDDEVISE,
       v.IDCLIENT,
       c.NOM AS CLIENTLIB,
       cast(V2.MONTANTTVA as number(30,2)) as MONTANTTVA,
       cast(V2.MONTANTTTC as number(30,2)) as montantttc,
       cast(V2.MONTANTTTCAR as number(30,2)) as MONTANTTTCAR,
       cast(nvl(mv.MONTANT,0)-nvl(ACG.MONTANTPAYEar, 0) AS NUMBER(30,2)) AS montantpaye,
       cast(V2.MONTANTTTC-nvl(mv.MONTANT,0)-nvl(ACG.MONTANTTTCAR, 0)+nvl(acg.MONTANTPAYEAR,0) AS NUMBER(30,2)) AS montantreste,
       nvl(ACG.MONTANTTTCAR, 0)  as avoir,
       v2.tauxDeChange AS tauxDeChange,v2.MONTANTREVIENT,cast((V2.MONTANTTTCAR-v2.MONTANTREVIENT) as number(20,2))  as margeBrute,
       v.IDRESERVATION,
       v.idorigine as IDORIGINE,
       cast(nvl(ACG.MONTANTTTCAR, 0)  as NUMBER(30,2)) as montantAvoir
FROM VENTE v
         LEFT JOIN CLIENT c ON c.ID = v.IDCLIENT
         LEFT JOIN MAGASIN m ON m.ID = v.IDMAGASIN
         JOIN VENTEMONTANTLEGER v2 ON v2.ID = v.ID
         LEFT JOIN LIAISONPAIEMENTTOTAL mv ON v.id=mv.ID2
         LEFT JOIN AVOIRFCMONTANT ACG on ACG.IDVENTE = v.ID
         --left join AS_BONDELIVRAISON_CLIENT asbl on asbl.ID = v.IDORIGINE
where v.ETAT = 11
;
-- [1083/1309] VENTE_DETAILS_BC
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_BC" ("IDPRODUIT","PU","QTE","PUACHAT","TVA") AS
SELECT 
	bcf.PRODUIT AS idproduit,
	bcf.PU AS PU,
	bcf.QUANTITE AS QTE,
	p.PUACHAT AS PUACHAT,
	bcf.TVA AS tva
FROM 
BONDECOMMANDE_CLIENT_FILLE bcf JOIN 
PRODUIT p ON p.ID =bcf.PRODUIT
;
-- [1084/1309] VENTE_DETAILS_CPL_2
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_CPL_2" ("ID","IDVENTE","IDVENTELIB","IDPRODUIT","IDPRODUITLIB","IDORIGINE","QTE","PU","PUTOTAL","PUTOTALACHAT","PUREVIENT","IDCATEGORIE","IDCATEGORIELIB","DATY","IDMAGASIN","IDMAGASINLIB","IDPOINT","IDPOINTLIB","IDDEVISE","IDDEVISELIB","IDRESERVATION","IDBCFILLE","TYPEPRODUIT","TYPEPRODUITLIB","IDPROVINCE","IDPROVINCELIB","MOTSCLESSS") AS
SELECT SQ.ID,
       SQ.IDVENTE,
       SQ.IDVENTELIB,
       SQ.IDPRODUIT,
       SQ.IDPRODUITLIB,
       SQ.IDORIGINE,
       SQ.QTE,
       SQ.PU,
       SQ.PUTOTAL,
       SQ.PUTOTALACHAT,
       SQ.PUREVIENT,
       SQ.IDCATEGORIE,
       SQ.IDCATEGORIELIB,
       SQ.DATY,
       SQ.IDMAGASIN,
       SQ.IDMAGASINLIB,
       SQ.IDPOINT,
       SQ.IDPOINTLIB,
       SQ.IDDEVISE,
       SQ.IDDEVISELIB,
       SQ.IDRESERVATION,
       SQ.IDBCFILLE,
       SQ.TYPEPRODUIT,
       SQ.TYPEPRODUITLIB,
       SQ.IDPROVINCE,
       SQ.IDPROVINCELIB,
       (NVL(TO_CHAR(SQ.ID), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDVENTE), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDVENTELIB), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDPRODUIT), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDPRODUITLIB), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDORIGINE), '') || ' | ' ||
        NVL(TO_CHAR(SQ.QTE), '') || ' | ' ||
        NVL(TO_CHAR(SQ.PU), '') || ' | ' ||
        NVL(TO_CHAR(SQ.PUTOTAL), '') || ' | ' ||
        NVL(TO_CHAR(SQ.PUTOTALACHAT), '') || ' | ' ||
        NVL(TO_CHAR(SQ.PUREVIENT), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDCATEGORIE), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDCATEGORIELIB), '') || ' | ' ||
        NVL(TO_CHAR(SQ.DATY, 'YYYY-MM-DD HH24:MI:SS'), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDMAGASIN), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDMAGASINLIB), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDPOINT), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDPOINTLIB), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDDEVISE), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDDEVISELIB), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDRESERVATION), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDBCFILLE), '') || ' | ' ||
        NVL(TO_CHAR(SQ.TYPEPRODUIT), '') || ' | ' ||
        NVL(TO_CHAR(SQ.TYPEPRODUITLIB), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDPROVINCE), '') || ' | ' ||
        NVL(TO_CHAR(SQ.IDPROVINCELIB), '')) AS MOTSCLESSS
FROM (
         SELECT vd.ID,
                vd.IDVENTE,
                v.DESIGNATION                                                      AS IDVENTELIB,
                vd.IDPRODUIT,
                p.LIBELLEVENTE                                                     AS IDPRODUITLIB,
                vd.IDORIGINE,
                vd.QTE,
                NVL(vd.PU, 0)                                                      AS PU,
                -- Formule de PUTOTAL aligne?e sur le MONTANTTTC de la vue de?taille?e
                CAST(
                    -- Partie HT avec de?duction des frais
                        ((NVL(vd.PU, 0) * (1 - NVL(vd.REMISE, 0) / 100)) * vd.QTE
                            - NVL(v.FRAISLIVRAISON, 0) * NVL(p.CALORIE, 0) * NVL(vd.QTE, 0))
                            +
                            -- Partie TVA applique?e sur cette me?me base HT modifie?e
                        (((NVL(vd.PU, 0) * (1 - NVL(vd.REMISE, 0) / 100)) * vd.QTE
                            - NVL(v.FRAISLIVRAISON, 0) * NVL(p.CALORIE, 0) * NVL(vd.QTE, 0)) * NVL(vd.TVA, 0) / 100)
                    AS NUMBER(30,2)
                )                                                                  AS PUTOTAL,
                CAST(NVL(vd.PUACHAT * vd.QTE, 0) AS NUMBER(30, 2))                  AS PUTOTALACHAT,
                CAST(NVL(vd.PU * vd.QTE, 0) - NVL(vd.PUACHAT * vd.QTE, 0) AS NUMBER(30, 2)) AS PUREVIENT,
                cat.ID                                                             AS IDCATEGORIE,
                cat.VAL                                                            AS IDCATEGORIELIB,
                v.DATY                                                             AS DATY,
                m.ID                                                               AS IDMAGASIN,
                m.VAL                                                              AS IDMAGASINLIB,
                p1.ID                                                              AS IDPOINT,
                p1.VAL                                                             AS IDPOINTLIB,
                vd.IDDEVISE,
                vd.IDDEVISE                                                        AS IDDEVISELIB,
                v.IDRESERVATION,
                vd.IDBCFILLE,
                p.TYPEPRODUIT,
                tp.VAL                                                             AS TYPEPRODUITLIB,
                cli.IDPROVINCE,
                pro.VAL                                                            AS IDPROVINCELIB
         FROM VENTE_DETAILS vd
                  LEFT JOIN VENTE v ON v.ID = vd.IDVENTE
                  LEFT JOIN MAGASIN2 m ON m.ID = v.IDMAGASIN
                  LEFT JOIN AS_INGREDIENTS p ON p.ID = vd.IDPRODUIT
                  LEFT JOIN POINT p1 ON p1.ID = m.IDPOINT
                  LEFT JOIN CATEGORIEINGREDIENT cat ON p.CATEGORIEINGREDIENT = cat.ID
                  LEFT JOIN TYPE_PRODUIT tp ON tp.ID = p.TYPEPRODUIT
                  LEFT JOIN CLIENT cli ON cli.ID = v.IDCLIENT
                  LEFT JOIN PROVINCE pro ON pro.ID = cli.IDPROVINCE
     ) SQ
;
-- [1085/1309] VENTE_CPL_ANALYSEF
CREATE OR REPLACE FORCE VIEW "VENTE_CPL_ANALYSEF" ("ID","IDVENTE","IDVENTELIB","IDPRODUIT","IDPRODUITLIB","IDORIGINE","QTE","PU","PUTOTAL","PUTOTALACHAT","PUREVIENT","CATEGORIEINGREDIENT","IDCATEGORIELIB","IDMAGASIN","IDMAGASINLIB","IDPOINT","IDPOINTLIB","IDDEVISE","IDDEVISELIB","IDRESERVATION","DATY") AS
select vd.ID,
       vd.IDVENTE,
       vd.IDVENTELIB,
       vd.IDPRODUIT,
       ai.libelle as idproduitlib,
       vd.IDORIGINE,
       vd.QTE,
       vd.PU,
       vd.PUTOTAL,
       vd.PUTOTALACHAT,
       vd.PUREVIENT,
       ai.CATEGORIEINGREDIENT,
       cat.val as idCategorieLib,
       vd.IDMAGASIN,
       vd.IDMAGASINLIB,
       vd.IDPOINT,
       vd.IDPOINTLIB,
       vd.IDDEVISE,
       vd.IDDEVISELIB,
       vd.IDRESERVATION,
       v.DATY
from VENTE_DETAILS_CPL_2 vd
         LEFT JOIN VENTE v ON v.ID = vd.IDVENTE
         LEFT JOIN AS_INGREDIENTS ai ON ai.id = vd.IDPRODUIT
         LEFT JOIN CATEGORIEINGREDIENT cat ON cat.id = ai.CATEGORIEINGREDIENT
WHERE v.ETAT >= 11
;
-- [1086/1309] VENTE_DETAILS_CPL_2_VISEE
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_CPL_2_VISEE" ("ID","IDVENTE","IDVENTELIB","IDPRODUIT","IDPRODUITLIB","IDORIGINE","QTE","PU","PUTOTAL","PUTOTALACHAT","PUREVIENT","IDCATEGORIE","IDCATEGORIELIB","DATY","IDMAGASIN","IDMAGASINLIB","IDPOINT","IDPOINTLIB","IDDEVISE","IDDEVISELIB","IDRESERVATION","IDBCFILLE","SUM_QTE","MONTANTTOTAL","MONTANT_TOTAL","IDCLIENT","TOTAL_ACHAT","TYPEPRODUIT","TYPEPRODUITLIB","IDPROVINCE","IDPROVINCELIB") AS
SELECT VD.ID,
       VD.IDVENTE,
       VD.IDVENTELIB,
       VD.IDPRODUIT,
       VD.IDPRODUITLIB,
       VD.IDORIGINE,
       VD.QTE,
       VD.PU,
       VD.PUTOTAL,
       VD.PUTOTALACHAT,
       VD.PUREVIENT,
       VD.IDCATEGORIE,
       VD.IDCATEGORIELIB,
       VD.DATY,
       VD.IDMAGASIN,
       VD.IDMAGASINLIB,
       VD.IDPOINT,
       VD.IDPOINTLIB,
       VD.IDDEVISE,
       VD.IDDEVISELIB,
       VD.IDRESERVATION,
       VD.IDBCFILLE,
       SUM(VD.QTE) OVER ()                            AS SUM_QTE,
       SUM(VD.PUTOTAL) OVER ()                        AS MONTANTTOTAL,
       SUM(VD.PUTOTAL) OVER ()                        AS MONTANT_TOTAL,
       V.IDCLIENT,
       SUM(VD.PUTOTAL) OVER (PARTITION BY V.IDCLIENT) AS TOTAL_ACHAT,
       VD.TYPEPRODUIT,
       VD.TYPEPRODUITLIB,
       VD.IDPROVINCE,
       VD.IDPROVINCELIB
FROM VENTE_DETAILS_CPL_2 VD
         LEFT JOIN VENTE V ON V.ID = VD.IDVENTE
WHERE V.ETAT >= 11
;
-- [1087/1309] CA_ANNEE_VIEW
CREATE OR REPLACE FORCE VIEW "CA_ANNEE_VIEW" ("MONTANT","ANNEE","MOIS") AS
WITH deja AS (
  SELECT
    SUM(montant) AS montant,
    TO_NUMBER(annee) AS annee,
    TO_NUMBER(mois)  AS mois
  FROM ca_annee_anterieur
  GROUP BY TO_NUMBER(annee), TO_NUMBER(mois)
),
recalc AS (
  SELECT
    EXTRACT(YEAR  FROM daty) AS annee,
    EXTRACT(MONTH FROM daty) AS mois,
    SUM(putotal) AS montant
  FROM vente_details_cpl_2_visee
  GROUP BY EXTRACT(YEAR  FROM daty), EXTRACT(MONTH FROM daty)
),
manquants AS (
  SELECT r.montant, r.annee, r.mois
  FROM recalc r
  WHERE NOT EXISTS (
    SELECT 1
    FROM deja d
    WHERE d.annee = r.annee
      AND d.mois  = r.mois
  )
)
SELECT montant, annee, mois FROM deja
UNION ALL
SELECT montant, annee, mois FROM manquants
;
-- [1088/1309] CA_ANNEE_MOIS
CREATE OR REPLACE FORCE VIEW "CA_ANNEE_MOIS" ("ANNEE","JANVIER","FEVRIER","MARS","AVRIL","MAI","JUIN","JUILLET","AOUT","SEPTEMBRE","OCTOBRE","NOVEMBRE","DECEMBRE") AS
SELECT
    annee,
    SUM(CASE WHEN mois = 1 THEN montant ELSE 0 END) AS janvier,
    SUM(CASE WHEN mois = 2 THEN montant ELSE 0 END) AS fevrier,
    SUM(CASE WHEN mois = 3 THEN montant ELSE 0 END) AS mars,
    SUM(CASE WHEN mois = 4 THEN montant ELSE 0 END) AS avril,
    SUM(CASE WHEN mois = 5 THEN montant ELSE 0 END) AS mai,
    SUM(CASE WHEN mois = 6 THEN montant ELSE 0 END) AS juin,
    SUM(CASE WHEN mois = 7 THEN montant ELSE 0 END) AS juillet,
    SUM(CASE WHEN mois = 8 THEN montant ELSE 0 END) AS aout,
    SUM(CASE WHEN mois = 9 THEN montant ELSE 0 END) AS septembre,
    SUM(CASE WHEN mois = 10 THEN montant ELSE 0 END) AS octobre,
    SUM(CASE WHEN mois = 11 THEN montant ELSE 0 END) AS novembre,
    SUM(CASE WHEN mois = 12 THEN montant ELSE 0 END) AS decembre
FROM CA_ANNEE_VIEW
GROUP BY annee
ORDER BY annee
;
-- [1089/1309] CA_JOURNALIER
CREATE OR REPLACE FORCE VIEW "CA_JOURNALIER" ("MONTANT","ANNEE","MOIS","MOISLIB","DATY") AS
WITH agg AS (
  SELECT
    TRUNC(daty) AS jour,
    SUM(putotal) AS montant
  FROM vente_details_cpl_2_visee
  GROUP BY TRUNC(daty)
)
SELECT
    a.montant,
    EXTRACT(YEAR  FROM a.jour) AS annee,
    EXTRACT(MONTH FROM a.jour) AS mois,
    TO_CHAR(a.jour, 'Month', 'NLS_DATE_LANGUAGE=FRENCH') AS moislib,
    a.jour AS daty
FROM agg a
WHERE NOT EXISTS (
    SELECT 1
    FROM ca_jour j
    WHERE j.daty = a.jour
)
;
-- [1090/1309] CA_JOURNALIER_UNION
CREATE OR REPLACE FORCE VIEW "CA_JOURNALIER_UNION" ("MONTANT","ANNEE","MOIS","DATY") AS
select cj.MONTANT,
       cj.ANNEE,
       cj.MOIS,
       cj.DATY
from ca_jour cj
union all
select cj.montant, annee, mois, daty
from ca_journalier cj
;
-- [1091/1309] CA_JOURNALIER_UNION_GP
CREATE OR REPLACE FORCE VIEW "CA_JOURNALIER_UNION_GP" ("MONTANT","ANNEE","MOIS","DATY") AS
select sum(montant) as montant, annee, mois, daty from ca_journalier_union group by annee, mois, daty
;
-- [1092/1309] CA_MENSUEL
CREATE OR REPLACE FORCE VIEW "CA_MENSUEL" ("ANNEE","MOIS","MOISLIB","MONTANT") AS
WITH agg AS (
  SELECT
    TRUNC(daty) AS jour,
    CAST(SUM(putotal) AS NUMBER(30,5))  AS montant
  FROM vente_details_cpl_2_visee
  GROUP BY TRUNC(daty)
),
agg_mois AS (
  SELECT
    EXTRACT(YEAR FROM jour)  AS annee,
    EXTRACT(MONTH FROM jour) AS mois,
    TO_CHAR(jour, 'Month', 'NLS_DATE_LANGUAGE=FRENCH') AS moislib,
    CAST(SUM(montant)AS NUMBER(30,5)) AS montant
  FROM agg
  GROUP BY
    EXTRACT(YEAR FROM jour),
    EXTRACT(MONTH FROM jour),
    TO_CHAR(jour, 'Month', 'NLS_DATE_LANGUAGE=FRENCH')
)
SELECT ANNEE,MOIS,MOISLIB,MONTANT
FROM agg_mois m
WHERE NOT EXISTS (
    SELECT 1
    FROM ca_jour j
    WHERE EXTRACT(YEAR  FROM j.daty) = m.annee
      AND EXTRACT(MONTH FROM j.daty) = m.mois
)
;
-- [1093/1309] VENTE_DETAILS_LIB
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_LIB" ("ID","IDVENTE","IDVENTELIB","IDPRODUIT","IDPRODUITLIB","IDORIGINE","QTE","PU","PUTOTAL","PUACHAT","IDRESERVATION") AS
SELECT vd.ID,
       vd.IDVENTE,
       v.DESIGNATION    AS IDVENTELIB,
       vd.IDPRODUIT,
       p.LIBELLE            AS IDPRODUITLIB,
       vd.IDORIGINE,
       vd.QTE,
       vd.PU,
       cast((vd.QTE * vd.PU) as NUMBER(30,2)) AS puTotal,
       vd.PuAchat AS PUACHAT,
       v.IDRESERVATION
FROM VENTE_DETAILS vd
         LEFT JOIN VENTE v ON v.ID = vd.IDVENTE
         LEFT JOIN AS_INGREDIENTS p ON p.ID = vd.IDPRODUIT
;
-- [1094/1309] VENTE_DETAILS_POIDS_ING
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_POIDS_ING" ("ID","IDVENTE","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","COMPTE","PUREVIENT","IDBCFILLE","UNITE","UNITELIB","PUNET","MONTANTHT","MONTANTTTC","MONTANTTVA","MONTANTREMISE","MONTANT","POIDS","RESTE","FRAIS","IDPRODUITLIB","DATY","DATYPREVU","IDDEVISELIB","IDCATEGORIELIB","CATEGORIEPRODUITLIB","PUTOTAL","IDCLIENTLIB","RISTOURNE","IDPREVISION","IDRESERVATION","FRAISLIVRAISON","CALORIE","PUINGREDIENT","CONTENUE","UNITE2","MONTANTREMISER","IDREMISE","REMISEARBIOCHEM","RISTOURNEARBIOCHEM") AS
SELECT
    p.ID,
    p.IDVENTE,
    p.IDPRODUIT,
    p.IDORIGINE,
    CAST(p.QTE AS NUMBER(38, 2))                                              AS QTE,
    p.PU,
    p.REMISE,
    p.TVA,
    p.PUACHAT,
    p.PUVENTE,
    p.IDDEVISE,
    p.TAUXDECHANGE,
    p.DESIGNATION,
    p.COMPTE,
    p.PUREVIENT,
    p.IDBCFILLE,
    p.UNITE,
    u.VAL                                                                     AS UNITELIB,

    CAST(p.pu - (p.pu * p.remise / 100) + (p.pu * p.tva / 100)
        AS NUMBER(30, 5))                                                    AS PUNET,

    -- MONTANTHT : deduction remise % + remise Arbiochem (montant fixe par qte)
    CAST(((p.pu - (p.pu * p.remise / 100)) * p.qte
        - NVL(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)
        - (nvl(p.remiseArbiochem, 0) * p.qte))
        AS NUMBER(30, 5))                                                    AS MONTANTHT,

    -- MONTANTTTC : base (avec remise Arbiochem) + TVA calculee sur cette meme base
    CAST(
            ((p.pu - (p.pu * p.remise / 100)) * p.qte
                - NVL(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)
                - (nvl(p.remiseArbiochem, 0) * p.qte))
                + ((((p.pu * p.qte) - (p.pu * p.remise / 100) * p.qte)
                - NVL(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)
                - (nvl(p.remiseArbiochem, 0) * p.qte)) * p.tva / 100)
        AS NUMBER(30, 2)
    )                                                                         AS MONTANTTTC,

    -- MONTANTTVA : calculee sur la base HT deja reduite de la remise Arbiochem
    CAST(
            ((((p.pu * p.qte) - (p.pu * p.remise / 100) * p.qte)
                - NVL(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)
                - (nvl(p.remiseArbiochem, 0) * p.qte)) * p.tva / 100)
        AS NUMBER(30, 2)
    )                                                                         AS MONTANTTVA,

    -- MONTANTREMISE : remise % + remise Arbiochem (montant total de la remise)
    CAST(((p.pu * p.remise / 100) * p.qte) + (nvl(p.remiseArbiochem, 0) * p.qte)
        AS NUMBER(30, 5))                                                    AS MONTANTREMISE,

    CAST(p.pu * p.qte AS NUMBER(30, 5))                                       AS MONTANT,

    CAST(NVL(ing.CALORIE, 0) * NVL(p.QTE, 0) AS NUMBER(30, 5))                AS POIDS,
    (NVL(p.QTE, 0) - NVL(bl.QUANTITE, 0)) - NVL(avcf.qte, 0)                  AS RESTE,

    CAST(NVL(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)
        AS NUMBER(30, 5))                                                    AS FRAIS,

    nvl(ing.LIBELLEVENTE,ing.libelle)                                                          AS IDPRODUITLIB,
    v.DATY,
    v.DATYPREVU                                                               AS DATYPREVU,
    p.IDDEVISE                                                                AS IDDEVISELIB,
    c.VAL                                                                     AS IDCATEGORIELIB,
    c.VAL                                                                     AS CATEGORIEPRODUITLIB,

    -- PUTOTAL : meme formule que MONTANTTTC (avec remise Arbiochem)
    CAST(
            ((p.pu - (p.pu * p.remise / 100)) * p.qte
                - NVL(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)
                - (nvl(p.remiseArbiochem, 0) * p.qte))
                + ((((p.pu * p.qte) - (p.pu * p.remise / 100) * p.qte)
                - NVL(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)
                - (nvl(p.remiseArbiochem, 0) * p.qte)) * p.tva / 100)
        AS NUMBER(30, 2)
    )                                                                         AS PUTOTAL,

    cl.nom                                                                    AS IDCLIENTLIB,
    p.ristourne                                                               AS RISTOURNE,
    p.idprevision,
    v.IDRESERVATION,
    NVL(v.fraislivraison, 0)                                                  AS FRAISLIVRAISON,
    ing.calorie,
    CAST(p.pu / NVL(eq.QUANTITE, 1) AS NUMBER(30, 2))                        AS PUINGREDIENT,
    NVL(eq.QUANTITE, 1)                                                       AS CONTENUE,
    ing.unite2,

    -- MONTANTREMISER : montant net apres remise % + remise Arbiochem
    (p.pu * p.qte) - ((p.pu * p.remise / 100) * p.qte) - (nvl(p.remiseArbiochem, 0) * p.qte) AS MONTANTREMISER,

    p.IDREMISE,
    nvl(p.remiseArbiochem, 0)                                                 AS REMISEARBIOCHEM,
    nvl(p.ristourneArbiochem, 0)                                              AS RISTOURNEARBIOCHEM
FROM VENTE_DETAILS p
         LEFT JOIN VENTE v
                   ON v.id = p.IDVENTE
         LEFT JOIN AS_UNITE u
                   ON u.id = p.unite
         LEFT JOIN AS_INGREDIENTS ing
                   ON ing.ID = p.IDPRODUIT
         LEFT JOIN CLIENT cl
                   ON v.IDCLIENT = cl.ID
         LEFT JOIN CATEGORIEINGREDIENT c
                   ON ing.CATEGORIEINGREDIENT = c.ID
         LEFT JOIN EQUIVALENCEVENTE eq
                   ON eq.IDPRODUIT1 = p.IDPRODUIT
         LEFT JOIN BL_CLIENT_FILLE_grp_vente bl
                   ON bl.idventedetail = p.ID
         LEFT JOIN avoirfcfille_grp_viseee avcf
                   ON avcf.idventedetails = p.ID
;
-- [1095/1309] VENTE_DETAILS_QTE_GRP
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_QTE_GRP" ("IDBCFILLE","QTE") AS
SELECT idbcfille AS idbcfille,sum(qte) AS qte FROM VENTE_DETAILS_CPL_2_VISEE vd GROUP BY idbcfille
;
-- [1096/1309] BC_CLIENT_FILLE_CPL_LIB
CREATE OR REPLACE FORCE VIEW "BC_CLIENT_FILLE_CPL_LIB" ("ID","PRODUIT","IDBC","QUANTITE","PU","MONTANT","TVA","REMISE","IDDEVISE","UNITE","PRODUITLIB","COMPTE","QTERESTE","UNITELIB","MONTANTTOTAL","MONTANTDELAREMISE","MONTANTRISTOURNE","MONTANTREMISE","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","RISTOURNE","FRAISTRANSPORT","POIDSTOTAL","TAUX","REMISEARBIOCHEM","RISTOURNEARBIOCHEM") AS
SELECT bcf.ID,
       bcf.PRODUIT,
       bcf.IDBC,
       bcf.QUANTITE,
       bcf.PU,
       bcf.MONTANT,
       bcf.TVA,
       bcf.REMISE,
       bcf.IDDEVISE,
       bcf.UNITE,
       nvl(i.LIBELLEVENTE,i.libelle)                                                                                                                  AS PRODUITlib,
       i.compte_vente                                                                                                                                 AS compte,
       NVL(bcf.quantite, 0)    - NVL(vdbc.qte, 0)    AS qtereste,   -- nanova qte reste : atao moins qte vendu  avy aminy vente_details_qte_grp
       au.val                                                                                                                                         AS UNITELIB,
       cast(NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) as Number(30, 2))                                                                                   AS MONTANTTOTAL,
       cast(((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) as number(30, 2))                                                          as montantdelaremise,
       cast((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
            (bcf.ristourne / 100) as number(30, 2))                                                                                                   as montantristourne,
       cast(NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) -
            ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
             (bcf.ristourne / 100)) -
            nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0) as number(30, 2))                                                                    as montantremise,
       CAST(
               (((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) -
                 (((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) +
                  ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) -
                    ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) * (bcf.ristourne / 100))) -
                 nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) *
                (nvl(bcf.TVA, 0) / 100))
           AS NUMBER(30, 2)
       )                                                                                                                                              AS MONTANTTVA,
       cast((cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) -
             (cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) *
              nvl(bcf.ristourne, 0) /
              100) - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) + (nvl(bcf.TVA, 0) / 100) *
                                                                             (cast((bcf.quantite * bcf.PU) -
                                                                                   ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                   100 as NUMBER(30, 2)) -
                                                                              (cast((bcf.quantite * bcf.PU) -
                                                                                    ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                    100 as NUMBER(30, 2)) *
                                                                               nvl(bcf.ristourne, 0) / 100) -
                                                                              nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) as number(30, 2)) AS MONTANTTTC,
       cast(((cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) -
              (cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) *
               nvl(bcf.ristourne, 0) /
               100) - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) + (nvl(bcf.TVA, 0) / 100) *
                                                                              (cast((bcf.quantite * bcf.PU) -
                                                                                    ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                    100 as NUMBER(30, 2)) -
                                                                               (cast((bcf.quantite * bcf.PU) -
                                                                                     ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                     100 as NUMBER(30, 2)) *
                                                                                nvl(bcf.ristourne, 0) / 100) -
                                                                               nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)))*bcf.TAUX as number(30, 2)) AS MONTANTTTCAR,
       bcf.ristourne,
       nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)                                                                                           as fraistransport,
       CAST(NVL(i.CALORIE * bcf.QUANTITE,0) AS NUMBER(30,2)) AS poidstotal,bcf.taux,
       bcf.remiseArbiochem,
       bcf.ristourneArbiochem
FROM bondecommande_client_fille bcf
         left JOIN as_ingredients i ON i.id = bcf.PRODUIT
         LEFT JOIN vente_details_qte_grp vdbc ON bcf.id = vdbc.idbcfille
         LEFT JOIN AS_UNITE au ON au.id = i.unite
         LEFT JOIN BONDECOMMANDE_CLIENT bc on bc.id = bcf.IDBC
;
-- [1097/1309] BC_CLIENT_FILLE_CPL_LIB2
CREATE OR REPLACE FORCE VIEW "BC_CLIENT_FILLE_CPL_LIB2" ("ID","PRODUIT","IDBC","QUANTITE","PU","MONTANT","TVA","REMISE","IDDEVISE","UNITE","PRODUITLIB","COMPTE","QTERESTE","UNITELIB","MONTANTTOTAL","MONTANTDELAREMISE","MONTANTRISTOURNE","MONTANTREMISE","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","RISTOURNE","FRAISTRANSPORT","POIDSTOTAL","TAUX","REMISEARBIOCHEM","RISTOURNEARBIOCHEM","QTELIVRE","QTEFACTURE") AS
SELECT bcf.ID,
       bcf.PRODUIT,
       bcf.IDBC,
       bcf.QUANTITE,
       bcf.PU,
       bcf.MONTANT,
       bcf.TVA,
       bcf.REMISE,
       bcf.IDDEVISE,
       bcf.UNITE,
       nvl(i.LIBELLEVENTE,i.libelle)                                                                                                                  AS PRODUITlib,
       i.compte_vente                                                                                                                                 AS compte,
       NVL(bcf.quantite, 0)    - NVL(vdbc.qte, 0)    AS qtereste,   -- nanova qte reste : atao moins qte vendu  avy aminy vente_details_qte_grp
       au.val                                                                                                                                         AS UNITELIB,
       cast(NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) as Number(30, 2))                                                                                   AS MONTANTTOTAL,
       -- montantRemise : remise classique (%) + remise Arbiochem (montant fixe par unite)
       cast((((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))+ (nvl(bcf.remiseArbiochem,0) * bcf.QUANTITE)) as number(30, 2))          as montantdelaremise,

       -- montantristourne : ristourne classique (%) + ristourne Arbiochem (montant fixe par unite)
       cast(
               ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
                (bcf.ristourne / 100))
                   + (nvl(bcf.ristourneArbiochem, 0) * bcf.QUANTITE)
           as number(30, 2)
       )                                                                                                                                              as montantristourne,

       -- montantremise : base HT nette = brut - remise% - ristourne% (incl. ristourneArbiochem) - frais transport - remiseArbiochem
       cast(
               NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)
                   - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))
                   - (
                   ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
                    (bcf.ristourne / 100))
                       + (nvl(bcf.ristourneArbiochem, 0) * bcf.QUANTITE)
                   )
                   - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)
                   - (nvl(bcf.remiseArbiochem, 0) * bcf.QUANTITE)
           as number(30, 2)
       )                                                                                                                                              as montantremise,

       -- MONTANTTVA : TVA calculee sur le nouveau montantremise (donc corrigee des montants Arbiochem)
       CAST(
               (
                   (NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)
                       - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))
                       - (
                        ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
                         (bcf.ristourne / 100))
                            + (nvl(bcf.ristourneArbiochem, 0) * bcf.QUANTITE)
                        )
                       - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)
                       - (nvl(bcf.remiseArbiochem, 0) * bcf.QUANTITE)
                       ) * (nvl(bcf.TVA, 0) / 100)
                   )
           AS NUMBER(30, 2)
       )                                                                                                                                              AS MONTANTTVA,

       -- MONTANTTTC : montantremise (corrige) + MONTANTTVA (corrigee)
       cast(
               (
                   NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)
                       - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))
                       - (
                       ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
                        (bcf.ristourne / 100))
                           + (nvl(bcf.ristourneArbiochem, 0) * bcf.QUANTITE)
                       )
                       - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)
                       - (nvl(bcf.remiseArbiochem, 0) * bcf.QUANTITE)
                   )
                   + (
                   (
                       NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)
                           - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))
                           - (
                           ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
                            (bcf.ristourne / 100))
                               + (nvl(bcf.ristourneArbiochem, 0) * bcf.QUANTITE)
                           )
                           - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)
                           - (nvl(bcf.remiseArbiochem, 0) * bcf.QUANTITE)
                       ) * (nvl(bcf.TVA, 0) / 100)
                   )
           as number(30, 2)
       )                                                                                                                                              AS MONTANTTTC,

       -- MONTANTTTCAR : simplifie, les montants Arbiochem sont deja pris en compte en amont dans montantremise
       cast(
               (
                   (
                       NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)
                           - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))
                           - (
                           ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
                            (bcf.ristourne / 100))
                               + (nvl(bcf.ristourneArbiochem, 0) * bcf.QUANTITE)
                           )
                           - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)
                           - (nvl(bcf.remiseArbiochem, 0) * bcf.QUANTITE)
                       )
                       + (
                       (
                           NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)
                               - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))
                               - (
                               ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
                                (bcf.ristourne / 100))
                                   + (nvl(bcf.ristourneArbiochem, 0) * bcf.QUANTITE)
                               )
                               - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)
                               - (nvl(bcf.remiseArbiochem, 0) * bcf.QUANTITE)
                           ) * (nvl(bcf.TVA, 0) / 100)
                       )
                   ) * bcf.TAUX
           as number(30, 2)
       )                                                                                                                                              AS MONTANTTTCAR,

       bcf.ristourne,
       nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)                                                                                           as fraistransport,
       CAST(NVL(i.CALORIE * bcf.QUANTITE,0) AS NUMBER(30,2)) AS poidstotal,bcf.taux,
       nvl(bcf.remiseArbiochem,0) as remiseArbiochem,
       nvl(bcf.ristourneArbiochem,0) as ristourneArbiochem,
       cast(nvl(blf.QUANTITE,0) as number(30,2)) as qtelivre, cast(nvl(vdbc.qte,0) as number(30,2)) as qteFacture
FROM bondecommande_client_fille bcf
         left JOIN as_ingredients i ON i.id = bcf.PRODUIT
         LEFT JOIN vente_details_qte_grp vdbc ON bcf.id = vdbc.idbcfille
         LEFT JOIN AS_UNITE au ON au.id = i.unite
         LEFT JOIN BONDECOMMANDE_CLIENT bc on bc.id = bcf.IDBC
         left join as_BLClientFilleGrpBCFille blf on blf.IDBC_FILLE=bcf.id
;
-- [1098/1309] BC_CLIENT_FILLE_CPL_LIBB
CREATE OR REPLACE FORCE VIEW "BC_CLIENT_FILLE_CPL_LIBB" ("ID","PRODUIT","IDBC","QUANTITE","PU","MONTANTREMISE","MONTANTTOTAL","MONTANT","TVA","MONTANTTVA","REMISE","IDDEVISE","UNITE","UNITELIB","PRODUITLIB","COMPTE","QTERESTE") AS
SELECT
    bcf.ID,
    bcf.PRODUIT,
    bcf.IDBC,
    bcf.QUANTITE,
    bcf.PU,
    (nvl(nvl(bcf.QUANTITE,0)*nvl(bcf.PU,0),0)*bcf.REMISE)/100 as montantremise,
    nvl(bcf.QUANTITE,0)*nvl(bcf.PU,0)-((nvl(nvl(bcf.QUANTITE,0)*nvl(bcf.PU,0),0)*bcf.REMISE)/100)+((((nvl(bcf.QUANTITE,0)*nvl(bcf.PU,0)-(nvl(nvl(bcf.QUANTITE,0)*nvl(bcf.PU,0),0)*bcf.REMISE)/100)*bcf.tva)/100)) as montanttotal,
    bcf.MONTANT as montant,
    bcf.TVA,
    (((nvl(bcf.QUANTITE,0)*nvl(bcf.PU,0)-(nvl(nvl(bcf.QUANTITE,0)*nvl(bcf.PU,0),0)*bcf.REMISE)/100)*bcf.tva)/100) as montanttva,
    bcf.REMISE,
    bcf.IDDEVISE,
    bcf.UNITE,
    un.VAL as unitelib,
    i.LIBELLE AS PRODUITlib,
    i.compte_vente AS compte,
    GREATEST(NVL(bcf.quantite, 0) - NVL(vdbc.qte, 0), 0) AS qtereste
FROM
bondecommande_client_fille bcf
JOIN as_ingredients i ON i.id = bcf.PRODUIT
    left join AS_UNITE un on un.id=bcf.UNITE
LEFT JOIN vente_details_qte_grp vdbc ON bcf.id = vdbc.idbcfille
;
-- [1099/1309] BC_CLIENT_FILLE_CPL_LIB_PDF
CREATE OR REPLACE FORCE VIEW "BC_CLIENT_FILLE_CPL_LIB_PDF" ("ID","PRODUIT","IDBC","QUANTITE","PU","MONTANT","TVA","REMISE","IDDEVISE","UNITE","PRODUITLIB","COMPTE","QTERESTE","UNITELIB","MONTANTTOTAL","MONTANTDELAREMISE","MONTANTRISTOURNE","MONTANTREMISE","MONTANTTVA","MONTANTTTC","RISTOURNE","FRAISTRANSPORT","POIDSTOTAL","PUINGREDIENT","CONTENUE","UNITE2","REMISEARBIOCHEM") AS
SELECT bcf.ID,
       bcf.PRODUIT,
       bcf.IDBC,
       bcf.QUANTITE,
       bcf.PU,
       bcf.MONTANT,
       bcf.TVA,
       bcf.REMISE,
       bcf.IDDEVISE,
       bcf.UNITE,
       nvl(i.LIBELLEVENTE,i.libelle)                                                                                                                                      AS PRODUITlib,
       i.compte_vente                                                                                                                                 AS compte,
       NVL(bcf.quantite, 0)    - NVL(vdbc.qte, 0)    AS qtereste,   -- nanova qte reste : atao moins qte vendu  avy aminy vente_details_qte_grp
       au.val                                                                                                                                         AS UNITELIB,
       cast(NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) as Number(30, 2))                                                                                   AS MONTANTTOTAL,
       cast(((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) as number(30, 2))                                                          as montantdelaremise,
       cast((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
            (bcf.ristourne / 100) as number(30, 2))                                                                                                   as montantristourne,
       cast(NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) as number(30, 2))                                                                    as montantremise,
       CAST(
               (((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) -
                 (((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) +
                  ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) -
                    ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) * (bcf.ristourne / 100))) -
                 nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) *
                (nvl(bcf.TVA, 0) / 100))
           AS NUMBER(30, 2)
       )                                                                                                                                              AS MONTANTTVA,
       cast((cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) -
             (cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) *
              nvl(bcf.ristourne, 0) /
              100) - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) + (nvl(bcf.TVA, 0) / 100) *
                                                                             (cast((bcf.quantite * bcf.PU) -
                                                                                   ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                   100 as NUMBER(30, 2)) -
                                                                              (cast((bcf.quantite * bcf.PU) -
                                                                                    ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                    100 as NUMBER(30, 2)) *
                                                                               nvl(bcf.ristourne, 0) / 100) -
                                                                              nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) as number(30, 2)) AS MONTANTTTC,
       bcf.ristourne,
       nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)                                                                                           as fraistransport,
       CAST(NVL(i.CALORIE * bcf.QUANTITE,0) AS NUMBER(30,2)) AS poidstotal,
       CAST((bcf.pu/nvl(eq.QUANTITE,1)) AS NUMBER (30,2)) as puingredient,
       nvl(eq.QUANTITE,1) as contenue,
       i.UNITE2,
       bcf.REMISEARBIOCHEM 
FROM bondecommande_client_fille bcf
         left JOIN as_ingredients i ON i.id = bcf.PRODUIT
         LEFT JOIN vente_details_qte_grp vdbc ON bcf.id = vdbc.idbcfille
         LEFT JOIN AS_UNITE au ON au.id = i.unite
         LEFT JOIN BONDECOMMANDE_CLIENT bc on bc.id = bcf.IDBC
         LEFT JOIN EQUIVALENCEVENTE eq on eq.IDPRODUIT1=i.ID
;
-- [1100/1309] COMMANDEFILLE_CPL_LIB
CREATE OR REPLACE FORCE VIEW "COMMANDEFILLE_CPL_LIB" ("ID","PRODUIT","IDC","QUANTITE","PU","MONTANT","TVA","REMISE","IDDEVISE","UNITE","PRODUITLIB","COMPTE","QTERESTE","UNITELIB","MONTANTTOTAL","MONTANTDELAREMISE","MONTANTRISTOURNE","MONTANTREMISE","MONTANTTVA","MONTANTTTC","RISTOURNE","FRAISTRANSPORT","POIDSTOTAL","CALORIE") AS
SELECT bcf.ID,
       bcf.PRODUIT,
       bcf.IDC,
       bcf.QUANTITE,
       bcf.PU,
       bcf.MONTANT,
       bcf.TVA,
       bcf.REMISE,
       bcf.IDDEVISE,
       bcf.UNITE,
       nvl(i.LIBELLEVENTE,i.libelle)                                                                                                                                      AS PRODUITlib,
       i.compte_vente                                                                                                                                 AS compte,
       NVL(bcf.quantite, 0) - NVL(vdbc.qte, 0)                                                                                                        AS qtereste,
       au.val                                                                                                                                         AS UNITELIB,
       cast(NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) as Number(30, 2))                                                                                   AS MONTANTTOTAL,
       cast(((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) as number(30, 2))                                                          as montantdelaremise,
       cast((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
            (bcf.ristourne / 100) as number(30, 2))                                                                                                   as montantristourne,
       cast(NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) -
            ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) - ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) *
             (bcf.ristourne / 100)) -
            nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0) as number(30, 2))                                                                    as montantremise,
       CAST(
               (((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) -
                 (((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100)) +
                  ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0) -
                    ((NVL(bcf.PU, 0) * NVL(bcf.QUANTITE, 0)) * (bcf.REMISE / 100))) * (bcf.ristourne / 100))) -
                 nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) *
                (nvl(bcf.TVA, 0) / 100))
           AS NUMBER(30, 2)
       )                                                                                                                                              AS MONTANTTVA,
       cast((cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) -
             (cast((bcf.quantite * bcf.PU) - ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) / 100 as NUMBER(30, 2)) *
              nvl(bcf.ristourne, 0) /
              100) - nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) + (nvl(bcf.TVA, 0) / 100) *
                                                                             (cast((bcf.quantite * bcf.PU) -
                                                                                   ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                   100 as NUMBER(30, 2)) -
                                                                              (cast((bcf.quantite * bcf.PU) -
                                                                                    ((bcf.quantite * bcf.PU) * NVL(bcf.remise, 0)) /
                                                                                    100 as NUMBER(30, 2)) *
                                                                               nvl(bcf.ristourne, 0) / 100) -
                                                                              nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)) as number(30, 2)) AS MONTANTTTC,
       bcf.ristourne,
       nvl(i.CALORIE * bcf.QUANTITE * bc.fraislivraison, 0)                                                                                           as fraistransport,
       CAST(NVL(i.CALORIE * bcf.QUANTITE,0) AS NUMBER(30,2)) AS poidstotal,
       i.CALORIE
FROM COMMANDEFILLE bcf
         left JOIN as_ingredients i ON i.id = bcf.PRODUIT
         LEFT JOIN vente_details_qte_grp vdbc ON bcf.id = vdbc.idbcfille
         LEFT JOIN AS_UNITE au ON au.id = i.unite
         LEFT JOIN COMMANDE bc on bc.id = bcf.IDC
;
-- [1101/1309] COMMANDEMONTANT
CREATE OR REPLACE FORCE VIEW "COMMANDEMONTANT" ("ID","POIDSTOTAL","MONTANT","MONTANTREMISE","MONTANTRISTOURNE","FRAISTRANSPORT","MONTANTTOTAL","MONTANTTOTALACHAT","MONTANTTVA","MONTANTTTC","IDDEVISE","TAUXDECHANGE","MONTANTTTCAR") AS
SELECT v.ID,
       cast(SUM(poidstotal) as number(30, 2))                            AS poidstotal,
       cast(SUM(PU) as number(30, 2))                               AS montant,
       cast(SUM(MONTANTREMISE) as number(30, 2))                         as montantremise,
       cast(SUM(montantristourne) as number(30, 2))                      as montantristourne,
       cast(SUM(vd.fraistransport) as number(30, 2))                     as fraistransport,
       cast(SUM(montanttotal) as number(30, 2))                          AS montanttotal,
       cast(SUM((NVL(vd.QUANTITE, 0) * NVL(vd.PU, 0))) as number(30, 2)) AS montanttotalachat,
       cast(SUM(montanttva) as number(30, 2))                            AS montantTva,
       cast(SUM(vd.MONTANTTTC) as number(30, 2))                            as montantTTC,
       NVL(vd.IDDEVISE, 'AR')                                            AS IDDEVISE,
       NVL(avg(1), 1)                                      AS tauxDeChange,
       cast(SUM(MONTANTTTC) as number(30, 2))          as montantTTCAR
FROM COMMANDEFILLE_CPL_LIB vd
         LEFT JOIN COMMANDE v ON v.ID = vd.IDC
GROUP BY v.ID, vd.IDDEVISE
;
-- [1102/1309] COMMANDECPL
CREATE OR REPLACE FORCE VIEW "COMMANDECPL" ("ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","IDCLIENT","REFERENCE","IDDEVISE","IDMAGASIN","DATEBESOIN","IDPROFORMA","MODELIVRAISON","DATELIVRAISON","LIEULIVRAISON","FRAISLIVRAISON","IDMAGASINLIB","IDCLIENTLIB","ETATLIB","MODELIVRAISONLIB","MODEPAIEMENTLIB","MONTANTTTC","MOTSCLESSS") AS
SELECT CMD.ID,
       CMD.DATY,
       CMD.ETAT,
       CMD.REMARQUE,
       CMD.DESIGNATION,
       CMD.MODEPAIEMENT,
       CMD.IDCLIENT,
       CMD.REFERENCE,
       CMD.IDDEVISE,
       CMD.IDMAGASIN,
       CMD.DATEBESOIN,
       CMD.IDPROFORMA,
       CMD.MODELIVRAISON,
       CMD.DATELIVRAISON,
       CMD.LIEULIVRAISON,
       CMD.FRAISLIVRAISON,
       P.VAL   AS IDMAGASINLIB,
       CL.NOM  AS IDCLIENTLIB,
       CASE
           WHEN CMD.ETAT = 1 THEN 'CR&Eacute;&Eacute;E'
           WHEN CMD.ETAT = 11 THEN 'VIS&Eacute;E'
           WHEN CMD.ETAT = 0 THEN 'ANNUL&Eacute;E'
           ELSE 'Inconnu'
           END AS ETATLIB,
       CASE
           WHEN CMD.MODELIVRAISON = 1 THEN '<span style=color: green;>LIVRAISON</span>'
           WHEN CMD.MODELIVRAISON = 2 THEN '<span style=color: green;>RECUPERATION</span>'
           END AS MODELIVRAISONLIB,
       MP.VAL  AS MODEPAIEMENTLIB,
       CMM.MONTANTTTC,
       (
           CMD.ID || ' | ' || REFERENCE || ' | ' || CL.NOM || ' | ' || DESIGNATION || ' | ' || CMD.REMARQUE
           )   AS MOTSCLESSS
FROM COMMANDE CMD
         LEFT JOIN MAGASIN2 P
                   ON P.ID = CMD.IDMAGASIN
         LEFT JOIN CLIENT CL
                   ON CL.ID = CMD.IDCLIENT
         LEFT JOIN MODEPAIEMENT MP
                   ON MP.ID = CMD.MODEPAIEMENT
         LEFT JOIN COMMANDEMONTANT CMM
                   ON CMM.ID = CMD.ID
;
-- [1103/1309] VENTE_DETAILS_RESTE
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_RESTE" ("ID","IDPRODUIT","IDUNITE","UNITELIB","QTE","RESTE","IDVENTE","IDBCFILLE") AS
SELECT
    vd.id AS id,
    vd.idProduit,
    vd.UNITE as idunite,
    u.VAL AS unitelib,
    vd.qte AS QTE,
    nvl(vd.QTE,0) - nvl(bl.QUANTITE,0) - nvl(acf.QUANTITE,0) AS reste,
    vd.IDVENTE AS IDVENTE,
    vd.IDBCFILLE
FROM
    VENTE_DETAILS vd
        LEFT JOIN BL_CLIENT_FILLE_grp_vente bl ON vd.ID = bl.idventedetail
--         left join BL_CLIENT_FILLE_grp_bc bl2 ON vd.IDBCFILLE = bl2.idbc_fille
        left join AS_BL_CLIENT_FILLE_vise acf on vd.IDORIGINE = acf.ID
        LEFT JOIN AS_INGREDIENTS p ON p.id = vd.IDPRODUIT
        LEFT JOIN AS_UNITE u ON u.id = vd.unite
WHERE p.actif = 1
;
-- [1104/1309] VENTE_DETAILS_SAISIE
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_SAISIE" ("ID","IDVENTE","IDPRODUIT","DESIGNATION","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","COMPTE","IDBCFILLE") AS
SELECT
         id,
         IDVENTE ,
         IDPRODUIT ,
         DESIGNATION ,
         IDORIGINE ,
         qte,
         pu,
         REMISE ,
         TVA ,
         PUACHAT ,
         PUVENTE ,
         IDDEVISE ,
         TAUXDECHANGE ,
         compte,
         vd.idbcfille
         FROM VENTE_DETAILS vd
;
-- [1105/1309] VENTE_DETAILS_SAISIE_DIRECTE
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_SAISIE_DIRECTE" ("ID","IDVENTE","IDPRODUIT","DESIGNATION","IDORIGINE","QTE","PU","REMISE","REMISEMONTANT","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","COMPTE","PHOTO","REFERENCE","MONTANT","UNITE","RISTOURNE") AS
SELECT id,
       IDVENTE,
       IDPRODUIT,
       DESIGNATION,
       IDORIGINE,
       qte,
       pu,
       REMISE,
       nvl(remiseMontant, 0) AS remiseMontant,
       TVA,
       PUACHAT,
       PUVENTE,
       IDDEVISE,
       TAUXDECHANGE,
       compte,
       PHOTO,
       reference,
       montant,
       unite,
       RISTOURNE
FROM VENTE_DETAILS vd
;
-- [1106/1309] VENTE_DETAILS_VIDE
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_VIDE" ("ID","IDVENTE","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","COMPTE","PUREVIENT","IDBCFILLE","UNITE","UNITELIB","PUNET","FRAIS","MONTANTHT","MONTANTTTC","MONTANTTVA","MONTANTREMISE","MONTANT","RISTOURNE","IDCLIENTLIB","DATY","DATYPREVU","IDPRODUITLIB","IDCATEGORIELIB","CATEGORIEPRODUITLIB","POIDS","IDPREVISION","CALORIE","IDRESERVATION","FRAISLIVRAISON","RISTOURNEARBIOCHEM","REMISEARBIOCHEM") AS
select p.ID,
       p.IDVENTE,
       p.IDPRODUIT,
       p.IDORIGINE,
       p.QTE,
       p.PU,
       p.REMISE,
       p.TVA,
       p.PUACHAT,
       p.PUVENTE,
       p.IDDEVISE,
       p.TAUXDECHANGE,
       p.DESIGNATION,
       p.COMPTE,
       p.PUREVIENT,
       p.IDBCFILLE,
       p.UNITE,
       u.VAL                                                                                                   as unitelib,
       cast(p.pu - (p.pu * p.remise / 100) + ((p.pu * p.tva / 100)) as number(30, 5))                                                   as punet,
       cast(nvl(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0) as number(30, 5))                                          as frais,
       cast(((p.pu - (p.pu * p.remise / 100)) * p.qte - nvl(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) *
                                                        NVL(p.QTE, 0)) as number(30, 5))                                                  as montantht,
       cast(((p.pu - (p.pu * p.remise / 100)) * p.qte - nvl(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)) +
            ((((p.pu * qte) - (p.pu * p.remise / 100) * p.qte) -
              nvl(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) * NVL(p.QTE, 0)) * p.tva /
             100) as number(30, 5))                                                                                                   as montantttc,
       cast(((((p.pu * qte) - (p.pu * p.remise / 100) * p.qte) - nvl(v.fraislivraison, 0) * NVL(ing.CALORIE, 0) *
                                                                 NVL(p.QTE, 0)) * p.tva / 100) as number(30, 5))                                            as montanttva,
       cast((p.pu * p.remise / 100) * qte as number(30, 5))                                                                             as montantremise,
       cast((p.pu) * p.qte as number(30, 5))                                                                                            as montant,
       p.ristourne,
       cl.nom                                                                                                  as idclientlib,
       v.DATY,
       v.DATYPREVU,
       ing.LIBELLEVENTE                                                                                             AS IDPRODUITLIB,
       c.VAL                                                                                                   AS IDCATEGORIELIB,
       c.VAL                                                                                                   AS CATEGORIEPRODUITLIB,
       cast(NVL(ing.CALORIE, 0) * NVL(p.QTE, 0) as number(30, 5))                                                                     as poids,
       p.idprevision,
       ing.calorie,
       v.IDRESERVATION,
       nvl(v.fraislivraison, 0) AS fraislivraison,
       p.ristourneArbiochem,
       p.remiseArbiochem
from VENTE_DETAILS p
         left join AS_UNITE u on u.id = p.unite
         left join vente v on v.id = p.IDVENTE
         LEFT JOIN AS_INGREDIENTS ing
                   ON ing.ID = p.IDPRODUIT
         LEFT JOIN CLIENT cl
                   ON v.IDCLIENT = cl.ID
         LEFT JOIN CATEGORIEINGREDIENT c
                   ON ing.CATEGORIEINGREDIENT = c.ID
;
-- [1107/1309] ETAT_VENTE_DETAILS_POIDS
CREATE OR REPLACE FORCE VIEW "ETAT_VENTE_DETAILS_POIDS" ("ID","IDVENTE","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","COMPTE","PUREVIENT","IDBCFILLE","UNITE","UNITELIB","PUNET","MONTANTHT","MONTANTTTC","MONTANTTVA","MONTANTREMISE","MONTANT","POIDS","RESTE","FRAIS","IDPRODUITLIB","DATY","DATYPREVU","IDDEVISELIB","IDCATEGORIELIB","CATEGORIEPRODUITLIB","PUTOTAL","IDCLIENTLIB","RISTOURNE","IDPREVISION","IDCLIENT","IDPROVINCE","ETAT","IDPROVINCELIB","IDMAGASIN","IDMAGASINLIB","IDPOINT","IDPOINTLIB","TYPEPRODUIT","TYPEPRODUITLIB") AS
SELECT V.ID,
       V.IDVENTE,
       V.IDPRODUIT,
       V.IDORIGINE,
       CAST(V.QTE AS NUMBER(38, 2))        AS QTE,
       V.PU,
       V.REMISE,
       V.TVA,
       V.PUACHAT,
       V.PUVENTE,
       V.IDDEVISE,
       V.TAUXDECHANGE,
       V.DESIGNATION,
       V.COMPTE,
       V.PUREVIENT,
       V.IDBCFILLE,
       V.UNITE,
       V.UNITELIB,
       V.PUNET,
       V.MONTANTHT,
       CAST(V.MONTANTTTC AS NUMBER(30, 2)) AS MONTANTTTC,
       CAST(V.MONTANTTVA AS NUMBER(30, 2)) AS MONTANTTVA,
       V.MONTANTREMISE,
       V.MONTANT,
       V.POIDS,
       VC.RESTE                            AS RESTE,
       V.FRAIS                             AS FRAIS,
       V.IDPRODUITLIB,
       V.DATY,
       V.DATYPREVU                         AS DATYPREVU,
       V.IDDEVISE                          AS IDDEVISELIB,
       V.IDCATEGORIELIB,
       V.CATEGORIEPRODUITLIB,
       MONTANTTTC                          AS PUTOTAL,
       V.IDCLIENTLIB,
       V.RISTOURNE                         AS RISTOURNE,
       V.IDPREVISION,
       VE.IDCLIENT,
       C.IDPROVINCE,
       VE.ETAT,
       PRO.VAL                             AS IDPROVINCELIB,

       M.ID                                AS IDMAGASIN,
       M.VAL                               AS IDMAGASINLIB,

       P1.ID                               AS IDPOINT,
       P1.VAL                              AS IDPOINTLIB,

       TP.ID                               AS TYPEPRODUIT,
       TP.VAL                              AS TYPEPRODUITLIB

FROM VENTE_DETAILS_VIDE V
         LEFT JOIN EQUIVALENCE E
                   ON E.IDPRODUIT = V.IDPRODUIT
                       AND E.IDUNITE = V.UNITE

         LEFT JOIN VENTE_DETAILS_RESTE VC
                   ON VC.ID = V.ID

         LEFT JOIN VENTE VE
                   ON VE.ID = V.IDVENTE

         LEFT JOIN AS_INGREDIENTS P
                   ON P.ID = V.IDPRODUIT

         LEFT JOIN CLIENT C
                   ON C.ID = VE.IDCLIENT
         LEFT JOIN PROVINCE PRO ON PRO.ID = C.IDPROVINCE
         LEFT JOIN MAGASIN2 M ON M.ID = VE.IDMAGASIN
         LEFT JOIN POINT P1 ON P1.ID = M.IDPOINT
         LEFT JOIN TYPE_PRODUIT TP ON TP.ID = P.TYPEPRODUIT
;
-- [1108/1309] VENTE_DETAILS_POIDS
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_POIDS" ("ID","IDVENTE","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","COMPTE","PUREVIENT","IDBCFILLE","UNITE","UNITELIB","PUNET","MONTANTHT","MONTANTTTC","MONTANTTVA","MONTANTREMISE","MONTANT","POIDS","RESTE","FRAIS","IDPRODUITLIB","DATY","DATYPREVU","IDDEVISELIB","IDCATEGORIELIB","CATEGORIEPRODUITLIB","PUTOTAL","IDCLIENTLIB","RISTOURNE","IDPREVISION","IDRESERVATION","FRAISLIVRAISON","CALORIE") AS
SELECT v.ID,
       v.IDVENTE,
       v.IDPRODUIT,
       v.IDORIGINE,
       CAST(v.QTE AS NUMBER(38, 2)) AS QTE,
       v.PU,
       v.REMISE,
       v.TVA,
       v.PUACHAT,
       v.PUVENTE,
       v.IDDEVISE,
       v.TAUXDECHANGE,
       v.DESIGNATION,
       v.COMPTE,
       v.PUREVIENT,
       v.IDBCFILLE,
       v.UNITE,
       v.UNITELIB,
       v.PUNET,
       v.MONTANTHT,
       cast(v.MONTANTTTC as number(30,2)) as MONTANTTTC,
       cast(v.MONTANTTVA as number(30,2)) as montanttva,
       v.MONTANTREMISE,
       v.MONTANT,
       v.poids,
       vc.RESTE                     AS RESTE,
       v.frais                      AS FRAIS,
       v.IDPRODUITLIB,
       v.DATY,
       v.DATYPREVU                  AS DATYPREVU,
       v.IDDEVISE                   AS IDDEVISELIB,
       v.IDCATEGORIELIB,
       v.CATEGORIEPRODUITLIB,
       montantttc                   AS PUTOTAL,
       v.idclientlib,
       v.RISTOURNE                  AS RISTOURNE,
       v.idprevision,
       v.IDRESERVATION,
       v.fraislivraison,
       v.calorie
FROM VENTE_DETAILS_VIDE v
--         LEFT JOIN EQUIVALENCE e
--                   ON e.IDPRODUIT = v.IDPRODUIT
--                       AND e.IDUNITE = v.UNITE
         LEFT JOIN VENTE_DETAILS_RESTE vc
                   ON vc.ID = v.ID
--         LEFT JOIN Vente ve
--                   ON ve.ID = v.IDVENTE
--         LEFT JOIN VENTE_DETAILS vdc
--                   ON vdc.ID = ve.ID
;
-- [1109/1309] VENTEMONTANT
CREATE OR REPLACE FORCE VIEW "VENTEMONTANT" ("ID","MONTANTTOTAL","MONTANTREMISE","FRAIS","MONTANTTOTALACHAT","MONTANTTVA","MONTANTTTC","IDDEVISE","TAUXDECHANGE","MONTANTTTCAR","MONTANTREVIENT","IDRESERVATION") AS
SELECT vd.IDVENTE AS ID,
       cast(SUM((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                (nvl(vd.fraislivraison, 0) * nvl(vd.CALORIE, 0) * vd.QTE)) as number(30, 2))                          AS montanttotal,
       cast(SUM((NVL(vd.QTE, 0) * NVL(vd.PU, 0))) -
            SUM((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0))) as number(30, 2))                  AS montantremise,
       sum(FRAIS)                                                                                                    as frais,
       cast(SUM((NVL(vd.QTE, 0) * NVL(vd.PuAchat, 0))) as number(30, 2))                                             AS montanttotalachat,
       cast(SUM(((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                (nvl(vd.fraislivraison, 0) * nvl(vd.CALORIE, 0) * vd.QTE)) * (NVL(VD.TVA, 0)) /
                100) as number(30, 2))                                                                               AS montantTva,
       cast(SUM(((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                 (nvl(vd.fraislivraison, 0) * nvl(vd.CALORIE, 0) * vd.QTE)) * (NVL(VD.TVA, 0)) / 100) +
            SUM((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0)) -
                (nvl(vd.fraislivraison, 0) * nvl(vd.CALORIE, 0) * vd.QTE)) as number(30, 2))                          as montantTTC,
       NVL(vd.IDDEVISE, 'AR')                                                                                        AS IDDEVISE,
       NVL(avg(vd.tauxDeChange), 1)                                                                                  AS tauxDeChange,
       cast(SUM((1 - nvl(vd.remise / 100, 0)) * (NVL(vd.QTE, 0) * NVL(vd.PU, 0) -
                                                 (nvl(vd.fraislivraison, 0) * nvl(vd.CALORIE, 0) * vd.QTE) *
                                                 NVL(VD.TAUXDECHANGE, 1)) *
                (NVL(VD.TVA, 0)) / 100) +
            SUM(((1 - nvl(vd.remise / 100, 0)) *
                 (NVL(vd.QTE, 0) * NVL(vd.PU, 0) - (nvl(vd.fraislivraison, 0) * nvl(vd.CALORIE, 0) * vd.QTE)) *
                 NVL(VD.TAUXDECHANGE, 1)) -
                ((nvl(vd.fraislivraison, 0) * nvl(vd.CALORIE, 0) * vd.QTE))) as number(30, 2))                        as montantTTCAR,
       cast(sum(vd.PUREVIENT * vd.QTE) as number(20, 2))                                                             as montantRevient,
       vd.IDRESERVATION
FROM VENTE_DETAILS_POIDS vd
--         LEFT JOIN VENTE v ON v.ID = vd.IDVENTE
--         left join AS_INGREDIENTS vp on vp.id = vd.IDPRODUIT
GROUP BY vd.IDVENTE, vd.IDDEVISE, vd.IDRESERVATION
;
-- [1110/1309] UPDATEVENTE
CREATE OR REPLACE FORCE VIEW "UPDATEVENTE" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","IDCLIENTLIB","IDDEVISE","IDRESERVATION","DATYPREVU","ECHEANCEFACTURE","ESTPREVU") AS
SELECT
	v.ID,
	v.DESIGNATION,
	v.IDMAGASIN,
	v.DATY,
	v.REMARQUE,
	v.ETAT,
	v.IDORIGINE,
	v.IDCLIENT,
	c.NOM AS idClientLib,
	v2.IDDEVISE,
	v.IDRESERVATION,
	v.DATYPREVU ,
	v.ECHEANCEFACTURE,
	v.ESTPREVU
FROM VENTE v
JOIN CLIENT c ON c.ID = v.IDCLIENT
JOIN VENTEMONTANT v2 ON v2.ID = v.ID
;
-- [1111/1309] VENTE_CPL_ANALYSE
CREATE OR REPLACE FORCE VIEW "VENTE_CPL_ANALYSE" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","MONTANTTOTALACHAT","IDPOINT","IDPOINTLIB","MONTANTREVIENT","IDRESERVATION") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       m.VAL   AS IDMAGASINLIB,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       CASE
           WHEN v.ETAT = 1
               THEN 'CREE'
           WHEN v.ETAT = 11
               THEN 'EN ATTENTE LIVRAISON ET PAIEMENT'
           WHEN v.ETAT = 0
               THEN 'ANNULEE'
           WHEN v.ETAT = 12
               THEN 'LIVRE NON PAYE'
           WHEN v.ETAT = 13
               THEN 'PAYE NON LIVRE'
           WHEN v.ETAT = 14
               THEN 'PAYE ET LIVRE'
           END AS ETATLIB,
       v2.MONTANTTOTAL,
       v2.MONTANTTOTALACHAT,
       p.ID AS IDPOINT,
       p.VAL AS IDPOINTLIB,
       v2.MONTANTTOTAL - v2.MONTANTTOTALACHAT AS MONTANTREVIENT,
       v.IDRESERVATION
FROM VENTE v
         LEFT JOIN MAGASIN m ON m.ID = v.IDMAGASIN
         LEFT JOIN POINT p ON m.IDPOINT = p.ID
         JOIN VENTEMONTANT v2 ON v2.ID = v.ID
;
-- [1112/1309] VENTE_DETAILS_ANALYSE
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_ANALYSE" ("IDVENTELIB","IDCLIENTLIB","CATEGORIEPRODUITLIB","DATY","DATYPREVU") AS
SELECT
v.DESIGNATION AS  idventelib,
c.NOM  AS idclientlib,
ct.VAL AS categorieproduitlib,
v.DATY,
v.DATYPREVU
FROM VENTE_DETAILS_POIDS vdp
LEFT JOIN VENTE v ON v.id = vdp.IDVENTE
LEFT JOIN CLIENT c ON c.id = v.IDCLIENT
LEFT JOIN AS_INGREDIENTS ai ON ai.ID = vdp.IDPRODUIT
LEFT JOIN CATEGORIEINGREDIENT ct ON ct.ID = ai.CATEGORIEINGREDIENT
;
-- [1113/1309] VENTE_DETAILS_VIDEAUTOCOMPLETE
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_VIDEAUTOCOMPLETE" ("ID","IDVENTE","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","COMPTE","PUREVIENT","IDBCFILLE","UNITE","UNITELIB","PUNET","FRAIS","MONTANTHT","MONTANTTTC","MONTANTTVA","MONTANTREMISE","MONTANT","RISTOURNE","IDCLIENTLIB","DATY","DATYPREVU","IDPRODUITLIB","IDCATEGORIELIB","CATEGORIEPRODUITLIB","POIDS","IDPREVISION","CALORIE","IDRESERVATION","FRAISLIVRAISON","RISTOURNEARBIOCHEM","REMISEARBIOCHEM") AS
SELECT
    v.ID,
    v.IDVENTE,
    CASE
        WHEN v.IDPRODUIT IS NULL
            THEN v.IDPRODUIT
        ELSE v.IDPRODUIT||'---'||a.LIBELLE
        END AS IDPRODUIT,
    v.IDORIGINE,
    v.QTE,
    v.PU,
    v.REMISE,
    v.TVA,
    v.PUACHAT,
    v.PUVENTE,
    v.IDDEVISE,
    v.TAUXDECHANGE,
    v.DESIGNATION,
    v.COMPTE,
    v.PUREVIENT,
    v.IDBCFILLE,
    v.UNITE,
    v.UNITELIB,
    v.PUNET,
    v.FRAIS,
    v.MONTANTHT,
    v.MONTANTTTC,
    v.MONTANTTVA,
    v.MONTANTREMISE,
    v.MONTANT,
    v.RISTOURNE,
    v.IDCLIENTLIB,
    v.DATY,
    v.DATYPREVU,
    v.IDPRODUITLIB,
    v.IDCATEGORIELIB,
    v.CATEGORIEPRODUITLIB,
    v.POIDS,
    CASE
        WHEN v.IDPREVISION IS NULL
            THEN v.IDPREVISION
        ELSE v.IDPREVISION||'---'||p.DESIGNATION
        END AS IDPREVISION ,
    v.CALORIE,
    v.IDRESERVATION,
    v.FRAISLIVRAISON,
    v.ristourneArbiochem,
    v.remiseArbiochem
FROM VENTE_DETAILS_VIDE v
         LEFT  JOIN AS_INGREDIENTS a ON a.id = v.IDPRODUIT
         LEFT JOIN PREVISION p ON p.ID = v.IDPREVISION
;
-- [1114/1309] VENTE_ENCAISSE
CREATE OR REPLACE FORCE VIEW "VENTE_ENCAISSE" ("IDVENTE","IDRESERVATION","MONTANTPAYE") AS
SELECT
v.id AS IDVENTE,
v.IDRESERVATION,
sum( nvl(ed.MONTANT,0) ) AS montantpaye
FROM ENCAISSEMENT_DETAILS ed
LEFT JOIN ENCAISSEMENT e ON e.id = ed.IDENCAISSEMENT
LEFT JOIN VENTE v ON v.id = e.IDORIGINE
GROUP BY v.id ,v.IDRESERVATION
;
-- [1115/1309] VENTE_CPL_AVEC_MONTANT
CREATE OR REPLACE FORCE VIEW "VENTE_CPL_AVEC_MONTANT" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","IDCLIENTLIB","IDMAGASINLIB","MONTANTTC","MONTANTTTC","MONTANTPAYE","ENCAISSEMENTCHANGE","MONTANTRESTE","IDDEVISE","IDRESERVATION") AS
SELECT
v.ID,v.DESIGNATION,v.IDMAGASIN,v.DATY,v.REMARQUE,v.ETAT,v.IDORIGINE,v.IDCLIENT,
c.NOM AS idClientLib,
m.VAL AS idMagasinLib,
nvl(vg.montanttc,0) AS montanttc,
nvl(vg.montanttc,0) AS montantttc,
nvl(ve.montantpaye*vg.TAUXDECHANGE,0) AS montantpaye,
nvl(ve.montantpaye * vg.TAUXDECHANGE ,0) AS encaissementchange,
nvl(vg.montanttc,0) - nvl(ve.montantpaye*vg.TAUXDECHANGE,0)  AS montantreste,
vg.idDevise,
v.IDRESERVATION
FROM ventedetails_grp vg
LEFT JOIN VENTE v ON v.id = vg.IDVENTE
LEFT JOIN vente_encaisse ve ON ve.IDVENTE = v.id
LEFT JOIN CLIENT c ON c.id = v.idclient
LEFT JOIN MAGASIN m ON m.id  = v.idmagasin
;
-- [1116/1309] VENTE_CPL_AVEC_MONTANT_EUR
CREATE OR REPLACE FORCE VIEW "VENTE_CPL_AVEC_MONTANT_EUR" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","IDCLIENTLIB","IDMAGASINLIB","MONTANTTC","MONTANTTTC","MONTANTPAYE","ENCAISSEMENTCHANGE","MONTANTRESTE","IDDEVISE","IDRESERVATION") AS
SELECT
v.ID,v.DESIGNATION,v.IDMAGASIN,v.DATY,v.REMARQUE,v.ETAT,v.IDORIGINE,v.IDCLIENT,
c.NOM AS idClientLib,
m.VAL AS idMagasinLib,
nvl(vg.montanttc,0) AS montanttc,
nvl(vg.montanttc,0) AS montantttc,
nvl(ve.montantpaye,0) AS montantpaye,
nvl(ve.montantpaye,0) AS encaissementchange,
nvl(vg.montanttc,0) - nvl(ve.montantpaye,0)  AS montantreste,
vg.idDevise,
v.IDRESERVATION
FROM ventedetails_grp vg
LEFT JOIN VENTE v ON v.id = vg.IDVENTE
LEFT JOIN vente_encaisse ve ON ve.IDVENTE = v.id
LEFT JOIN CLIENT c ON c.id = v.idclient
LEFT JOIN MAGASIN m ON m.id  = v.idmagasin
WHERE vg.idDevise='EUR'
;
