-- [1119/1309] VENTE_GRP_SANSDEVISE
CREATE OR REPLACE FORCE VIEW "VENTE_GRP_SANSDEVISE" ("IDVENTE","QTETOTAL","MONTANTTC","IDDEVISE") AS
SELECT 
vd.IDVENTE,
sum(nvl(vd.qte,0) ) AS qtetotal,
sum(nvl(vd.qte*pu,0) ) AS montanttc,
max(iddevise) AS iddevise
FROM VENTE_DETAILS vd 
GROUP BY vd.IDVENTE
;
-- [1120/1309] VENTE_CPL_AVEC_MONTANT_SANSDEV
CREATE OR REPLACE FORCE VIEW "VENTE_CPL_AVEC_MONTANT_SANSDEV" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","IDCLIENTLIB","IDMAGASINLIB","MONTANTTTC","MONTANTPAYE","ENCAISSEMENTCHANGE","MONTANTRESTE","IDDEVISE","IDRESERVATION") AS
