	"MONTANTTVA",
	"MONTANTTTC",
	"MONTANTHTAR",
	"MONTANTTVAAR",
	"MONTANTTTCAR",
	"ETAT",
	"TAUXDECHANGE"
FROM
	VENTE_GRP_TOUS
;
-- [1123/1309] VENTE_GRP_CREE
CREATE OR REPLACE FORCE VIEW "VENTE_GRP_CREE" ("IDVENTE","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","ETAT") AS
