-- [1124/1309] VENTE_GRP_CREER
CREATE OR REPLACE FORCE VIEW "VENTE_GRP_CREER" ("IDVENTE","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","ETAT") AS
