-- [1125/1309] VENTE_GRP_VISER
CREATE OR REPLACE FORCE VIEW "VENTE_GRP_VISER" ("IDVENTE","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","ETAT","TAUXDECHANGE") AS
