from VENTE_GRP_TOUS
where etat >=11
;
-- [1126/1309] VENTE_LIB
CREATE OR REPLACE FORCE VIEW "VENTE_LIB" ("IDORIGINE","ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","IDCLIENT","IDCLIENTLIB") AS
SELECT
  v.IDORIGINE ,
v.ID ,
v.DESIGNATION ,
v.IDMAGASIN ,
m.VAL AS IDMAGASINLIB,
v.DATY ,
v.REMARQUE ,
v.ETAT ,
CASE
	WHEN v.ETAT = 1
	THEN 'CREE'
	WHEN v.ETAT = 11
	THEN 'VALIDEE'
	WHEN v.ETAT = 0
	THEN 'ANNULEE'
END AS ETATLIB,
v.IDCLIENT ,
c.NOM AS IDCLIENTLIB
FROM VENTE v
LEFT JOIN MAGASIN m ON m.ID = v.IDMAGASIN
LEFT JOIN CLIENT c ON c.ID = v.IDCLIENT
;
-- [1127/1309] VENTE_DETAILS_CPL
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_CPL" ("ID","IDVENTE","IDVENTELIB","IDPRODUIT","IDPRODUITLIB","IDORIGINE","QTE","PU","MONTANTREMISE","MONTANT","IDDEVISE","TAUXDECHANGE","TVA","IDCLIENT","IDCLIENTLIB","DESIGNATION","PUREVIENT","MONTANTREVIENT") AS
SELECT vd.ID,
          vd.IDVENTE,
          v.DESIGNATION AS IDVENTELIB,
          vd.IDPRODUIT,
          p.LIBELLE AS IDPRODUITLIB,
          v.IDORIGINE,
          vd.QTE,
          VD.pu
             AS PU,
         	CAST((nvl(vd.remise/100,0))*(vd.QTE * vd.PU) AS NUMBER(30,2)) AS montantRemise,
            CAST((1-nvl(vd.remise/100,0))*(vd.QTE * vd.PU) AS NUMBER(30,2)) AS montant,
          vd.iddevise AS iddevise,
          vd.tauxDeChange AS tauxDeChange,
          vd.tva AS tva,
          v.idclient,
          v.idclientlib,
          vd.designation,
          vd.PUREVIENT,
          cast(vd.QTE*vd.PUREVIENT as NUMBER(20,2)) as montantRevient
     FROM VENTE_DETAILS vd
          LEFT JOIN VENTE_LIB v ON v.ID = vd.IDVENTE
          LEFT JOIN AS_INGREDIENTS p ON p.ID = vd.IDPRODUIT
;
-- [1128/1309] VENTEDETAILS_AVEC_MONTANT
CREATE OR REPLACE FORCE VIEW "VENTEDETAILS_AVEC_MONTANT" ("ID","IDVENTE","IDVENTELIB","IDPRODUIT","IDPRODUITLIB","IDORIGINE","QTE","PU","MONTANT","IDDEVISE","TAUXDECHANGE","TVA","IDCLIENT","IDCLIENTLIB","PUTOTAL","PUREVIENT","MONTANTRESTE","MONTANTPAYE") AS
SELECT 
	v."ID",v."IDVENTE",v."IDVENTELIB",v."IDPRODUIT",v."IDPRODUITLIB",v."IDORIGINE",v."QTE",v."PU",v."MONTANT",v."IDDEVISE",v."TAUXDECHANGE",v."TVA",v."IDCLIENT",v."IDCLIENTLIB",
	v.pu*v.qte*nvl(v.tauxdechange,0) AS putotal,
	v.pu*v.qte AS 	purevient,
	vcm.montantreste,
	vcm.montantpaye
FROM VENTE_DETAILS_CPL v
JOIN VENTE_CPL_AVEC_MONTANT vcm ON vcm.id=v.IDVENTE
;
-- [1129/1309] VENTEPRELEVEMENT
CREATE OR REPLACE FORCE VIEW "VENTEPRELEVEMENT" ("IDORIGINE","MONTANTTOTALVENTE") AS
SELECT 
vdc.IDORIGINE ,
sum( nvl( vdc.MONTANT ,0) ) AS montantTotalVente
FROM VENTE_DETAILS_CPL vdc 
GROUP BY vdc.IDORIGINE
;
-- [1130/1309] VENTE_DETAILS_TICKET
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_TICKET" ("ID","IDVENTE","IDVENTELIB","IDPRODUIT","IDPRODUITLIB","IDORIGINE","QTE","PU","MONTANTREMISE","MONTANT","IDDEVISE","TAUXDECHANGE","TVA","IDCLIENT","IDCLIENTLIB","DESIGNATION","PUREVIENT","MONTANTREVIENT","UNITE","IDUNITELIB") AS
SELECT vd.ID,
       vd.IDVENTE,
       v.DESIGNATION AS IDVENTELIB,
       vd.IDPRODUIT,
       p.LIBELLE AS IDPRODUITLIB,
       v.IDORIGINE,
       vd.QTE,
       VD.pu
                     AS PU,
       CAST((nvl(vd.remise/100,0))*(vd.QTE * vd.PU) AS NUMBER(30,2)) AS montantRemise,
       CAST((1-nvl(vd.remise/100,0))*(vd.QTE * vd.PU) AS NUMBER(30,2)) AS montant,
       vd.iddevise AS iddevise,
       vd.tauxDeChange AS tauxDeChange,
       vd.tva AS tva,
       v.idclient,
       v.idclientlib,
       vd.designation,
       vd.PUREVIENT,
       cast(vd.QTE*vd.PUREVIENT as NUMBER(20,2)) as montantRevient,
       p.UNITE,
       unit.val as idUniteLib
FROM VENTE_DETAILS vd
         LEFT JOIN VENTE_LIB v ON v.ID = vd.IDVENTE
         LEFT JOIN AS_INGREDIENTS p ON p.ID = vd.IDPRODUIT
         LEFT JOIN UNITE unit ON unit.id = p.UNITE
;
-- [1131/1309] VENTE_LIB_ANNULEE
CREATE OR REPLACE FORCE VIEW "VENTE_LIB_ANNULEE" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","IDCLIENT","IDCLIENTLIB","IDRESERVATION") AS
SELECT
vl."ID",vl."DESIGNATION",vl."IDMAGASIN",vl."IDMAGASINLIB",vl."DATY",vl."REMARQUE",vl."ETAT",vl."ETATLIB",vl."IDCLIENT",vl."IDCLIENTLIB",vl."IDRESERVATION"
FROM VENTE_LIB vl
WHERE vl.ETAT = 0
;
-- [1132/1309] VENTE_LIB_CREE
CREATE OR REPLACE FORCE VIEW "VENTE_LIB_CREE" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","IDCLIENT","IDCLIENTLIB","IDRESERVATION") AS
SELECT
vl."ID",vl."DESIGNATION",vl."IDMAGASIN",vl."IDMAGASINLIB",vl."DATY",vl."REMARQUE",vl."ETAT",vl."ETATLIB",vl."IDCLIENT",vl."IDCLIENTLIB",vl."IDRESERVATION"
FROM VENTE_LIB vl
WHERE vl.ETAT = 1
;
-- [1133/1309] VENTE_LIB_VISEE
CREATE OR REPLACE FORCE VIEW "VENTE_LIB_VISEE" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","IDCLIENT","IDCLIENTLIB","IDRESERVATION") AS
SELECT
vl."ID",vl."DESIGNATION",vl."IDMAGASIN",vl."IDMAGASINLIB",vl."DATY",vl."REMARQUE",vl."ETAT",vl."ETATLIB",vl."IDCLIENT",vl."IDCLIENTLIB",vl."IDRESERVATION"
FROM VENTE_LIB vl
WHERE vl.ETAT = 11
;
-- [1134/1309] VENTE_MERE_MONTANT
CREATE OR REPLACE FORCE VIEW "VENTE_MERE_MONTANT" ("ID","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","MONTANTHT","MONTANTTVA","MONTANTTTC","TAUXDECHANGE","CLIENTLIB","COMPTE","IDRESERVATION") AS
select v.ID,v.DESIGNATION,v.IDMAGASIN,v.DATY,v.REMARQUE,v.ETAT,v.IDORIGINE,v.IDCLIENT,
       vt.MONTANTHT,
       vt.MONTANTTVA,
       vt.MONTANTTTC,
       vt.TAUXDECHANGE,
        CL.NOM AS CLIENTLIB,
       CL.COMPTE,
       v.IDRESERVATION
from VENTE v
left join VENTE_GRP_TOUS vt on vt.IDVENTE = v.id
left join CLIENT CL on CL.ID = v.IDCLIENT
;
-- [1135/1309] VENTE_MF
CREATE OR REPLACE FORCE VIEW "VENTE_MF" ("ID","IDVENTE","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","DESIGNATION","IDMAGASIN","DATY","REMARQUE","ETAT","IDCLIENT","COMPTE","MONTANTHT","MONTANTTVA","MONTANTTTC","TAUXDECHANGE","IDRESERVATION") AS
select vd.ID,vd.IDVENTE,vd.IDPRODUIT,vd.IDORIGINE,vd.QTE,vd.PU,vd.REMISE,vd.TVA,vd.PUACHAT,vd.PUVENTE,
       v.DESIGNATION,
       v.IDMAGASIN,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       v.IDCLIENT,
       vd.compte,
       cast((PU * qte* (1-(nvl(vd.REMISE,0)/100))) as NUMBER(30, 2)) as montantHT,
       cast((PU * qte* (1-(nvl(vd.REMISE,0)/100)) *(tva/100)) as NUMBER(30, 2)) as montantTVA,
       cast(PU * qte* (1-(nvl(vd.REMISE,0)/100)) + (PU * qte* (1-(nvl(vd.REMISE,0)/100)) * (tva/100))  as NUMBER(30, 2)) as montantTTC,
       vd.TAUXDECHANGE AS tauxdechange,
       v.IDRESERVATION
from VENTE_DETAILS vd
         left outer join VENTE V on V.ID = vd.IDVENTE
;
-- [1136/1309] VENTE_ORIGINE
CREATE OR REPLACE FORCE VIEW "VENTE_ORIGINE" ("IDORIGINE","NOMBRE") AS
select IDORIGINE,count(*) as nombre from VENTE where ETAT>=11 group by IDORIGINE
;
-- [1137/1309] BONDECOMMANDE_CLIENT_CPL
CREATE OR REPLACE FORCE VIEW "BONDECOMMANDE_CLIENT_CPL" ("ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","MODEPAIEMENTLIB","IDCLIENT","IDCLIENTLIB","REFERENCE","IDMAGASINLIB","ETATLIB","IDPROFORMA","NBFACTURE","MODELIVRAISONLIB","DATELIVRAISON","LIEULIVRAISON","NUMEROBC","FRAISLIVRAISON") AS
SELECT
    bc.ID,
    bc.DATY,
    bc.ETAT,
    bc.REMARQUE,
    bc.DESIGNATION,
    bc.MODEPAIEMENT,
    m.VAL AS MODEPAIEMENTLIB,
    bc.IDCLIENT,
    c.NOM AS IDCLIENTLIB,
    bc.REFERENCE,
    m2.VAL AS IDMAGASINLIB,
    CASE
        WHEN bc.ETAT = 0 THEN '<span style=color: green;>ANNUL&Eacute;</span>'
        WHEN bc.ETAT = 1 THEN '<span style=color: green;>CR&Eacute;&Eacute;</span>'
        WHEN bc.ETAT = 11 THEN '<span style=color: green;>VALID&Eacute;</span>'
        END AS ETATLIB,
    bc.IDPROFORMA,
    nvl(vo.nombre,0) as nbfacture,
    CASE
        WHEN bc.modelivraison = 1 THEN '<span style=color: green;>LIVRAISON</span>'
        WHEN bc.modelivraison = 2 THEN '<span style=color: green;>RECUPERATION</span>'
        END AS modelivraisonlib,
    bc.dateLivraison,
    bc.lieuLivraison,
    bc.NUMEROBC,
    FRAISLIVRAISON
FROM BONDECOMMANDE_CLIENT bc
         LEFT JOIN CLIENT c ON c.id = bc.IDCLIENT
         LEFT JOIN MODEPAIEMENT m ON m.id = bc.MODEPAIEMENT
         LEFT JOIN MAGASIN2 m2 ON m2.id = bc.IDMAGASIN
         left join vente_origine vo on vo.IDORIGINE=bc.id
;
-- [1138/1309] BONDECOMMANDE_CLIENT_CPL_A
CREATE OR REPLACE FORCE VIEW "BONDECOMMANDE_CLIENT_CPL_A" ("ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","MODEPAIEMENTLIB","IDCLIENT","IDCLIENTLIB","REFERENCE","ETATLIB") AS
SELECT "ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","MODEPAIEMENTLIB","IDCLIENT","IDCLIENTLIB","REFERENCE","ETATLIB" FROM BONDECOMMANDE_CLIENT_CPL WHERE etat=0
;
-- [1139/1309] BONDECOMMANDE_CLIENT_CPL_C
CREATE OR REPLACE FORCE VIEW "BONDECOMMANDE_CLIENT_CPL_C" ("ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","MODEPAIEMENTLIB","IDCLIENT","IDCLIENTLIB","REFERENCE","ETATLIB") AS
SELECT "ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","MODEPAIEMENTLIB","IDCLIENT","IDCLIENTLIB","REFERENCE","ETATLIB" FROM BONDECOMMANDE_CLIENT_CPL WHERE etat=1
;
-- [1140/1309] BONDECOMMANDE_CLIENT_CPL_M
CREATE OR REPLACE FORCE VIEW "BONDECOMMANDE_CLIENT_CPL_M" ("ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","MODEPAIEMENTLIB","IDCLIENT","IDCLIENTLIB","REFERENCE","IDMAGASINLIB","ETATLIB","IDPROFORMA","NBFACTURE","MODELIVRAISONLIB","DATELIVRAISON","LIEULIVRAISON","NUMEROBC","QTERESTE","MONTANTTTC","MONTANTTTCAR","FACTURELIB","MOTSCLESSS","IDMAGASIN","MONTANTHT","MONTANTREMISE","MONTANTTVA","IDDEVISE") AS
SELECT BC.ID,
       BC.DATY,
       CASE
           WHEN (SUM(BCF.QTERESTE)) = 0 THEN 12
           ELSE BC.ETAT
           END           AS ETAT,
       BC.REMARQUE,
       BC.DESIGNATION,
       BC.MODEPAIEMENT,
       M.VAL             AS MODEPAIEMENTLIB,
       BC.IDCLIENT,
       C.NOM             AS IDCLIENTLIB,
       BC.REFERENCE,
       M2.VAL            AS IDMAGASINLIB,
       CASE
           WHEN (SUM(BCF.QTERESTE)) = 0 THEN '<span style=color: green;>Valid&eacute;e</span>'
           WHEN BC.ETAT = 0 THEN '<span style=color: green;>Annul&eacute;e</span>'
           WHEN BC.ETAT = 1 THEN '<span style=color: green;>Cr&eacute;&eacute;</span>'
           WHEN BC.ETAT = 11 THEN '<span style=color: green;>Valid&eacute;e</span>'
           WHEN BC.ETAT = 12 THEN '<span style=color: green;>Valid&eacute;e</span>'
           END           AS ETATLIB,
       BC.IDPROFORMA,
       NVL(VO.NOMBRE, 0) AS NBFACTURE,
       CASE
           WHEN BC.MODELIVRAISON = 1 THEN '<span style=color: green;>LIVRAISON</span>'
           WHEN BC.MODELIVRAISON = 2 THEN '<span style=color: green;>R&Eacute;CUP&Eacute;RATION</span>'
           END           AS MODELIVRAISONLIB,
       BC.DATELIVRAISON,
       BC.LIEULIVRAISON,
       BC.NUMEROBC,
       SUM(BCF.QTERESTE) AS QTERESTE, sum(BCF.MONTANTTTC) as montantTTC,sum(BCF.MONTANTTTCAR) as montantTTCAR,
       CASE
           WHEN NVL(VO.NOMBRE, 0) > 0 THEN '<span style=color: green;>FACTUR&Eacute;</span>'
           WHEN NVL(VO.NOMBRE, 0) = 0 THEN '<span style=color: red;>NON FACTUR&Eacute;</span>'
           END           AS FACTURELIB,
       (
           BC.id || ' | ' ||  C.NOM  || ' | ' || designation || ' | ' || reference || ' | ' || M.VAL || ' | ' || BC.remarque || ' | ' || numeroBc
           )             AS MOTSCLESSS,
       BC.IDMAGASIN,
       cast(sum(bcf.montantremise) as number(30,2)) as montantHT,
       cast(sum(bcf.montantdelaremise) as number(30,2)) as montantremise,cast(sum(bcf.MONTANTTVA) as number(30,2)) as MONTANTTVA,
       bc.IDDEVISE
FROM BONDECOMMANDE_CLIENT BC
         LEFT JOIN CLIENT C ON C.ID = BC.IDCLIENT
         LEFT JOIN MODEPAIEMENT M ON M.ID = BC.MODEPAIEMENT
         LEFT JOIN MAGASIN2 M2 ON M2.ID = BC.IDMAGASIN
         LEFT JOIN VENTE_ORIGINE VO ON VO.IDORIGINE = BC.ID
         LEFT JOIN BC_CLIENT_FILLE_CPL_LIB2 BCF ON BCF.IDBC = BC.ID
GROUP BY BC.ID,
         BC.DATY,
         BC.ETAT,
         BC.REMARQUE,
         BC.DESIGNATION,
         BC.MODEPAIEMENT,
         M.VAL,
         BC.IDCLIENT,
         C.NOM,
         BC.REFERENCE,
         M2.VAL,
         BC.IDPROFORMA,
         VO.NOMBRE,
         BC.DATELIVRAISON,
         BC.LIEULIVRAISON,
         BC.NUMEROBC,
         BC.MODELIVRAISON, BC.IDMAGASIN, bc.IDDEVISE
;
-- [1141/1309] BONDECOMMANDE_CLIENT_CPL_V
CREATE OR REPLACE FORCE VIEW "BONDECOMMANDE_CLIENT_CPL_V" ("ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","MODEPAIEMENTLIB","IDCLIENT","IDCLIENTLIB","REFERENCE","ETATLIB") AS
SELECT "ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","MODEPAIEMENTLIB","IDCLIENT","IDCLIENTLIB","REFERENCE","ETATLIB" FROM BONDECOMMANDE_CLIENT_CPL WHERE etat=11
;
-- [1142/1309] BONDECOMMANDE_CLIENT_GLOBALE
CREATE OR REPLACE FORCE VIEW "BONDECOMMANDE_CLIENT_GLOBALE" ("ID","IDBC","IDDEVISE","MONTANT","PRODUIT","PU","QUANTITE","REMISE","TVA","UNITE","QTEOF","QTEOFRESTANTE","QTEFAB","QTEFABRESTANTE","QTELIVRE","QTENONLIVRE","LIBELLEPRODUIT","IDCLIENT","IDCLIENTLIB","DATY","ETAT","ETATLIB") AS
SELECT BCFC."ID",BCFC."IDBC",BCFC."IDDEVISE",BCFC."MONTANT",BCFC."PRODUIT",BCFC."PU",BCFC."QUANTITE",BCFC."REMISE",BCFC."TVA",BCFC."UNITE",BCFC."QTEOF",BCFC."QTEOFRESTANTE",BCFC."QTEFAB",BCFC."QTEFABRESTANTE",BCFC."QTELIVRE",BCFC."QTENONLIVRE",BCFC."LIBELLEPRODUIT",bc.IDCLIENT,bc.IDCLIENTLIB , bc.DATY,bc.ETAT , bc.ETATLIB  FROM 
	BONDECOMMANDE_CLIENT_FILLE_CPL bcfc
	JOIN BONDECOMMANDE_CLIENT_CPL bc ON bc.ID = BCFC.IDBC
;
-- [1143/1309] BC_GROUPE_ING
CREATE OR REPLACE FORCE VIEW "BC_GROUPE_ING" ("BCLIST","PRODUIT","LIBELLEPRODUIT","CLIENTLIST","QTEOFRESTANTE") AS
SELECT
    LISTAGG(ID || ':' || QTEOFRESTANTE, ';') WITHIN GROUP (ORDER BY ID) AS BCLIST,
    PRODUIT,
    LIBELLEPRODUIT,
    LISTAGG(IDCLIENTLIB , ';') WITHIN GROUP (ORDER BY ID) AS CLIENTLIST,
    SUM(QTEOFRESTANTE) AS QTEOFRESTANTE
    FROM
    ASYNCARTISANAT.BONDECOMMANDE_CLIENT_GLOBALE
    WHERE
    QTEOFRESTANTE > 0
    GROUP BY
    PRODUIT,
    LIBELLEPRODUIT
;
-- [1144/1309] ETATRECAPITULATIFCOMMANDE
CREATE OR REPLACE FORCE VIEW "ETATRECAPITULATIFCOMMANDE" ("IDCLIENT","IDCLIENTLIB","DATY","MONTANT","QTELIVRE","QTENONLIVRE","MONTANTPAYE","MONTANTRESTANT","ETAT","ETATLIB") AS
SELECT
    bcg.IDCLIENT,
    bcg.IDCLIENTLIB,
    bcg.DATY,
    SUM(bcg.pu * bcg.QUANTITE) as MONTANT,
    SUM(bcg.QTELIVRE) as qteLivre,
    SUM(bcg.QTENONLIVRE) as qteNonLivre,
    COALESCE(SUM(mc_accompte.CREDIT), 0) + COALESCE(SUM(mc_paye.CREDIT), 0) as montantPaye,
    COALESCE(SUM(bcg.pu * bcg.QUANTITE), 0) - COALESCE(COALESCE(SUM(mc_accompte.CREDIT), 0) + COALESCE(SUM(mc_paye.CREDIT), 0), 0) as montantRestant,
    CASE
        WHEN (COALESCE(SUM(mc_accompte.CREDIT), 0) + COALESCE(SUM(mc_paye.CREDIT), 0)) >= SUM(bcg.pu * bcg.QUANTITE) THEN 22
        WHEN (COALESCE(SUM(bcg.pu * bcg.QUANTITE), 0) - COALESCE(COALESCE(SUM(mc_accompte.CREDIT), 0) + COALESCE(SUM(mc_paye.CREDIT), 0), 0)) > 0 THEN 2
        WHEN SUM(bcg.QTELIVRE) = SUM(bcg.QUANTITE) THEN 111
        WHEN SUM(bcg.QTELIVRE) > 0 THEN 11
        ELSE 1
        END as etat,
    CASE
        WHEN (COALESCE(SUM(mc_accompte.CREDIT), 0) + COALESCE(SUM(mc_paye.CREDIT), 0)) >= SUM(bcg.pu * bcg.QUANTITE) THEN 'Pay&eacute;'
        WHEN (COALESCE(SUM(bcg.pu * bcg.QUANTITE), 0) - COALESCE(COALESCE(SUM(mc_accompte.CREDIT), 0) + COALESCE(SUM(mc_paye.CREDIT), 0), 0)) > 0 THEN 'Accompte'
        WHEN SUM(bcg.QTELIVRE) = SUM(bcg.QUANTITE) THEN 'Livr&eacute;'
        WHEN SUM(bcg.QTELIVRE) > 0 THEN 'non livr&eacute; en totalit&eacute;'
        ELSE 'non livr&eacute;'
        END as etatLib
FROM BONDECOMMANDE_CLIENT_GLOBALE bcg
         LEFT JOIN MOUVEMENTCAISSE mc_accompte ON mc_accompte.IDORIGINE = bcg.IDBC
         LEFT JOIN VENTE v ON v.IDORIGINE = bcg.IDBC
         LEFT JOIN MOUVEMENTCAISSE mc_paye ON mc_paye.IDORIGINE = v.ID
WHERE bcg.ETAT = 11
GROUP BY
    bcg.IDCLIENT,
    bcg.IDCLIENTLIB,
    bcg.DATY,
    bcg.IDBC
;
-- [1145/1309] VENTE_POIDS
CREATE OR REPLACE FORCE VIEW "VENTE_POIDS" ("IDVENTE","POIDS","COLIS") AS
select IDVENTE,sum(poids) as poids, sum(QTE) as colis from VENTE_DETAILS_POIDS group by IDVENTE
;
-- [1146/1309] VENTE_PRELEVEMENT
CREATE OR REPLACE FORCE VIEW "VENTE_PRELEVEMENT" ("ID","IDPRELEVEMENTANTERIEUR","COMPTEUR","DATY","HEURE","IDPOMPISTE","IDPOMPE","ETAT","MONTANTTOTALVENTE","IDENCAISSEMENT","MONTANTTOTALENCAISSEMENT") AS
SELECT
	p.ID ,
	p.IDPRELEVEMENTANTERIEUR ,
	p.COMPTEUR ,
	p.DATY ,
	p.HEURE ,
	p.IDPOMPISTE ,
	p.IDPOMPE ,
	p.ETAT ,
	nvl(vdc.montantTotalVente,0) AS montantTotalVente,
	pe.IDENCAISSEMENT ,
	nvl(m.montantTotalEncaissement,0) AS montantTotalEncaissement
FROM
	PRELEVEMENT p
LEFT JOIN PRELEVEMENT_ENCAISSE pe ON
	pe.IDPRELEVEMENT = p.ID
LEFT JOIN VENTEPRELEVEMENT vdc ON
	vdc.IDORIGINE = pe.IDPRELEVEMENT
LEFT JOIN MONTANTENCAISSEMENT m ON m.IDENCAISSEMENT = pe.IDENCAISSEMENT
;
-- [1147/1309] VENTE_RESTE
CREATE OR REPLACE FORCE VIEW "VENTE_RESTE" ("IDVENTE","RESTE") AS
select IDVENTE, sum(reste) reste
from VENTE_DETAILS_RESTE
group by IDVENTE
;
-- [1148/1309] VENTE_CPL
CREATE OR REPLACE FORCE VIEW "VENTE_CPL" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","DATYPREVU","REFERENCEFACTURE","MONTANTREMISE","MONTANT","MOIS","ANNEE","POIDS","COLIS","MODEPAIEMENT","MODEPAIEMENTLIB","FRAISLIVRAISON","MODELIVRAISON","MODELIVRAISONLIB","RESTE","IDPROVINCE","PROVINCELIB","IDORIGINE","FRAIS","REFERENCEFACT","NUMEROFACTURE","LIEULIVRAISON","DATELIVRAISON","UPDATED_AT","ESTPREVULIB","IDECRITURE","DATEDELIVRAISON","MOTSCLESSS") AS
SELECT V.ID,
       V.DESIGNATION,
       V.IDMAGASIN,
       M.VAL                                                                     AS IDMAGASINLIB,
       V.DATY,
       V.REMARQUE,
       V.ETAT,
       CASE
           WHEN V.ETAT = 1 THEN 'CR&Eacute;&Eacute;E'
           WHEN V.ETAT = 11 THEN 'VIS&Eacute;E'
           WHEN V.ETAT = 0 THEN 'ANNUL&Eacute;E'
           END                                                                   AS ETATLIB,
       CAST(V2.MONTANTTOTAL AS NUMBER(30, 5))                                    AS MONTANTTOTAL,
       V2.IDDEVISE,
       V.IDCLIENT,
       C.NOM                                                                     AS IDCLIENTLIB,
       CAST(V2.MONTANTTVA AS NUMBER(30, 5))                                      AS MONTANTTVA,
       CAST(V2.MONTANTTTC AS NUMBER(30, 5))                                      AS MONTANTTTC,
       CAST(V2.MONTANTTTCAR AS NUMBER(30, 5))                                    AS MONTANTTTCAR,
       CAST(NVL(MV.MONTANT, 0) AS NUMBER(30, 5))                                 AS MONTANTPAYE,
       CAST(NVL(V2.MONTANTTTC, 0) - NVL(MV.MONTANT, 0) -
            NVL(ACG.MONTANTTTCAR - ACG.MONTANTPAYEAR, 0) AS NUMBER(30, 5))       AS MONTANTRESTE,
       CAST(NVL(ACG.MONTANTTTCAR, 0) AS NUMBER(30, 5))                           AS AVOIR,
       CAST(V2.TAUXDECHANGE AS NUMBER(10, 2))                                    AS TAUXDECHANGE,
       CAST(V2.MONTANTREVIENT AS NUMBER(20, 5))                                  AS MONTANTREVIENT,
       CAST((V2.MONTANTTTCAR - V2.MONTANTREVIENT) AS NUMBER(20, 5))              AS MARGEBRUTE,
       V.IDRESERVATION,
       CASE WHEN V.DATYPREVU IS NULL THEN V.DATY ELSE V.DATYPREVU END            AS DATYPREVU,
       RF.REFERENCE                                                              AS REFERENCEFACTURE,
       CAST(V2.MONTANTREMISE AS NUMBER(30, 5))                                   AS MONTANTREMISE,
       CAST(NVL(V2.MONTANTTOTAL, 0) + NVL(V2.MONTANTREMISE, 0) AS NUMBER(30, 5)) AS MONTANT,
       EXTRACT(MONTH FROM V.DATY)                                                AS MOIS,
       EXTRACT(YEAR FROM V.DATY)                                                 AS ANNEE,
       CAST(V2.POIDS AS NUMBER(30, 5))                                           AS POIDS,
       CAST(V2.COLIS AS NUMBER(30, 5))                                           AS COLIS,
       V.MODEPAIEMENT,
       MP.VAL                                                                    AS MODEPAIEMENTLIB,
       NVL(V.FRAISLIVRAISON, 0) * NVL(V2.POIDS, 0)                               AS FRAISLIVRAISON,
       V.MODELIVRAISON,
       CASE
           WHEN V.MODELIVRAISON = 1 THEN '<span style=color: green;>LIVRAISON</span>'
           WHEN V.MODELIVRAISON = 2 THEN '<span style=color: green;>RECUPERATION</span>'
           END                                                                   AS MODELIVRAISONLIB,
       CAST(VR.RESTE AS NUMBER(30, 5))                                           AS RESTE,
       PV.ID                                                                     AS IDPROVINCE,
       PV.VAL                                                                    AS PROVINCELIB,
       V.IDORIGINE,
       CAST(COALESCE(V.FRAISLIVRAISON, 0) AS NUMBER(30, 5))                      AS FRAIS,
       V.REFERENCEFACT,
       V.NUMEROFACTURE,
       V.LIEULIVRAISON,
       V.DATELIVRAISON,
       V.UPDATED_AT,
       CASE
           WHEN V.ESTPREVU = 0 THEN 'Non'
           ELSE 'Oui'
           END                                                                   AS ESTPREVULIB,
       CE.ID                                                                     AS IDECRITURE,
       NVL(BLC.DATY, V.DATELIVRAISON)                                            AS DATEDELIVRAISON,
       (
           V.ID || ' | ' || V.DESIGNATION || ' | ' || C.NOM || ' | ' || NUMEROFACTURE || ' | ' || PV.VAL
           )                                                                     AS MOTSCLESSS
FROM VENTE V
         LEFT JOIN CLIENT C ON C.ID = V.IDCLIENT
         LEFT JOIN PROVINCE PV ON PV.ID = C.IDPROVINCE
         LEFT JOIN MAGASINPOINT M ON M.ID = V.IDMAGASIN
         JOIN VENTEMONTANTLEGER V2 ON V2.ID = V.ID
         LEFT JOIN LIAISONPAIEMENTTOTAL MV ON V.ID = MV.ID2
         LEFT JOIN AVOIRFCMONTANT_GBVENTE ACG ON ACG.IDVENTE = V.ID
         LEFT JOIN REFERENCEFACTURE RF ON RF.IDFACTURE = V.ID
         LEFT JOIN MODEPAIEMENT MP ON MP.ID = V.MODEPAIEMENT
         LEFT JOIN VENTE_RESTE VR ON VR.IDVENTE = V.ID
         LEFT JOIN AS_BONDELIVRAISON_CLIENT BLC ON BLC.IDVENTE = V.ID
         LEFT JOIN COMPTA_ECRITURE CE ON CE.IDOBJET = V.ID
;
-- [1149/1309] COMPTA_ECRITURE_LIB
CREATE OR REPLACE FORCE VIEW "COMPTA_ECRITURE_LIB" ("ID","DATY","DATECOMPTABLE","EXERCICE","DESIGNATION","REMARQUE","ETAT","HORSEXERCICE","JOURNAL","OD","ORIGINE","CREDIT","DEBIT","IDUSER","PERIODE","TRIMESTRE","ANNEE","IDOBJET","MONTANT","JOURNALLIB","JOURNALCODE","ETATLIB","TIERSLIB","PIECE") AS
SELECT ce.ID,
       ce.DATY,
       ce.DATECOMPTABLE,
       ce.EXERCICE,
       ce.DESIGNATION,
       ce.REMARQUE,
       ce.ETAT,
       ce.HORSEXERCICE,
       ce.JOURNAL,
       ce.OD,
       ce.ORIGINE,
       ce.CREDIT,
       ce.DEBIT,
       ce.IDUSER,
       ce.PERIODE,
       ce.TRIMESTRE,
       ce.ANNEE,
       COALESCE(ce.IDOBJET , '-') as IDOBJET,
       CAST(cm.montant AS NUMBER(38, 2))                        AS montant,
       cj.desce                                                 AS JOURNALLIB,
       cj.val                                                   as JOURNALCODE,
       CASE
           WHEN ce.ETAT = 1 THEN 'Cree'
           WHEN ce.ETAT = 11 THEN 'Valide'
           ELSE 'Autre'
           END                                                  AS etatlib,
       COALESCE(fc.IDFOURNISSEURLIB, vc.idClientlib, mvc.tiers, '-') AS tierslib,
       CASE
           WHEN ce.ORIGINE = 'AVR' THEN '-'
           WHEN ce.ORIGINE = 'MTC' THEN COALESCE(vc_mtc.NUMEROFACTURE, fc_mtc.NUMERO, '-')
           WHEN ce.ORIGINE = 'MVT' THEN '-'
           WHEN ce.ORIGINE = 'VNT' THEN vc.NUMEROFACTURE
           WHEN ce.ORIGINE = 'FCF' THEN fc.NUMERO
           ELSE '-'
           END                                AS piece
FROM COMPTA_ECRITURE ce
         JOIN COMPTA_MONTANT cm ON ce.id = cm.IDMERE
         LEFT JOIN COMPTA_JOURNAL cj ON cj.id = ce.JOURNAL
         LEFT JOIN FACTUREFOURNISSEURCPL fc ON fc.id = ce.idobjet
         LEFT JOIN VENTE_CPL vc ON vc.id = ce.idobjet
         LEFT JOIN MOUVEMENTCAISSECPL mvc ON mvc.id = ce.idobjet
         LEFT JOIN VENTE_CPL vc_mtc ON vc_mtc.ID = mvc.IDORIGINE
         LEFT JOIN FACTUREFOURNISSEURCPL fc_mtc ON fc_mtc.ID = mvc.IDORIGINE
order by ce.DATY DESC
;
