-- [1155/1309] PLANNINGFACTURE
CREATE OR REPLACE FORCE VIEW "PLANNINGFACTURE" ("ID","IDCLIENT","DESIGNATION","DATY","MONTANTTOTAL","MONTANTRESTE","MONTANTPAYE","ETATPLANNING","ETATPAIEMENT") AS
SELECT
    v.ID,
    v.IDCLIENT,
    v.DESIGNATION,
    v.DATYPREVU AS DATY,
    v.MONTANTTTC AS MONTANTTOTAL,
    v.MONTANTRESTE,
    v.MONTANTPAYE,
    CASE
        WHEN v.DATYPREVU < SYSDATE THEN 1
        ELSE 0
        END etatPlanning,
    CASE
        WHEN v.MONTANTRESTE = 0 THEN 1
        ELSE 0
        END etatPaiement
FROM VENTE_CPL v
;
-- [1156/1309] PLANNINGFACTURELIB
CREATE OR REPLACE FORCE VIEW "PLANNINGFACTURELIB" ("ID","IDCLIENT","DESIGNATION","DATY","MONTANTTOTAL","MONTANTRESTE","MONTANTPAYE","ETATPLANNING","ETATPAIEMENT","ETATPAIEMENTLIB","IDCLIENTLIB") AS
SELECT p."ID",p."IDCLIENT",p."DESIGNATION",p."DATY",p."MONTANTTOTAL",p."MONTANTRESTE",p."MONTANTPAYE",p."ETATPLANNING",p."ETATPAIEMENT",
       CASE
           WHEN p.etatPaiement = 1 THEN 'Pay&eacute;'
           ELSE 'Impay&eacute;'
           END etatPaiementLib,
       c.NOM AS idClientLib
FROM PLANNINGFACTURE p
         LEFT JOIN CLIENT c ON p.IDCLIENT = c.ID
;
-- [1157/1309] TRAITE_FC
CREATE OR REPLACE FORCE VIEW "TRAITE_FC" ("ID","IDTRAITE","IDFC","MONTANTFACTURE","MONTANTJC","MONTANT","DATY","ETAT","CODE","TIERS","BANQUE","FACTURECLIENTLIB","TIERSLIB","ETATLIB") AS
select
    fc.ID,tl.id AS IDTRAITE,fc.id AS IDFC, FC.MONTANTTTC as MONTANTFACTURE, j.CREDIT as MONTANTJC, pf.MONTANT,fc.DATY,fc.ETAT,'' as CODE,
    tl.tiers,
    tl.banque,
    fc.designation as factureclientlib,
    fc.IDCLIENTLIB as TIERSLIB,
    CASE
        WHEN j.etat = 1
            THEN 'Cree'
        WHEN j.ETAT >= 11
            THEN 'visee'
        WHEN j.ETAT =0
            THEN 'Annulee'
        END AS etatlib
from LIAISONPAIEMENT pf
         LEFT JOIN MOUVEMENTCAISSE j ON j.ID  = pf.id2
         JOIN traite tl on tl.id = j.idtraite
         left join VENTE_CPL fc on pf.id1  = fc.id
;
-- [1158/1309] MONTANT_TRAITE_FC
CREATE OR REPLACE FORCE VIEW "MONTANT_TRAITE_FC" ("ID","IDTRAITE","MONTANTTRAITE") AS
select
    ID,IDTRAITE,
    sum(montant) AS montanttraite
from TRAITE_FC
GROUP BY ID,IDTRAITE
;
-- [1159/1309] TRAITE_FCLIB
CREATE OR REPLACE FORCE VIEW "TRAITE_FCLIB" ("IDTRAITE","IDFACT","CODE") AS
SELECT t.IDTRAITE ,t.idFc AS idfact,t.code FROM TRAITE_FC t
;
-- [1160/1309] TRAITELIB_GRP
CREATE OR REPLACE FORCE VIEW "TRAITELIB_GRP" ("IDTRAITE","CODE") AS
SELECT  IDTRAITE,LISTAGG(CODE , ';') WITHIN GROUP (ORDER BY CODE) AS CODE FROM TRAITE_FCLIB tf
GROUP BY IDTRAITE
;
-- [1161/1309] MVTINTRACAISSETRAITEV
CREATE OR REPLACE FORCE VIEW "MVTINTRACAISSETRAITEV" ("ID","DATY","CAISSEDEPART","CAISSEARRIVEE","MONTANT","MODEPAIEMENT","REMARQUE","ETAT","DESIGNATION","IDTRAITE","ETATVERSEMENT","IDFINALEDESTINATION","DATEECHEANCE","REFERENCE","TIERS","CODECLIENT","CAISSEDEPARTLIB","CAISSEARRIVEELIB","MODEPAIEMENTLIB","ETATLIB","ETATVERSEMENTLIB","FINALEDESTINATIONLIB","FACTURE") AS
SELECT
    mic.ID,mic.DATY,mic.CAISSEDEPART,mic.CAISSEARRIVEE,mic.MONTANT,mic.MODEPAIEMENT,mic.REMARQUE,mic.ETAT,mic.DESIGNATION,mic.IDTRAITE,mic.ETATVERSEMENT,mic.IDFINALEDESTINATION,
    t.Dateecheance,t.reference,t.tiers,t.CDCLT AS codeclient,
    c1.val AS caissedepartlib,
    c2.val AS caissearriveelib,
    m.Desce as modepaiementlib,
    case
        when mic.etat = 1 then 'CREE'
        when mic.etat >= 11 then 'VISE'
        else '' end                           as etatlib,
    case
        when mic.etatversement = -2 then 'encaissee'
        when mic.etatversement = 11 then 'versee'
        else '' end                           as etatversementlib,
    c3.val AS finaledestinationlib,
    grp.code AS facture
from mvtintracaisse mic
         JOIN traite_lib t on t.id = mic.idtraite
         LEFT JOIN CAISSE C1 on C1.id = mic.caissedepart
         LEFT JOIN CAISSE C2 on C2.id = mic.caissearrivee
         LEFT JOIN caisse C3 ON c3.id= mic.IDFINALEDESTINATION
         LEFT JOIN MODEPAIEMENT m on m.id = mic.modepaiement
         LEFT JOIN TRAITELIB_GRP grp ON mic.IDTRAITE = grp.idTraite
where mic.etatversement = 11 AND mic.IDTRAITE NOT IN (SELECT IDTRAITE FROM mvtintracaisse WHERE ETATVERSEMENT  = -2)
;
-- [1162/1309] TRAITE_FCSUM
CREATE OR REPLACE FORCE VIEW "TRAITE_FCSUM" ("ID","FACTURECLIENTLIB","TIERSLIB","DATY","MONTANTFACTURE","ETATLIB","IDTRAITE","MONTANTTRAITE") AS
SELECT
    t.id,
    t.factureclientlib,
    t.tierslib,
    t.daty,
    cast(t.montantfacture as number(30,2)),
    t.etatLib,
    t.idTraite,
    cast(m.montanttraite as number(30,2))
FROM TRAITE_FC t
         LEFT JOIN montant_traite_fc m ON m.id=t.id AND m.idtraite=t.IDTRAITE
;
-- [1163/1309] VENTECPLJOUR
CREATE OR REPLACE FORCE VIEW "VENTECPLJOUR" ("DATY","MONTANT") AS
select v.daty,sum(v.MONTANTTTC) as montant from VENTE_CPL v
group by v.daty
;
-- [1164/1309] VENTECPLJOUR_V2
CREATE OR REPLACE FORCE VIEW "VENTECPLJOUR_V2" ("DATY","IDPROVINCE","PROVINCELIB","MONTANT") AS
select v.daty,
       v.idprovince,
       v.provincelib,
       sum(v.MONTANTTTC) as montant
from VENTE_CPL v
where v.ETAT >= 11
group by v.daty, v.idprovince, v.provincelib
;
-- [1165/1309] VENTENONPAYE
CREATE OR REPLACE FORCE VIEW "VENTENONPAYE" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","DATYPREVU","MOIS","ANNEE","MOTSCLESSS") AS
SELECT ID,
       DESIGNATION,
       IDMAGASIN,
       IDMAGASINLIB,
       DATY,
       REMARQUE,
       ETAT,
       ETATLIB,
       MONTANTTOTAL,
       IDDEVISE,
       IDCLIENT,
       IDCLIENTLIB,
       MONTANTTVA,
       MONTANTTTC,
       MONTANTTTCAR,
       MONTANTPAYE,
       MONTANTRESTE,
       AVOIR,
       TAUXDECHANGE,
       MONTANTREVIENT,
       MARGEBRUTE,
       IDRESERVATION,
       DATYPREVU,
       MOIS,
       ANNEE,
       (
           ID || ' | ' || DESIGNATION || ' | ' || IDCLIENTLIB || ' | ' || IDDEVISE
           ) AS MOTSCLESSS
FROM VENTE_CPL
WHERE ETAT >= 11
  AND MONTANTREMISE = 0
;
-- [1166/1309] VENTE_CPL_EUR
