-- [1170/1309] VENTE_CPL_SANSAVOIR
CREATE OR REPLACE FORCE VIEW "VENTE_CPL_SANSAVOIR" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","DATYPREVU","REFERENCEFACTURE","MONTANTREMISE","MONTANT","MOIS","ANNEE","POIDS","MODEPAIEMENT","MODEPAIEMENTLIB","FRAISLIVRAISON","MODELIVRAISON","MODELIVRAISONLIB","RESTE","IDPROVINCE","PROVINCELIB","NUMFACT") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       m.VAL                                                        AS IDMAGASINLIB,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       CASE
           WHEN v.ETAT = 1 THEN 'CREE'
           WHEN v.ETAT = 11 THEN 'VISE'
           WHEN v.ETAT = 0 THEN 'ANNULE'
           END
                                                                    AS ETATLIB,
       v2.MONTANTTOTAL,
       v2.IDDEVISE,
       v.IDCLIENT,
       c.NOM                                                        AS IDCLIENTLIB,
       cast(V2.MONTANTTVA as number(30, 2))                         as MONTANTTVA,
       cast(V2.MONTANTTTC as number(30, 2))                         as montantttc,
       cast(V2.MONTANTTTCAR as number(30, 2))                       as MONTANTTTCAR,
       cast(nvl(mv.montant, 0) AS NUMBER(30, 2))                    AS montantpaye,
       cast(V2.MONTANTTTC - nvl(mv.montant, 0) AS NUMBER(30, 2))    AS montantreste,
       v2.tauxDeChange                                              AS tauxDeChange,
       v2.MONTANTREVIENT,
       cast((V2.MONTANTTTCAR - v2.MONTANTREVIENT) as number(20, 2)) as margeBrute,
       v.IDRESERVATION,
       case when v.DATYPREVU is null then daty else V.DATYPREVU end as datyprevu,
       rf.REFERENCE                                                 as referencefacture,
       v2.MONTANTREMISE,
       nvl(v2.MONTANTTOTAL, 0) + nvl(v2.MONTANTREMISE, 0)           as montant,
       extract(month from DATY)                                     as mois,
       extract(year from DATY)                                      as annee,
       vp.poids,
       v.modepaiement,
       mp.VAL                                                       as modepaiementlib,
       nvl(v.fraislivraison, 0) * nvl(vp.poids, 0)                  as fraislivraison,
       v.modelivraison,
       CASE
           WHEN v.modelivraison = 1 THEN '<span style=color: green;>LIVRAISON</span>'
           WHEN v.modelivraison = 2 THEN '<span style=color: green;>RECUPERATION</span>'
           END                                                      AS modelivraisonlib,
       vr.reste,
       pv.id                                                        as idprovince,
       pv.val                                                       as provincelib,
       v.NUMEROFACTURE as numfact
FROM VENTE v
         LEFT JOIN CLIENT c ON c.ID = v.IDCLIENT
         left join PROVINCE pv on pv.id = c.IDPROVINCE
         LEFT JOIN MAGASINPOINT m ON m.ID = v.IDMAGASIN
         JOIN VENTEMONTANT v2 ON v2.ID = v.ID
         LEFT JOIN LIAISONPAIEMENTTOTAL mv ON v.id = mv.id2
         LEFT JOIN REFERENCEFACTURE rf ON rf.idfacture = v.Id
         left join vente_poids vp on vp.idvente = v.id
         left join MODEPAIEMENT mp on mp.id = v.modepaiement
         left join vente_reste vr on vr.idvente = v.id
;
-- [1171/1309] AVOIRFCLIB
CREATE OR REPLACE FORCE VIEW "AVOIRFCLIB" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","COMPTE","COMPTEAUXILIAIRE","IDVENTE","IDVENTELIB","IDMOTIF","IDMOTIFLIB","IDCATEGORIE","IDCATEGORIELIB","IDDEVISE","TAUXDECHANGE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","IDRESERVATION","TYPEAVOIR","CLIENTLIB","NUMAVOIR","IDRISTOURNE","MONTANTRESTE","NUMFACT") AS
SELECT a.ID,
       a.DESIGNATION,
       a.IDMAGASIN,
       m.VAL         AS IDMAGASINLIB,
       a.DATY,
       a.REMARQUE,
       a.ETAT,
       a.IDORIGINE,
       a.IDCLIENT,
       t.COMPTE,
       t.compteauxiliaire,
       a.IDVENTE,
       v.DESIGNATION AS IDVENTELIB,
       a.IDMOTIF,
       ma.VAL        AS IDMOTIFLIB,
       a.IDCATEGORIE,
       c.VAL         AS IDCATEGORIELIB,
       ag.IDDEVISE,
       ag.TAUXDECHANGE,
       ag.MONTANTHT,
       ag.MONTANTTVA,
       ag.MONTANTTTC,
       ag.MONTANTHTAR,
       ag.MONTANTTVAAR,
       ag.MONTANTTTCAR,
       v.IDRESERVATION,
       ta.val        as Typeavoir,
       t.NOM         as clientlib,
       a.numavoir,
       a.idristourne,
       v.MONTANTRESTE,
       v.NUMFACT
FROM AVOIRFC a
         LEFT JOIN magasin2 m ON m.id = a.IDMAGASIN
         LEFT JOIN VENTE_CPL_SANSAVOIR v ON v.id = a.IDVENTE
         LEFT JOIN MOTIFAVOIRFC ma ON ma.id = a.IDMOTIF
         LEFT JOIN CATEGORIEAVOIRFC c ON c.id = a.IDCATEGORIE
         JOIN AVOIRFCFILLE_GRP ag ON ag.idavoirfc = a.id
         LEFT JOIN TIERS T ON T.ID = A.IDCLIENT
         left join TYPEAVOIR ta on ta.id = a.IDTYPEAVOIR
;
-- [1172/1309] AVOIRFCLIB_CPL
CREATE OR REPLACE FORCE VIEW "AVOIRFCLIB_CPL" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","COMPTE","IDVENTE","IDVENTELIB","IDMOTIF","IDMOTIFLIB","IDCATEGORIE","IDCATEGORIELIB","IDDEVISE","TAUXDECHANGE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","MONTANTPAYE","MONTANTPAYEAR","MONTANT_RESTE_FACTURE","MONTANT_AVOIRS_ANTERIEURS","RESTE_CALCULE","EXCEDENT_AR","RESTEAPAYER","RESTEAPAYERAR","CLIENTLIB","TYPEAVOIR","NUMFACT","MOTSCLESSS") AS
SELECT AL.ID,
       AL.DESIGNATION,
       AL.IDMAGASIN,
       AL.IDMAGASINLIB,
       AL.DATY,
       AL.REMARQUE,
       AL.ETAT,
       AL.IDORIGINE,
       AL.IDCLIENT,
       AL.COMPTE,
       AL.IDVENTE,
       AL.IDVENTELIB,
       AL.IDMOTIF,
       AL.IDMOTIFLIB,
       AL.IDCATEGORIE,
       AL.IDCATEGORIELIB,
       AL.IDDEVISE,
       AL.TAUXDECHANGE,
       AL.MONTANTHT,
       AL.MONTANTTVA,
       AL.MONTANTTTC,
       AL.MONTANTHTAR,
       AL.MONTANTTVAAR,
       AL.MONTANTTTCAR,
       NVL(M.MONTANT, 0)                                        AS MONTANTPAYE,
       NVL(M.MONTANT, 0) * NVL(AL.TAUXDECHANGE, 0)              AS MONTANTPAYEAR,

       NVL(VC.MONTANTRESTE, 0)                                  AS MONTANT_RESTE_FACTURE,

       NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0)         AS MONTANT_AVOIRS_ANTERIEURS,
       CASE
           WHEN NVL(VC.MONTANTRESTE, 0) = 0 THEN 0
           ELSE NVL(VC.MONTANTRESTE, 0) - NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0) - NVL(AL.MONTANTTTCAR, 0)
           END                                                  AS RESTE_CALCULE,
       CASE
           WHEN NVL(VC.MONTANTRESTE, 0) = 0 THEN NVL(AL.MONTANTTTCAR, 0)
           WHEN NVL(VC.MONTANTRESTE, 0) - NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0) - NVL(AL.MONTANTTTCAR, 0) < 0
               THEN ABS(NVL(VC.MONTANTRESTE, 0) - NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0) -
                        NVL(AL.MONTANTTTCAR, 0))
           ELSE 0
           END                                                  AS EXCEDENT_AR,
       (CASE
            WHEN NVL(VC.MONTANTRESTE, 0) = 0 THEN NVL(AL.MONTANTTTCAR, 0)
            WHEN NVL(VC.MONTANTRESTE, 0) - NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0) - NVL(AL.MONTANTTTCAR, 0) <
                 0
                THEN ABS(NVL(VC.MONTANTRESTE, 0) - NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0) -
                         NVL(AL.MONTANTTTCAR, 0))
            ELSE 0
           END) - NVL(M.MONTANT, 0)                             AS RESTEAPAYER,
       (CASE
            WHEN NVL(VC.MONTANTRESTE, 0) = 0 THEN NVL(AL.MONTANTTTCAR, 0)
            WHEN NVL(VC.MONTANTRESTE, 0) - NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0) - NVL(AL.MONTANTTTCAR, 0) <
                 0
                THEN ABS(NVL(VC.MONTANTRESTE, 0) - NVL(SUM_PRECEDENTS.MONTANT_AVOIRS_PRECEDENTS, 0) -
                         NVL(AL.MONTANTTTCAR, 0))
            ELSE 0
           END) - (NVL(M.MONTANT, 0) * NVL(AL.TAUXDECHANGE, 0)) AS RESTEAPAYERAR,
       AL.CLIENTLIB,
       AL.TYPEAVOIR,
       VC.NUMFACT,
       (
           NVL(TO_CHAR(AL.ID), '') || ' | ' ||
           AL.ID || ' | ' || CLIENTLIB || ' | ' ||  AL.IDMAGASINLIB || ' | ' || VC.NUMFACT || ' | ' ||
           TYPEAVOIR || ' | ' || IDMOTIFLIB || ' | ' || IDCATEGORIELIB
           )                                                    AS MOTSCLESSS
FROM AVOIRFCLIB AL
         LEFT JOIN MOUVEMENTCAISSEGRPAVOIR_LP M
                   ON AL.ID = M.IDORIGINE
         LEFT JOIN VENTE_CPL_SANSAVOIR VC
                   ON VC.ID = AL.IDVENTE
         LEFT JOIN (SELECT A2.IDVENTE,
                           A2.ID                AS IDCOURANT,
                           SUM(A1.MONTANTTTCAR) AS MONTANT_AVOIRS_PRECEDENTS
                    FROM AVOIRFCLIB A1
                             JOIN AVOIRFCLIB A2 ON A1.IDVENTE = A2.IDVENTE
                    WHERE A1.ETAT <> 0
                      AND (A1.DATY < A2.DATY OR (A1.DATY = A2.DATY AND A1.ID < A2.ID))
                    GROUP BY A2.IDVENTE, A2.ID) SUM_PRECEDENTS
                   ON SUM_PRECEDENTS.IDVENTE = AL.IDVENTE
                       AND SUM_PRECEDENTS.IDCOURANT = AL.ID
;
-- [1173/1309] AVOIRFCLIB_CPL_CREE
CREATE OR REPLACE FORCE VIEW "AVOIRFCLIB_CPL_CREE" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","COMPTE","IDVENTE","IDVENTELIB","IDMOTIF","IDMOTIFLIB","IDCATEGORIE","IDCATEGORIELIB","IDDEVISE","TAUXDECHANGE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","MONTANTPAYE","MONTANTPAYEAR","RESTEAPAYER","RESTEAPAYERAR") AS
