-- [1175/1309] AVOIRFCLIB_CPL_V2
CREATE OR REPLACE FORCE VIEW "AVOIRFCLIB_CPL_V2" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","COMPTE","IDVENTE","IDVENTELIB","IDMOTIF","IDMOTIFLIB","IDCATEGORIE","IDCATEGORIELIB","IDDEVISE","TAUXDECHANGE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","MONTANTPAYE","MONTANTPAYEAR","MONTANT_RESTE_FACTURE","MONTANT_AVOIRS_ANTERIEURS","RESTE_CALCULE","EXCEDENT_AR","RESTEAPAYER","RESTEAPAYERAR","CLIENTLIB","TYPEAVOIR","NUMFACT") AS
SELECT AL.ID,
       AL.DESIGNATION,
       AL.IDMAGASIN,
       AL.IDMAGASINLIB,
       AL.DATY,
       AL.REMARQUE,
       AL.ETAT,
       AL.IDORIGINE,
       AL.IDCLIENT,
       AL.COMPTE,
       AL.IDVENTE,
       AL.IDVENTELIB,
       AL.IDMOTIF,
       AL.IDMOTIFLIB,
       AL.IDCATEGORIE,
       AL.IDCATEGORIELIB,
       AL.IDDEVISE,
       AL.TAUXDECHANGE,
       AL.MONTANTHT,
       AL.MONTANTTVA,
       AL.MONTANTTTC,
       AL.MONTANTHTAR,
       AL.MONTANTTVAAR,
       AL.MONTANTTTCAR,
       nvl(M.montant, 0)                                        AS MONTANTPAYE,
       NVL(M.montant, 0) * NVL(AL.TAUXDECHANGE, 0)              AS MONTANTPAYEAR,

       NVL(AL.MONTANTRESTE, 0)                                  AS MONTANT_RESTE_FACTURE ,

       0         AS MONTANT_AVOIRS_ANTERIEURS,
       -- Cas 1 : facture deja soldee -> chaque avoir = credit direct (exedent)
       CASE
           WHEN NVL(AL.MONTANTRESTE, 0) = 0 THEN 0
           ELSE NVL(AL.MONTANTRESTE, 0)  - NVL(AL.MONTANTTTCAR, 0)
           END                                                  AS RESTE_CALCULE,
       -- Excedent a rembourser ou a reporter
       CASE
           WHEN NVL(AL.MONTANTRESTE, 0) = 0 THEN NVL(AL.MONTANTTTCAR, 0)
           WHEN NVL(AL.MONTANTRESTE, 0) - NVL(AL.MONTANTTTCAR, 0) < 0
               THEN ABS(NVL(AL.MONTANTRESTE, 0)  -
                        NVL(AL.MONTANTTTCAR, 0))
           ELSE 0
           END                                                  AS EXCEDENT_AR,
       (CASE
            WHEN NVL(AL.MONTANTRESTE, 0) = 0 THEN NVL(AL.MONTANTTTCAR, 0)
            WHEN NVL(AL.MONTANTRESTE, 0) - NVL(AL.MONTANTTTCAR, 0) <
                 0
                THEN ABS(NVL(AL.MONTANTRESTE, 0)  -
                         NVL(AL.MONTANTTTCAR, 0))
            ELSE 0
           END) - NVL(M.montant, 0)                             AS resteapayer,
       (CASE
            WHEN NVL(AL.MONTANTRESTE, 0) = 0 THEN NVL(AL.MONTANTTTCAR, 0)
            WHEN NVL(AL.MONTANTRESTE, 0)  - NVL(AL.MONTANTTTCAR, 0) <
                 0
                THEN ABS(NVL(AL.MONTANTRESTE, 0)  -
                         NVL(AL.MONTANTTTCAR, 0))
            ELSE 0
           END) - (NVL(M.montant, 0) * NVL(AL.TAUXDECHANGE, 0)) AS resteapayerar,
       AL.clientlib,
       AL.Typeavoir,
       AL.NUMFACT
FROM AVOIRFCLIB AL
         LEFT JOIN MOUVEMENTCAISSEGRPAVOIR_LP M
                   ON AL.ID = M.IDORIGINE
;
-- [1176/1309] AVOIRFCLIB_CPL_V2_VISEE
CREATE OR REPLACE FORCE VIEW "AVOIRFCLIB_CPL_V2_VISEE" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","COMPTE","IDVENTE","IDVENTELIB","IDMOTIF","IDMOTIFLIB","IDCATEGORIE","IDCATEGORIELIB","IDDEVISE","TAUXDECHANGE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","MONTANTPAYE","MONTANTPAYEAR","RESTEAPAYER","RESTEAPAYERAR","IMPUTEEFACT","IMPUTEEFACTAR") AS
select ID,
       DESIGNATION,
       IDMAGASIN,
       IDMAGASINLIB,
       DATY,
       REMARQUE,
       ETAT,
       IDORIGINE,
       IDCLIENT,
       COMPTE,
       IDVENTE,
       IDVENTELIB,
       IDMOTIF,
       IDMOTIFLIB,
       IDCATEGORIE,
       IDCATEGORIELIB,
       IDDEVISE,
       TAUXDECHANGE,
       MONTANTHT,
       MONTANTTVA,
       MONTANTTTC,
       MONTANTHTAR,
       MONTANTTVAAR,
       MONTANTTTCAR,
       MONTANTPAYE,
       MONTANTPAYEAR,
       RESTEAPAYER,
       RESTEAPAYERAR,
       MONTANTTTC - MONTANTPAYE     as imputeefact,
       MONTANTTTCar - MONTANTPAYEar as imputeefactar
from AVOIRFCLIB_CPL_V2
where ETAT >= 11
;
-- [1177/1309] AVOIRFCLIB_CPL_V2_GRP
CREATE OR REPLACE FORCE VIEW "AVOIRFCLIB_CPL_V2_GRP" ("IDVENTE","IDDEVISE","MONTANTHT_AVR","MONTANTTVA_AVR","MONTANTTTC_AVR","MONTANTHTAR_AVR","MONTANTTVAAR_AVR","MONTANTTTCAR_AVR","MONTANTPAYE","MONTANTPAYEAR","RESTEAPAYER_AVR","RESTEAPAYERAR_AVR","IMPUTEEFACT","IMPUTEEFACTAR") AS
SELECT AL.IDVENTE,
       AL.IDDEVISE,
       SUM(MONTANTHT)     as MONTANTHT_avr,
       SUM(MONTANTTVA)    as MONTANTTVA_avr,
       SUM(MONTANTTTC)    as MONTANTTTC_avr,
       SUM(MONTANTHTAR)   as MONTANTHTAR_avr,
       SUM(MONTANTTVAAR)  as MONTANTTVAAR_avr,
       SUM(MONTANTTTCAR)  as MONTANTTTCAR_avr,
       SUM(MONTANTPAYE)   as MONTANTPAYE,
       SUM(MONTANTPAYEAR) as MONTANTPAYEAR,
       SUM(RESTEAPAYER)   as resteapayer_avr,
       SUM(RESTEAPAYERAR) as resteapayerar_avr,
       SUM(imputeefact)   as imputeefact,
       SUM(imputeefactar) as imputeefactar
from AVOIRFCLIB_CPL_V2_VISEE AL
group by IDVENTE, IDDEVISE
;
-- [1178/1309] AVOIRFCLIB_CPL_VISEE
CREATE OR REPLACE FORCE VIEW "AVOIRFCLIB_CPL_VISEE" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","IDORIGINE","IDCLIENT","COMPTE","IDVENTE","IDVENTELIB","IDMOTIF","IDMOTIFLIB","IDCATEGORIE","IDCATEGORIELIB","IDDEVISE","TAUXDECHANGE","MONTANTHT","MONTANTTVA","MONTANTTTC","MONTANTHTAR","MONTANTTVAAR","MONTANTTTCAR","MONTANTPAYE","MONTANTPAYEAR","RESTEAPAYER","RESTEAPAYERAR","IMPUTEEFACT","IMPUTEEFACTAR") AS
select ID,
