       IDMAGASIN,
       IDMAGASINLIB,
       DATY,
       REMARQUE,
       ETAT,
       IDORIGINE,
       IDCLIENT,
       COMPTE,
       IDVENTE,
       IDVENTELIB,
       IDMOTIF,
       IDMOTIFLIB,
       IDCATEGORIE,
       IDCATEGORIELIB,
       IDDEVISE,
       TAUXDECHANGE,
       MONTANTHT,
       MONTANTTVA,
       MONTANTTTC,
       MONTANTHTAR,
       MONTANTTVAAR,
