       MONTANTTTC - MONTANTPAYE     as imputeefact,
       MONTANTTTCar - MONTANTPAYEar as imputeefactar
from avoirfclib_cpl
where ETAT >= 11
;
-- [1179/1309] AVOIRFCLIB_CPL_GRP
CREATE OR REPLACE FORCE VIEW "AVOIRFCLIB_CPL_GRP" ("IDVENTE","IDDEVISE","MONTANTHT_AVR","MONTANTTVA_AVR","MONTANTTTC_AVR","MONTANTHTAR_AVR","MONTANTTVAAR_AVR","MONTANTTTCAR_AVR","MONTANTPAYE","MONTANTPAYEAR","RESTEAPAYER_AVR","RESTEAPAYERAR_AVR","IMPUTEEFACT","IMPUTEEFACTAR") AS
SELECT AL.IDVENTE,
       AL.IDDEVISE,
       SUM(MONTANTHT)     as MONTANTHT_avr,
       SUM(MONTANTTVA)    as MONTANTTVA_avr,
       SUM(MONTANTTTC)    as MONTANTTTC_avr,
       SUM(MONTANTHTAR)   as MONTANTHTAR_avr,
       SUM(MONTANTTVAAR)  as MONTANTTVAAR_avr,
       SUM(MONTANTTTCAR)  as MONTANTTTCAR_avr,
       SUM(MONTANTPAYE)   as MONTANTPAYE,
       SUM(MONTANTPAYEAR) as MONTANTPAYEAR,
       SUM(RESTEAPAYER)   as resteapayer_avr,
       SUM(RESTEAPAYERAR) as resteapayerar_avr,
       SUM(imputeefact)   as imputeefact,
       SUM(imputeefactar) as imputeefactar
from avoirfclib_cpl_visee AL
group by IDVENTE, IDDEVISE
;
-- [1180/1309] MOUVEMENTCAISSECPL_V_D_AVOIR
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSECPL_V_D_AVOIR" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","IDVENTEDETAIL","IDVIREMENT","DEBIT","CREDIT","MONTANTIMPUTE","DATY","ETAT","ETATLIB","IDVENTE","IDORIGINE","IDTIERS","TIERS","IDPAIEMENT","REFERENCEPAIEMENT","DESIGNATIONPAIEMENT") AS
SELECT m.ID,
       DESIGNATION,
       IDCAISSE,
       IDCAISSELIB,
       IDVENTEDETAIL,
       IDVIREMENT,
       DEBIT,
       CREDIT,
       lp.MONTANT as montantimpute,
       DATY,
       m.ETAT,
       ETATLIB,
       IDVENTE,
       id2 as IDORIGINE,
       IDTIERS,
       TIERS,
       id1 as idpaiement,
       m.REFERENCE as referencepaiement,
       m.DESIGNATION as designationpaiement
FROM LIAISONPAIEMENT lp LEFT JOIN
    MOUVEMENTCAISSECPL m on m.id = lp.ID1
WHERE m.etat > 7
UNION ALL
SELECT m.ID,
       m.DESIGNATION,
       '' as IDCAISSE,
       '' as IDCAISSELIB,
       '' as IDVENTEDETAIL,
       '' as IDVIREMENT,
       0 as DEBIT,
       m.MONTANTTTCAR as CREDIT,
       lp.MONTANT as montantimpute,
       DATY,
       m.ETAT,
       '' as ETATLIB,
       IDVENTE,
       id2 as IDORIGINE,
       m.IDCLIENT as IDTIERS,
       m.CLIENTLIB as TIERS,
       id1 as idpaiement,
       m.id as referencepaiement,
       'NOTE DE CREDIT'as designationpaiement
FROM LIAISONPAIEMENT lp LEFT JOIN
    AVOIRFCLIB_CPL m on m.id = lp.ID1
WHERE m.etat > 7
;
-- [1181/1309] MOUVEMENTCAISSE_DETAIL
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSE_DETAIL" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","IDOBJET","MONTANTIMPUTE","REFERENCEPAIEMENT","IDPAIEMENT","DESIGNATIONPAIEMENT","NUMEROFACTURE","UPDATED_AT") AS
select v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       v.IDMAGASINLIB,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       v.ETATLIB,
       v.MONTANTTOTAL,
       v.IDDEVISE,
       v.IDCLIENT,
       v.IDCLIENTLIB,
       v.MONTANTTVA,
       v.MONTANTTTC,
       v.MONTANTTTCAR,
       v.MONTANTPAYE,
       v.MONTANTRESTE,
       v.AVOIR,
       v.TAUXDECHANGE,
       v.MONTANTREVIENT,
       v.MARGEBRUTE,
       v.IDRESERVATION,
       mv.id as idobjet,
       mv.montantimpute,
       referencepaiement,
       idpaiement,
       designationpaiement,
       v.NUMEROFACTURE,
       v.UPDATED_AT
from VENTE_CPL v
         left join MOUVEMENTCAISSECPL_V_D_avoir mv on v.id = mv.idorigine
;
-- [1182/1309] MOUVEMENTCAISSE_DETAIL_UNIQUE
CREATE OR REPLACE FORCE VIEW "MOUVEMENTCAISSE_DETAIL_UNIQUE" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","NUMEROFACTURE","UPDATED_AT","TOTALIMPUTE","REFERENCES_PAIEMENT") AS
SELECT
    v.ID,
    v.DESIGNATION,
    v.IDMAGASIN,
    v.IDMAGASINLIB,
    v.DATY,
    v.REMARQUE,
    v.ETAT,
    v.ETATLIB,
    v.MONTANTTOTAL,
    v.IDDEVISE,
    v.IDCLIENT,
    v.IDCLIENTLIB,
    v.MONTANTTVA,
    v.MONTANTTTC,
    v.MONTANTTTCAR,
    v.MONTANTPAYE,
    v.MONTANTRESTE,
    v.AVOIR,
    v.TAUXDECHANGE,
    v.MONTANTREVIENT,
    v.MARGEBRUTE,
    v.IDRESERVATION,
    v.NUMEROFACTURE,
    v.UPDATED_AT,
    -- ? Somme des montants imputes
    SUM(v.montantimpute) AS TOTALIMPUTE,
    -- ? Concatenation des references paiement (separees par //)
    LISTAGG(v.designationpaiement ||' '|| v.referencepaiement, ' // ') WITHIN GROUP (ORDER BY v.designationpaiement || v.referencepaiement) AS REFERENCES_PAIEMENT
FROM MOUVEMENTCAISSE_DETAIL v
GROUP BY
    v.ID,
    v.DESIGNATION,
    v.IDMAGASIN,
    v.IDMAGASINLIB,
    v.DATY,
    v.REMARQUE,
    v.ETAT,
    v.ETATLIB,
    v.MONTANTTOTAL,
    v.IDDEVISE,
    v.IDCLIENT,
    v.IDCLIENTLIB,
    v.MONTANTTVA,
    v.MONTANTTTC,
    v.MONTANTTTCAR,
    v.MONTANTPAYE,
    v.MONTANTRESTE,
    v.AVOIR,
    v.TAUXDECHANGE,
    v.MONTANTREVIENT,
    v.MARGEBRUTE,
    v.IDRESERVATION, v.NUMEROFACTURE, v.UPDATED_AT
;
-- [1183/1309] RELEVECLIENT
CREATE OR REPLACE FORCE VIEW "RELEVECLIENT" ("ID","JOURNAL","REFERENCE","DATY","LIBELLE","LETTRE","DEBIT","CREDIT","IDCLIENT","CLIENTLIB","COMPTE","UPDATED_AT","SOLDE","ANNEE","MOTSCLESSS") AS
SELECT SQ.ID,
       SQ.JOURNAL,
       SQ.REFERENCE,
       SQ.DATY,
       SQ.LIBELLE,
       SQ.LETTRE,
       CAST(SQ.DEBIT AS NUMBER(30, 5))  AS DEBIT,
       CAST(SQ.CREDIT AS NUMBER(30, 5)) AS CREDIT,
       SQ.IDCLIENT,
       SQ.CLIENTLIB,
       SQ.COMPTE,
       SQ.UPDATED_AT,
       CAST(SQ.SOLDE AS NUMBER(30, 5))  AS SOLDE,
       SQ.ANNEE,
       (
           ID || ' | ' || JOURNAL || ' | ' || REFERENCE || ' | ' || CLIENTLIB || ' | ' || LIBELLE || ' | ' || LETTRE
           )                            AS MOTSCLESSS
FROM (SELECT RELEVER.ID,
             RELEVER.JOURNAL,
             RELEVER.REFERENCE,
             RELEVER.DATY,
             RELEVER.LIBELLE,
             RELEVER.LETTRE,
             RELEVER.DEBIT,
             RELEVER.CREDIT,
             RELEVER.IDCLIENT,
             T.NOM                           AS CLIENTLIB,
             NVL(RELEVER.COMPTE, T.COMPTE)   AS COMPTE,
             RELEVER.UPDATED_AT,
             RELEVER.SOLDE,
             EXTRACT(YEAR FROM RELEVER.DATY) AS ANNEE,

             ROW_NUMBER() OVER (
                 PARTITION BY RELEVER.ID, RELEVER.JOURNAL, RELEVER.REFERENCE, RELEVER.DATY
                 ORDER BY
                     CASE
                         WHEN RELEVER.LETTRE IS NOT NULL AND TRIM(RELEVER.LETTRE) IS NOT NULL THEN 0
                         ELSE 1
                         END
                 )                           AS RN

      FROM (

               /* NOTE DE CREDIT / AVOIR CLIENT */
               SELECT AV.ID                        AS ID,
                      NVL(CJ.DESCE, ' ')           AS JOURNAL,
                      AV.ID                        AS REFERENCE,
                      AV.DATY                      AS DATY,
                      'NOTE DE CREDIT : ' || AV.ID AS LIBELLE,
                      NVL(CL.LETTRE, ' ')          AS LETTRE,
                      0                            AS DEBIT,
                      AV.MONTANTTTCAR              AS CREDIT,
                      AV.IDCLIENT                  AS IDCLIENT,
                      SOUS.COMPTE                  AS COMPTE,
                      AV.DATY                      AS UPDATED_AT,
                      AV.MONTANTTTCAR * -1         AS SOLDE
               FROM AVOIRFCLIB_CPL_VISEE AV
                        JOIN COMPTA_ECRITURE ECR ON ECR.IDOBJET = AV.ID
                        JOIN COMPTA_SOUS_ECRITURE SOUS ON SOUS.IDMERE = ECR.ID
                        LEFT JOIN COMPTA_LETTRAGE CL ON CL.ID = SOUS.LETTRAGE
                        LEFT JOIN COMPTA_JOURNAL CJ ON CJ.ID = SOUS.JOURNAL
               WHERE SOUS.COMPTE LIKE '411%'

               UNION ALL

               /* FACTURE / VENTE CLIENT */
               SELECT MCD.ID                            AS ID,
                      NVL(CJ.DESCE, ' ')                AS JOURNAL,
                      MCD.NUMEROFACTURE                 AS REFERENCE,
                      MCD.DATY                          AS DATY,
                      NVL(MCD.REFERENCES_PAIEMENT, ' ') AS LIBELLE,
                      NVL(CL.LETTRE, ' ')               AS LETTRE,
                      MCD.MONTANTTTCAR                  AS DEBIT,
                      0                                 AS CREDIT,
                      MCD.IDCLIENT                      AS IDCLIENT,
                      SOUS.COMPTE                       AS COMPTE,
                      MCD.UPDATED_AT                    AS UPDATED_AT,
                      MCD.MONTANTTTCAR                  AS SOLDE
               FROM MOUVEMENTCAISSE_DETAIL_UNIQUE MCD
                        JOIN COMPTA_ECRITURE ECR ON ECR.IDOBJET = MCD.ID
                        JOIN COMPTA_SOUS_ECRITURE SOUS ON SOUS.IDMERE = ECR.ID
                        LEFT JOIN COMPTA_LETTRAGE CL ON CL.ID = SOUS.LETTRAGE
                        LEFT JOIN COMPTA_JOURNAL CJ ON CJ.ID = SOUS.JOURNAL
               WHERE MCD.ETAT >= 7
                 AND SOUS.COMPTE LIKE '411%'

               UNION ALL

               /* REGLEMENT CLIENT */
               SELECT MC.ID                   AS ID,
                      NVL(CJ.DESCE, ' ')      AS JOURNAL,
                      MC.ID                   AS REFERENCE,
                      MC.DATYCOMPTABILISATION AS DATY,
                      MC.DESIGNATION          AS LIBELLE,
                      NVL(CL.LETTRE, ' ')     AS LETTRE,
                      0                       AS DEBIT,
                      MC.CREDIT               AS CREDIT,
                      MC.IDTIERS              AS IDCLIENT,
                      SOUS.COMPTE             AS COMPTE,
                      MC.UPDATED_AT           AS UPDATED_AT,
                      MC.CREDIT * -1          AS SOLDE
               FROM MOUVEMENTCAISSECPL MC
                        JOIN COMPTA_ECRITURE ECR ON ECR.IDOBJET = MC.ID
                        JOIN COMPTA_SOUS_ECRITURE SOUS ON SOUS.IDMERE = ECR.ID
                        LEFT JOIN COMPTA_LETTRAGE CL ON CL.ID = SOUS.LETTRAGE
                        LEFT JOIN COMPTA_JOURNAL CJ ON CJ.ID = SOUS.JOURNAL
               WHERE MC.ETAT > 8
                 AND SOUS.COMPTE LIKE '411%') RELEVER
               LEFT JOIN TIERS T ON T.ID = RELEVER.IDCLIENT) SQ
WHERE SQ.RN = 1
;
-- [1184/1309] VENTE_CPL_CL
CREATE OR REPLACE FORCE VIEW "VENTE_CPL_CL" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","DATYPREVU","REFERENCEFACTURE","MONTANTREMISE","MONTANT","MOIS","ANNEE","POIDS","COLIS","MODEPAIEMENT","MODEPAIEMENTLIB","FRAISLIVRAISON","MODELIVRAISON","MODELIVRAISONLIB","RESTE","IDPROVINCE","PROVINCELIB","IDORIGINE","FRAIS","REFERENCEFACT","NUMEROFACTURE","LIEULIVRAISON","DATELIVRAISON","UPDATED_AT","ESTPREVULIB","IDECRITURE","DATEDELIVRAISON","ADRESSE") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       m.VAL                                                                                         AS IDMAGASINLIB,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       CASE
           WHEN v.ETAT = 1 THEN 'CR&Eacute;&Eacute;E'
           WHEN v.ETAT = 11 THEN 'VIS&Eacute;E'
           WHEN v.ETAT = 0 THEN 'ANNUL&Eacute;E'
           END
                                                                                                     AS ETATLIB,
       cast(v2.MONTANTTOTAL as number(30, 5)) AS MONTANTTOTAL,
       v2.IDDEVISE,
       v.IDCLIENT,
       c.NOM                                                                                         AS IDCLIENTLIB,
       cast(V2.MONTANTTVA as number(30, 5))                                                          as MONTANTTVA,
       cast(V2.MONTANTTTC as number(30, 5))                                                          as montantttc,
       cast(V2.MONTANTTTCAR as number(30, 5))                                                        as MONTANTTTCAR,
       cast(nvl(mv.montant, 0) AS number(30, 5))                                                     AS montantpaye,
       cast(nvl(V2.MONTANTTTC, 0) - nvl(mv.montant, 0) - nvl(ACG.imputeefactar, 0) AS number(30, 5)) AS montantreste,
       cast(nvl(ACG.MONTANTTTC_avr, 0) as number(30, 5))                                             as avoir,
       cast(v2.tauxDeChange as number(10, 2))                                                                        AS tauxDeChange,
       cast(v2.MONTANTREVIENT as number(20, 5)) AS MONTANTREVIENT  ,
       cast((V2.MONTANTTTCAR - v2.MONTANTREVIENT) as number(20, 5))                                  as margeBrute,
       v.IDRESERVATION,
       case when v.DATYPREVU is null then v.daty else V.DATYPREVU end                                as datyprevu,
       rf.REFERENCE                                                                                  as referencefacture,
       cast(v2.MONTANTREMISE as number(30, 5)) AS MONTANTREMISE,
       cast(nvl(v2.MONTANTTOTAL, 0) + nvl(v2.MONTANTREMISE, 0) as number(30, 5))                                             as montant,
       extract(month from v.DATY)                                                                    as mois,
       extract(year from v.DATY)                                                                     as annee,
       CAST(vp.poids as number(30, 5))                                                               as poids,
       CAST(vp.colis as number(30, 5))                                                               as colis,
       v.modepaiement,
       mp.VAL                                                                                        as modepaiementlib,
       nvl(v.fraislivraison, 0) * nvl(vp.poids, 0)                                                   as fraislivraison,
       v.modelivraison,
       CASE
           WHEN v.modelivraison = 1 THEN '<span style=color: green;>LIVRAISON</span>'
           WHEN v.modelivraison = 2 THEN '<span style=color: green;>RECUPERATION</span>'
           END                                                                                       AS modelivraisonlib,
       cast(vr.reste  as number(30, 5)) AS reste,
       pv.id                                                                                         as idprovince,
       pv.val                                                                                        as provincelib,
       --bl.id                                                                                         as idbl,
       v.IDORIGINE,
       CAST(COALESCE(v.FRAISLIVRAISON,0) AS  number(30, 5))                                                                             as frais,
       v.REFERENCEFACT,
       v.NUMEROFACTURE,
       v.LIEULIVRAISON,
       v.DATELIVRAISON,
       v.UPDATED_AT,
       case
           when v.ESTPREVU = 0 then 'Non'
           ELSE 'Oui'
           END estprevulib,
       ce.id AS idecriture,
       nvl(blc.daty,v.DATELIVRAISON) AS datedelivraison,
       c.ADRESSE
FROM VENTE v
         LEFT JOIN CLIENT c ON c.ID = v.IDCLIENT
         left join PROVINCE pv on pv.id = c.IDPROVINCE
         LEFT JOIN MAGASINPOINT m ON m.ID = v.IDMAGASIN
         JOIN VENTEMONTANT v2 ON v2.ID = v.ID
         LEFT JOIN LIAISONPAIEMENTTOTAL mv ON v.id = mv.id2
         LEFT JOIN AVOIRFCLIB_CPL_GRP ACG on ACG.IDVENTE = v.ID
         LEFT JOIN REFERENCEFACTURE rf ON rf.idfacture = v.Id
         left join vente_poids vp on vp.idvente = v.id
         left join MODEPAIEMENT mp on mp.id = v.modepaiement
         left join vente_reste vr on vr.idvente = v.id
         LEFT JOIN AS_BONDELIVRAISON_CLIENT blc ON blc.IDVENTE = v.id
         LEFT JOIN compta_ecriture ce ON ce.idobjet=v.id
;
-- [1185/1309] VENTE_CPL_USD
CREATE OR REPLACE FORCE VIEW "VENTE_CPL_USD" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE") AS
SELECT "ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE" FROM VENTE_CPL WHERE iddevise='USD'
;
-- [1186/1309] VENTE_CPL_VISEE
CREATE OR REPLACE FORCE VIEW "VENTE_CPL_VISEE" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","CLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","IDORIGINE","IDBL") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       m.VAL AS IDMAGASINLIB,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       CASE
           WHEN v.ETAT = 1 THEN 'CREE'
           WHEN v.ETAT = 11 THEN 'VISEE'
           WHEN v.ETAT = 0 THEN 'ANNULEE'
           END
             AS ETATLIB,
       v2.MONTANTTOTAL,
       v2.IDDEVISE,
       v.IDCLIENT,
       c.NOM AS CLIENTLIB,
       cast(V2.MONTANTTVA as number(30,2)) as MONTANTTVA,
       cast(V2.MONTANTTTC as number(30,2)) as montantttc,
       cast(V2.MONTANTTTCAR as number(30,2)) as MONTANTTTCAR,
       cast(nvl(mv.credit,0)-nvl(ACG.MONTANTPAYE, 0) AS NUMBER(30,2)) AS montantpaye,
       cast(V2.MONTANTTTC-nvl(mv.credit,0)-nvl(ACG.resteapayer_avr, 0) AS NUMBER(30,2)) AS montantreste,
       nvl(ACG.MONTANTTTC_avr, 0)  as avoir,
       v2.tauxDeChange AS tauxDeChange,v2.MONTANTREVIENT,cast((V2.MONTANTTTCAR-v2.MONTANTREVIENT) as number(20,2))  as margeBrute,
       v.IDRESERVATION,
       v.IDORIGINE,
       bl.id as idbl
FROM VENTE v
         LEFT JOIN CLIENT c ON c.ID = v.IDCLIENT
         LEFT JOIN MAGASIN m ON m.ID = v.IDMAGASIN
         JOIN VENTEMONTANT v2 ON v2.ID = v.ID
         LEFT JOIN mouvementcaisseGroupeFacture mv ON v.id=mv.IDORIGINE
         LEFT JOIN AVOIRFCLIB_CPL_GRP ACG on ACG.IDVENTE = v.ID
         left join AS_BONDELIVRAISON_CLIENT bl on bl.IDVENTE = v.id
where v.ETAT = 11
;
-- [1187/1309] VENTE_DETAILS_PAYE
CREATE OR REPLACE FORCE VIEW "VENTE_DETAILS_PAYE" ("ID","IDVENTE","IDPRODUIT","IDORIGINE","QTE","PU","REMISE","TVA","PUACHAT","PUVENTE","IDDEVISE","TAUXDECHANGE","DESIGNATION","COMPTE","PUREVIENT","IDBCFILLE","UNITE","POIDS","RISTOURNE","IDPREVISION","MOIS","ANNEE","POURCENTAGEPAYE","MONTANTFILLEPAYE","RESTEAPAYERFILLE","MONTANTFILLEPAYEAR","MONTANTFILLE") AS
SELECT
    VD.ID,
    VD.IDVENTE,
    VD.IDPRODUIT,
    VD.IDORIGINE,
    VD.QTE,
    VD.PU,
    VD.REMISE,
    VD.TVA,
    VD.PUACHAT,
    VD.PUVENTE,
    VD.IDDEVISE,
    VD.TAUXDECHANGE,
    VD.DESIGNATION,
    VD.COMPTE,
    VD.PUREVIENT,
    VD.IDBCFILLE,
    VD.UNITE,
    VD.POIDS,
    VD.RISTOURNE,
    VD.IDPREVISION,
    V.MOIS,
    V.ANNEE,
    V.MONTANTPAYE * 100 / NULLIF(V.MONTANTTTC,0) AS  pourcentagepaye,
    (V.MONTANTPAYE / NULLIF(V.MONTANTTTC, 0)) * (VD.QTE * VD.PU) AS MontantFillePaye,
    (VD.QTE * VD.PU) - ((V.MONTANTPAYE / NULLIF(V.MONTANTTTC, 0)) * (VD.QTE * VD.PU))   AS resteapayerfille,
    ((V.MONTANTPAYE / NULLIF(V.MONTANTTTC, 0)) * (VD.QTE * VD.PU)) * VD.TAUXDECHANGE AS MontantFillePayeAr,
    (VD.QTE * VD.PU) AS montantfille
FROM VENTE_DETAILS VD
    LEFT JOIN VENTE_CPL V ON V.ID = VD.IDVENTE
;
-- [1188/1309] SITUATION_BUDGET_RECETTES
CREATE OR REPLACE FORCE VIEW "SITUATION_BUDGET_RECETTES" ("ID","COMPTE","SERVICE","MOIS","ANNEE","MOISLIB","BUDGET","MONTANTFACTURE","PAIEMENT","RESTEAPAYER","ECARTFACTUREBUDGET","ECARTBUDGETPAIEMENT") AS
SELECT SQ.ID,
       SQ.COMPTE,
       SQ.SERVICE,
       SQ.MOIS,
       SQ.ANNEE,
       SQ.MOISLIB,
       SQ.BUDGET,
       SQ.MONTANTFACTURE,
       SQ.PAIEMENT,
       SQ.RESTEAPAYER,
       SQ.ECARTFACTUREBUDGET,
       SQ.ECARTBUDGETPAIEMENT
FROM (
  select
    '-' as id,
    bdsv.COMPTE,
    IDSERVICELIB as service,
    bdsv.mois,
    bdsv.annee,
    bdsv.moislib,
    bdsv.depenses as budget,
    ffc.montant as montantfacture,
    ffc.montantpaye as paiement,
    ffc.resteapayer,
    bdsv.depenses - ffc.montant as ecartfacturebudget,
    bdsv.depenses - ffc.montantpaye as ecartbudgetpaiement
from BUDGET_RECETTE_SUM_VIEW bdsv
    left join (
        select
            SUBSTR(ffp.compte, 1, LENGTH(bdsv_inner.COMPTE)) as compteregr_groupe,
            mois,
            annee,
            sum(montantfille * TAUXDECHANGE)     as montant,
            sum(MontantFillePaye * TAUXDECHANGE) as montantpaye,
            sum(resteapayerfille * TAUXDECHANGE) as resteapayer
        from VENTE_DETAILS_PAYE ffp
        cross join (select distinct COMPTE from BUDGET_RECETTE_SUM_VIEW) bdsv_inner
        where SUBSTR(ffp.compte, 1, LENGTH(bdsv_inner.COMPTE)) = bdsv_inner.COMPTE
        group by SUBSTR(ffp.compte, 1, LENGTH(bdsv_inner.COMPTE)), mois, annee
    ) ffc
    on ffc.compteregr_groupe like bdsv.COMPTE||'%'
        and ffc.mois = bdsv.mois
        and ffc.annee = bdsv.annee
) SQ
;
-- [1189/1309] SITUATION_BUDGET_RECETTES_VIDE
CREATE OR REPLACE FORCE VIEW "SITUATION_BUDGET_RECETTES_VIDE" ("ID","COMPTE","SERVICE","ANNEE","MOISDEBUT","MOISDEBUTLIB","MOISFIN","MOISFINLIB","BUDGET","MONTANTFACTURE","PAIEMENT","RESTEAPAYER","ECARTFACTUREBUDGET","ECARTBUDGETPAIEMENT") AS
SELECT SQ.ID,
       SQ.COMPTE,
       SQ.SERVICE,
       SQ.ANNEE,
       SQ.MOISDEBUT,
       SQ.MOISDEBUTLIB,
       SQ.MOISFIN,
       SQ.MOISFINLIB,
       SQ.BUDGET,
       SQ.MONTANTFACTURE,
       SQ.PAIEMENT,
       SQ.RESTEAPAYER,
       SQ.ECARTFACTUREBUDGET,
       SQ.ECARTBUDGETPAIEMENT
FROM (
select id, compte, service, annee, 6 as moisdebut,moisdebutlib, 8 as moisfin,moisfinlib, budget, montantfacture, paiement, resteapayer, ECARTFACTUREBUDGET, ECARTBUDGETPAIEMENT from
(select ID,
    COMPTE,
    SERVICE,
    ANNEE,
    sum(nvl(BUDGET, 0)) as budget,
    sum(nvl(MONTANTFACTURE, 0)) as montantfacture,
    sum(nvl(PAIEMENT, 0)) as paiement,
    SUM(nvl(RESTEAPAYER, 0)) as resteapayer,
    SUM(nvl(ECARTFACTUREBUDGET, 0)) as ECARTFACTUREBUDGET,
    SUM(nvl(ECARTBUDGETPAIEMENT, 0)) as ECARTBUDGETPAIEMENT,
    TO_CHAR(
        TO_DATE(TO_CHAR(6, 'FM00'), 'MM'),
        'FMMonth',
        'NLS_DATE_LANGUAGE=FRENCH'
    ) AS moisdebutlib,
    TO_CHAR(
        TO_DATE(TO_CHAR(8, 'FM00'), 'MM'),
        'FMMonth',
        'NLS_DATE_LANGUAGE=FRENCH'
    ) AS moisfinlib
    from SITUATION_BUDGET_RECETTES where mois between 6 and 8 group by ID, COMPTE, SERVICE, ANNEE)
) SQ
;
-- [1190/1309] VENTE_DIRECTE_CPL_PDF
CREATE OR REPLACE FORCE VIEW "VENTE_DIRECTE_CPL_PDF" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","DATYPREVU","REMARQUE","ETAT","ADECLARER","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","AVECCOMMISSION","IDMODEPAIEMENT","REFERENCEFACTURE","IDMODEPAIEMENTLIB","MONTANTDONNE","MONTANTRETOURNER","HEURESAISIE","IDECHEANCEPAIEMENT","ECHEANCEPAIEMENTLIB","IDORIGINE","DATYHEURE") AS
SELECT "ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","DATYPREVU","REMARQUE","ETAT","ADECLARER","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","AVECCOMMISSION","IDMODEPAIEMENT","REFERENCEFACTURE","IDMODEPAIEMENTLIB","MONTANTDONNE","MONTANTRETOURNER","HEURESAISIE","IDECHEANCEPAIEMENT","ECHEANCEPAIEMENTLIB","IDORIGINE","DATYHEURE"
FROM (
         SELECT v.ID,
                v.DESIGNATION,
                v.IDMAGASIN,
                m.VAL AS IDMAGASINLIB,
                v.DATY,
                v.DATYPREVU,
                v.REMARQUE,
                v.ETAT,
                ADECLARER,
                CASE
                    WHEN v.ETAT = 1  THEN 'CR&Eacute;&Eacute;E'
                    WHEN v.ETAT = 11 THEN 'VIS&Eacute;E'
                    WHEN v.ETAT = 0  THEN 'ANNUL&Eacute;E'
                    END AS ETATLIB,
                v2.MONTANTTOTAL,
                v2.IDDEVISE,
                v.IDCLIENT,
                c.NOM AS IDCLIENTLIB,
                cast(V2.MONTANTTVA as number(30,2)) as MONTANTTVA,
                cast(V2.MONTANTTTC as number(30,2)) as montantttc,
                cast(V2.MONTANTTTCAR as number(30,2)) as MONTANTTTCAR,
                cast(nvl(mv.credit,0)-nvl(ACG.MONTANTPAYE, 0) AS NUMBER(30,2)) AS montantpaye,
                cast(V2.MONTANTTTC-nvl(mv.credit,0)-nvl(ACG.resteapayer_avr, 0) AS NUMBER(30,2)) AS montantreste,
                nvl(ACG.MONTANTTTC_avr, 0) as avoir,
                v2.tauxDeChange AS tauxDeChange,
                v2.MONTANTREVIENT,
                cast((V2.MONTANTTTCAR-v2.MONTANTREVIENT) as number(20,2)) as margeBrute,
                v.IDRESERVATION,
                CASE
                    WHEN cm.id IS NOT NULL THEN 'Oui'
                    ELSE                        'Non'
                    END AS avecCommission,
                v.idmodepaiement,
                rf.REFERENCE as referencefacture,
                mp.val AS idmodepaiementlib,
                CASE
                    WHEN v.MONTANTDONNE IS NULL OR v.MONTANTDONNE = 0
                        THEN cast(nvl(mv.credit,0)-nvl(ACG.MONTANTPAYE, 0) AS NUMBER(30,2))
                    ELSE cast(v.MONTANTDONNE AS NUMBER(30,2))
                    END AS MONTANTDONNE,
                nvl(mv.MONTANTRETOURNER, 0) as montantretourner,
                v.heureSaisie,
                V.IDECHEANCEPAIEMENT,
                EP.DESCE AS echeancePaiementLib,
                v.IDORIGINE,
                TO_DATE(v.daty || ' ' || v.heureSaisie, 'DD/MM/YYYY HH24:MI:SS') AS DATYHEURE
         FROM VENTE v
                  LEFT JOIN CLIENT c ON c.ID = v.IDCLIENT
                  LEFT JOIN MAGASIN m ON m.ID = v.IDMAGASIN
                  JOIN VENTEMONTANT v2 ON v2.ID = v.ID
                  LEFT JOIN MVTCAISSEGROUPEFACTURE_PDF mv ON v.id in mv.IDORIGINE
                  LEFT JOIN AVOIRFCLIB_CPL_GRP ACG on ACG.IDVENTE = v.ID
             LEFT JOIN COMMISSION cm ON cm.IDFACTURE = v.id
             LEFT JOIN MODEPAIEMENT mp ON mp.id = v.idmodepaiement
             LEFT JOIN REFERENCEFACTURE rf ON rf.idfacture=v.Id
             LEFT JOIN ECHEANCEPAIEMENT EP on EP.ID = V.IDECHEANCEPAIEMENT
     )
ORDER BY DATYHEURE DESC NULLS LAST
;
-- [1191/1309] VENTE_EDITEES
CREATE OR REPLACE FORCE VIEW "VENTE_EDITEES" ("ID","DATY","IDRISTOURNE") AS
SELECT v.id,
       v.daty,
       r.idristourne
FROM VENTE_CPL v
JOIN (
    SELECT id as idristourne,
           REGEXP_SUBSTR(idorigine, '[^,]+', 1, LEVEL) AS idvente_explose
    FROM ristourne
    CONNECT BY REGEXP_SUBSTR(idorigine, '[^,]+', 1, LEVEL) IS NOT NULL
           AND PRIOR id = id
           AND PRIOR SYS_GUID() IS NOT NULL
) r
ON v.id = r.idvente_explose
;
-- [1192/1309] VENTE_LIB_BC
CREATE OR REPLACE FORCE VIEW "VENTE_LIB_BC" ("ID","DESIGNATION","IDORIGINE","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION") AS
SELECT v.ID,
          v.DESIGNATION,
          v.IDORIGINE,
          v.IDMAGASIN,
          m.VAL AS IDMAGASINLIB,
          v.DATY,
          v.REMARQUE,
          v.ETAT,
          CASE
             WHEN v.ETAT = 1 THEN 'CREE'
             WHEN v.ETAT = 11 THEN 'VISEE'
             WHEN v.ETAT = 0 THEN 'ANNULEE'
          END
             AS ETATLIB,
          v2.MONTANTTOTAL,
          v2.IDDEVISE,
          v.IDCLIENT,
          c.NOM AS IDCLIENTLIB,
          cast(V2.MONTANTTVA as number(30,2)) as MONTANTTVA,
          cast(V2.MONTANTTTC as number(30,2)) as montantttc,
          cast(V2.MONTANTTTCAR as number(30,2)) as MONTANTTTCAR,
          cast(nvl(mv.credit,0)-nvl(ACG.MONTANTPAYE, 0) AS NUMBER(30,2)) AS montantpaye,
          cast(V2.MONTANTTTC-nvl(mv.credit,0)-nvl(ACG.resteapayer_avr, 0) AS NUMBER(30,2)) AS montantreste,
          nvl(ACG.MONTANTTTC_avr, 0)  as avoir,
          v2.tauxDeChange AS tauxDeChange,v2.MONTANTREVIENT,cast((V2.MONTANTTTCAR-v2.MONTANTREVIENT) as number(20,2))  as margeBrute,
          v.IDRESERVATION
     FROM VENTE v
          LEFT JOIN CLIENT c ON c.ID = v.IDCLIENT
          LEFT JOIN MAGASIN m ON m.ID = v.IDMAGASIN
          JOIN VENTEMONTANT v2 ON v2.ID = v.ID
          LEFT JOIN mouvementcaisseGroupeFacture mv ON v.id=mv.IDORIGINE
		  LEFT JOIN AVOIRFCLIB_CPL_GRP ACG on ACG.IDVENTE = v.ID
;
-- [1193/1309] VENTE_RECAP_JOUR
CREATE OR REPLACE FORCE VIEW "VENTE_RECAP_JOUR" ("DATY","MONTANTTTC","MONTANTPAYE","MONTANTRESTE","NOMBRE","MONTANTRESTEACEJOUR") AS
WITH BORNES AS (
    SELECT
        DATE '2026-06-01' AS DATE_MIN,
        TRUNC(SYSDATE) AS DATE_MAX
    FROM DUAL
),
CALENDRIER AS (
    SELECT
        DATE_MIN + LEVEL - 1 AS DATY
    FROM BORNES
    CONNECT BY LEVEL <= DATE_MAX - DATE_MIN + 1
),
VENTE_JOUR AS (
    SELECT
        TRUNC(DATY) AS DATY,
        SUM(NVL(MONTANTTTC, 0)) AS MONTANTTTC,
        SUM(NVL(MONTANTPAYE, 0)) AS MONTANTPAYE,
        SUM(NVL(MONTANTRESTE, 0)) AS MONTANTRESTE,
        COUNT(*) AS NOMBRE
    FROM VENTE_CPL
    WHERE ETAT = 11
      AND DATY >= DATE '2026-06-01'
    GROUP BY TRUNC(DATY)
)
SELECT
    c.DATY,

    CAST(NVL(v.MONTANTTTC, 0) AS NUMBER(30,5)) AS MONTANTTTC,
    CAST(NVL(v.MONTANTPAYE, 0) AS NUMBER(30,5)) AS MONTANTPAYE,
    CAST(NVL(v.MONTANTRESTE, 0) AS NUMBER(30,5)) AS MONTANTRESTE,
    CAST(NVL(v.NOMBRE, 0) AS NUMBER(10,0)) AS NOMBRE,

    CAST(
        SUM(NVL(v.MONTANTRESTE, 0))
        OVER (
            ORDER BY c.DATY
            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
        )
        AS NUMBER(30,5)
    ) AS MONTANTRESTEACEJOUR

FROM CALENDRIER c
LEFT JOIN VENTE_JOUR v
    ON c.DATY = v.DATY
;
-- [1194/1309] VENTE_SANS_RISTOURNE
CREATE OR REPLACE FORCE VIEW "VENTE_SANS_RISTOURNE" ("ID","DESIGNATION","IDMAGASIN","IDMAGASINLIB","DATY","REMARQUE","ETAT","ETATLIB","MONTANTTOTAL","IDDEVISE","IDCLIENT","IDCLIENTLIB","MONTANTTVA","MONTANTTTC","MONTANTTTCAR","MONTANTPAYE","MONTANTRESTE","AVOIR","TAUXDECHANGE","MONTANTREVIENT","MARGEBRUTE","IDRESERVATION","DATYPREVU","MOIS","ANNEE") AS
SELECT v.ID,
       v.DESIGNATION,
       v.IDMAGASIN,
       v.IDMAGASINLIB,
       v.DATY,
       v.REMARQUE,
       v.ETAT,
       v.ETATLIB,
       v.MONTANTTOTAL,
       v.IDDEVISE,
       v.IDCLIENT,
       v.IDCLIENTLIB,
       v.MONTANTTVA,
       v.MONTANTTTC,
       v.MONTANTTTCAR,
       v.MONTANTPAYE,
       v.MONTANTRESTE,
       v.AVOIR,
       v.TAUXDECHANGE,
       v.MONTANTREVIENT,
       v.MARGEBRUTE,
       v.IDRESERVATION,
       v.DATYPREVU,
       v.mois,
       v.annee
FROM VENTE_CPL v
WHERE v.ETAT >= 11
  AND NOT EXISTS (
        SELECT 1
        FROM VENTE_EDITEES e
        WHERE e.id = v.id
  )
;
-- [1195/1309] VENTE_VALIDEE
CREATE OR REPLACE FORCE VIEW "VENTE_VALIDEE" ("ID","IDVENTE","IDPRODUIT","IDORIGINE","QTE","PU","IDRESERVATION") AS
SELECT
vd.ID,vd.IDVENTE,vd.IDPRODUIT,vd.IDORIGINE,vd.QTE,vd.PU,v.IDRESERVATION
FROM VENTE_DETAILS vd
LEFT JOIN VENTE v ON v.ID = vd.IDVENTE AND v.ETAT > 1
;
-- [1196/1309] ENCAISSEMENTVENTE
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENTVENTE" ("IDENCAISSEMENT","VENTECARBURANT") AS
SELECT 
pe.IDENCAISSEMENT ,
sum( nvl(v.QTE * v.PU ,0) ) AS ventecarburant 
FROM PRELEVEMENT_ENCAISSE pe 
LEFT JOIN vente_validee v ON v.IDORIGINE =  pe.IDPRELEVEMENT 
GROUP BY pe.IDENCAISSEMENT
;
-- [1197/1309] ENCAISSEMENT_LIB
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_LIB" ("ID","DESIGNATION","IDCAISSE","IDCAISSELIB","ETAT","ETATLIB","DATY","IDPOMPISTE","IDPOMPISTELIB","IDPOINT","IDPOINTLIB","IDCATEGORIECAISSE","VENTECARBURANT","VENTELUBRIFIANT","DEPENSE","TOTALRECETTE","TOTALENCAISSEMENT","TOTALVERSEMENT","ECART","TOTALESPECE","TOTALORANGEMONEY") AS
SELECT 
e.ID ,
e.DESIGNATION ,
e.IDCAISSE ,
c.VAL AS IDCAISSELIB,
e.ETAT ,
CASE 
	WHEN e.ETAT = 1 
	THEN 'CREE'
	WHEN e.ETAT = 11 
	THEN 'VALIDEE'
	WHEN e.ETAT = 0 
	THEN 'ANNULEE'
END AS ETATLIB, 
e.DATY ,
c.IDPOMPISTE ,
p.NOMUSER AS IDPOMPISTELIB,
c.IDPOINT ,
p2.VAL AS IDPOINTLIB ,
c.IDCATEGORIECAISSE ,
nvl(ev.ventecarburant,0) AS ventecarburant ,
nvl(vv.ventelubrifiant,0) AS ventelubrifiant ,
nvl(dv.depense,0) AS depense ,
nvl(ev.ventecarburant,0) + nvl(vv.ventelubrifiant,0) AS totalrecette ,
nvl(ev2.totalencaissement,0) AS totalencaissement ,
nvl(ev2.totalencaissement,0) - nvl(dv.depense,0) AS totalversement ,
nvl(ev2.totalencaissement,0) - ( nvl(ev.ventecarburant,0) + nvl(vv.ventelubrifiant,0) ) AS ecart ,
nvl(ee.montantcategorie , 0) AS totalEspece,
nvl(eo.montantcategorie , 0) AS totalOrangeMoney
FROM ENCAISSEMENT e 
LEFT JOIN CAISSE c ON c.ID = e.IDCAISSE 
LEFT JOIN POMPISTELIB p ON p.REFUSER = c.IDPOMPISTE 
LEFT JOIN encaissementvente ev ON ev.IDENCAISSEMENT = e.ID 
LEFT JOIN ventelubrifiant_validee vv ON vv.IDENCAISSEMENT = e.ID
LEFT JOIN depense_validee dv ON dv.IDORIGINE = e.ID
LEFT JOIN encaissement_validee ev2 ON ev2.IDENCAISSEMENT = e.ID
LEFT JOIN POINT p2 ON p2.ID = c.IDPOINT 
LEFT JOIN ENCAISSEMENT_ESPECES ee ON ee.IDENCAISSEMENT = e.ID
LEFT JOIN ENCAISSEMENT_ORANGEMONEY eo ON eo.IDENCAISSEMENT = e.ID
;
-- [1198/1309] ENCAISSEMENT_RESUME
CREATE OR REPLACE FORCE VIEW "ENCAISSEMENT_RESUME" ("ID","IDPOINT","IDPOINTLIB","DATY","VENTECARBURANT","VENTELUBRIFIANT","BON","CHEQUE","MVOLA","ESPECES","ORANGEMONEY","FANILO","TPE","VISA","DEPENSE","TOTALRECETTE","TOTALENCAISSEMENT","TOTALVERSEMENT") AS
SELECT 
el.ID ,
el.IDPOINT,
el.IDPOINTLIB ,
el.DATY,
el.ventecarburant,
el.ventelubrifiant,
nvl(eb.montantcategorie,0) AS bon ,
nvl(ec.montantcategorie,0) AS cheque ,
nvl(em.montantcategorie,0) AS mvola ,
nvl(ee.montantcategorie,0) AS especes ,
nvl(eo.montantcategorie,0) AS orangemoney ,
nvl(ef.montantcategorie,0) AS fanilo,
nvl(et.montantcategorie,0) AS tpe ,
nvl(ev.montantcategorie,0) AS visa ,
el.depense ,
el.totalrecette ,
el.totalencaissement ,
el.totalversement 
FROM ENCAISSEMENT_LIB el 
LEFT JOIN CATEGORIECAISSE c ON c.ID = el.IDCATEGORIECAISSE 
LEFT JOIN encaissement_bon eb ON eb.IDENCAISSEMENT = el.ID 
LEFT JOIN encaissement_cheque ec ON ec.IDENCAISSEMENT = el.ID
LEFT JOIN encaissement_mvola em ON em.IDENCAISSEMENT = el.ID
LEFT JOIN encaissement_especes ee ON ee.IDENCAISSEMENT = el.ID 
LEFT JOIN encaissement_orangemoney eo ON eo.IDENCAISSEMENT = el.ID
LEFT JOIN encaissement_fanilo ef ON ef.IDENCAISSEMENT = el.ID
LEFT JOIN encaissement_tpe et ON et.IDENCAISSEMENT = el.ID
LEFT JOIN encaissement_visa ev ON ev.IDENCAISSEMENT = el.ID
;
-- [1199/1309] VENTEDEP_GRAPH
CREATE OR REPLACE FORCE VIEW "VENTEDEP_GRAPH" ("IDPRELEVEMENT","IDENCAISSEMENT","IDPOMPISTE","NOMUSER","IDPOMPE","NOMMAGASIN","VENTECARBURANT","ENTREE","DATY") AS
(
SELECT
pe.IDPRELEVEMENT,
pe.IDENCAISSEMENT,
p.IDPOMPISTE,
p.NOMUSER,
p.IDPOMPE,
p.NOMMAGASIN,
el.VENTECARBURANT,
el.VENTECARBURANT - el.DEPENSE AS entree,
el.DATY
FROM PRELEVEMENT_ENCAISSE pe
JOIN PRELEVEMENTLIB p ON p.id=pe.IDPRELEVEMENT
JOIN ENCAISSEMENT_LIB el ON el.ID =pe.IDENCAISSEMENT
)
;
-- [1200/1309] VENTE_CARBU_CLIENT
CREATE OR REPLACE FORCE VIEW "VENTE_CARBU_CLIENT" ("IDPRELEVEMENT","IDENCAISSEMENT","IDPOMPISTE","NOMUSER","IDPOMPE","NOMMAGASIN","VENTECARBURANT","DATY") AS
(
SELECT 
pe.IDPRELEVEMENT,
pe.IDENCAISSEMENT,
p.IDPOMPISTE,
p.NOMUSER,
p.IDPOMPE,
p.NOMMAGASIN,
el.VENTECARBURANT,
el.DATY
FROM PRELEVEMENT_ENCAISSE pe
JOIN PRELEVEMENTLIB p ON p.id=pe.IDPRELEVEMENT
JOIN ENCAISSEMENT_LIB el ON el.ID =pe.IDENCAISSEMENT)
;
-- [1201/1309] VERSEMENTCHEQUEDETAILSCPL
CREATE OR REPLACE FORCE VIEW "VERSEMENTCHEQUEDETAILSCPL" ("ID","IDVERSEMENTCHEQUE","IDVERSEMENTCHEQUELIB","IDCHEQUE","IDCHEQUELIB","REMARQUE","IDCAISSECHEQUE","MONTANT","DATY","IDCAISSEVERSEMENT") AS
SELECT 
v.ID ,
v.IDVERSEMENTCHEQUE ,
v2.DESIGNATION AS IDVERSEMENTCHEQUELIB,
v.IDCHEQUE ,
c.REFERENCE AS IDCHEQUELIB,
v.REMARQUE ,
c.IDCAISSE AS idcaissecheque ,
c.MONTANT ,
v2.DATY ,
v2.IDCAISSE AS idcaisseversement
FROM VERSEMENTCHEQUEDETAILS v 
LEFT JOIN VERSEMENTCHEQUE v2 ON v2.ID = v.IDVERSEMENTCHEQUE 
LEFT JOIN CHEQUE c ON c.ID = v.IDCHEQUE
;
-- [1202/1309] VIEW_VIDE_SOMME
CREATE OR REPLACE FORCE VIEW "VIEW_VIDE_SOMME" ("ID","IDDEPARTEMENT","IDTYPESOMME") AS
SELECT
    CAST(NULL AS VARCHAR2(50)) AS id,
    CAST(NULL AS VARCHAR2(50)) AS idDepartement,
    CAST(NULL AS VARCHAR2(50)) AS idTypeSomme
FROM dual
WHERE 1 = 0
;
-- [1203/1309] VIREMENTINTRACAISSECPL
CREATE OR REPLACE FORCE VIEW "VIREMENTINTRACAISSECPL" ("ID","DESIGNATION","IDCAISSEDEPART","IDCAISSEDEPARTLIB","IDCAISSEARRIVE","IDCAISSEARRIVELIB","MONTANT","DATY","ETAT","ETATLIB") AS
SELECT
	    v.ID ,
	    v.DESIGNATION ,
	    v.IDCAISSEDEPART ,
	    c.VAL AS IDCAISSEDEPARTLIB ,
	    v.IDCAISSEARRIVE ,
	    c2.VAL AS IDCAISSEARRIVELIB,
	    CAST(v.MONTANT AS NUMBER(30,5)) AS MONTANT   ,
	    v.DATY ,
	    v.ETAT ,
	    CASE
	        WHEN v.ETAT = 0
	            THEN 'ANNUL&Eacute;'
	        WHEN v.ETAT = 1
	            THEN 'CR&Eacute;&Eacute;'
	        WHEN v.ETAT = 11
	            THEN  'VIS&Eacute;'
	        END AS ETATLIB
	FROM VIREMENTINTRACAISSE v
	         LEFT JOIN CAISSE c ON c.ID = v.IDCAISSEDEPART
	         LEFT JOIN CAISSE c2 ON c2.ID  = v.IDCAISSEARRIVE
;
-- [1204/1309] VIREMENTINTRACAISSECPL_ANNULE
CREATE OR REPLACE FORCE VIEW "VIREMENTINTRACAISSECPL_ANNULE" ("ID","DESIGNATION","IDCAISSEDEPART","IDCAISSEDEPARTLIB","IDCAISSEARRIVE","IDCAISSEARRIVELIB","MONTANT","DATY","ETAT","ETATLIB") AS
SELECT
		ID,DESIGNATION,IDCAISSEDEPART,IDCAISSEDEPARTLIB,IDCAISSEARRIVE,IDCAISSEARRIVELIB,MONTANT,DATY,ETAT,ETATLIB
	FROM 
		VIREMENTINTRACAISSECPL v 
	WHERE 
		v.etat = 0
;
-- [1205/1309] VIREMENTINTRACAISSECPL_CREE
CREATE OR REPLACE FORCE VIEW "VIREMENTINTRACAISSECPL_CREE" ("ID","DESIGNATION","IDCAISSEDEPART","IDCAISSEDEPARTLIB","IDCAISSEARRIVE","IDCAISSEARRIVELIB","MONTANT","DATY","ETAT","ETATLIB") AS
SELECT
		ID,DESIGNATION,IDCAISSEDEPART,IDCAISSEDEPARTLIB,IDCAISSEARRIVE,IDCAISSEARRIVELIB,MONTANT,DATY,ETAT,ETATLIB
	FROM 
		VIREMENTINTRACAISSECPL v 
	WHERE 
		v.etat = 1
;
-- [1206/1309] VIREMENTINTRACAISSECPL_VALIDER
CREATE OR REPLACE FORCE VIEW "VIREMENTINTRACAISSECPL_VALIDER" ("ID","DESIGNATION","IDCAISSEDEPART","IDCAISSEDEPARTLIB","IDCAISSEARRIVE","IDCAISSEARRIVELIB","MONTANT","DATY","ETAT","ETATLIB") AS
SELECT
		ID,DESIGNATION,IDCAISSEDEPART,IDCAISSEDEPARTLIB,IDCAISSEARRIVE,IDCAISSEARRIVELIB,MONTANT,DATY,ETAT,ETATLIB
	FROM 
		VIREMENTINTRACAISSECPL v 
	WHERE 
		v.etat = 11
;
-- [1207/1309] VUE_CARTONFILLE_IDMERE
CREATE OR REPLACE FORCE VIEW "VUE_CARTONFILLE_IDMERE" ("IDBCFILLE","ID_CARTON_MERE") AS
SELECT
  cf.IDBCFILLE,
  MIN(cf.IDMERE) AS ID_CARTON_MERE
FROM CARTONFILLE cf
JOIN CARTON c ON c.ID = cf.IDMERE AND c.ETAT >= 11
GROUP BY cf.IDBCFILLE
;
-- [1208/1309] VUE_CARTONFILLE_SUM
CREATE OR REPLACE FORCE VIEW "VUE_CARTONFILLE_SUM" ("IDBCFILLE","QUANTITE_CARTONFILLE") AS
SELECT
  cf.IDBCFILLE,
  SUM(cf.QUANTITE) AS QUANTITE_CARTONFILLE
FROM CARTONFILLE cf
JOIN CARTON c ON c.ID = cf.IDMERE AND c.ETAT >= 11
GROUP BY cf.IDBCFILLE
;
-- [1209/1309] VUE_CNAPS
CREATE OR REPLACE FORCE VIEW "VUE_CNAPS" ("IDPERSONNEL","MOIS","ANNEE","RETENUE") AS
SELECT pe.idpersonnel,
       pe.mois,
       pe.annee,
       pe.retenue
FROM paie_edition pe
WHERE pe.idelementpaie = 'PR000101'
;
-- [1210/1309] VUE_CONTRAT_LIB
CREATE OR REPLACE FORCE VIEW "VUE_CONTRAT_LIB" ("ID","MATRICULE","NOM","PRENOM","SEXE","DATEEMBAUCHE","PERIODE","DATE_FIN_CONTRAT","ETAT","TYPE_CONTRAT") AS
SELECT
    lpf.idpersonnel AS id,
    lpf.matricule,
    lpf.nom,
    lpf.prenom,
    lpf.sexe,
    pip.dateembauche,
    pip.indesirable AS periode,
    CASE
        WHEN pip.indesirable > 0 THEN pip.dateembauche + INTERVAL '1' MONTH * pip.indesirable
        ELSE NULL
        END AS date_fin_contrat,
    lpf.etat,
    tc.val AS type_contrat
FROM
    log_personnel_fin lpf
        JOIN paie_info_personnel pip ON pip.id = lpf.idpersonnel
        JOIN type_contrat tc ON tc.id = pip.typecontrat
;
-- [1211/1309] VUE_ID_MATRICULE
CREATE OR REPLACE FORCE VIEW "VUE_ID_MATRICULE" ("ID","PRENOM","NOM","MATRICULE","DIRECTION","IDDIRECTION","ETAT") AS
SELECT lp.id,
       lp.prenom,
       lp.nom,
       pip.matricule,
       ld.VAL AS direction,
       ld.ID AS iddirection,
       pip.ETAT
FROM paie_info_personnel pip
         JOIN log_personnel lp ON pip.id = lp.id
         LEFT JOIN LOG_DIRECTION ld ON ld.ID = lp.direction
;
-- [1212/1309] CATEG_QUALILIBCOMPLET
CREATE OR REPLACE FORCE VIEW "CATEG_QUALILIBCOMPLET" ("ID","IDCATEGORIE","IDQUALIFICATION","REMARQUE","ETAT","MONTANT","ETATLIBELLE","ETATVAL","MATRICULE","DATE_DEBUT","DATE_FIN","NOMCPL","PRENOM") AS
SELECT cq.id,
       cp.val AS idcategorie,
       qp.val AS idqualification,
       cq.remarque,
       cq.etat,
       cq.montant,
       CASE
           WHEN cq.etat = 1 THEN 'actif'
           ELSE 'inactif'
           END AS etatlibelle,
       ecq.desce AS etatval,
       vim.matricule,
       cq.date_debut,
       cq.date_fin,
       vim.NOM || vim.PRENOM AS nomCpl,
       vim.PRENOM
FROM categorie_qualification cq
         JOIN categorie_paie cp ON cp.id = cq.idcategorie
         JOIN qualification_paie qp ON qp.id = cq.idqualification
         JOIN etat_categ_qualif2 ecq ON ecq.id = cq.etat
         LEFT JOIN vue_id_matricule vim ON vim.id = cq.remarque
;
-- [1213/1309] VUE_SUIVI_CARTON
CREATE OR REPLACE FORCE VIEW "VUE_SUIVI_CARTON" ("ID","IDBC_MERE","PRODUITLIB","QUANTITEBCF","QUANTITECARTONFILLE","RESTECARTONFILLE") AS
SELECT 
    bcf.ID AS id,
    bcf.IDBC AS idbc_mere,
    ai.LIBELLE AS produitlib,
    NVL(bcf.QUANTITE, 0) AS quantitebcf,
    NVL(SUM(cf.QUANTITE), 0) AS quantitecartonfille,
    NVL(bcf.QUANTITE, 0) - NVL(SUM(cf.QUANTITE), 0) AS restecartonfille
FROM BONDECOMMANDE_CLIENT_FILLE bcf
LEFT JOIN CARTONFILLE cf ON cf.IDBCFILLE = bcf.ID
LEFT JOIN CARTON c ON c.ID = cf.IDMERE AND c.ETAT > 11
LEFT JOIN AS_INGREDIENTS ai ON ai.ID = bcf.PRODUIT
GROUP BY 
    bcf.ID,
    bcf.IDBC,
    ai.LIBELLE,
    bcf.QUANTITE
;
-- [1214/1309] VUE_SUIVI_CARTON_LIVRAISON
CREATE OR REPLACE FORCE VIEW "VUE_SUIVI_CARTON_LIVRAISON" ("ID","IDBC_MERE","IDCARTONMERE","PRODUIT","PRODUITLIB","UNITE","QUANTITEBCF","QUANTITECARTONFILLE","RESTECARTONFILLE") AS
SELECT 
    bcf.ID AS id,
    bcf.IDBC AS idbc_mere,
    vci.ID_CARTON_MERE AS idCartonMere,
    ai.ID AS produit,
    ai.LIBELLE AS produitlib,
    ai.UNITE AS unite,
    NVL(bcf.QUANTITE, 0) AS quantitebcf,
    NVL(vc.QUANTITE_CARTONFILLE, 0) AS quantitecartonfille,
    NVL(bcf.QUANTITE, 0) - NVL(vc.QUANTITE_CARTONFILLE, 0) AS restecartonfille
FROM BONDECOMMANDE_CLIENT_FILLE bcf
LEFT JOIN AS_INGREDIENTS ai ON ai.ID = bcf.PRODUIT
LEFT JOIN VUE_CARTONFILLE_SUM vc ON vc.IDBCFILLE = bcf.ID
LEFT JOIN VUE_CARTONFILLE_IDMERE vci ON vci.IDBCFILLE = bcf.ID
;
-- [1215/1309] VW_HS_CUMUL_WEEK
CREATE OR REPLACE FORCE VIEW "VW_HS_CUMUL_WEEK" ("IDPERSONNEL","SEMAINE","TOTAL_HS") AS
SELECT
    pip.id as IDPERSONNEL,
    TO_CHAR(f.DATY, 'IYYY-IW') AS SEMAINE,
    NVL(SUM(hp.HS), 0) AS TOTAL_HS
FROM HEURESUPFABRICATION hp
         LEFT JOIN FABRICATION f ON f.ID = hp.IDFABRICATION
         LEFT JOIN RESSOURCEPARFABRICATION ress ON ress.id = hp.IDRESSPARFAB
         LEFT JOIN PAIE_INFO_PERSONNEL pip ON pip.id = ress.IDRESSOURCE

GROUP BY
    pip.id,
    TO_CHAR(f.DATY, 'IYYY-IW')
;
-- [1216/1309] VW_MOUVEMENTCAISSE_TOTAL_DEBIT
CREATE OR REPLACE FORCE VIEW "VW_MOUVEMENTCAISSE_TOTAL_DEBIT" ("IDBC","TOTAL_DEBIT") AS
SELECT
    idbc,
    SUM(debit) AS total_debit
FROM mouvementcaisse
GROUP BY idbc
;
-- [1217/1309] AS_BONDECOMMANDE_MERECPL
CREATE OR REPLACE FORCE VIEW "AS_BONDECOMMANDE_MERECPL" ("ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","FOURNISSEUR","REFERENCE","DATELIMITE","IDDMDACHAT","MODEPAIEMENTLIB","FOURNISSEURLIB","MONTANTTVA","MONTANTHT","MONTANTTTC","MONTANTTTCARIARY","IDDEVISELIB","IDDEVISE","ETATLIB","IDSERVICELIB","REFPROFORMA","NB","SOMMEACOMPTE","REMISE") AS
SELECT
    ab.ID,
    ab.DATY,
    ab.ETAT,
    ab.REMARQUE,
    ab.DESIGNATION,
    ab.MODEPAIEMENT,
    ab.FOURNISSEUR,
    ab.REFERENCE,
    ab.dateLimite,
    ab.iddmdachat AS IDDMDACHAT,
    mp.VAL AS MODEPAIEMENTLIB,
    F.NOM AS FOURNISSEURLIB,
    CAST(abf.montantTVA*(1-(NVL(ab.REMISE,0)/100)) as number(30,2)) as montantTVA,
    cast(abf.montantHT*(1-(NVL(ab.REMISE,0)/100)) as number(30,2)) as montantHT,
    CAST(nvl((abf.montantHT + abf.montantTVA - abf.remiseMontant)*(1-(NVL(ab.REMISE,0)/100)),0) AS NUMBER(30,2)) AS montantTTC ,
    CAST(nvl((abf.montantHT + abf.montantTVA- abf.remiseMontant) * abf.TAUXDECHANGE*(1-(NVL(ab.REMISE,0)/100)),0) AS NUMBER(30,2)) AS montantTTCAriary,
    d.val AS idDeviselib,
    d.id AS IDDEVISE,
    CASE
        WHEN ab.ETAT = 1 THEN 'CR&Eacute;&Eacute;E'
        WHEN ab.ETAT = 11 THEN 'VIS&Eacute;E'
        WHEN ab.ETAT = 0 THEN 'ANNUL&Eacute;E'
        END AS ETATLIB,
    s.VAL AS idServiceLib,
    ab.refproforma,
    1 AS nb,
    vw.TOTAL_DEBIT as sommeAcompte,
    ab.REMISE
FROM AS_BONDECOMMANDE AB
    LEFT JOIN MODEPAIEMENT mp ON AB.MODEPAIEMENT = mp.id
    LEFT JOIN FOURNISSEUR F ON AB.FOURNISSEUR = F.id
    LEFT JOIN AS_BONDECOMMANDEFILLE_CPL abf ON abf.IDBC = ab.ID
    LEFT JOIN DEVISE d ON d.id = ab.IDDEVISE
    LEFT JOIN DEPARTEMENT s ON ab.SERVICE = s.ID
    LEFT JOIN vw_mouvementcaisse_total_debit vw on VW.IDBC = ab.id
;
-- [1218/1309] AS_BONDECOMMANDE_MERETRAITE
CREATE OR REPLACE FORCE VIEW "AS_BONDECOMMANDE_MERETRAITE" ("ID","DATY","ETAT","REMARQUE","DESIGNATION","MODEPAIEMENT","FOURNISSEUR","REFERENCE","DATELIMITE","IDDMDACHAT","MODEPAIEMENTLIB","FOURNISSEURLIB","MONTANTTVA","MONTANTHT","MONTANTTTC","MONTANTTTCARIARY","IDDEVISELIB","IDDEVISE","ETATLIB","IDSERVICELIB","REFPROFORMA","SOMMEACOMPTE","REMISE","IDTRAITE","TRAITE") AS
SELECT
    abm."ID",abm."DATY",abm."ETAT",abm."REMARQUE",abm."DESIGNATION",abm."MODEPAIEMENT",abm."FOURNISSEUR",abm."REFERENCE",abm."DATELIMITE",abm."IDDMDACHAT",abm."MODEPAIEMENTLIB",abm."FOURNISSEURLIB",abm."MONTANTTVA",abm."MONTANTHT",abm."MONTANTTTC",abm."MONTANTTTCARIARY",abm."IDDEVISELIB",abm."IDDEVISE",abm."ETATLIB",abm."IDSERVICELIB",abm."REFPROFORMA",
    abm.SOMMEACOMPTE,abm.remise,
    CASE
      WHEN abrcp.totalRecept = 0 THEN '0'
      WHEN abrcp.totalCommande > abrcp.totalRecept THEN '1'
      WHEN abrcp.totalCommande = abrcp.totalRecept THEN '2'
      WHEN abrcp.totalCommande < abrcp.totalRecept THEN '3'
      END AS IDTRAITE,
    CASE
        WHEN abrcp.totalRecept = 0 THEN 'Non Trait&eacute;'
        WHEN abrcp.totalCommande > abrcp.totalRecept  THEN 'Trait&eacute; Partiellement'
        WHEN abrcp.totalCommande = abrcp.totalRecept THEN 'Trait&eacute;'
        WHEN abrcp.totalCommande < abrcp.totalRecept THEN 'Trait&eacute; avec surplus'
        END AS TRAITE
  FROM As_BonDeCommande_MERECPL abm
  left join AS_BONDECOMMANDE_CPL_RECEPTGRP abrcp on abrcp.idbc = abm.id
;
-- [1219/1309] V_ACCIDENT_LIB
CREATE OR REPLACE FORCE VIEW "V_ACCIDENT_LIB" ("ID","DATY","DATE_DECLARATION","ID_PERSONNEL","ID_LIEU","ID_TYPE_ACCIDENT","ID_GRAVITE","ID_MACHINE","CAUSE","HEUREACCIDENT","HORAIREDEBUT","HORAIREFIN","ACTIVITE","LESIONS","CENTRESOIN","DETAILSTEMOIN1","DETAILSTEMOIN2","ETAT","ID_MACHINE_LIB","ID_LIEU_LIB","ID_TYPE_ACCIDENT_LIB","ID_GRAVITE_LIB","ID_PERSONNEL_LIB","MATRICULE","ETAT_LIB") AS
SELECT acc."ID",acc."DATY",acc."DATE_DECLARATION",acc."ID_PERSONNEL",acc."ID_LIEU",acc."ID_TYPE_ACCIDENT",acc."ID_GRAVITE",acc."ID_MACHINE",acc."CAUSE",acc."HEUREACCIDENT",acc."HORAIREDEBUT",acc."HORAIREFIN",acc."ACTIVITE",acc."LESIONS",acc."CENTRESOIN",acc."DETAILSTEMOIN1",acc."DETAILSTEMOIN2",acc."ETAT",
       m.VAL AS id_machine_lib,
       lat.val AS id_lieu_lib,
       ta.VAL AS id_type_accident_lib,
       ga.val AS id_gravite_lib,
       lp.NOM || ' ' || lp.prenom AS id_personnel_lib,
       pip.MATRICULE AS matricule,
       CASE
           WHEN acc.etat = 1 THEN 'Cree'
           WHEN acc.etat = 11 THEN 'Declare'
           ELSE 'inconnu'
       END AS etat_lib
FROM Accident acc
         LEFT JOIN MACHINE m ON m.ID = acc.Id_machine
         LEFT JOIN lieu_accident_travail lat ON lat.ID = acc.id_lieu
         LEFT JOIN type_accident ta ON ta.id = acc.id_type_accident
         LEFT JOIN gravite_accident ga ON ga.id = acc.id_gravite
         LEFT JOIN LOG_PERSONNEL lp ON lp.ID = acc.ID_PERSONNEL
         LEFT JOIN PAIE_INFO_PERSONNEL pip ON pip.id = acc.ID_PERSONNEL
;
-- [1220/1309] V_ACCIDENT_PDF
CREATE OR REPLACE FORCE VIEW "V_ACCIDENT_PDF" ("ID","DATY","DATE_DECLARATION","ID_PERSONNEL","ID_LIEU","ID_TYPE_ACCIDENT","ID_GRAVITE","ID_MACHINE","CAUSE","ETAT","ID_MACHINE_LIB","ID_LIEU_LIB","ID_TYPE_ACCIDENT_LIB","ID_GRAVITE_LIB","ID_PERSONNEL_LIB","MATRICULE","ETAT_LIB","DETAILSTEMOIN1","DETAILSTEMOIN2","HEUREACCIDENT","HORAIREDEBUT","HORAIREFIN","ACTIVITE","LESIONS","CENTRESOIN","NUMERO_CIN","DATE_NAISSANCE","FONCTION","ADRESSE","DATEEMBAUCHE","NUMERO_CNAPS") AS
SELECT acc."ID",acc."DATY",acc."DATE_DECLARATION",acc."ID_PERSONNEL",acc."ID_LIEU",acc."ID_TYPE_ACCIDENT",acc."ID_GRAVITE",acc."ID_MACHINE",acc."CAUSE",acc."ETAT",
       m.VAL AS id_machine_lib,
       lat.val AS id_lieu_lib,
       ta.VAL AS id_type_accident_lib,
       ga.val AS id_gravite_lib,
       lp.NOM || ' ' || lp.prenom AS id_personnel_lib,
       pip.MATRICULE AS matricule,
       CASE
           WHEN acc.etat = 1 THEN 'Cree'
           WHEN acc.etat = 11 THEN 'Declare'
           ELSE 'inconnu'
           END AS etat_lib,
       acc.DETAILSTEMOIN1,
       acc.DETAILSTEMOIN2,
       acc.HEUREACCIDENT,
       acc.HORAIREDEBUT,
       acc.HORAIREFIN,
       acc.ACTIVITE,
       acc.LESIONS,
       acc.CENTRESOIN,
       lp.NUMERO_CIN,
       lp.DATE_NAISSANCE,
       pf.val as fonction,
       lp.ADRESSE,
       pip.DATEEMBAUCHE,
       pip.NUMERO_CNAPS
FROM Accident acc
         LEFT JOIN MACHINE m ON m.ID = acc.Id_machine
         LEFT JOIN lieu_accident_travail lat ON lat.ID = acc.id_lieu
         LEFT JOIN type_accident ta ON ta.id = acc.id_type_accident
         LEFT JOIN gravite_accident ga ON ga.id = acc.id_gravite
         LEFT JOIN LOG_PERSONNEL lp ON lp.ID = acc.ID_PERSONNEL
         LEFT JOIN PAIE_INFO_PERSONNEL pip ON pip.id = acc.ID_PERSONNEL
         LEFT JOIN PAIE_FONCTION pf ON pf.id = pip.IDFONCTION
;
-- [1221/1309] V_ARRETTRAVAIL_LIB
CREATE OR REPLACE FORCE VIEW "V_ARRETTRAVAIL_LIB" ("ID","DATY","DATE_FIN_ARRET","DATE_DEBUT_ARRET","ID_ACCIDENT","NOMBRE_JOUR","NOMPERSONNEL","MATRICULE","DATEACCIDENT","ID_PERSONNEL") AS
SELECT
    at.id,
    at.DATY,
    at.DATE_FIN_ARRET,
    at.DATE_DEBUT_ARRET,
    at.ID_ACCIDENT,
    at.NOMBRE_JOUR,
    acc.id_personnel_lib as nomPersonnel,
    acc.MATRICULE,
    acc.DATY as dateAccident,
    acc.ID_PERSONNEL
FROM ARRET_TRAVAIL at
        left join V_ACCIDENT_LIB acc ON acc.id = at.ID_ACCIDENT
;
-- [1222/1309] V_BALANCE_DETAILS
CREATE OR REPLACE FORCE VIEW "V_BALANCE_DETAILS" ("ANNEE","MOIS","COMPTE","LIBELLECOMPTE","DEBIT","CREDIT","COMPTE3","COMPTE2","CUMULDEBIT","CUMULCREDIT") AS
WITH mois_annees AS (
    SELECT
        ADD_MONTHS(TRUNC(SYSDATE, 'MM'), LEVEL - 25) AS mois
    FROM DUAL
        CONNECT BY LEVEL <= 49
        ),
        base_comptes_periode AS (
        SELECT
        CAST(c.compte AS VARCHAR2(100)) AS compte,
        c.libelle AS libelleCompte,
        m.mois,
        EXTRACT(YEAR FROM m.mois) AS annee,
        EXTRACT(MONTH FROM m.mois) AS mois_num
        FROM
        compta_compte c
        CROSS JOIN mois_annees m
        ),
        ecritures_mensuelles AS (
    -- Excludes journal = 'COMP000015'
        SELECT
        CAST(cse.compte AS VARCHAR2(100)) AS compte,
        TRUNC(cse.daty, 'MM') AS mois,
        SUM(cse.debit) AS soldeDebit,
        SUM(cse.credit) AS soldeCredit
        FROM
        compta_sous_ecriture cse
        JOIN compta_ecriture ce ON ce.id = cse.idmere
        WHERE
        cse.daty IS NOT NULL
        AND cse.etat >= 11
        AND cse.journal != 'COMP000015'
        GROUP BY
        cse.compte, TRUNC(cse.daty, 'MM')
        ),
        ecritures_mensuelles_cumuls AS (
    -- Includes all journals, including 'COMP000015'
        SELECT
        CAST(cse.compte AS VARCHAR2(100)) AS compte,
        TRUNC(cse.daty, 'MM') AS mois,
        SUM(cse.debit) AS cumulDebit,
        SUM(cse.credit) AS cumulCredit
        FROM
        compta_sous_ecriture cse
        JOIN compta_ecriture ce ON ce.id = cse.idmere
        WHERE
        cse.daty IS NOT NULL
        AND cse.etat >= 11
        GROUP BY
        cse.compte, TRUNC(cse.daty, 'MM')
        ),
        fusion_comptes_mois AS (
        SELECT
        b.annee,
        b.mois_num AS mois,
        b.compte,
        b.libelleCompte,
        b.mois AS date_mois,
        NVL(em.soldeDebit, 0) AS soldeDebit,
        NVL(em.soldeCredit, 0) AS soldeCredit,
        NVL(ec.cumulDebit, 0) AS cumulDebit,
        NVL(ec.cumulCredit, 0) AS cumulCredit
        FROM
        base_comptes_periode b
        LEFT JOIN ecritures_mensuelles em ON b.compte = em.compte AND b.mois = em.mois
        LEFT JOIN ecritures_mensuelles_cumuls ec ON b.compte = ec.compte AND b.mois = ec.mois
        )
SELECT
    annee,
    mois,
    compte,
    libelleCompte,
    ROUND(soldeDebit, 2) AS debit,
    ROUND(soldeCredit, 2) AS credit,
    TO_NUMBER(SUBSTR(compte, 1, 3)) AS compte3,
    TO_NUMBER(SUBSTR(compte, 1, 2)) AS compte2,
    ROUND(
            SUM(cumulDebit) OVER (
            PARTITION BY compte ORDER BY date_mois
            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 2
    ) AS cumulDebit,
    ROUND(
            SUM(cumulCredit) OVER (
            PARTITION BY compte ORDER BY date_mois
            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 2
    ) AS cumulCredit
FROM
    fusion_comptes_mois
ORDER BY
    compte, annee, mois
;
-- [1223/1309] V_BALANCE_DETAILS_ANALYTIQUE
CREATE OR REPLACE FORCE VIEW "V_BALANCE_DETAILS_ANALYTIQUE" ("ANNEE","MOIS","COMPTE","LIBELLECOMPTE","DEBIT","CREDIT","COMPTE3","COMPTE2","CUMULDEBIT","CUMULCREDIT") AS
WITH mois_annees AS (
    SELECT
        ADD_MONTHS(TRUNC(SYSDATE, 'MM'), LEVEL - 25) AS mois
    FROM DUAL
        CONNECT BY LEVEL <= 49
        ),
        base_comptes_periode AS (
        SELECT
        CAST(c.compte AS VARCHAR2(100)) AS compte,
        c.libelle AS libelleCompte,
        m.mois,
        EXTRACT(YEAR FROM m.mois) AS annee,
        EXTRACT(MONTH FROM m.mois) AS mois_num
        FROM
        compta_compte c
        CROSS JOIN mois_annees m
        WHERE
        c.typecompte = '3'
        ),
        ecritures_mensuelles AS (
    -- For monthly values: EXCLUDE journal = 'COMP000015'
        SELECT
        CAST(cse.compte AS VARCHAR2(100)) AS compte,
        TRUNC(cse.daty, 'MM') AS mois,
        SUM(cse.debit) AS soldeDebit,
        SUM(cse.credit) AS soldeCredit
        FROM
        compta_sous_ecriture cse
        JOIN compta_ecriture ce ON ce.id = cse.idmere
        WHERE
        cse.daty IS NOT NULL
        AND cse.etat >= 11
        AND ce.journal != 'COMP000015'
        GROUP BY
        cse.compte, TRUNC(cse.daty, 'MM')
        ),
        ecritures_mensuelles_cumuls AS (
    -- For cumulative values: INCLUDE everything
        SELECT
        CAST(cse.compte AS VARCHAR2(100)) AS compte,
        TRUNC(cse.daty, 'MM') AS mois,
        SUM(cse.debit) AS cumulDebit,
        SUM(cse.credit) AS cumulCredit
        FROM
        compta_sous_ecriture cse
        JOIN compta_ecriture ce ON ce.id = cse.idmere
        WHERE
        cse.daty IS NOT NULL
        AND cse.etat >= 11
        GROUP BY
        cse.compte, TRUNC(cse.daty, 'MM')
        ),
        fusion_comptes_mois AS (
        SELECT
        b.annee,
        b.mois_num AS mois,
        b.compte,
        b.libelleCompte,
        b.mois AS date_mois,
        NVL(em.soldeDebit, 0) AS soldeDebit,
        NVL(em.soldeCredit, 0) AS soldeCredit,
        NVL(ec.cumulDebit, 0) AS cumulDebit,
        NVL(ec.cumulCredit, 0) AS cumulCredit
        FROM
        base_comptes_periode b
        LEFT JOIN ecritures_mensuelles em ON b.compte = em.compte AND b.mois = em.mois
        LEFT JOIN ecritures_mensuelles_cumuls ec ON b.compte = ec.compte AND b.mois = ec.mois
        )
SELECT
    annee,
    mois,
    compte,
    libelleCompte,
    ROUND(soldeDebit, 2) AS debit,
    ROUND(soldeCredit, 2) AS credit,
    TO_NUMBER(SUBSTR(compte, 1, 3)) AS compte3,
    TO_NUMBER(SUBSTR(compte, 1, 2)) AS compte2,
    ROUND(
            SUM(cumulDebit) OVER (
            PARTITION BY compte ORDER BY date_mois
            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 2
    ) AS cumulDebit,
    ROUND(
            SUM(cumulCredit) OVER (
            PARTITION BY compte ORDER BY date_mois
            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 2
    ) AS cumulCredit
FROM
    fusion_comptes_mois
ORDER BY
    compte, annee, mois
;
-- [1224/1309] V_BALANCE_DETAILS_AUX
CREATE OR REPLACE FORCE VIEW "V_BALANCE_DETAILS_AUX" ("ANNEE","MOIS","COMPTE","LIBELLECOMPTE","DEBIT","CREDIT","COMPTE3","COMPTE2","CUMULDEBIT","CUMULCREDIT") AS
WITH mois_annees AS (
    SELECT
        ADD_MONTHS(TRUNC(SYSDATE, 'MM'), LEVEL - 25) AS mois
    FROM DUAL
        CONNECT BY LEVEL <= 49
        ),
        base_comptes_periode AS (
        SELECT
        CAST(c.compte AS VARCHAR2(100)) AS compte,
        c.libelle AS libelleCompte,
        m.mois,
        EXTRACT(YEAR FROM m.mois) AS annee,
        EXTRACT(MONTH FROM m.mois) AS mois_num
        FROM
        compte_aux c
        CROSS JOIN mois_annees m
        ),
        ecritures_mensuelles AS (
    -- Excludes journal = 'COMP000015'
        SELECT
        CAST(cse.COMPTE_AUX AS VARCHAR2(100)) AS compte,
        TRUNC(cse.daty, 'MM') AS mois,
        SUM(cse.debit) AS soldeDebit,
        SUM(cse.credit) AS soldeCredit
        FROM
        compta_sous_ecriture cse
        JOIN compta_ecriture ce ON ce.id = cse.idmere
        WHERE
        cse.daty IS NOT NULL
        AND cse.etat >= 11
        AND cse.journal != 'COMP000015'
        GROUP BY
        cse.COMPTE_AUX, TRUNC(cse.daty, 'MM')
        ),
        ecritures_mensuelles_cumuls AS (
    -- Includes all journals, including 'COMP000015'
        SELECT
        CAST(cse.COMPTE_AUX AS VARCHAR2(100)) AS compte,
        TRUNC(cse.daty, 'MM') AS mois,
        SUM(cse.debit) AS cumulDebit,
        SUM(cse.credit) AS cumulCredit
        FROM
        compta_sous_ecriture cse
        JOIN compta_ecriture ce ON ce.id = cse.idmere
        WHERE
        cse.daty IS NOT NULL
        AND cse.etat >= 11
        GROUP BY
        cse.COMPTE_AUX, TRUNC(cse.daty, 'MM')
        ),
        fusion_comptes_mois AS (
        SELECT
        b.annee,
        b.mois_num AS mois,
        b.compte,
        b.libelleCompte,
        b.mois AS date_mois,
        NVL(em.soldeDebit, 0) AS soldeDebit,
        NVL(em.soldeCredit, 0) AS soldeCredit,
        NVL(ec.cumulDebit, 0) AS cumulDebit,
        NVL(ec.cumulCredit, 0) AS cumulCredit
        FROM
        base_comptes_periode b
        LEFT JOIN ecritures_mensuelles em ON b.compte = em.compte AND b.mois = em.mois
        LEFT JOIN ecritures_mensuelles_cumuls ec ON b.compte = ec.compte AND b.mois = ec.mois
        )
SELECT
    annee,
    mois,
    compte,
    libelleCompte,
    ROUND(soldeDebit, 2) AS debit,
    ROUND(soldeCredit, 2) AS credit,
    TO_NUMBER(SUBSTR(compte, 1, 3)) AS compte3,
    TO_NUMBER(SUBSTR(compte, 1, 2)) AS compte2,
    ROUND(
            SUM(cumulDebit) OVER (
            PARTITION BY compte ORDER BY date_mois
            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 2
    ) AS cumulDebit,
    ROUND(
            SUM(cumulCredit) OVER (
            PARTITION BY compte ORDER BY date_mois
            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 2
    ) AS cumulCredit
FROM
    fusion_comptes_mois
ORDER BY
    compte, annee, mois
;
-- [1225/1309] V_BILAN_SECTION_COMPTE_COMPLET
CREATE OR REPLACE FORCE VIEW "V_BILAN_SECTION_COMPTE_COMPLET" ("ID","IDBILANSECTION","EXERCICE","COMPTE","DEBIT","CREDIT") AS
SELECT 
bsc.ID ,
bsc.IDBILANSECTION ,
ce.ID AS exercice ,
bsc.COMPTE ,
sum(nvl(cse.DEBIT,0)) AS debit,
sum(nvl(cse.CREDIT,0)) AS credit
FROM BILAN_SECTION_COMPTE bsc
JOIN COMPTA_EXERCICE ce ON 1=1
JOIN BILANSECTION b ON b.ID = bsc.IDBILANSECTION 
LEFT JOIN COMPTA_SOUS_ECRITURE cse ON cse.COMPTE = bsc.COMPTE AND EXTRACT(YEAR FROM cse.daty) = ce.id 
GROUP BY bsc.ID,bsc.IDBILANSECTION,ce.ID,bsc.COMPTE
;
-- [1226/1309] V_CATEGORIEINGREDIENT
CREATE OR REPLACE FORCE VIEW "V_CATEGORIEINGREDIENT" ("ID","VAL","DESCE") AS
select c.id, val, desce from CATEGORIEINGREDIENT c where ACTIF > 0
;
-- [1227/1309] V_CLASSEETFICHE
CREATE OR REPLACE FORCE VIEW "V_CLASSEETFICHE" ("ID","CLASSE","FICHE","LIBELLE") AS
select
    id, classe, fiche,
    nvl(libelle, REGEXP_SUBSTR(classe, '[^\.]+', 1, REGEXP_COUNT(classe, '\.') + 1)) as libelle
from CLASSEETFICHE
;
-- [1228/1309] COMPTA_ECRITURE_FICHE
CREATE OR REPLACE FORCE VIEW "COMPTA_ECRITURE_FICHE" ("ID","DATY","DATECOMPTABLE","EXERCICE","DESIGNATION","REMARQUE","ETAT","HORSEXERCICE","JOURNAL","OD","ORIGINE","CREDIT","DEBIT","IDUSER","PERIODE","TRIMESTRE","ANNEE","IDOBJET","LETTRAGE","LIEN","DATESAISIE","DATEMODIF","IDMODIFICATEUR","IDMODIFICATEURLIB","JOURNALLIB") AS
select ce."ID",
       ce."DATY",
       ce."DATECOMPTABLE",
       ce."EXERCICE",
       ce."DESIGNATION",
       ce."REMARQUE",
       ce."ETAT",
       ce."HORSEXERCICE",
       ce."JOURNAL",
       ce."OD",
       ce."ORIGINE",
       ce."CREDIT",
       ce."DEBIT",
       ce."IDUSER",
       ce."PERIODE",
       ce."TRIMESTRE",
       ce."ANNEE",
       ce."IDOBJET",
       ce."LETTRAGE",
       vc.FICHE  as lien,
       ce.dateSaisie,
       ce.DATEMODIF,
       ce.idModificateur,
       u.NOMUSER as idModificateurlib,
       cj.VAL as journalLib
from COMPTA_ECRITURE ce
         left join V_CLASSEETFICHE vc on substr(ce.IDOBJET, 1, 3) = vc.LIBELLE
         left join utilisateur u on ce.idmodificateur = u.REFUSER
        left join COMPTA_JOURNAL cj on cj.id=ce.JOURNAL
;
-- [1229/1309] V_COMPTA_COMPTE
CREATE OR REPLACE FORCE VIEW "V_COMPTA_COMPTE" ("ID","COMPTEINT","COMPTE","LIBELLE","TYPECOMPTE","CLASSY","ANALYTIQUE_OBLI","IDJOURNAL","CODEIMPOT") AS
SELECT
    id,
    TO_NUMBER(REGEXP_SUBSTR(TRIM(compte), '^[0-9]+')) AS compteInt,
    compte,
    libelle,
    typecompte,
    classy,
    analytique_obli,
    idjournal,
    codeimpot
FROM compta_compte
WHERE REGEXP_LIKE(TRIM(compte), '^[0-9]+')
;
-- [1230/1309] V_COMPTA_ETAT_BALANCE
CREATE OR REPLACE FORCE VIEW "V_COMPTA_ETAT_BALANCE" ("EXERCICE","TYPECOMPTE","MOISDEBUT","MOISFIN","DEBUTCOMPTE","FINCOMPTE","ETAT") AS
select
    CAST(0 AS int) as exercice,
    CAST(' ' AS varchar(1)) as typeCompte,
    CAST(0 AS int) as moisDebut,
    CAST(0 AS int) as moisFin,
    CAST(' ' AS varchar(1)) as debutCompte,
    CAST(' ' AS varchar(1)) as finCompte,
    CAST(0 AS int) as etat
from dual
;
-- [1231/1309] V_DETAILSBONCAISSECLIENTRESTE
CREATE OR REPLACE FORCE VIEW "V_DETAILSBONCAISSECLIENTRESTE" ("ID","IDCLIENTLIB","IDCAISSE","IDCAISSELIB","IDPOINT","IDPOINTLIB","DEBIT","CREDIT","RESTE") AS
SELECT
	d.IDCLIENT as ID,
	d.IDCLIENTLIB,
	d.IDCAISSE,
	d.IDCAISSELIB,
	d.IDPOINT,
	d.IDPOINTLIB,
	sum(d.DEBIT) as DEBIT,
	sum(d.CREDIT) as CREDIT,
	sum(d.CREDIT)-sum(d.DEBIT) AS reste
FROM
	DetailsBonCaisseCpl d
GROUP by
	d.IDCAISSE,
	d.IDCAISSELIB,
	d.IDPOINT,
	d.IDPOINTLIB,
	d.IDCLIENT,
	d.IDCLIENTLIB
;
-- [1232/1309] V_DUREE_REELLE_TRAVAUX
CREATE OR REPLACE FORCE VIEW "V_DUREE_REELLE_TRAVAUX" ("REFOBJET","OBJET","ACTION","DATEHISTORIQUE","HEURE","DUREE_HEURES_DECIMALE","ECART") AS
SELECT
    p.REFOBJET,
    p.OBJET,
    p.ACTION,
    p.DATEHISTORIQUE,
    p.HEURE,
    CASE
        WHEN p.HEURE IS NOT NULL THEN
            TO_NUMBER(SUBSTR(p.HEURE, 1, INSTR(p.HEURE, ':') - 1)) +
            (TO_NUMBER(SUBSTR(p.HEURE, INSTR(p.HEURE, ':') + 1)) / 60)
        ELSE NULL
        END AS DUREE_HEURES_DECIMALE,
    p.ECART
FROM PROCESS p
WHERE p.REFOBJET IS NOT NULL
;
-- [1233/1309] V_DUREE_AGREGEE_TRAVAUX
CREATE OR REPLACE FORCE VIEW "V_DUREE_AGREGEE_TRAVAUX" ("REFOBJET","DUREE_REELLE_TOTAL_HEURES","ECART_ENREGISTRE") AS
SELECT
    REFOBJET,
    SUM(DUREE_HEURES_DECIMALE) AS DUREE_REELLE_TOTAL_HEURES,
    MAX(ECART) AS ECART_ENREGISTRE
FROM V_DUREE_REELLE_TRAVAUX
GROUP BY REFOBJET
;
-- [1234/1309] V_DUREE_TRAVAUX_MACHINE
CREATE OR REPLACE FORCE VIEW "V_DUREE_TRAVAUX_MACHINE" ("IDINGREDIENTS","DESCRIPTIONOBJET","DATY","ID_TRAVAUX","DUREE_ESTIMATIVE_HEURES","DUREE_REELLE_HEURES","ECART_HEURES","ECART_POURCENTAGE","ECART_ENREGISTRE") AS
SELECT
    CASE
        WHEN aim.id IS NULL THEN ai.id
        ELSE aim.id
        END AS idIngredients,
    CASE
        WHEN aim.libelle IS NULL THEN ai.descriptionObjet
        ELSE aim.libelle
        END AS DESCRIPTIONOBJET,
    t.DATY,
    t.ID AS ID_TRAVAUX,
    NVL(t.DUREEESTIMATIF, 0) AS DUREE_ESTIMATIVE_HEURES,
    COALESCE(vd.DUREE_REELLE_TOTAL_HEURES, 0) AS DUREE_REELLE_HEURES,
    COALESCE(vd.DUREE_REELLE_TOTAL_HEURES, 0) - COALESCE (t.DUREEESTIMATIF, 0) AS ECART_HEURES,
    CASE
        WHEN t.DUREEESTIMATIF > 0 THEN
            ROUND(((COALESCE(vd.DUREE_REELLE_TOTAL_HEURES, 0) - t.DUREEESTIMATIF) / t.DUREEESTIMATIF) * 100, 2)
        ELSE NULL
        END AS ECART_POURCENTAGE,
    vd.ECART_ENREGISTRE
FROM ORDRETRAVAUXFILLE o
         LEFT JOIN AS_INGREDIENTS aim
                   ON o.IDINGREDIENTS = aim.ID
         LEFT JOIN as_ingredient_maintenance ai
                   ON o.IDINGREDIENTS = ai.ID
         JOIN TRAVAUX t
              ON o.id = t.IDOFFILLE
         LEFT JOIN V_DUREE_AGREGEE_TRAVAUX vd
                   ON vd.REFOBJET = t.ID
;
-- [1235/1309] DUREETRAVAUXMACHINE
CREATE OR REPLACE FORCE VIEW "DUREETRAVAUXMACHINE" ("IDMACHINE","NOMMACHINE","DATY","IDTRAVAUX","DUREEESTIMATIF","DUREE","ECART") AS
SELECT
    IDINGREDIENTS AS idMachine,
    DESCRIPTIONOBJET AS nomMachine,
    DATY,
    ID_TRAVAUX AS idTravaux,
    DUREE_ESTIMATIVE_HEURES AS DureeEstimatif ,
    DUREE_REELLE_HEURES as Duree ,
    ECART_HEURES AS ecart
FROM V_DUREE_TRAVAUX_MACHINE
ORDER BY DATY DESC
;
-- [1236/1309] MOYENNETRAVAUXMACHINE
CREATE OR REPLACE FORCE VIEW "MOYENNETRAVAUXMACHINE" ("IDMACHINE","NOMMACHINE","MOYENNEDUREEESTIMATIF","MOYENNEDUREE","MOYENNEECART") AS
SELECT
    d.IDMACHINE,
    d.NOMMACHINE ,
    CAST (AVG(d.DUREEESTIMATIF) AS NUMBER(10, 2)) AS moyenneDureeEstimatif,
    CAST (AVG(d.DUREE) AS NUMBER(10, 2)) AS moyenneDuree,
    CAST (AVG(d.ECART) AS NUMBER(10, 2)) as moyenneEcart
FROM DUREETRAVAUXMACHINE d
GROUP BY d.IDMACHINE, d.NOMMACHINE
;
-- [1237/1309] TAUXDISPONIBILITEMACHINE
CREATE OR REPLACE FORCE VIEW "TAUXDISPONIBILITEMACHINE" ("IDMACHINE","NOMMACHINE","IDLIGNE","IDLIGNELIB","TAUXDISPONIBILITE") AS
SELECT
    m.IDMACHINE ,
    m.NOMMACHINE ,
    l.ID AS idLigne,
    l.VAL AS idLigneLib,
    CASE
        WHEN m2.ECARTJOURS != 0 AND m.MOYENNEDUREE !=0 THEN (m2.ECARTJOURS * 24)/((m2.ECARTJOURS * 24)/m.MOYENNEDUREE)
		ELSE 0
END AS TauxDisponibilite
FROM MOYENNETRAVAUXMACHINE m
LEFT JOIN MOYENNEPANNESTRAVAUX m2
ON m.IDMACHINE = m2.IDMACHINE
LEFT JOIN AS_INGREDIENT_MAINTENANCE aim
ON m.IDMACHINE = aim.ID
LEFT JOIN LIGNE l
ON aim.IDLIGNE = l.ID
;
-- [1238/1309] V_ETATCAISSE
CREATE OR REPLACE FORCE VIEW "V_ETATCAISSE" ("IDCAISSE","IDCAISSELIB","CREDIT","DEBIT","RESTE","TAUX","RESTEAR","DATY","ID","DATEDERNIERREPORT","MONTANTDERNIERREPORT","IDPOINT","IDPOINTLIB","IDTYPECAISSE","IDTYPECAISSELIB","MOTSCLESSS") AS
WITH MAX_INVENTAIRE AS (
    -- Etape 1 : On extrait la date maximale valide et la quantite par COUPLE produit/magasin
    SELECT REP.IDCAISSE,
           MAX(REP.DATY)                                             AS MAX_DATY,
           MAX(REP.MONTANT) KEEP (DENSE_RANK LAST ORDER BY REP.DATY) AS MONTANT_MAX_DATY
    FROM REPORTCAISSEAVECHEURE REP
    WHERE REP.ETAT >= 11 --and rep.DATY<=TO_DATE('27/07/2026','DD-MM-YYYY')
    GROUP BY REP.IDCAISSE),
     TAUXCHANGEMAX
         AS (SELECT MAX(TAU.TAUX) KEEP (DENSE_RANK LAST ORDER BY TAU.DATY) AS TAUX,
                    TAU.IDDEVISE                                           AS TAUXIDDEVISE,
                    MAX(TAU.DATY)                                          AS TAUXDATY
             FROM TAUXDECHANGE TAU
             GROUP BY IDDEVISE),
     SOMME_PRECALC AS (SELECT C.ID                              AS IDCAISSE,
                              C.VAL                             AS IDCAISSELIB,
                              NVL(SUM(CASE
                                          WHEN MFF.DATY > NVL(INV.MAX_DATY, DATE '2025-01-01') THEN MFF.CREDIT
                                          ELSE 0 END), 0)       AS CREDIT,

                              NVL(SUM(CASE
                                          WHEN MFF.DATY > NVL(INV.MAX_DATY, DATE '2025-01-01') THEN MFF.DEBIT
                                          ELSE 0 END), 0)       AS DEBIT,
                              MAX(INV.MAX_DATY)                 AS DATEDERNIERREPORT,
                              NVL(MAX(INV.MONTANT_MAX_DATY), 0) AS MONTANTDERNIERREPORT,
                              C.IDPOINT,
                              P.VAL                             AS IDPOINTLIB,
                              C.IDTYPECAISSE,
                              TYP.VAL                           AS IDTYPECAISSELIB,
                              C.IDDEVISE,
                              MAX(TAU.TAUX)                     AS TAUX
                       FROM CAISSE C
                                LEFT JOIN MOUVEMENTCAISSEAVECHEURE MFF
                                          ON MFF.IDCAISSE = C.ID AND MFF.ETAT >= 11 AND MFF.IDREPORT IS NOT NULL-- and mff.DATY<=TO_DATE('27/07/2026','DD-MM-YYYY')
                                JOIN MAX_INVENTAIRE INV ON INV.IDCAISSE = C.ID
                                LEFT JOIN TAUXCHANGEMAX TAU ON TAU.TAUXIDDEVISE = C.IDDEVISE
                                LEFT JOIN POINT P ON P.ID = C.IDPOINT
                                LEFT JOIN TYPECAISSE TYP ON TYP.ID = C.IDTYPECAISSE
                       GROUP BY C.ID, C.IDPOINT, P.VAL, C.IDTYPECAISSE, TYP.VAL, C.VAL, C.IDDEVISE)
-- Selection finale
SELECT IDCAISSE,
       IDCAISSELIB || ' (' || NVL(IDDEVISE, 'AR') || ')'                             AS IDCAISSELIB,
       CAST(CREDIT AS NUMBER(30, 2))                                                 AS CREDIT,
       CAST(DEBIT AS NUMBER(30, 2))                                                  AS DEBIT,
       CAST(MONTANTDERNIERREPORT + CREDIT - DEBIT AS NUMBER(30, 2))                  AS RESTE,
       CAST(NVL(TAUX, 1) AS NUMBER(30, 2))                                           AS TAUX,
       CAST((MONTANTDERNIERREPORT + CREDIT - DEBIT) * NVL(TAUX, 1) AS NUMBER(30, 2)) AS RESTEAR,
       DATE '2025-01-01'                                                             AS DATY,
       IDCAISSE                                                                      AS ID,
       DATEDERNIERREPORT,
       CAST(MONTANTDERNIERREPORT AS NUMBER(30, 2))                                   AS MONTANTDERNIERREPORT,
       IDPOINT,
       IDPOINTLIB,
       IDTYPECAISSE,
       IDTYPECAISSELIB,
       (IDCAISSELIB || ' | ' || IDPOINTLIB || ' | ' || IDTYPECAISSELIB || ' | ' || DATEDERNIERREPORT) AS MOTSCLESSS
FROM SOMME_PRECALC
;
-- [1239/1309] V_ETATCAISSE_CLOTURE
CREATE OR REPLACE FORCE VIEW "V_ETATCAISSE_CLOTURE" ("ID","IDCAISSE","IDCAISSELIB","IDTYPECAISSE","IDTYPECAISSELIB","IDPOINT","IDPOINTLIB","DATEDERNIERREPORT","MONTANTDERNIERREPORT","DEBIT","CREDIT","RESTE","DEVISE") AS
SELECT
    r.ID,
    r.IDCAISSE,
    c.val AS idcaisseLib,
    c.idtypecaisse,
    tc.desce AS idtypecaisselib,
    c.idpoint,
    p.desce AS idpointlib,
    r.DATY AS dateDernierReport,
    CAST(NVL(((r.MONTANT + NVL(mvtAv.CREDIT - mvtAv.DEBIT, 0)) * taux.taux), 0) AS NUMBER(30,2)) AS montantDernierReport,
    CAST(NVL(mvt.debit, 0) AS NUMBER(30,2)) AS debit,
    CAST(NVL(mvt.credit, 0) AS NUMBER(30,2)) AS credit,
    CAST((NVL(mvt.credit, 0) - NVL(mvt.debit, 0)) AS NUMBER(30,2)) AS reste,
    'AR' AS devise
FROM REPORTCAISSE_deVISE r,
     (
         SELECT  r.IDCAISSE,
                 MAX(r.DATY) AS maxDateReport
         FROM REPORTCAISSE_deVISE r
         WHERE r.ETAT = 11
           AND r.DATY <= TRUNC(SYSDATE)
         GROUP BY r.IDCAISSE
     ) rm,
     (
         SELECT  m.IDCAISSE,
                 SUM(NVL((m.DEBIT * t.taux),0)) AS DEBIT,
                 SUM(NVL((m.CREDIT * t.taux),0)) AS CREDIT
         FROM MOUVEMENTCAISSE_VISE m,
              (
                  SELECT  r.IDCAISSE,
                          MAX(r.DATY) AS maxDateReport
                  FROM REPORTCAISSE r
                  WHERE r.ETAT = 11
                    AND r.DATY <= TRUNC(SYSDATE)
                  GROUP BY r.IDCAISSE
              ) rm,
              (
                  SELECT ta.*
                  FROM TAUXDECHANGE ta,
                       (
                           SELECT MAX(daty) AS daty, iddevise
                           FROM TAUXDECHANGE t
                           WHERE daty <= TRUNC(SYSDATE)
                           GROUP BY iddevise
                       ) tmax
                  WHERE ta.daty = tmax.daty
                    AND ta.iddevise = tmax.iddevise
              ) t
         WHERE m.IDDEVISE = t.iddevise(+)
           AND m.IDCAISSE = rm.idcaisse(+)
           AND m.DATY >= TRUNC(SYSDATE)
           AND m.DATY <= TRUNC(SYSDATE)
         GROUP BY m.IDCAISSE
     ) mvt,
     (
         SELECT  m.IDCAISSE,
                 SUM(NVL((m.DEBIT * t.taux),0)) AS DEBIT,
                 SUM(NVL((m.CREDIT * t.taux),0)) AS CREDIT
         FROM MOUVEMENTCAISSE_VISE m,
              (
                  SELECT  r.IDCAISSE,
                          MAX(r.DATY) AS maxDateReport
                  FROM REPORTCAISSE r
                  WHERE r.ETAT = 11
                    AND r.DATY <= TRUNC(SYSDATE)
                  GROUP BY r.IDCAISSE
              ) rm,
              (
                  SELECT ta.*
                  FROM TAUXDECHANGE ta,
                       (
                           SELECT MAX(daty) AS daty, iddevise
                           FROM TAUXDECHANGE t
                           WHERE daty <=TRUNC(SYSDATE)
                           GROUP BY iddevise
                       ) tmax
                  WHERE ta.daty = tmax.daty
                    AND ta.iddevise = tmax.iddevise
              ) t
         WHERE m.IDDEVISE = t.iddevise(+)
           AND m.IDCAISSE = rm.idcaisse(+)
           AND m.DATY >= maxDateReport
           AND m.DATY < TRUNC(SYSDATE)
         GROUP BY m.IDCAISSE
     ) mvtAv,
     (
         SELECT ta.*
         FROM TAUXDECHANGE ta,
              (
                  SELECT MAX(daty) AS daty, iddevise
                  FROM TAUXDECHANGE t
                  WHERE daty <= TRUNC(SYSDATE)
                  GROUP BY iddevise
              ) tmax
         WHERE ta.daty = tmax.daty
           AND ta.iddevise = tmax.iddevise
     ) taux,
     CAISSE c,
     TYPECAISSE tc,
     POINT p
WHERE r.DATY = rm.maxDateReport
  AND r.IDDEVISE = taux.iddevise(+)
  AND r.ETAT = 11
  AND r.IDCAISSE = rm.IDCAISSE
  AND r.IDCAISSE = c.ID(+)
  AND r.IDCAISSE = mvt.idcaisse(+)
  AND r.IDCAISSE = mvtAv.idcaisse(+)
  AND c.IDTYPECAISSE = tc.ID(+)
  AND c.IDPOINT = p.ID
;
-- [1240/1309] MONTANTCAISSE
CREATE OR REPLACE FORCE VIEW "MONTANTCAISSE" ("CAISSELIB","IDCAISSE","MONTANTTHEORIQUE","MONTANT","DATEDERNIERREPORT","EXPLICATION","IDCLOTURE") AS
SELECT
    etatcaisse.idcaisseLib AS caisselib,
    etatcaisse.idcaisse,
    CAST(ROUND(etatcaisse.reste, 0) AS NUMBER(30,0)) AS montantTheorique,
    0 AS montant,
    etatcaisse.dateDernierReport AS dateDernierReport,
    '' AS explication,
    '' AS idcloture
FROM V_ETATCAISSE_CLOTURE etatcaisse
WHERE TRUNC(etatcaisse.dateDernierReport) <= TRUNC(SYSDATE)
;
-- [1241/1309] V_ETATCAISSE_DEVISE_AR
CREATE OR REPLACE FORCE VIEW "V_ETATCAISSE_DEVISE_AR" ("IDCAISSE","IDCAISSELIB","CREDIT","DEBIT","RESTE","TAUX","RESTEAR","DATY","ID","DATEDERNIERREPORT","MONTANTDERNIERREPORT","IDPOINT","IDPOINTLIB","IDTYPECAISSE","IDTYPECAISSELIB") AS
select "IDCAISSE","IDCAISSELIB","CREDIT","DEBIT","RESTE","TAUX","RESTEAR","DATY","ID","DATEDERNIERREPORT","MONTANTDERNIERREPORT","IDPOINT","IDPOINTLIB","IDTYPECAISSE","IDTYPECAISSELIB" from v_Etatcaisse
;
-- [1242/1309] V_ETATSTOCK
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK" ("ID","IDPRODUITLIB","IDTYPEPRODUIT","IDTYPEPRODUITLIB","IDMAGASIN","IDMAGASINLIB","DATEDERNIERINVENTAIRE","QUANTITE","ENTREE","SORTIE","RESTE","IDUNITE","IDUNITELIB","PUVENTE","IDPOINT","IDTYPEMAGASIN","SEUILMIN","SEUILMAX") AS
SELECT inv.IDPRODUIT AS                                               ID,
       p.desce       AS                                               idproduitLib,
       p.IDTYPEPRODUIT,
       tp.desce      AS                                               idtypeproduitlib,
       inv.idmagasin,
       mag.desce     AS                                               idmagasinlib,
       inv.DATY                                                       dateDernierinventaire,
       CAST(NVL(inv.QUANTITE, 0)  AS NUMBER(30, 2))                                          QUANTITE,
       NVL(mvt.ENTREE, 0)                                             ENTREE,
       NVL(mvt.SORTIE, 0)                                             SORTIE,
       NVL(mvt.ENTREE, 0) + NVL(inv.QUANTITE, 0) - NVL(mvt.SORTIE, 0) reste,
       p.IDUNITE,
       u.desce       AS                                               idunitelib,
       CAST(NVL(p.PUVENTE, 0) AS NUMBER(30, 2))                       PUVENTE,
       mag.IDPOINT,
       mag.IDTYPEMAGASIN,
       p.seuilmin,
       p.seuilmax
FROM INVENTAIRE_FILLE_CPL inv,
     (
         SELECT inv.IDPRODUIT,
                inv.IDMAGASIN,
                MAX(inv.DATY) maxDateInventaire
         FROM INVENTAIRE_FILLE_CPL inv
         WHERE inv.ETAT = 11
           AND inv.DATY <= SYSDATE --- dateMin
         GROUP BY inv.IDPRODUIT, inv.IDMAGASIN
     ) invm,
     (
         SELECT m.IDPRODUIT,
                dinv.IDMAGASIN,
                SUM(nvl(m.ENTREE, 0)) ENTREE,
                SUM(nvl(m.SORTIE, 0)) SORTIE
         FROM MVTSTOCKFILLELIB_VISE m,
              (
                  SELECT inv.IDPRODUIT,
                         inv.IDMAGASIN,
                         MAX(inv.DATY) maxDateInventaire
                  FROM INVENTAIRE_FILLE_CPL inv
                  WHERE inv.ETAT = 11
                    AND inv.DATY <= SYSDATE --- dateMin
                  GROUP BY inv.IDPRODUIT, inv.IDMAGASIN
              ) dinv
         WHERE m.IDPRODUIT = dinv.IDPRODUIT(+)
           AND m.IDMAGASIN = dinv.IDMAGASIN(+)
           AND m.DATY > dinv.maxDateInventaire
           AND m.DATY <= SYSDATE -- dateMax
         GROUP BY m.IDPRODUIT, dinv.IDMAGASIN
     ) mvt,
     produit p,
     type_produit tp,
     magasin mag,
     unite u
WHERE inv.DATY = invm.maxDateInventaire
  AND inv.IDMAGASIN = invm.IDMAGASIN
  AND inv.IDPRODUIT = invm.IDPRODUIT
  AND inv.IDPRODUIT = mvt.IDPRODUIT(+)
  AND inv.IDMAGASIN = mvt.IDMAGASIN(+)
  AND inv.IDPRODUIT = p.ID(+)
  AND p.IDTYPEPRODUIT = tp.ID
  AND inv.idmagasin = mag.ID
  AND p.IDUNITE = u.ID(+)
  AND ( mvt.SORTIE > 0 OR mvt.ENTREE > 0 )
  AND inv.ETAT >= 11
;
-- [1243/1309] V_ETATSTOCK_ENTREE
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_ENTREE" ("ID","IDPRODUIT","IDPRODUITLIB","CATEGORIEINGREDIENT","IDTYPEPRODUITLIB","IDMAGASIN","IDMAGASINLIB","QUANTITE","ENTREE","SORTIE","RESTE","UNITE","IDUNITELIB","PU","DATY","IDFOURNISSEUR","IDFOURNISSEURLIB","DATEACHAT","PUVENTE","IDPOINT","IDTYPEMAGASIN","SEUILMIN","SEUILMAX","MONTANTENTREE","MONTANTSORTIE","MONTANTRESTE","MOTSCLESSS") AS
SELECT SQ.ID,SQ.IDPRODUIT,SQ.IDPRODUITLIB,SQ.CATEGORIEINGREDIENT,SQ.IDTYPEPRODUITLIB,SQ.IDMAGASIN,SQ.IDMAGASINLIB,CAST(COALESCE(SQ.QUANTITE,0) AS NUMBER(30,5)) AS quantite,cast(COALESCE(SQ.ENTREE,0) as number(30,5)) as entree,cast(COALESCE(SQ.SORTIE,0) as number(30,5)) as sortie,CAST(COALESCE(SQ.RESTE,0) AS NUMBER(30,5)) AS reste,SQ.UNITE,SQ.IDUNITELIB,SQ.PU,SQ.DATY,SQ.IDFOURNISSEUR,SQ.IDFOURNISSEURLIB,SQ.DATEACHAT,CAST(COALESCE(SQ.PUVENTE,0) AS NUMBER(30,5)) AS PUVENTE,SQ.IDPOINT,SQ.IDTYPEMAGASIN,CAST(COALESCE(SQ.SEUILMIN,0) AS NUMBER(30,5)) AS SEUILMIN,CAST(COALESCE(SQ.SEUILMAX,0) AS NUMBER(30,5)) AS SEUILMAX ,CAST(COALESCE(SQ.MONTANTENTREE,0) AS NUMBER(30,5)) AS MONTANTENTREE,CAST(COALESCE(SQ.MONTANTSORTIE,0) AS NUMBER(30,5)) AS MONTANTSORTIE ,CAST(COALESCE(SQ.MONTANTRESTE,0) AS NUMBER(30,5)) AS MONTANTRESTE,
       (NVL(TO_CHAR(ID),'') || ' | ' || NVL(TO_CHAR(IDPRODUIT),'') || ' | ' || NVL(TO_CHAR(IDPRODUITLIB),'') || ' | ' || NVL(TO_CHAR(CATEGORIEINGREDIENT),'') || ' | ' || NVL(TO_CHAR(IDTYPEPRODUITLIB),'') || ' | ' || NVL(TO_CHAR(IDMAGASIN),'') || ' | ' || NVL(TO_CHAR(IDMAGASINLIB),'') || ' | ' || NVL(TO_CHAR(QUANTITE),'') || ' | ' || NVL(TO_CHAR(ENTREE),'') || ' | ' || NVL(TO_CHAR(SORTIE),'') || ' | ' || NVL(TO_CHAR(RESTE),'') || ' | ' || NVL(TO_CHAR(UNITE),'') || ' | ' || NVL(TO_CHAR(IDUNITELIB),'') || ' | ' || NVL(TO_CHAR(PU),'') || ' | ' || NVL(TO_CHAR(DATY,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(IDFOURNISSEUR),'') || ' | ' || NVL(TO_CHAR(IDFOURNISSEURLIB),'') || ' | ' || NVL(TO_CHAR(DATEACHAT,'YYYY-MM-DD HH24:MI:SS'),'') || ' | ' || NVL(TO_CHAR(PUVENTE),'') || ' | ' || NVL(TO_CHAR(IDPOINT),'') || ' | ' || NVL(TO_CHAR(IDTYPEMAGASIN),'') || ' | ' || NVL(TO_CHAR(SEUILMIN),'') || ' | ' || NVL(TO_CHAR(SEUILMAX),'') || ' | ' || NVL(TO_CHAR(MONTANTENTREE),'') || ' | ' || NVL(TO_CHAR(MONTANTSORTIE),'') || ' | ' || NVL(TO_CHAR(MONTANTRESTE),'')) AS MOTSCLESSS
FROM (
         SELECT DISTINCT
             ve.id,
             ai.id AS idproduit,
             ai.libelle AS idproduitlib,
             ai.categorieingredient,
             c.val AS idtypeproduitlib,
             ve.idmagasin,
             m.val AS idmagasinlib,
             CAST(ve.quantite AS NUMBER(30,5)) AS quantite,
             CAST(ve.entree AS NUMBER(30,5)) AS entree,
             CAST(ve.sortie AS NUMBER(30,5)) AS sortie,
             CAST(ve.reste AS NUMBER(30,5)) AS reste,
             ai.unite,
             u.val AS idunitelib,
             ve.pu,
             ve.daty,
             ve.idfournisseur,
             f.NOM AS idfournisseurlib,
             ve.dateAchat,
             CAST(NVL(ai.PV, 0) AS NUMBER(30, 5)) AS PUVENTE,
             m.IDPOINT,
             m.IDTYPEMAGASIN,
             ai.SEUILMIN,
             ai.SEUILMAX,
             MONTANTENTREE,
             MONTANTSORTIE,
             MONTANTRESTE
         FROM (
                  SELECT
                      x.*,
                      COALESCE(b.idfournisseur, invf.idfournisseur, bb.IDFOURNISSEUR,trs.idfournisseur) AS idfournisseur,
                      f.DATY as dateAchat

                  FROM (
                           SELECT
                               ID,
                               IDMVTSTOCK,
                               IDPRODUIT,
                               ENTREE,
                               SORTIE,
                               IDVENTEDETAIL,
                               IDTRANSFERTDETAIL,
                               PU,
                               MVTSRC,
                               DATY,
                               RESTE,
                               QUANTITE,
                               IDMAGASIN,
                               IDINVENTAIREFILLE,
                               MONTANTENTREE,
                               MONTANTSORTIE,
                               MONTANTRESTE
                           FROM (
                                    SELECT
                                        mf.ID,
                                        mf.IDMVTSTOCK,
                                        mf.IDPRODUIT,
                                        nvl(mf.ENTREE,0)+nvl(s.ENTREE,0) as entree,
                                        s.SORTIE,
                                        mf.IDVENTEDETAIL,
                                        mf.IDTRANSFERTDETAIL,
                                        mf.PU,
                                        mf.MVTSRC,
                                        ms.DATY,
                                        NVL(mf.ENTREE, 0) - NVL(s.SORTIE, 0)  + NVL(s.ENTREE, 0) AS RESTE,
                                        NVL(mf.ENTREE, 0) - NVL(s.SORTIE, 0) +  NVL(s.ENTREE, 0) AS QUANTITE,
                                        ms.IDMAGASIN,
                                        mf.idinventairefille,
                                        cast((mf.PU*mf.ENTREE) as number(30,5)) AS MONTANTENTREE,
                                        cast((mf.PU*s.SORTIE) as number(30,5)) AS MONTANTSORTIE,
                                        CAST(NVL(mf.ENTREE, 0) - NVL(s.SORTIE, 0)  + NVL(s.ENTREE, 0) AS NUMBER(30,5)) * mf.PU AS MONTANTRESTE

                                    FROM MVTSTOCKFILLE mf
                                             LEFT JOIN MVTSTOCK ms ON ms.id = mf.IDMVTSTOCK
                                             LEFT JOIN (
                                        SELECT mf2.MVTSRC, SUM(mf2.SORTIE) AS SORTIE,SUM(mf2.ENTREE) AS ENTREE
                                        FROM MVTSTOCKFILLE mf2
                                                 LEFT JOIN MVTSTOCK ms2 ON ms2.id = mf2.IDMVTSTOCK
                                        WHERE ms2.ETAT >= 11
                                          AND mf2.MVTSRC IS NOT NULL
                                        GROUP BY mf2.MVTSRC
                                    ) s ON s.MVTSRC = mf.id
                                    WHERE mf.ENTREE > 0 and (mf.MVTSRC is null or mf.MVTSRC=mf.id)
                                      AND (ms.IDCATEGORIESTOCK IS NULL
                                        OR ms.IDCATEGORIESTOCK <> 'CTGST000003')
                                      AND ms.ETAT >= 11
                                )
                       ) x
                           LEFT JOIN MVTSTOCK ms  ON ms.id = x.IDMVTSTOCK
                           LEFT JOIN AS_BONDELIVRAISON b ON b.ID = ms.IDOBJET
                           LEFT JOIN AS_BONDELIVRAISON bb ON b.ID = ms.IDTRANSFERT
                           LEFT JOIN FACTUREFOURNISSEUR f on f.id=b.IDFACTUREFOURNISSEUR
                           LEFT JOIN INVENTAIREFILLE invf ON invf.id = x.IDINVENTAIREFILLE
                           LEFT JOIN TRANSFERTSTOCKDETAILS trs ON trs.id = x.IDTRANSFERTDETAIL
                  WHERE b.IDFOURNISSEUR IS NOT NULL OR invf.IDFOURNISSEUR IS NOT NULL or bb.IDFOURNISSEUR IS NOT NULL OR trs.idfournisseur is not null

              ) ve

                  LEFT JOIN AS_INGREDIENTS ai ON ai.id = ve.IDPRODUIT
                  LEFT JOIN CATEGORIEINGREDIENT c ON ai.CATEGORIEINGREDIENT = c.id
                  LEFT JOIN MAGASINPOINT m ON ve.IDMAGASIN = m.id
                  LEFT JOIN AS_UNITE u ON ai.UNITE = u.id

                  LEFT JOIN FOURNISSEUR f ON f.ID = ve.idfournisseur

         WHERE ve.PU > 0 AND CAST(ve.reste AS NUMBER(30,5)) != 0
     ) SQ
;
-- [1244/1309] PRIXTEMP
CREATE OR REPLACE FORCE VIEW "PRIXTEMP" ("PUTEMP","IDPRODUIT") AS
SELECT AVG(PU)AS putemp,IDPRODUIT FROM V_ETATSTOCK_ENTREE vee GROUP BY IDPRODUIT
;
-- [1245/1309] V_ETATSTOCK_ENTREE_DMDACHAT
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_ENTREE_DMDACHAT" ("ID","IDPRODUIT","IDPRODUITLIB","CATEGORIEINGREDIENT","IDTYPEPRODUITLIB","IDMAGASIN","IDMAGASINLIB","QUANTITE","ENTREE","SORTIE","RESTE","UNITE","IDUNITELIB","PU","DATY") AS
SELECT
    ai.id AS ID,
    ai.id AS IDPRODUIT,
    ai.LIBELLE AS IDPRODUITLIB,
    ai.CATEGORIEINGREDIENT,
    c.VAL AS IDTYPEPRODUITLIB,
    ve.IDMAGASIN,
    ai.IDMAGASINLIB,
    CAST(SUM(nvl(ve.QUANTITE, 0)) AS NUMBER(30,5)) AS QUANTITE,
    CAST(SUM(nvl(ve.ENTREE, 0))AS NUMBER(30,5)) AS ENTREE,
    CAST(SUM(nvl(ve.SORTIE, 0))AS NUMBER(30,5)) AS SORTIE,
    CAST(SUM(nvl(ve.RESTE, 0))AS NUMBER(30,5)) AS RESTE,
    ai.UNITE,
    u.VAL AS IDUNITELIB,
    CAST(MIN(nvl(ve.PU, 0))AS NUMBER(30,5)) AS PU,  -- On prend le PU minimal si plusieurs
    MIN(ve.DATY) AS DATY  -- Date representative
FROM
    as_ingredientxmagasin2 ai
    left join MVTSTOCKENTREEAVECRESTE ve on ai.id = ve.IDPRODUIT
    LEFT JOIN CATEGORIEINGREDIENT c ON ai.CATEGORIEINGREDIENT = c.id
    LEFT JOIN UNITE u ON ai.UNITE = u.id
--WHERE ve.RESTE > 0 AND ve.PU > 0
GROUP BY
    ai.id,
    ai.LIBELLE,
    ai.CATEGORIEINGREDIENT,
    c.VAL,
    ve.IDMAGASIN,
    ai.UNITE,
    u.VAL, ai.IDMAGASINLIB
;
-- [1246/1309] V_ETATSTOCK_ENTREE_STANDARD
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_ENTREE_STANDARD" ("ID","DATY","INVQUANTITE","ENTREE","SORTIE","RESTE","QUANTITE","MONTANTRESTE","IDPRODUITLIB","CATEGORIEINGREDIENT","UNITE","TYPESTOCK","IDUNITELIB","IDTYPEPRODUITLIB","PU","IDFOURNISSEUR","IDFOURNISSEURLIB","IDPRODUIT","IDMAGASIN","IDMAGASINLIB","INVDATY") AS
WITH max_inventaire AS (
    -- ?    tape 1 : On extrait la date maximale valide par produit une fois pour toutes
    SELECT
        invff.MVTSRC,
        MAX(imeref.DATY) AS max_daty
    FROM INVENTAIREFILLE invff
             LEFT JOIN inventaireDateHeure imeref ON imeref.ID = invff.IDINVENTAIRE
    WHERE imeref.ETAT >= 11
    GROUP BY invff.MVTSRC
),
     inv_final_precalc AS (
         -- ?   tape 2 : On r??cup??re les quantit??s associ??es ?  cette date maximale
         SELECT
             invfff.MVTSRC,
             invfff.QUANTITE,
             imm.DATY AS invdaty
         FROM INVENTAIREFILLE invfff
                  LEFT JOIN inventaireDateHeure imm ON imm.ID = invfff.IDINVENTAIRE
                  INNER JOIN max_inventaire mi ON mi.MVTSRC = invfff.MVTSRC AND imm.DATY = mi.max_daty
         WHERE imm.ETAT >= 11
     ),
     somme_precalc AS (
         -- ?   tape 3 : Calcul des sommes globales (sorties/entr??es) sans sous-requ??te corr??l??e cass??e
         SELECT
             mff.MVTSRC,
             NVL(SUM(mff.ENTREE), 0) AS entree,
             NVL(SUM(mff.SORTIE), 0) AS sortie
         FROM MVTSTOCKFILLE mff
                  LEFT JOIN mvtStockDateHeure meref ON meref.ID = mff.IDMVTSTOCK
                  LEFT JOIN inv_final_precalc inv ON inv.MVTSRC = mff.MVTSRC
         WHERE meref.DATY > nvl(inv.invdaty,to_date('01/01/2025','DD-MM-YYYY')) and meref.ETAT>=11
           AND meref.IDTYPEMVSTOCK != 'TPMVST000023'
         GROUP BY mff.MVTSRC
     ),
     main_data AS (
         -- ?   tape 4 : Requ??te principale avec application exacte des r??gles de calcul d'origine
         SELECT
             mf.ID,
             mere.DATY,
             CAST(NVL(invfinal.QUANTITE, 0) AS NUMBER(30,3)) AS invquantite,

             CASE WHEN mere.DATY > NVL(invfinal.invdaty, TO_DATE('01/01/2025','DD-MM-YYYY'))
                      THEN CAST(NVL(mf.ENTREE, 0) AS NUMBER(30,3))
                  ELSE 0
                 END AS ENTREE,

             CAST(NVL(somme.SORTIE, 0) AS NUMBER(30,3)) AS sortie,

             CASE WHEN mere.DATY <= NVL(invfinal.invdaty, TO_DATE('01/01/2025','DD-MM-YYYY'))
                      THEN CAST((NVL(invfinal.QUANTITE, 0) - NVL(somme.SORTIE, 0)) AS NUMBER(30,3))
                  ELSE CAST((NVL(invfinal.QUANTITE, 0) + mf.ENTREE - NVL(somme.SORTIE, 0)) AS NUMBER(30,3))
                 END AS reste,

             ai.LIBELLE AS idproduitlib,
             ai.CATEGORIEINGREDIENT,
             ai.UNITE,
             ai.TYPESTOCK,
             u.VAL AS idunitelib,
             c.VAL AS idtypeproduitlib,
             mf.PU,
             b.IDFOURNISSEUR,
             b.IDFOURNISSEURLIB,
             mf.IDPRODUIT,
             mere.IDMAGASIN,
             m.VAL AS idmagasinlib,
             invfinal.invdaty AS invdaty
         FROM MVTSTOCKFILLE mf
                  LEFT JOIN mvtStockDateHeure mere ON mere.id = mf.IDMVTSTOCK
                  LEFT JOIN somme_precalc somme ON somme.MVTSRC = mf.id
                  LEFT JOIN inv_final_precalc invfinal ON invfinal.MVTSRC = mf.ID
                  LEFT JOIN AS_INGREDIENTS ai ON ai.id = mf.IDPRODUIT
                  LEFT JOIN CATEGORIEINGREDIENT c ON ai.CATEGORIEINGREDIENT = c.id
                  LEFT JOIN MAGASINPOINT m ON mere.IDMAGASIN = m.id
                  LEFT JOIN AS_UNITE u ON ai.UNITE = u.id
                  LEFT JOIN AS_BONDELIVRAISON_LIB b ON b.ID = mere.IDOBJET
         WHERE mf.ENTREE > 0
            AND mere.IDTYPEMVSTOCK != 'TPMVST000023'
            AND mere.ETAT >= 11
            AND ai.TYPESTOCK != 'CUMP'
     )
SELECT
    ID, DATY, CAST(invquantite AS NUMBER(30,3)) AS invquantite, CAST(entree AS NUMBER(30,3)) AS entree, CAST(sortie AS NUMBER(30,3)) AS sortie, CAST(reste AS NUMBER(30,3)) AS reste,
    CAST(reste AS NUMBER(30,3)) AS quantite,
    CAST(reste * PU AS NUMBER(30,2)) AS montantreste,
    idproduitlib, CATEGORIEINGREDIENT, UNITE, TYPESTOCK, idunitelib, idtypeproduitlib,
    PU, IDFOURNISSEUR, IDFOURNISSEURLIB, IDPRODUIT, IDMAGASIN, idmagasinlib, invdaty
FROM main_data
WHERE reste != 0
;
-- [1247/1309] V_ETATSTOCK_ING
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_ING" ("ID","DATY","INVQUANTITE","ENTREE","SORTIE","RESTE","QUANTITE","MONTANTRESTE","IDPRODUITLIB","CATEGORIEINGREDIENT","UNITE","TYPESTOCK","IDUNITELIB","IDTYPEPRODUITLIB","PU","IDFOURNISSEUR","IDFOURNISSEURLIB","IDPRODUIT","IDMAGASIN","IDMAGASINLIB","INVDATY") AS
SELECT
    '' as id,
    '' as DATY,
    cast(sum(invquantite) as number(30,3)) as invquantite,
    cast(sum(entree) as number(30,3)) as entree,
    cast(sum(sortie) as number(30,3)) as sortie,
    cast(sum(reste) as number(30,3)) as reste,
    cast(sum(quantite) as number(30,3)) as quantite,
    cast(sum(reste)* avg(pu) as number(30,2)) as montantReste,
    idproduitlib,
    CATEGORIEINGREDIENT,
    UNITE,
    TYPESTOCK,
    idunitelib,
    idtypeproduitlib,
    avg(PU) AS PU,
    '' as IDFOURNISSEUR,
    '' as IDFOURNISSEURLIB,
    IDPRODUIT,
    IDMAGASIN,
    idmagasinlib,
    min(invdaty) as invdaty
FROM (
    SELECT * FROM V_ETATSTOCK_ENTREE_STANDARD
    union all select * from (
    WITH max_inventaire AS (
        SELECT
            invff.IDPRODUIT,imeref.IDMAGASIN,
            MAX(imeref.DATY) AS max_daty
            ,MAX(invff.QUANTITE) KEEP (DENSE_RANK LAST ORDER BY imeref.DATY) AS qte_max_daty,
            MAX(invff.pu) KEEP (DENSE_RANK LAST ORDER BY imeref.DATY) AS pu_max_daty
        FROM INVENTAIREFILLE invff
        LEFT JOIN inventaireDateHeure imeref ON imeref.ID = invff.IDINVENTAIRE
        WHERE imeref.ETAT >= 11 and invff.MVTSRC is null
        GROUP BY invff.IDPRODUIT, imeref.IDMAGASIN
    ),
         somme_precalc AS (
             -- Etape 3 : Calcul des sommes globales agregees par COUPLE produit/magasin
             SELECT
                 mff.idproduit as idproduit,
                 meref.idmagasin as idmagasin,
                 NVL(SUM(CASE WHEN meref.DATY >NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.ENTREE ELSE 0 END), 0) AS entree,

                 NVL(SUM(CASE WHEN meref.DATY > NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.SORTIE ELSE 0 END), 0) AS sortie,
                 ai.LIBELLE AS idproduitlib,
            ai.CATEGORIEINGREDIENT as CATEGORIEINGREDIENT,
            ai.UNITE as unite,
            ai.TYPESTOCK as typestock,
            u.VAL AS idunitelib,
            c.VAL AS idtypeproduitlib,
                 avg(mff.PU) as pu,
                 null as IDFOURNISSEUR,
                 null as IDFOURNISSEURLIB,
                 m.VAL AS idmagasinlib,
                 max(inv.max_daty) AS invdaty,
                 nvl(max(inv.qte_max_daty),0)as invquantite,
                 NVL(SUM(CASE WHEN meref.DATY >NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.ENTREE*mff.pu ELSE 0 END), 0) AS montantEntree,
                 NVL(SUM(CASE WHEN meref.DATY > NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.SORTIE*mff.pu ELSE 0 END), 0) AS montantSortie,
                 nvl(avg(inv.pu_max_daty*inv.qte_max_daty),0) as montantInv, nvl(max(ai.SEUIL),0) as seuil,nvl(max(ai.SEUILMAX),nvl(max(ai.SEUILMIN),0)+1000) as seuilmax,nvl(max(ai.SEUILMIN),0) as seuilMin
             FROM MVTSTOCKFILLE mff
                      LEFT JOIN mvtStockDateHeure meref ON meref.ID = mff.IDMVTSTOCK
        LEFT JOIN max_inventaire inv ON inv.idproduit = mff.idproduit AND inv.idmagasin = meref.idmagasin
        LEFT JOIN AS_INGREDIENTS ai ON ai.id = mff.IDPRODUIT
        LEFT JOIN CATEGORIEINGREDIENT c ON ai.CATEGORIEINGREDIENT = c.id
        LEFT JOIN MAGASINPOINT m ON meref.IDMAGASIN = m.id
        LEFT JOIN AS_UNITE u ON ai.UNITE = u.id
        WHERE --meref.DATY > NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) and
          meref.ETAT >= 11
          AND meref.IDTYPEMVSTOCK != 'TPMVST000023' and mff.MVTSRC is null
          and not exists(select 1 from V_ETATSTOCK_ENTREE_STANDARD  ve where ve.id = mff.id)
        GROUP BY mff.idproduit, meref.idmagasin,ai.LIBELLE,ai.CATEGORIEINGREDIENT,ai.UNITE,ai.TYPESTOCK,u.VAL,c.VAL,m.VAL
         )
    SELECT
        null as ID, null as DATY,  cast(invquantite as number(30,3)) as invquantite,cast(entree as number(30,3)) as entree, cast(sortie as number(30,3)) as sortie,CAST((invquantite)+(ENTREE)-(sortie) AS NUMBER(30,3)) as reste,
        CAST(invquantite+ENTREE-sortie AS NUMBER(30,3)) AS quantite,
        CAST((montantInv+montantEntree-montantSortie)AS NUMBER(30,2))AS montantreste,
        idproduitlib, CATEGORIEINGREDIENT, UNITE, TYPESTOCK, idunitelib, idtypeproduitlib,
        cast((montantInv+montantEntree-montantSortie)/(invquantite+ENTREE-sortie)  as number(30,2)) as pu,
        IDFOURNISSEUR, IDFOURNISSEURLIB, IDPRODUIT, IDMAGASIN, idmagasinlib,invdaty
    FROM somme_precalc
    WHERE (invquantite+ENTREE-sortie) != 0)
) GROUP BY
idproduitlib, CATEGORIEINGREDIENT, UNITE, TYPESTOCK,
idunitelib, idtypeproduitlib, IDPRODUIT,
IDMAGASIN, idmagasinlib
;
-- [1248/1309] V_ETATSTOCK_ING_ALL
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_ING_ALL" ("ID","IDPRODUITLIB","CATEGORIEINGREDIENT","IDTYPEPRODUITLIB","IDMAGASIN","IDMAGASINLIB","DATEDERNIERMOUVEMENT","QUANTITE","ENTREE","SORTIE","RESTE","UNITE","IDUNITELIB","PUVENTE","IDPOINT","IDTYPEMAGASIN","SEUILMIN","SEUILMAX","MONTANTENTREE","MONTANTSORTIE","PU","MONTANTRESTE") AS
SELECT
 p.ID AS ID,
 p.LIBELLE AS idproduitLib,
 p.CATEGORIEINGREDIENT,
 tp.DESCE AS idtypeproduitlib,
 ms.IDMAGASIN,
 mag.VAL AS idmagasinlib,
 TO_DATE('01-01-2001', 'DD-MM-YYYY') AS dateDernierMouvement,
 ms.quantite AS QUANTITE,
 CAST(NVL( ms.entree, 0) AS NUMBER(30, 2))  AS ENTREE,
 CAST(NVL( ms.sortie, 0) AS NUMBER(30, 2))  AS SORTIE,
 CAST(NVL( ms.quantite, 0) AS NUMBER(30, 2))  AS reste,
 p.UNITE,
 u.DESCE AS idunitelib,
 CAST(NVL(p.PV, 0) AS NUMBER(30, 2)) AS PUVENTE,
 mag.IDPOINT,
 mag.IDTYPEMAGASIN,
 p.SEUILMIN,
 p.SEUILMAX,
 ms.montantEntree,
 ms.montantSortie,
 p.pu,
 ms.montant as montantReste
FROM AS_INGREDIENTS p
LEFT JOIN MONTANT_STOCK ms ON ms.IDPRODUIT = p.ID
LEFT JOIN CATEGORIEINGREDIENT tp ON p.CATEGORIEINGREDIENT = tp.ID
LEFT JOIN MAGASINPOINT mag ON ms.IDMAGASIN = mag.ID
LEFT JOIN AS_UNITE u ON p.UNITE = u.ID
;
-- [1249/1309] V_ETATSTOCK_ING_ENG
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_ING_ENG" ("ID","DATY","INVQUANTITE","ENTREE","SORTIE","RESTE","QUANTITE","MONTANTRESTE","IDPRODUITLIB","CATEGORIEINGREDIENT","UNITE","TYPESTOCK","IDUNITELIB","IDTYPEPRODUITLIB","PU","IDFOURNISSEUR","IDFOURNISSEURLIB","IDPRODUIT","IDMAGASIN","IDMAGASINLIB","INVDATY") AS
SELECT
    '' as id,
    '' as DATY,
    cast(sum(invquantite) as number(30,3)) as invquantite,
    cast(sum(entree) as number(30,3)) as entree,
    cast(sum(sortie) as number(30,3)) as sortie,
    cast(sum(reste) as number(30,3)) as reste,
    cast(sum(quantite) as number(30,3)) as quantite,
    cast(sum(reste)* avg(pu) as number(30,2)) as montantReste,
    idproduitlib,
    CATEGORIEINGREDIENT,
    UNITE,
    TYPESTOCK,
    idunitelib,
    idtypeproduitlib,
    avg(PU) AS PU,
    '' as IDFOURNISSEUR,
    '' as IDFOURNISSEURLIB,
    IDPRODUIT,
    IDMAGASIN,
    idmagasinlib,
    min(invdaty) as invdaty
FROM (
    SELECT * FROM V_ETATSTOCK_ING
    UNION ALL
    SELECT
        TO_CHAR(mf.ID)                    AS id,
        TO_CHAR(mere.DATY, 'DD/MM/YYYY')  AS DATY,
        0 AS invquantite,
        mf.entree,
        mf.sortie AS sortie,
        mf.entree - mf.SORTIE AS reste,
        mf.entree - mf.SORTIE AS quantite,
        (mf.entree - mf.SORTIE) * mf.pu AS montantReste,
        ai.LIBELLE AS idproduitlib,
        ai.CATEGORIEINGREDIENT AS CATEGORIEINGREDIENT,
        ai.UNITE,
        ai.TYPESTOCK,
        u.val AS idunitelib,
        c.val AS idtypeproduitlib,
        mf.pu AS PU,
        '' AS IDFOURNISSEUR,
        '' AS IDFOURNISSEURLIB,
        mf.IDPRODUIT,
        mere.IDMAGASIN,
        m.val AS idmagasinlib,
        NULL AS invdaty
    FROM stock_engage_FILLE mf
        LEFT JOIN stock_engage mere ON mere.id = mf.IDMVTSTOCK
        LEFT JOIN AS_INGREDIENTS ai ON ai.id = mf.IDPRODUIT
        LEFT JOIN CATEGORIEINGREDIENT c ON ai.CATEGORIEINGREDIENT = c.id
        LEFT JOIN MAGASINPOINT m ON mere.IDMAGASIN = m.id
        LEFT JOIN AS_UNITE u ON ai.UNITE = u.id
) GROUP BY
    idproduitlib, CATEGORIEINGREDIENT, UNITE, TYPESTOCK,
    idunitelib, idtypeproduitlib, IDPRODUIT,
    IDMAGASIN, idmagasinlib
;
-- [1250/1309] V_ETATSTOCK_ING_ENG_SOMME
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_ING_ENG_SOMME" ("ID","IDPRODUITLIB","CATEGORIEINGREDIENT","IDTYPEPRODUITLIB","IDMAGASIN","IDMAGASINLIB","QUANTITE","ENTREE","SORTIE","RESTE","UNITE","IDUNITELIB","IDPOINT","IDTYPEMAGASIN","SEUILMIN","SEUILMAX","PU","LIBELLEVENTE") AS
SELECT
    p.ID,
    p.LIBELLE AS idproduitLib,
    p.CATEGORIEINGREDIENT,
    tp.DESCE AS idtypeproduitlib,
    ms.IDMAGASIN,
    mag.VAL AS idmagasinlib,
    sum(CAST(ms.quantite AS NUMBER(30,5) )) AS QUANTITE,
    sum(CAST(NVL( ms.entree, 0) AS NUMBER(30, 5)))  AS ENTREE,
    sum(CAST(NVL( ms.sortie, 0) AS NUMBER(30, 5)) ) AS SORTIE,
    sum(CAST(NVL( ms.quantite, 0) AS NUMBER(30, 5)))  AS reste,
    p.UNITE,
    u.DESCE AS idunitelib,
    mag.IDPOINT,
    mag.IDTYPEMAGASIN,
    p.SEUILMIN,
    p.SEUILMAX,
    CAST(p.pu AS NUMBER(30,5)) AS pu,
    p.LIBELLEVENTE
FROM AS_INGREDIENTS p
         LEFT JOIN MONTANT_STOCK_eng ms ON ms.IDPRODUIT = p.ID
         LEFT JOIN CATEGORIEINGREDIENT tp ON p.CATEGORIEINGREDIENT = tp.ID
         LEFT JOIN MAGASINPOINT mag ON ms.IDMAGASIN = mag.ID
         LEFT JOIN AS_UNITE u ON p.UNITE = u.ID
WHERE NVL(ms.ENTREE, 0) > 0 OR NVL(ms.SORTIE, 0) > 0
group by p.ID, p.LIBELLE, p.CATEGORIEINGREDIENT, tp.DESCE, ms.IDMAGASIN, mag.VAL, p.UNITE, u.DESCE, mag.IDPOINT, mag.IDTYPEMAGASIN, p.SEUILMIN, p.SEUILMAX, p.pu, p.LIBELLEVENTE
;
-- [1251/1309] V_ETATSTOCK_ING_GP
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_ING_GP" ("ID","IDPRODUITLIB","RESTE") AS
select id,idProduitLib,sum(reste) as reste
from V_ETATSTOCK_ING where CATEGORIEINGREDIENT = 'CAT008'
group by idProduitLib, id
;
-- [1252/1309] V_ETATSTOCK_ING_GP_PDF
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_ING_GP_PDF" ("ID","IDPRODUITLIB","RESTE","IDTYPEPRODUITLIB","PU","MONTANTRESTE") AS
select ving.id,ving.idProduitLib,sum(ving.reste) as reste,tp.val as IDTYPEPRODUITLIB ,sum(ving.pu),sum(ving.montantreste)
from V_ETATSTOCK_ING ving
LEFT JOIN as_ingredients aig ON aig.id=ving.id
LEFT JOIN type_produit tp ON aig.typeproduit=tp.id
where ving.CATEGORIEINGREDIENT = 'CAT008'
group by ving.idProduitLib, ving.id,tp.val
;
-- [1253/1309] V_ETATSTOCK_ING_ENG_PDF
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_ING_ENG_PDF" ("ID","IDPRODUITLIB","RESTE","SORTIE","ENTREE","IDTYPEPRODUITLIB","PU","MONTANTRESTE") AS
select
    v.id,
    v.idProduitLib,
    v.reste,
    NVL(s.SORTIE, 0) as SORTIE,
    v.RESTE - NVL(s.SORTIE, 0) as entree,
    v.IDTYPEPRODUITLIB,
    v.pu,
    v.montantreste
from V_ETATSTOCK_ING_GP_PDF v
         left join STOCK_ENGAGE_FILLE_GP s
                   on v.id = s.IDPRODUIT
;
-- [1254/1309] V_ETATSTOCK_ING_MAGASIN
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_ING_MAGASIN" ("ID","IDPRODUITLIB","CATEGORIEINGREDIENT","IDTYPEPRODUITLIB","IDMAGASIN","IDMAGASINLIB","DATEDERNIERMOUVEMENT","QUANTITE","ENTREE","SORTIE","RESTE","UNITE","IDUNITELIB","PUVENTE","IDPOINT","IDTYPEMAGASIN","SEUILMIN","SEUILMAX","IDPOINTLIB") AS
SELECT
    aim.ID AS ID,
    p.LIBELLE AS idproduitLib,
    p.CATEGORIEINGREDIENT,
    tp.DESCE AS idtypeproduitlib,
    aim.IDMAGASIN,
    mag.DESCE AS idmagasinlib,
    NVL(MAX(m.DATY),TO_DATE('01-01-2001', 'DD-MM-YYYY')) AS dateDernierMouvement,
    CAST(SUM(NVL(f.ENTREE, 0)) - SUM(NVL(f.SORTIE, 0)) AS NUMBER(30,2)) AS QUANTITE,
    CAST(SUM(NVL(f.ENTREE, 0)) AS NUMBER(30,2)) AS ENTREE,
    CAST(SUM(NVL(f.SORTIE, 0)) AS NUMBER(30,2)) AS SORTIE,
    CAST(SUM(NVL(f.ENTREE, 0)) - SUM(NVL(f.SORTIE, 0)) AS NUMBER(30,2)) AS reste,
    p.UNITE,
    u.DESCE AS idunitelib,
    CAST(NVL(p.PV, 0) AS NUMBER(30, 2)) AS PUVENTE,
    mag.IDPOINT,
    mag.IDTYPEMAGASIN,
    p.SEUILMIN,
    p.SEUILMAX,
    pt.VAL AS idPointLib
FROM AS_INGREDIENTS_MAGASIN aim
LEFT JOIN AS_INGREDIENTS p ON aim.ID = p.ID
LEFT JOIN CATEGORIEINGREDIENT tp ON p.CATEGORIEINGREDIENT = tp.ID
LEFT JOIN MAGASINPOINT mag ON aim.IDMAGASIN = mag.ID
LEFT JOIN AS_UNITE u ON p.UNITE = u.ID
LEFT JOIN MVTSTOCK m ON m.IDMAGASIN = aim.IDMAGASIN AND m.ETAT = 11
LEFT JOIN MVTSTOCKFILLE f ON f.IDMVTSTOCK = m.ID AND f.IDPRODUIT = aim.ID
LEFT JOIN POINT pt ON pt.ID = mag.IDPOINT
GROUP BY
    aim.ID,
    p.LIBELLE,
    p.CATEGORIEINGREDIENT,
    tp.DESCE,
    aim.IDMAGASIN,
    mag.DESCE,
    p.UNITE,
    u.DESCE,
    p.PV,
    mag.IDPOINT,
    mag.IDTYPEMAGASIN,
    p.SEUILMIN,
    p.SEUILMAX,
	pt.VAL
;
-- [1255/1309] V_ETATSTOCK_ING_POINT
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_ING_POINT" ("ID","IDPRODUITLIB","CATEGORIEINGREDIENT","IDTYPEPRODUITLIB","DATEDERNIERMOUVEMENT","QUANTITE","ENTREE","SORTIE","RESTE","UNITE","IDUNITELIB","PUVENTE","IDPOINT","SEUILMIN","SEUILMAX","IDPOINTLIB") AS
SELECT
    aim.ID AS ID,
    p.LIBELLE AS idproduitLib,
    p.CATEGORIEINGREDIENT,
    tp.DESCE AS idtypeproduitlib,
    NVL(MAX(m.DATY),TO_DATE('01-01-2001', 'DD-MM-YYYY')) AS dateDernierMouvement,
    CAST(SUM(NVL(f.ENTREE, 0)) - SUM(NVL(f.SORTIE, 0)) AS NUMBER(30,2)) AS QUANTITE,
    CAST(SUM(NVL(f.ENTREE, 0)) AS NUMBER(30,2)) AS ENTREE,
    CAST(SUM(NVL(f.SORTIE, 0)) AS NUMBER(30,2)) AS SORTIE,
    CAST(SUM(NVL(f.ENTREE, 0)) - SUM(NVL(f.SORTIE, 0)) AS NUMBER(30,2)) AS reste,
    p.UNITE,
    u.DESCE AS idunitelib,
    CAST(NVL(p.PV, 0) AS NUMBER(30, 2)) AS PUVENTE,
    mag.IDPOINT,
    p.SEUILMIN,
    p.SEUILMAX,
    pt.VAL AS idPointLib
FROM AS_INGREDIENTS_MAGASIN aim
LEFT JOIN AS_INGREDIENTS p ON aim.ID = p.ID
LEFT JOIN CATEGORIEINGREDIENT tp ON p.CATEGORIEINGREDIENT = tp.ID
LEFT JOIN MAGASINPOINT mag ON aim.IDMAGASIN = mag.ID
LEFT JOIN AS_UNITE u ON p.UNITE = u.ID
LEFT JOIN MVTSTOCK m ON m.IDMAGASIN = aim.IDMAGASIN AND m.ETAT = 11
LEFT JOIN MVTSTOCKFILLE f ON f.IDMVTSTOCK = m.ID AND f.IDPRODUIT = aim.ID
LEFT JOIN POINT pt ON pt.ID = mag.IDPOINT
GROUP BY
    aim.ID,
    p.LIBELLE,
    p.CATEGORIEINGREDIENT,
    tp.DESCE,
    p.UNITE,
    u.DESCE,
    p.PV,
    mag.IDPOINT,
    p.SEUILMIN,
    p.SEUILMAX,
  	pt.VAL
;
-- [1256/1309] V_ETATSTOCK_ING_TOUS
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_ING_TOUS" ("ID","DATY","INVQUANTITE","ENTREE","SORTIE","RESTE","QUANTITE","MONTANTRESTE","PU","IDPRODUITLIB","CATEGORIEINGREDIENT","UNITE","TYPESTOCK","IDUNITELIB","IDTYPEPRODUITLIB","IDFOURNISSEUR","IDFOURNISSEURLIB","IDPRODUIT","IDMAGASIN","IDMAGASINLIB","INVDATY","SEUIL","SEUILMIN","SEUILMAX") AS
WITH max_inventaire AS (
    -- Etape 1 : On extrait la date maximale valide et la quantite par COUPLE produit/magasin
    SELECT
        invff.idproduit,
        imeref.idmagasin,
        MAX(imeref.DATY) AS max_daty,
        MAX(invff.QUANTITE) KEEP (DENSE_RANK LAST ORDER BY imeref.DATY) AS qte_max_daty,
        MAX(invff.pu) KEEP (DENSE_RANK LAST ORDER BY imeref.DATY) AS pu_max_daty
    FROM INVENTAIREFILLE invff
    LEFT JOIN inventaireDateHeure imeref ON imeref.ID = invff.IDINVENTAIRE
    WHERE imeref.ETAT >= 11
    GROUP BY invff.idproduit, imeref.idmagasin
),
somme_precalc AS (
    -- Etape 3 : Calcul des sommes globales agregees par COUPLE produit/magasin
    SELECT
        mff.idproduit as idproduit,
        meref.idmagasin as idmagasin,
        NVL(SUM(CASE WHEN meref.DATY >NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.ENTREE ELSE 0 END), 0) AS entree,

        NVL(SUM(CASE WHEN meref.DATY > NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.SORTIE ELSE 0 END), 0) AS sortie,
        ai.LIBELLE AS idproduitlib,
        ai.CATEGORIEINGREDIENT as CATEGORIEINGREDIENT,
        ai.UNITE as unite,
        ai.TYPESTOCK as typestock,
        u.VAL AS idunitelib,
        c.VAL AS idtypeproduitlib,
        avg(mff.PU) as pu,
        null as IDFOURNISSEUR,
        null as IDFOURNISSEURLIB,
        m.VAL AS idmagasinlib,
        max(inv.max_daty) AS invdaty,
        nvl(max(inv.qte_max_daty),0)as invquantite,
        NVL(SUM(CASE WHEN meref.DATY >NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.ENTREE*mff.pu ELSE 0 END), 0) AS montantEntree,
        NVL(SUM(CASE WHEN meref.DATY > NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) THEN mff.SORTIE*mff.pu ELSE 0 END), 0) AS montantSortie,
        nvl(avg(inv.pu_max_daty*inv.qte_max_daty),0) as montantInv, nvl(max(ai.SEUIL),0) as seuil,nvl(max(ai.SEUILMAX),nvl(max(ai.SEUILMIN),0)+1000) as seuilmax,nvl(max(ai.SEUILMIN),0) as seuilMin
    FROM MVTSTOCKFILLE mff
    LEFT JOIN mvtStockDateHeure meref ON meref.ID = mff.IDMVTSTOCK
    LEFT JOIN max_inventaire inv ON inv.idproduit = mff.idproduit AND inv.idmagasin = meref.idmagasin
    LEFT JOIN AS_INGREDIENTS ai ON ai.id = mff.IDPRODUIT
    LEFT JOIN CATEGORIEINGREDIENT c ON ai.CATEGORIEINGREDIENT = c.id
    LEFT JOIN MAGASINPOINT m ON meref.IDMAGASIN = m.id
    LEFT JOIN AS_UNITE u ON ai.UNITE = u.id
    WHERE --meref.DATY > NVL(inv.max_daty, TO_DATE('01/01/2025','DD-MM-YYYY')) and
      meref.ETAT >= 11
      AND meref.IDTYPEMVSTOCK != 'TPMVST000023'
    GROUP BY mff.idproduit, meref.idmagasin,ai.LIBELLE,ai.CATEGORIEINGREDIENT,ai.UNITE,ai.TYPESTOCK,u.VAL,c.VAL,m.VAL
)
-- Selection finale
SELECT
    null as ID, null as DATY,  cast(invquantite as number(30,2)) as invquantite,cast(entree as number(30,2)) as entree, cast(sortie as number(30,2)) as sortie,CAST((invquantite)+(ENTREE)-(sortie) AS NUMBER(30,2)) as reste,
    CAST(invquantite+ENTREE-sortie AS NUMBER(30,2)) AS quantite,
    CAST((montantInv+montantEntree-montantSortie)AS NUMBER(30,2))AS montantreste,
    cast((montantInv+montantEntree-montantSortie)/(invquantite+ENTREE-sortie)  as number(30,2)) as pu,
    idproduitlib, CATEGORIEINGREDIENT, UNITE, TYPESTOCK, idunitelib, idtypeproduitlib,
     IDFOURNISSEUR, IDFOURNISSEURLIB, IDPRODUIT, IDMAGASIN, idmagasinlib,invdaty,cast(seuil as number(30,2))as seuil,cast(seuilMin as number(30,2))as seuilMin,cast(seuilMax as number(30,2))as seuilMax
FROM somme_precalc
;
-- [1257/1309] V_ETATSTOCK_INGINFSEUIL
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_INGINFSEUIL" ("ID","DATY","INVQUANTITE","ENTREE","SORTIE","RESTE","QUANTITE","MONTANTRESTE","PU","IDPRODUITLIB","CATEGORIEINGREDIENT","UNITE","TYPESTOCK","IDUNITELIB","IDTYPEPRODUITLIB","IDFOURNISSEUR","IDFOURNISSEURLIB","IDPRODUIT","IDMAGASIN","IDMAGASINLIB","INVDATY","SEUIL","SEUILMIN","SEUILMAX","QTEDEMANDE") AS
select eta."ID",eta."DATY",eta."INVQUANTITE",eta."ENTREE",eta."SORTIE",eta."RESTE",eta."QUANTITE",eta."MONTANTRESTE",eta."PU",eta."IDPRODUITLIB",eta."CATEGORIEINGREDIENT",eta."UNITE",eta."TYPESTOCK",eta."IDUNITELIB",eta."IDTYPEPRODUITLIB",eta."IDFOURNISSEUR",eta."IDFOURNISSEURLIB",eta."IDPRODUIT",eta."IDMAGASIN",eta."IDMAGASINLIB",eta."INVDATY",eta."SEUIL",eta."SEUILMIN",eta."SEUILMAX", cast(seuilMax-reste as number(30,2)) as qteDemande from V_ETATSTOCK_ING_TOUS eta where reste<seuilMin and seuilMin>0
;
-- [1258/1309] V_ETATSTOCK_ING_VENTE
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_ING_VENTE" ("ID","IDPRODUITLIB","IDMAGASIN","IDMAGASINLIB","PHYSIQUE","ENGAGE","AFACTURER","MONTANTENTREE","MONTANTSORTIE","MONTANTRESTE","UNITE","IDUNITELIB","PU","MOTSCLESSS") AS
SELECT AI.ID                                                                               AS ID,
       nvl(AI.LIBELLEVENTE,ai.libelle)                                                                     AS IDPRODUITLIB,
       M.ID                                                                                AS IDMAGASIN,
       M.VAL                                                                               AS IDMAGASINLIB,
       CAST(VE.RESTE AS NUMBER(30, 2))                                                     AS PHYSIQUE,
       NVL(CAST(STE.SORTIE AS NUMBER(30, 2)), 0)                                           AS ENGAGE,
       NVL(CAST(VE.RESTE AS NUMBER(30, 2)) - NVL(CAST(STE.SORTIE AS NUMBER(30, 2)), 0), 0) AS AFACTURER,
       CAST(NVL(VE.ENTREE * VE.PU, 0) AS NUMBER(30, 2))                                    AS MONTANTENTREE,
       CAST(NVL(VE.SORTIE * VE.PU, 0) AS NUMBER(30, 2))                                    AS MONTANTSORTIE,
       CAST(NVL((VE.ENTREE * VE.PU) - (VE.SORTIE * VE.PU), 0) AS NUMBER(30, 2))            AS MONTANTRESTE,
       AI.UNITE,
       U.VAL                                                                               AS IDUNITELIB,
       CASE
           WHEN VE.RESTE != 0
               THEN CAST(NVL(((VE.ENTREE * VE.PU) - (VE.SORTIE * VE.PU)) / NVL(VE.RESTE, 1), 0) AS NUMBER(30, 2))
           ELSE CAST(AI.PU AS NUMBER(30, 2))
           END                                                                             AS PU,
       (
           AI.ID || ' | ' || AI.LIBELLEVENTE || ' | ' || M.VAL
           )                                                                               AS MOTSCLESSS
FROM (SELECT MF.IDPRODUIT,
             SUM(MF.ENTREE)                  AS ENTREE,
             SUM(MF.SORTIE)                  AS SORTIE,
             ''                              AS IDVENTEDETAIL,
             ''                              AS IDTRANSFERTDETAIL,
             AVG(MF.PU)                      AS PU,
             ''                              AS MVTSRC,
             ''                              AS DATY,
             SUM(MF.ENTREE) - SUM(MF.SORTIE) AS RESTE,
             0                               AS QUANTITE,
             MS.IDMAGASIN                    AS IDMAGASIN
      FROM MVTSTOCKFILLE MF
               LEFT JOIN MVTSTOCK MS ON MS.ID = MF.IDMVTSTOCK
      WHERE MS.ETAT >= 11
      GROUP BY MF.IDPRODUIT, MS.IDMAGASIN) VE
         LEFT JOIN AS_INGREDIENTS AI ON AI.ID = VE.IDPRODUIT
         LEFT JOIN CATEGORIEINGREDIENT C ON AI.CATEGORIEINGREDIENT = C.ID
         JOIN MAGASINPOINT M ON VE.IDMAGASIN = M.ID
         LEFT JOIN AS_UNITE U ON AI.UNITE = U.ID
         LEFT JOIN STOCK_ENGAGE_FILLE_GP_MAG STE
                   ON STE.IDPRODUIT = VE.IDPRODUIT
                       AND STE.IDMAGASIN = VE.IDMAGASIN
where ai.ISVENTE = 1 and ai.ACTIF = 1
;
-- [1259/1309] V_ETATSTOCK_PROD_FINI
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_PROD_FINI" ("ID","IDPRODUITLIB","CATEGORIEINGREDIENT","IDTYPEPRODUITLIB","IDMAGASIN","IDMAGASINLIB","DATEDERNIERMOUVEMENT","QUANTITE","ENTREE","SORTIE","RESTE","UNITE","IDUNITELIB","PUVENTE","IDPOINT","IDTYPEMAGASIN","SEUILMIN","SEUILMAX","MONTANTENTREE","MONTANTSORTIE","PU","MONTANTRESTE") AS
SELECT
 p.ID AS ID,
 p.LIBELLE AS idproduitLib,
 p.CATEGORIEINGREDIENT,
 tp.DESCE AS idtypeproduitlib,
 ms.IDMAGASIN,
 mag.VAL AS idmagasinlib,
 TO_DATE('01-01-2001', 'DD-MM-YYYY') AS dateDernierMouvement,
 CAST(ms.quantite AS NUMBER(30,5) ) AS QUANTITE,
 CAST(NVL( ms.entree, 0) AS NUMBER(30,5))  AS ENTREE,
 CAST(NVL( ms.sortie, 0) AS NUMBER(30,5))  AS SORTIE,
 CAST(NVL( ms.quantite, 0) AS NUMBER(30,5))  AS reste,
 p.UNITE,
 u.DESCE AS idunitelib,
 CAST(NVL(p.PV, 0) AS NUMBER(30,5)) AS PUVENTE,
 mag.IDPOINT,
 mag.IDTYPEMAGASIN,
 CAST(COALESCE(p.SEUILMIN,0) AS NUMBER(30,5)) AS SEUILMIN,
 CAST(COALESCE(p.SEUILMAX,0) AS NUMBER(30,5)) AS SEUILMAX,
 CAST(ms.montantEntree AS NUMBER(30,5)) AS montantEntree,
 CAST(ms.montantSortie AS NUMBER(30,5)) AS montantSortie,
 CAST(p.pu AS NUMBER(30,5)) AS pu,
 CAST(ms.montant AS NUMBER(30,5)) as montantReste
FROM AS_INGREDIENTS p
LEFT JOIN MONTANT_STOCK ms ON ms.IDPRODUIT = p.ID
LEFT JOIN CATEGORIEINGREDIENT tp ON p.CATEGORIEINGREDIENT = tp.ID
LEFT JOIN MAGASINPOINT mag ON ms.IDMAGASIN = mag.ID
LEFT JOIN AS_UNITE u ON p.UNITE = u.ID
WHERE NVL(ms.ENTREE, 0)>0 or NVL(ms.SORTIE, 0)>0
AND p.CATEGORIEINGREDIENT = 'CAT008'
;
-- [1260/1309] V_ETATSTOCK_PROD_FINI2
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_PROD_FINI2" ("ID","IDPRODUITLIB","CATEGORIEINGREDIENT","IDTYPEPRODUITLIB","IDMAGASIN","IDMAGASINLIB","DATEDERNIERMOUVEMENT","QUANTITE","ENTREE","SORTIE","RESTE","UNITE","IDUNITELIB","PUVENTE","IDPOINT","IDTYPEMAGASIN","SEUILMIN","SEUILMAX","MONTANTENTREE","MONTANTSORTIE","PU","MONTANTRESTE","TYPEPRODUIT","TYPEPRODUITLIB","DATY") AS
SELECT
    p.ID AS ID,
    p.LIBELLE AS idproduitLib,
    p.CATEGORIEINGREDIENT,
    tp.DESCE AS idtypeproduitlib,
    ms.IDMAGASIN,
    mag.VAL AS idmagasinlib,
    TO_DATE('01-01-2001', 'DD-MM-YYYY') AS dateDernierMouvement,
    CAST(ms.quantite AS NUMBER(30,2) ) AS QUANTITE,
    CAST(NVL( ms.entree, 0) AS NUMBER(30, 2))  AS ENTREE,
    CAST(NVL( ms.sortie, 0) AS NUMBER(30, 2))  AS SORTIE,
    CAST(NVL( ms.quantite, 0) AS NUMBER(30, 2))  AS reste,
    p.UNITE,
    u.DESCE AS idunitelib,
    CAST(NVL(p.PV, 0) AS NUMBER(30, 2)) AS PUVENTE,
    mag.IDPOINT,
    mag.IDTYPEMAGASIN,
    p.SEUILMIN,
    p.SEUILMAX,
    CAST(ms.montantEntree AS NUMBER(30,2)) AS montantEntree,
    CAST(ms.montantSortie AS NUMBER(30,2)) AS montantSortie,
    CAST(p.pu AS NUMBER(30,2)) AS pu,
    CAST(ms.montant AS NUMBER(30,2)) as montantReste,
    p.TYPEPRODUIT,
    tpp.val as typeproduitlib,
    CURRENT_DATE AS DATY
FROM AS_INGREDIENTS p
         LEFT JOIN MONTANT_STOCK ms ON ms.IDPRODUIT = p.ID
         LEFT JOIN CATEGORIEINGREDIENT tp ON p.CATEGORIEINGREDIENT = tp.ID
         LEFT JOIN MAGASINPOINT mag ON ms.IDMAGASIN = mag.ID
         LEFT JOIN AS_UNITE u ON p.UNITE = u.ID
         LEFT JOIN TYPE_PRODUIT tpp ON tpp.id = p.TYPEPRODUIT
WHERE (NVL(ms.ENTREE, 0) > 0 OR NVL(ms.SORTIE, 0) > 0) -- Parentheses ajoutees pour la logique
  AND p.CATEGORIEINGREDIENT = 'CAT008'
  AND p.actif = 1
;
-- [1261/1309] VESTOCKPRODFINI_CAT_PCENTAGE
CREATE OR REPLACE FORCE VIEW "VESTOCKPRODFINI_CAT_PCENTAGE" ("ID","IDTYPEPRODUITLIB","QUANTITE","POURCENTAGE","DATY","MONTANTRESTE") AS
SELECT
    TYPEPRODUIT        AS id,
    typeproduitlib AS idTypeProduitLib ,
    CAST(SUM(quantite) AS NUMBER(30,2))  AS quantite,
    CAST(
            SUM(quantite) * 100.0
                / SUM(SUM(quantite)) OVER ()
        AS NUMBER(10,2))                     AS pourcentage,
    CURRENT_DATE AS DATY,
    CAST(SUM(montantReste) AS NUMBER(30,2))  AS montantReste
FROM V_ETATSTOCK_PROD_FINI2 where TYPEPRODUIT is not null
GROUP BY TYPEPRODUIT, typeproduitlib
;
-- [1262/1309] V_ETATSTOCK_PU
CREATE OR REPLACE FORCE VIEW "V_ETATSTOCK_PU" ("ID","RESTE","IDMAGASIN","PU","IDMAGASINLIB","MVTSRC") AS
SELECT
    idproduit AS id,
    SUM(QUANTITE) AS RESTE,
    IDMAGASIN,
    PU,
    IDMAGASINLIB,
    max(id) AS mvtsrc
FROM
    V_ETATSTOCK_ENTREE vee
GROUP BY
    IDPRODUIT,
    pu,
    IDMAGASIN ,
    IDMAGASINLIB
;
-- [1263/1309] INVENTAIREFILLECOMPLET
CREATE OR REPLACE FORCE VIEW "INVENTAIREFILLECOMPLET" ("ID","IDINVENTAIRE","IDPRODUIT","EXPLICATION","IDJAUGE","PU","QUANTITETHEORIQUE","QUANTITE","MVTSRC","IDMAGASIN","RESTE","MVTENTREE") AS
SELECT
	i."ID",i."IDINVENTAIRE",i."IDPRODUIT",i."EXPLICATION",i."IDJAUGE",i."PU",i."QUANTITETHEORIQUE",i."QUANTITE",i."MVTSRC",i."IDMAGASIN",
	vee.RESTE , vee.MVTSRC AS mvtentree
FROM
	INVENTAIREFILLEMERE i
LEFT JOIN V_ETATSTOCK_PU vee ON
	vee.ID = i.IDPRODUIT
	AND vee.pu = i.PU
	AND i.IDMAGASIN = vee.IDMAGASIN
;
-- [1264/1309] V_FORMATEUR_FF
CREATE OR REPLACE FORCE VIEW "V_FORMATEUR_FF" ("ID","LIBELLE","NIF","STAT","ADRESSE","CONTACT","CODEPOSTAL","COMPTE","IDTYPEFOURNISSEUR","COMPTEAUXILIAIRE","ESTACTIF") AS
SELECT "ID",
       "NOM" AS LIBELLE,
       "NIF",
       "STAT",
       "ADRESSE",
       "CONTACT",
       "CODEPOSTAL",
       "COMPTE",
       "IDTYPEFOURNISSEUR",
       "COMPTEAUXILIAIRE",
       "ESTACTIF"
FROM FOURNISSEUR
WHERE IDTYPEFOURNISSEUR = 'TYP000004'
;
-- [1265/1309] V_FORMATION_BILAN_PAR_STATUT
CREATE OR REPLACE FORCE VIEW "V_FORMATION_BILAN_PAR_STATUT" ("ANNEE","NBREALISE","NBNONREALISEE") AS
SELECT
    pf.ANNEE,

    SUM(CASE WHEN afl.ESTREALISEELIB = 'OUI' THEN 1 ELSE 0 END) AS nbRealise,

    SUM(CASE WHEN afl.ESTREALISEELIB = 'NON' THEN 1 ELSE 0 END) AS nbNonRealisee

FROM ACTION_FORMATION_LIB afl

         LEFT JOIN PLAN_FORMATION_ANNUEL pf
                   ON afl.IDPLANFORMATION = pf.ID

GROUP BY pf.ANNEE
;
-- [1266/1309] V_FORMATION_BILAN_PAR_TYPE
CREATE OR REPLACE FORCE VIEW "V_FORMATION_BILAN_PAR_TYPE" ("ANNEE","NBINTERNE","NBEXTERNE") AS
SELECT
    pf.ANNEE,

    SUM(CASE WHEN af.TYPEPRESTATAIRE = '1' THEN 1 ELSE 0 END) AS nbInterne,

    SUM(CASE WHEN af.TYPEPRESTATAIRE = '0' THEN 1 ELSE 0 END) AS nbExterne

FROM ACTION_FORMATION af

         LEFT JOIN PLAN_FORMATION_ANNUEL pf
                   ON af.IDPLANFORMATION = pf.ID

GROUP BY pf.ANNEE
;
-- [1267/1309] V_FORMATION_CROISE_TYPE_STATUT
CREATE OR REPLACE FORCE VIEW "V_FORMATION_CROISE_TYPE_STATUT" ("ANNEE","NBREALISEINTERNE","NBREALISEEXTERNE") AS
SELECT
    pf.ANNEE,

    SUM(CASE
            WHEN af.ESTREALISEE = 1
                AND af.TYPEPRESTATAIRE = '1'
                THEN 1 ELSE 0
        END) AS nbRealiseInterne,

    SUM(CASE
            WHEN af.ESTREALISEE = 1
                AND af.TYPEPRESTATAIRE = '0'
                THEN 1 ELSE 0
        END) AS nbRealiseExterne

FROM ACTION_FORMATION af

         LEFT JOIN PLAN_FORMATION_ANNUEL pf
                   ON af.IDPLANFORMATION = pf.ID

GROUP BY pf.ANNEE
;
-- [1268/1309] V_FOURNISSEUR_LIB
CREATE OR REPLACE FORCE VIEW "V_FOURNISSEUR_LIB" ("ID","NOM","NIF","STAT","ADRESSE","CONTACT","CODEPOSTAL","COMPTE","IDTYPEFOURNISSEUR","COMPTEAUXILIAIRE","ESTACTIF","ECHEANCE","DEVISE","MAIL","BANQUE","IDTYPEFOURNISSEURLIB") AS
SELECT
    f.ID,
    f.NOM,
    f.NIF,
    f.STAT,
    f.ADRESSE,
    f.CONTACT,
    f.CODEPOSTAL,
    f.COMPTE,
    f.IDTYPEFOURNISSEUR,
    f.COMPTEAUXILIAIRE,
    f.ESTACTIF,
    f.ECHEANCE,
    f.DEVISE,
    f.MAIL,
    f.BANQUE,
    tf.VAL AS IDTYPEFOURNISSEURLIB
FROM FOURNISSEUR f
         LEFT JOIN TYPEFOURNISSEUR tf ON f.IDTYPEFOURNISSEUR = tf.ID
;
-- [1269/1309] V_HIERARCHIE_PROFESSIONNELLE
CREATE OR REPLACE FORCE VIEW "V_HIERARCHIE_PROFESSIONNELLE" ("IDFAMILLEPRO","FAMILLEPRO","SOUSFAMILLE","CODEROME","METIER","EMPLOIE","FONCTION") AS
SELECT 
    fp.ID AS idFamillePro,
    fp.VAL AS FamillePro,
    sfp.VAL AS SousFamille,
    cr.CODE AS CodeRome,
    m.VAL AS Metier,
    e.VAL AS Emploie,
    pf.VAL AS Fonction
FROM FAMILLE_PROFESSIONNELLE fp
LEFT JOIN SOUS_FAMILLE_PRO sfp
    ON sfp.IDFAMILLE = fp.ID
LEFT JOIN CODE_ROME cr
    ON cr.IDSOUSFAMILLE = sfp.ID
LEFT JOIN METIER m
    ON m.IDCODEROME = cr.ID
LEFT JOIN EMPLOI e
    ON e.IDMETIER = m.ID
LEFT JOIN PAIE_FONCTION pf
    ON pf.IDEMPLOIE = e.ID
;
-- [1270/1309] V_HISTOINSERT
CREATE OR REPLACE FORCE VIEW "V_HISTOINSERT" ("IDHISTORIQUE","DATEHISTORIQUE","HEURE","OBJET","ACTION","IDUTILISATEUR","REFOBJET","REMARQUE","FICHE") AS
select
    hi."IDHISTORIQUE",hi."DATEHISTORIQUE",hi."HEURE",hi."OBJET",hi."ACTION",hi."IDUTILISATEUR",hi."REFOBJET",hi."REMARQUE"|| ' ' ||hi.REFOBJET||' '||hi.datehistorique as remarque,
    cf.FICHE
from HISTOINSERT hi
         left join V_CLASSEETFICHE cf on cf.CLASSE = hi.OBJET
;
-- [1271/1309] V_HS_FABRICATION_DETAIL
CREATE OR REPLACE FORCE VIEW "V_HS_FABRICATION_DETAIL" ("IDFABRICATION","IDPERSONNE","DATY","ANNEE","MOIS","HS_TOTAL","HS30","HS50") AS
SELECT
    hp.IDFABRICATION,
    hp.idPersonne,
    f.daty,
    p.annee,
    p.mois,
    SUM(hp.HS) AS hs_total,
    LEAST(SUM(hp.HS), 8) AS hs30,
    GREATEST(SUM(hp.HS) - 8, 0) AS hs50
FROM HEURESUPFABRICATION_CPL hp
         LEFT JOIN FABRICATION f ON f.id = hp.IDFABRICATION
         LEFT JOIN PERIODEPAIE p ON f.daty BETWEEN p.datedebut AND p.datefin
GROUP BY hp.IDFABRICATION, hp.idPersonne, f.daty, p.annee, p.mois
;
-- [1272/1309] HS_PAR_FABRICATION
CREATE OR REPLACE FORCE VIEW "HS_PAR_FABRICATION" ("IDFABRICATION","IDPERSONNE","DATY","HS30","HS50","MOIS","ANNEE") AS
SELECT
    d.IDFABRICATION,
    d.idPersonne,
    d.daty,
    d.hs30,
    d.hs50,
    d.mois,
    d.annee
FROM V_HS_FABRICATION_DETAIL d
ORDER BY d.idPersonne, d.daty
;
-- [1273/1309] V_INVENTAIREFILLECPL
CREATE OR REPLACE FORCE VIEW "V_INVENTAIREFILLECPL" ("ID","IDINVENTAIRE","IDPRODUIT","IDPRODUITLIB","EXPLICATION","QUANTITETHEORIQUE","QUANTITE","LIBELLEEXTACTE","PU","ECART","DATEINV","MONTANTTHEORIQUE","MONTANTREELLE","ECARTMONTANT","CATEGORIEINGREDIENT","MVTSRC","UNITELIB","IDMAGASIN","IDMAGASINLIB") AS
SELECT
    i.ID AS ID,
    i.IDINVENTAIRE AS IDINVENTAIRE,
    i.IDPRODUIT AS IDPRODUIT,
    p.LIBELLE AS IDPRODUITLIB,
    i.EXPLICATION AS EXPLICATION,

    CAST(
            NVL(i.QUANTITETHEORIQUE, 0)
        AS NUMBER(30, 6)
    ) AS QUANTITETHEORIQUE,

    CAST(
            NVL(i.QUANTITE, 0)
        AS NUMBER(30, 6)
    ) AS QUANTITE,

    p.LIBELLEEXTACTE AS LIBELLEEXTACTE,

    CAST(
            NVL(i.PU, 0)
        AS NUMBER(30, 6)
    ) AS PU,

    CAST(
            NVL(i.QUANTITE, 0)
                - NVL(i.QUANTITETHEORIQUE, 0)
        AS NUMBER(30, 6)
    ) AS ECART,

    iv.DATY AS DATEINV,

    CAST(
            NVL(i.PU, 0)
                * NVL(i.QUANTITETHEORIQUE, 0)
        AS NUMBER(30, 6)
    ) AS MONTANTTHEORIQUE,

    CAST(
            NVL(i.PU, 0)
                * NVL(i.QUANTITE, 0)
        AS NUMBER(30, 6)
    ) AS MONTANTREELLE,

    CAST(
            (
                NVL(i.PU, 0)
                    * NVL(i.QUANTITE, 0)
                )
                -
            (
                NVL(i.PU, 0)
                    * NVL(i.QUANTITETHEORIQUE, 0)
                )
        AS NUMBER(30, 6)
    ) AS ECARTMONTANT,

    p.CATEGORIEINGREDIENT AS CATEGORIEINGREDIENT,
    i.MVTSRC,
    au.val as uniteLib,
    iv.idMagasin,
    m.val as idMagasinLib
FROM INVENTAIREFILLE i

         LEFT JOIN INVENTAIRE iv
                   ON iv.ID = i.IDINVENTAIRE

         LEFT JOIN AS_INGREDIENTS p
                   ON p.ID = i.IDPRODUIT
         LEFT JOIN AS_UNITE AU on p.UNITE = au.id
         LEFT JOIN MAGASINPOINT m ON m.ID = iv.IDMAGASIN
WHERE iv.ETAT >= 11
;
-- [1274/1309] V_INVENTAIREFILLECAT
CREATE OR REPLACE FORCE VIEW "V_INVENTAIREFILLECAT" ("ID","IDINVENTAIRE","IDPRODUIT","IDPRODUITLIB","EXPLICATION","QUANTITETHEORIQUE","QUANTITE","LIBELLEEXTACTE","PU","ECART","DATEINV","MONTANTTHEORIQUE","MONTANTREELLE","ECARTMONTANT","CATEGORIEINGREDIENT","MVTSRC","CATEGORIEINGREDIENTLIB") AS
SELECT v."ID",v."IDINVENTAIRE",v."IDPRODUIT",v."IDPRODUITLIB",v."EXPLICATION",v."QUANTITETHEORIQUE",v."QUANTITE",v."LIBELLEEXTACTE",v."PU",v."ECART",v."DATEINV",v."MONTANTTHEORIQUE",v."MONTANTREELLE",v."ECARTMONTANT",v."CATEGORIEINGREDIENT",v."MVTSRC",
	c.val AS categorieingredientlib
	FROM V_INVENTAIREFILLECPL v
	LEFT JOIN CATEGORIEINGREDIENT c ON c.id=v.categorieingredient
;
-- [1275/1309] V_JOURS_2016_NOW
CREATE OR REPLACE FORCE VIEW "V_JOURS_2016_NOW" ("DATY","JOUR","SEMAINEMOIS","MOIS","ANNEE","NUMEROJOURSEMAINE","JOURLIB") AS
SELECT
    d AS DATY,
    EXTRACT(DAY FROM d) AS JOUR,
    CEIL((TO_CHAR(d, 'DD') + TO_CHAR(TRUNC(d, 'MM'), 'D') - 1) / 7) as semainemois,
    EXTRACT(MONTH FROM d) AS MOIS,
    EXTRACT(YEAR FROM d) AS ANNEE,
    TO_CHAR(d, 'D') as numerojoursemaine,
    TO_CHAR(d, 'Day', 'NLS_DATE_LANGUAGE=FRENCH') AS JOURLIB
FROM (
         SELECT TO_DATE('2025-05-01', 'YYYY-MM-DD') + LEVEL - 1 AS d
         FROM dual
             CONNECT BY LEVEL <= LAST_DAY(SYSDATE) - TO_DATE('2025-05-01', 'YYYY-MM-DD') + 1
     )
;
-- [1276/1309] CA_JOUR_DETAILS
CREATE OR REPLACE FORCE VIEW "CA_JOUR_DETAILS" ("DATY","JOUR","SEMAINEMOIS","MOIS","ANNEE","JOURLIB","MONTANT","IDJOURSEMAINE","NUMEROJOURSEMAINE") AS
select vj2n.DATY,
       vj2n.JOUR,
       vj2n.semainemois,
       vj2n.MOIS,
       vj2n.ANNEE,
       vj2n.JOURLIB,
       cast(nvl(cj.MONTANT, 0) as number(38, 2)) as montant,
       js.id as idjoursemaine,
       vj2n.numerojoursemaine
from V_JOURS_2016_now vj2n
         left join ca_journalier_union_gp cj on cj.DATY = vj2n.DATY
         left join joursemaine js on js.numsemaine = vj2n.semainemois and js.numjour = vj2n.numerojoursemaine
;
-- [1277/1309] CA_JOUR_DETAILS_CA
CREATE OR REPLACE FORCE VIEW "CA_JOUR_DETAILS_CA" ("DATY","JOUR","SEMAINEMOIS","MOIS","ANNEE","JOURLIB","MONTANT","IDJOURSEMAINE","NUMEROJOURSEMAINE") AS
select vj2n.DATY,
       vj2n.JOUR,
       vj2n.semainemois,
       vj2n.MOIS,
       vj2n.ANNEE,
       vj2n.JOURLIB,
       cast(nvl(cj.MONTANT, 0) as number(38, 2)) as montant,
       js.id as idjoursemaine,
       vj2n.numerojoursemaine
from V_JOURS_2016_now vj2n
         left join Ventecpljour cj on cj.DATY = vj2n.DATY
         left join joursemaine js on js.numsemaine = vj2n.semainemois and js.numjour = vj2n.numerojoursemaine
;
-- [1278/1309] CA_JOUR_DETAILS_CA_V2
CREATE OR REPLACE FORCE VIEW "CA_JOUR_DETAILS_CA_V2" ("DATY","JOUR","SEMAINEMOIS","MOIS","ANNEE","JOURLIB","MONTANT","IDJOURSEMAINE","NUMEROJOURSEMAINE","IDPROVINCE","PROVINCELIB") AS
select vj2n.DATY,
       vj2n.JOUR,
       vj2n.semainemois,
       vj2n.MOIS,
       vj2n.ANNEE,
       vj2n.JOURLIB,
       cast(nvl(cj.MONTANT, 0) as number(38, 2)) as montant,
       js.id as idjoursemaine,
       vj2n.numerojoursemaine,
       cj.idprovince,
       cj.provincelib
from V_JOURS_2016_now vj2n
         left join VENTECPLJOUR_V2 cj on cj.DATY = vj2n.DATY
         left join joursemaine js on js.numsemaine = vj2n.semainemois and js.numjour = vj2n.numerojoursemaine
;
-- [1279/1309] V_LIAISONPAIEMENT_FACTUREFOURN
CREATE OR REPLACE FORCE VIEW "V_LIAISONPAIEMENT_FACTUREFOURN" ("ID","ID1","ID2","MONTANT","ETAT","IDFACTUREFOURNISSEUR","DESIGNATION","DATY") AS
select li."ID",li."ID1",li."ID2",li."MONTANT",li."ETAT",ve.id as idfacturefournisseur, ve.DESIGNATION,ve.daty from LIAISONPAIEMENT li left join FACTUREFOURNISSEUR ve on ve.id=li.ID2
;
-- [1280/1309] V_LIAISONPAIEMENT_VENTE
CREATE OR REPLACE FORCE VIEW "V_LIAISONPAIEMENT_VENTE" ("ID","ID1","ID2","MONTANT","ETAT","IDVENTE","DESIGNATION","DATY") AS
select li."ID",li."ID1",li."ID2",li."MONTANT",li."ETAT",ve.id as idVente, ve.DESIGNATION,ve.daty
from LIAISONPAIEMENT li left join (select id,DESIGNATION,daty from vente union all select id,designation,daty from FACTUREFOURNISSEUR) ve on ve.id=li.ID2
;
-- [1281/1309] V_MATCHING_CV_FP
CREATE OR REPLACE FORCE VIEW "V_MATCHING_CV_FP" ("IDCV","IDFICHEPOSTE","IDFICHEPOSTECOMPETENCE","IDTYPECOMPETENCE","TYPECOMPETENCELIB","COMPETENCE","NIVEAUREQUIS","NIVEAUCANDIDAT","ECART","ESTVALIDE","RESULTAT") AS
SELECT
    cv.ID AS idCv,
    cv.IDFICHEPOSTE AS idFichePoste,
    fpc.ID AS idFichePosteCompetence,
    fpc.IDTYPECOMPETENCESFP AS idTypeCompetence,
    typ.VAL AS typeCompetenceLib,
    fpc.DESCRIPTION AS competence,
    fpc.NIVEAU AS niveauRequis,
    cvc.NIVEAU AS niveauCandidat,
    (cvc.NIVEAU - fpc.NIVEAU) AS ecart,
    CASE
        WHEN cvc.NIVEAU IS NULL THEN 0
        WHEN cvc.NIVEAU >= fpc.NIVEAU THEN 1
        ELSE 0
        END AS estValide,
    CASE
        WHEN cvc.NIVEAU IS NULL THEN 'NON RENSEIGNE'
        WHEN cvc.NIVEAU >= fpc.NIVEAU THEN 'OK'
        ELSE 'INSUFFISANT'
        END AS resultat
FROM CV cv
         JOIN FICHE_POSTE_COMPETENCES fpc ON fpc.IDFICHEPOSTE = cv.IDFICHEPOSTE
         LEFT JOIN TYPE_COMPETENCES_FP typ ON typ.ID = fpc.IDTYPECOMPETENCESFP
         LEFT JOIN CV_COMPETENCE cvc ON cvc.IDCV = cv.ID
    AND cvc.IDTYPECOMPETENCESFP = fpc.IDTYPECOMPETENCESFP
;
-- [1282/1309] V_CV_SCORE_GLOBAL
CREATE OR REPLACE FORCE VIEW "V_CV_SCORE_GLOBAL" ("IDCV","IDFICHEPOSTE","NBCOMPETENCES","NBCOMPETENCESVALIDES","NBCOMPETENCESNONVALIDES","SCORE") AS
SELECT
    v.IDCV                                          AS idCv,
    v.IDFICHEPOSTE                                  AS idFichePoste,
    COUNT(*)                                        AS nbCompetences,
    SUM(v.ESTVALIDE)                                AS nbCompetencesValides,
    COUNT(*) - SUM(v.ESTVALIDE)                     AS nbCompetencesNonValides,
    ROUND((SUM(v.ESTVALIDE) / COUNT(*)) * 100, 2)   AS score
FROM V_MATCHING_CV_FP v
GROUP BY
    v.IDCV,
    v.IDFICHEPOSTE
;
-- [1283/1309] V_MODULE_PRESTATAIRE_LIB
CREATE OR REPLACE FORCE VIEW "V_MODULE_PRESTATAIRE_LIB" ("ID","IDFORMATEUR","MODULE","IDFORMATEURLIB") AS
SELECT
    mp.ID,mp.IDFORMATEUR,mp.MODULE,
    f.LIBELLE AS idFormateurLib
FROM
    MODULE_PRESTATAIRE mp
        LEFT JOIN
    FORMATEUR f ON f.ID = mp.IDFORMATEUR
;
-- [1284/1309] V_MOIS_ANNEE_DISTINCTS
CREATE OR REPLACE FORCE VIEW "V_MOIS_ANNEE_DISTINCTS" ("MOIS","ANNEE","MOISLIB") AS
SELECT
    EXTRACT(MONTH FROM dt) AS MOIS,
    EXTRACT(YEAR FROM dt) AS ANNEE,
    TRIM(TO_CHAR(dt, 'Month', 'NLS_DATE_LANGUAGE=FRENCH')) AS moislib
FROM (
         SELECT ADD_MONTHS(DATE '2025-05-01', LEVEL - 1) AS dt
         FROM dual
             CONNECT BY ADD_MONTHS(DATE '2025-05-01', LEVEL - 1) <= TRUNC(SYSDATE, 'MM')
     )
ORDER BY ANNEE, MOIS
;
-- [1285/1309] V_MOYENNE_SALAIRE_PARFONCTION
CREATE OR REPLACE FORCE VIEW "V_MOYENNE_SALAIRE_PARFONCTION" ("ID","FONCTIONLIB","ANNEE","MOIS","MOYENNE_SALAIRE_BASE") AS
SELECT
    pip.idfonction as id,
    pf.desce as fonctionlib,
    pem.annee,
    pem.mois,
    ROUND(AVG(pe.GAIN), 2) AS moyenne_salaire_base
FROM PAIE_EDITION pe
         LEFT JOIN PAIE_EDITIONMOISANNEE pem ON pem.ID = pe.IDEDITION
         LEFT JOIN PAIE_INFO_PERSONNEL pip ON pip.ID = pe.IDPERSONNEL
         left join PAIE_FONCTION pf ON pf.id = pip.IDFONCTION
WHERE pe.IDELEMENTPAIE = 'PR000041'
GROUP BY pip.idfonction, pf.desce, pem.annee, pem.mois
;
-- [1286/1309] V_MOYENNE_SALAIRE_PAR_FONCTION
CREATE OR REPLACE FORCE VIEW "V_MOYENNE_SALAIRE_PAR_FONCTION" ("IDFONCTION","FONCTION_LIBELLE","MOYENNE_SALAIRE") AS
SELECT
    sb.idfonction,
    pf.desce AS fonction_libelle,
    AVG(sb.montant) AS moyenne_salaire
FROM PAIE_INFO_PERSONNEL_SB sb
         LEFT JOIN PAIE_FONCTION pf ON pf.id = sb.idfonction
GROUP BY sb.idfonction, pf.desce
;
-- [1287/1309] V_MVTSTOCKFILLEOFF
CREATE OR REPLACE FORCE VIEW "V_MVTSTOCKFILLEOFF" ("IDPRODUIT","IDOFFILLE","LIBELLEEXACTE","ENTREE","SORTIE","PU","MONTANT") AS
SELECT
	mvt.IDPRODUIT,
	fof.IDOFFILLE,
	mvt.LIBELLEEXACTE,
	CAST(sum(mvt.ENTREE ) AS NUMBER(20, 2)) AS ENTREE,
	CAST(sum(mvt.SORTIE ) AS NUMBER(20, 2)) AS SORTIE,
	ROUND(sum(mvt.PU), 2) AS PU,
	ROUND(SUM(MONTANT), 2) AS MONTANT
FROM
	MVTSTOCKFILLELIB mvt
JOIN FABRICATION_OF fof ON
	mvt.IDOBJET = fof.IDMERE
WHERE
	mvt.ETAT >= 11
GROUP BY
	mvt.IDPRODUIT,
	fof.IDOFFILLE,
	mvt.LIBELLEEXACTE
;
-- [1288/1309] V_MVTSTOCKFILLERENDEMENT
CREATE OR REPLACE FORCE VIEW "V_MVTSTOCKFILLERENDEMENT" ("IDPRODUIT","IDOFFILLE","LIBELLEEXACTE","ENTREE","PU","MONTANT") AS
SELECT
	mvt.IDPRODUIT,
	fof.IDOFFILLE,
	mvt.LIBELLEEXACTE,
	CAST(sum(mvt.ENTREE) AS NUMBER(20, 2)) AS ENTREE,
	ROUND(sum(mvt.PU), 2) AS PU,
	ROUND(SUM(MONTANT), 2) AS MONTANT
FROM
	MVTSTOCKFILLELIB mvt
JOIN FABRICATION_OF fof ON
	mvt.IDOBJET = fof.IDMERE
WHERE
	mvt.ENTREE > 0 and
	mvt.ETAT >= 11
GROUP BY
	mvt.IDPRODUIT,
	fof.IDOFFILLE,
	mvt.LIBELLEEXACTE
;
-- [1289/1309] V_NEXT_FACTURE_FOURNISSEUR
CREATE OR REPLACE FORCE VIEW "V_NEXT_FACTURE_FOURNISSEUR" ("PREFIXE","DATE_FACTURE","NEXTNUM") AS
SELECT
    typeachat || '-' || SUBSTR(IDFOURNISSEURLIB, 1, 1) AS prefixe,
    daty AS date_facture,
    LPAD(COUNT(*) + 1, 2, '0') AS nextnum
FROM facturefournisseurcpl
WHERE etat>=11
GROUP BY
    typeachat || '-' || SUBSTR(IDFOURNISSEURLIB, 1, 1),
    daty
;
-- [1290/1309] V_NUMEROAVOIR_EN_COURS
CREATE OR REPLACE FORCE VIEW "V_NUMEROAVOIR_EN_COURS" ("ANNEE_EN_COURS","DERNIER_NUM","PROCHAIN_NUM","PROCHAIN_NUM_FORMAT") AS
SELECT
    EXTRACT(YEAR FROM SYSDATE) AS ANNEE_EN_COURS,
    NVL(MAX(TO_NUMBER(SUBSTR(numavoir, 1, INSTR(numavoir, '/') - 1))), 0) AS DERNIER_NUM,
    NVL(MAX(TO_NUMBER(SUBSTR(numavoir, 1, INSTR(numavoir, '/') - 1))), 0) + 1 AS PROCHAIN_NUM,
    LPAD(NVL(MAX(TO_NUMBER(SUBSTR(numavoir, 1, INSTR(numavoir, '/') - 1))), 0) + 1, 4, '0')
        || '/' || TO_CHAR(EXTRACT(YEAR FROM SYSDATE)) AS PROCHAIN_NUM_FORMAT
FROM AVOIRFC
WHERE SUBSTR(numavoir, INSTR(numavoir, '/') + 1) = TO_CHAR(EXTRACT(YEAR FROM SYSDATE))
;
-- [1291/1309] V_NUMEROBC_EN_COURS
CREATE OR REPLACE FORCE VIEW "V_NUMEROBC_EN_COURS" ("ANNEE_EN_COURS","DERNIER_NUM","PROCHAIN_NUM","PROCHAIN_NUM_FORMAT") AS
SELECT
    EXTRACT(YEAR FROM SYSDATE) AS ANNEE_EN_COURS,
    NVL(MAX(TO_NUMBER(SUBSTR(NUMEROBC, 1, INSTR(NUMEROBC, '/') - 1))), 0) AS DERNIER_NUM,
    NVL(MAX(TO_NUMBER(SUBSTR(NUMEROBC, 1, INSTR(NUMEROBC, '/') - 1))), 0) + 1 AS PROCHAIN_NUM,
    LPAD(NVL(MAX(TO_NUMBER(SUBSTR(NUMEROBC, 1, INSTR(NUMEROBC, '/') - 1))), 0) + 1, 4, '0')
        || '/' || TO_CHAR(EXTRACT(YEAR FROM SYSDATE)) AS PROCHAIN_NUM_FORMAT
FROM BONDECOMMANDE_CLIENT
WHERE SUBSTR(NUMEROBC, INSTR(NUMEROBC, '/') + 1) = TO_CHAR(EXTRACT(YEAR FROM SYSDATE))
;
-- [1292/1309] V_NUMEROFACTURE_EN_COURS
CREATE OR REPLACE FORCE VIEW "V_NUMEROFACTURE_EN_COURS" ("ANNEE_EN_COURS","DERNIER_NUM","PROCHAIN_NUM","PROCHAIN_NUM_FORMAT") AS
SELECT
    EXTRACT(YEAR FROM SYSDATE) AS ANNEE_EN_COURS,
    NVL(MAX(TO_NUMBER(SUBSTR(NUMEROFACTURE, 1, INSTR(NUMEROFACTURE, '/') - 1))), 0) AS DERNIER_NUM,
    NVL(MAX(TO_NUMBER(SUBSTR(NUMEROFACTURE, 1, INSTR(NUMEROFACTURE, '/') - 1))), 0) + 1 AS PROCHAIN_NUM,
    LPAD(NVL(MAX(TO_NUMBER(SUBSTR(NUMEROFACTURE, 1, INSTR(NUMEROFACTURE, '/') - 1))), 0) + 1, 4, '0')
    || '/' || TO_CHAR(EXTRACT(YEAR FROM SYSDATE)) AS PROCHAIN_NUM_FORMAT
FROM VENTE
WHERE SUBSTR(NUMEROFACTURE, INSTR(NUMEROFACTURE, '/') + 1) = TO_CHAR(EXTRACT(YEAR FROM SYSDATE))
;
-- [1293/1309] V_NUMEROPROFORMA_EN_COURS
CREATE OR REPLACE FORCE VIEW "V_NUMEROPROFORMA_EN_COURS" ("ANNEE_EN_COURS","DERNIER_NUM","PROCHAIN_NUM","PROCHAIN_NUM_FORMAT") AS
SELECT
    EXTRACT(YEAR FROM SYSDATE) AS ANNEE_EN_COURS,
    NVL(MAX(TO_NUMBER(SUBSTR(NUMEROPROFORMA, 1, INSTR(NUMEROPROFORMA, '/') - 1))), 0) AS DERNIER_NUM,
    NVL(MAX(TO_NUMBER(SUBSTR(NUMEROPROFORMA, 1, INSTR(NUMEROPROFORMA, '/') - 1))), 0) + 1 AS PROCHAIN_NUM,
    LPAD(NVL(MAX(TO_NUMBER(SUBSTR(NUMEROPROFORMA, 1, INSTR(NUMEROPROFORMA, '/') - 1))), 0) + 1, 4, '0')
        || '/' || TO_CHAR(EXTRACT(YEAR FROM SYSDATE)) AS PROCHAIN_NUM_FORMAT
FROM PROFORMA
WHERE SUBSTR(NUMEROPROFORMA, INSTR(NUMEROPROFORMA, '/') + 1) = TO_CHAR(EXTRACT(YEAR FROM SYSDATE))
;
-- [1294/1309] V_PAIE_RECAP
CREATE OR REPLACE FORCE VIEW "V_PAIE_RECAP" ("ID","MOIS","ANNEE","IDEDITION","SALAIRE","HS_M","INDEM","ANCIEN","PRIME","AUTRES","TOTAL","CNAPS","OSTIE","IRSA_E","IRSA_S","AV_SPE","AUTRES2","A_PAYER") AS
SELECT
    p.idpersonnel AS id,
    p.mois,
    p.annee,
    p.idedition,
    SUM(NVL(CASE WHEN p.regroupement = 1  THEN p.gain END, 0)) AS SALAIRE,
    SUM(NVL(CASE WHEN p.regroupement = 2  THEN p.gain END, 0)) AS HS_M,
    SUM(NVL(CASE WHEN p.regroupement = 3  THEN p.gain END, 0)) AS INDEM,
    SUM(NVL(CASE WHEN p.regroupement = 4  THEN p.gain END, 0)) AS ANCIEN,
    SUM(NVL(CASE WHEN p.regroupement = 5  THEN p.gain END, 0)) AS PRIME,
    SUM(NVL(CASE WHEN p.regroupement = 6  THEN p.gain END, 0)) AS AUTRES,
    SUM(NVL(CASE WHEN p.regroupement = 7  THEN p.gain END, 0)) AS TOTAL,
    SUM(NVL(CASE WHEN p.regroupement = 8  THEN p.retenue END, 0)) AS CNAPS,
    SUM(NVL(CASE WHEN p.regroupement = 9  THEN p.retenue END, 0)) AS OSTIE,
    SUM(NVL(CASE WHEN p.regroupement = 10 THEN p.retenue END, 0)) AS IRSA_E,
    SUM(NVL(CASE WHEN p.regroupement = 11 THEN p.retenue END, 0)) AS IRSA_S,
    SUM(NVL(CASE WHEN p.regroupement = 12 THEN p.retenue END, 0)) AS AV_SPE,
    SUM(NVL(CASE WHEN p.regroupement = 13 THEN p.retenue END, 0)) AS AUTRES2,
    SUM(NVL(CASE WHEN p.regroupement = 14 THEN p.gain END, 0)) AS A_PAYER
FROM
    PAIE_EDITION p
        LEFT JOIN log_personnel l ON l.id = p.idpersonnel
GROUP BY
    p.idedition,p.idpersonnel, p.mois, p.annee
;
-- [1295/1309] SITUATION_SALAIRE_EDITION
CREATE OR REPLACE FORCE VIEW "SITUATION_SALAIRE_EDITION" ("MATRICULE","NOM","ID","MOIS","ANNEE","IDEDITION","SALAIRE","HS_M","INDEM","ANCIEN","PRIME","AUTRES","TOTAL","CNAPS","OSTIE","IRSA_E","IRSA_S","AV_SPE","AUTRES2","A_PAYER") AS
SELECT
    pinfo.matricule AS matricule,
    log.nom AS nom,
    v."ID",v."MOIS",v."ANNEE",v."IDEDITION",v."SALAIRE",v."HS_M",v."INDEM",v."ANCIEN",v."PRIME",v."AUTRES",v."TOTAL",v."CNAPS",v."OSTIE",v."IRSA_E",v."IRSA_S",v."AV_SPE",v."AUTRES2",v."A_PAYER"
FROM
    V_PAIE_RECAP v
        LEFT JOIN paie_info_personnel pinfo
                  ON v.id = pinfo.id
        LEFT JOIN log_personnel log
                  ON v.id = log.id
;
-- [1296/1309] SITUATION_SALAIRE_COMPLET
CREATE OR REPLACE FORCE VIEW "SITUATION_SALAIRE_COMPLET" ("MATRICULE","NOM","ID","MOIS","ANNEE","IDEDITION","SALAIRE","HS_M","INDEM","ANCIEN","PRIME","AUTRES","TOTAL","CNAPS","OSTIE","IRSA_E","IRSA_S","AV_SPE","AUTRES2","A_PAYER","HEURESUPP30NI","HEURESUPP30I","HEURESUPP50NI","HEURESUPP50I","MAJNUIT","MAJFERIE","MAJWEEKEND","ABBATEMENT","MOISLIB") AS
SELECT se.MATRICULE,se.NOM,(se.ID||'//'||sa.idedition) AS id,se.MOIS,se.ANNEE,se.IDEDITION,se.SALAIRE,se.HS_M,se.INDEM,se.ANCIEN,se.PRIME,se.AUTRES,se.TOTAL,se.CNAPS,se.OSTIE,se.IRSA_E,se.IRSA_S,se.AV_SPE,se.AUTRES2,se.A_PAYER,sa.heuresupp30ni,heuresupp30i,heuresupp50ni,heuresupp50i,majnuit,majferie,majweekend,abbatement,
	       CASE se.MOIS
	           WHEN 1 THEN 'Janvier'
	           WHEN 2 THEN 'Fevrier'
	           WHEN 3 THEN 'Mars'
	           WHEN 4 THEN 'Avril'
	           WHEN 5 THEN 'Mai'
	           WHEN 6 THEN 'Juin'
	           WHEN 7 THEN 'Juillet'
	           WHEN 8 THEN 'Aout'
	           WHEN 9 THEN 'Septembre'
	           WHEN 10 THEN 'Octobre'
	           WHEN 11 THEN 'Novembre'
	           WHEN 12 THEN 'Decembre'
	           END AS MOISLIB
	FROM SITUATION_SALAIRE_EDITION se
	         LEFT JOIN SITUATION_SALAIRE_AUTRE sa
	                   ON se.idedition =sa.idedition
	                       AND se.id = sa.idpersonnel
;
-- [1297/1309] V_POINTAGE_TOTAL_HEURE_SUP
CREATE OR REPLACE FORCE VIEW "V_POINTAGE_TOTAL_HEURE_SUP" ("IDPERSONNEL","MOIS","ANNEE","TOTAL_HEURE_SUP") AS
SELECT
    IDPERSONNEL,
    MOIS,
    ANNEE,
    (HEURESUPNORMAL + HEURESUPNUIT + HEURESUPFERIE + HEURESUPWEEKEND) AS TOTAL_HEURE_SUP
FROM
    POINTAGE
WHERE
    ETAT = 11
ORDER BY
    IDPERSONNEL, ANNEE, MOIS
;
-- [1298/1309] V_PROGRAMME_INTEGRATION_LIB
CREATE OR REPLACE FORCE VIEW "V_PROGRAMME_INTEGRATION_LIB" ("ID","IDPERSONNEL","DATY","REMARQUE","IDPERSONNELLIB","MATRICULE","IDFONCTION","IDFONCTIONLIB","IDSERVICE","IDSERVICELIB") AS
SELECT
    p.ID,p.IDPERSONNEL,p.DATY,p.REMARQUE,
    lp.nom || ' ' || lp.prenom AS idPersonnelLib,
    paie.matricule,
    paie.idfonction,
    f.val AS idFonctionLib,
    lp.service AS idService,
    s.libelle AS idServiceLib
FROM Programme_integration p
         JOIN LOG_PERSONNEL lp ON p.idPersonnel = lp.id
         JOIN PAIE_INFO_PERSONNEL paie ON lp.id = paie.id
         LEFT JOIN PAIE_FONCTION f ON paie.idfonction = f.id
         LEFT JOIN LOG_SERVICE s ON lp.service = s.id
;
-- [1299/1309] V_PROG_INTEGRATION_DETAIL_LIB
CREATE OR REPLACE FORCE VIEW "V_PROG_INTEGRATION_DETAIL_LIB" ("ID","IDPROGRAMEDETAIL","JOURDELASEMAINE","HEURE","DUREE","ACTIONTHEME","CONTENUE","IDINTERVENANT","IDINTERVENANTLIB","IDINTERVENANTFONCTION","IDINTERVENANTFONCTIONLIB","IDINTERVENANTSERVICE","IDINTERVENANTSERVICELIB","DUREE_EFFECTIVE") AS
SELECT
    pd.ID,
    pd.IDPROGRAMEDETAIL,

    CASE
        WHEN pd.JOURDELASEMAINE = 1 THEN 'Lundi'
        WHEN pd.JOURDELASEMAINE = 2 THEN 'Mardi'
        WHEN pd.JOURDELASEMAINE = 3 THEN 'Mercredi'
        WHEN pd.JOURDELASEMAINE = 4 THEN 'Jeudi'
        WHEN pd.JOURDELASEMAINE = 5 THEN 'Vendredi'
        WHEN pd.JOURDELASEMAINE = 6 THEN 'Samedi'
        WHEN pd.JOURDELASEMAINE = 7 THEN 'Dimanche'
        ELSE 'Inconnu'
        END AS JOURDELASEMAINE,

    pd.HEURE,
    pd.DUREE,
    pd.ACTIONTHEME,
    pd.CONTENUE,
    pd.IDINTERVENANT,

    lp.nom || ' ' || lp.prenom AS idIntervenantLib,

    paie.idfonction AS idIntervenantFonction,
    f.val AS idIntervenantFonctionLib,

    lp.service AS idIntervenantService,
    s.libelle AS idIntervenantServiceLib,

    (pd.Duree * 2) AS Duree_Effective

FROM Programme_integration_detail pd
         LEFT JOIN LOG_PERSONNEL lp
                   ON pd.idIntervenant = lp.id
         LEFT JOIN PAIE_INFO_PERSONNEL paie
                   ON lp.id = paie.id
         LEFT JOIN PAIE_FONCTION f
                   ON paie.idfonction = f.id
         LEFT JOIN LOG_SERVICE s
                   ON lp.service = s.id
;
-- [1300/1309] V_QTE_DISPO_LOT_SEXE_QUALITE
CREATE OR REPLACE FORCE VIEW "V_QTE_DISPO_LOT_SEXE_QUALITE" ("ID","IDSEXE","IDQUALITE","QTE") AS
SELECT
    m.IDLOT                     AS id,
    d.IDSEXE                    AS idsexe,
    d.IDQUALITE                 AS idqualite,
    SUM(d.QTE)                  AS qte
FROM TRIAGEBATIMENTPARQUETDETAIL d
JOIN TRIAGEBATIMENTPARQUET m
    ON d.IDMERE = m.ID
GROUP BY
    m.IDLOT,
    d.IDSEXE,
    d.IDQUALITE
;
-- [1301/1309] V_RAPPROCHEMENT_OF
CREATE OR REPLACE FORCE VIEW "V_RAPPROCHEMENT_OF" ("IDOBJET","SORTIE","PU","MONTANTSORTIE","QTETH","PUTH","MONTTH","ECARTQTE","ECARTMONTANT","ECARTPU") AS
SELECT
    IDOBJET,
    CAST(SUM(SORTIE) AS NUMBER(30,5)) AS sortie,
    CAST(SUM(PU) AS NUMBER(30,2)) AS pu,
    CAST(SUM(MONTANTSORTIE) AS NUMBER(30,5)) AS montantsortie,
    CAST(SUM(QTETH) AS NUMBER(30,5)) AS qteth,
    CAST(SUM(PUTH) AS NUMBER(30,2)) AS puth,
    CAST(SUM(MONTTH) AS NUMBER(30,2)) AS montth,
    CAST(SUM(SORTIE - QTETH) AS NUMBER(30,5)) AS ecartqte,
    CAST(SUM(MONTANTSORTIE - MONTTH) AS NUMBER(30,2)) AS ecartmontant,
    CAST(SUM(PU - PUTH) AS NUMBER(30,2)) AS ecartpu
FROM
    STOCKETDEPENSEOFFABTHE
GROUP BY
    IDOBJET
;
-- [1302/1309] V_RAPPROCHEMENT_OF_IA
CREATE OR REPLACE FORCE VIEW "V_RAPPROCHEMENT_OF_IA" ("IDOBJET","SORTIE","PU","MONTANTSORTIE","QTETH","PUTH","MONTTH","ECARTQTE","ECARTMONTANT","ECARTPU","IDPRODUIT","MOTSCLESSS") AS
SELECT SQ."IDOBJET",SQ."SORTIE",SQ."PU",SQ."MONTANTSORTIE",SQ."QTETH",SQ."PUTH",SQ."MONTTH",SQ."ECARTQTE",SQ."ECARTMONTANT",SQ."ECARTPU",SQ.IDPRODUIT,
       (NVL(TO_CHAR(IDOBJET),'') || ' | ' || NVL(TO_CHAR(SORTIE),'') || ' | ' || NVL(TO_CHAR(PU),'') || ' | ' || NVL(TO_CHAR(MONTANTSORTIE),'') || ' | ' || NVL(TO_CHAR(QTETH),'') || ' | ' || NVL(TO_CHAR(PUTH),'') || ' | ' || NVL(TO_CHAR(MONTTH),'') || ' | ' || NVL(TO_CHAR(ECARTQTE),'') || ' | ' || NVL(TO_CHAR(ECARTMONTANT),'') || ' | ' || NVL(TO_CHAR(ECARTPU),'')) AS MOTSCLESSS
FROM (
         SELECT
             IDOBJET,
             IDPRODUIT,
             CAST(SUM(SORTIE) AS NUMBER(30,5)) AS sortie,
             CAST(SUM(PU) AS NUMBER(30,2)) AS pu,
             CAST(SUM(MONTANTSORTIE) AS NUMBER(30,5)) AS montantsortie,
             CAST(SUM(QTETH) AS NUMBER(30,5)) AS qteth,
             CAST(SUM(PUTH) AS NUMBER(30,2)) AS puth,
             CAST(SUM(MONTTH) AS NUMBER(30,2)) AS montth,
             CAST(SUM(SORTIE - QTETH) AS NUMBER(30,5)) AS ecartqte,
             CAST(SUM(MONTANTSORTIE - MONTTH) AS NUMBER(30,2)) AS ecartmontant,
             CAST(SUM(PU - PUTH) AS NUMBER(30,2)) AS ecartpu
         FROM
             STOCKETDEPENSEOFFABTHE
         GROUP BY
             IDOBJET,
             IDPRODUIT
     ) SQ
;
-- [1303/1309] V_RAPPROCHEMENT_POURCENTAGE
CREATE OR REPLACE FORCE VIEW "V_RAPPROCHEMENT_POURCENTAGE" ("ID","VAL","DESCE","MONTANT","POURCENTAGE","DATY") AS
SELECT
    ID,
    VAL,
    DESCE,
    CAST(MONTANT AS NUMBER(15,2)) AS montant,
    CAST(
            CASE
                WHEN MONTANT > 0 THEN
                    MONTANT * 100.0 /
                    SUM(
                            CASE
                                WHEN MONTANT > 0 THEN MONTANT
                                ELSE 0
                                END
                    ) OVER ()
                ELSE 0
                END
        AS NUMBER(10,2)) AS pourcentage,
    CURRENT_DATE AS DATY
FROM RAPPROCHEMENTGLOBALE_PIE
;
-- [1304/1309] V_RECAP_GLOBAL_FORMATION
CREATE OR REPLACE FORCE VIEW "V_RECAP_GLOBAL_FORMATION" ("ANNEE","REF_FORMATION","TYPE_FORMATION","TYPE_FORMATIONLIB","CATEGORIE","CATEGORIELIB","INTITULE","SEMESTRE","SEMESTRELIB","INTERNE_EXTERNE","FORMATEUR","FORMATEURLIB","TYPE_COUT_ID","TYPE_COUT_LIB","MONTANT_COUT","NOMBRE_SESSION","NB_PARTICIPANT_OUVRIERS","NB_PARTICIPANT_CADRES","NB_PARTICIPANT_TOTAL","DUREE_PAR_STAGIAIRE","DUREE_TOTALE_HEURE") AS
SELECT
    pfa.ANNEE,

    af.REFERENCE AS REF_FORMATION,

    af.IDTYPEFORMATION AS TYPE_FORMATION,
    tf.VAL AS TYPE_FORMATIONLIB,

    af.IDCATEGORIEFORMATION AS CATEGORIE,
    cf.VAL AS CATEGORIELIB,

    af.INTITULE,

    af.IDSEMESTRE AS SEMESTRE,
    s.VAL AS SEMESTRELIB,

    cASE af.TYPEPRESTATAIRE
        WHEN '0' THEN 'INTERNE'
        WHEN '1' THEN 'EXTERNE'
        ELSE 'AUTRE'
    END AS INTERNE_EXTERNE,

    af.FORMATEUR,
    f.LIBELLE AS FORMATEURLIB,

    tcf.ID AS TYPE_COUT_ID,
    tcf.VAL AS TYPE_COUT_LIB,

    NVL(cout.MONTANT,0) AS MONTANT_COUT,

    NVL(sess.NB_SESSION,0) AS NOMBRE_SESSION,

    NVL(af.NBOUVRIERSPREVUE,0) AS NB_PARTICIPANT_OUVRIERS,
    NVL(af.NBCADREPREVUE,0) AS NB_PARTICIPANT_CADRES,

    NVL(af.NBOUVRIERSPREVUE,0) + NVL(af.NBCADREPREVUE,0) AS NB_PARTICIPANT_TOTAL,

    NVL(af.DUREESTAGIAIREHEURE,0) AS DUREE_PAR_STAGIAIRE,

    NVL(af.DUREESTAGIAIREHEURE,0) *
    (NVL(af.NBOUVRIERSPREVUE,0) + NVL(af.NBCADREPREVUE,0))
        AS DUREE_TOTALE_HEURE

FROM PLAN_FORMATION_ANNUEL pfa

         JOIN ACTION_FORMATION af
              ON af.IDPLANFORMATION = pfa.ID

-- ? jointures libelles
         LEFT JOIN TYPE_FORMATION tf
                   ON tf.ID = af.IDTYPEFORMATION

         LEFT JOIN CATEGORIE_FORMATION cf
                   ON cf.ID = af.IDCATEGORIEFORMATION

         LEFT JOIN SEMESTRE s
                   ON s.ID = af.IDSEMESTRE

         LEFT JOIN FORMATEUR f
                   ON f.ID = af.FORMATEUR

-- ? sessions agregees
         LEFT JOIN (
    SELECT
        IDACTIONFORMATION,
        COUNT(*) AS NB_SESSION
    FROM SESSION_FORMATION
    GROUP BY IDACTIONFORMATION
) sess
                   ON sess.IDACTIONFORMATION = af.ID

-- ? couts agreges
         LEFT JOIN (
    SELECT
        afd.IDACTIONFORMATION,
        afd.IDTYPECOUT,
        SUM(afd.COUT) AS MONTANT
    FROM ACTION_FORMATION_DETAIL afd
    GROUP BY afd.IDACTIONFORMATION, afd.IDTYPECOUT
) cout
                   ON cout.IDACTIONFORMATION = af.ID

         LEFT JOIN TYPE_COUT_FORMATION tcf
                   ON tcf.ID = cout.IDTYPECOUT
;
-- [1305/1309] V_STATISTIQUE_CA
CREATE OR REPLACE FORCE VIEW "V_STATISTIQUE_CA" ("ANNEE","DATY","CA_DU_JOUR","MEILLEUR_CA_SEMAINE","MEILLEUR_CA_MOIS","CA_ANNEE","CA_JANVIER","CA_FEVRIER","CA_MARS","CA_AVRIL","CA_MAI","CA_JUIN","CA_JUILLET","CA_AOUT","CA_SEPTEMBRE","CA_OCTOBRE","CA_NOVEMBRE","CA_DECEMBRE") AS
WITH CA_PAR_VENTE AS (
    SELECT
        v.ID AS IDVENTE,
        TRUNC(v.DATY) AS DATY,


        SUM(
                NVL(vd.QTE, 0) * NVL(vd.PU, 0)
        ) - NVL(v.FRAISLIVRAISON, 0) AS CA_VENTE

    FROM VENTE v

             JOIN VENTE_DETAILS vd
                  ON vd.IDVENTE = v.ID

    WHERE v.DATY IS NOT NULL
      AND v.ETAT >= 11

    GROUP BY
        v.ID,
        TRUNC(v.DATY),
        v.FRAISLIVRAISON
),

     CA_PAR_JOUR AS (
         SELECT
             DATY,
             SUM(CA_VENTE) AS CA
         FROM CA_PAR_VENTE
         GROUP BY DATY
     )

SELECT
    EXTRACT(YEAR FROM SYSDATE) AS ANNEE,
    TRUNC(SYSDATE) AS DATY,

    /* CA du jour */
    NVL(
            MAX(
                    CASE
                        WHEN DATY = TRUNC(SYSDATE)
                            THEN CA
                        END
            ),
            0
    ) AS CA_DU_JOUR,

    /* Meilleur CA journalier de la semaine */
    NVL(
            MAX(
                    CASE
                        WHEN DATY >= TRUNC(SYSDATE, 'IW')
                            AND DATY < TRUNC(SYSDATE, 'IW') + 7
                            THEN CA
                        END
            ),
            0
    ) AS MEILLEUR_CA_SEMAINE,

    /* Meilleur CA journalier du mois */
    NVL(
            MAX(
                    CASE
                        WHEN DATY >= TRUNC(SYSDATE, 'MM')
                            AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'MM'), 1)
                            THEN CA
                        END
            ),
            0
    ) AS MEILLEUR_CA_MOIS,

    /* CA total de l'annee */
    NVL(
            SUM(
                    CASE
                        WHEN DATY >= TRUNC(SYSDATE, 'YYYY')
                            AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 12)
                            THEN CA
                        ELSE 0
                        END
            ),
            0
    ) AS CA_ANNEE,

    /* CA par mois de l'annee courante */
    NVL(SUM(
                CASE
                    WHEN DATY >= TRUNC(SYSDATE, 'YYYY')
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 1)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_JANVIER,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 1)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 2)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_FEVRIER,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 2)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 3)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_MARS,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 3)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 4)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_AVRIL,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 4)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 5)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_MAI,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 5)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 6)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_JUIN,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 6)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 7)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_JUILLET,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 7)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 8)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_AOUT,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 8)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 9)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_SEPTEMBRE,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 9)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 10)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_OCTOBRE,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 10)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 11)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_NOVEMBRE,

    NVL(SUM(
                CASE
                    WHEN DATY >= ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 11)
                        AND DATY < ADD_MONTHS(TRUNC(SYSDATE, 'YYYY'), 12)
                        THEN CA ELSE 0
                    END
        ), 0) AS CA_DECEMBRE

FROM CA_PAR_JOUR
;
-- [1306/1309] V_TRIAGEOEUFDETAIL_AGG
CREATE OR REPLACE FORCE VIEW "V_TRIAGEOEUFDETAIL_AGG" ("IDMERE","QTE_TOTAL") AS
SELECT
    IDMERE,
    SUM(NVL(QTE, 0)) AS QTE_TOTAL
FROM TRIAGEOEUFDETAIL
GROUP BY IDMERE
;
-- [1307/1309] TRIAGEOEUF_LIB
CREATE OR REPLACE FORCE VIEW "TRIAGEOEUF_LIB" ("ID","DATY","HEUREDEPART","IDOPERATEUR","IDNUMEROCOLLECTE","IDBATIMENT","IDPARQUET","OEUFTOTAL","POIDSMOYENOEUFS","IDOPERATEURLIB","IDNUMEROCOLLECTELIB","IDBATIMENTLIB","IDPARQUETLIB","ETAT","ETATLIB","ECART") AS
SELECT
    t.ID,
    t.DATY,
    t.HEUREDEPART,
    t.IDOPERATEUR,
    t.IDNUMEROCOLLECTE,
    t.IDBATIMENT,
    t.IDPARQUET,
    t.OEUFTOTAL,
    t.POIDSMOYENOEUFS,
 
    lp.NOM || ' ' || lp.PRENOM AS IDOPERATEURLIB,
 
    nc.VAL AS IDNUMEROCOLLECTELIB,
 
    b.NOMBATIMENT AS IDBATIMENTLIB,
 
    p.VAL AS IDPARQUETLIB,
 
    t.ETAT,
 
    CASE
        WHEN t.ETAT = 1 THEN 'CREE'
        WHEN t.ETAT = 0 THEN 'ANNULEE'
        WHEN t.ETAT = 11 THEN 'VISEE'
    END AS ETATLIB,
    t.OEUFTOTAL - COALESCE(td.QTE_TOTAL, 0) AS ECART

FROM TRIAGEOEUF t
 
LEFT JOIN LOG_PERSONNEL lp
    ON lp.ID = t.IDOPERATEUR
 
LEFT JOIN NUMEROCOLLECTE nc
    ON nc.ID = t.IDNUMEROCOLLECTE
 
LEFT JOIN BATIMENT b
    ON b.ID = t.IDBATIMENT
 
LEFT JOIN PARQUET p
    ON p.ID = t.IDPARQUET

LEFT JOIN V_TRIAGEOEUFDETAIL_AGG td ON td.IDMERE = t.ID
;
