CREATE OR REPLACE PROCEDURE allocate_extent_for_owner(p_owner VARCHAR2) AS
BEGIN
    FOR tbl IN (SELECT TABLE_NAME FROM dba_tables WHERE OWNER = UPPER(p_owner) ORDER BY TABLE_NAME) LOOP
        EXECUTE IMMEDIATE 'ALTER TABLE ' || p_owner || '.' || tbl.TABLE_NAME || ' ALLOCATE EXTENT';
    END LOOP;
END;
/
CREATE OR REPLACE PROCEDURE DELETECALCULHS(id VARCHAR) AS
BEGIN
DELETE FROM HSMOIS WHERE ID = id;
DELETE FROM HS_FABRICATION_DETAIL_PAIE WHERE ID_HSMOIS = id;
END;
/
CREATE OR REPLACE PROCEDURE DELETEEDITIONWITHDIR2(ms NUMBER,ane NUMBER,dir VARCHAR,idobj varchar) AS
BEGIN
    DELETE FROM PAIE_EDITION WHERE MOIS = ms AND ANNEE = ane and IDPERSONNEL in(select p.id from LOG_PERSONNEL p where p.DIRECTION=dir);
    DELETE FROM PAIE_EDITIONMOISANNEE WHERE MOIS = ms AND ANNEE = ane and IDDIRECTION=dir;
END;
/
CREATE OR REPLACE PROCEDURE DELETEEDITIONWITHPERIODE(periode VARCHAR) AS
BEGIN
DELETE FROM PAIE_EDITION WHERE idperiodepaie = periode;
DELETE FROM PAIE_EDITIONMOISANNEE where idperiodepaie = periode;
END;
/
CREATE OR REPLACE PROCEDURE generer_dates IS
    v_date DATE := TO_DATE('01/01/2025', 'DD/MM/YYYY');
    v_fin  DATE := TO_DATE('31/12/2026', 'DD/MM/YYYY');
BEGIN
    WHILE v_date <= v_fin LOOP
        INSERT INTO datyexiste (daty)
        VALUES (v_date);
        v_date := v_date + 1;
    END LOOP;
    COMMIT;
END;
/
CREATE OR REPLACE PROCEDURE REPORTSOLDE_RAN(EXO IN VARCHAR, IDUSER IN VARCHAR) AS
    idEcr VARCHAR2(50 BYTE);
    er varchar2(500);
    exo_num NUMBER;
BEGIN
    exo_num := TO_NUMBER(EXO);
    FOR sousecr IN (SELECT * FROM COMPTA_REPORT WHERE ANNEE = ''||EXO||'') LOOP
            idEcr := 'MVT'||getseqcomptaecriture();
            insert into compta_ecriture (ID,DATY,DATECOMPTABLE,EXERCICE,DESIGNATION,REMARQUE,ETAT,HORSEXERCICE,JOURNAL,OD,ORIGINE,CREDIT,DEBIT,IDUSER,PERIODE,TRIMESTRE,ANNEE,
                                         IDOBJET) values (idEcr, '01/01/'||(EXO+1), '01/01/'||(EXO+1), EXO + 1, 'R A N '||EXO, 'R A N '||EXO, 1,0, 'COMP000015', '-', 'MAN', sousecr.DEBIT, sousecr.CREDIT, IDUSER, (EXO + 1)||'01', 1,  (EXO + 1), '' );
            IF (sousecr.debit - sousecr.credit) > 0 THEN
                insert into compta_sous_ecriture (ID,COMPTE,DEBIT,CREDIT,REMARQUE,LIBELLEPIECE,IDMERE,REFERENCE_ENGAGEMENT,COMPTE_AUX,LETTRAGE,JOURNAL,EXERCICE,DATY,FOLIO,ANALYTIQUE,SOURCE,ETAT)
                values(seq_compta_sous_ecriture.NEXTVAL, sousecr.compte, sousecr.debit - sousecr.credit, 0, 'R A N '||EXO, 'R A N '||EXO, idEcr, '-', '-', '-', 'COMP000015', (EXO + 1),  '01/01/'||(EXO + 1),NULL,NULL,NULL,11);
                insert into compta_sous_ecriture (ID,COMPTE,DEBIT,CREDIT,REMARQUE,LIBELLEPIECE,IDMERE,REFERENCE_ENGAGEMENT,COMPTE_AUX,LETTRAGE,JOURNAL,EXERCICE,DATY,FOLIO,ANALYTIQUE,SOURCE,ETAT)
                values(seq_compta_sous_ecriture.NEXTVAL, '8900100', 0, sousecr.debit - sousecr.credit, 'R A N '||EXO, 'R A N '||EXO, idEcr, '-', '-', '-', 'COMP000015', (EXO + 1), '01/01/'||(EXO + 1),NULL,NULL,NULL,11);
            END IF;
            IF (sousecr.credit - sousecr.debit)>0 THEN
                insert into compta_sous_ecriture (ID,COMPTE,DEBIT,CREDIT,REMARQUE,LIBELLEPIECE,IDMERE,REFERENCE_ENGAGEMENT,COMPTE_AUX,LETTRAGE,JOURNAL,EXERCICE,DATY,FOLIO,ANALYTIQUE,SOURCE,ETAT)
                values(seq_compta_sous_ecriture.NEXTVAL, sousecr.compte, 0, sousecr.credit - sousecr.debit, 'R A N '||EXO, 'R A N '||EXO, idEcr, '-', '-', '-', 'COMP000015', (EXO + 1), '01/01/'||(EXO + 1),NULL,NULL,NULL,11);
                insert into compta_sous_ecriture (ID,COMPTE,DEBIT,CREDIT,REMARQUE,LIBELLEPIECE,IDMERE,REFERENCE_ENGAGEMENT,COMPTE_AUX,LETTRAGE,JOURNAL,EXERCICE,DATY,FOLIO,ANALYTIQUE,SOURCE,ETAT)
                values(seq_compta_sous_ecriture.NEXTVAL, '8900100', sousecr.credit - sousecr.debit, 0, 'R A N '||EXO, 'R A N '||EXO, idEcr, '-', '-', '-', 'COMP000015', (EXO + 1), '01/01/'||(EXO + 1),NULL,NULL,NULL,11);
            END IF;
        END LOOP;

exception
    WHEN OTHERS THEN
        er := SQLERRM;
        commit;
END;
/

