CREATE OR REPLACE TRIGGER "MOUVEMENTCAISSE_UPD_TRG" 
BEFORE UPDATE ON MOUVEMENTCAISSE
FOR EACH ROW
BEGIN
    :NEW.UPDATED_AT := SYSTIMESTAMP; -- ou SYSDATE selon ton besoin
END;
/
CREATE OR REPLACE TRIGGER "TRG_PLANNING_PERIODIQUE" 
	    BEFORE INSERT OR UPDATE OF FREQUENCE ON PLANNING
	    FOR EACH ROW
	BEGIN
	    IF :NEW.FREQUENCE IS NOT NULL AND :NEW.FREQUENCE <> 0 THEN
	        :NEW.ESTPERIODIQUE := 1;
	ELSE
	        :NEW.ESTPERIODIQUE := 0;
	END IF;
	END;
/
CREATE OR REPLACE TRIGGER "VENTE_UPD_TRG" 
BEFORE UPDATE ON vente
FOR EACH ROW
BEGIN
    :NEW.UPDATED_AT := SYSTIMESTAMP; -- ou SYSDATE selon ton besoin
END;
/

